        sign = '-'
        delta = -delta
    else:
        sign = '+'
    hours, rest = divmod(delta, timedelta(hours=1))
    minutes, rest = divmod(rest, timedelta(minutes=1))
    seconds = rest.seconds
    microseconds = rest.microseconds
    if microseconds:
        return f'UTC{sign}{hours:02d}:{minutes:02d}:{seconds:02d}.{microseconds:06d}'
    if seconds:
        return f'UTC{sign}{hours:02d}:{minutes:02d}:{seconds:02d}'
    return f'UTC{sign}{hours:02d}:{minutes:02d}'

def local(u):
    y, m, d, hh, mm, ss = _time.localtime(u)[:6]
    return (datetime(y, m, d, hh, mm, ss) - epoch) // timedelta(0, 1)

def getcontext():
    """Returns this thread's context.

    If this thread does not yet have a context, returns
    a new context and sets this thread's context.
    New contexts are copies of DefaultContext."""
    try:
        return _current_context_var.get()
    except LookupError:
        context = Context()
        _current_context_var.set(context)
        return context

def setcontext(context):
    """Set this thread's context to context."""
    if context in (DefaultContext, BasicContext, ExtendedContext):
        context = context.copy()
        context.clear_flags()
    _current_context_var.set(context)

def _decimal_lshift_exact(n, e):
    """Given integers n and e, return n * 10**e if it's an integer, else None.

    The computation is designed to avoid computing large powers of 10
    unnecessarily.

    >>> _decimal_lshift_exact(3, 4)
    30000
    >>> _decimal_lshift_exact(300, -999999999)  # returns None"""
    if n == 0:
        return 0
    elif e >= 0:
        return n * 10 ** e
    else:
        str_n = str(abs(n))
        val_n = len(str_n) - len(str_n.rstrip('0'))
        return None if val_n < -e else n // 10 ** (-e)

def _rshift_nearest(x, shift):
    """Given an integer x and a nonnegative integer shift, return closest
    integer to x / 2**shift; use round-to-even in case of a tie."""
    b, q = (1 << shift, x >> shift)
    return q + (2 * (x & b - 1) + (q & 1) > b)

def _div_nearest(a, b):
    """Closest integer to a/b, a and b positive integers; rounds to even
    in the case of a tie."""
    q, r = divmod(a, b)
    return q + (2 * r + (q & 1) > b)

def _dlog(c, e, p):
    """Given integers c, e and p with c > 0, compute an integer
    approximation to 10**p * log(c*10**e), with an absolute error of
    at most 1.  Assumes that c*10**e is not exactly 1."""
    p += 2
    l = len(str(c))
    f = e + l - (e + l >= 1)
    if p > 0:
        k = e + p - f
        if k >= 0:
            c *= 10 ** k
        else:
            c = _div_nearest(c, 10 ** (-k))
        log_d = _ilog(c, 10 ** p)
    else:
        log_d = 0
    if f:
        extra = len(str(abs(f))) - 1
        if p + extra >= 0:
            f_log_ten = _div_nearest(f * _log10_digits(p + extra), 10 ** extra)
        else:
            f_log_ten = 0
    else:
        f_log_ten = 0
    return _div_nearest(f_log_ten + log_d, 100)

def _log10_lb(c, correction={'1': 100, '2': 70, '3': 53, '4': 40, '5': 31, '6': 23, '7': 16, '8': 10, '9': 5}):
    """Compute a lower bound for 100*log10(c) for a positive integer c."""
    if c <= 0:
        raise ValueError('The argument to _log10_lb should be nonnegative.')
    str_c = str(c)
    return 100 * len(str_c) - correction[str_c[0]]

def _convert_other(other, raiseit=False, allow_float=False):
    """Convert other to Decimal.

    Verifies that it's ok to use in an implicit construction.
    If allow_float is true, allow conversion from float;  this
    is used in the comparison methods (__eq__ and friends)."""
    if isinstance(other, Decimal):
        return other
    if isinstance(other, int):
        return Decimal(other)
    if allow_float and isinstance(other, float):
        return Decimal.from_float(other)
    if raiseit:
        raise TypeError('Unable to convert %s to Decimal' % other)
    return NotImplemented

def _convert_for_comparison(self, other, equality_op=False):
    """Given a Decimal instance self and a Python object other, return
    a pair (s, o) of Decimal instances such that "s op o" is
    equivalent to "self op other" for any of the 6 comparison
    operators "op"."""
    if isinstance(other, Decimal):
        return (self, other)
    if isinstance(other, _numbers.Rational):
        if not self._is_special:
            self = _dec_from_triple(self._sign, str(int(self._int) * other.denominator), self._exp)
        return (self, Decimal(other.numerator))
    if equality_op and isinstance(other, _numbers.Complex) and (other.imag == 0):
        other = other.real
    if isinstance(other, float):
        context = getcontext()
        if equality_op:
            context.flags[FloatOperation] = 1
        else:
            context._raise_error(FloatOperation, 'strict semantics for mixing floats and Decimals are enabled')
        return (self, Decimal.from_float(other))
    return (NotImplemented, NotImplemented)

def _group_lengths(grouping):
    """Convert a localeconv-style grouping into a (possibly infinite)
    iterable of integers representing group lengths."""
    from itertools import chain, repeat
    if not grouping:
        return []
    elif grouping[-1] == 0 and len(grouping) >= 2:
        return chain(grouping[:-1], repeat(grouping[-2]))
    elif grouping[-1] == _locale.CHAR_MAX:
        return grouping[:-1]
    else:
        raise ValueError('unrecognised format for grouping')

def _format_sign(is_negative, spec):
    """Determine sign character."""
    if is_negative:
        return '-'
    elif spec['sign'] in ' +':
        return spec['sign']
    else:
        return ''

def handle(self, context, *args):
    if args:
        ans = _dec_from_triple(args[0]._sign, args[0]._int, 'n', True)
        return ans._fix_nan(context)
    return _NaN

def handle(self, context, sign, *args):
    if context.rounding in (ROUND_HALF_UP, ROUND_HALF_EVEN, ROUND_HALF_DOWN, ROUND_UP):
        return _SignedInfinity[sign]
    if sign == 0:
        if context.rounding == ROUND_CEILING:
            return _SignedInfinity[sign]
        return _dec_from_triple(sign, '9' * context.prec, context.Emax - context.prec + 1)
    if sign == 1:
        if context.rounding == ROUND_FLOOR:
            return _SignedInfinity[sign]
        return _dec_from_triple(sign, '9' * context.prec, context.Emax - context.prec + 1)

def _isnan(self):
    """Returns whether the number is not actually one.

    0 if a number
    1 if NaN
    2 if sNaN"""
    if self._is_special:
        exp = self._exp
        if exp == 'n':
            return 1
        elif exp == 'N':
            return 2
    return 0

def _isinfinity(self):
    """Returns whether the number is infinite

    0 if finite or not a number
    1 if +INF
    -1 if -INF"""
    if self._exp == 'F':
        if self._sign:
            return -1
        return 1
    return 0

def _check_nans(self, other=None, context=None):
    """Returns whether the number is not actually one.

    if self, other are sNaN, signal
    if self, other are NaN return nan
    return 0

    Done before operations."""
    self_is_nan = self._isnan()
    if other is None:
        other_is_nan = False
    else:
        other_is_nan = other._isnan()
    if self_is_nan or other_is_nan:
        if context is None:
            context = getcontext()
        if self_is_nan == 2:
            return context._raise_error(InvalidOperation, 'sNaN', self)
        if other_is_nan == 2:
            return context._raise_error(InvalidOperation, 'sNaN', other)
        if self_is_nan:
            return self._fix_nan(context)
        return other._fix_nan(context)
    return 0

def _compare_check_nans(self, other, context):
    """Version of _check_nans used for the signaling comparisons
    compare_signal, __le__, __lt__, __ge__, __gt__.

    Signal InvalidOperation if either self or other is a (quiet
    or signaling) NaN.  Signaling NaNs take precedence over quiet
    NaNs.

    Return 0 if neither operand is a NaN."""
    if context is None:
        context = getcontext()
    if self._is_special or other._is_special:
        if self.is_snan():
            return context._raise_error(InvalidOperation, 'comparison involving sNaN', self)
        elif other.is_snan():
            return context._raise_error(InvalidOperation, 'comparison involving sNaN', other)
        elif self.is_qnan():
            return context._raise_error(InvalidOperation, 'comparison involving NaN', self)
        elif other.is_qnan():
            return context._raise_error(InvalidOperation, 'comparison involving NaN', other)
    return 0

def _cmp(self, other):
    """Compare the two non-NaN decimal instances self and other.

    Returns -1 if self < other, 0 if self == other and 1
    if self > other.  This routine is for internal use only."""
    if self._is_special or other._is_special:
        self_inf = self._isinfinity()
        other_inf = other._isinfinity()
        if self_inf == other_inf:
            return 0
        elif self_inf < other_inf:
            return -1
        else:
            return 1
    if not self:
        if not other:
            return 0
        else:
            return -(-1) ** other._sign
    if not other:
        return (-1) ** self._sign
    if other._sign < self._sign:
        return -1
    if self._sign < other._sign:
        return 1
    self_adjusted = self.adjusted()
    other_adjusted = other.adjusted()
    if self_adjusted == other_adjusted:
        self_padded = self._int + '0' * (self._exp - other._exp)
        other_padded = other._int + '0' * (other._exp - self._exp)
        if self_padded == other_padded:
            return 0
        elif self_padded < other_padded:
            return -(-1) ** self._sign
        else:
            return (-1) ** self._sign
    elif self_adjusted > other_adjusted:
        return (-1) ** self._sign
    else:
        return -(-1) ** self._sign

def __eq__(self, other, context=None):
    self, other = _convert_for_comparison(self, other, equality_op=True)
    if other is NotImplemented:
        return other
    if self._check_nans(other, context):
        return False
    return self._cmp(other) == 0

def __lt__(self, other, context=None):
    self, other = _convert_for_comparison(self, other)
    if other is NotImplemented:
        return other
    ans = self._compare_check_nans(other, context)
    if ans:
        return False
    return self._cmp(other) < 0

def __le__(self, other, context=None):
    self, other = _convert_for_comparison(self, other)
    if other is NotImplemented:
        return other
    ans = self._compare_check_nans(other, context)
    if ans:
        return False
    return self._cmp(other) <= 0

def __gt__(self, other, context=None):
    self, other = _convert_for_comparison(self, other)
    if other is NotImplemented:
        return other
    ans = self._compare_check_nans(other, context)
    if ans:
        return False
    return self._cmp(other) > 0

def __ge__(self, other, context=None):
    self, other = _convert_for_comparison(self, other)
    if other is NotImplemented:
        return other
    ans = self._compare_check_nans(other, context)
    if ans:
        return False
    return self._cmp(other) >= 0

def compare(self, other, context=None):
    """Compare self to other.  Return a decimal value:

    a or b is a NaN ==> Decimal('NaN')
    a < b           ==> Decimal('-1')
    a == b          ==> Decimal('0')
    a > b           ==> Decimal('1')"""
    other = _convert_other(other, raiseit=True)
    if self._is_special or (other and other._is_special):
        ans = self._check_nans(other, context)
        if ans:
            return ans
    return Decimal(self._cmp(other))

def __hash__(self):
    """x.__hash__() <==> hash(x)"""
    if self._is_special:
        if self.is_snan():
            raise TypeError('Cannot hash a signaling NaN value.')
        elif self.is_nan():
            return object.__hash__(self)
        elif self._sign:
            return -_PyHASH_INF
        else:
            return _PyHASH_INF
    if self._exp >= 0:
        exp_hash = pow(10, self._exp, _PyHASH_MODULUS)
    else:
        exp_hash = pow(_PyHASH_10INV, -self._exp, _PyHASH_MODULUS)
    hash_ = int(self._int) * exp_hash % _PyHASH_MODULUS
    ans = hash_ if self >= 0 else -hash_
    return -2 if ans == -1 else ans

def as_tuple(self):
    """Represents the number as a triple tuple.

    To show the internals exactly as they are."""
    return DecimalTuple(self._sign, tuple(map(int, self._int)), self._exp)

def as_integer_ratio(self):
    """Express a finite Decimal instance in the form n / d.

    Returns a pair (n, d) of integers.  When called on an infinity
    or NaN, raises OverflowError or ValueError respectively.

    >>> Decimal('3.14').as_integer_ratio()
    (157, 50)
    >>> Decimal('-123e5').as_integer_ratio()
    (-12300000, 1)
    >>> Decimal('0.00').as_integer_ratio()
    (0, 1)"""
    if self._is_special:
        if self.is_nan():
            raise ValueError('cannot convert NaN to integer ratio')
        else:
            raise OverflowError('cannot convert Infinity to integer ratio')
    if not self:
        return (0, 1)
    n = int(self._int)
    if self._exp >= 0:
        n, d = (n * 10 ** self._exp, 1)
    else:
        d5 = -self._exp
        while d5 > 0 and n % 5 == 0:
            n //= 5
            d5 -= 1
        d2 = -self._exp
        shift2 = min((n & -n).bit_length() - 1, d2)
        if shift2:
            n >>= shift2
            d2 -= shift2
        d = 5 ** d5 << d2
    if self._sign:
        n = -n
    return (n, d)

def __repr__(self):
    """Represents the number as an instance of Decimal."""
    return "Decimal('%s')" % str(self)

def __str__(self, eng=False, context=None):
    """Return string representation of the number in scientific notation.

    Captures all of the information in the underlying representation."""
    sign = ['', '-'][self._sign]
    if self._is_special:
        if self._exp == 'F':
            return sign + 'Infinity'
        elif self._exp == 'n':
            return sign + 'NaN' + self._int
        else:
            return sign + 'sNaN' + self._int
    leftdigits = self._exp + len(self._int)
    if self._exp <= 0 and leftdigits > -6:
        dotplace = leftdigits
    elif not eng:
        dotplace = 1
    elif self._int == '0':
        dotplace = (leftdigits + 1) % 3 - 1
    else:
        dotplace = (leftdigits - 1) % 3 + 1
    if dotplace <= 0:
        intpart = '0'
        fracpart = '.' + '0' * -dotplace + self._int
    elif dotplace >= len(self._int):
        intpart = self._int + '0' * (dotplace - len(self._int))
        fracpart = ''
    else:
        intpart = self._int[:dotplace]
        fracpart = '.' + self._int[dotplace:]
    if leftdigits == dotplace:
        exp = ''
    else:
        if context is None:
            context = getcontext()
        exp = ['e', 'E'][context.capitals] + '%+d' % (leftdigits - dotplace)
    return sign + intpart + fracpart + exp

def to_eng_string(self, context=None):
    """Convert to a string, using engineering notation if an exponent is needed.

    Engineering notation has an exponent which is a multiple of 3.  This
    can leave up to 3 digits to the left of the decimal place and may
    require the addition of either one or two trailing zeros."""
    return self.__str__(eng=True, context=context)

def __neg__(self, context=None):
    """Returns a copy with the sign switched.

    Rounds, if it has reason."""
    if self._is_special:
        ans = self._check_nans(context=context)
        if ans:
            return ans
    if context is None:
        context = getcontext()
    if not self and context.rounding != ROUND_FLOOR:
        ans = self.copy_abs()
    else:
        ans = self.copy_negate()
    return ans._fix(context)

def __pos__(self, context=None):
    """Returns a copy, unless it is a sNaN.

    Rounds the number (if more than precision digits)"""
    if self._is_special:
        ans = self._check_nans(context=context)
        if ans:
            return ans
    if context is None:
        context = getcontext()
    if not self and context.rounding != ROUND_FLOOR:
        ans = self.copy_abs()
    else:
        ans = Decimal(self)
    return ans._fix(context)

def __abs__(self, round=True, context=None):
    """Returns the absolute value of self.

    If the keyword argument 'round' is false, do not round.  The
    expression self.__abs__(round=False) is equivalent to
    self.copy_abs()."""
    if not round:
        return self.copy_abs()
    if self._is_special:
        ans = self._check_nans(context=context)
        if ans:
            return ans
    if self._sign:
        ans = self.__neg__(context=context)
    else:
        ans = self.__pos__(context=context)
    return ans

def __sub__(self, other, context=None):
    """Return self - other"""
    other = _convert_other(other)
    if other is NotImplemented:
        return other
    if self._is_special or other._is_special:
        ans = self._check_nans(other, context=context)
        if ans:
            return ans
    return self.__add__(other.copy_negate(), context=context)

def __rsub__(self, other, context=None):
    """Return other - self"""
    other = _convert_other(other)
    if other is NotImplemented:
        return other
    return other.__sub__(self, context=context)

def __mul__(self, other, context=None):
    """Return self * other.

    (+-) INF * 0 (or its reverse) raise InvalidOperation."""
    other = _convert_other(other)
    if other is NotImplemented:
        return other
    if context is None:
        context = getcontext()
    resultsign = self._sign ^ other._sign
    if self._is_special or other._is_special:
        ans = self._check_nans(other, context)
        if ans:
            return ans
        if self._isinfinity():
            if not other:
                return context._raise_error(InvalidOperation, '(+-)INF * 0')
            return _SignedInfinity[resultsign]
        if other._isinfinity():
            if not self:
                return context._raise_error(InvalidOperation, '0 * (+-)INF')
            return _SignedInfinity[resultsign]
    resultexp = self._exp + other._exp
    if not self or not other:
        ans = _dec_from_triple(resultsign, '0', resultexp)
        ans = ans._fix(context)
        return ans
    if self._int == '1':
        ans = _dec_from_triple(resultsign, other._int, resultexp)
        ans = ans._fix(context)
        return ans
    if other._int == '1':
        ans = _dec_from_triple(resultsign, self._int, resultexp)
        ans = ans._fix(context)
        return ans
    op1 = _WorkRep(self)
    op2 = _WorkRep(other)
    ans = _dec_from_triple(resultsign, str(op1.int * op2.int), resultexp)
    ans = ans._fix(context)
    return ans

def _divide(self, other, context):
    """Return (self // other, self % other), to context.prec precision.

    Assumes that neither self nor other is a NaN, that self is not
    infinite and that other is nonzero."""
    sign = self._sign ^ other._sign
    if other._isinfinity():
        ideal_exp = self._exp
    else:
        ideal_exp = min(self._exp, other._exp)
    expdiff = self.adjusted() - other.adjusted()
    if not self or other._isinfinity() or expdiff <= -2:
        return (_dec_from_triple(sign, '0', 0), self._rescale(ideal_exp, context.rounding))
    if expdiff <= context.prec:
        op1 = _WorkRep(self)
        op2 = _WorkRep(other)
        if op1.exp >= op2.exp:
            op1.int *= 10 ** (op1.exp - op2.exp)
        else:
            op2.int *= 10 ** (op2.exp - op1.exp)
        q, r = divmod(op1.int, op2.int)
        if q < 10 ** context.prec:
            return (_dec_from_triple(sign, str(q), 0), _dec_from_triple(self._sign, str(r), ideal_exp))
    ans = context._raise_error(DivisionImpossible, 'quotient too large in //, % or divmod')
    return (ans, ans)

def __rtruediv__(self, other, context=None):
    """Swaps self/other and returns __truediv__."""
    other = _convert_other(other)
    if other is NotImplemented:
        return other
    return other.__truediv__(self, context=context)

def __divmod__(self, other, context=None):
    """Return (self // other, self % other)"""
    other = _convert_other(other)
    if other is NotImplemented:
        return other
    if context is None:
        context = getcontext()
    ans = self._check_nans(other, context)
    if ans:
        return (ans, ans)
    sign = self._sign ^ other._sign
    if self._isinfinity():
        if other._isinfinity():
            ans = context._raise_error(InvalidOperation, 'divmod(INF, INF)')
            return (ans, ans)
        else:
            return (_SignedInfinity[sign], context._raise_error(InvalidOperation, 'INF % x'))
    if not other:
        if not self:
            ans = context._raise_error(DivisionUndefined, 'divmod(0, 0)')
            return (ans, ans)
        else:
            return (context._raise_error(DivisionByZero, 'x // 0', sign), context._raise_error(InvalidOperation, 'x % 0'))
    quotient, remainder = self._divide(other, context)
    remainder = remainder._fix(context)
    return (quotient, remainder)

def __rdivmod__(self, other, context=None):
    """Swaps self/other and returns __divmod__."""
    other = _convert_other(other)
    if other is NotImplemented:
        return other
    return other.__divmod__(self, context=context)

def __mod__(self, other, context=None):
    """self % other"""
    other = _convert_other(other)
    if other is NotImplemented:
        return other
    if context is None:
        context = getcontext()
    ans = self._check_nans(other, context)
    if ans:
        return ans
    if self._isinfinity():
        return context._raise_error(InvalidOperation, 'INF % x')
    elif not other:
        if self:
            return context._raise_error(InvalidOperation, 'x % 0')
        else:
            return context._raise_error(DivisionUndefined, '0 % 0')
    remainder = self._divide(other, context)[1]
    remainder = remainder._fix(context)
    return remainder

def __rmod__(self, other, context=None):
    """Swaps self/other and returns __mod__."""
    other = _convert_other(other)
    if other is NotImplemented:
        return other
    return other.__mod__(self, context=context)

def __floordiv__(self, other, context=None):
    """self // other"""
    other = _convert_other(other)
    if other is NotImplemented:
        return other
    if context is None:
        context = getcontext()
    ans = self._check_nans(other, context)
    if ans:
        return ans
    if self._isinfinity():
        if other._isinfinity():
            return context._raise_error(InvalidOperation, 'INF // INF')
        else:
            return _SignedInfinity[self._sign ^ other._sign]
    if not other:
        if self:
            return context._raise_error(DivisionByZero, 'x // 0', self._sign ^ other._sign)
        else:
            return context._raise_error(DivisionUndefined, '0 // 0')
    return self._divide(other, context)[0]

def __rfloordiv__(self, other, context=None):
    """Swaps self/other and returns __floordiv__."""
    other = _convert_other(other)
    if other is NotImplemented:
        return other
    return other.__floordiv__(self, context=context)

def __float__(self):
    """Float representation."""
    if self._isnan():
        if self.is_snan():
            raise ValueError('Cannot convert signaling NaN to float')
        s = '-nan' if self._sign else 'nan'
    else:
        s = str(self)
    return float(s)

def __int__(self):
    """Converts self to an int, truncating if necessary."""
    if self._is_special:
        if self._isnan():
            raise ValueError('Cannot convert NaN to integer')
        elif self._isinfinity():
            raise OverflowError('Cannot convert infinity to integer')
    s = (-1) ** self._sign
    if self._exp >= 0:
        return s * int(self._int) * 10 ** self._exp
    else:
        return s * int(self._int[:self._exp] or '0')

def _fix_nan(self, context):
    """Decapitate the payload of a NaN to fit the context"""
    payload = self._int
    max_payload_len = context.prec - context.clamp
    if len(payload) > max_payload_len:
        payload = payload[len(payload) - max_payload_len:].lstrip('0')
        return _dec_from_triple(self._sign, payload, self._exp, True)
    return Decimal(self)

def _round_down(self, prec):
    """Also known as round-towards-0, truncate."""
    if _all_zeros(self._int, prec):
        return 0
    else:
        return -1

def _round_up(self, prec):
    """Rounds away from 0."""
    return -self._round_down(prec)

def _round_half_up(self, prec):
    """Rounds 5 up (away from 0)"""
    if self._int[prec] in '56789':
        return 1
    elif _all_zeros(self._int, prec):
        return 0
    else:
        return -1

def _round_half_down(self, prec):
    """Round 5 down"""
    if _exact_half(self._int, prec):
        return -1
    else:
        return self._round_half_up(prec)

def _round_half_even(self, prec):
    """Round 5 to even, rest to nearest."""
    if _exact_half(self._int, prec) and (prec == 0 or self._int[prec - 1] in '02468'):
        return -1
    else:
        return self._round_half_up(prec)

def _round_ceiling(self, prec):
    """Rounds up (not away from 0 if negative.)"""
    if self._sign:
        return self._round_down(prec)
    else:
        return -self._round_down(prec)

def _round_floor(self, prec):
    """Rounds down (not towards 0 if negative)"""
    if not self._sign:
        return self._round_down(prec)
    else:
        return -self._round_down(prec)

def _round_05up(self, prec):
    """Round down unless digit prec-1 is 0 or 5."""
    if prec and self._int[prec - 1] not in '05':
        return self._round_down(prec)
    else:
        return -self._round_down(prec)

def __floor__(self):
    """Return the floor of self, as an integer.

    For a finite Decimal instance self, return the greatest
    integer n such that n <= self.  If self is infinite or a NaN
    then a Python exception is raised."""
    if self._is_special:
        if self.is_nan():
            raise ValueError('cannot round a NaN')
        else:
            raise OverflowError('cannot round an infinity')
    return int(self._rescale(0, ROUND_FLOOR))

def __ceil__(self):
    """Return the ceiling of self, as an integer.

    For a finite Decimal instance self, return the least integer n
    such that n >= self.  If self is infinite or a NaN then a
    Python exception is raised."""
    if self._is_special:
        if self.is_nan():
            raise ValueError('cannot round a NaN')
        else:
            raise OverflowError('cannot round an infinity')
    return int(self._rescale(0, ROUND_CEILING))

def __rpow__(self, other, context=None):
    """Swaps self/other and returns __pow__."""
    other = _convert_other(other)
    if other is NotImplemented:
        return other
    return other.__pow__(self, context=context)

def normalize(self, context=None):
    """Normalize- strip trailing 0s, change anything equal to 0 to 0e0"""
    if context is None:
        context = getcontext()
    if self._is_special:
        ans = self._check_nans(context=context)
        if ans:
            return ans
    dup = self._fix(context)
    if dup._isinfinity():
        return dup
    if not dup:
        return _dec_from_triple(dup._sign, '0', 0)
    exp_max = [context.Emax, context.Etop()][context.clamp]
    end = len(dup._int)
    exp = dup._exp
    while dup._int[end - 1] == '0' and exp < exp_max:
        exp += 1
        end -= 1
    return _dec_from_triple(dup._sign, dup._int[:end], exp)

def quantize(self, exp, rounding=None, context=None):
    """Quantize self so its exponent is the same as that of exp.

    Similar to self._rescale(exp._exp) but with error checking."""
    exp = _convert_other(exp, raiseit=True)
    if context is None:
        context = getcontext()
    if rounding is None:
        rounding = context.rounding
    if self._is_special or exp._is_special:
        ans = self._check_nans(exp, context)
        if ans:
            return ans
        if exp._isinfinity() or self._isinfinity():
            if exp._isinfinity() and self._isinfinity():
                return Decimal(self)
            return context._raise_error(InvalidOperation, 'quantize with one INF')
    if not context.Etiny() <= exp._exp <= context.Emax:
        return context._raise_error(InvalidOperation, 'target exponent out of bounds in quantize')
    if not self:
        ans = _dec_from_triple(self._sign, '0', exp._exp)
        return ans._fix(context)
    self_adjusted = self.adjusted()
    if self_adjusted > context.Emax:
        return context._raise_error(InvalidOperation, 'exponent of quantize result too large for current context')
    if self_adjusted - exp._exp + 1 > context.prec:
        return context._raise_error(InvalidOperation, 'quantize result has too many digits for current context')
    ans = self._rescale(exp._exp, rounding)
    if ans.adjusted() > context.Emax:
        return context._raise_error(InvalidOperation, 'exponent of quantize result too large for current context')
    if len(ans._int) > context.prec:
        return context._raise_error(InvalidOperation, 'quantize result has too many digits for current context')
    if ans and ans.adjusted() < context.Emin:
        context._raise_error(Subnormal)
    if ans._exp > self._exp:
        if ans != self:
            context._raise_error(Inexact)
        context._raise_error(Rounded)
    ans = ans._fix(context)
    return ans

def _rescale(self, exp, rounding):
    """Rescale self so that the exponent is exp, either by padding with zeros
    or by truncating digits, using the given rounding mode.

    Specials are returned without change.  This operation is
    quiet: it raises no flags, and uses no information from the
    context.

    exp = exp to scale to (an integer)
    rounding = rounding mode"""
    if self._is_special:
        return Decimal(self)
    if not self:
        return _dec_from_triple(self._sign, '0', exp)
    if self._exp >= exp:
        return _dec_from_triple(self._sign, self._int + '0' * (self._exp - exp), exp)
    digits = len(self._int) + self._exp - exp
    if digits < 0:
        self = _dec_from_triple(self._sign, '1', exp - 1)
        digits = 0
    this_function = self._pick_rounding_function[rounding]
    changed = this_function(self, digits)
    coeff = self._int[:digits] or '0'
    if changed == 1:
        coeff = str(int(coeff) + 1)
    return _dec_from_triple(self._sign, coeff, exp)

def _round(self, places, rounding):
    """Round a nonzero, nonspecial Decimal to a fixed number of
    significant figures, using the given rounding mode.

    Infinities, NaNs and zeros are returned unaltered.

    This operation is quiet: it raises no flags, and uses no
    information from the context."""
    if places <= 0:
        raise ValueError('argument should be at least 1 in _round')
    if self._is_special or not self:
        return Decimal(self)
    ans = self._rescale(self.adjusted() + 1 - places, rounding)
    if ans.adjusted() != self.adjusted():
        ans = ans._rescale(ans.adjusted() + 1 - places, rounding)
    return ans

def to_integral_exact(self, rounding=None, context=None):
    """Rounds to a nearby integer.

    If no rounding mode is specified, take the rounding mode from
    the context.  This method raises the Rounded and Inexact flags
    when appropriate.

    See also: to_integral_value, which does exactly the same as
    this method except that it doesn't raise Inexact or Rounded."""
    if self._is_special:
        ans = self._check_nans(context=context)
        if ans:
            return ans
        return Decimal(self)
    if self._exp >= 0:
        return Decimal(self)
    if not self:
        return _dec_from_triple(self._sign, '0', 0)
    if context is None:
        context = getcontext()
    if rounding is None:
        rounding = context.rounding
    ans = self._rescale(0, rounding)
    if ans != self:
        context._raise_error(Inexact)
    context._raise_error(Rounded)
    return ans

def to_integral_value(self, rounding=None, context=None):
    """Rounds to the nearest integer, without raising inexact, rounded."""
    if context is None:
        context = getcontext()
    if rounding is None:
        rounding = context.rounding
    if self._is_special:
        ans = self._check_nans(context=context)
        if ans:
            return ans
        return Decimal(self)
    if self._exp >= 0:
        return Decimal(self)
    else:
        return self._rescale(0, rounding)

def max(self, other, context=None):
    """Returns the larger value.

    Like max(self, other) except if one is not a number, returns
    NaN (and signals if one is sNaN).  Also rounds."""
    other = _convert_other(other, raiseit=True)
    if context is None:
        context = getcontext()
    if self._is_special or other._is_special:
        sn = self._isnan()
        on = other._isnan()
        if sn or on:
            if on == 1 and sn == 0:
                return self._fix(context)
            if sn == 1 and on == 0:
                return other._fix(context)
            return self._check_nans(other, context)
    c = self._cmp(other)
    if c == 0:
        c = self.compare_total(other)
    if c == -1:
        ans = other
    else:
        ans = self
    return ans._fix(context)

def min(self, other, context=None):
    """Returns the smaller value.

    Like min(self, other) except if one is not a number, returns
    NaN (and signals if one is sNaN).  Also rounds."""
    other = _convert_other(other, raiseit=True)
    if context is None:
        context = getcontext()
    if self._is_special or other._is_special:
        sn = self._isnan()
        on = other._isnan()
        if sn or on:
            if on == 1 and sn == 0:
                return self._fix(context)
            if sn == 1 and on == 0:
                return other._fix(context)
            return self._check_nans(other, context)
    c = self._cmp(other)
    if c == 0:
        c = self.compare_total(other)
    if c == -1:
        ans = self
    else:
        ans = other
    return ans._fix(context)

def _isinteger(self):
    """Returns whether self is an integer"""
    if self._is_special:
        return False
    if self._exp >= 0:
        return True
    rest = self._int[self._exp:]
    return rest == '0' * len(rest)

def _iseven(self):
    """Returns True if self is even.  Assumes self is an integer."""
    if not self or self._exp > 0:
        return True
    return self._int[-1 + self._exp] in '02468'

def adjusted(self):
    """Return the adjusted exponent of self"""
    try:
        return self._exp + len(self._int) - 1
    except TypeError:
        return 0

def compare_signal(self, other, context=None):
    """Compares self to the other operand numerically.

    It's pretty much like compare(), but all NaNs signal, with signaling
    NaNs taking precedence over quiet NaNs."""
    other = _convert_other(other, raiseit=True)
    ans = self._compare_check_nans(other, context)
    if ans:
        return ans
    return self.compare(other, context=context)

def copy_abs(self):
    """Returns a copy with the sign set to 0."""
    return _dec_from_triple(0, self._int, self._exp, self._is_special)

def copy_negate(self):
    """Returns a copy with the sign inverted."""
    if self._sign:
        return _dec_from_triple(0, self._int, self._exp, self._is_special)
    else:
        return _dec_from_triple(1, self._int, self._exp, self._is_special)

def copy_sign(self, other, context=None):
    """Returns self with the sign of other."""
    other = _convert_other(other, raiseit=True)
    return _dec_from_triple(other._sign, self._int, self._exp, self._is_special)

def exp(self, context=None):
    """Returns e ** self."""
    if context is None:
        context = getcontext()
    ans = self._check_nans(context=context)
    if ans:
        return ans
    if self._isinfinity() == -1:
        return _Zero
    if not self:
        return _One
    if self._isinfinity() == 1:
        return Decimal(self)
    p = context.prec
    adj = self.adjusted()
    if self._sign == 0 and adj > len(str((context.Emax + 1) * 3)):
        ans = _dec_from_triple(0, '1', context.Emax + 1)
    elif self._sign == 1 and adj > len(str((-context.Etiny() + 1) * 3)):
        ans = _dec_from_triple(0, '1', context.Etiny() - 1)
    elif self._sign == 0 and adj < -p:
        ans = _dec_from_triple(0, '1' + '0' * (p - 1) + '1', -p)
    elif self._sign == 1 and adj < -p - 1:
        ans = _dec_from_triple(0, '9' * (p + 1), -p - 1)
    else:
        op = _WorkRep(self)
        c, e = (op.int, op.exp)
        if op.sign == 1:
            c = -c
        extra = 3
        while True:
            coeff, exp = _dexp(c, e, p + extra)
            if coeff % (5 * 10 ** (len(str(coeff)) - p - 1)):
                break
            extra += 3
        ans = _dec_from_triple(0, str(coeff), exp)
    context = context._shallow_copy()
    rounding = context._set_rounding(ROUND_HALF_EVEN)
    ans = ans._fix(context)
    context.rounding = rounding
    return ans

def is_infinite(self):
    """Return True if self is infinite; otherwise return False."""
    return self._exp == 'F'

def is_nan(self):
    """Return True if self is a qNaN or sNaN; otherwise return False."""
    return self._exp in ('n', 'N')

def is_normal(self, context=None):
    """Return True if self is a normal number; otherwise return False."""
    if self._is_special or not self:
        return False
    if context is None:
        context = getcontext()
    return context.Emin <= self.adjusted()

def is_qnan(self):
    """Return True if self is a quiet NaN; otherwise return False."""
    return self._exp == 'n'

def is_signed(self):
    """Return True if self is negative; otherwise return False."""
    return self._sign == 1

def is_snan(self):
    """Return True if self is a signaling NaN; otherwise return False."""
    return self._exp == 'N'

def is_subnormal(self, context=None):
    """Return True if self is subnormal; otherwise return False."""
    if self._is_special or not self:
        return False
    if context is None:
        context = getcontext()
    return self.adjusted() < context.Emin

def is_zero(self):
    """Return True if self is a zero; otherwise return False."""
    return not self._is_special and self._int == '0'

def _ln_exp_bound(self):
    """Compute a lower bound for the adjusted exponent of self.ln().
    In other words, compute r such that self.ln() >= 10**r.  Assumes
    that self is finite and positive and that self != 1."""
    adj = self._exp + len(self._int) - 1
    if adj >= 1:
        return len(str(adj * 23 // 10)) - 1
    if adj <= -2:
        return len(str((-1 - adj) * 23 // 10)) - 1
    op = _WorkRep(self)
    c, e = (op.int, op.exp)
    if adj == 0:
        num = str(c - 10 ** (-e))
        den = str(c)
        return len(num) - len(den) - (num < den)
    return e + len(str(10 ** (-e) - c)) - 1

def ln(self, context=None):
    """Returns the natural (base e) logarithm of self."""
    if context is None:
        context = getcontext()
    ans = self._check_nans(context=context)
    if ans:
        return ans
    if not self:
        return _NegativeInfinity
    if self._isinfinity() == 1:
        return _Infinity
    if self == _One:
        return _Zero
    if self._sign == 1:
        return context._raise_error(InvalidOperation, 'ln of a negative value')
    op = _WorkRep(self)
    c, e = (op.int, op.exp)
    p = context.prec
    places = p - self._ln_exp_bound() + 2
    while True:
        coeff = _dlog(c, e, places)
        if coeff % (5 * 10 ** (len(str(abs(coeff))) - p - 1)):
            break
        places += 3
    ans = _dec_from_triple(int(coeff < 0), str(abs(coeff)), -places)
    context = context._shallow_copy()
    rounding = context._set_rounding(ROUND_HALF_EVEN)
    ans = ans._fix(context)
    context.rounding = rounding
    return ans

def log10(self, context=None):
    """Returns the base 10 logarithm of self."""
    if context is None:
        context = getcontext()
    ans = self._check_nans(context=context)
    if ans:
        return ans
    if not self:
        return _NegativeInfinity
    if self._isinfinity() == 1:
        return _Infinity
    if self._sign == 1:
        return context._raise_error(InvalidOperation, 'log10 of a negative value')
    if self._int[0] == '1' and self._int[1:] == '0' * (len(self._int) - 1):
        ans = Decimal(self._exp + len(self._int) - 1)
    else:
        op = _WorkRep(self)
        c, e = (op.int, op.exp)
        p = context.prec
        places = p - self._log10_exp_bound() + 2
        while True:
            coeff = _dlog10(c, e, places)
            if coeff % (5 * 10 ** (len(str(abs(coeff))) - p - 1)):
                break
            places += 3
        ans = _dec_from_triple(int(coeff < 0), str(abs(coeff)), -places)
    context = context._shallow_copy()
    rounding = context._set_rounding(ROUND_HALF_EVEN)
    ans = ans._fix(context)
    context.rounding = rounding
    return ans

def logb(self, context=None):
    """Returns the exponent of the magnitude of self's MSD.

    The result is the integer which is the exponent of the magnitude
    of the most significant digit of self (as though it were truncated
    to a single digit while maintaining the value of that digit and
    without limiting the resulting exponent)."""
    ans = self._check_nans(context=context)
    if ans:
        return ans
    if context is None:
        context = getcontext()
    if self._isinfinity():
        return _Infinity
    if not self:
        return context._raise_error(DivisionByZero, 'logb(0)', 1)
    ans = Decimal(self.adjusted())
    return ans._fix(context)

def _islogical(self):
    """Return True if self is a logical operand.

    For being logical, it must be a finite number with a sign of 0,
    an exponent of 0, and a coefficient whose digits must all be
    either 0 or 1."""
    if self._sign != 0 or self._exp != 0:
        return False
    for dig in self._int:
        if dig not in '01':
            return False
    return True

def _fill_logical(self, context, opa, opb):
    dif = context.prec - len(opa)
    if dif > 0:
        opa = '0' * dif + opa
    elif dif < 0:
        opa = opa[-context.prec:]
    dif = context.prec - len(opb)
    if dif > 0:
        opb = '0' * dif + opb
    elif dif < 0:
        opb = opb[-context.prec:]
    return (opa, opb)

def logical_and(self, other, context=None):
    """Applies an 'and' operation between self and other's digits."""
    if context is None:
        context = getcontext()
    other = _convert_other(other, raiseit=True)
    if not self._islogical() or not other._islogical():
        return context._raise_error(InvalidOperation)
    opa, opb = self._fill_logical(context, self._int, other._int)
    result = ''.join([str(int(a) & int(b)) for a, b in zip(opa, opb)])
    return _dec_from_triple(0, result.lstrip('0') or '0', 0)

def logical_invert(self, context=None):
    """Invert all its digits."""
    if context is None:
        context = getcontext()
    return self.logical_xor(_dec_from_triple(0, '1' * context.prec, 0), context)

def logical_or(self, other, context=None):
    """Applies an 'or' operation between self and other's digits."""
    if context is None:
        context = getcontext()
    other = _convert_other(other, raiseit=True)
    if not self._islogical() or not other._islogical():
        return context._raise_error(InvalidOperation)
    opa, opb = self._fill_logical(context, self._int, other._int)
    result = ''.join([str(int(a) | int(b)) for a, b in zip(opa, opb)])
    return _dec_from_triple(0, result.lstrip('0') or '0', 0)

def logical_xor(self, other, context=None):
    """Applies an 'xor' operation between self and other's digits."""
    if context is None:
        context = getcontext()
    other = _convert_other(other, raiseit=True)
    if not self._islogical() or not other._islogical():
        return context._raise_error(InvalidOperation)
    opa, opb = self._fill_logical(context, self._int, other._int)
    result = ''.join([str(int(a) ^ int(b)) for a, b in zip(opa, opb)])
    return _dec_from_triple(0, result.lstrip('0') or '0', 0)

def max_mag(self, other, context=None):
    """Compares the values numerically with their sign ignored."""
    other = _convert_other(other, raiseit=True)
    if context is None:
        context = getcontext()
    if self._is_special or other._is_special:
        sn = self._isnan()
        on = other._isnan()
        if sn or on:
            if on == 1 and sn == 0:
                return self._fix(context)
            if sn == 1 and on == 0:
                return other._fix(context)
            return self._check_nans(other, context)
    c = self.copy_abs()._cmp(other.copy_abs())
    if c == 0:
        c = self.compare_total(other)
    if c == -1:
        ans = other
    else:
        ans = self
    return ans._fix(context)

def min_mag(self, other, context=None):
    """Compares the values numerically with their sign ignored."""
    other = _convert_other(other, raiseit=True)
    if context is None:
        context = getcontext()
    if self._is_special or other._is_special:
        sn = self._isnan()
        on = other._isnan()
        if sn or on:
            if on == 1 and sn == 0:
                return self._fix(context)
            if sn == 1 and on == 0:
                return other._fix(context)
            return self._check_nans(other, context)
    c = self.copy_abs()._cmp(other.copy_abs())
    if c == 0:
        c = self.compare_total(other)
    if c == -1:
        ans = self
    else:
        ans = other
    return ans._fix(context)

def next_minus(self, context=None):
    """Returns the largest representable number smaller than itself."""
    if context is None:
        context = getcontext()
    ans = self._check_nans(context=context)
    if ans:
        return ans
    if self._isinfinity() == -1:
        return _NegativeInfinity
    if self._isinfinity() == 1:
        return _dec_from_triple(0, '9' * context.prec, context.Etop())
    context = context.copy()
    context._set_rounding(ROUND_FLOOR)
    context._ignore_all_flags()
    new_self = self._fix(context)
    if new_self != self:
        return new_self
    return self.__sub__(_dec_from_triple(0, '1', context.Etiny() - 1), context)

def next_plus(self, context=None):
    """Returns the smallest representable number larger than itself."""
    if context is None:
        context = getcontext()
    ans = self._check_nans(context=context)
    if ans:
        return ans
    if self._isinfinity() == 1:
        return _Infinity
    if self._isinfinity() == -1:
        return _dec_from_triple(1, '9' * context.prec, context.Etop())
    context = context.copy()
    context._set_rounding(ROUND_CEILING)
    context._ignore_all_flags()
    new_self = self._fix(context)
    if new_self != self:
        return new_self
    return self.__add__(_dec_from_triple(0, '1', context.Etiny() - 1), context)

def next_toward(self, other, context=None):
    """Returns the number closest to self, in the direction towards other.

    The result is the closest representable number to self
    (excluding self) that is in the direction towards other,
    unless both have the same value.  If the two operands are
    numerically equal, then the result is a copy of self with the
    sign set to be the same as the sign of other."""
    other = _convert_other(other, raiseit=True)
    if context is None:
        context = getcontext()
    ans = self._check_nans(other, context)
    if ans:
        return ans
    comparison = self._cmp(other)
    if comparison == 0:
        return self.copy_sign(other)
    if comparison == -1:
        ans = self.next_plus(context)
    else:
        ans = self.next_minus(context)
    if ans._isinfinity():
        context._raise_error(Overflow, 'Infinite result from next_toward', ans._sign)
        context._raise_error(Inexact)
        context._raise_error(Rounded)
    elif ans.adjusted() < context.Emin:
        context._raise_error(Underflow)
        context._raise_error(Subnormal)
        context._raise_error(Inexact)
        context._raise_error(Rounded)
        if not ans:
            context._raise_error(Clamped)
    return ans

def number_class(self, context=None):
    """Returns an indication of the class of self.

    The class is one of the following strings:
      sNaN
      NaN
      -Infinity
      -Normal
      -Subnormal
      -Zero
      +Zero
      +Subnormal
      +Normal
      +Infinity"""
    if self.is_snan():
        return 'sNaN'
    if self.is_qnan():
        return 'NaN'
    inf = self._isinfinity()
    if inf == 1:
        return '+Infinity'
    if inf == -1:
        return '-Infinity'
    if self.is_zero():
        if self._sign:
            return '-Zero'
        else:
            return '+Zero'
    if context is None:
        context = getcontext()
    if self.is_subnormal(context=context):
        if self._sign:
            return '-Subnormal'
        else:
            return '+Subnormal'
    if self._sign:
        return '-Normal'
    else:
        return '+Normal'

def radix(self):
    """Just returns 10, as this is Decimal, :)"""
    return Decimal(10)

def scaleb(self, other, context=None):
    """Returns self operand after adding the second value to its exp."""
    if context is None:
        context = getcontext()
    other = _convert_other(other, raiseit=True)
    ans = self._check_nans(other, context)
    if ans:
        return ans
    if other._exp != 0:
        return context._raise_error(InvalidOperation)
    liminf = -2 * (context.Emax + context.prec)
    limsup = 2 * (context.Emax + context.prec)
    if not liminf <= int(other) <= limsup:
        return context._raise_error(InvalidOperation)
    if self._isinfinity():
        return Decimal(self)
    d = _dec_from_triple(self._sign, self._int, self._exp + int(other))
    d = d._fix(context)
    return d

def shift(self, other, context=None):
    """Returns a shifted copy of self, value-of-other times."""
    if context is None:
        context = getcontext()
    other = _convert_other(other, raiseit=True)
    ans = self._check_nans(other, context)
    if ans:
        return ans
    if other._exp != 0:
        return context._raise_error(InvalidOperation)
    if not -context.prec <= int(other) <= context.prec:
        return context._raise_error(InvalidOperation)
    if self._isinfinity():
        return Decimal(self)
    torot = int(other)
    rotdig = self._int
    topad = context.prec - len(rotdig)
    if topad > 0:
        rotdig = '0' * topad + rotdig
    elif topad < 0:
        rotdig = rotdig[-topad:]
    if torot < 0:
        shifted = rotdig[:torot]
    else:
        shifted = rotdig + '0' * torot
        shifted = shifted[-context.prec:]
    return _dec_from_triple(self._sign, shifted.lstrip('0') or '0', self._exp)

def __copy__(self):
    if type(self) is Decimal:
        return self
    return self.__class__(str(self))

def __init__(self, prec=None, rounding=None, Emin=None, Emax=None, capitals=None, clamp=None, flags=None, traps=None, _ignored_flags=None):
    try:
        dc = DefaultContext
    except NameError:
        pass
    self.prec = prec if prec is not None else dc.prec
    self.rounding = rounding if rounding is not None else dc.rounding
    self.Emin = Emin if Emin is not None else dc.Emin
    self.Emax = Emax if Emax is not None else dc.Emax
    self.capitals = capitals if capitals is not None else dc.capitals
    self.clamp = clamp if clamp is not None else dc.clamp
    if _ignored_flags is None:
        self._ignored_flags = []
    else:
        self._ignored_flags = _ignored_flags
    if traps is None:
        self.traps = dc.traps.copy()
    elif not isinstance(traps, dict):
        self.traps = dict(((s, int(s in traps)) for s in _signals + traps))
    else:
        self.traps = traps
    if flags is None:
        self.flags = dict.fromkeys(_signals, 0)
    elif not isinstance(flags, dict):
        self.flags = dict(((s, int(s in flags)) for s in _signals + flags))
    else:
        self.flags = flags

def _set_integer_check(self, name, value, vmin, vmax):
    if not isinstance(value, int):
        raise TypeError('%s must be an integer' % name)
    if vmin == '-inf':
        if value > vmax:
            raise ValueError('%s must be in [%s, %d]. got: %s' % (name, vmin, vmax, value))
    elif vmax == 'inf':
        if value < vmin:
            raise ValueError('%s must be in [%d, %s]. got: %s' % (name, vmin, vmax, value))
    elif value < vmin or value > vmax:
        raise ValueError('%s must be in [%d, %d]. got %s' % (name, vmin, vmax, value))
    return object.__setattr__(self, name, value)

def _set_signal_dict(self, name, d):
    if not isinstance(d, dict):
        raise TypeError('%s must be a signal dict' % d)
    for key in d:
        if not key in _signals:
            raise KeyError('%s is not a valid signal dict' % d)
    for key in _signals:
        if not key in d:
            raise KeyError('%s is not a valid signal dict' % d)
    return object.__setattr__(self, name, d)

def __setattr__(self, name, value):
    if name == 'prec':
        return self._set_integer_check(name, value, 1, 'inf')
    elif name == 'Emin':
        return self._set_integer_check(name, value, '-inf', 0)
    elif name == 'Emax':
        return self._set_integer_check(name, value, 0, 'inf')
    elif name == 'capitals':
        return self._set_integer_check(name, value, 0, 1)
    elif name == 'clamp':
        return self._set_integer_check(name, value, 0, 1)
    elif name == 'rounding':
        if not value in _rounding_modes:
            raise TypeError('%s: invalid rounding mode' % value)
        return object.__setattr__(self, name, value)
    elif name == 'flags' or name == 'traps':
        return self._set_signal_dict(name, value)
    elif name == '_ignored_flags':
        return object.__setattr__(self, name, value)
    else:
        raise AttributeError("'decimal.Context' object has no attribute '%s'" % name)

def __reduce__(self):
    flags = [sig for sig, v in self.flags.items() if v]
    traps = [sig for sig, v in self.traps.items() if v]
    return (self.__class__, (self.prec, self.rounding, self.Emin, self.Emax, self.capitals, self.clamp, flags, traps))

def clear_flags(self):
    """Reset all flags to zero"""
    for flag in self.flags:
        self.flags[flag] = 0

def clear_traps(self):
    """Reset all traps to zero"""
    for flag in self.traps:
        self.traps[flag] = 0

def _raise_error(self, condition, explanation=None, *args):
    """Handles an error

    If the flag is in _ignored_flags, returns the default response.
    Otherwise, it sets the flag, then, if the corresponding
    trap_enabler is set, it reraises the exception.  Otherwise, it returns
    the default value after setting the flag."""
    error = _condition_map.get(condition, condition)
    if error in self._ignored_flags:
        return error().handle(self, *args)
    self.flags[error] = 1
    if not self.traps[error]:
        return condition().handle(self, *args)
    raise error(explanation)

def _ignore_all_flags(self):
    """Ignore all flags, if they are raised"""
    return self._ignore_flags(*_signals)

def _ignore_flags(self, *flags):
    """Ignore the flags, if they are raised"""
    self._ignored_flags = self._ignored_flags + list(flags)
    return list(flags)

def _regard_flags(self, *flags):
    """Stop ignoring the flags, if they are raised"""
    if flags and isinstance(flags[0], (tuple, list)):
        flags = flags[0]
    for flag in flags:
        self._ignored_flags.remove(flag)

def Etiny(self):
    """Returns Etiny (= Emin - prec + 1)"""
    return int(self.Emin - self.prec + 1)

def Etop(self):
    """Returns maximum exponent (= Emax - prec + 1)"""
    return int(self.Emax - self.prec + 1)

def create_decimal(self, num='0'):
    """Creates a new Decimal instance but using self as context.

    This method implements the to-number operation of the
    IBM Decimal specification."""
    if isinstance(num, str) and (num != num.strip() or '_' in num):
        return self._raise_error(ConversionSyntax, 'trailing or leading whitespace and underscores are not permitted.')
    d = Decimal(num, context=self)
    if d._isnan() and len(d._int) > self.prec - self.clamp:
        return self._raise_error(ConversionSyntax, 'diagnostic info too long in NaN')
    return d._fix(self)

def canonical(self, a):
    """Returns the same Decimal object.

    As we do not have different encodings for the same number, the
    received object already is in its canonical form.

    >>> ExtendedContext.canonical(Decimal('2.50'))
    Decimal('2.50')"""
    if not isinstance(a, Decimal):
        raise TypeError('canonical requires a Decimal as an argument.')
    return a.canonical()

def compare_total_mag(self, a, b):
    """Compares two operands using their abstract representation ignoring sign.

    Like compare_total, but with operand's sign ignored and assumed to be 0."""
    a = _convert_other(a, raiseit=True)
    return a.compare_total_mag(b)

def radix(self):
    """Just returns 10, as this is Decimal, :)

    >>> ExtendedContext.radix()
    Decimal('10')"""
    return Decimal(10)

def __init__(self, value=None):
    if value is None:
        self.sign = None
        self.int = 0
        self.exp = None
    elif isinstance(value, Decimal):
        self.sign = value._sign
        self.int = int(value._int)
        self.exp = value._exp
    else:
        self.sign = value[0]
        self.int = value[1]
        self.exp = value[2]

def getdigits(self, p):
    """Given an integer p >= 0, return floor(10**p)*log(10).

    For example, self.getdigits(3) returns 2302."""
    if p < 0:
        raise ValueError('p should be nonnegative')
    if p >= len(self.digits):
        extra = 3
        while True:
            M = 10 ** (p + extra + 2)
            digits = str(_div_nearest(_ilog(10 * M, M), 100))
            if digits[-extra:] != '0' * extra:
                break
            extra += 3
        self.digits = digits.rstrip('0')[:-1]
    return int(self.digits[:p + 1])

def _unsupported(self, name):
    """Internal: raise an OSError exception for unsupported operations."""
    raise UnsupportedOperation('%s.%s() not supported' % (self.__class__.__name__, name))

def tell(self):
    """Return an int indicating the current stream position."""
    return self.seek(0, 1)

def close(self):
    """Flush and close the IO object.

    This method has no effect if the file is already closed."""
    if not self.__closed:
        try:
            self.flush()
        finally:
            self.__closed = True

def __del__(self):
    """Destructor.  Calls close()."""
    try:
        closed = self.closed
    except AttributeError:
        return
    if closed:
        return
    if _IOBASE_EMITS_UNRAISABLE:
        self.close()
    else:
        try:
            self.close()
        except:
            pass

def _checkSeekable(self, msg=None):
    """Internal: raise UnsupportedOperation if file is not seekable
    """
    if not self.seekable():
        raise UnsupportedOperation('File or stream is not seekable.' if msg is None else msg)

def _checkReadable(self, msg=None):
    """Internal: raise UnsupportedOperation if file is not readable
    """
    if not self.readable():
        raise UnsupportedOperation('File or stream is not readable.' if msg is None else msg)

def _checkWritable(self, msg=None):
    """Internal: raise UnsupportedOperation if file is not writable
    """
    if not self.writable():
        raise UnsupportedOperation('File or stream is not writable.' if msg is None else msg)

@property
def closed(self):
    """closed: bool.  True iff the file has been closed.

    For backwards compatibility, this is a property, not a predicate."""
    return self.__closed

def _checkClosed(self, msg=None):
    """Internal: raise a ValueError if file is closed
    """
    if self.closed:
        raise ValueError('I/O operation on closed file.' if msg is None else msg)

def __exit__(self, *args):
    """Context management protocol.  Calls close()"""
    self.close()

def readline(self, size=-1):
    """Read and return a line of bytes from the stream.

    If size is specified, at most size bytes will be read.
    Size should be an int.

    The line terminator is always b'\\n' for binary files; for text
    files, the newlines argument to open can be used to select the line
    terminator(s) recognized."""
    if hasattr(self, 'peek'):
        def nreadahead():
            readahead = self.peek(1)
            if not readahead:
                return 1
            n = readahead.find(b'\n') + 1 or len(readahead)
            if size >= 0:
                n = min(n, size)
            return n
    else:
        def nreadahead():
            return 1
    if size is None:
        size = -1
    else:
        try:
            size_index = size.__index__
        except AttributeError:
            raise TypeError(f'{size!r} is not an integer')
        else:
            size = size_index()
    res = bytearray()
    while size < 0 or len(res) < size:
        b = self.read(nreadahead())
        if not b:
            break
        res += b
        if res.endswith(b'\n'):
            break
    return bytes(res)

def __iter__(self):
    self._checkClosed()
    return self

def __next__(self):
    line = self.readline()
    if not line:
        raise StopIteration
    return line

def readlines(self, hint=None):
    """Return a list of lines from the stream.

    hint can be specified to control the number of lines read: no more
    lines will be read if the total size (in bytes/characters) of all
    lines so far exceeds hint."""
    if hint is None or hint <= 0:
        return list(self)
    n = 0
    lines = []
    for line in self:
        lines.append(line)
        n += len(line)
        if n >= hint:
            break
    return lines

def read(self, size=-1):
    """Read and return up to size bytes, where size is an int.

    Returns an empty bytes object on EOF, or None if the object is
    set not to block and has no data to read."""
    if size is None:
        size = -1
    if size < 0:
        return self.readall()
    b = bytearray(size.__index__())
    n = self.readinto(b)
    if n is None:
        return None
    del b[n:]
    return bytes(b)

def readall(self):
    """Read until EOF, using multiple read() call."""
    res = bytearray()
    while (data := self.read(DEFAULT_BUFFER_SIZE)):
        res += data
    if res:
        return bytes(res)
    else:
        return data

def readinto1(self, b):
    """Read bytes into buffer *b*, using at most one system call

    Returns an int representing the number of bytes read (0 for EOF).

    Raises BlockingIOError if the underlying raw stream has no
    data at the moment."""
    return self._readinto(b, read1=True)

def _readinto(self, b, read1):
    if not isinstance(b, memoryview):
        b = memoryview(b)
    b = b.cast('B')
    if read1:
        data = self.read1(len(b))
    else:
        data = self.read(len(b))
    n = len(data)
    b[:n] = data
    return n

def seek(self, pos, whence=0):
    new_position = self.raw.seek(pos, whence)
    if new_position < 0:
        raise OSError('seek() returned an invalid position')
    return new_position

def tell(self):
    pos = self.raw.tell()
    if pos < 0:
        raise OSError('tell() returned an invalid position')
    return pos

def truncate(self, pos=None):
    self._checkClosed()
    self._checkWritable()
    self.flush()
    if pos is None:
        pos = self.tell()
    return self.raw.truncate(pos)

def flush(self):
    if self.closed:
        raise ValueError('flush on closed file')
    self.raw.flush()

def close(self):
    if self.raw is not None and (not self.closed):
        try:
            self.flush()
        finally:
            self.raw.close()

@property
def raw(self):
    return self._raw

@property
def closed(self):
    return self.raw.closed

@property
def name(self):
    return self.raw.name

@property
def mode(self):
    return self.raw.mode

def __repr__(self):
    modname = self.__class__.__module__
    clsname = self.__class__.__qualname__
    try:
        name = self.name
    except AttributeError:
        return '<{}.{}>'.format(modname, clsname)
    else:
        return '<{}.{} name={!r}>'.format(modname, clsname, name)

def __init__(self, initial_bytes=None):
    buf = bytearray()
    if initial_bytes is not None:
        buf += initial_bytes
    self._buffer = buf
    self._pos = 0

def __getstate__(self):
    if self.closed:
        raise ValueError('__getstate__ on closed file')
    return self.__dict__.copy()

def getvalue(self):
    """Return the bytes value (contents) of the buffer
    """
    if self.closed:
        raise ValueError('getvalue on closed file')
    return bytes(self._buffer)

def getbuffer(self):
    """Return a readable and writable view of the buffer.
    """
    if self.closed:
        raise ValueError('getbuffer on closed file')
    return memoryview(self._buffer)

def close(self):
    if self._buffer is not None:
        self._buffer.clear()
    super().close()

def read(self, size=-1):
    if self.closed:
        raise ValueError('read from closed file')
    if size is None:
        size = -1
    else:
        try:
            size_index = size.__index__
        except AttributeError:
            raise TypeError(f'{size!r} is not an integer')
        else:
            size = size_index()
    if size < 0:
        size = len(self._buffer)
    if len(self._buffer) <= self._pos:
        return b''
    newpos = min(len(self._buffer), self._pos + size)
    b = self._buffer[self._pos:newpos]
    self._pos = newpos
    return bytes(b)

def read1(self, size=-1):
    """This is the same as read.
    """
    return self.read(size)

def write(self, b):
    if self.closed:
        raise ValueError('write to closed file')
    if isinstance(b, str):
        raise TypeError("can't write str to binary stream")
    with memoryview(b) as view:
        n = view.nbytes
    if n == 0:
        return 0
    pos = self._pos
    if pos > len(self._buffer):
        padding = b'\x00' * (pos - len(self._buffer))
        self._buffer += padding
    self._buffer[pos:pos + n] = b
    self._pos += n
    return n

def seek(self, pos, whence=0):
    if self.closed:
        raise ValueError('seek on closed file')
    try:
        pos_index = pos.__index__
    except AttributeError:
        raise TypeError(f'{pos!r} is not an integer')
    else:
        pos = pos_index()
    if whence == 0:
        if pos < 0:
            raise ValueError('negative seek position %r' % (pos,))
        self._pos = pos
    elif whence == 1:
        self._pos = max(0, self._pos + pos)
    elif whence == 2:
        self._pos = max(0, len(self._buffer) + pos)
    else:
        raise ValueError('unsupported whence value')
    return self._pos

def tell(self):
    if self.closed:
        raise ValueError('tell on closed file')
    return self._pos

def truncate(self, pos=None):
    if self.closed:
        raise ValueError('truncate on closed file')
    if pos is None:
        pos = self._pos
    else:
        try:
            pos_index = pos.__index__
        except AttributeError:
            raise TypeError(f'{pos!r} is not an integer')
        else:
            pos = pos_index()
        if pos < 0:
            raise ValueError('negative truncate position %r' % (pos,))
    del self._buffer[pos:]
    return pos

def readable(self):
    if self.closed:
        raise ValueError('I/O operation on closed file.')
    return True

def writable(self):
    if self.closed:
        raise ValueError('I/O operation on closed file.')
    return True

def seekable(self):
    if self.closed:
        raise ValueError('I/O operation on closed file.')
    return True

def _reset_read_buf(self):
    self._read_buf = b''
    self._read_pos = 0

def read(self, size=None):
    """Read size bytes.

    Returns exactly size bytes of data unless the underlying raw IO
    stream reaches EOF or if the call would block in non-blocking
    mode. If size is negative, read until EOF or until read() would
    block."""
    if size is not None and size < -1:
        raise ValueError('invalid number of bytes to read')
    with self._read_lock:
        return self._read_unlocked(size)

def _peek_unlocked(self, n=0):
    want = min(n, self.buffer_size)
    have = len(self._read_buf) - self._read_pos
    if have < want or have <= 0:
        to_read = self.buffer_size - have
        current = self.raw.read(to_read)
        if current:
            self._read_buf = self._read_buf[self._read_pos:] + current
            self._read_pos = 0
    return self._read_buf[self._read_pos:]

def _readinto(self, buf, read1):
    """Read data into *buf* with at most one system call."""
    self._checkClosed('readinto of closed file')
    if not isinstance(buf, memoryview):
        buf = memoryview(buf)
    if buf.nbytes == 0:
        return 0
    buf = buf.cast('B')
    written = 0
    with self._read_lock:
        while written < len(buf):
            avail = min(len(self._read_buf) - self._read_pos, len(buf))
            if avail:
                buf[written:written + avail] = self._read_buf[self._read_pos:self._read_pos + avail]
                self._read_pos += avail
                written += avail
                if written == len(buf):
                    break
            if len(buf) - written > self.buffer_size:
                n = self.raw.readinto(buf[written:])
                if not n:
                    break
                written += n
            elif not (read1 and written):
                if not self._peek_unlocked(1):
                    break
            if read1 and written:
                break
    return written

def seek(self, pos, whence=0):
    if whence not in valid_seek_flags:
        raise ValueError('invalid whence value')
    self._checkClosed('seek of closed file')
    with self._read_lock:
        if whence == 1:
            pos -= len(self._read_buf) - self._read_pos
        pos = _BufferedIOMixin.seek(self, pos, whence)
        self._reset_read_buf()
        return pos

def __init__(self, raw, buffer_size=DEFAULT_BUFFER_SIZE):
    if not raw.writable():
        raise OSError('"raw" argument must be writable.')
    _BufferedIOMixin.__init__(self, raw)
    if buffer_size <= 0:
        raise ValueError('invalid buffer size')
    self.buffer_size = buffer_size
    self._write_buf = bytearray()
    self._write_lock = Lock()

def write(self, b):
    if isinstance(b, str):
        raise TypeError("can't write str to binary stream")
    with self._write_lock:
        if self.closed:
            raise ValueError('write to closed file')
        if len(self._write_buf) > self.buffer_size:
            self._flush_unlocked()
        before = len(self._write_buf)
        self._write_buf.extend(b)
        written = len(self._write_buf) - before
        if len(self._write_buf) > self.buffer_size:
            try:
                self._flush_unlocked()
            except BlockingIOError as e:
                if len(self._write_buf) > self.buffer_size:
                    overage = len(self._write_buf) - self.buffer_size
                    written -= overage
                    self._write_buf = self._write_buf[:self.buffer_size]
                    raise BlockingIOError(e.errno, e.strerror, written)
        return written

def truncate(self, pos=None):
    with self._write_lock:
        self._flush_unlocked()
        if pos is None:
            pos = self.raw.tell()
        return self.raw.truncate(pos)

def flush(self):
    with self._write_lock:
        self._flush_unlocked()

def _flush_unlocked(self):
    if self.closed:
        raise ValueError('flush on closed file')
    while self._write_buf:
        try:
            n = self.raw.write(self._write_buf)
        except BlockingIOError:
            raise RuntimeError('self.raw should implement RawIOBase: it should not raise BlockingIOError')
        if n is None:
            raise BlockingIOError(errno.EAGAIN, 'write could not complete without blocking', 0)
        if n > len(self._write_buf) or n < 0:
            raise OSError('write() returned incorrect number of bytes')
        del self._write_buf[:n]

def seek(self, pos, whence=0):
    if whence not in valid_seek_flags:
        raise ValueError('invalid whence value')
    with self._write_lock:
        self._flush_unlocked()
        return _BufferedIOMixin.seek(self, pos, whence)

def close(self):
    with self._write_lock:
        if self.raw is None or self.closed:
            return
    try:
        self.flush()
    finally:
        with self._write_lock:
            self.raw.close()

def __init__(self, reader, writer, buffer_size=DEFAULT_BUFFER_SIZE):
    """Constructor.

    The arguments are two RawIO instances."""
    if not reader.readable():
        raise OSError('"reader" argument must be readable.')
    if not writer.writable():
        raise OSError('"writer" argument must be writable.')
    self.reader = BufferedReader(reader, buffer_size)
    self.writer = BufferedWriter(writer, buffer_size)

def read(self, size=-1):
    if size is None:
        size = -1
    return self.reader.read(size)

def close(self):
    try:
        self.writer.close()
    finally:
        self.reader.close()

@property
def closed(self):
    return self.writer.closed

def seek(self, pos, whence=0):
    if whence not in valid_seek_flags:
        raise ValueError('invalid whence value')
    self.flush()
    if self._read_buf:
        with self._read_lock:
            self.raw.seek(self._read_pos - len(self._read_buf), 1)
