def _strptime_time(data_string, format='%a %b %d %H:%M:%S %Y'):
    """Return a time struct based on the input string and the
    format string."""
    tt = _strptime(data_string, format)[0]
    return time.struct_time(tt[:time._STRUCT_TM_ITEMS])

def _strptime_datetime(cls, data_string, format='%a %b %d %H:%M:%S %Y'):
    """Return a class cls instance based on the input string and the
    format string."""
    tt, fraction, gmtoff_fraction = _strptime(data_string, format)
    tzname, gmtoff = tt[-2:]
    args = tt[:6] + (fraction,)
    if gmtoff is not None:
        tzdelta = datetime_timedelta(seconds=gmtoff, microseconds=gmtoff_fraction)
        if tzname:
            tz = datetime_timezone(tzdelta, tzname)
        else:
            tz = datetime_timezone(tzdelta)
        args += (tz,)
    return cls(*args)

def __calc_am_pm(self):
    am_pm = []
    for hour in (1, 22):
        time_tuple = time.struct_time((1999, 3, 17, hour, 44, 55, 2, 76, 0))
        am_pm.append(time.strftime('%p', time_tuple).lower().strip())
    self.am_pm = am_pm

def __find_weekday_format(self, directive):
    """Find the day of the week format appropriate for the current locale.

    Similar to __find_month_format()."""
    full_indices = abbr_indices = None
    for wd in range(7):
        time_tuple = time.struct_time((1999, 3, 17, 22, 44, 55, wd, 76, 0))
        datetime = time.strftime(directive, time_tuple).lower()
        indices = set(_findall(datetime, self.f_weekday[wd]))
        if full_indices is None:
            full_indices = indices
        else:
            full_indices &= indices
        if self.f_weekday[wd] != self.a_weekday[wd]:
            indices = set(_findall(datetime, self.a_weekday[wd]))
        if abbr_indices is None:
            abbr_indices = indices
        else:
            abbr_indices &= indices
        if not full_indices and (not abbr_indices):
            return (None, None)
    if full_indices:
        return (self.f_weekday, '%A')
    if abbr_indices:
        return (self.a_weekday, '%a')
    return (None, None)

def __calc_timezone(self):
    try:
        time.tzset()
    except AttributeError:
        pass
    self.tzname = time.tzname
    self.daylight = time.daylight
    no_saving = frozenset({'utc', 'gmt', self.tzname[0].lower()})
    if self.daylight:
        has_saving = frozenset({self.tzname[1].lower()})
    else:
        has_saving = frozenset()
    self.timezone = (no_saving, has_saving)

def compile(self, format):
    """Return a compiled re object for the format string."""
    return re_compile(self.pattern(format), IGNORECASE)

@contextmanager
def _patch(self):
    impl = object.__getattribute__(self, '_local__impl')
    try:
        dct = impl.get_dict()
    except KeyError:
        dct = impl.create_dict()
        args, kw = impl.localargs
        self.__init__(*args, **kw)
    with impl.locallock:
        object.__setattr__(self, '__dict__', dct)
        yield

def __init__(self):
    self.key = '_threading_local._localimpl.' + str(id(self))
    self.dicts = {}

def create_dict(self):
    """Create a new dict for the current thread, and return it."""
    localdict = {}
    key = self.key
    thread = current_thread()
    idt = id(thread)
    def local_deleted(_, key=key):
        thread = wrthread()
        if thread is not None:
            del thread.__dict__[key]
    def thread_deleted(_, idt=idt):
        local = wrlocal()
        if local is not None:
            dct = local.dicts.pop(idt)
    wrlocal = ref(self, local_deleted)
    wrthread = ref(thread, thread_deleted)
    thread.__dict__[key] = wrlocal
    self.dicts[idt] = (wrthread, localdict)
    return localdict

def __getattribute__(self, name):
    with _patch(self):
        return object.__getattribute__(self, name)

def __delattr__(self, name):
    if name == '__dict__':
        raise AttributeError("%r object attribute '__dict__' is read-only" % self.__class__.__name__)
    with _patch(self):
        return object.__delattr__(self, name)

def thread_deleted(_, idt=idt):
    local = wrlocal()
    if local is not None:
        dct = local.dicts.pop(idt)

def __enter__(self):
    w = self.weakcontainer()
    if w is not None:
        w._iterating.add(self)
    return self

def __init__(self, data=None):
    self.data = set()
    def _remove(item, selfref=ref(self)):
        self = selfref()
        if self is not None:
            if self._iterating:
                self._pending_removals.append(item)
            else:
                self.data.discard(item)
    self._remove = _remove
    self._pending_removals = []
    self._iterating = set()
    if data is not None:
        self.update(data)

def _commit_removals(self):
    pop = self._pending_removals.pop
    discard = self.data.discard
    while True:
        try:
            item = pop()
        except IndexError:
            return
        discard(item)

def __iter__(self):
    with _IterationGuard(self):
        for itemref in self.data:
            item = itemref()
            if item is not None:
                yield item

def __contains__(self, item):
    try:
        wr = ref(item)
    except TypeError:
        return False
    return wr in self.data

def add(self, item):
    if self._pending_removals:
        self._commit_removals()
    self.data.add(ref(item, self._remove))

def clear(self):
    if self._pending_removals:
        self._commit_removals()
    self.data.clear()

def pop(self):
    if self._pending_removals:
        self._commit_removals()
    while True:
        try:
            itemref = self.data.pop()
        except KeyError:
            raise KeyError('pop from empty WeakSet') from None
        item = itemref()
        if item is not None:
            return item

def remove(self, item):
    if self._pending_removals:
        self._commit_removals()
    self.data.remove(ref(item))

def discard(self, item):
    if self._pending_removals:
        self._commit_removals()
    self.data.discard(ref(item))

def update(self, other):
    if self._pending_removals:
        self._commit_removals()
    for element in other:
        self.add(element)

def __ior__(self, other):
    self.update(other)
    return self

def __isub__(self, other):
    if self._pending_removals:
        self._commit_removals()
    if self is other:
        self.data.clear()
    else:
        self.data.difference_update((ref(item) for item in other))
    return self

def __iand__(self, other):
    if self._pending_removals:
        self._commit_removals()
    self.data.intersection_update((ref(item) for item in other))
    return self

def __eq__(self, other):
    if not isinstance(other, self.__class__):
        return NotImplemented
    return self.data == set(map(ref, other))

def __ixor__(self, other):
    if self._pending_removals:
        self._commit_removals()
    if self is other:
        self.data.clear()
    else:
        self.data.symmetric_difference_update((ref(item, self._remove) for item in other))
    return self

def _remove(item, selfref=ref(self)):
    self = selfref()
    if self is not None:
        if self._iterating:
            self._pending_removals.append(item)
        else:
            self.data.discard(item)

