    return audioop.byteswap(data, 2)

def _ensure_header_written(self, datasize):
    if not self._nframeswritten:
        if self._comptype in (b'ULAW', b'ulaw', b'ALAW', b'alaw', b'G722', b'sowt', b'SOWT'):
            if not self._sampwidth:
                self._sampwidth = 2
            if self._sampwidth != 2:
                raise Error('sample width must be 2 when compressing with ulaw/ULAW, alaw/ALAW, sowt/SOWT or G7.22 (ADPCM)')
        if not self._nchannels:
            raise Error('# channels not specified')
        if not self._sampwidth:
            raise Error('sample width not specified')
        if not self._framerate:
            raise Error('sampling rate not specified')
        self._write_header(datasize)

def _init_compression(self):
    if self._comptype == b'G722':
        self._convert = self._lin2adpcm
    elif self._comptype in (b'ulaw', b'ULAW'):
        self._convert = self._lin2ulaw
    elif self._comptype in (b'alaw', b'ALAW'):
        self._convert = self._lin2alaw
    elif self._comptype in (b'sowt', b'SOWT'):
        self._convert = self._lin2sowt

def _write_form_length(self, datalength):
    if self._aifc:
        commlength = 18 + 5 + len(self._compname)
        if commlength & 1:
            commlength = commlength + 1
        verslength = 12
    else:
        commlength = 18
        verslength = 0
    _write_ulong(self._file, 4 + verslength + self._marklength + 8 + commlength + 16 + datalength)
    return commlength

def _copy_items(items):
    if items is None:
        return []
    if type(items) is list:
        return items[:]
    import copy
    return copy.copy(items)

def _get_action_name(argument):
    if argument is None:
        return None
    elif argument.option_strings:
        return '/'.join(argument.option_strings)
    elif argument.metavar not in (None, SUPPRESS):
        metavar = argument.metavar
        if not isinstance(metavar, tuple):
            return metavar
        if argument.nargs == ZERO_OR_MORE and len(metavar) == 2:
            return '%s[, %s]' % metavar
        elif argument.nargs == ONE_OR_MORE:
            return '%s[, %s]' % metavar
        else:
            return ', '.join(metavar)
    elif argument.dest not in (None, SUPPRESS):
        return argument.dest
    elif argument.choices:
        return '{%s}' % ','.join(map(str, argument.choices))
    else:
        return None

def __repr__(self):
    type_name = type(self).__name__
    arg_strings = []
    star_args = {}
    for arg in self._get_args():
        arg_strings.append(repr(arg))
    for name, value in self._get_kwargs():
        if name.isidentifier():
            arg_strings.append('%s=%r' % (name, value))
        else:
            star_args[name] = value
    if star_args:
        arg_strings.append('**%s' % repr(star_args))
    return '%s(%s)' % (type_name, ', '.join(arg_strings))

def end_section(self):
    self._current_section = self._current_section.parent
    self._dedent()

def add_text(self, text):
    if text is not SUPPRESS and text is not None:
        self._add_item(self._format_text, [text])

def add_usage(self, usage, actions, groups, prefix=None):
    if usage is not SUPPRESS:
        args = (usage, actions, groups, prefix)
        self._add_item(self._format_usage, args)

def add_argument(self, action):
    if action.help is not SUPPRESS:
        get_invocation = self._format_action_invocation
        invocation_lengths = [len(get_invocation(action)) + self._current_indent]
        for subaction in self._iter_indented_subactions(action):
            invocation_lengths.append(len(get_invocation(subaction)) + self._current_indent)
        action_length = max(invocation_lengths)
        self._action_max_length = max(self._action_max_length, action_length)
        self._add_item(self._format_action, [action])

def add_arguments(self, actions):
    for action in actions:
        self.add_argument(action)

def format_help(self):
    help = self._root_section.format_help()
    if help:
        help = self._long_break_matcher.sub('\n\n', help)
        help = help.strip('\n') + '\n'
    return help

def _format_text(self, text):
    if '%(prog)' in text:
        text = text % dict(prog=self._prog)
    text_width = max(self._width - self._current_indent, 11)
    indent = ' ' * self._current_indent
    return self._fill_text(text, text_width, indent) + '\n\n'

def _format_action(self, action):
    help_position = min(self._action_max_length + 2, self._max_help_position)
    help_width = max(self._width - help_position, 11)
    action_width = help_position - self._current_indent - 2
    action_header = self._format_action_invocation(action)
    if not action.help:
        tup = (self._current_indent, '', action_header)
        action_header = '%*s%s\n' % tup
    elif len(action_header) <= action_width:
        tup = (self._current_indent, '', action_width, action_header)
        action_header = '%*s%-*s  ' % tup
        indent_first = 0
    else:
        tup = (self._current_indent, '', action_header)
        action_header = '%*s%s\n' % tup
        indent_first = help_position
    parts = [action_header]
    if action.help and action.help.strip():
        help_text = self._expand_help(action)
        if help_text:
            help_lines = self._split_lines(help_text, help_width)
            parts.append('%*s%s\n' % (indent_first, '', help_lines[0]))
            for line in help_lines[1:]:
                parts.append('%*s%s\n' % (help_position, '', line))
    elif not action_header.endswith('\n'):
        parts.append('\n')
    for subaction in self._iter_indented_subactions(action):
        parts.append(self._format_action(subaction))
    return self._join_parts(parts)

def _format_action_invocation(self, action):
    if not action.option_strings:
        default = self._get_default_metavar_for_positional(action)
        return ' '.join(self._metavar_formatter(action, default)(1))
    else:
        parts = []
        if action.nargs == 0:
            parts.extend(action.option_strings)
        else:
            default = self._get_default_metavar_for_optional(action)
            args_string = self._format_args(action, default)
            for option_string in action.option_strings:
                parts.append('%s %s' % (option_string, args_string))
        return ', '.join(parts)

def _metavar_formatter(self, action, default_metavar):
    if action.metavar is not None:
        result = action.metavar
    elif action.choices is not None:
        result = '{%s}' % ','.join(map(str, action.choices))
    else:
        result = default_metavar
    def format(tuple_size):
        if isinstance(result, tuple):
            return result
        else:
            return (result,) * tuple_size
    return format

def _format_args(self, action, default_metavar):
    get_metavar = self._metavar_formatter(action, default_metavar)
    if action.nargs is None:
        result = '%s' % get_metavar(1)
    elif action.nargs == OPTIONAL:
        result = '[%s]' % get_metavar(1)
    elif action.nargs == ZERO_OR_MORE:
        metavar = get_metavar(1)
        if len(metavar) == 2:
            result = '[%s [%s ...]]' % metavar
        else:
            result = '[%s ...]' % metavar
    elif action.nargs == ONE_OR_MORE:
        result = '%s [%s ...]' % get_metavar(2)
    elif action.nargs == REMAINDER:
        result = '...'
    elif action.nargs == PARSER:
        result = '%s ...' % get_metavar(1)
    elif action.nargs == SUPPRESS:
        result = ''
    else:
        try:
            formats = ['%s' for _ in range(action.nargs)]
        except TypeError:
            raise ValueError('invalid nargs value') from None
        result = ' '.join(formats) % get_metavar(action.nargs)
    return result

def _iter_indented_subactions(self, action):
    try:
        get_subactions = action._get_subactions
    except AttributeError:
        pass
    else:
        self._indent()
        yield from get_subactions()
        self._dedent()

def _split_lines(self, text, width):
    text = self._whitespace_matcher.sub(' ', text).strip()
    import textwrap
    return textwrap.wrap(text, width)

def _fill_text(self, text, width, indent):
    text = self._whitespace_matcher.sub(' ', text).strip()
    import textwrap
    return textwrap.fill(text, width, initial_indent=indent, subsequent_indent=indent)

def _get_help_string(self, action):
    """Add the default value to the option help message.

    ArgumentDefaultsHelpFormatter and BooleanOptionalAction when it isn't
    already present. This code will do that, detecting cornercases to
    prevent duplicates or cases where it wouldn't make sense to the end
    user."""
    help = action.help
    if help is None:
        help = ''
    if '%(default)' not in help:
        if action.default is not SUPPRESS:
            defaulting_nargs = [OPTIONAL, ZERO_OR_MORE]
            if action.option_strings or action.nargs in defaulting_nargs:
                help += _(' (default: %(default)s)')
    return help

def __init__(self, argument, message):
    self.argument_name = _get_action_name(argument)
    self.message = message

def __str__(self):
    if self.argument_name is None:
        format = '%(message)s'
    else:
        format = _('argument %(argument_name)s: %(message)s')
    return format % dict(message=self.message, argument_name=self.argument_name)

def _get_kwargs(self):
    names = ['option_strings', 'dest', 'nargs', 'const', 'default', 'type', 'choices', 'required', 'help', 'metavar']
    return [(name, getattr(self, name)) for name in names]

def __init__(self, option_strings, dest, default=None, type=_deprecated_default, choices=_deprecated_default, required=False, help=None, metavar=_deprecated_default):
    _option_strings = []
    for option_string in option_strings:
        _option_strings.append(option_string)
        if option_string.startswith('--'):
            option_string = '--no-' + option_string[2:]
            _option_strings.append(option_string)
    for field_name in ('type', 'choices', 'metavar'):
        if locals()[field_name] is not _deprecated_default:
            warnings._deprecated(field_name, '{name!r} is deprecated as of Python 3.12 and will be removed in Python {remove}.', remove=(3, 14))
    if type is _deprecated_default:
        type = None
    if choices is _deprecated_default:
        choices = None
    if metavar is _deprecated_default:
        metavar = None
    super().__init__(option_strings=_option_strings, dest=dest, nargs=0, default=default, type=type, choices=choices, required=required, help=help, metavar=metavar)

def __call__(self, parser, namespace, values, option_string=None):
    if option_string in self.option_strings:
        setattr(namespace, self.dest, not option_string.startswith('--no-'))

def __init__(self, option_strings, dest, nargs=None, const=None, default=None, type=None, choices=None, required=False, help=None, metavar=None):
    if nargs == 0:
        raise ValueError('nargs for store actions must be != 0; if you have nothing to store, actions such as store true or store const may be more appropriate')
    if const is not None and nargs != OPTIONAL:
        raise ValueError('nargs must be %r to supply const' % OPTIONAL)
    super(_StoreAction, self).__init__(option_strings=option_strings, dest=dest, nargs=nargs, const=const, default=default, type=type, choices=choices, required=required, help=help, metavar=metavar)

def __init__(self, option_strings, dest, nargs=None, const=None, default=None, type=None, choices=None, required=False, help=None, metavar=None):
    if nargs == 0:
        raise ValueError('nargs for append actions must be != 0; if arg strings are not supplying the value to append, the append const action may be more appropriate')
    if const is not None and nargs != OPTIONAL:
        raise ValueError('nargs must be %r to supply const' % OPTIONAL)
    super(_AppendAction, self).__init__(option_strings=option_strings, dest=dest, nargs=nargs, const=const, default=default, type=type, choices=choices, required=required, help=help, metavar=metavar)

def __call__(self, parser, namespace, values, option_string=None):
    count = getattr(namespace, self.dest, None)
    if count is None:
        count = 0
    setattr(namespace, self.dest, count + 1)

def __call__(self, parser, namespace, values, option_string=None):
    parser.print_help()
    parser.exit()

def __init__(self, option_strings, version=None, dest=SUPPRESS, default=SUPPRESS, help=None):
    if help is None:
        help = _("show program's version number and exit")
    super(_VersionAction, self).__init__(option_strings=option_strings, dest=dest, default=default, nargs=0, help=help)
    self.version = version

def __init__(self, option_strings, prog, parser_class, dest=SUPPRESS, required=False, help=None, metavar=None):
    self._prog_prefix = prog
    self._parser_class = parser_class
    self._name_parser_map = {}
    self._choices_actions = []
    super(_SubParsersAction, self).__init__(option_strings=option_strings, dest=dest, nargs=PARSER, choices=self._name_parser_map, required=required, help=help, metavar=metavar)

def add_parser(self, name, **kwargs):
    if kwargs.get('prog') is None:
        kwargs['prog'] = '%s %s' % (self._prog_prefix, name)
    aliases = kwargs.pop('aliases', ())
    if name in self._name_parser_map:
        raise ArgumentError(self, _('conflicting subparser: %s') % name)
    for alias in aliases:
        if alias in self._name_parser_map:
            raise ArgumentError(self, _('conflicting subparser alias: %s') % alias)
    if 'help' in kwargs:
        help = kwargs.pop('help')
        choice_action = self._ChoicesPseudoAction(name, aliases, help)
        self._choices_actions.append(choice_action)
    parser = self._parser_class(**kwargs)
    self._name_parser_map[name] = parser
    for alias in aliases:
        self._name_parser_map[alias] = parser
    return parser

def __call__(self, parser, namespace, values, option_string=None):
    parser_name = values[0]
    arg_strings = values[1:]
    if self.dest is not SUPPRESS:
        setattr(namespace, self.dest, parser_name)
    try:
        parser = self._name_parser_map[parser_name]
    except KeyError:
        args = {'parser_name': parser_name, 'choices': ', '.join(self._name_parser_map)}
        msg = _('unknown parser %(parser_name)r (choices: %(choices)s)') % args
        raise ArgumentError(self, msg)
    subnamespace, arg_strings = parser.parse_known_args(arg_strings, None)
    for key, value in vars(subnamespace).items():
        setattr(namespace, key, value)
    if arg_strings:
        if not hasattr(namespace, _UNRECOGNIZED_ARGS_ATTR):
            setattr(namespace, _UNRECOGNIZED_ARGS_ATTR, [])
        getattr(namespace, _UNRECOGNIZED_ARGS_ATTR).extend(arg_strings)

def __call__(self, string):
    if string == '-':
        if 'r' in self._mode:
            return _sys.stdin.buffer if 'b' in self._mode else _sys.stdin
        elif any((c in self._mode for c in 'wax')):
            return _sys.stdout.buffer if 'b' in self._mode else _sys.stdout
        else:
            msg = _('argument "-" with mode %r') % self._mode
            raise ValueError(msg)
    try:
        return open(string, self._mode, self._bufsize, self._encoding, self._errors)
    except OSError as e:
        args = {'filename': string, 'error': e}
        message = _("can't open '%(filename)s': %(error)s")
        raise ArgumentTypeError(message % args)

def __repr__(self):
    args = (self._mode, self._bufsize)
    kwargs = [('encoding', self._encoding), ('errors', self._errors)]
    args_str = ', '.join([repr(arg) for arg in args if arg != -1] + ['%s=%r' % (kw, arg) for kw, arg in kwargs if arg is not None])
    return '%s(%s)' % (type(self).__name__, args_str)

def __init__(self, **kwargs):
    for name in kwargs:
        setattr(self, name, kwargs[name])

def __eq__(self, other):
    if not isinstance(other, Namespace):
        return NotImplemented
    return vars(self) == vars(other)

def register(self, registry_name, value, object):
    registry = self._registries.setdefault(registry_name, {})
    registry[value] = object

def set_defaults(self, **kwargs):
    self._defaults.update(kwargs)
    for action in self._actions:
        if action.dest in kwargs:
            action.default = kwargs[action.dest]

def get_default(self, dest):
    for action in self._actions:
        if action.dest == dest and action.default is not None:
            return action.default
    return self._defaults.get(dest, None)

def add_argument(self, *args, **kwargs):
    """add_argument(dest, ..., name=value, ...)
    add_argument(option_string, option_string, ..., name=value, ...)"""
    chars = self.prefix_chars
    if not args or (len(args) == 1 and args[0][0] not in chars):
        if args and 'dest' in kwargs:
            raise ValueError('dest supplied twice for positional argument')
        kwargs = self._get_positional_kwargs(*args, **kwargs)
    else:
        kwargs = self._get_optional_kwargs(*args, **kwargs)
    if 'default' not in kwargs:
        dest = kwargs['dest']
        if dest in self._defaults:
            kwargs['default'] = self._defaults[dest]
        elif self.argument_default is not None:
            kwargs['default'] = self.argument_default
    action_class = self._pop_action_class(kwargs)
    if not callable(action_class):
        raise ValueError('unknown action "%s"' % (action_class,))
    action = action_class(**kwargs)
    type_func = self._registry_get('type', action.type, action.type)
    if not callable(type_func):
        raise ValueError('%r is not callable' % (type_func,))
    if type_func is FileType:
        raise ValueError('%r is a FileType class object, instance of it must be passed' % (type_func,))
    if hasattr(self, '_get_formatter'):
        try:
            self._get_formatter()._format_args(action, None)
        except TypeError:
            raise ValueError('length of metavar tuple does not match nargs')
    return self._add_action(action)

def _add_action(self, action):
    self._check_conflict(action)
    self._actions.append(action)
    action.container = self
    for option_string in action.option_strings:
        self._option_string_actions[option_string] = action
    for option_string in action.option_strings:
        if self._negative_number_matcher.match(option_string):
            if not self._has_negative_number_optionals:
                self._has_negative_number_optionals.append(True)
    return action

def _add_container_actions(self, container):
    title_group_map = {}
    for group in self._action_groups:
        if group.title in title_group_map:
            msg = _('cannot merge actions - two groups are named %r')
            raise ValueError(msg % group.title)
        title_group_map[group.title] = group
    group_map = {}
    for group in container._action_groups:
        if group.title not in title_group_map:
            title_group_map[group.title] = self.add_argument_group(title=group.title, description=group.description, conflict_handler=group.conflict_handler)
        for action in group._group_actions:
            group_map[action] = title_group_map[group.title]
    for group in container._mutually_exclusive_groups:
        if group._container is container:
            cont = self
        else:
            cont = title_group_map[group._container.title]
        mutex_group = cont.add_mutually_exclusive_group(required=group.required)
        for action in group._group_actions:
            group_map[action] = mutex_group
    for action in container._actions:
        group_map.get(action, self)._add_action(action)

def _get_positional_kwargs(self, dest, **kwargs):
    if 'required' in kwargs:
        msg = _("'required' is an invalid argument for positionals")
        raise TypeError(msg)
    nargs = kwargs.get('nargs')
    if nargs not in [OPTIONAL, ZERO_OR_MORE, REMAINDER, SUPPRESS, 0]:
        kwargs['required'] = True
    return dict(kwargs, dest=dest, option_strings=[])

def _get_optional_kwargs(self, *args, **kwargs):
    option_strings = []
    long_option_strings = []
    for option_string in args:
        if not option_string[0] in self.prefix_chars:
            args = {'option': option_string, 'prefix_chars': self.prefix_chars}
            msg = _('invalid option string %(option)r: must start with a character %(prefix_chars)r')
            raise ValueError(msg % args)
        option_strings.append(option_string)
        if len(option_string) > 1 and option_string[1] in self.prefix_chars:
            long_option_strings.append(option_string)
    dest = kwargs.pop('dest', None)
    if dest is None:
        if long_option_strings:
            dest_option_string = long_option_strings[0]
        else:
            dest_option_string = option_strings[0]
        dest = dest_option_string.lstrip(self.prefix_chars)
        if not dest:
            msg = _('dest= is required for options like %r')
            raise ValueError(msg % option_string)
        dest = dest.replace('-', '_')
    return dict(kwargs, dest=dest, option_strings=option_strings)

def _pop_action_class(self, kwargs, default=None):
    action = kwargs.pop('action', default)
    return self._registry_get('action', action, action)

def _get_handler(self):
    handler_func_name = '_handle_conflict_%s' % self.conflict_handler
    try:
        return getattr(self, handler_func_name)
    except AttributeError:
        msg = _('invalid conflict_resolution value: %r')
        raise ValueError(msg % self.conflict_handler)

def _check_conflict(self, action):
    confl_optionals = []
    for option_string in action.option_strings:
        if option_string in self._option_string_actions:
            confl_optional = self._option_string_actions[option_string]
            confl_optionals.append((option_string, confl_optional))
    if confl_optionals:
        conflict_handler = self._get_handler()
        conflict_handler(action, confl_optionals)

def _handle_conflict_resolve(self, action, conflicting_actions):
    for option_string, action in conflicting_actions:
        action.option_strings.remove(option_string)
        self._option_string_actions.pop(option_string, None)
        if not action.option_strings:
            action.container._remove_action(action)

def _remove_action(self, action):
    super(_ArgumentGroup, self)._remove_action(action)
    self._group_actions.remove(action)

def add_argument_group(self, *args, **kwargs):
    warnings.warn('Nesting argument groups is deprecated.', category=DeprecationWarning, stacklevel=2)
    return super().add_argument_group(*args, **kwargs)

def _remove_action(self, action):
    self._container._remove_action(action)
    self._group_actions.remove(action)

def add_mutually_exclusive_group(self, *args, **kwargs):
    warnings.warn('Nesting mutually exclusive groups is deprecated.', category=DeprecationWarning, stacklevel=2)
    return super().add_mutually_exclusive_group(*args, **kwargs)

def _get_kwargs(self):
    names = ['prog', 'usage', 'description', 'formatter_class', 'conflict_handler', 'add_help']
    return [(name, getattr(self, name)) for name in names]

def _add_action(self, action):
    if action.option_strings:
        self._optionals._add_action(action)
    else:
        self._positionals._add_action(action)
    return action

def parse_args(self, args=None, namespace=None):
    args, argv = self.parse_known_args(args, namespace)
    if argv:
        msg = _('unrecognized arguments: %s') % ' '.join(argv)
        if self.exit_on_error:
            self.error(msg)
        else:
            raise ArgumentError(None, msg)
    return args

def _parse_known_args2(self, args, namespace, intermixed):
    if args is None:
        args = _sys.argv[1:]
    else:
        args = list(args)
    if namespace is None:
        namespace = Namespace()
    for action in self._actions:
        if action.dest is not SUPPRESS:
            if not hasattr(namespace, action.dest):
                if action.default is not SUPPRESS:
                    setattr(namespace, action.dest, action.default)
    for dest in self._defaults:
        if not hasattr(namespace, dest):
            setattr(namespace, dest, self._defaults[dest])
    if self.exit_on_error:
        try:
            namespace, args = self._parse_known_args(args, namespace, intermixed)
        except ArgumentError as err:
            self.error(str(err))
    else:
        namespace, args = self._parse_known_args(args, namespace, intermixed)
    if hasattr(namespace, _UNRECOGNIZED_ARGS_ATTR):
        args.extend(getattr(namespace, _UNRECOGNIZED_ARGS_ATTR))
        delattr(namespace, _UNRECOGNIZED_ARGS_ATTR)
    return (namespace, args)

def _read_args_from_files(self, arg_strings):
    new_arg_strings = []
    for arg_string in arg_strings:
        if not arg_string or arg_string[0] not in self.fromfile_prefix_chars:
            new_arg_strings.append(arg_string)
        else:
            try:
                with open(arg_string[1:], encoding=_sys.getfilesystemencoding(), errors=_sys.getfilesystemencodeerrors()) as args_file:
                    arg_strings = []
                    for arg_line in args_file.read().splitlines():
                        for arg in self.convert_arg_line_to_args(arg_line):
                            arg_strings.append(arg)
                    arg_strings = self._read_args_from_files(arg_strings)
                    new_arg_strings.extend(arg_strings)
            except OSError as err:
                raise ArgumentError(None, str(err))
    return new_arg_strings

def _match_argument(self, action, arg_strings_pattern):
    nargs_pattern = self._get_nargs_pattern(action)
    match = _re.match(nargs_pattern, arg_strings_pattern)
    if match is None:
        nargs_errors = {None: _('expected one argument'), OPTIONAL: _('expected at most one argument'), ONE_OR_MORE: _('expected at least one argument')}
        msg = nargs_errors.get(action.nargs)
        if msg is None:
            msg = ngettext('expected %s argument', 'expected %s arguments', action.nargs) % action.nargs
        raise ArgumentError(action, msg)
    return len(match.group(1))

def _match_arguments_partial(self, actions, arg_strings_pattern):
    for i in range(len(actions), 0, -1):
        actions_slice = actions[:i]
        pattern = ''.join([self._get_nargs_pattern(action) for action in actions_slice])
        match = _re.match(pattern, arg_strings_pattern)
        if match is not None:
            result = [len(string) for string in match.groups()]
            if match.end() < len(arg_strings_pattern) and arg_strings_pattern[match.end()] == 'O':
                while result and (not result[-1]):
                    del result[-1]
            return result
    return []

def _get_option_tuples(self, option_string):
    result = []
    chars = self.prefix_chars
    if option_string[0] in chars and option_string[1] in chars:
        if self.allow_abbrev:
            option_prefix, sep, explicit_arg = option_string.partition('=')
            if not sep:
                sep = explicit_arg = None
            for option_string in self._option_string_actions:
                if option_string.startswith(option_prefix):
                    action = self._option_string_actions[option_string]
                    tup = (action, option_string, sep, explicit_arg)
                    result.append(tup)
    elif option_string[0] in chars and option_string[1] not in chars:
        option_prefix, sep, explicit_arg = option_string.partition('=')
        if not sep:
            sep = explicit_arg = None
        short_option_prefix = option_string[:2]
        short_explicit_arg = option_string[2:]
        for option_string in self._option_string_actions:
            if option_string == short_option_prefix:
                action = self._option_string_actions[option_string]
                tup = (action, option_string, '', short_explicit_arg)
                result.append(tup)
            elif self.allow_abbrev and option_string.startswith(option_prefix):
                action = self._option_string_actions[option_string]
                tup = (action, option_string, sep, explicit_arg)
                result.append(tup)
    else:
        raise ArgumentError(None, _('unexpected option string: %s') % option_string)
    return result

def _get_nargs_pattern(self, action):
    nargs = action.nargs
    option = action.option_strings
    if nargs is None:
        nargs_pattern = '([A])' if option else '(-*A-*)'
    elif nargs == OPTIONAL:
        nargs_pattern = '(A?)' if option else '(-*A?-*)'
    elif nargs == ZERO_OR_MORE:
        nargs_pattern = '(A*)' if option else '(-*[A-]*)'
    elif nargs == ONE_OR_MORE:
        nargs_pattern = '(A+)' if option else '(-*A[A-]*)'
    elif nargs == REMAINDER:
        nargs_pattern = '([AO]*)' if option else '(.*)'
    elif nargs == PARSER:
        nargs_pattern = '(A[AO]*)' if option else '(-*A[-AO]*)'
    elif nargs == SUPPRESS:
        nargs_pattern = '()' if option else '(-*)'
    else:
        nargs_pattern = '([AO]{%d})' % nargs if option else '((?:-*A){%d}-*)' % nargs
    return nargs_pattern

def parse_intermixed_args(self, args=None, namespace=None):
    args, argv = self.parse_known_intermixed_args(args, namespace)
    if argv:
        msg = _('unrecognized arguments: %s') % ' '.join(argv)
        if self.exit_on_error:
            self.error(msg)
        else:
            raise ArgumentError(None, msg)
    return args

def parse_known_intermixed_args(self, args=None, namespace=None):
    positionals = self._get_positional_actions()
    a = [action for action in positionals if action.nargs in [PARSER, REMAINDER]]
    if a:
        raise TypeError('parse_intermixed_args: positional arg with nargs=%s' % a[0].nargs)
    return self._parse_known_args2(args, namespace, intermixed=True)

def _get_values(self, action, arg_strings):
    if not arg_strings and action.nargs == OPTIONAL:
        if action.option_strings:
            value = action.const
        else:
            value = action.default
        if isinstance(value, str) and value is not SUPPRESS:
            value = self._get_value(action, value)
            self._check_value(action, value)
    elif not arg_strings and action.nargs == ZERO_OR_MORE and (not action.option_strings):
        if action.default is not None:
            value = action.default
            self._check_value(action, value)
        else:
            value = arg_strings
    elif len(arg_strings) == 1 and action.nargs in [None, OPTIONAL]:
        arg_string, = arg_strings
        value = self._get_value(action, arg_string)
        self._check_value(action, value)
    elif action.nargs == REMAINDER:
        value = [self._get_value(action, v) for v in arg_strings]
    elif action.nargs == PARSER:
        value = [self._get_value(action, v) for v in arg_strings]
        self._check_value(action, value[0])
    elif action.nargs == SUPPRESS:
        value = SUPPRESS
    else:
        value = [self._get_value(action, v) for v in arg_strings]
        for v in value:
            self._check_value(action, v)
    return value

def _get_value(self, action, arg_string):
    type_func = self._registry_get('type', action.type, action.type)
    if not callable(type_func):
        msg = _('%r is not callable')
        raise ArgumentError(action, msg % type_func)
    try:
        result = type_func(arg_string)
    except ArgumentTypeError as err:
        msg = str(err)
        raise ArgumentError(action, msg)
    except (TypeError, ValueError):
        name = getattr(action.type, '__name__', repr(action.type))
        args = {'type': name, 'value': arg_string}
        msg = _('invalid %(type)s value: %(value)r')
        raise ArgumentError(action, msg % args)
    return result

def _check_value(self, action, value):
    choices = action.choices
    if choices is not None:
        if isinstance(choices, str):
            choices = iter(choices)
        if value not in choices:
            args = {'value': str(value), 'choices': ', '.join(map(str, action.choices))}
            msg = _('invalid choice: %(value)r (choose from %(choices)s)')
            raise ArgumentError(action, msg % args)

def format_usage(self):
    formatter = self._get_formatter()
    formatter.add_usage(self.usage, self._actions, self._mutually_exclusive_groups)
    return formatter.format_help()

def print_help(self, file=None):
    if file is None:
        file = _sys.stdout
    self._print_message(self.format_help(), file)

def _print_message(self, message, file=None):
    if message:
        file = file or _sys.stderr
        try:
            file.write(message)
        except (AttributeError, OSError):
            pass

def format_help(self):
    if self.parent is not None:
        self.formatter._indent()
    join = self.formatter._join_parts
    item_help = join([func(*args) for func, args in self.items])
    if self.parent is not None:
        self.formatter._dedent()
    if not item_help:
        return ''
    if self.heading is not SUPPRESS and self.heading is not None:
        current_indent = self.formatter._current_indent
        heading_text = _('%(heading)s:') % dict(heading=self.heading)
        heading = '%*s%s\n' % (current_indent, '', heading_text)
    else:
        heading = ''
    return join(['\n', heading, item_help, '\n'])

def format(tuple_size):
    if isinstance(result, tuple):
        return result
    else:
        return (result,) * tuple_size

def __init__(self, name, aliases, help):
    metavar = dest = name
    if aliases:
        metavar += ' (%s)' % ', '.join(aliases)
    sup = super(_SubParsersAction._ChoicesPseudoAction, self)
    sup.__init__(option_strings=[], dest=dest, help=help, metavar=metavar)

def take_action(action, argument_strings, option_string=None):
    seen_actions.add(action)
    argument_values = self._get_values(action, argument_strings)
    if action.option_strings or argument_strings:
        seen_non_default_actions.add(action)
        for conflict_action in action_conflicts.get(action, []):
            if conflict_action in seen_non_default_actions:
                msg = _('not allowed with argument %s')
                action_name = _get_action_name(conflict_action)
                raise ArgumentError(action, msg % action_name)
    if argument_values is not SUPPRESS:
        action(self, namespace, argument_values, option_string)

def consume_positionals(start_index):
    match_partial = self._match_arguments_partial
    selected_pattern = arg_strings_pattern[start_index:]
    arg_counts = match_partial(positionals, selected_pattern)
    for action, arg_count in zip(positionals, arg_counts):
        args = arg_strings[start_index:start_index + arg_count]
        if action.nargs == PARSER:
            if arg_strings_pattern[start_index] == '-':
                assert args[0] == '--'
                args.remove('--')
        elif action.nargs != REMAINDER:
            if arg_strings_pattern.find('-', start_index, start_index + arg_count) >= 0:
                args.remove('--')
        start_index += arg_count
        take_action(action, args)
    positionals[:] = positionals[len(arg_counts):]
    return start_index

def get_lines(parts, indent, prefix=None):
    lines = []
    line = []
    indent_length = len(indent)
    if prefix is not None:
        line_len = len(prefix) - 1
    else:
        line_len = indent_length - 1
    for part in parts:
        if line_len + 1 + len(part) > text_width and line:
            lines.append(indent + ' '.join(line))
            line = []
            line_len = indent_length - 1
        line.append(part)
        line_len += len(part) + 1
    if line:
        lines.append(indent + ' '.join(line))
    if prefix is not None:
        lines[0] = lines[0][indent_length:]
    return lines

def parse(source, filename='<unknown>', mode='exec', *, type_comments=False, feature_version=None):
    """Parse the source into an AST node.
    Equivalent to compile(source, filename, mode, PyCF_ONLY_AST).
    Pass type_comments=True to get back type comments where the syntax allows."""
    flags = PyCF_ONLY_AST
    if type_comments:
        flags |= PyCF_TYPE_COMMENTS
    if feature_version is None:
        feature_version = -1
    elif isinstance(feature_version, tuple):
        major, minor = feature_version
        if major != 3:
            raise ValueError(f'Unsupported major version: {major}')
        feature_version = minor
    return compile(source, filename, mode, flags, _feature_version=feature_version)

def copy_location(new_node, old_node):
    """Copy source location (`lineno`, `col_offset`, `end_lineno`, and `end_col_offset`
    attributes) from *old_node* to *new_node* if possible, and return *new_node*."""
    for attr in ('lineno', 'col_offset', 'end_lineno', 'end_col_offset'):
        if attr in old_node._attributes and attr in new_node._attributes:
            value = getattr(old_node, attr, None)
            if value is not None or (hasattr(old_node, attr) and attr.startswith('end_')):
                setattr(new_node, attr, value)
    return new_node

def fix_missing_locations(node):
    """When you compile a node tree with compile(), the compiler expects lineno and
    col_offset attributes for every node that supports them.  This is rather
    tedious to fill in for generated nodes, so this helper adds these attributes
    recursively where not already set, by setting them to the values of the
    parent node.  It works recursively starting at *node*."""
    def _fix(node, lineno, col_offset, end_lineno, end_col_offset):
        if 'lineno' in node._attributes:
            if not hasattr(node, 'lineno'):
                node.lineno = lineno
            else:
                lineno = node.lineno
        if 'end_lineno' in node._attributes:
            if getattr(node, 'end_lineno', None) is None:
                node.end_lineno = end_lineno
            else:
                end_lineno = node.end_lineno
        if 'col_offset' in node._attributes:
            if not hasattr(node, 'col_offset'):
                node.col_offset = col_offset
            else:
                col_offset = node.col_offset
        if 'end_col_offset' in node._attributes:
            if getattr(node, 'end_col_offset', None) is None:
                node.end_col_offset = end_col_offset
            else:
                end_col_offset = node.end_col_offset
        for child in iter_child_nodes(node):
            _fix(child, lineno, col_offset, end_lineno, end_col_offset)
    _fix(node, 1, 0, 1, 0)
    return node

def increment_lineno(node, n=1):
    """Increment the line number and end line number of each node in the tree
    starting at *node* by *n*. This is useful to "move code" to a different
    location in a file."""
    for child in walk(node):
        if isinstance(child, TypeIgnore):
            child.lineno = getattr(child, 'lineno', 0) + n
            continue
        if 'lineno' in child._attributes:
            child.lineno = getattr(child, 'lineno', 0) + n
        if 'end_lineno' in child._attributes and (end_lineno := getattr(child, 'end_lineno', 0)) is not None:
            child.end_lineno = end_lineno + n
    return node

def iter_child_nodes(node):
    """Yield all direct child nodes of *node*, that is, all fields that are nodes
    and all items of fields that are lists of nodes."""
    for name, field in iter_fields(node):
        if isinstance(field, AST):
            yield field
        elif isinstance(field, list):
            for item in field:
                if isinstance(item, AST):
                    yield item

def get_docstring(node, clean=True):
    """Return the docstring for the given node or None if no docstring can
    be found.  If the node provided does not have docstrings a TypeError
    will be raised.

    If *clean* is `True`, all tabs are expanded to spaces and any whitespace
    that can be uniformly removed from the second line onwards is removed."""
    if not isinstance(node, (AsyncFunctionDef, FunctionDef, ClassDef, Module)):
        raise TypeError("%r can't have docstrings" % node.__class__.__name__)
    if not (node.body and isinstance(node.body[0], Expr)):
        return None
    node = node.body[0].value
    if isinstance(node, Constant) and isinstance(node.value, str):
        text = node.value
    else:
        return None
    if clean:
        import inspect
        text = inspect.cleandoc(text)
    return text

def _splitlines_no_ff(source, maxlines=None):
    """Split a string into lines ignoring form feed and other chars.

    This mimics how the Python parser splits source code."""
    lines = []
    for lineno, match in enumerate(_line_pattern.finditer(source), 1):
        if maxlines is not None and lineno > maxlines:
            break
        lines.append(match[0])
    return lines

def _pad_whitespace(source):
    """Replace all chars except '\\f\\t' in a line with spaces."""
    result = ''
    for c in source:
        if c in '\x0c\t':
            result += c
        else:
            result += ' '
    return result

def get_source_segment(source, node, *, padded=False):
    """Get source code segment of the *source* that generated *node*.

    If some location information (`lineno`, `end_lineno`, `col_offset`,
    or `end_col_offset`) is missing, return None.

    If *padded* is `True`, the first line of a multi-line statement will
    be padded with spaces to match its original position."""
    try:
        if node.end_lineno is None or node.end_col_offset is None:
            return None
        lineno = node.lineno - 1
        end_lineno = node.end_lineno - 1
        col_offset = node.col_offset
        end_col_offset = node.end_col_offset
    except AttributeError:
        return None
    lines = _splitlines_no_ff(source, maxlines=end_lineno + 1)
    if end_lineno == lineno:
        return lines[lineno].encode()[col_offset:end_col_offset].decode()
    if padded:
        padding = _pad_whitespace(lines[lineno].encode()[:col_offset].decode())
    else:
        padding = ''
    first = padding + lines[lineno].encode()[col_offset:].decode()
    last = lines[end_lineno].encode()[:end_col_offset].decode()
    lines = lines[lineno + 1:end_lineno]
    lines.insert(0, first)
    lines.append(last)
    return ''.join(lines)

def _new(cls, *args, **kwargs):
    for key in kwargs:
        if key not in cls._fields:
            continue
        pos = cls._fields.index(key)
        if pos < len(args):
            raise TypeError(f'{cls.__name__} got multiple values for argument {key!r}')
    if cls in _const_types:
        import warnings
        warnings._deprecated(f'ast.{cls.__qualname__}', message=_DEPRECATED_CLASS_MESSAGE, remove=(3, 14))
        return Constant(*args, **kwargs)
    return Constant.__new__(cls, *args, **kwargs)

def unparse(ast_obj):
    unparser = _Unparser()
    return unparser.visit(ast_obj)

def _raise_malformed_node(node):
    msg = 'malformed node or string'
    if (lno := getattr(node, 'lineno', None)):
        msg += f' on line {lno}'
    raise ValueError(msg + f': {node!r}')

def _convert_num(node):
    if not isinstance(node, Constant) or type(node.value) not in (int, float, complex):
        _raise_malformed_node(node)
    return node.value

def _convert_signed_num(node):
    if isinstance(node, UnaryOp) and isinstance(node.op, (UAdd, USub)):
        operand = _convert_num(node.operand)
        if isinstance(node.op, UAdd):
            return +operand
        else:
            return -operand
    return _convert_num(node)

def _convert(node):
    if isinstance(node, Constant):
        return node.value
    elif isinstance(node, Tuple):
        return tuple(map(_convert, node.elts))
    elif isinstance(node, List):
        return list(map(_convert, node.elts))
    elif isinstance(node, Set):
        return set(map(_convert, node.elts))
    elif isinstance(node, Call) and isinstance(node.func, Name) and (node.func.id == 'set') and (node.args == node.keywords == []):
        return set()
    elif isinstance(node, Dict):
        if len(node.keys) != len(node.values):
            _raise_malformed_node(node)
        return dict(zip(map(_convert, node.keys), map(_convert, node.values)))
    elif isinstance(node, BinOp) and isinstance(node.op, (Add, Sub)):
        left = _convert_signed_num(node.left)
        right = _convert_num(node.right)
        if isinstance(left, (int, float)) and isinstance(right, complex):
            if isinstance(node.op, Add):
                return left + right
            else:
                return left - right
    return _convert_signed_num(node)

def _fix(node, lineno, col_offset, end_lineno, end_col_offset):
    if 'lineno' in node._attributes:
        if not hasattr(node, 'lineno'):
            node.lineno = lineno
        else:
            lineno = node.lineno
    if 'end_lineno' in node._attributes:
        if getattr(node, 'end_lineno', None) is None:
            node.end_lineno = end_lineno
        else:
            end_lineno = node.end_lineno
    if 'col_offset' in node._attributes:
        if not hasattr(node, 'col_offset'):
            node.col_offset = col_offset
        else:
            col_offset = node.col_offset
    if 'end_col_offset' in node._attributes:
        if getattr(node, 'end_col_offset', None) is None:
            node.end_col_offset = end_col_offset
        else:
            end_col_offset = node.end_col_offset
    for child in iter_child_nodes(node):
        _fix(child, lineno, col_offset, end_lineno, end_col_offset)

def visit(self, node):
    """Visit a node."""
    method = 'visit_' + node.__class__.__name__
    visitor = getattr(self, method, self.generic_visit)
    return visitor(node)

def visit_Constant(self, node):
    value = node.value
    type_name = _const_node_type_names.get(type(value))
    if type_name is None:
        for cls, name in _const_node_type_names.items():
            if isinstance(value, cls):
                type_name = name
                break
    if type_name is not None:
        method = 'visit_' + type_name
        try:
            visitor = getattr(self, method)
        except AttributeError:
            pass
        else:
            import warnings
            warnings.warn(f'{method} is deprecated; add visit_Constant', DeprecationWarning, 2)
            return visitor(node)
    return self.generic_visit(node)

def generic_visit(self, node):
    for field, old_value in iter_fields(node):
        if isinstance(old_value, list):
            new_values = []
            for value in old_value:
                if isinstance(value, AST):
                    value = self.visit(value)
                    if value is None:
                        continue
                    elif not isinstance(value, AST):
                        new_values.extend(value)
                        continue
                new_values.append(value)
            old_value[:] = new_values
        elif isinstance(old_value, AST):
            new_node = self.visit(old_value)
            if new_node is None:
                delattr(node, field)
            else:
                setattr(node, field, new_node)
    return node

def __instancecheck__(cls, inst):
    if cls in _const_types:
        import warnings
        warnings._deprecated(f'ast.{cls.__qualname__}', message=_DEPRECATED_CLASS_MESSAGE, remove=(3, 14))
    if not isinstance(inst, Constant):
        return False
    if cls in _const_types:
        try:
            value = inst.value
        except AttributeError:
            return False
        else:
            return isinstance(value, _const_types[cls]) and (not isinstance(value, _const_types_not.get(cls, ())))
    return type.__instancecheck__(cls, inst)

def __new__(cls, *args, **kwargs):
    if cls is _ast_Ellipsis:
        import warnings
        warnings._deprecated('ast.Ellipsis', message=_DEPRECATED_CLASS_MESSAGE, remove=(3, 14))
        return Constant(..., *args, **kwargs)
    return Constant.__new__(cls, *args, **kwargs)

def _dims_getter(self):
    """Deprecated. Use elts instead."""
    return self.elts

def next(self):
    try:
        return self.__class__(self + 1)
    except ValueError:
        return self

def __init__(self, *, _avoid_backslashes=False):
    self._source = []
    self._precedences = {}
    self._type_ignores = {}
    self._indent = 0
    self._avoid_backslashes = _avoid_backslashes
    self._in_try_star = False

def interleave(self, inter, f, seq):
    """Call f on each item in seq, calling inter() in between."""
    seq = iter(seq)
    try:
        f(next(seq))
    except StopIteration:
        pass
    else:
        for x in seq:
            inter()
            f(x)

def maybe_newline(self):
    """Adds a newline if it isn't the start of generated source"""
    if self._source:
        self.write('\n')

def write(self, *text):
    """Add new source parts"""
    self._source.extend(text)

@contextmanager
def buffered(self, buffer=None):
    if buffer is None:
        buffer = []
    original_source = self._source
    self._source = buffer
    yield buffer
    self._source = original_source

def delimit_if(self, start, end, condition):
    if condition:
        return self.delimit(start, end)
    else:
        return nullcontext()

def require_parens(self, precedence, node):
    """Shortcut to adding precedence related parens"""
    return self.delimit_if('(', ')', self.get_precedence(node) > precedence)

def set_precedence(self, precedence, *nodes):
    for node in nodes:
        self._precedences[node] = precedence

def get_raw_docstring(self, node):
    """If a docstring node is found in the body of the *node* parameter,
    return that docstring node, None otherwise.

    Logic mirrored from ``_PyAST_GetDocString``."""
    if not isinstance(node, (AsyncFunctionDef, FunctionDef, ClassDef, Module)) or len(node.body) < 1:
        return None
    node = node.body[0]
    if not isinstance(node, Expr):
        return None
    node = node.value
    if isinstance(node, Constant) and isinstance(node.value, str):
        return node

def get_type_comment(self, node):
    comment = self._type_ignores.get(node.lineno) or node.type_comment
    if comment is not None:
        return f' # type: {comment}'

def traverse(self, node):
    if isinstance(node, list):
        for item in node:
            self.traverse(item)
    else:
        super().visit(node)

def visit(self, node):
    """Outputs a source code string that, if converted back to an ast
    (using ast.parse) will generate an AST equivalent to *node*"""
    self._source = []
    self.traverse(node)
    return ''.join(self._source)

def _write_docstring_and_traverse_body(self, node):
    if (docstring := self.get_raw_docstring(node)):
        self._write_docstring(docstring)
        self.traverse(node.body[1:])
    else:
        self.traverse(node.body)

def visit_Module(self, node):
    self._type_ignores = {ignore.lineno: f'ignore{ignore.tag}' for ignore in node.type_ignores}
    self._write_docstring_and_traverse_body(node)
    self._type_ignores.clear()

def visit_Import(self, node):
    self.fill('import ')
    self.interleave(lambda: self.write(', '), self.traverse, node.names)

def visit_Assign(self, node):
    self.fill()
    for target in node.targets:
        self.set_precedence(_Precedence.TUPLE, target)
        self.traverse(target)
        self.write(' = ')
    self.traverse(node.value)
    if (type_comment := self.get_type_comment(node)):
        self.write(type_comment)

def visit_Return(self, node):
    self.fill('return')
    if node.value:
        self.write(' ')
        self.traverse(node.value)

def visit_Delete(self, node):
    self.fill('del ')
    self.interleave(lambda: self.write(', '), self.traverse, node.targets)

def visit_Assert(self, node):
    self.fill('assert ')
    self.traverse(node.test)
    if node.msg:
        self.write(', ')
        self.traverse(node.msg)

def visit_Global(self, node):
    self.fill('global ')
    self.interleave(lambda: self.write(', '), self.write, node.names)

def visit_Nonlocal(self, node):
    self.fill('nonlocal ')
    self.interleave(lambda: self.write(', '), self.write, node.names)

def visit_Raise(self, node):
    self.fill('raise')
    if not node.exc:
        if node.cause:
            raise ValueError(f"Node can't use cause without an exception.")
        return
    self.write(' ')
    self.traverse(node.exc)
    if node.cause:
        self.write(' from ')
        self.traverse(node.cause)

def visit_ExceptHandler(self, node):
    self.fill('except*' if self._in_try_star else 'except')
    if node.type:
        self.write(' ')
        self.traverse(node.type)
    if node.name:
        self.write(' as ')
        self.write(node.name)
    with self.block():
        self.traverse(node.body)

def visit_ClassDef(self, node):
    self.maybe_newline()
    for deco in node.decorator_list:
        self.fill('@')
        self.traverse(deco)
    self.fill('class ' + node.name)
    if hasattr(node, 'type_params'):
        self._type_params_helper(node.type_params)
    with self.delimit_if('(', ')', condition=node.bases or node.keywords):
        comma = False
        for e in node.bases:
            if comma:
                self.write(', ')
            else:
                comma = True
            self.traverse(e)
        for e in node.keywords:
            if comma:
                self.write(', ')
            else:
                comma = True
            self.traverse(e)
    with self.block():
        self._write_docstring_and_traverse_body(node)

def _type_params_helper(self, type_params):
    if type_params is not None and len(type_params) > 0:
        with self.delimit('[', ']'):
            self.interleave(lambda: self.write(', '), self.traverse, type_params)

def visit_TypeVar(self, node):
    self.write(node.name)
    if node.bound:
        self.write(': ')
        self.traverse(node.bound)

def _str_literal_helper(self, string, *, quote_types=_ALL_QUOTES, escape_special_whitespace=False):
    """Helper for writing string literals, minimizing escapes.
    Returns the tuple (string literal to write, possible quote types)."""
    def escape_char(c):
        if not escape_special_whitespace and c in '\n\t':
            return c
        if c == '\\' or not c.isprintable():
            return c.encode('unicode_escape').decode('ascii')
        return c
    escaped_string = ''.join(map(escape_char, string))
    possible_quotes = quote_types
    if '\n' in escaped_string:
        possible_quotes = [q for q in possible_quotes if q in _MULTI_QUOTES]
    possible_quotes = [q for q in possible_quotes if q not in escaped_string]
    if not possible_quotes:
        string = repr(string)
        quote = next((q for q in quote_types if string[0] in q), string[0])
        return (string[1:-1], [quote])
    if escaped_string:
        possible_quotes.sort(key=lambda q: q[0] == escaped_string[-1])
        if possible_quotes[0][0] == escaped_string[-1]:
            assert len(possible_quotes[0]) == 3
            escaped_string = escaped_string[:-1] + '\\' + escaped_string[-1]
    return (escaped_string, possible_quotes)

def _write_fstring_inner(self, node, is_format_spec=False):
    if isinstance(node, JoinedStr):
        for value in node.values:
            self._write_fstring_inner(value, is_format_spec=is_format_spec)
    elif isinstance(node, Constant) and isinstance(node.value, str):
        value = node.value.replace('{', '{{').replace('}', '}}')
        if is_format_spec:
            value = value.replace('\\', '\\\\')
            value = value.replace("'", "\\'")
            value = value.replace('"', '\\"')
            value = value.replace('\n', '\\n')
        self.write(value)
    elif isinstance(node, FormattedValue):
        self.visit_FormattedValue(node)
    else:
        raise ValueError(f'Unexpected node inside JoinedStr, {node!r}')

def visit_FormattedValue(self, node):
    def unparse_inner(inner):
        unparser = type(self)()
        unparser.set_precedence(_Precedence.TEST.next(), inner)
        return unparser.visit(inner)
    with self.delimit('{', '}'):
        expr = unparse_inner(node.value)
        if expr.startswith('{'):
            self.write(' ')
        self.write(expr)
        if node.conversion != -1:
            self.write(f'!{chr(node.conversion)}')
        if node.format_spec:
            self.write(':')
            self._write_fstring_inner(node.format_spec, is_format_spec=True)

def _write_docstring(self, node):
    self.fill()
    if node.kind == 'u':
        self.write('u')
    self._write_str_avoiding_backslashes(node.value, quote_types=_MULTI_QUOTES)

def _write_constant(self, value):
    if isinstance(value, (float, complex)):
        self.write(repr(value).replace('inf', _INFSTR).replace('nan', f'({_INFSTR}-{_INFSTR})'))
    elif self._avoid_backslashes and isinstance(value, str):
        self._write_str_avoiding_backslashes(value)
    else:
        self.write(repr(value))

def visit_Constant(self, node):
    value = node.value
    if isinstance(value, tuple):
        with self.delimit('(', ')'):
            self.items_view(self._write_constant, value)
    elif value is ...:
        self.write('...')
    else:
        if node.kind == 'u':
            self.write('u')
        self._write_constant(node.value)

def visit_List(self, node):
    with self.delimit('[', ']'):
        self.interleave(lambda: self.write(', '), self.traverse, node.elts)

def visit_ListComp(self, node):
    with self.delimit('[', ']'):
        self.traverse(node.elt)
        for gen in node.generators:
            self.traverse(gen)

def visit_GeneratorExp(self, node):
    with self.delimit('(', ')'):
        self.traverse(node.elt)
        for gen in node.generators:
            self.traverse(gen)

def visit_SetComp(self, node):
    with self.delimit('{', '}'):
        self.traverse(node.elt)
        for gen in node.generators:
            self.traverse(gen)

def visit_comprehension(self, node):
    if node.is_async:
        self.write(' async for ')
    else:
        self.write(' for ')
    self.set_precedence(_Precedence.TUPLE, node.target)
    self.traverse(node.target)
    self.write(' in ')
    self.set_precedence(_Precedence.TEST.next(), node.iter, *node.ifs)
    self.traverse(node.iter)
    for if_clause in node.ifs:
        self.write(' if ')
        self.traverse(if_clause)

def visit_Set(self, node):
    if node.elts:
        with self.delimit('{', '}'):
            self.interleave(lambda: self.write(', '), self.traverse, node.elts)
    else:
        self.write('{*()}')

def visit_Dict(self, node):
    def write_key_value_pair(k, v):
        self.traverse(k)
        self.write(': ')
        self.traverse(v)
    def write_item(item):
        k, v = item
        if k is None:
            self.write('**')
            self.set_precedence(_Precedence.EXPR, v)
            self.traverse(v)
        else:
            write_key_value_pair(k, v)
    with self.delimit('{', '}'):
        self.interleave(lambda: self.write(', '), write_item, zip(node.keys, node.values))

def visit_Tuple(self, node):
    with self.delimit_if('(', ')', len(node.elts) == 0 or self.get_precedence(node) > _Precedence.TUPLE):
        self.items_view(self.traverse, node.elts)

def visit_Call(self, node):
    self.set_precedence(_Precedence.ATOM, node.func)
    self.traverse(node.func)
    with self.delimit('(', ')'):
        comma = False
        for e in node.args:
            if comma:
                self.write(', ')
            else:
                comma = True
            self.traverse(e)
        for e in node.keywords:
            if comma:
                self.write(', ')
            else:
                comma = True
            self.traverse(e)

def visit_Subscript(self, node):
    def is_non_empty_tuple(slice_value):
        return isinstance(slice_value, Tuple) and slice_value.elts
    self.set_precedence(_Precedence.ATOM, node.value)
    self.traverse(node.value)
    with self.delimit('[', ']'):
        if is_non_empty_tuple(node.slice):
            self.items_view(self.traverse, node.slice.elts)
        else:
            self.traverse(node.slice)

def visit_Slice(self, node):
    if node.lower:
        self.traverse(node.lower)
    self.write(':')
    if node.upper:
        self.traverse(node.upper)
    if node.step:
        self.write(':')
        self.traverse(node.step)

def visit_Match(self, node):
    self.fill('match ')
    self.traverse(node.subject)
    with self.block():
        for case in node.cases:
            self.traverse(case)

def visit_arg(self, node):
    self.write(node.arg)
    if node.annotation:
        self.write(': ')
        self.traverse(node.annotation)

def visit_keyword(self, node):
    if node.arg is None:
        self.write('**')
    else:
        self.write(node.arg)
        self.write('=')
    self.traverse(node.value)

def visit_alias(self, node):
    self.write(node.name)
    if node.asname:
        self.write(' as ' + node.asname)

def visit_withitem(self, node):
    self.traverse(node.context_expr)
    if node.optional_vars:
        self.write(' as ')
        self.traverse(node.optional_vars)

def visit_MatchSequence(self, node):
    with self.delimit('[', ']'):
        self.interleave(lambda: self.write(', '), self.traverse, node.patterns)

def visit_MatchStar(self, node):
    name = node.name
    if name is None:
        name = '_'
    self.write(f'*{name}')

def visit_MatchAs(self, node):
    name = node.name
    pattern = node.pattern
    if name is None:
        self.write('_')
    elif pattern is None:
        self.write(node.name)
    else:
        with self.require_parens(_Precedence.TEST, node):
            self.set_precedence(_Precedence.BOR, node.pattern)
            self.traverse(node.pattern)
            self.write(f' as {node.name}')

def escape_char(c):
    if not escape_special_whitespace and c in '\n\t':
        return c
    if c == '\\' or not c.isprintable():
        return c.encode('unicode_escape').decode('ascii')
    return c

def unparse_inner(inner):
    unparser = type(self)()
    unparser.set_precedence(_Precedence.TEST.next(), inner)
    return unparser.visit(inner)

def write_item(item):
    k, v = item
    if k is None:
        self.write('**')
        self.set_precedence(_Precedence.EXPR, v)
        self.traverse(v)
    else:
        write_key_value_pair(k, v)

def runcode(self, code):
    future = concurrent.futures.Future()
    def callback():
        global repl_future
        global repl_future_interrupted
        repl_future = None
        repl_future_interrupted = False
        func = types.FunctionType(code, self.locals)
        try:
            coro = func()
        except SystemExit:
            raise
        except KeyboardInterrupt as ex:
            repl_future_interrupted = True
            future.set_exception(ex)
            return
        except BaseException as ex:
            future.set_exception(ex)
            return
        if not inspect.iscoroutine(coro):
            future.set_result(coro)
            return
        try:
            repl_future = self.loop.create_task(coro, context=self.context)
            futures._chain_future(repl_future, future)
        except BaseException as exc:
            future.set_exception(exc)
    loop.call_soon_threadsafe(callback, context=self.context)
    try:
        return future.result()
    except SystemExit:
        raise
    except BaseException:
        if repl_future_interrupted:
            self.write('\nKeyboardInterrupt\n')
        else:
            self.showtraceback()

def callback():
    global repl_future
    global repl_future_interrupted
    repl_future = None
    repl_future_interrupted = False
    func = types.FunctionType(code, self.locals)
    try:
        coro = func()
    except SystemExit:
        raise
    except KeyboardInterrupt as ex:
        repl_future_interrupted = True
        future.set_exception(ex)
        return
    except BaseException as ex:
        future.set_exception(ex)
        return
    if not inspect.iscoroutine(coro):
        future.set_result(coro)
        return
    try:
        repl_future = self.loop.create_task(coro, context=self.context)
        futures._chain_future(repl_future, future)
    except BaseException as exc:
        future.set_exception(exc)

def _format_handle(handle):
    cb = handle._callback
    if isinstance(getattr(cb, '__self__', None), tasks.Task):
        return repr(cb.__self__)
    else:
        return str(handle)

def _format_pipe(fd):
    if fd == subprocess.PIPE:
        return '<pipe>'
    elif fd == subprocess.STDOUT:
        return '<stdout>'
    else:
        return repr(fd)

def _set_reuseport(sock):
    if not hasattr(socket, 'SO_REUSEPORT'):
        raise ValueError('reuse_port not supported by socket module')
    else:
        try:
            sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEPORT, 1)
        except OSError:
            raise ValueError('reuse_port not supported by socket module, SO_REUSEPORT defined but not implemented.')

def _run_until_complete_cb(fut):
    if not fut.cancelled():
        exc = fut.exception()
        if isinstance(exc, (SystemExit, KeyboardInterrupt)):
            return
    futures._get_loop(fut).stop()

def _check_ssl_socket(sock):
    if ssl is not None and isinstance(sock, ssl.SSLSocket):
        raise TypeError('Socket cannot be of type SSLSocket')

def _set_nodelay(sock):
    if sock.family in {socket.AF_INET, socket.AF_INET6} and sock.type == socket.SOCK_STREAM and (sock.proto == socket.IPPROTO_TCP):
        sock.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)

def __init__(self, transp):
    if not isinstance(transp, transports._FlowControlMixin):
        raise TypeError('transport should be _FlowControlMixin instance')
    self._transport = transp
    self._proto = transp.get_protocol()
    self._should_resume_reading = transp.is_reading()
    self._should_resume_writing = transp._protocol_paused
    transp.pause_reading()
    transp.set_protocol(self)
    if self._should_resume_writing:
        self._write_ready_fut = self._transport._loop.create_future()
    else:
        self._write_ready_fut = None

def connection_lost(self, exc):
    if self._write_ready_fut is not None:
        if exc is None:
            self._write_ready_fut.set_exception(ConnectionError('Connection is closed by peer'))
        else:
            self._write_ready_fut.set_exception(exc)
    self._proto.connection_lost(exc)

def pause_writing(self):
    if self._write_ready_fut is not None:
        return
    self._write_ready_fut = self._transport._loop.create_future()

def resume_writing(self):
    if self._write_ready_fut is None:
        return
    self._write_ready_fut.set_result(False)
    self._write_ready_fut = None

async def restore(self):
    self._transport.set_protocol(self._proto)
    if self._should_resume_reading:
        self._transport.resume_reading()
    if self._write_ready_fut is not None:
        self._write_ready_fut.cancel()
    if self._should_resume_writing:
        self._proto.resume_writing()

def _attach(self):
    assert self._sockets is not None
    self._active_count += 1

def _detach(self):
    assert self._active_count > 0
    self._active_count -= 1
    if self._active_count == 0 and self._sockets is None:
        self._wakeup()

def _wakeup(self):
    waiters = self._waiters
    self._waiters = None
    for waiter in waiters:
        if not waiter.done():
            waiter.set_result(None)

def _start_serving(self):
    if self._serving:
        return
    self._serving = True
    for sock in self._sockets:
        sock.listen(self._backlog)
        self._loop._start_serving(self._protocol_factory, sock, self._ssl_context, self, self._backlog, self._ssl_handshake_timeout, self._ssl_shutdown_timeout)

@property
def sockets(self):
    if self._sockets is None:
        return ()
    return tuple((trsock.TransportSocket(s) for s in self._sockets))

def close(self):
    sockets = self._sockets
    if sockets is None:
        return
    self._sockets = None
    for sock in sockets:
        self._loop._stop_serving(sock)
    self._serving = False
    if self._serving_forever_fut is not None and (not self._serving_forever_fut.done()):
        self._serving_forever_fut.cancel()
        self._serving_forever_fut = None
    if self._active_count == 0:
        self._wakeup()

def create_future(self):
    """Create a Future object attached to the loop."""
    return futures.Future(loop=self)

def create_task(self, coro, *, name=None, context=None):
    """Schedule a coroutine object.

    Return a task object."""
    self._check_closed()
    if self._task_factory is None:
        task = tasks.Task(coro, loop=self, name=name, context=context)
        if task._source_traceback:
            del task._source_traceback[-1]
    else:
        if context is None:
            task = self._task_factory(self, coro)
        else:
            task = self._task_factory(self, coro, context=context)
        tasks._set_task_name(task, name)
    try:
        return task
    finally:
        del task

def get_task_factory(self):
    """Return a task factory, or None if the default one is in use."""
    return self._task_factory

def _make_socket_transport(self, sock, protocol, waiter=None, *, extra=None, server=None):
    """Create socket transport."""
    raise NotImplementedError

def _make_ssl_transport(self, rawsock, protocol, sslcontext, waiter=None, *, server_side=False, server_hostname=None, extra=None, server=None, ssl_handshake_timeout=None, ssl_shutdown_timeout=None, call_connection_made=True):
    """Create SSL transport."""
    raise NotImplementedError

def _make_datagram_transport(self, sock, protocol, address=None, waiter=None, extra=None):
    """Create datagram transport."""
    raise NotImplementedError

def _make_read_pipe_transport(self, pipe, protocol, waiter=None, extra=None):
    """Create read pipe transport."""
    raise NotImplementedError

def _make_write_pipe_transport(self, pipe, protocol, waiter=None, extra=None):
    """Create write pipe transport."""
    raise NotImplementedError

def _process_events(self, event_list):
    """Process selector events."""
    raise NotImplementedError

def _check_closed(self):
    if self._closed:
        raise RuntimeError('Event loop is closed')

def _check_default_executor(self):
    if self._executor_shutdown_called:
        raise RuntimeError('Executor shutdown has been called')

def _asyncgen_finalizer_hook(self, agen):
    self._asyncgens.discard(agen)
    if not self.is_closed():
        self.call_soon_threadsafe(self.create_task, agen.aclose())

def _asyncgen_firstiter_hook(self, agen):
    if self._asyncgens_shutdown_called:
        warnings.warn(f'asynchronous generator {agen!r} was scheduled after loop.shutdown_asyncgens() call', ResourceWarning, source=self)
    self._asyncgens.add(agen)

def _do_shutdown(self, future):
    try:
        self._default_executor.shutdown(wait=True)
        if not self.is_closed():
            self.call_soon_threadsafe(futures._set_result_unless_cancelled, future, None)
    except Exception as ex:
        if not self.is_closed() and (not future.cancelled()):
            self.call_soon_threadsafe(future.set_exception, ex)

def _check_running(self):
    if self.is_running():
        raise RuntimeError('This event loop is already running')
    if events._get_running_loop() is not None:
        raise RuntimeError('Cannot run the event loop while another loop is running')

def is_closed(self):
    """Returns True if the event loop was closed."""
    return self._closed

def is_running(self):
    """Returns True if the event loop is running."""
    return self._thread_id is not None

def time(self):
    """Return the time according to the event loop's clock.

    This is a float expressed in seconds since an epoch, but the
    epoch, precision, accuracy and drift are unspecified and may
    differ per event loop."""
    return time.monotonic()

def _check_callback(self, callback, method):
    if coroutines.iscoroutine(callback) or coroutines.iscoroutinefunction(callback):
        raise TypeError(f'coroutines cannot be used with {method}()')
    if not callable(callback):
        raise TypeError(f'a callable object was expected by {method}(), got {callback!r}')

def _call_soon(self, callback, args, context):
    handle = events.Handle(callback, args, self, context)
    if handle._source_traceback:
        del handle._source_traceback[-1]
    self._ready.append(handle)
    return handle

def call_soon_threadsafe(self, callback, *args, context=None):
    """Like call_soon(), but thread-safe."""
    self._check_closed()
    if self._debug:
        self._check_callback(callback, 'call_soon_threadsafe')
    handle = self._call_soon(callback, args, context)
    if handle._source_traceback:
        del handle._source_traceback[-1]
    self._write_to_self()
    return handle

def run_in_executor(self, executor, func, *args):
    self._check_closed()
    if self._debug:
        self._check_callback(func, 'run_in_executor')
    if executor is None:
        executor = self._default_executor
        self._check_default_executor()
        if executor is None:
            executor = concurrent.futures.ThreadPoolExecutor(thread_name_prefix='asyncio')
            self._default_executor = executor
    return futures.wrap_future(executor.submit(func, *args), loop=self)

def set_default_executor(self, executor):
    if not isinstance(executor, concurrent.futures.ThreadPoolExecutor):
        raise TypeError('executor must be ThreadPoolExecutor instance')
    self._default_executor = executor

def _getaddrinfo_debug(self, host, port, family, type, proto, flags):
    msg = [f'{host}:{port!r}']
    if family:
        msg.append(f'family={family!r}')
    if type:
        msg.append(f'type={type!r}')
    if proto:
        msg.append(f'proto={proto!r}')
    if flags:
        msg.append(f'flags={flags!r}')
    msg = ', '.join(msg)
    logger.debug('Get address info %s', msg)
    t0 = self.time()
    addrinfo = socket.getaddrinfo(host, port, family, type, proto, flags)
    dt = self.time() - t0
    msg = f'Getting address info {msg} took {dt * 1000.0:.3f}ms: {addrinfo!r}'
    if dt >= self.slow_callback_duration:
        logger.info(msg)
    else:
        logger.debug(msg)
    return addrinfo

async def getaddrinfo(self, host, port, *, family=0, type=0, proto=0, flags=0):
    if self._debug:
        getaddr_func = self._getaddrinfo_debug
    else:
        getaddr_func = socket.getaddrinfo
    return await self.run_in_executor(None, getaddr_func, host, port, family, type, proto, flags)

async def sock_sendfile(self, sock, file, offset=0, count=None, *, fallback=True):
    if self._debug and sock.gettimeout() != 0:
        raise ValueError('the socket must be non-blocking')
    _check_ssl_socket(sock)
    self._check_sendfile_params(sock, file, offset, count)
    try:
        return await self._sock_sendfile_native(sock, file, offset, count)
    except exceptions.SendfileNotAvailableError as exc:
        if not fallback:
            raise
    return await self._sock_sendfile_fallback(sock, file, offset, count)

async def _sock_sendfile_fallback(self, sock, file, offset, count):
    if offset:
        file.seek(offset)
    blocksize = min(count, constants.SENDFILE_FALLBACK_READBUFFER_SIZE) if count else constants.SENDFILE_FALLBACK_READBUFFER_SIZE
    buf = bytearray(blocksize)
    total_sent = 0
    try:
        while True:
            if count:
                blocksize = min(count - total_sent, blocksize)
                if blocksize <= 0:
                    break
            view = memoryview(buf)[:blocksize]
            read = await self.run_in_executor(None, file.readinto, view)
            if not read:
                break
            await self.sock_sendall(sock, view[:read])
            total_sent += read
        return total_sent
    finally:
        if total_sent > 0 and hasattr(file, 'seek'):
            file.seek(offset + total_sent)

def _check_sendfile_params(self, sock, file, offset, count):
    if 'b' not in getattr(file, 'mode', 'b'):
        raise ValueError('file should be opened in binary mode')
    if not sock.type == socket.SOCK_STREAM:
        raise ValueError('only SOCK_STREAM type sockets are supported')
    if count is not None:
        if not isinstance(count, int):
            raise TypeError('count must be a positive integer (got {!r})'.format(count))
        if count <= 0:
            raise ValueError('count must be a positive integer (got {!r})'.format(count))
    if not isinstance(offset, int):
        raise TypeError('offset must be a non-negative integer (got {!r})'.format(offset))
    if offset < 0:
        raise ValueError('offset must be a non-negative integer (got {!r})'.format(offset))

async def _connect_sock(self, exceptions, addr_info, local_addr_infos=None):
    """Create, bind and connect one socket."""
    my_exceptions = []
    exceptions.append(my_exceptions)
    family, type_, proto, _, address = addr_info
    sock = None
    try:
        sock = socket.socket(family=family, type=type_, proto=proto)
        sock.setblocking(False)
        if local_addr_infos is not None:
            for lfamily, _, _, _, laddr in local_addr_infos:
                if lfamily != family:
                    continue
                try:
                    sock.bind(laddr)
                    break
                except OSError as exc:
                    msg = f'error while attempting to bind on address {laddr!r}: {str(exc).lower()}'
                    exc = OSError(exc.errno, msg)
                    my_exceptions.append(exc)
            else:
                if my_exceptions:
                    raise my_exceptions.pop()
                else:
                    raise OSError(f'no matching local address with family={family!r} found')
        await self.sock_connect(sock, address)
        return sock
    except OSError as exc:
        my_exceptions.append(exc)
        if sock is not None:
            sock.close()
        raise
    except:
        if sock is not None:
            sock.close()
        raise
    finally:
        exceptions = my_exceptions = None

async def _create_connection_transport(self, sock, protocol_factory, ssl, server_hostname, server_side=False, ssl_handshake_timeout=None, ssl_shutdown_timeout=None):
    sock.setblocking(False)
    protocol = protocol_factory()
    waiter = self.create_future()
    if ssl:
        sslcontext = None if isinstance(ssl, bool) else ssl
        transport = self._make_ssl_transport(sock, protocol, sslcontext, waiter, server_side=server_side, server_hostname=server_hostname, ssl_handshake_timeout=ssl_handshake_timeout, ssl_shutdown_timeout=ssl_shutdown_timeout)
    else:
        transport = self._make_socket_transport(sock, protocol, waiter)
    try:
        await waiter
    except:
        transport.close()
        raise
    return (transport, protocol)

async def sendfile(self, transport, file, offset=0, count=None, *, fallback=True):
    """Send a file to transport.

    Return the total number of bytes which were sent.

    The method uses high-performance os.sendfile if available.

    file must be a regular file object opened in binary mode.

    offset tells from where to start reading the file. If specified,
    count is the total number of bytes to transmit as opposed to
    sending the file until EOF is reached. File position is updated on
    return or also in case of error in which case file.tell()
    can be used to figure out the number of bytes
    which were sent.

    fallback set to True makes asyncio to manually read and send
    the file when the platform does not support the sendfile syscall
    (e.g. Windows or SSL socket on Unix).

    Raise SendfileNotAvailableError if the system does not support
    sendfile syscall and fallback is False."""
    if transport.is_closing():
        raise RuntimeError('Transport is closing')
    mode = getattr(transport, '_sendfile_compatible', constants._SendfileMode.UNSUPPORTED)
    if mode is constants._SendfileMode.UNSUPPORTED:
        raise RuntimeError(f'sendfile is not supported for transport {transport!r}')
    if mode is constants._SendfileMode.TRY_NATIVE:
        try:
            return await self._sendfile_native(transport, file, offset, count)
        except exceptions.SendfileNotAvailableError as exc:
            if not fallback:
                raise
    if not fallback:
        raise RuntimeError(f'fallback is disabled and native sendfile is not supported for transport {transport!r}')
    return await self._sendfile_fallback(transport, file, offset, count)

async def _ensure_resolved(self, address, *, family=0, type=socket.SOCK_STREAM, proto=0, flags=0, loop):
    host, port = address[:2]
    info = _ipaddr_info(host, port, family, type, proto, *address[2:])
    if info is not None:
        return [info]
    else:
        return await loop.getaddrinfo(host, port, family=family, type=type, proto=proto, flags=flags)

async def connect_accepted_socket(self, protocol_factory, sock, *, ssl=None, ssl_handshake_timeout=None, ssl_shutdown_timeout=None):
    if sock.type != socket.SOCK_STREAM:
        raise ValueError(f'A Stream Socket was expected, got {sock!r}')
    if ssl_handshake_timeout is not None and (not ssl):
        raise ValueError('ssl_handshake_timeout is only meaningful with ssl')
    if ssl_shutdown_timeout is not None and (not ssl):
        raise ValueError('ssl_shutdown_timeout is only meaningful with ssl')
    if sock is not None:
        _check_ssl_socket(sock)
    transport, protocol = await self._create_connection_transport(sock, protocol_factory, ssl, '', server_side=True, ssl_handshake_timeout=ssl_handshake_timeout, ssl_shutdown_timeout=ssl_shutdown_timeout)
    if self._debug:
        sock = transport.get_extra_info('socket')
        logger.debug('%r handled: (%r, %r)', sock, transport, protocol)
    return (transport, protocol)

async def connect_read_pipe(self, protocol_factory, pipe):
    protocol = protocol_factory()
    waiter = self.create_future()
    transport = self._make_read_pipe_transport(pipe, protocol, waiter)
    try:
        await waiter
    except:
        transport.close()
        raise
    if self._debug:
        logger.debug('Read pipe %r connected: (%r, %r)', pipe.fileno(), transport, protocol)
    return (transport, protocol)

async def connect_write_pipe(self, protocol_factory, pipe):
    protocol = protocol_factory()
    waiter = self.create_future()
    transport = self._make_write_pipe_transport(pipe, protocol, waiter)
    try:
        await waiter
    except:
        transport.close()
        raise
    if self._debug:
        logger.debug('Write pipe %r connected: (%r, %r)', pipe.fileno(), transport, protocol)
    return (transport, protocol)

def _log_subprocess(self, msg, stdin, stdout, stderr):
    info = [msg]
    if stdin is not None:
        info.append(f'stdin={_format_pipe(stdin)}')
    if stdout is not None and stderr == subprocess.STDOUT:
        info.append(f'stdout=stderr={_format_pipe(stdout)}')
    else:
        if stdout is not None:
            info.append(f'stdout={_format_pipe(stdout)}')
        if stderr is not None:
            info.append(f'stderr={_format_pipe(stderr)}')
    logger.debug(' '.join(info))

async def subprocess_shell(self, protocol_factory, cmd, *, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, universal_newlines=False, shell=True, bufsize=0, encoding=None, errors=None, text=None, **kwargs):
    if not isinstance(cmd, (bytes, str)):
        raise ValueError('cmd must be a string')
    if universal_newlines:
        raise ValueError('universal_newlines must be False')
    if not shell:
        raise ValueError('shell must be True')
    if bufsize != 0:
        raise ValueError('bufsize must be 0')
    if text:
        raise ValueError('text must be False')
    if encoding is not None:
        raise ValueError('encoding must be None')
    if errors is not None:
        raise ValueError('errors must be None')
    protocol = protocol_factory()
    debug_log = None
    if self._debug:
        debug_log = 'run shell command %r' % cmd
        self._log_subprocess(debug_log, stdin, stdout, stderr)
    transport = await self._make_subprocess_transport(protocol, cmd, True, stdin, stdout, stderr, bufsize, **kwargs)
    if self._debug and debug_log is not None:
        logger.info('%s: %r', debug_log, transport)
    return (transport, protocol)

async def subprocess_exec(self, protocol_factory, program, *args, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, universal_newlines=False, shell=False, bufsize=0, encoding=None, errors=None, text=None, **kwargs):
    if universal_newlines:
        raise ValueError('universal_newlines must be False')
    if shell:
        raise ValueError('shell must be False')
    if bufsize != 0:
        raise ValueError('bufsize must be 0')
    if text:
        raise ValueError('text must be False')
    if encoding is not None:
        raise ValueError('encoding must be None')
    if errors is not None:
        raise ValueError('errors must be None')
    popen_args = (program,) + args
    protocol = protocol_factory()
    debug_log = None
    if self._debug:
        debug_log = f'execute program {program!r}'
        self._log_subprocess(debug_log, stdin, stdout, stderr)
    transport = await self._make_subprocess_transport(protocol, popen_args, False, stdin, stdout, stderr, bufsize, **kwargs)
    if self._debug and debug_log is not None:
        logger.info('%s: %r', debug_log, transport)
    return (transport, protocol)

def _add_callback(self, handle):
    """Add a Handle to _ready."""
    if not handle._cancelled:
        self._ready.append(handle)

def _set_coroutine_origin_tracking(self, enabled):
    if bool(enabled) == bool(self._coroutine_origin_tracking_enabled):
        return
    if enabled:
        self._coroutine_origin_tracking_saved_depth = sys.get_coroutine_origin_tracking_depth()
        sys.set_coroutine_origin_tracking_depth(constants.DEBUG_STACK_DEPTH)
    else:
        sys.set_coroutine_origin_tracking_depth(self._coroutine_origin_tracking_saved_depth)
    self._coroutine_origin_tracking_enabled = enabled

def set_debug(self, enabled):
    self._debug = enabled
    if self.is_running():
        self.call_soon_threadsafe(self._set_coroutine_origin_tracking, enabled)

def _format_callbacks(cb):
    """helper function for Future.__repr__"""
    size = len(cb)
    if not size:
        cb = ''
    def format_cb(callback):
        return format_helpers._format_callback_source(callback, ())
    if size == 1:
        cb = format_cb(cb[0][0])
    elif size == 2:
        cb = '{}, {}'.format(format_cb(cb[0][0]), format_cb(cb[1][0]))
    elif size > 2:
        cb = '{}, <{} more>, {}'.format(format_cb(cb[0][0]), size - 2, format_cb(cb[-1][0]))
    return f'cb=[{cb}]'

def _future_repr_info(future):
    """helper function for Future.__repr__"""
    info = [future._state.lower()]
    if future._state == _FINISHED:
        if future._exception is not None:
            info.append(f'exception={future._exception!r}')
        else:
            result = reprlib.repr(future._result)
            info.append(f'result={result}')
    if future._callbacks:
        info.append(_format_callbacks(future._callbacks))
    if future._source_traceback:
        frame = future._source_traceback[-1]
        info.append(f'created at {frame[0]}:{frame[1]}')
    return info

@reprlib.recursive_repr()
def _future_repr(future):
    info = ' '.join(_future_repr_info(future))
    return f'<{future.__class__.__name__} {info}>'

def __init__(self, loop, protocol, args, shell, stdin, stdout, stderr, bufsize, waiter=None, extra=None, **kwargs):
    super().__init__(extra)
    self._closed = False
    self._protocol = protocol
    self._loop = loop
    self._proc = None
    self._pid = None
    self._returncode = None
    self._exit_waiters = []
    self._pending_calls = collections.deque()
    self._pipes = {}
    self._finished = False
    if stdin == subprocess.PIPE:
        self._pipes[0] = None
    if stdout == subprocess.PIPE:
        self._pipes[1] = None
    if stderr == subprocess.PIPE:
        self._pipes[2] = None
    try:
        self._start(args=args, shell=shell, stdin=stdin, stdout=stdout, stderr=stderr, bufsize=bufsize, **kwargs)
    except:
        self.close()
        raise
    self._pid = self._proc.pid
    self._extra['subprocess'] = self._proc
    if self._loop.get_debug():
        if isinstance(args, (bytes, str)):
            program = args
        else:
            program = args[0]
        logger.debug('process %r created: pid %s', program, self._pid)
    self._loop.create_task(self._connect_pipes(waiter))

def __repr__(self):
    info = [self.__class__.__name__]
    if self._closed:
        info.append('closed')
    if self._pid is not None:
        info.append(f'pid={self._pid}')
    if self._returncode is not None:
        info.append(f'returncode={self._returncode}')
    elif self._pid is not None:
        info.append('running')
    else:
        info.append('not started')
    stdin = self._pipes.get(0)
    if stdin is not None:
        info.append(f'stdin={stdin.pipe}')
    stdout = self._pipes.get(1)
    stderr = self._pipes.get(2)
    if stdout is not None and stderr is stdout:
        info.append(f'stdout=stderr={stdout.pipe}')
    else:
        if stdout is not None:
            info.append(f'stdout={stdout.pipe}')
        if stderr is not None:
            info.append(f'stderr={stderr.pipe}')
    return '<{}>'.format(' '.join(info))

def close(self):
    if self._closed:
        return
    self._closed = True
    for proto in self._pipes.values():
        if proto is None:
            continue
        proto.pipe.close()
    if self._proc is not None and self._returncode is None and (self._proc.poll() is None):
        if self._loop.get_debug():
            logger.warning('Close running child process: kill %r', self)
        try:
            self._proc.kill()
        except ProcessLookupError:
            pass

def __del__(self, _warn=warnings.warn):
    if not self._closed:
        _warn(f'unclosed transport {self!r}', ResourceWarning, source=self)
        self.close()

def get_pipe_transport(self, fd):
    if fd in self._pipes:
        return self._pipes[fd].pipe
    else:
        return None

def _check_proc(self):
    if self._proc is None:
        raise ProcessLookupError()

def send_signal(self, signal):
    self._check_proc()
    self._proc.send_signal(signal)

def terminate(self):
    self._check_proc()
    self._proc.terminate()

def kill(self):
    self._check_proc()
    self._proc.kill()

def _call(self, cb, *data):
    if self._pending_calls is not None:
        self._pending_calls.append((cb, data))
    else:
        self._loop.call_soon(cb, *data)

def _pipe_connection_lost(self, fd, exc):
    self._call(self._protocol.pipe_connection_lost, fd, exc)
    self._try_finish()

def _process_exited(self, returncode):
    assert returncode is not None, returncode
    assert self._returncode is None, self._returncode
    if self._loop.get_debug():
        logger.info('%r exited with return code %r', self, returncode)
    self._returncode = returncode
    if self._proc.returncode is None:
        self._proc.returncode = returncode
    self._call(self._protocol.process_exited)
    self._try_finish()

def _try_finish(self):
    assert not self._finished
    if self._returncode is None:
        return
    if all((p is not None and p.disconnected for p in self._pipes.values())):
        self._finished = True
        self._call(self._call_connection_lost, None)

def _call_connection_lost(self, exc):
    try:
        self._protocol.connection_lost(exc)
    finally:
        for waiter in self._exit_waiters:
            if not waiter.cancelled():
                waiter.set_result(self._returncode)
        self._exit_waiters = None
        self._loop = None
        self._proc = None
        self._protocol = None

def _task_repr_info(task):
    info = base_futures._future_repr_info(task)
    if task.cancelling() and (not task.done()):
        info[0] = 'cancelling'
    info.insert(1, 'name=%r' % task.get_name())
    if task._fut_waiter is not None:
        info.insert(2, f'wait_for={task._fut_waiter!r}')
    if task._coro:
        coro = coroutines._format_coroutine(task._coro)
        info.insert(2, f'coro=<{coro}>')
    return info

@reprlib.recursive_repr()
def _task_repr(task):
    info = ' '.join(_task_repr_info(task))
    return f'<{task.__class__.__name__} {info}>'

def _task_get_stack(task, limit):
    frames = []
    if hasattr(task._coro, 'cr_frame'):
        f = task._coro.cr_frame
    elif hasattr(task._coro, 'gi_frame'):
        f = task._coro.gi_frame
    elif hasattr(task._coro, 'ag_frame'):
        f = task._coro.ag_frame
    else:
        f = None
    if f is not None:
        while f is not None:
            if limit is not None:
                if limit <= 0:
                    break
                limit -= 1
            frames.append(f)
            f = f.f_back
        frames.reverse()
    elif task._exception is not None:
        tb = task._exception.__traceback__
        while tb is not None:
            if limit is not None:
                if limit <= 0:
                    break
                limit -= 1
            frames.append(tb.tb_frame)
            tb = tb.tb_next
    return frames

def _task_print_stack(task, limit, file):
    extracted_list = []
    checked = set()
    for f in task.get_stack(limit=limit):
        lineno = f.f_lineno
        co = f.f_code
        filename = co.co_filename
        name = co.co_name
        if filename not in checked:
            checked.add(filename)
            linecache.checkcache(filename)
        line = linecache.getline(filename, lineno, f.f_globals)
        extracted_list.append((filename, lineno, name, line))
    exc = task._exception
    if not extracted_list:
        print(f'No stack for {task!r}', file=file)
    elif exc is not None:
        print(f'Traceback for {task!r} (most recent call last):', file=file)
    else:
        print(f'Stack for {task!r} (most recent call last):', file=file)
    traceback.print_list(extracted_list, file=file)
    if exc is not None:
        for line in traceback.format_exception_only(exc.__class__, exc):
            print(line, file=file, end='')

def iscoroutinefunction(func):
