        return get_loop()
    return fut._loop

def _set_result_unless_cancelled(fut, result):
    """Helper setting the result only if the future was not cancelled."""
    if fut.cancelled():
        return
    fut.set_result(result)

def _convert_future_exc(exc):
    exc_class = type(exc)
    if exc_class is concurrent.futures.CancelledError:
        return exceptions.CancelledError(*exc.args)
    elif exc_class is concurrent.futures.TimeoutError:
        return exceptions.TimeoutError(*exc.args)
    elif exc_class is concurrent.futures.InvalidStateError:
        return exceptions.InvalidStateError(*exc.args)
    else:
        return exc

def _set_concurrent_future_state(concurrent, source):
    """Copy state from a future to a concurrent.futures.Future."""
    assert source.done()
    if source.cancelled():
        concurrent.cancel()
    if not concurrent.set_running_or_notify_cancel():
        return
    exception = source.exception()
    if exception is not None:
        concurrent.set_exception(_convert_future_exc(exception))
    else:
        result = source.result()
        concurrent.set_result(result)

def _copy_future_state(source, dest):
    """Internal helper to copy state from another Future.

    The other Future may be a concurrent.futures.Future."""
    assert source.done()
    if dest.cancelled():
        return
    assert not dest.done()
    if source.cancelled():
        dest.cancel()
    else:
        exception = source.exception()
        if exception is not None:
            dest.set_exception(_convert_future_exc(exception))
        else:
            result = source.result()
            dest.set_result(result)

def _chain_future(source, destination):
    """Chain two futures so that when one completes, so does the other.

    The result (or exception) of source will be copied to destination.
    If destination is cancelled, source gets cancelled too.
    Compatible with both asyncio.Future and concurrent.futures.Future."""
    if not isfuture(source) and (not isinstance(source, concurrent.futures.Future)):
        raise TypeError('A future is required for source argument')
    if not isfuture(destination) and (not isinstance(destination, concurrent.futures.Future)):
        raise TypeError('A future is required for destination argument')
    source_loop = _get_loop(source) if isfuture(source) else None
    dest_loop = _get_loop(destination) if isfuture(destination) else None
    def _set_state(future, other):
        if isfuture(future):
            _copy_future_state(other, future)
        else:
            _set_concurrent_future_state(future, other)
    def _call_check_cancel(destination):
        if destination.cancelled():
            if source_loop is None or source_loop is dest_loop:
                source.cancel()
            else:
                source_loop.call_soon_threadsafe(source.cancel)
    def _call_set_state(source):
        if destination.cancelled() and dest_loop is not None and dest_loop.is_closed():
            return
        if dest_loop is None or dest_loop is source_loop:
            _set_state(destination, source)
        else:
            if dest_loop.is_closed():
                return
            dest_loop.call_soon_threadsafe(_set_state, destination, source)
    destination.add_done_callback(_call_check_cancel)
    source.add_done_callback(_call_set_state)

def wrap_future(future, *, loop=None):
    """Wrap concurrent.futures.Future object."""
    if isfuture(future):
        return future
    assert isinstance(future, concurrent.futures.Future), f'concurrent.futures.Future is expected, got {future!r}'
    if loop is None:
        loop = events.get_event_loop()
    new_future = loop.create_future()
    _chain_future(future, new_future)
    return new_future

def __init__(self, *, loop=None):
    """Initialize the future.

    The optional event_loop argument allows explicitly setting the event
    loop object used by the future. If it's not provided, the future uses
    the default event loop."""
    if loop is None:
        self._loop = events.get_event_loop()
    else:
        self._loop = loop
    self._callbacks = []
    if self._loop.get_debug():
        self._source_traceback = format_helpers.extract_stack(sys._getframe(1))

def __del__(self):
    if not self.__log_traceback:
        return
    exc = self._exception
    context = {'message': f'{self.__class__.__name__} exception was never retrieved', 'exception': exc, 'future': self}
    if self._source_traceback:
        context['source_traceback'] = self._source_traceback
    self._loop.call_exception_handler(context)

@property
def _log_traceback(self):
    return self.__log_traceback

@_log_traceback.setter
def _log_traceback(self, val):
    if val:
        raise ValueError('_log_traceback can only be set to False')
    self.__log_traceback = False

def __schedule_callbacks(self):
    """Internal: Ask the event loop to call all callbacks.

    The callbacks are scheduled to be called as soon as possible. Also
    clears the callback list."""
    callbacks = self._callbacks[:]
    if not callbacks:
        return
    self._callbacks[:] = []
    for callback, ctx in callbacks:
        self._loop.call_soon(callback, self, context=ctx)

def cancelled(self):
    """Return True if the future was cancelled."""
    return self._state == _CANCELLED

def result(self):
    """Return the result this future represents.

    If the future has been cancelled, raises CancelledError.  If the
    future's result isn't yet available, raises InvalidStateError.  If
    the future is done and has an exception set, this exception is raised."""
    if self._state == _CANCELLED:
        raise self._make_cancelled_error()
    if self._state != _FINISHED:
        raise exceptions.InvalidStateError('Result is not ready.')
    self.__log_traceback = False
    if self._exception is not None:
        raise self._exception.with_traceback(self._exception_tb)
    return self._result

def add_done_callback(self, fn, *, context=None):
    """Add a callback to be run when the future becomes done.

    The callback is called with a single argument - the future object. If
    the future is already done when this is called, the callback is
    scheduled with call_soon."""
    if self._state != _PENDING:
        self._loop.call_soon(fn, self, context=context)
    else:
        if context is None:
            context = contextvars.copy_context()
        self._callbacks.append((fn, context))

def __await__(self):
    if not self.done():
        self._asyncio_future_blocking = True
        yield self
    if not self.done():
        raise RuntimeError("await wasn't used with future")
    return self.result()

def _set_state(future, other):
    if isfuture(future):
        _copy_future_state(other, future)
    else:
        _set_concurrent_future_state(future, other)

def _call_check_cancel(destination):
    if destination.cancelled():
        if source_loop is None or source_loop is dest_loop:
            source.cancel()
        else:
            source_loop.call_soon_threadsafe(source.cancel)

def _call_set_state(source):
    if destination.cancelled() and dest_loop is not None and dest_loop.is_closed():
        return
    if dest_loop is None or dest_loop is source_loop:
        _set_state(destination, source)
    else:
        if dest_loop.is_closed():
            return
        dest_loop.call_soon_threadsafe(_set_state, destination, source)

def __repr__(self):
    res = super().__repr__()
    extra = 'locked' if self._locked else 'unlocked'
    if self._waiters:
        extra = f'{extra}, waiters:{len(self._waiters)}'
    return f'<{res[1:-1]} [{extra}]>'

def locked(self):
    """Return True if lock is acquired."""
    return self._locked

def _wake_up_first(self):
    """Wake up the first waiter if it isn't done."""
    if not self._waiters:
        return
    try:
        fut = next(iter(self._waiters))
    except StopIteration:
        return
    if not fut.done():
        fut.set_result(True)

def __init__(self):
    self._waiters = collections.deque()
    self._value = False

def __repr__(self):
    res = super().__repr__()
    extra = 'set' if self._value else 'unset'
    if self._waiters:
        extra = f'{extra}, waiters:{len(self._waiters)}'
    return f'<{res[1:-1]} [{extra}]>'

def is_set(self):
    """Return True if and only if the internal flag is true."""
    return self._value

def set(self):
    """Set the internal flag to true. All coroutines waiting for it to
    become true are awakened. Coroutine that call wait() once the flag is
    true will not block at all."""
    if not self._value:
        self._value = True
        for fut in self._waiters:
            if not fut.done():
                fut.set_result(True)

def __repr__(self):
    res = super().__repr__()
    extra = 'locked' if self.locked() else 'unlocked'
    if self._waiters:
        extra = f'{extra}, waiters:{len(self._waiters)}'
    return f'<{res[1:-1]} [{extra}]>'

def __init__(self, value=1):
    if value < 0:
        raise ValueError('Semaphore initial value must be >= 0')
    self._waiters = None
    self._value = value

def __repr__(self):
    res = super().__repr__()
    extra = 'locked' if self.locked() else f'unlocked, value:{self._value}'
    if self._waiters:
        extra = f'{extra}, waiters:{len(self._waiters)}'
    return f'<{res[1:-1]} [{extra}]>'

def locked(self):
    """Returns True if semaphore cannot be acquired immediately."""
    return self._value == 0 or any((not w.cancelled() for w in self._waiters or ()))

def _wake_up_next(self):
    """Wake up the first waiter that isn't done."""
    if not self._waiters:
        return
    for fut in self._waiters:
        if not fut.done():
            self._value -= 1
            fut.set_result(True)
            return

def __init__(self, value=1):
    self._bound_value = value
    super().__init__(value)

def release(self):
    if self._value >= self._bound_value:
        raise ValueError('BoundedSemaphore released too many times')
    super().release()

def __repr__(self):
    res = super().__repr__()
    extra = f'{self._state.value}'
    if not self.broken:
        extra += f', waiters:{self.n_waiting}/{self.parties}'
    return f'<{res[1:-1]} [{extra}]>'

def _exit(self):
    if self._count == 0:
        if self._state in (_BarrierState.RESETTING, _BarrierState.DRAINING):
            self._state = _BarrierState.FILLING
        self._cond.notify_all()

@property
def parties(self):
    """Return the number of tasks required to trip the barrier."""
    return self._parties

@property
def broken(self):
    """Return True if the barrier is in a broken state."""
    return self._state is _BarrierState.BROKEN

def _get_loop(self):
    loop = events._get_running_loop()
    if self._loop is None:
        with _global_lock:
            if self._loop is None:
                self._loop = loop
    if loop is not self._loop:
        raise RuntimeError(f'{self!r} is bound to a different event loop')
    return loop

def _set_socket_extra(transport, sock):
    transport._extra['socket'] = trsock.TransportSocket(sock)
    try:
        transport._extra['sockname'] = sock.getsockname()
    except socket.error:
        if transport._loop.get_debug():
            logger.warning('getsockname() failed on %r', sock, exc_info=True)
    if 'peername' not in transport._extra:
        try:
            transport._extra['peername'] = sock.getpeername()
        except socket.error:
            transport._extra['peername'] = None

def __repr__(self):
    info = [self.__class__.__name__]
    if self._sock is None:
        info.append('closed')
    elif self._closing:
        info.append('closing')
    if self._sock is not None:
        info.append(f'fd={self._sock.fileno()}')
    if self._read_fut is not None:
        info.append(f'read={self._read_fut!r}')
    if self._write_fut is not None:
        info.append(f'write={self._write_fut!r}')
    if self._buffer:
        info.append(f'write_bufsize={len(self._buffer)}')
    if self._eof_written:
        info.append('EOF written')
    return '<{}>'.format(' '.join(info))

def close(self):
    if self._closing:
        return
    self._closing = True
    self._conn_lost += 1
    if not self._buffer and self._write_fut is None:
        self._loop.call_soon(self._call_connection_lost, None)
    if self._read_fut is not None:
        self._read_fut.cancel()
        self._read_fut = None

def __del__(self, _warn=warnings.warn):
    if self._sock is not None:
        _warn(f'unclosed transport {self!r}', ResourceWarning, source=self)
        self._sock.close()

def _fatal_error(self, exc, message='Fatal error on pipe transport'):
    try:
        if isinstance(exc, OSError):
            if self._loop.get_debug():
                logger.debug('%r: %s', self, message, exc_info=True)
        else:
            self._loop.call_exception_handler({'message': message, 'exception': exc, 'transport': self, 'protocol': self._protocol})
    finally:
        self._force_close(exc)

def _force_close(self, exc):
    if self._empty_waiter is not None and (not self._empty_waiter.done()):
        if exc is None:
            self._empty_waiter.set_result(None)
        else:
            self._empty_waiter.set_exception(exc)
    if self._closing and self._called_connection_lost:
        return
    self._closing = True
    self._conn_lost += 1
    if self._write_fut:
        self._write_fut.cancel()
        self._write_fut = None
    if self._read_fut:
        self._read_fut.cancel()
        self._read_fut = None
    self._pending_write = 0
    self._buffer = None
    self._loop.call_soon(self._call_connection_lost, exc)

def _call_connection_lost(self, exc):
    if self._called_connection_lost:
        return
    try:
        self._protocol.connection_lost(exc)
    finally:
        if hasattr(self._sock, 'shutdown') and self._sock.fileno() != -1:
            self._sock.shutdown(socket.SHUT_RDWR)
        self._sock.close()
        self._sock = None
        server = self._server
        if server is not None:
            server._detach()
            self._server = None
        self._called_connection_lost = True

def get_write_buffer_size(self):
    size = self._pending_write
    if self._buffer is not None:
        size += len(self._buffer)
    return size

def pause_reading(self):
    if self._closing or self._paused:
        return
    self._paused = True
    if self._loop.get_debug():
        logger.debug('%r pauses reading', self)

def resume_reading(self):
    if self._closing or not self._paused:
        return
    self._paused = False
    if self._read_fut is None:
        self._loop.call_soon(self._loop_reading, None)
    length = self._pending_data_length
    self._pending_data_length = -1
    if length > -1:
        self._loop.call_soon(self._data_received, self._data[:length], length)
    if self._loop.get_debug():
        logger.debug('%r resumes reading', self)

def _eof_received(self):
    if self._loop.get_debug():
        logger.debug('%r received EOF', self)
    try:
        keep_open = self._protocol.eof_received()
    except (SystemExit, KeyboardInterrupt):
        raise
    except BaseException as exc:
        self._fatal_error(exc, 'Fatal error: protocol.eof_received() call failed.')
        return
    if not keep_open:
        self.close()

def _data_received(self, data, length):
    if self._paused:
        assert self._pending_data_length == -1
        self._pending_data_length = length
        return
    if length == 0:
        self._eof_received()
        return
    if isinstance(self._protocol, protocols.BufferedProtocol):
        try:
            protocols._feed_data_to_buffered_proto(self._protocol, data)
        except (SystemExit, KeyboardInterrupt):
            raise
        except BaseException as exc:
            self._fatal_error(exc, 'Fatal error: protocol.buffer_updated() call failed.')
            return
    else:
        self._protocol.data_received(data)

def _loop_reading(self, fut=None):
    length = -1
    data = None
    try:
        if fut is not None:
            assert self._read_fut is fut or (self._read_fut is None and self._closing)
            self._read_fut = None
            if fut.done():
                length = fut.result()
                if length == 0:
                    return
                data = bytes(memoryview(self._data)[:length])
            else:
                fut.cancel()
        if self._closing:
            return
        if not self._paused:
            self._read_fut = self._loop._proactor.recv_into(self._sock, self._data)
    except ConnectionAbortedError as exc:
        if not self._closing:
            self._fatal_error(exc, 'Fatal read error on pipe transport')
        elif self._loop.get_debug():
            logger.debug('Read error on pipe transport while closing', exc_info=True)
    except ConnectionResetError as exc:
        self._force_close(exc)
    except OSError as exc:
        self._fatal_error(exc, 'Fatal read error on pipe transport')
    except exceptions.CancelledError:
        if not self._closing:
            raise
    else:
        if not self._paused:
            self._read_fut.add_done_callback(self._loop_reading)
    finally:
        if length > -1:
            self._data_received(data, length)

def __init__(self, *args, **kw):
    super().__init__(*args, **kw)
    self._empty_waiter = None

def write(self, data):
    if not isinstance(data, (bytes, bytearray, memoryview)):
        raise TypeError(f'data argument must be a bytes-like object, not {type(data).__name__}')
    if self._eof_written:
        raise RuntimeError('write_eof() already called')
    if self._empty_waiter is not None:
        raise RuntimeError('unable to write; sendfile is in progress')
    if not data:
        return
    if self._conn_lost:
        if self._conn_lost >= constants.LOG_THRESHOLD_FOR_CONNLOST_WRITES:
            logger.warning('socket.send() raised exception.')
        self._conn_lost += 1
        return
    if self._write_fut is None:
        assert self._buffer is None
        self._loop_writing(data=bytes(data))
    elif not self._buffer:
        self._buffer = bytearray(data)
        self._maybe_pause_protocol()
    else:
        self._buffer.extend(data)
        self._maybe_pause_protocol()

def _make_empty_waiter(self):
    if self._empty_waiter is not None:
        raise RuntimeError('Empty waiter is already set')
    self._empty_waiter = self._loop.create_future()
    if self._write_fut is None:
        self._empty_waiter.set_result(None)
    return self._empty_waiter

def _pipe_closed(self, fut):
    if fut.cancelled():
        return
    assert fut.result() == b''
    if self._closing:
        assert self._read_fut is None
        return
    assert fut is self._read_fut, (fut, self._read_fut)
    self._read_fut = None
    if self._write_fut is not None:
        self._force_close(BrokenPipeError())
    else:
        self.close()

def sendto(self, data, addr=None):
    if not isinstance(data, (bytes, bytearray, memoryview)):
        raise TypeError('data argument must be bytes-like object (%r)', type(data))
    if not data:
        return
    if self._address is not None and addr not in (None, self._address):
        raise ValueError(f'Invalid address: must be None or {self._address}')
    if self._conn_lost and self._address:
        if self._conn_lost >= constants.LOG_THRESHOLD_FOR_CONNLOST_WRITES:
            logger.warning('socket.sendto() raised exception.')
        self._conn_lost += 1
        return
    self._buffer.append((bytes(data), addr))
    self._buffer_size += len(data)
    if self._write_fut is None:
        self._loop_writing()
    self._maybe_pause_protocol()

def _loop_writing(self, fut=None):
    try:
        if self._conn_lost:
            return
        assert fut is self._write_fut
        self._write_fut = None
        if fut:
            fut.result()
        if not self._buffer or (self._conn_lost and self._address):
            if self._closing:
                self._loop.call_soon(self._call_connection_lost, None)
            return
        data, addr = self._buffer.popleft()
        self._buffer_size -= len(data)
        if self._address is not None:
            self._write_fut = self._loop._proactor.send(self._sock, data)
        else:
            self._write_fut = self._loop._proactor.sendto(self._sock, data, addr=addr)
    except OSError as exc:
        self._protocol.error_received(exc)
    except Exception as exc:
        self._fatal_error(exc, 'Fatal write error on datagram transport')
    else:
        self._write_fut.add_done_callback(self._loop_writing)
        self._maybe_resume_protocol()

def _loop_reading(self, fut=None):
    data = None
    try:
        if self._conn_lost:
            return
        assert self._read_fut is fut or (self._read_fut is None and self._closing)
        self._read_fut = None
        if fut is not None:
            res = fut.result()
            if self._closing:
                data = None
                return
            if self._address is not None:
                data, addr = (res, self._address)
            else:
                data, addr = res
        if self._conn_lost:
            return
        if self._address is not None:
            self._read_fut = self._loop._proactor.recv(self._sock, self.max_size)
        else:
            self._read_fut = self._loop._proactor.recvfrom(self._sock, self.max_size)
    except OSError as exc:
        self._protocol.error_received(exc)
    except exceptions.CancelledError:
        if not self._closing:
            raise
    else:
        if self._read_fut is not None:
            self._read_fut.add_done_callback(self._loop_reading)
    finally:
        if data:
            self._protocol.datagram_received(data, addr)

def __init__(self, loop, sock, protocol, waiter=None, extra=None, server=None):
    super().__init__(loop, sock, protocol, waiter, extra, server)
    base_events._set_nodelay(sock)

def write_eof(self):
    if self._closing or self._eof_written:
        return
    self._eof_written = True
    if self._write_fut is None:
        self._sock.shutdown(socket.SHUT_WR)

def close(self):
    if self.is_running():
        raise RuntimeError('Cannot close a running event loop')
    if self.is_closed():
        return
    if threading.current_thread() is threading.main_thread():
        signal.set_wakeup_fd(-1)
    self._stop_accept_futures()
    self._close_self_pipe()
    self._proactor.close()
    self._proactor = None
    self._selector = None
    super().close()

async def sock_recvfrom_into(self, sock, buf, nbytes=0):
    if not nbytes:
        nbytes = len(buf)
    return await self._proactor.recvfrom_into(sock, buf, nbytes)

async def sock_connect(self, sock, address):
    if self._debug and sock.gettimeout() != 0:
        raise ValueError('the socket must be non-blocking')
    return await self._proactor.connect(sock, address)

async def _sock_sendfile_native(self, sock, file, offset, count):
    try:
        fileno = file.fileno()
    except (AttributeError, io.UnsupportedOperation) as err:
        raise exceptions.SendfileNotAvailableError('not a regular file')
    try:
        fsize = os.fstat(fileno).st_size
    except OSError:
        raise exceptions.SendfileNotAvailableError('not a regular file')
    blocksize = count if count else fsize
    if not blocksize:
        return 0
    blocksize = min(blocksize, 4294967295)
    end_pos = min(offset + count, fsize) if count else fsize
    offset = min(offset, fsize)
    total_sent = 0
    try:
        while True:
            blocksize = min(end_pos - offset, blocksize)
            if blocksize <= 0:
                return total_sent
            await self._proactor.sendfile(sock, file, offset, blocksize)
            offset += blocksize
            total_sent += blocksize
    finally:
        if total_sent > 0:
            file.seek(offset)

async def _sendfile_native(self, transp, file, offset, count):
    resume_reading = transp.is_reading()
    transp.pause_reading()
    await transp._make_empty_waiter()
    try:
        return await self.sock_sendfile(transp._sock, file, offset, count, fallback=False)
    finally:
        transp._reset_empty_waiter()
        if resume_reading:
            transp.resume_reading()

def _loop_self_reading(self, f=None):
    try:
        if f is not None:
            f.result()
        if self._self_reading_future is not f:
            return
        f = self._proactor.recv(self._ssock, 4096)
    except exceptions.CancelledError:
        return
    except (SystemExit, KeyboardInterrupt):
        raise
    except BaseException as exc:
        self.call_exception_handler({'message': 'Error on reading from the event loop self pipe', 'exception': exc, 'loop': self})
    else:
        self._self_reading_future = f
        f.add_done_callback(self._loop_self_reading)

def _write_to_self(self):
    csock = self._csock
    if csock is None:
        return
    try:
        csock.send(b'\x00')
    except OSError:
        if self._debug:
            logger.debug('Fail to write a null byte into the self-pipe socket', exc_info=True)

def _start_serving(self, protocol_factory, sock, sslcontext=None, server=None, backlog=100, ssl_handshake_timeout=None, ssl_shutdown_timeout=None):
    def loop(f=None):
        try:
            if f is not None:
                conn, addr = f.result()
                if self._debug:
                    logger.debug('%r got a new connection from %r: %r', server, addr, conn)
                protocol = protocol_factory()
                if sslcontext is not None:
                    self._make_ssl_transport(conn, protocol, sslcontext, server_side=True, extra={'peername': addr}, server=server, ssl_handshake_timeout=ssl_handshake_timeout, ssl_shutdown_timeout=ssl_shutdown_timeout)
                else:
                    self._make_socket_transport(conn, protocol, extra={'peername': addr}, server=server)
            if self.is_closed():
                return
            f = self._proactor.accept(sock)
        except OSError as exc:
            if sock.fileno() != -1:
                self.call_exception_handler({'message': 'Accept failed on a socket', 'exception': exc, 'socket': trsock.TransportSocket(sock)})
                sock.close()
            elif self._debug:
                logger.debug('Accept failed on socket %r', sock, exc_info=True)
        except exceptions.CancelledError:
            sock.close()
        else:
            self._accept_futures[sock.fileno()] = f
            f.add_done_callback(loop)
    self.call_soon(loop)

def _stop_accept_futures(self):
    for future in self._accept_futures.values():
        future.cancel()
    self._accept_futures.clear()

def _stop_serving(self, sock):
    future = self._accept_futures.pop(sock.fileno(), None)
    if future:
        future.cancel()
    self._proactor._stop_serving(sock)
    sock.close()

def loop(f=None):
    try:
        if f is not None:
            conn, addr = f.result()
            if self._debug:
                logger.debug('%r got a new connection from %r: %r', server, addr, conn)
            protocol = protocol_factory()
            if sslcontext is not None:
                self._make_ssl_transport(conn, protocol, sslcontext, server_side=True, extra={'peername': addr}, server=server, ssl_handshake_timeout=ssl_handshake_timeout, ssl_shutdown_timeout=ssl_shutdown_timeout)
            else:
                self._make_socket_transport(conn, protocol, extra={'peername': addr}, server=server)
        if self.is_closed():
            return
        f = self._proactor.accept(sock)
    except OSError as exc:
        if sock.fileno() != -1:
            self.call_exception_handler({'message': 'Accept failed on a socket', 'exception': exc, 'socket': trsock.TransportSocket(sock)})
            sock.close()
        elif self._debug:
            logger.debug('Accept failed on socket %r', sock, exc_info=True)
    except exceptions.CancelledError:
        sock.close()
    else:
        self._accept_futures[sock.fileno()] = f
        f.add_done_callback(loop)

def _feed_data_to_buffered_proto(proto, data):
    data_len = len(data)
    while data_len:
        buf = proto.get_buffer(data_len)
        buf_len = len(buf)
        if not buf_len:
            raise RuntimeError('get_buffer() returned an empty buffer')
        if buf_len >= data_len:
            buf[:data_len] = data
            proto.buffer_updated(data_len)
            return
        else:
            buf[:buf_len] = data[:buf_len]
            proto.buffer_updated(buf_len)
            data = data[buf_len:]
            data_len = len(data)

def resume_writing(self):
    """Called when the transport's buffer drains below the low-water mark.

    See pause_writing() for details."""

def data_received(self, data):
    """Called when some data is received.

    The argument is a bytes object."""

def error_received(self, exc):
    """Called when a send or receive operation raises an OSError.

    (Other than BlockingIOError or InterruptedError.)"""

def _wakeup_next(self, waiters):
    while waiters:
        waiter = waiters.popleft()
        if not waiter.done():
            waiter.set_result(None)
            break

def qsize(self):
    """Number of items in the queue."""
    return len(self._queue)

@property
def maxsize(self):
    """Number of items allowed in the queue."""
    return self._maxsize

def empty(self):
    """Return True if the queue is empty, False otherwise."""
    return not self._queue

def full(self):
    """Return True if there are maxsize items in the queue.

    Note: if the Queue was initialized with maxsize=0 (the default),
    then full() is never True."""
    if self._maxsize <= 0:
        return False
    else:
        return self.qsize() >= self._maxsize

async def put(self, item):
    """Put an item into the queue.

    Put an item into the queue. If the queue is full, wait until a free
    slot is available before adding item."""
    while self.full():
        putter = self._get_loop().create_future()
        self._putters.append(putter)
        try:
            await putter
        except:
            putter.cancel()
            try:
                self._putters.remove(putter)
            except ValueError:
                pass
            if not self.full() and (not putter.cancelled()):
                self._wakeup_next(self._putters)
            raise
    return self.put_nowait(item)

async def get(self):
    """Remove and return an item from the queue.

    If queue is empty, wait until an item is available."""
    while self.empty():
        getter = self._get_loop().create_future()
        self._getters.append(getter)
        try:
            await getter
        except:
            getter.cancel()
            try:
                self._getters.remove(getter)
            except ValueError:
                pass
            if not self.empty() and (not getter.cancelled()):
                self._wakeup_next(self._getters)
            raise
    return self.get_nowait()

def __enter__(self):
    self._lazy_init()
    return self

def run(self, coro, *, context=None):
    """Run a coroutine inside the embedded event loop."""
    if not coroutines.iscoroutine(coro):
        raise ValueError('a coroutine was expected, got {!r}'.format(coro))
    if events._get_running_loop() is not None:
        raise RuntimeError('Runner.run() cannot be called from a running event loop')
    self._lazy_init()
    if context is None:
        context = self._context
    task = self._loop.create_task(coro, context=context)
    if threading.current_thread() is threading.main_thread() and signal.getsignal(signal.SIGINT) is signal.default_int_handler:
        sigint_handler = functools.partial(self._on_sigint, main_task=task)
        try:
            signal.signal(signal.SIGINT, sigint_handler)
        except ValueError:
            sigint_handler = None
    else:
        sigint_handler = None
    self._interrupt_count = 0
    try:
        return self._loop.run_until_complete(task)
    except exceptions.CancelledError:
        if self._interrupt_count > 0:
            uncancel = getattr(task, 'uncancel', None)
            if uncancel is not None and uncancel() == 0:
                raise KeyboardInterrupt()
        raise
    finally:
        if sigint_handler is not None and signal.getsignal(signal.SIGINT) is sigint_handler:
            signal.signal(signal.SIGINT, signal.default_int_handler)

def _lazy_init(self):
    if self._state is _State.CLOSED:
        raise RuntimeError('Runner is closed')
    if self._state is _State.INITIALIZED:
        return
    if self._loop_factory is None:
        self._loop = events.new_event_loop()
        if not self._set_event_loop:
            events.set_event_loop(self._loop)
            self._set_event_loop = True
    else:
        self._loop = self._loop_factory()
    if self._debug is not None:
        self._loop.set_debug(self._debug)
    self._context = contextvars.copy_context()
    self._state = _State.INITIALIZED

def _test_selector_event(selector, fd, event):
    try:
        key = selector.get_key(fd)
    except KeyError:
        return False
    else:
        return bool(key.events & event)

def _make_socket_transport(self, sock, protocol, waiter=None, *, extra=None, server=None):
    self._ensure_fd_no_transport(sock)
    return _SelectorSocketTransport(self, sock, protocol, waiter, extra, server)

def _make_datagram_transport(self, sock, protocol, address=None, waiter=None, extra=None):
    self._ensure_fd_no_transport(sock)
    return _SelectorDatagramTransport(self, sock, protocol, address, waiter, extra)

def close(self):
    if self.is_running():
        raise RuntimeError('Cannot close a running event loop')
    if self.is_closed():
        return
    self._close_self_pipe()
    super().close()
    if self._selector is not None:
        self._selector.close()
        self._selector = None

def _read_from_self(self):
    while True:
        try:
            data = self._ssock.recv(4096)
            if not data:
                break
            self._process_self_data(data)
        except InterruptedError:
            continue
        except BlockingIOError:
            break

def _accept_connection(self, protocol_factory, sock, sslcontext=None, server=None, backlog=100, ssl_handshake_timeout=constants.SSL_HANDSHAKE_TIMEOUT, ssl_shutdown_timeout=constants.SSL_SHUTDOWN_TIMEOUT):
    for _ in range(backlog):
        try:
            conn, addr = sock.accept()
            if self._debug:
                logger.debug('%r got a new connection from %r: %r', server, addr, conn)
            conn.setblocking(False)
        except (BlockingIOError, InterruptedError, ConnectionAbortedError):
            return None
        except OSError as exc:
            if exc.errno in (errno.EMFILE, errno.ENFILE, errno.ENOBUFS, errno.ENOMEM):
                self.call_exception_handler({'message': 'socket.accept() out of system resource', 'exception': exc, 'socket': trsock.TransportSocket(sock)})
                self._remove_reader(sock.fileno())
                self.call_later(constants.ACCEPT_RETRY_DELAY, self._start_serving, protocol_factory, sock, sslcontext, server, backlog, ssl_handshake_timeout, ssl_shutdown_timeout)
            else:
                raise
        else:
            extra = {'peername': addr}
            accept = self._accept_connection2(protocol_factory, conn, extra, sslcontext, server, ssl_handshake_timeout, ssl_shutdown_timeout)
            self.create_task(accept)

async def _accept_connection2(self, protocol_factory, conn, extra, sslcontext=None, server=None, ssl_handshake_timeout=constants.SSL_HANDSHAKE_TIMEOUT, ssl_shutdown_timeout=constants.SSL_SHUTDOWN_TIMEOUT):
    protocol = None
    transport = None
    try:
        protocol = protocol_factory()
        waiter = self.create_future()
        if sslcontext:
            transport = self._make_ssl_transport(conn, protocol, sslcontext, waiter=waiter, server_side=True, extra=extra, server=server, ssl_handshake_timeout=ssl_handshake_timeout, ssl_shutdown_timeout=ssl_shutdown_timeout)
        else:
            transport = self._make_socket_transport(conn, protocol, waiter=waiter, extra=extra, server=server)
        try:
            await waiter
        except BaseException:
            transport.close()
            waiter = None
            raise
    except (SystemExit, KeyboardInterrupt):
        raise
    except BaseException as exc:
        if self._debug:
            context = {'message': 'Error on transport creation for incoming connection', 'exception': exc}
            if protocol is not None:
                context['protocol'] = protocol
            if transport is not None:
                context['transport'] = transport
            self.call_exception_handler(context)

def _ensure_fd_no_transport(self, fd):
    fileno = fd
    if not isinstance(fileno, int):
        try:
            fileno = int(fileno.fileno())
        except (AttributeError, TypeError, ValueError):
            raise ValueError(f'Invalid file object: {fd!r}') from None
    try:
        transport = self._transports[fileno]
    except KeyError:
        pass
    else:
        if not transport.is_closing():
            raise RuntimeError(f'File descriptor {fd!r} is used by transport {transport!r}')

def _add_reader(self, fd, callback, *args):
    self._check_closed()
    handle = events.Handle(callback, args, self, None)
    try:
        key = self._selector.get_key(fd)
    except KeyError:
        self._selector.register(fd, selectors.EVENT_READ, (handle, None))
    else:
        mask, (reader, writer) = (key.events, key.data)
        self._selector.modify(fd, mask | selectors.EVENT_READ, (handle, writer))
        if reader is not None:
            reader.cancel()
    return handle

def _remove_reader(self, fd):
    if self.is_closed():
        return False
    try:
        key = self._selector.get_key(fd)
    except KeyError:
        return False
    else:
        mask, (reader, writer) = (key.events, key.data)
        mask &= ~selectors.EVENT_READ
        if not mask:
            self._selector.unregister(fd)
        else:
            self._selector.modify(fd, mask, (None, writer))
        if reader is not None:
            reader.cancel()
            return True
        else:
            return False

def _add_writer(self, fd, callback, *args):
    self._check_closed()
    handle = events.Handle(callback, args, self, None)
    try:
        key = self._selector.get_key(fd)
    except KeyError:
        self._selector.register(fd, selectors.EVENT_WRITE, (None, handle))
    else:
        mask, (reader, writer) = (key.events, key.data)
        self._selector.modify(fd, mask | selectors.EVENT_WRITE, (reader, handle))
        if writer is not None:
            writer.cancel()
    return handle

def _remove_writer(self, fd):
    """Remove a writer callback."""
    if self.is_closed():
        return False
    try:
        key = self._selector.get_key(fd)
    except KeyError:
        return False
    else:
        mask, (reader, writer) = (key.events, key.data)
        mask &= ~selectors.EVENT_WRITE
        if not mask:
            self._selector.unregister(fd)
        else:
            self._selector.modify(fd, mask, (reader, None))
        if writer is not None:
            writer.cancel()
            return True
        else:
            return False

def remove_reader(self, fd):
    """Remove a reader callback."""
    self._ensure_fd_no_transport(fd)
    return self._remove_reader(fd)

def remove_writer(self, fd):
    """Remove a writer callback."""
    self._ensure_fd_no_transport(fd)
    return self._remove_writer(fd)

def _sock_read_done(self, fd, fut, handle=None):
    if handle is None or not handle.cancelled():
        self.remove_reader(fd)

def _sock_recv(self, fut, sock, n):
    if fut.done():
        return
    try:
        data = sock.recv(n)
    except (BlockingIOError, InterruptedError):
        return
    except (SystemExit, KeyboardInterrupt):
        raise
    except BaseException as exc:
        fut.set_exception(exc)
    else:
        fut.set_result(data)

def _sock_recv_into(self, fut, sock, buf):
    if fut.done():
        return
    try:
        nbytes = sock.recv_into(buf)
    except (BlockingIOError, InterruptedError):
        return
    except (SystemExit, KeyboardInterrupt):
        raise
    except BaseException as exc:
        fut.set_exception(exc)
    else:
        fut.set_result(nbytes)

def _sock_recvfrom(self, fut, sock, bufsize):
    if fut.done():
        return
    try:
        result = sock.recvfrom(bufsize)
    except (BlockingIOError, InterruptedError):
        return
    except (SystemExit, KeyboardInterrupt):
        raise
    except BaseException as exc:
        fut.set_exception(exc)
    else:
        fut.set_result(result)

def _sock_recvfrom_into(self, fut, sock, buf, bufsize):
    if fut.done():
        return
    try:
        result = sock.recvfrom_into(buf, bufsize)
    except (BlockingIOError, InterruptedError):
        return
    except (SystemExit, KeyboardInterrupt):
        raise
    except BaseException as exc:
        fut.set_exception(exc)
    else:
        fut.set_result(result)

def _sock_sendall(self, fut, sock, view, pos):
    if fut.done():
        return
    start = pos[0]
    try:
        n = sock.send(view[start:])
    except (BlockingIOError, InterruptedError):
        return
    except (SystemExit, KeyboardInterrupt):
        raise
    except BaseException as exc:
        fut.set_exception(exc)
        return
    start += n
    if start == len(view):
        fut.set_result(None)
    else:
        pos[0] = start

def _sock_sendto(self, fut, sock, data, address):
    if fut.done():
        return
    try:
        n = sock.sendto(data, 0, address)
    except (BlockingIOError, InterruptedError):
        return
    except (SystemExit, KeyboardInterrupt):
        raise
    except BaseException as exc:
        fut.set_exception(exc)
    else:
        fut.set_result(n)

def _sock_connect(self, fut, sock, address):
    fd = sock.fileno()
    try:
        sock.connect(address)
    except (BlockingIOError, InterruptedError):
        self._ensure_fd_no_transport(fd)
        handle = self._add_writer(fd, self._sock_connect_cb, fut, sock, address)
        fut.add_done_callback(functools.partial(self._sock_write_done, fd, handle=handle))
    except (SystemExit, KeyboardInterrupt):
        raise
    except BaseException as exc:
        fut.set_exception(exc)
    else:
        fut.set_result(None)
    finally:
        fut = None

def _sock_write_done(self, fd, fut, handle=None):
    if handle is None or not handle.cancelled():
        self.remove_writer(fd)

def _sock_connect_cb(self, fut, sock, address):
    if fut.done():
        return
    try:
        err = sock.getsockopt(socket.SOL_SOCKET, socket.SO_ERROR)
        if err != 0:
            raise OSError(err, f'Connect call failed {address}')
    except (BlockingIOError, InterruptedError):
        pass
    except (SystemExit, KeyboardInterrupt):
        raise
    except BaseException as exc:
        fut.set_exception(exc)
    else:
        fut.set_result(None)
    finally:
        fut = None

def _sock_accept(self, fut, sock):
    fd = sock.fileno()
    try:
        conn, address = sock.accept()
        conn.setblocking(False)
    except (BlockingIOError, InterruptedError):
        self._ensure_fd_no_transport(fd)
        handle = self._add_reader(fd, self._sock_accept, fut, sock)
        fut.add_done_callback(functools.partial(self._sock_read_done, fd, handle=handle))
    except (SystemExit, KeyboardInterrupt):
        raise
    except BaseException as exc:
        fut.set_exception(exc)
    else:
        fut.set_result((conn, address))

def _process_events(self, event_list):
    for key, mask in event_list:
        fileobj, (reader, writer) = (key.fileobj, key.data)
        if mask & selectors.EVENT_READ and reader is not None:
            if reader._cancelled:
                self._remove_reader(fileobj)
            else:
                self._add_callback(reader)
        if mask & selectors.EVENT_WRITE and writer is not None:
            if writer._cancelled:
                self._remove_writer(fileobj)
            else:
                self._add_callback(writer)

def _stop_serving(self, sock):
    self._remove_reader(sock.fileno())
    sock.close()

def __repr__(self):
    info = [self.__class__.__name__]
    if self._sock is None:
        info.append('closed')
    elif self._closing:
        info.append('closing')
    info.append(f'fd={self._sock_fd}')
    if self._loop is not None and (not self._loop.is_closed()):
        polling = _test_selector_event(self._loop._selector, self._sock_fd, selectors.EVENT_READ)
        if polling:
            info.append('read=polling')
        else:
            info.append('read=idle')
        polling = _test_selector_event(self._loop._selector, self._sock_fd, selectors.EVENT_WRITE)
        if polling:
            state = 'polling'
        else:
            state = 'idle'
        bufsize = self.get_write_buffer_size()
        info.append(f'write=<{state}, bufsize={bufsize}>')
    return '<{}>'.format(' '.join(info))

def set_protocol(self, protocol):
    self._protocol = protocol
    self._protocol_connected = True

def pause_reading(self):
    if not self.is_reading():
        return
    self._paused = True
    self._loop._remove_reader(self._sock_fd)
    if self._loop.get_debug():
        logger.debug('%r pauses reading', self)

def resume_reading(self):
    if self._closing or not self._paused:
        return
    self._paused = False
    self._add_reader(self._sock_fd, self._read_ready)
    if self._loop.get_debug():
        logger.debug('%r resumes reading', self)

def close(self):
    if self._closing:
        return
    self._closing = True
    self._loop._remove_reader(self._sock_fd)
    if not self._buffer:
        self._conn_lost += 1
        self._loop._remove_writer(self._sock_fd)
        self._loop.call_soon(self._call_connection_lost, None)

def _fatal_error(self, exc, message='Fatal error on transport'):
    if isinstance(exc, OSError):
        if self._loop.get_debug():
            logger.debug('%r: %s', self, message, exc_info=True)
    else:
        self._loop.call_exception_handler({'message': message, 'exception': exc, 'transport': self, 'protocol': self._protocol})
    self._force_close(exc)

def _call_connection_lost(self, exc):
    try:
        if self._protocol_connected:
            self._protocol.connection_lost(exc)
    finally:
        self._sock.close()
        self._sock = None
        self._protocol = None
        self._loop = None
        server = self._server
        if server is not None:
            server._detach()
            self._server = None

def _add_reader(self, fd, callback, *args):
    if not self.is_reading():
        return
    self._loop._add_reader(fd, callback, *args)

def set_protocol(self, protocol):
    if isinstance(protocol, protocols.BufferedProtocol):
        self._read_ready_cb = self._read_ready__get_buffer
    else:
        self._read_ready_cb = self._read_ready__data_received
    super().set_protocol(protocol)

def _read_ready__get_buffer(self):
    if self._conn_lost:
        return
    try:
        buf = self._protocol.get_buffer(-1)
        if not len(buf):
            raise RuntimeError('get_buffer() returned an empty buffer')
    except (SystemExit, KeyboardInterrupt):
        raise
    except BaseException as exc:
        self._fatal_error(exc, 'Fatal error: protocol.get_buffer() call failed.')
        return
    try:
        nbytes = self._sock.recv_into(buf)
    except (BlockingIOError, InterruptedError):
        return
    except (SystemExit, KeyboardInterrupt):
        raise
    except BaseException as exc:
        self._fatal_error(exc, 'Fatal read error on socket transport')
        return
    if not nbytes:
        self._read_ready__on_eof()
        return
    try:
        self._protocol.buffer_updated(nbytes)
    except (SystemExit, KeyboardInterrupt):
        raise
    except BaseException as exc:
        self._fatal_error(exc, 'Fatal error: protocol.buffer_updated() call failed.')

def _read_ready__data_received(self):
    if self._conn_lost:
        return
    try:
        data = self._sock.recv(self.max_size)
    except (BlockingIOError, InterruptedError):
        return
    except (SystemExit, KeyboardInterrupt):
        raise
    except BaseException as exc:
        self._fatal_error(exc, 'Fatal read error on socket transport')
        return
    if not data:
        self._read_ready__on_eof()
        return
    try:
        self._protocol.data_received(data)
    except (SystemExit, KeyboardInterrupt):
        raise
    except BaseException as exc:
        self._fatal_error(exc, 'Fatal error: protocol.data_received() call failed.')

def _read_ready__on_eof(self):
    if self._loop.get_debug():
        logger.debug('%r received EOF', self)
    try:
        keep_open = self._protocol.eof_received()
    except (SystemExit, KeyboardInterrupt):
        raise
    except BaseException as exc:
        self._fatal_error(exc, 'Fatal error: protocol.eof_received() call failed.')
        return
    if keep_open:
        self._loop._remove_reader(self._sock_fd)
    else:
        self.close()

def write(self, data):
    if not isinstance(data, (bytes, bytearray, memoryview)):
        raise TypeError(f'data argument must be a bytes-like object, not {type(data).__name__!r}')
    if self._eof:
        raise RuntimeError('Cannot call write() after write_eof()')
    if self._empty_waiter is not None:
        raise RuntimeError('unable to write; sendfile is in progress')
    if not data:
        return
    if self._conn_lost:
        if self._conn_lost >= constants.LOG_THRESHOLD_FOR_CONNLOST_WRITES:
            logger.warning('socket.send() raised exception.')
        self._conn_lost += 1
        return
    if not self._buffer:
        try:
            n = self._sock.send(data)
        except (BlockingIOError, InterruptedError):
            pass
        except (SystemExit, KeyboardInterrupt):
            raise
        except BaseException as exc:
            self._fatal_error(exc, 'Fatal write error on socket transport')
            return
        else:
            data = memoryview(data)[n:]
            if not data:
                return
        self._loop._add_writer(self._sock_fd, self._write_ready)
    self._buffer.append(data)
    self._maybe_pause_protocol()

def _write_sendmsg(self):
    assert self._buffer, 'Data should not be empty'
    if self._conn_lost:
        return
    try:
        nbytes = self._sock.sendmsg(self._get_sendmsg_buffer())
        self._adjust_leftover_buffer(nbytes)
    except (BlockingIOError, InterruptedError):
        pass
    except (SystemExit, KeyboardInterrupt):
        raise
    except BaseException as exc:
        self._loop._remove_writer(self._sock_fd)
        self._buffer.clear()
        self._fatal_error(exc, 'Fatal write error on socket transport')
        if self._empty_waiter is not None:
            self._empty_waiter.set_exception(exc)
    else:
        self._maybe_resume_protocol()
        if not self._buffer:
            self._loop._remove_writer(self._sock_fd)
            if self._empty_waiter is not None:
                self._empty_waiter.set_result(None)
            if self._closing:
                self._call_connection_lost(None)
            elif self._eof:
                self._sock.shutdown(socket.SHUT_WR)

def _adjust_leftover_buffer(self, nbytes: int) -> None:
    buffer = self._buffer
    while nbytes:
        b = buffer.popleft()
        b_len = len(b)
        if b_len <= nbytes:
            nbytes -= b_len
        else:
            buffer.appendleft(b[nbytes:])
            break

def write_eof(self):
    if self._closing or self._eof:
        return
    self._eof = True
    if not self._buffer:
        self._sock.shutdown(socket.SHUT_WR)

def writelines(self, list_of_data):
    if self._eof:
        raise RuntimeError('Cannot call writelines() after write_eof()')
    if self._empty_waiter is not None:
        raise RuntimeError('unable to writelines; sendfile is in progress')
    if not list_of_data:
        return
    self._buffer.extend([memoryview(data) for data in list_of_data])
    self._write_ready()
    if self._buffer:
        self._loop._add_writer(self._sock_fd, self._write_ready)
        self._maybe_pause_protocol()

def _call_connection_lost(self, exc):
    try:
        super()._call_connection_lost(exc)
    finally:
        self._write_ready = None
        if self._empty_waiter is not None:
            self._empty_waiter.set_exception(ConnectionError('Connection is closed by peer'))

def close(self):
    self._read_ready_cb = None
    super().close()

def _read_ready(self):
    if self._conn_lost:
        return
    try:
        data, addr = self._sock.recvfrom(self.max_size)
    except (BlockingIOError, InterruptedError):
        pass
    except OSError as exc:
        self._protocol.error_received(exc)
    except (SystemExit, KeyboardInterrupt):
        raise
    except BaseException as exc:
        self._fatal_error(exc, 'Fatal read error on datagram transport')
    else:
        self._protocol.datagram_received(data, addr)

def sendto(self, data, addr=None):
    if not isinstance(data, (bytes, bytearray, memoryview)):
        raise TypeError(f'data argument must be a bytes-like object, not {type(data).__name__!r}')
    if not data:
        return
    if self._address:
        if addr not in (None, self._address):
            raise ValueError(f'Invalid address: must be None or {self._address}')
        addr = self._address
    if self._conn_lost and self._address:
        if self._conn_lost >= constants.LOG_THRESHOLD_FOR_CONNLOST_WRITES:
            logger.warning('socket.send() raised exception.')
        self._conn_lost += 1
        return
    if not self._buffer:
        try:
            if self._extra['peername']:
                self._sock.send(data)
            else:
                self._sock.sendto(data, addr)
            return
        except (BlockingIOError, InterruptedError):
            self._loop._add_writer(self._sock_fd, self._sendto_ready)
        except OSError as exc:
            self._protocol.error_received(exc)
            return
        except (SystemExit, KeyboardInterrupt):
            raise
        except BaseException as exc:
            self._fatal_error(exc, 'Fatal write error on datagram transport')
            return
    self._buffer.append((bytes(data), addr))
    self._buffer_size += len(data)
    self._maybe_pause_protocol()

def _sendto_ready(self):
    while self._buffer:
        data, addr = self._buffer.popleft()
        self._buffer_size -= len(data)
        try:
            if self._extra['peername']:
                self._sock.send(data)
            else:
                self._sock.sendto(data, addr)
        except (BlockingIOError, InterruptedError):
            self._buffer.appendleft((data, addr))
            self._buffer_size += len(data)
            break
        except OSError as exc:
            self._protocol.error_received(exc)
            return
        except (SystemExit, KeyboardInterrupt):
            raise
        except BaseException as exc:
            self._fatal_error(exc, 'Fatal write error on datagram transport')
            return
    self._maybe_resume_protocol()
    if not self._buffer:
        self._loop._remove_writer(self._sock_fd)
        if self._closing:
            self._call_connection_lost(None)

def _create_transport_context(server_side, server_hostname):
    if server_side:
        raise ValueError('Server side SSL needs a valid SSLContext')
    sslcontext = ssl.create_default_context()
    if not server_hostname:
        sslcontext.check_hostname = False
    return sslcontext

def add_flowcontrol_defaults(high, low, kb):
    if high is None:
        if low is None:
            hi = kb * 1024
        else:
            lo = low
            hi = 4 * lo
    else:
        hi = high
    if low is None:
        lo = hi // 4
    else:
        lo = low
    if not hi >= lo >= 0:
        raise ValueError('high (%r) must be >= low (%r) must be >= 0' % (hi, lo))
    return (hi, lo)

def get_extra_info(self, name, default=None):
    """Get optional transport information."""
    return self._ssl_protocol._get_extra_info(name, default)

def __del__(self, _warnings=warnings):
    if not self._closed:
        self._closed = True
        _warnings.warn('unclosed transport <asyncio._SSLProtocolTransport object>', ResourceWarning)

def get_write_buffer_size(self):
    """Return the current size of the write buffers."""
    return self._ssl_protocol._get_write_buffer_size()

@property
def _protocol_paused(self):
    return self._ssl_protocol._app_writing_paused

def write(self, data):
    """Write some data bytes to the transport.

    This does not block; it buffers the data and arranges for it
    to be sent out asynchronously."""
    if not isinstance(data, (bytes, bytearray, memoryview)):
        raise TypeError(f'data: expecting a bytes-like instance, got {type(data).__name__}')
    if not data:
        return
    self._ssl_protocol._write_appdata((data,))

def can_write_eof(self):
    """Return True if this transport supports write_eof(), False if not."""
    return False

def _force_close(self, exc):
    self._closed = True
    if self._ssl_protocol is not None:
        self._ssl_protocol._abort(exc)

def _test__append_write_backlog(self, data):
    self._ssl_protocol._write_backlog.append(data)
    self._ssl_protocol._write_buffer_size += len(data)

def _set_app_protocol(self, app_protocol):
    self._app_protocol = app_protocol
    if hasattr(app_protocol, 'get_buffer') and isinstance(app_protocol, protocols.BufferedProtocol):
        self._app_protocol_get_buffer = app_protocol.get_buffer
        self._app_protocol_buffer_updated = app_protocol.buffer_updated
        self._app_protocol_is_buffer = True
    else:
        self._app_protocol_is_buffer = False

def _wakeup_waiter(self, exc=None):
    if self._waiter is None:
        return
    if not self._waiter.cancelled():
        if exc is not None:
            self._waiter.set_exception(exc)
        else:
            self._waiter.set_result(None)
    self._waiter = None

def _get_app_transport(self):
    if self._app_transport is None:
        if self._app_transport_created:
            raise RuntimeError('Creating _SSLProtocolTransport twice')
        self._app_transport = _SSLProtocolTransport(self._loop, self)
        self._app_transport_created = True
    return self._app_transport

def get_buffer(self, n):
    want = n
    if want <= 0 or want > self.max_size:
        want = self.max_size
    if len(self._ssl_buffer) < want:
        self._ssl_buffer = bytearray(want)
        self._ssl_buffer_view = memoryview(self._ssl_buffer)
    return self._ssl_buffer_view

def buffer_updated(self, nbytes):
    self._incoming.write(self._ssl_buffer_view[:nbytes])
    if self._state == SSLProtocolState.DO_HANDSHAKE:
        self._do_handshake()
    elif self._state == SSLProtocolState.WRAPPED:
        self._do_read()
    elif self._state == SSLProtocolState.FLUSHING:
        self._do_flush()
    elif self._state == SSLProtocolState.SHUTDOWN:
        self._do_shutdown()

def eof_received(self):
    """Called when the other end of the low-level stream
    is half-closed.

    If this returns a false value (including None), the transport
    will close itself.  If it returns a true value, closing the
    transport is up to the protocol."""
    self._eof_received = True
    try:
        if self._loop.get_debug():
            logger.debug('%r received EOF', self)
        if self._state == SSLProtocolState.DO_HANDSHAKE:
            self._on_handshake_complete(ConnectionResetError)
        elif self._state == SSLProtocolState.WRAPPED:
            self._set_state(SSLProtocolState.FLUSHING)
            if self._app_reading_paused:
                return True
            else:
                self._do_flush()
        elif self._state == SSLProtocolState.FLUSHING:
            self._do_write()
            self._set_state(SSLProtocolState.SHUTDOWN)
            self._do_shutdown()
        elif self._state == SSLProtocolState.SHUTDOWN:
            self._do_shutdown()
    except Exception:
        self._transport.close()
        raise

def _get_extra_info(self, name, default=None):
    if name in self._extra:
        return self._extra[name]
    elif self._transport is not None:
        return self._transport.get_extra_info(name, default)
    else:
        return default

def _set_state(self, new_state):
    allowed = False
    if new_state == SSLProtocolState.UNWRAPPED:
        allowed = True
    elif self._state == SSLProtocolState.UNWRAPPED and new_state == SSLProtocolState.DO_HANDSHAKE:
        allowed = True
    elif self._state == SSLProtocolState.DO_HANDSHAKE and new_state == SSLProtocolState.WRAPPED:
        allowed = True
    elif self._state == SSLProtocolState.WRAPPED and new_state == SSLProtocolState.FLUSHING:
        allowed = True
    elif self._state == SSLProtocolState.FLUSHING and new_state == SSLProtocolState.SHUTDOWN:
        allowed = True
    if allowed:
        self._state = new_state
    else:
        raise RuntimeError('cannot switch state from {} to {}'.format(self._state, new_state))

def _start_handshake(self):
    if self._loop.get_debug():
        logger.debug('%r starts SSL handshake', self)
        self._handshake_start_time = self._loop.time()
    else:
        self._handshake_start_time = None
    self._set_state(SSLProtocolState.DO_HANDSHAKE)
    self._handshake_timeout_handle = self._loop.call_later(self._ssl_handshake_timeout, lambda: self._check_handshake_timeout())
    self._do_handshake()

def _check_handshake_timeout(self):
    if self._state == SSLProtocolState.DO_HANDSHAKE:
        msg = f'SSL handshake is taking longer than {self._ssl_handshake_timeout} seconds: aborting the connection'
        self._fatal_error(ConnectionAbortedError(msg))

def _do_handshake(self):
    try:
        self._sslobj.do_handshake()
    except SSLAgainErrors:
        self._process_outgoing()
    except ssl.SSLError as exc:
        self._on_handshake_complete(exc)
    else:
        self._on_handshake_complete(None)

def _on_handshake_complete(self, handshake_exc):
    if self._handshake_timeout_handle is not None:
        self._handshake_timeout_handle.cancel()
        self._handshake_timeout_handle = None
    sslobj = self._sslobj
    try:
        if handshake_exc is None:
            self._set_state(SSLProtocolState.WRAPPED)
        else:
            raise handshake_exc
        peercert = sslobj.getpeercert()
    except Exception as exc:
        handshake_exc = None
        self._set_state(SSLProtocolState.UNWRAPPED)
        if isinstance(exc, ssl.CertificateError):
            msg = 'SSL handshake failed on verifying the certificate'
        else:
            msg = 'SSL handshake failed'
        self._fatal_error(exc, msg)
        self._wakeup_waiter(exc)
        return
    if self._loop.get_debug():
        dt = self._loop.time() - self._handshake_start_time
        logger.debug('%r: SSL handshake took %.1f ms', self, dt * 1000.0)
    self._extra.update(peercert=peercert, cipher=sslobj.cipher(), compression=sslobj.compression(), ssl_object=sslobj)
    if self._app_state == AppProtocolState.STATE_INIT:
        self._app_state = AppProtocolState.STATE_CON_MADE
        self._app_protocol.connection_made(self._get_app_transport())
    self._wakeup_waiter()
    self._do_read()

def _start_shutdown(self):
    if self._state in (SSLProtocolState.FLUSHING, SSLProtocolState.SHUTDOWN, SSLProtocolState.UNWRAPPED):
        return
    if self._app_transport is not None:
        self._app_transport._closed = True
    if self._state == SSLProtocolState.DO_HANDSHAKE:
        self._abort(None)
    else:
        self._set_state(SSLProtocolState.FLUSHING)
        self._shutdown_timeout_handle = self._loop.call_later(self._ssl_shutdown_timeout, lambda: self._check_shutdown_timeout())
        self._do_flush()

def _check_shutdown_timeout(self):
    if self._state in (SSLProtocolState.FLUSHING, SSLProtocolState.SHUTDOWN):
        self._transport._force_close(exceptions.TimeoutError('SSL shutdown timed out'))

def _do_shutdown(self):
    try:
        if not self._eof_received:
            self._sslobj.unwrap()
    except SSLAgainErrors:
        self._process_outgoing()
    except ssl.SSLError as exc:
        self._on_shutdown_complete(exc)
    else:
        self._process_outgoing()
        self._call_eof_received()
        self._on_shutdown_complete(None)

def _on_shutdown_complete(self, shutdown_exc):
    if self._shutdown_timeout_handle is not None:
        self._shutdown_timeout_handle.cancel()
        self._shutdown_timeout_handle = None
    if shutdown_exc:
        self._fatal_error(shutdown_exc)
    else:
        self._loop.call_soon(self._transport.close)

def _abort(self, exc):
    self._set_state(SSLProtocolState.UNWRAPPED)
    if self._transport is not None:
        self._transport._force_close(exc)

def _write_appdata(self, list_of_data):
    if self._state in (SSLProtocolState.FLUSHING, SSLProtocolState.SHUTDOWN, SSLProtocolState.UNWRAPPED):
        if self._conn_lost >= constants.LOG_THRESHOLD_FOR_CONNLOST_WRITES:
            logger.warning('SSL connection is closed')
        self._conn_lost += 1
        return
    for data in list_of_data:
        self._write_backlog.append(data)
        self._write_buffer_size += len(data)
    try:
        if self._state == SSLProtocolState.WRAPPED:
            self._do_write()
    except Exception as ex:
        self._fatal_error(ex, 'Fatal error on SSL protocol')

def _process_outgoing(self):
    if not self._ssl_writing_paused:
        data = self._outgoing.read()
        if len(data):
            self._transport.write(data)
    self._control_app_writing()

def _do_read__copied(self):
    chunk = b'1'
    zero = True
    one = False
    try:
        while True:
            chunk = self._sslobj.read(self.max_size)
            if not chunk:
                break
            if zero:
                zero = False
                one = True
                first = chunk
            elif one:
                one = False
                data = [first, chunk]
            else:
                data.append(chunk)
    except SSLAgainErrors:
        pass
    if one:
        self._app_protocol.data_received(first)
    elif not zero:
        self._app_protocol.data_received(b''.join(data))
    if not chunk:
        self._call_eof_received()
        self._start_shutdown()

def _call_eof_received(self):
    try:
        if self._app_state == AppProtocolState.STATE_CON_MADE:
            self._app_state = AppProtocolState.STATE_EOF
            keep_open = self._app_protocol.eof_received()
            if keep_open:
                logger.warning('returning true from eof_received() has no effect when using ssl')
    except (KeyboardInterrupt, SystemExit):
        raise
    except BaseException as ex:
        self._fatal_error(ex, 'Error calling eof_received()')

def _resume_reading(self):
    if self._app_reading_paused:
        self._app_reading_paused = False
        def resume():
            if self._state == SSLProtocolState.WRAPPED:
                self._do_read()
            elif self._state == SSLProtocolState.FLUSHING:
                self._do_flush()
            elif self._state == SSLProtocolState.SHUTDOWN:
                self._do_shutdown()
        self._loop.call_soon(resume)

def _control_ssl_reading(self):
    size = self._get_read_buffer_size()
    if size >= self._incoming_high_water and (not self._ssl_reading_paused):
        self._ssl_reading_paused = True
        self._transport.pause_reading()
    elif size <= self._incoming_low_water and self._ssl_reading_paused:
        self._ssl_reading_paused = False
        self._transport.resume_reading()

def _fatal_error(self, exc, message='Fatal error on transport'):
    if self._transport:
        self._transport._force_close(exc)
    if isinstance(exc, OSError):
        if self._loop.get_debug():
            logger.debug('%r: %s', self, message, exc_info=True)
    elif not isinstance(exc, exceptions.CancelledError):
        self._loop.call_exception_handler({'message': message, 'exception': exc, 'transport': self._transport, 'protocol': self})

def resume():
    if self._state == SSLProtocolState.WRAPPED:
        self._do_read()
    elif self._state == SSLProtocolState.FLUSHING:
        self._do_flush()
    elif self._state == SSLProtocolState.SHUTDOWN:
        self._do_shutdown()

def task_done(task):
    running_tasks.discard(task)
    if on_completed_fut is not None and (not on_completed_fut.done()) and (not running_tasks):
        on_completed_fut.set_result(None)
    if task.cancelled():
        return
    exc = task.exception()
    if exc is None:
        return
    unhandled_exceptions.append(exc)

def __init__(self, loop=None):
    if loop is None:
        self._loop = events.get_event_loop()
    else:
        self._loop = loop
    self._paused = False
    self._drain_waiters = collections.deque()
    self._connection_lost = False

def pause_writing(self):
    assert not self._paused
    self._paused = True
    if self._loop.get_debug():
        logger.debug('%r pauses writing', self)

def resume_writing(self):
    assert self._paused
    self._paused = False
    if self._loop.get_debug():
        logger.debug('%r resumes writing', self)
    for waiter in self._drain_waiters:
        if not waiter.done():
            waiter.set_result(None)

def connection_lost(self, exc):
    self._connection_lost = True
    if not self._paused:
        return
    for waiter in self._drain_waiters:
        if not waiter.done():
            if exc is None:
                waiter.set_result(None)
            else:
                waiter.set_exception(exc)

@property
def _stream_reader(self):
    if self._stream_reader_wr is None:
        return None
    return self._stream_reader_wr()

def connection_made(self, transport):
    if self._reject_connection:
        context = {'message': 'An open stream was garbage collected prior to establishing network connection; call "stream.close()" explicitly.'}
        if self._source_traceback:
            context['source_traceback'] = self._source_traceback
        self._loop.call_exception_handler(context)
        transport.abort()
        return
    self._transport = transport
    reader = self._stream_reader
    if reader is not None:
        reader.set_transport(transport)
    self._over_ssl = transport.get_extra_info('sslcontext') is not None
    if self._client_connected_cb is not None:
        self._stream_writer = StreamWriter(transport, self, reader, self._loop)
        res = self._client_connected_cb(reader, self._stream_writer)
        if coroutines.iscoroutine(res):
            def callback(task):
                if task.cancelled():
                    transport.close()
                    return
                exc = task.exception()
                if exc is not None:
                    self._loop.call_exception_handler({'message': 'Unhandled exception in client_connected_cb', 'exception': exc, 'transport': transport})
                    transport.close()
            self._task = self._loop.create_task(res)
            self._task.add_done_callback(callback)
        self._strong_reader = None

def connection_lost(self, exc):
    reader = self._stream_reader
    if reader is not None:
        if exc is None:
            reader.feed_eof()
        else:
            reader.set_exception(exc)
    if not self._closed.done():
        if exc is None:
            self._closed.set_result(None)
        else:
            self._closed.set_exception(exc)
    super().connection_lost(exc)
    self._stream_reader_wr = None
    self._stream_writer = None
    self._task = None
    self._transport = None

def data_received(self, data):
    reader = self._stream_reader
    if reader is not None:
        reader.feed_data(data)

def eof_received(self):
    reader = self._stream_reader
    if reader is not None:
        reader.feed_eof()
    if self._over_ssl:
        return False
    return True

def __del__(self):
    try:
        closed = self._closed
    except AttributeError:
        pass
    else:
        if closed.done() and (not closed.cancelled()):
            closed.exception()

def __repr__(self):
    info = [self.__class__.__name__, f'transport={self._transport!r}']
    if self._reader is not None:
        info.append(f'reader={self._reader!r}')
    return '<{}>'.format(' '.join(info))

@property
def transport(self):
    return self._transport

def __del__(self):
    if not self._transport.is_closing():
        if self._loop.is_closed():
            warnings.warn('loop is closed', ResourceWarning)
        else:
            self.close()
            warnings.warn(f'unclosed {self!r}', ResourceWarning)

def __init__(self, limit=_DEFAULT_LIMIT, loop=None):
    if limit <= 0:
        raise ValueError('Limit cannot be <= 0')
    self._limit = limit
    if loop is None:
        self._loop = events.get_event_loop()
    else:
        self._loop = loop
    self._buffer = bytearray()
    self._eof = False
    self._waiter = None
    self._exception = None
    self._transport = None
    self._paused = False
    if self._loop.get_debug():
        self._source_traceback = format_helpers.extract_stack(sys._getframe(1))

def __repr__(self):
    info = ['StreamReader']
    if self._buffer:
        info.append(f'{len(self._buffer)} bytes')
    if self._eof:
        info.append('eof')
    if self._limit != _DEFAULT_LIMIT:
        info.append(f'limit={self._limit}')
    if self._waiter:
        info.append(f'waiter={self._waiter!r}')
    if self._exception:
        info.append(f'exception={self._exception!r}')
    if self._transport:
        info.append(f'transport={self._transport!r}')
    if self._paused:
        info.append('paused')
    return '<{}>'.format(' '.join(info))

def set_exception(self, exc):
    self._exception = exc
    waiter = self._waiter
    if waiter is not None:
        self._waiter = None
        if not waiter.cancelled():
            waiter.set_exception(exc)

def _wakeup_waiter(self):
    """Wakeup read*() functions waiting for data or EOF."""
    waiter = self._waiter
    if waiter is not None:
        self._waiter = None
        if not waiter.cancelled():
            waiter.set_result(None)

def set_transport(self, transport):
    assert self._transport is None, 'Transport already set'
    self._transport = transport

def _maybe_resume_transport(self):
    if self._paused and len(self._buffer) <= self._limit:
        self._paused = False
        self._transport.resume_reading()

def feed_eof(self):
    self._eof = True
    self._wakeup_waiter()

def at_eof(self):
    """Return True if the buffer is empty and 'feed_eof' was called."""
    return self._eof and (not self._buffer)

def feed_data(self, data):
    assert not self._eof, 'feed_data after feed_eof'
    if not data:
        return
    self._buffer.extend(data)
    self._wakeup_waiter()
    if self._transport is not None and (not self._paused) and (len(self._buffer) > 2 * self._limit):
        try:
            self._transport.pause_reading()
        except NotImplementedError:
            self._transport = None
        else:
            self._paused = True

def callback(task):
    if task.cancelled():
        transport.close()
        return
    exc = task.exception()
    if exc is not None:
        self._loop.call_exception_handler({'message': 'Unhandled exception in client_connected_cb', 'exception': exc, 'transport': transport})
        transport.close()

def __repr__(self):
    info = [self.__class__.__name__]
    if self.stdin is not None:
        info.append(f'stdin={self.stdin!r}')
    if self.stdout is not None:
        info.append(f'stdout={self.stdout!r}')
    if self.stderr is not None:
        info.append(f'stderr={self.stderr!r}')
    return '<{}>'.format(' '.join(info))

def pipe_data_received(self, fd, data):
    if fd == 1:
        reader = self.stdout
    elif fd == 2:
        reader = self.stderr
    else:
        reader = None
    if reader is not None:
        reader.feed_data(data)

def pipe_connection_lost(self, fd, exc):
    if fd == 0:
        pipe = self.stdin
        if pipe is not None:
            pipe.close()
        self.connection_lost(exc)
        if exc is None:
            self._stdin_closed.set_result(None)
        else:
            self._stdin_closed.set_exception(exc)
            self._stdin_closed._log_traceback = False
        return
    if fd == 1:
        reader = self.stdout
    elif fd == 2:
        reader = self.stderr
    else:
        reader = None
    if reader is not None:
        if exc is None:
            reader.feed_eof()
        else:
            reader.set_exception(exc)
    if fd in self._pipe_fds:
        self._pipe_fds.remove(fd)
    self._maybe_close_transport()

def process_exited(self):
    self._process_exited = True
    self._maybe_close_transport()

def _maybe_close_transport(self):
    if len(self._pipe_fds) == 0 and self._process_exited:
        self._transport.close()
        self._transport = None

def _get_close_waiter(self, stream):
    if stream is self.stdin:
        return self._stdin_closed

@property
def returncode(self):
    return self._transport.get_returncode()

async def wait(self):
    """Wait until the process exit and return the process return code."""
    return await self._transport._wait()

async def _feed_stdin(self, input):
    debug = self._loop.get_debug()
    try:
        if input is not None:
            self.stdin.write(input)
            if debug:
                logger.debug('%r communicate: feed stdin (%s bytes)', self, len(input))
        await self.stdin.drain()
    except (BrokenPipeError, ConnectionResetError) as exc:
        if debug:
            logger.debug('%r communicate: stdin got %r', self, exc)
    if debug:
        logger.debug('%r communicate: close stdin', self)
    self.stdin.close()

async def communicate(self, input=None):
    if self.stdin is not None:
        stdin = self._feed_stdin(input)
    else:
        stdin = self._noop()
    if self.stdout is not None:
        stdout = self._read_stream(1)
    else:
        stdout = self._noop()
    if self.stderr is not None:
        stderr = self._read_stream(2)
    else:
        stderr = self._noop()
    stdin, stdout, stderr = await tasks.gather(stdin, stdout, stderr)
    await self.wait()
    return (stdout, stderr)

def __repr__(self):
    info = ['']
    if self._tasks:
        info.append(f'tasks={len(self._tasks)}')
    if self._errors:
        info.append(f'errors={len(self._errors)}')
    if self._aborting:
        info.append('cancelling')
    elif self._entered:
        info.append('entered')
    info_str = ' '.join(info)
    return f'<TaskGroup{info_str}>'

async def __aenter__(self):
    if self._entered:
        raise RuntimeError(f'TaskGroup {self!r} has already been entered')
    if self._loop is None:
        self._loop = events.get_running_loop()
    self._parent_task = tasks.current_task(self._loop)
    if self._parent_task is None:
        raise RuntimeError(f'TaskGroup {self!r} cannot determine the parent task')
    self._entered = True
    return self

def create_task(self, coro, *, name=None, context=None):
    """Create a new task in this group and return it.

    Similar to `asyncio.create_task`."""
    if not self._entered:
        raise RuntimeError(f'TaskGroup {self!r} has not been entered')
    if self._exiting and (not self._tasks):
        raise RuntimeError(f'TaskGroup {self!r} is finished')
    if self._aborting:
        raise RuntimeError(f'TaskGroup {self!r} is shutting down')
    if context is None:
        task = self._loop.create_task(coro)
    else:
        task = self._loop.create_task(coro, context=context)
    tasks._set_task_name(task, name)
    self._tasks.add(task)
    task.add_done_callback(self._on_task_done)
    try:
        return task
    finally:
        del task

def _is_base_error(self, exc: BaseException) -> bool:
    assert isinstance(exc, BaseException)
    return isinstance(exc, (SystemExit, KeyboardInterrupt))

def _abort(self):
    self._aborting = True
    for t in self._tasks:
        if not t.done():
            t.cancel()

def _on_task_done(self, task):
    self._tasks.discard(task)
    if self._on_completed_fut is not None and (not self._tasks):
        if not self._on_completed_fut.done():
            self._on_completed_fut.set_result(True)
    if task.cancelled():
        return
    exc = task.exception()
    if exc is None:
        return
    self._errors.append(exc)
    if self._is_base_error(exc) and self._base_error is None:
        self._base_error = exc
    if self._parent_task.done():
        self._loop.call_exception_handler({'message': f'Task {task!r} has errored out but its parent task {self._parent_task} is already completed', 'exception': exc, 'task': task})
        return
    if not self._aborting and (not self._parent_cancel_requested):
        self._abort()
        self._parent_cancel_requested = True
        self._parent_task.cancel()

def current_task(loop=None):
    """Return a currently executed task."""
    if loop is None:
        loop = events.get_running_loop()
    return _current_tasks.get(loop)

def all_tasks(loop=None):
    """Return a set of all tasks for the loop."""
    if loop is None:
        loop = events.get_running_loop()
    eager_tasks = list(_eager_tasks)
    scheduled_tasks = None
    i = 0
    while True:
        try:
            scheduled_tasks = list(_scheduled_tasks)
        except RuntimeError:
            i += 1
            if i >= 1000:
                raise
        else:
            break
    return {t for t in itertools.chain(scheduled_tasks, eager_tasks) if futures._get_loop(t) is loop and (not t.done())}

def _set_task_name(task, name):
    if name is not None:
        try:
            set_name = task.set_name
        except AttributeError:
            warnings.warn('Task.set_name() was added in Python 3.8, the method support will be mandatory for third-party task implementations since 3.13.', DeprecationWarning, stacklevel=3)
        else:
            set_name(name)

def create_task(coro, *, name=None, context=None):
    """Schedule the execution of a coroutine object in a spawn task.

    Return a Task object."""
    loop = events.get_running_loop()
    if context is None:
        task = loop.create_task(coro)
    else:
        task = loop.create_task(coro, context=context)
    _set_task_name(task, name)
    return task

def _release_waiter(waiter, *args):
    if not waiter.done():
        waiter.set_result(None)

async def _wait(fs, timeout, return_when, loop):
    """Internal helper for wait().

    The fs argument must be a collection of Futures."""
    assert fs, 'Set of Futures is empty.'
    waiter = loop.create_future()
    timeout_handle = None
    if timeout is not None:
        timeout_handle = loop.call_later(timeout, _release_waiter, waiter)
    counter = len(fs)
    def _on_completion(f):
        nonlocal counter
        counter -= 1
        if counter <= 0 or return_when == FIRST_COMPLETED or (return_when == FIRST_EXCEPTION and (not f.cancelled() and f.exception() is not None)):
            if timeout_handle is not None:
                timeout_handle.cancel()
            if not waiter.done():
                waiter.set_result(None)
    for f in fs:
        f.add_done_callback(_on_completion)
    try:
        await waiter
    finally:
        if timeout_handle is not None:
            timeout_handle.cancel()
        for f in fs:
            f.remove_done_callback(_on_completion)
    done, pending = (set(), set())
    for f in fs:
        if f.done():
            done.add(f)
        else:
            pending.add(f)
    return (done, pending)

def ensure_future(coro_or_future, *, loop=None):
    """Wrap a coroutine or an awaitable in a future.

    If the argument is a Future, it is returned directly."""
    if futures.isfuture(coro_or_future):
        if loop is not None and loop is not futures._get_loop(coro_or_future):
            raise ValueError('The future belongs to a different loop than the one specified as the loop argument')
        return coro_or_future
    should_close = True
    if not coroutines.iscoroutine(coro_or_future):
        if inspect.isawaitable(coro_or_future):
            async def _wrap_awaitable(awaitable):
                return await awaitable
            coro_or_future = _wrap_awaitable(coro_or_future)
            should_close = False
        else:
            raise TypeError('An asyncio.Future, a coroutine or an awaitable is required')
    if loop is None:
        loop = events.get_event_loop()
    try:
        return loop.create_task(coro_or_future)
    except RuntimeError:
        if should_close:
            coro_or_future.close()
        raise

def run_coroutine_threadsafe(coro, loop):
    """Submit a coroutine object to a given event loop.

    Return a concurrent.futures.Future to access the result."""
    if not coroutines.iscoroutine(coro):
        raise TypeError('A coroutine object is required')
    future = concurrent.futures.Future()
    def callback():
        try:
            futures._chain_future(ensure_future(coro, loop=loop), future)
        except (SystemExit, KeyboardInterrupt):
            raise
        except BaseException as exc:
            if future.set_running_or_notify_cancel():
                future.set_exception(exc)
            raise
    loop.call_soon_threadsafe(callback)
    return future

def _register_task(task):
    """Register an asyncio Task scheduled to run on an event loop."""
    _scheduled_tasks.add(task)

def _register_eager_task(task):
    """Register an asyncio Task about to be eagerly executed."""
    _eager_tasks.add(task)

def _enter_task(loop, task):
    current_task = _current_tasks.get(loop)
    if current_task is not None:
        raise RuntimeError(f'Cannot enter into task {task!r} while another task {current_task!r} is being executed.')
    _current_tasks[loop] = task

def _leave_task(loop, task):
    current_task = _current_tasks.get(loop)
    if current_task is not task:
        raise RuntimeError(f'Leaving task {task!r} does not match the current task {current_task!r}.')
    del _current_tasks[loop]

def _swap_current_task(loop, task):
    prev_task = _current_tasks.get(loop)
    if task is None:
        del _current_tasks[loop]
    else:
        _current_tasks[loop] = task
    return prev_task

def _unregister_task(task):
    """Unregister a completed, scheduled Task."""
    _scheduled_tasks.discard(task)

def _unregister_eager_task(task):
    """Unregister a task which finished its first eager step."""
    _eager_tasks.discard(task)

def __init__(self, coro, *, loop=None, name=None, context=None, eager_start=False):
    super().__init__(loop=loop)
    if self._source_traceback:
        del self._source_traceback[-1]
    if not coroutines.iscoroutine(coro):
        self._log_destroy_pending = False
        raise TypeError(f'a coroutine was expected, got {coro!r}')
    if name is None:
        self._name = f'Task-{_task_name_counter()}'
    else:
        self._name = str(name)
    self._num_cancels_requested = 0
    self._must_cancel = False
    self._fut_waiter = None
    self._coro = coro
    if context is None:
        self._context = contextvars.copy_context()
    else:
        self._context = context
    if eager_start and self._loop.is_running():
        self.__eager_start()
    else:
        self._loop.call_soon(self.__step, context=self._context)
        _register_task(self)

def __del__(self):
    if self._state == futures._PENDING and self._log_destroy_pending:
        context = {'task': self, 'message': 'Task was destroyed but it is pending!'}
        if self._source_traceback:
            context['source_traceback'] = self._source_traceback
        self._loop.call_exception_handler(context)
    super().__del__()

def __eager_start(self):
    prev_task = _swap_current_task(self._loop, self)
    try:
        _register_eager_task(self)
        try:
            self._context.run(self.__step_run_and_handle_result, None)
        finally:
            _unregister_eager_task(self)
    finally:
        try:
            curtask = _swap_current_task(self._loop, prev_task)
            assert curtask is self
        finally:
            if self.done():
                self._coro = None
                self = None
            else:
                _register_task(self)

def __step(self, exc=None):
    if self.done():
        raise exceptions.InvalidStateError(f'_step(): already done: {self!r}, {exc!r}')
    if self._must_cancel:
        if not isinstance(exc, exceptions.CancelledError):
            exc = self._make_cancelled_error()
        self._must_cancel = False
    self._fut_waiter = None
    _enter_task(self._loop, self)
    try:
        self.__step_run_and_handle_result(exc)
    finally:
        _leave_task(self._loop, self)
        self = None

def __wakeup(self, future):
    try:
        future.result()
    except BaseException as exc:
        self.__step(exc)
    else:
        self.__step()
    self = None

def _on_completion(f):
    nonlocal counter
    counter -= 1
    if counter <= 0 or return_when == FIRST_COMPLETED or (return_when == FIRST_EXCEPTION and (not f.cancelled() and f.exception() is not None)):
        if timeout_handle is not None:
            timeout_handle.cancel()
        if not waiter.done():
            waiter.set_result(None)

def _on_timeout():
    for f in todo:
        f.remove_done_callback(_on_completion)
        done.put_nowait(None)
    todo.clear()

def _on_completion(f):
    if not todo:
        return
    todo.remove(f)
    done.put_nowait(f)
    if not todo and timeout_handle is not None:
        timeout_handle.cancel()

async def _wait_for_one():
    f = await done.get()
    if f is None:
        raise exceptions.TimeoutError
    return f.result()

def cancel(self, msg=None):
    if self.done():
        return False
    ret = False
    for child in self._children:
        if child.cancel(msg=msg):
            ret = True
    if ret:
        self._cancel_requested = True
    return ret

def _done_callback(fut):
    nonlocal nfinished
    nfinished += 1
    if outer is None or outer.done():
        if not fut.cancelled():
            fut.exception()
        return
    if not return_exceptions:
        if fut.cancelled():
            exc = fut._make_cancelled_error()
            outer.set_exception(exc)
            return
        else:
            exc = fut.exception()
            if exc is not None:
                outer.set_exception(exc)
                return
    if nfinished == nfuts:
        results = []
        for fut in children:
            if fut.cancelled():
                res = exceptions.CancelledError('' if fut._cancel_message is None else fut._cancel_message)
            else:
                res = fut.exception()
                if res is None:
                    res = fut.result()
            results.append(res)
        if outer._cancel_requested:
            exc = fut._make_cancelled_error()
            outer.set_exception(exc)
        else:
            outer.set_result(results)

def _inner_done_callback(inner):
    if outer.cancelled():
        if not inner.cancelled():
            inner.exception()
        return
    if inner.cancelled():
        outer.cancel()
    else:
        exc = inner.exception()
        if exc is not None:
            outer.set_exception(exc)
        else:
            outer.set_result(inner.result())

def _outer_done_callback(outer):
    if not inner.done():
        inner.remove_done_callback(_inner_done_callback)

def callback():
    try:
        futures._chain_future(ensure_future(coro, loop=loop), future)
    except (SystemExit, KeyboardInterrupt):
        raise
    except BaseException as exc:
        if future.set_running_or_notify_cancel():
            future.set_exception(exc)
        raise

def when(self) -> Optional[float]:
    """Return the current deadline."""
    return self._when

def reschedule(self, when: Optional[float]) -> None:
    """Reschedule the timeout."""
    if self._state is not _State.ENTERED:
        if self._state is _State.CREATED:
            raise RuntimeError('Timeout has not been entered')
        raise RuntimeError(f'Cannot change state of {self._state.value} Timeout')
    self._when = when
    if self._timeout_handler is not None:
        self._timeout_handler.cancel()
    if when is None:
        self._timeout_handler = None
    else:
        loop = events.get_running_loop()
        if when <= loop.time():
            self._timeout_handler = loop.call_soon(self._on_timeout)
        else:
            self._timeout_handler = loop.call_at(when, self._on_timeout)

def expired(self) -> bool:
    """Is timeout expired during execution?"""
    return self._state in (_State.EXPIRING, _State.EXPIRED)

async def __aexit__(self, exc_type: Optional[Type[BaseException]], exc_val: Optional[BaseException], exc_tb: Optional[TracebackType]) -> Optional[bool]:
    assert self._state in (_State.ENTERED, _State.EXPIRING)
    if self._timeout_handler is not None:
        self._timeout_handler.cancel()
        self._timeout_handler = None
    if self._state is _State.EXPIRING:
        self._state = _State.EXPIRED
        if self._task.uncancel() <= self._cancelling and exc_type is exceptions.CancelledError:
            raise TimeoutError from exc_val
    elif self._state is _State.ENTERED:
        self._state = _State.EXITED
    return None

def __init__(self, extra=None):
    if extra is None:
        extra = {}
    self._extra = extra

def get_extra_info(self, name, default=None):
    """Get optional transport information."""
    return self._extra.get(name, default)

def is_closing(self):
    """Return True if the transport is closing or closed."""
    raise NotImplementedError

def set_protocol(self, protocol):
    """Set a new protocol."""
    raise NotImplementedError

def get_protocol(self):
    """Return the current protocol."""
    raise NotImplementedError

def get_write_buffer_size(self):
    """Return the current size of the write buffer."""
    raise NotImplementedError

def can_write_eof(self):
    """Return True if this transport supports write_eof(), False if not."""
    raise NotImplementedError

def get_pid(self):
