    raise NotImplementedError

def _maybe_pause_protocol(self):
    size = self.get_write_buffer_size()
    if size <= self._high_water:
        return
    if not self._protocol_paused:
        self._protocol_paused = True
        try:
            self._protocol.pause_writing()
        except (SystemExit, KeyboardInterrupt):
            raise
        except BaseException as exc:
            self._loop.call_exception_handler({'message': 'protocol.pause_writing() failed', 'exception': exc, 'transport': self, 'protocol': self._protocol})

def _maybe_resume_protocol(self):
    if self._protocol_paused and self.get_write_buffer_size() <= self._low_water:
        self._protocol_paused = False
        try:
            self._protocol.resume_writing()
        except (SystemExit, KeyboardInterrupt):
            raise
        except BaseException as exc:
            self._loop.call_exception_handler({'message': 'protocol.resume_writing() failed', 'exception': exc, 'transport': self, 'protocol': self._protocol})

def _set_write_buffer_limits(self, high=None, low=None):
    if high is None:
        if low is None:
            high = 64 * 1024
        else:
            high = 4 * low
    if low is None:
        low = high // 4
    if not high >= low >= 0:
        raise ValueError(f'high ({high!r}) must be >= low ({low!r}) must be >= 0')
    self._high_water = high
    self._low_water = low

def set_write_buffer_limits(self, high=None, low=None):
    self._set_write_buffer_limits(high=high, low=low)
    self._maybe_pause_protocol()

@property
def family(self):
    return self._sock.family

@property
def type(self):
    return self._sock.type

@property
def proto(self):
    return self._sock.proto

def __repr__(self):
    s = f'<asyncio.TransportSocket fd={self.fileno()}, family={self.family!s}, type={self.type!s}, proto={self.proto}'
    if self.fileno() != -1:
        try:
            laddr = self.getsockname()
            if laddr:
                s = f'{s}, laddr={laddr}'
        except socket.error:
            pass
        try:
            raddr = self.getpeername()
            if raddr:
                s = f'{s}, raddr={raddr}'
        except socket.error:
            pass
    return f'{s}>'

def settimeout(self, value):
    if value == 0:
