def __init__(self, skip=None):
    self.skip = set(skip) if skip else None
    self.breaks = {}
    self.fncache = {}
    self.frame_returning = None
    self.enterframe = None
    self._load_breaks()

def dispatch_line(self, frame):
    """Invoke user function and return trace function for line event.

    If the debugger stops on the current line, invoke
    self.user_line(). Raise BdbQuit if self.quitting is set.
    Return self.trace_dispatch to continue tracing in this scope."""
    if self.stop_here(frame) or self.break_here(frame):
        self.user_line(frame)
        if self.quitting:
            raise BdbQuit
    return self.trace_dispatch

def dispatch_call(self, frame, arg):
    """Invoke user function and return trace function for call event.

    If the debugger stops on this function call, invoke
    self.user_call(). Raise BdbQuit if self.quitting is set.
    Return self.trace_dispatch to continue tracing in this scope."""
    if self.botframe is None:
        self.botframe = frame.f_back
        return self.trace_dispatch
    if not (self.stop_here(frame) or self.break_anywhere(frame)):
        return
    if self.stopframe and frame.f_code.co_flags & GENERATOR_AND_COROUTINE_FLAGS:
        return self.trace_dispatch
    self.user_call(frame, arg)
    if self.quitting:
        raise BdbQuit
    return self.trace_dispatch

def dispatch_return(self, frame, arg):
    """Invoke user function and return trace function for return event.

    If the debugger stops on this function return, invoke
    self.user_return(). Raise BdbQuit if self.quitting is set.
    Return self.trace_dispatch to continue tracing in this scope."""
    if self.stop_here(frame) or frame == self.returnframe:
        if self.stopframe and frame.f_code.co_flags & GENERATOR_AND_COROUTINE_FLAGS:
            return self.trace_dispatch
        try:
            self.frame_returning = frame
            self.user_return(frame, arg)
        finally:
            self.frame_returning = None
        if self.quitting:
            raise BdbQuit
        if self.stopframe is frame and self.stoplineno != -1:
            self._set_stopinfo(None, None)
        if self.stoplineno != -1:
            self._set_caller_tracefunc(frame)
    return self.trace_dispatch

def dispatch_exception(self, frame, arg):
    """Invoke user function and return trace function for exception event.

    If the debugger stops on this exception, invoke
    self.user_exception(). Raise BdbQuit if self.quitting is set.
    Return self.trace_dispatch to continue tracing in this scope."""
    if self.stop_here(frame):
        if not (frame.f_code.co_flags & GENERATOR_AND_COROUTINE_FLAGS and arg[0] is StopIteration and (arg[2] is None)):
            self.user_exception(frame, arg)
            if self.quitting:
                raise BdbQuit
    elif self.stopframe and frame is not self.stopframe and self.stopframe.f_code.co_flags & GENERATOR_AND_COROUTINE_FLAGS and (arg[0] in (StopIteration, GeneratorExit)):
        self.user_exception(frame, arg)
        if self.quitting:
            raise BdbQuit
    return self.trace_dispatch

def is_skipped_module(self, module_name):
    """Return True if module_name matches any skip pattern."""
    if module_name is None:
        return False
    for pattern in self.skip:
        if fnmatch.fnmatch(module_name, pattern):
            return True
    return False

def stop_here(self, frame):
    """Return True if frame is below the starting frame in the stack."""
    if self.skip and self.is_skipped_module(frame.f_globals.get('__name__')):
        return False
    if frame is self.stopframe:
        if self.stoplineno == -1:
            return False
        return frame.f_lineno >= self.stoplineno
    if not self.stopframe:
        return True
    return False

def break_here(self, frame):
    """Return True if there is an effective breakpoint for this line.

    Check for line or function breakpoint and if in effect.
    Delete temporary breakpoints if effective() says to."""
    filename = self.canonic(frame.f_code.co_filename)
    if filename not in self.breaks:
        return False
    lineno = frame.f_lineno
    if lineno not in self.breaks[filename]:
        lineno = frame.f_code.co_firstlineno
        if lineno not in self.breaks[filename]:
            return False
    bp, flag = effective(filename, lineno, frame)
    if bp:
        self.currentbp = bp.number
        if flag and bp.temporary:
            self.do_clear(str(bp.number))
        return True
    else:
        return False

def user_call(self, frame, argument_list):
    """Called if we might stop in a function."""
    pass

def user_line(self, frame):
    """Called when we stop or break at a line."""
    pass

def user_return(self, frame, return_value):
    """Called when a return trap is set here."""
    pass

def user_exception(self, frame, exc_info):
    """Called when we stop on an exception."""
    pass

def _set_caller_tracefunc(self, current_frame):
    caller_frame = current_frame.f_back
    if caller_frame and (not caller_frame.f_trace) and (caller_frame is not self.botframe):
        caller_frame.f_trace = self.trace_dispatch

def set_until(self, frame, lineno=None):
    """Stop when the line with the lineno greater than the current one is
    reached or when returning from current frame."""
    if lineno is None:
        lineno = frame.f_lineno + 1
    self._set_stopinfo(frame, frame, lineno)

def set_step(self):
    """Stop after one line of code."""
    self._set_stopinfo(None, None)

def set_next(self, frame):
    """Stop on the next line in or below the given frame."""
    self._set_stopinfo(frame, None)

def set_return(self, frame):
    """Stop when returning from the given frame."""
    if frame.f_code.co_flags & GENERATOR_AND_COROUTINE_FLAGS:
        self._set_stopinfo(frame, None, -1)
    else:
        self._set_stopinfo(frame.f_back, frame)

def set_continue(self):
    """Stop only at breakpoints or when finished.

    If there are no breakpoints, set the system trace function to None."""
    self._set_stopinfo(self.botframe, None, -1)
    if not self.breaks:
        sys.settrace(None)
        frame = sys._getframe().f_back
        while frame and frame is not self.botframe:
            del frame.f_trace
            frame = frame.f_back

def _add_to_breaks(self, filename, lineno):
    """Add breakpoint to breaks, if not already there."""
    bp_linenos = self.breaks.setdefault(filename, [])
    if lineno not in bp_linenos:
        bp_linenos.append(lineno)

def _prune_breaks(self, filename, lineno):
    """Prune breakpoints for filename:lineno.

    A list of breakpoints is maintained in the Bdb instance and in
    the Breakpoint class.  If a breakpoint in the Bdb instance no
    longer exists in the Breakpoint class, then it's removed from the
    Bdb instance."""
    if (filename, lineno) not in Breakpoint.bplist:
        self.breaks[filename].remove(lineno)
    if not self.breaks[filename]:
        del self.breaks[filename]

def clear_break(self, filename, lineno):
    """Delete breakpoints for filename:lineno.

    If no breakpoints were set, return an error message."""
    filename = self.canonic(filename)
    if filename not in self.breaks:
        return 'There are no breakpoints in %s' % filename
    if lineno not in self.breaks[filename]:
        return 'There is no breakpoint at %s:%d' % (filename, lineno)
    for bp in Breakpoint.bplist[filename, lineno][:]:
        bp.deleteMe()
    self._prune_breaks(filename, lineno)
    return None

def clear_bpbynumber(self, arg):
    """Delete a breakpoint by its index in Breakpoint.bpbynumber.

    If arg is invalid, return an error message."""
    try:
        bp = self.get_bpbynumber(arg)
    except ValueError as err:
        return str(err)
    bp.deleteMe()
    self._prune_breaks(bp.file, bp.line)
    return None

def clear_all_file_breaks(self, filename):
    """Delete all breakpoints in filename.

    If none were set, return an error message."""
    filename = self.canonic(filename)
    if filename not in self.breaks:
        return 'There are no breakpoints in %s' % filename
    for line in self.breaks[filename]:
        blist = Breakpoint.bplist[filename, line]
        for bp in blist:
            bp.deleteMe()
    del self.breaks[filename]
    return None

def clear_all_breaks(self):
    """Delete all existing breakpoints.

    If none were set, return an error message."""
    if not self.breaks:
        return 'There are no breakpoints'
    for bp in Breakpoint.bpbynumber:
        if bp:
            bp.deleteMe()
    self.breaks = {}
    return None

def get_bpbynumber(self, arg):
    """Return a breakpoint by its index in Breakpoint.bybpnumber.

    For invalid arg values or if the breakpoint doesn't exist,
    raise a ValueError."""
    if not arg:
        raise ValueError('Breakpoint number expected')
    try:
        number = int(arg)
    except ValueError:
        raise ValueError('Non-numeric breakpoint number %s' % arg) from None
    try:
        bp = Breakpoint.bpbynumber[number]
    except IndexError:
        raise ValueError('Breakpoint number %d out of range' % number) from None
    if bp is None:
        raise ValueError('Breakpoint %d already deleted' % number)
    return bp

def get_file_breaks(self, filename):
    """Return all lines with breakpoints for filename.

    If no breakpoints are set, return an empty list."""
    filename = self.canonic(filename)
    if filename in self.breaks:
        return self.breaks[filename]
    else:
        return []

def get_all_breaks(self):
    """Return all breakpoints that are set."""
    return self.breaks

def get_stack(self, f, t):
    """Return a list of (frame, lineno) in a stack trace and a size.

    List starts with original calling frame, if there is one.
    Size may be number of frames above or below f."""
    stack = []
    if t and t.tb_frame is f:
        t = t.tb_next
    while f is not None:
        stack.append((f, f.f_lineno))
        if f is self.botframe:
            break
        f = f.f_back
    stack.reverse()
    i = max(0, len(stack) - 1)
    while t is not None:
        stack.append((t.tb_frame, t.tb_lineno))
        t = t.tb_next
    if f is None:
        i = max(0, len(stack) - 1)
    return (stack, i)

def run(self, cmd, globals=None, locals=None):
    """Debug a statement executed via the exec() function.

    globals defaults to __main__.dict; locals defaults to globals."""
    if globals is None:
        import __main__
        globals = __main__.__dict__
    if locals is None:
        locals = globals
    self.reset()
    if isinstance(cmd, str):
        cmd = compile(cmd, '<string>', 'exec')
    sys.settrace(self.trace_dispatch)
    try:
        exec(cmd, globals, locals)
    except BdbQuit:
        pass
    finally:
        self.quitting = True
        sys.settrace(None)

def runeval(self, expr, globals=None, locals=None):
    """Debug an expression executed via the eval() function.

    globals defaults to __main__.dict; locals defaults to globals."""
    if globals is None:
        import __main__
        globals = __main__.__dict__
    if locals is None:
        locals = globals
    self.reset()
    sys.settrace(self.trace_dispatch)
    try:
        return eval(expr, globals, locals)
    except BdbQuit:
        pass
    finally:
        self.quitting = True
        sys.settrace(None)

def runctx(self, cmd, globals, locals):
    """For backwards-compatibility.  Defers to run()."""
    self.run(cmd, globals, locals)

