            self._writer.send_bytes(b'')

def clear(self):
    if self._closed:
        raise RuntimeError('operation on closed _ThreadWakeup')
    while self._reader.poll():
        self._reader.recv_bytes()

def _on_queue_feeder_error(self, e, obj):
    if isinstance(obj, _CallItem):
        tb = format_exception(type(e), e, e.__traceback__)
        e.__cause__ = _RemoteTraceback('\n"""\n{}"""'.format(''.join(tb)))
        work_item = self.pending_work_items.pop(obj.work_id, None)
        self.thread_wakeup.wakeup()
        if work_item is not None:
            work_item.future.set_exception(e)
    else:
        super()._on_queue_feeder_error(e, obj)

def run(self):
    while True:
        try:
            self.add_call_item_to_queue()
        except BaseException as exc:
            cause = format_exception(exc)
            self.terminate_broken(cause)
            return
        result_item, is_broken, cause = self.wait_result_broken_or_wakeup()
        if is_broken:
            self.terminate_broken(cause)
            return
        if result_item is not None:
            self.process_result_item(result_item)
            process_exited = result_item.exit_pid is not None
            if process_exited:
                p = self.processes.pop(result_item.exit_pid)
                p.join()
            del result_item
            if (executor := self.executor_reference()):
                if process_exited:
                    with self.shutdown_lock:
                        executor._adjust_process_count()
                else:
                    executor._idle_worker_semaphore.release()
                del executor
        if self.is_shutting_down():
            self.flag_executor_shutting_down()
            self.add_call_item_to_queue()
            if not self.pending_work_items:
                self.join_executor_internals()
                return

def add_call_item_to_queue(self):
    while True:
        if self.call_queue.full():
            return
        try:
            work_id = self.work_ids_queue.get(block=False)
        except queue.Empty:
            return
        else:
            work_item = self.pending_work_items[work_id]
            if work_item.future.set_running_or_notify_cancel():
                self.call_queue.put(_CallItem(work_id, work_item.fn, work_item.args, work_item.kwargs), block=True)
            else:
                del self.pending_work_items[work_id]
                continue

def wait_result_broken_or_wakeup(self):
    result_reader = self.result_queue._reader
    assert not self.thread_wakeup._closed
    wakeup_reader = self.thread_wakeup._reader
    readers = [result_reader, wakeup_reader]
    worker_sentinels = [p.sentinel for p in list(self.processes.values())]
    ready = mp.connection.wait(readers + worker_sentinels)
    cause = None
    is_broken = True
    result_item = None
    if result_reader in ready:
        try:
            result_item = result_reader.recv()
            is_broken = False
        except BaseException as exc:
            cause = format_exception(exc)
    elif wakeup_reader in ready:
        is_broken = False
    self.thread_wakeup.clear()
    return (result_item, is_broken, cause)

def process_result_item(self, result_item):
    if isinstance(result_item, int):
        assert self.is_shutting_down()
        p = self.processes.pop(result_item)
        p.join()
        if not self.processes:
            self.join_executor_internals()
            return
    else:
        work_item = self.pending_work_items.pop(result_item.work_id, None)
        if work_item is not None:
            if result_item.exception:
                work_item.future.set_exception(result_item.exception)
            else:
                work_item.future.set_result(result_item.result)

def is_shutting_down(self):
    executor = self.executor_reference()
    return _global_shutdown or executor is None or executor._shutdown_thread

def terminate_broken(self, cause):
    with self.shutdown_lock:
        self._terminate_broken(cause)

def flag_executor_shutting_down(self):
    executor = self.executor_reference()
    if executor is not None:
        executor._shutdown_thread = True
        if executor._cancel_pending_futures:
            new_pending_work_items = {}
            for work_id, work_item in self.pending_work_items.items():
                if not work_item.future.cancel():
                    new_pending_work_items[work_id] = work_item
            self.pending_work_items = new_pending_work_items
            while True:
                try:
                    self.work_ids_queue.get_nowait()
                except queue.Empty:
                    break
            executor._cancel_pending_futures = False

def shutdown_workers(self):
    n_children_to_stop = self.get_n_children_alive()
    n_sentinels_sent = 0
    while n_sentinels_sent < n_children_to_stop and self.get_n_children_alive() > 0:
        for i in range(n_children_to_stop - n_sentinels_sent):
            try:
                self.call_queue.put_nowait(None)
                n_sentinels_sent += 1
            except queue.Full:
                break

def join_executor_internals(self):
    with self.shutdown_lock:
        self._join_executor_internals()

def _join_executor_internals(self, broken=False):
    if not broken:
        self.shutdown_workers()
    self.call_queue.close()
    self.call_queue.join_thread()
    self.thread_wakeup.close()
    for p in self.processes.values():
        if broken:
            p.terminate()
        p.join()

def _start_executor_manager_thread(self):
    if self._executor_manager_thread is None:
        if not self._safe_to_dynamically_spawn_children:
            self._launch_processes()
        self._executor_manager_thread = _ExecutorManagerThread(self)
        self._executor_manager_thread.start()
        _threads_wakeups[self._executor_manager_thread] = self._executor_manager_thread_wakeup

def _launch_processes(self):
    assert not self._executor_manager_thread, 'Processes cannot be fork()ed after the thread has started, deadlock in the child processes could result.'
    for _ in range(len(self._processes), self._max_workers):
        self._spawn_process()

def weakref_cb(_, thread_wakeup=self.thread_wakeup):
    mp.util.debug('Executor collected: triggering callback for QueueManager wakeup')
    thread_wakeup.wakeup()

def _python_exit():
    global _shutdown
    with _global_shutdown_lock:
        _shutdown = True
    items = list(_threads_queues.items())
    for t, q in items:
        q.put(None)
    for t, q in items:
        t.join()

def _worker(executor_reference, work_queue, initializer, initargs):
    if initializer is not None:
        try:
            initializer(*initargs)
        except BaseException:
            _base.LOGGER.critical('Exception in initializer:', exc_info=True)
            executor = executor_reference()
            if executor is not None:
                executor._initializer_failed()
            return
    try:
        while True:
            try:
                work_item = work_queue.get_nowait()
            except queue.Empty:
                executor = executor_reference()
                if executor is not None:
                    executor._idle_semaphore.release()
                del executor
                work_item = work_queue.get(block=True)
            if work_item is not None:
                work_item.run()
                del work_item
                continue
            executor = executor_reference()
            if _shutdown or executor is None or executor._shutdown:
                if executor is not None:
                    executor._shutdown = True
                work_queue.put(None)
                return
            del executor
    except BaseException:
        _base.LOGGER.critical('Exception in worker', exc_info=True)

def run(self):
    if not self.future.set_running_or_notify_cancel():
        return
    try:
        result = self.fn(*self.args, **self.kwargs)
    except BaseException as exc:
        self.future.set_exception(exc)
        self = None
    else:
        self.future.set_result(result)

def submit(self, fn, /, *args, **kwargs):
    with self._shutdown_lock, _global_shutdown_lock:
        if self._broken:
            raise BrokenThreadPool(self._broken)
        if self._shutdown:
            raise RuntimeError('cannot schedule new futures after shutdown')
        if _shutdown:
            raise RuntimeError('cannot schedule new futures after interpreter shutdown')
        f = _base.Future()
        w = _WorkItem(f, fn, args, kwargs)
        self._work_queue.put(w)
        self._adjust_thread_count()
        return f

def _adjust_thread_count(self):
    if self._idle_semaphore.acquire(timeout=0):
        return
    def weakref_cb(_, q=self._work_queue):
        q.put(None)
    num_threads = len(self._threads)
    if num_threads < self._max_workers:
        thread_name = '%s_%d' % (self._thread_name_prefix or self, num_threads)
        t = threading.Thread(name=thread_name, target=_worker, args=(weakref.ref(self, weakref_cb), self._work_queue, self._initializer, self._initargs))
        t.start()
        self._threads.add(t)
        _threads_queues[t] = self._work_queue

def _initializer_failed(self):
    with self._shutdown_lock:
        self._broken = 'A thread initializer failed, the thread pool is not usable anymore'
        while True:
            try:
                work_item = self._work_queue.get_nowait()
            except queue.Empty:
                break
            if work_item is not None:
                work_item.future.set_exception(BrokenThreadPool(self._broken))

def shutdown(self, wait=True, *, cancel_futures=False):
    with self._shutdown_lock:
        self._shutdown = True
        if cancel_futures:
            while True:
                try:
                    work_item = self._work_queue.get_nowait()
                except queue.Empty:
                    break
                if work_item is not None:
                    work_item.future.cancel()
        self._work_queue.put(None)
    if wait:
        for t in self._threads:
            t.join()

def __init__(self, msg=''):
    self.message = msg
    Exception.__init__(self, msg)

def append(self, lineno, line):
    self.errors.append((lineno, line))
    self.message += '\n\t[line %2d]: %s' % (lineno, line)

def before_get(self, parser, section, option, value, defaults):
    L = []
    self._interpolate_some(parser, option, L, value, section, defaults, 1)
    return ''.join(L)

def _interpolate_some(self, parser, option, accum, rest, section, map, depth):
    rawval = parser.get(section, option, raw=True, fallback=rest)
    if depth > MAX_INTERPOLATION_DEPTH:
        raise InterpolationDepthError(option, section, rawval)
    while rest:
        p = rest.find('%')
        if p < 0:
            accum.append(rest)
            return
        if p > 0:
            accum.append(rest[:p])
            rest = rest[p:]
        c = rest[1:2]
        if c == '%':
            accum.append('%')
            rest = rest[2:]
        elif c == '(':
            m = self._KEYCRE.match(rest)
            if m is None:
                raise InterpolationSyntaxError(option, section, 'bad interpolation variable reference %r' % rest)
            var = parser.optionxform(m.group(1))
            rest = rest[m.end():]
            try:
                v = map[var]
            except KeyError:
                raise InterpolationMissingOptionError(option, section, rawval, var) from None
            if '%' in v:
                self._interpolate_some(parser, option, accum, v, section, map, depth + 1)
            else:
                accum.append(v)
        else:
            raise InterpolationSyntaxError(option, section, "'%%' must be followed by '%%' or '(', found: %r" % (rest,))

def before_set(self, parser, section, option, value):
    tmp_value = value.replace('$$', '')
    tmp_value = self._KEYCRE.sub('', tmp_value)
    if '$' in tmp_value:
        raise ValueError('invalid interpolation syntax in %r at position %d' % (value, tmp_value.find('$')))
    return value

def __init__(self, *args, **kwargs):
    super().__init__(*args, **kwargs)
    warnings.warn('LegacyInterpolation has been deprecated since Python 3.2 and will be removed from the configparser module in Python 3.13. Use BasicInterpolation or ExtendedInterpolation instead.', DeprecationWarning, stacklevel=2)

def before_get(self, parser, section, option, value, vars):
    rawval = value
    depth = MAX_INTERPOLATION_DEPTH
    while depth:
        depth -= 1
        if value and '%(' in value:
            replace = functools.partial(self._interpolation_replace, parser=parser)
            value = self._KEYCRE.sub(replace, value)
            try:
                value = value % vars
            except KeyError as e:
                raise InterpolationMissingOptionError(option, section, rawval, e.args[0]) from None
        else:
            break
    if value and '%(' in value:
        raise InterpolationDepthError(option, section, rawval)
    return value

@staticmethod
def _interpolation_replace(match, parser):
    s = match.group(1)
    if s is None:
        return match.group()
    else:
        return '%%(%s)s' % parser.optionxform(s)

def __init__(self, defaults=None, dict_type=_default_dict, allow_no_value=False, *, delimiters=('=', ':'), comment_prefixes=('#', ';'), inline_comment_prefixes=None, strict=True, empty_lines_in_values=True, default_section=DEFAULTSECT, interpolation=_UNSET, converters=_UNSET):
    self._dict = dict_type
    self._sections = self._dict()
    self._defaults = self._dict()
    self._converters = ConverterMapping(self)
    self._proxies = self._dict()
    self._proxies[default_section] = SectionProxy(self, default_section)
    self._delimiters = tuple(delimiters)
    if delimiters == ('=', ':'):
        self._optcre = self.OPTCRE_NV if allow_no_value else self.OPTCRE
    else:
        d = '|'.join((re.escape(d) for d in delimiters))
        if allow_no_value:
            self._optcre = re.compile(self._OPT_NV_TMPL.format(delim=d), re.VERBOSE)
        else:
            self._optcre = re.compile(self._OPT_TMPL.format(delim=d), re.VERBOSE)
    self._comment_prefixes = tuple(comment_prefixes or ())
    self._inline_comment_prefixes = tuple(inline_comment_prefixes or ())
    self._strict = strict
    self._allow_no_value = allow_no_value
    self._empty_lines_in_values = empty_lines_in_values
    self.default_section = default_section
    self._interpolation = interpolation
    if self._interpolation is _UNSET:
        self._interpolation = self._DEFAULT_INTERPOLATION
    if self._interpolation is None:
        self._interpolation = Interpolation()
    if not isinstance(self._interpolation, Interpolation):
        raise TypeError(f'interpolation= must be None or an instance of Interpolation; got an object of type {type(self._interpolation)}')
    if converters is not _UNSET:
        self._converters.update(converters)
    if defaults:
        self._read_defaults(defaults)

def sections(self):
    """Return a list of section names, excluding [DEFAULT]"""
    return list(self._sections.keys())

def add_section(self, section):
    """Create a new section in the configuration.

    Raise DuplicateSectionError if a section by the specified name
    already exists. Raise ValueError if name is DEFAULT."""
    if section == self.default_section:
        raise ValueError('Invalid section name: %r' % section)
    if section in self._sections:
        raise DuplicateSectionError(section)
    self._sections[section] = self._dict()
    self._proxies[section] = SectionProxy(self, section)

def options(self, section):
    """Return a list of option names for the given section name."""
    try:
        opts = self._sections[section].copy()
    except KeyError:
        raise NoSectionError(section) from None
    opts.update(self._defaults)
    return list(opts.keys())

def read_file(self, f, source=None):
    """Like read() but the argument must be a file-like object.

    The `f` argument must be iterable, returning one line at a time.
    Optional second argument is the `source` specifying the name of the
    file being read. If not given, it is taken from f.name. If `f` has no
    `name` attribute, `<???>` is used."""
    if source is None:
        try:
            source = f.name
        except AttributeError:
            source = '<???>'
    self._read(f, source)

def read_dict(self, dictionary, source='<dict>'):
    """Read configuration from a dictionary.

    Keys are section names, values are dictionaries with keys and values
    that should be present in the section. If the used dictionary type
    preserves order, sections and their keys will be added in order.

    All types held in the dictionary are converted to strings during
    reading, including section names, option names and keys.

    Optional second argument is the `source` specifying the name of the
    dictionary being read."""
    elements_added = set()
    for section, keys in dictionary.items():
        section = str(section)
        try:
            self.add_section(section)
        except (DuplicateSectionError, ValueError):
            if self._strict and section in elements_added:
                raise
        elements_added.add(section)
        for key, value in keys.items():
            key = self.optionxform(str(key))
            if value is not None:
                value = str(value)
            if self._strict and (section, key) in elements_added:
                raise DuplicateOptionError(section, key, source)
            elements_added.add((section, key))
            self.set(section, key, value)

def get(self, section, option, *, raw=False, vars=None, fallback=_UNSET):
    """Get an option value for a given section.

    If `vars` is provided, it must be a dictionary. The option is looked up
    in `vars` (if provided), `section`, and in `DEFAULTSECT` in that order.
    If the key is not found and `fallback` is provided, it is used as
    a fallback value. `None` can be provided as a `fallback` value.

    If interpolation is enabled and the optional argument `raw` is False,
    all interpolations are expanded in the return values.

    Arguments `raw`, `vars`, and `fallback` are keyword only.

    The section DEFAULT is special."""
    try:
        d = self._unify_values(section, vars)
    except NoSectionError:
        if fallback is _UNSET:
            raise
        else:
            return fallback
    option = self.optionxform(option)
    try:
        value = d[option]
    except KeyError:
        if fallback is _UNSET:
            raise NoOptionError(option, section)
        else:
            return fallback
    if raw or value is None:
        return value
    else:
        return self._interpolation.before_get(self, section, option, value, d)

def _get_conv(self, section, option, conv, *, raw=False, vars=None, fallback=_UNSET, **kwargs):
    try:
        return self._get(section, conv, option, raw=raw, vars=vars, **kwargs)
    except (NoSectionError, NoOptionError):
        if fallback is _UNSET:
            raise
        return fallback

def items(self, section=_UNSET, raw=False, vars=None):
    """Return a list of (name, value) tuples for each option in a section.

    All % interpolations are expanded in the return values, based on the
    defaults passed into the constructor, unless the optional argument
    `raw` is true.  Additional substitutions may be provided using the
    `vars` argument, which must be a dictionary whose contents overrides
    any pre-existing defaults.

    The section DEFAULT is special."""
    if section is _UNSET:
        return super().items()
    d = self._defaults.copy()
    try:
        d.update(self._sections[section])
    except KeyError:
        if section != self.default_section:
            raise NoSectionError(section)
    orig_keys = list(d.keys())
    if vars:
        for key, value in vars.items():
            d[self.optionxform(key)] = value
    value_getter = lambda option: self._interpolation.before_get(self, section, option, d[option], d)
    if raw:
        value_getter = lambda option: d[option]
    return [(option, value_getter(option)) for option in orig_keys]

def popitem(self):
    """Remove a section from the parser and return it as
    a (section_name, section_proxy) tuple. If no section is present, raise
    KeyError.

    The section DEFAULT is never returned because it cannot be removed."""
    for key in self.sections():
        value = self[key]
        del self[key]
        return (key, value)
    raise KeyError

def has_option(self, section, option):
    """Check for the existence of a given option in a given section.
    If the specified `section` is None or an empty string, DEFAULT is
    assumed. If the specified `section` does not exist, returns False."""
    if not section or section == self.default_section:
        option = self.optionxform(option)
        return option in self._defaults
    elif section not in self._sections:
        return False
    else:
        option = self.optionxform(option)
        return option in self._sections[section] or option in self._defaults

def set(self, section, option, value=None):
    """Set an option."""
    if value:
        value = self._interpolation.before_set(self, section, option, value)
    if not section or section == self.default_section:
        sectdict = self._defaults
    else:
        try:
            sectdict = self._sections[section]
        except KeyError:
            raise NoSectionError(section) from None
    sectdict[self.optionxform(option)] = value

def write(self, fp, space_around_delimiters=True):
    """Write an .ini-format representation of the configuration state.

    If `space_around_delimiters` is True (the default), delimiters
    between keys and values are surrounded by spaces.

    Please note that comments in the original configuration file are not
    preserved when writing the configuration back."""
    if space_around_delimiters:
        d = ' {} '.format(self._delimiters[0])
    else:
        d = self._delimiters[0]
    if self._defaults:
        self._write_section(fp, self.default_section, self._defaults.items(), d)
    for section in self._sections:
        self._write_section(fp, section, self._sections[section].items(), d)

def _write_section(self, fp, section_name, section_items, delimiter):
    """Write a single section to the specified `fp`."""
    fp.write('[{}]\n'.format(section_name))
    for key, value in section_items:
        value = self._interpolation.before_write(self, section_name, key, value)
        if value is not None or not self._allow_no_value:
            value = delimiter + str(value).replace('\n', '\n\t')
        else:
            value = ''
        fp.write('{}{}\n'.format(key, value))
    fp.write('\n')

def remove_option(self, section, option):
    """Remove an option."""
    if not section or section == self.default_section:
        sectdict = self._defaults
    else:
        try:
            sectdict = self._sections[section]
        except KeyError:
            raise NoSectionError(section) from None
    option = self.optionxform(option)
    existed = option in sectdict
    if existed:
        del sectdict[option]
    return existed

def __getitem__(self, key):
    if key != self.default_section and (not self.has_section(key)):
        raise KeyError(key)
    return self._proxies[key]

def __setitem__(self, key, value):
    if key in self and self[key] is value:
        return
    if key == self.default_section:
        self._defaults.clear()
    elif key in self._sections:
        self._sections[key].clear()
    self.read_dict({key: value})

def __delitem__(self, key):
    if key == self.default_section:
        raise ValueError('Cannot remove the default section.')
    if not self.has_section(key):
        raise KeyError(key)
    self.remove_section(key)

def _join_multiline_values(self):
    defaults = (self.default_section, self._defaults)
    all_sections = itertools.chain((defaults,), self._sections.items())
    for section, options in all_sections:
        for name, val in options.items():
            if isinstance(val, list):
                val = '\n'.join(val).rstrip()
            options[name] = self._interpolation.before_read(self, section, name, val)

def _read_defaults(self, defaults):
    """Read the defaults passed in the initializer.
    Note: values can be non-string."""
    for key, value in defaults.items():
        self._defaults[self.optionxform(key)] = value

def _handle_error(self, exc, fpname, lineno, line):
    if not exc:
        exc = ParsingError(fpname)
    exc.append(lineno, repr(line))
    return exc

def _unify_values(self, section, vars):
    """Create a sequence of lookups with 'vars' taking priority over
    the 'section' which takes priority over the DEFAULTSECT."""
    sectiondict = {}
    try:
        sectiondict = self._sections[section]
    except KeyError:
        if section != self.default_section:
            raise NoSectionError(section) from None
    vardict = {}
    if vars:
        for key, value in vars.items():
            if value is not None:
                value = str(value)
            vardict[self.optionxform(key)] = value
    return _ChainMap(vardict, sectiondict, self._defaults)

def _convert_to_boolean(self, value):
    """Return a boolean value translating from other types if necessary.
    """
    if value.lower() not in self.BOOLEAN_STATES:
        raise ValueError('Not a boolean: %s' % value)
    return self.BOOLEAN_STATES[value.lower()]

@property
def converters(self):
    return self._converters

def __getitem__(self, key):
    if not self._parser.has_option(self._name, key):
        raise KeyError(key)
    return self._parser.get(self._name, key)

def __setitem__(self, key, value):
    self._parser._validate_value_types(option=key, value=value)
    return self._parser.set(self._name, key, value)

def __delitem__(self, key):
    if not (self._parser.has_option(self._name, key) and self._parser.remove_option(self._name, key)):
        raise KeyError(key)

def _options(self):
    if self._name != self._parser.default_section:
        return self._parser.options(self._name)
    else:
        return self._parser.defaults()

@property
def parser(self):
    return self._parser

@property
def name(self):
    return self._name

def get(self, option, fallback=None, *, raw=False, vars=None, _impl=None, **kwargs):
    """Get an option value.

    Unless `fallback` is provided, `None` will be returned if the option
    is not found."""
    if not _impl:
        _impl = self._parser.get
    return _impl(self._name, option, raw=raw, vars=vars, fallback=fallback, **kwargs)

def __setitem__(self, key, value):
    try:
        k = 'get' + key
    except TypeError:
        raise ValueError('Incompatible key: {} (type: {})'.format(key, type(key)))
    if k == 'get':
        raise ValueError('Incompatible key: cannot use "" as a name')
    self._data[key] = value
    func = functools.partial(self._parser._get_conv, conv=value)
    func.converter = value
    setattr(self._parser, k, func)
    for proxy in self._parser.values():
        getter = functools.partial(proxy.get, _impl=func)
        setattr(proxy, k, getter)

def contextmanager(func):
    """@contextmanager decorator.

    Typical usage:

        @contextmanager
        def some_generator(<arguments>):
            <setup>
            try:
                yield <value>
            finally:
                <cleanup>

    This makes this:

        with some_generator(<arguments>) as <variable>:
            <body>

    equivalent to this:

        <setup>
        try:
            <variable> = <value>
            <body>
        finally:
            <cleanup>"""
    @wraps(func)
    def helper(*args, **kwds):
        return _GeneratorContextManager(func, args, kwds)
    return helper

def __enter__(self):
    """Return `self` upon entering the runtime context."""
    return self

@abc.abstractmethod
def __exit__(self, exc_type, exc_value, traceback):
