def __exit__(self, exctype, excinst, exctb):
    if exctype is None:
        return
    if issubclass(exctype, self._exceptions):
        return True
    if issubclass(exctype, BaseExceptionGroup):
        match, rest = excinst.split(self._exceptions)
        if rest is None:
            return True
        raise rest
    return False

