@property
def fieldnames(self):
    if self._fieldnames is None:
        try:
            self._fieldnames = next(self.reader)
        except StopIteration:
            pass
    self.line_num = self.reader.line_num
    return self._fieldnames

@fieldnames.setter
def fieldnames(self, value):
    self._fieldnames = value

def __next__(self):
    if self.line_num == 0:
        self.fieldnames
    row = next(self.reader)
    self.line_num = self.reader.line_num
    while row == []:
        row = next(self.reader)
    d = dict(zip(self.fieldnames, row))
    lf = len(self.fieldnames)
    lr = len(row)
    if lf < lr:
        d[self.restkey] = row[lf:]
    elif lf > lr:
        for key in self.fieldnames[lr:]:
            d[key] = self.restval
    return d

def __init__(self, f, fieldnames, restval='', extrasaction='raise', dialect='excel', *args, **kwds):
    if fieldnames is not None and iter(fieldnames) is fieldnames:
        fieldnames = list(fieldnames)
    self.fieldnames = fieldnames
    self.restval = restval
    extrasaction = extrasaction.lower()
    if extrasaction not in ('raise', 'ignore'):
        raise ValueError("extrasaction (%s) must be 'raise' or 'ignore'" % extrasaction)
    self.extrasaction = extrasaction
    self.writer = writer(f, dialect, *args, **kwds)

def writeheader(self):
    header = dict(zip(self.fieldnames, self.fieldnames))
    return self.writerow(header)

def has_header(self, sample):
    rdr = reader(StringIO(sample), self.sniff(sample))
    header = next(rdr)
    columns = len(header)
    columnTypes = {}
    for i in range(columns):
        columnTypes[i] = None
    checked = 0
    for row in rdr:
        if checked > 20:
            break
        checked += 1
        if len(row) != columns:
            continue
        for col in list(columnTypes.keys()):
            thisType = complex
            try:
                thisType(row[col])
            except (ValueError, OverflowError):
                thisType = len(row[col])
            if thisType != columnTypes[col]:
                if columnTypes[col] is None:
                    columnTypes[col] = thisType
                else:
                    del columnTypes[col]
    hasHeader = 0
    for col, colType in columnTypes.items():
        if isinstance(colType, int):
            if len(header[col]) != colType:
                hasHeader += 1
            else:
                hasHeader -= 1
        else:
            try:
                colType(header[col])
            except (ValueError, TypeError):
                hasHeader += 1
            else:
                hasHeader -= 1
    return hasHeader > 0

def _check_size(typ, typecode=None):
    from struct import calcsize
    if typecode is None:
        typecode = typ._type_
    actual, required = (sizeof(typ), calcsize(typecode))
    if actual != required:
        raise SystemError('sizeof(%s) wrong: %d instead of %d' % (typ, actual, required))

def SetPointerType(pointer, cls):
    if _pointer_type_cache.get(cls, None) is not None:
        raise RuntimeError('This type already exists in the cache')
    if id(pointer) not in _pointer_type_cache:
        raise RuntimeError("What's this???")
    pointer.set_type(cls)
    _pointer_type_cache[cls] = pointer
    del _pointer_type_cache[id(pointer)]

def PYFUNCTYPE(restype, *argtypes):
    class CFunctionType(_CFuncPtr):
        _argtypes_ = argtypes
        _restype_ = restype
        _flags_ = _FUNCFLAG_CDECL | _FUNCFLAG_PYTHONAPI
    return CFunctionType

def string_at(ptr, size=-1):
    """string_at(ptr[, size]) -> string

    Return the byte string at void *ptr."""
    return _string_at(ptr, size)

def WINFUNCTYPE(restype, *argtypes, **kw):
    flags = _FUNCFLAG_STDCALL
    if kw.pop('use_errno', False):
        flags |= _FUNCFLAG_USE_ERRNO
    if kw.pop('use_last_error', False):
        flags |= _FUNCFLAG_USE_LASTERROR
    if kw:
        raise ValueError('unexpected keyword argument(s) %s' % kw.keys())
    try:
        return _win_functype_cache[restype, argtypes, flags]
    except KeyError:
        pass
    class WinFunctionType(_CFuncPtr):
        _argtypes_ = argtypes
        _restype_ = restype
        _flags_ = flags
    _win_functype_cache[restype, argtypes, flags] = WinFunctionType
    return WinFunctionType

def __repr__(self):
    try:
        return super().__repr__()
    except ValueError:
        return '%s(<NULL>)' % type(self).__name__

def __init__(self, name, mode=DEFAULT_MODE, handle=None, use_errno=False, use_last_error=False, winmode=None):
    if name:
        name = _os.fspath(name)
    self._name = name
    flags = self._func_flags_
    if use_errno:
        flags |= _FUNCFLAG_USE_ERRNO
    if use_last_error:
        flags |= _FUNCFLAG_USE_LASTERROR
    if _sys.platform.startswith('aix'):
        'When the name contains ".a(" and ends with ")",\n               e.g., "libFOO.a(libFOO.so)" - this is taken to be an\n               archive(member) syntax for dlopen(), and the mode is adjusted.\n               Otherwise, name is presented to dlopen() as a file argument.\n            '
        if name and name.endswith(')') and ('.a(' in name):
            mode |= _os.RTLD_MEMBER | _os.RTLD_NOW
    if _os.name == 'nt':
        if winmode is not None:
            mode = winmode
        else:
            import nt
            mode = nt._LOAD_LIBRARY_SEARCH_DEFAULT_DIRS
            if '/' in name or '\\' in name:
                self._name = nt._getfullpathname(self._name)
                mode |= nt._LOAD_LIBRARY_SEARCH_DLL_LOAD_DIR
    class _FuncPtr(_CFuncPtr):
        _flags_ = flags
        _restype_ = self._func_restype_
    self._FuncPtr = _FuncPtr
    if handle is None:
        self._handle = _dlopen(self._name, mode)
    else:
        self._handle = handle

def __getattr__(self, name):
