def get_shared(ld_headers):
    """extract the shareable objects from ld_headers
    character "[" is used to strip off the path information.
    Note: the "[" and "]" characters that are part of dump -H output
    are not removed here."""
    shared = []
    for line, _ in ld_headers:
        if '[' in line:
            shared.append(line[line.index('['):-1])
    return shared

def get_one_match(expr, lines):
    '''Must be only one match, otherwise result is None.
    When there is a match, strip leading "[" and trailing "]"'''
    expr = f'\\[({expr})\\]'
    matches = list(filter(None, (re.search(expr, line) for line in lines)))
    if len(matches) == 1:
        return matches[0].group(1)
    else:
        return None

def get_legacy(members):
    """This routine provides historical aka legacy naming schemes started
    in AIX4 shared library support for library members names.
    e.g., in /usr/lib/libc.a the member name shr.o for 32-bit binary and
    shr_64.o for 64-bit binary."""
    if AIX_ABI == 64:
        expr = 'shr4?_?64\\.o'
        member = get_one_match(expr, members)
        if member:
            return member
    else:
        for name in ['shr.o', 'shr4.o']:
            member = get_one_match(re.escape(name), members)
            if member:
                return member
    return None

def get_member(name, members):
    """Return an archive member matching the request in name.
    Name is the library name without any prefix like lib, suffix like .so,
    or version number.
    Given a list of members find and return the most appropriate result
    Priority is given to generic libXXX.so, then a versioned libXXX.so.a.b.c
    and finally, legacy AIX naming scheme."""
    expr = f'lib{name}\\.so'
    member = get_one_match(expr, members)
    if member:
        return member
    elif AIX_ABI == 64:
        expr = f'lib{name}64\\.so'
        member = get_one_match(expr, members)
    if member:
        return member
    member = get_version(name, members)
    if member:
        return member
    else:
        return get_legacy(members)

def get_libpaths():
    """On AIX, the buildtime searchpath is stored in the executable.
    as "loader header information".
    The command /usr/bin/dump -H extracts this info.
    Prefix searched libraries with LD_LIBRARY_PATH (preferred),
    or LIBPATH if defined. These paths are appended to the paths
    to libraries the python executable is linked with.
    This mimics AIX dlopen() behavior."""
    libpaths = environ.get('LD_LIBRARY_PATH')
    if libpaths is None:
        libpaths = environ.get('LIBPATH')
    if libpaths is None:
        libpaths = []
    else:
        libpaths = libpaths.split(':')
    objects = get_ld_headers(executable)
    for _, lines in objects:
        for line in lines:
            path = line.split()[1]
            if '/' in path:
                libpaths.extend(path.split(':'))
    return libpaths

def find_shared(paths, name):
    """paths is a list of directories to search for an archive.
    name is the abbreviated name given to find_library().
    Process: search "paths" for archive, and if an archive is found
    return the result of get_member().
    If an archive is not found then return None"""
    for dir in paths:
        if dir == '/lib':
            continue
        base = f'lib{name}.a'
        archive = path.join(dir, base)
        if path.exists(archive):
            members = get_shared(get_ld_headers(archive))
            member = get_member(re.escape(name), members)
            if member is not None:
                return (base, member)
            else:
                return (None, None)
    return (None, None)

