    try:
        proc = subprocess.Popen(('/usr/ccs/bin/dump', '-Lpv', f), stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
    except OSError:
        return None
    with proc:
        data = proc.stdout.read()
    res = re.search(b'\\[.*\\]\\sSONAME\\s+([^\\s]+)', data)
    if not res:
        return None
    return os.fsdecode(res.group(1))

def _get_soname(f):
    if not f:
