def find_library(name):
    ename = re.escape(name)
    expr = ':-l%s\\.\\S+ => \\S*/(lib%s\\.\\S+)' % (ename, ename)
    expr = os.fsencode(expr)
    try:
        proc = subprocess.Popen(('/sbin/ldconfig', '-r'), stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
    except OSError:
        data = b''
    else:
        with proc:
            data = proc.stdout.read()
    res = re.findall(expr, data)
    if not res:
        return _get_soname(_findLib_gcc(name))
    res.sort(key=_num_version)
    return os.fsdecode(res[-1])

def _findLib_crle(name, is64):
    if not os.path.exists('/usr/bin/crle'):
        return None
    env = dict(os.environ)
    env['LC_ALL'] = 'C'
    if is64:
        args = ('/usr/bin/crle', '-64')
    else:
        args = ('/usr/bin/crle',)
    paths = None
    try:
        proc = subprocess.Popen(args, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, env=env)
    except OSError:
        return None
    with proc:
        for line in proc.stdout:
            line = line.strip()
            if line.startswith(b'Default Library Path (ELF):'):
                paths = os.fsdecode(line).split()[4]
    if not paths:
        return None
    for dir in paths.split(':'):
        libfile = os.path.join(dir, 'lib%s.so' % name)
        if os.path.exists(libfile):
            return libfile
    return None

def _findSoname_ldconfig(name):
    import struct
    if struct.calcsize('l') == 4:
        machine = os.uname().machine + '-32'
    else:
        machine = os.uname().machine + '-64'
    mach_map = {'x86_64-64': 'libc6,x86-64', 'ppc64-64': 'libc6,64bit', 'sparc64-64': 'libc6,64bit', 's390x-64': 'libc6,64bit', 'ia64-64': 'libc6,IA-64'}
    abi_type = mach_map.get(machine, 'libc6')
    regex = '\\s+(lib%s\\.[^\\s]+)\\s+\\(%s'
    regex = os.fsencode(regex % (re.escape(name), abi_type))
    try:
        with subprocess.Popen(['/sbin/ldconfig', '-p'], stdin=subprocess.DEVNULL, stderr=subprocess.DEVNULL, stdout=subprocess.PIPE, env={'LC_ALL': 'C', 'LANG': 'C'}) as p:
            res = re.search(regex, p.stdout.read())
            if res:
                return os.fsdecode(res.group(1))
    except OSError:
        pass

def _findLib_ld(name):
    expr = '[^\\(\\)\\s]*lib%s\\.[^\\(\\)\\s]*' % re.escape(name)
    cmd = ['ld', '-t']
    libpath = os.environ.get('LD_LIBRARY_PATH')
    if libpath:
        for d in libpath.split(':'):
            cmd.extend(['-L', d])
    cmd.extend(['-o', os.devnull, '-l%s' % name])
    result = None
    try:
        p = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, universal_newlines=True)
        out, _ = p.communicate()
        res = re.findall(expr, os.fsdecode(out))
        for file in res:
            if not _is_elf(file):
                continue
            return os.fsdecode(file)
    except Exception:
        pass
    return result

def initscr():
    import _curses, curses
    setupterm(term=_os.environ.get('TERM', 'unknown'), fd=_sys.__stdout__.fileno())
    stdscr = _curses.initscr()
    for key, value in _curses.__dict__.items():
        if key[0:4] == 'ACS_' or key in ('LINES', 'COLS'):
            setattr(curses, key, value)
    return stdscr

def start_color():
    import _curses, curses
    retval = _curses.start_color()
    if hasattr(_curses, 'COLORS'):
        curses.COLORS = _curses.COLORS
    if hasattr(_curses, 'COLOR_PAIRS'):
        curses.COLOR_PAIRS = _curses.COLOR_PAIRS
    return retval

def wrapper(func, /, *args, **kwds):
    """Wrapper function that initializes curses and calls another function,
    restoring normal keyboard/screen behavior on error.
    The callable object 'func' is then passed the main window 'stdscr'
    as its first argument, followed by any other arguments passed to
    wrapper()."""
    try:
        stdscr = initscr()
        noecho()
        cbreak()
        stdscr.keypad(1)
        try:
            start_color()
        except:
            pass
        return func(stdscr, *args, **kwds)
    finally:
        if 'stdscr' in locals():
            stdscr.keypad(0)
            echo()
            nocbreak()
            endwin()

def _ctoi(c):
    if isinstance(c, str):
        return ord(c)
    else:
        return c

def ascii(c):
    if isinstance(c, str):
        return chr(_ctoi(c) & 127)
    else:
        return _ctoi(c) & 127

def ctrl(c):
    if isinstance(c, str):
        return chr(_ctoi(c) & 31)
    else:
        return _ctoi(c) & 31

def unctrl(c):
    bits = _ctoi(c)
    if bits == 127:
        rep = '^?'
    elif isprint(bits & 127):
        rep = chr(bits & 127)
    else:
        rep = '^' + chr((bits & 127 | 32) + 32)
    if bits & 128:
        return '!' + rep
    return rep

def has_key(ch):
    if isinstance(ch, str):
        ch = ord(ch)
    capability_name = _capability_names.get(ch)
    if capability_name is None:
        return False
    if _curses.tigetstr(capability_name):
        return True
    else:
        return False

def _end_of_line(self, y):
    """Go to the location of the first blank on the given line,
    returning the index of the last non-blank character."""
    self._update_max_yx()
    last = self.maxx
    while True:
        if curses.ascii.ascii(self.win.inch(y, last)) != curses.ascii.SP:
            last = min(self.maxx, last + 1)
            break
        elif last == 0:
            break
        last = last - 1
    return last

def _insert_printable_char(self, ch):
    self._update_max_yx()
    y, x = self.win.getyx()
    backyx = None
    while y < self.maxy or x < self.maxx:
        if self.insert_mode:
            oldch = self.win.inch()
        try:
            self.win.addch(ch)
        except curses.error:
            pass
        if not self.insert_mode or not curses.ascii.isprint(oldch):
            break
        ch = oldch
        y, x = self.win.getyx()
        if backyx is None:
            backyx = (y, x)
    if backyx is not None:
        self.win.move(*backyx)

def gather(self):
    """Collect and return the contents of the window."""
    result = ''
    self._update_max_yx()
    for y in range(self.maxy + 1):
        self.win.move(y, 0)
        stop = self._end_of_line(y)
        if stop == 0 and self.stripspaces:
            continue
        for x in range(self.maxx + 1):
            if self.stripspaces and x > stop:
                break
            result = result + chr(curses.ascii.ascii(self.win.inch(y, x)))
        if self.maxy > 0:
            result = result + '\n'
    return result

def edit(self, validate=None):
    """Edit in the widget window and collect the results."""
    while 1:
        ch = self.win.getch()
        if validate:
            ch = validate(ch)
        if not ch:
            continue
        if not self.do_command(ch):
            break
        self.win.refresh()
    return self.gather()

def _recursive_repr(user_function):
    repr_running = set()
    @functools.wraps(user_function)
    def wrapper(self):
        key = (id(self), _thread.get_ident())
        if key in repr_running:
            return '...'
        repr_running.add(key)
        try:
            result = user_function(self)
        finally:
            repr_running.discard(key)
        return result
    return wrapper

def _tuple_str(obj_name, fields):
    if not fields:
        return '()'
    return f"({','.join([f'{obj_name}.{f.name}' for f in fields])},)"

def _create_fn(name, args, body, *, globals=None, locals=None, return_type=MISSING):
    if locals is None:
        locals = {}
    return_annotation = ''
    if return_type is not MISSING:
        locals['__dataclass_return_type__'] = return_type
        return_annotation = '->__dataclass_return_type__'
    args = ','.join(args)
    body = '\n'.join((f'  {b}' for b in body))
    txt = f' def {name}({args}){return_annotation}:\n{body}'
    local_vars = ', '.join(locals.keys())
    txt = f'def __create_fn__({local_vars}):\n{txt}\n return {name}'
    ns = {}
    exec(txt, globals, ns)
    return ns['__create_fn__'](**locals)

def _field_assign(frozen, name, value, self_name):
    if frozen:
        return f'__dataclass_builtins_object__.__setattr__({self_name},{name!r},{value})'
    return f'{self_name}.{name}={value}'

def _field_init(f, frozen, globals, self_name, slots):
    default_name = f'__dataclass_dflt_{f.name}__'
    if f.default_factory is not MISSING:
        if f.init:
            globals[default_name] = f.default_factory
            value = f'{default_name}() if {f.name} is __dataclass_HAS_DEFAULT_FACTORY__ else {f.name}'
        else:
            globals[default_name] = f.default_factory
            value = f'{default_name}()'
    elif f.init:
        if f.default is MISSING:
            value = f.name
        elif f.default is not MISSING:
            globals[default_name] = f.default
            value = f.name
    elif slots and f.default is not MISSING:
        globals[default_name] = f.default
        value = default_name
    else:
        return None
    if f._field_type is _FIELD_INITVAR:
        return None
    return _field_assign(frozen, f.name, value, self_name)

def _init_param(f):
    if f.default is MISSING and f.default_factory is MISSING:
        default = ''
    elif f.default is not MISSING:
        default = f'=__dataclass_dflt_{f.name}__'
    elif f.default_factory is not MISSING:
        default = '=__dataclass_HAS_DEFAULT_FACTORY__'
    return f'{f.name}:__dataclass_type_{f.name}__{default}'

def _init_fn(fields, std_fields, kw_only_fields, frozen, has_post_init, self_name, globals, slots):
    seen_default = False
    for f in std_fields:
        if f.init:
            if not (f.default is MISSING and f.default_factory is MISSING):
                seen_default = True
            elif seen_default:
                raise TypeError(f'non-default argument {f.name!r} follows default argument')
    locals = {f'__dataclass_type_{f.name}__': f.type for f in fields}
    locals.update({'__dataclass_HAS_DEFAULT_FACTORY__': _HAS_DEFAULT_FACTORY, '__dataclass_builtins_object__': object})
    body_lines = []
    for f in fields:
        line = _field_init(f, frozen, locals, self_name, slots)
        if line:
            body_lines.append(line)
    if has_post_init:
        params_str = ','.join((f.name for f in fields if f._field_type is _FIELD_INITVAR))
        body_lines.append(f'{self_name}.{_POST_INIT_NAME}({params_str})')
    if not body_lines:
        body_lines = ['pass']
    _init_params = [_init_param(f) for f in std_fields]
    if kw_only_fields:
        _init_params += ['*']
        _init_params += [_init_param(f) for f in kw_only_fields]
    return _create_fn('__init__', [self_name] + _init_params, body_lines, locals=locals, globals=globals, return_type=None)

def _repr_fn(fields, globals):
    fn = _create_fn('__repr__', ('self',), ['return self.__class__.__qualname__ + f"(' + ', '.join([f'{f.name}={{self.{f.name}!r}}' for f in fields]) + ')"'], globals=globals)
    return _recursive_repr(fn)

def _frozen_get_del_attr(cls, fields, globals):
    locals = {'cls': cls, 'FrozenInstanceError': FrozenInstanceError}
    condition = 'type(self) is cls'
    if fields:
        condition += ' or name in {' + ', '.join((repr(f.name) for f in fields)) + '}'
    return (_create_fn('__setattr__', ('self', 'name', 'value'), (f'if {condition}:', ' raise FrozenInstanceError(f"cannot assign to field {name!r}")', f'super(cls, self).__setattr__(name, value)'), locals=locals, globals=globals), _create_fn('__delattr__', ('self', 'name'), (f'if {condition}:', ' raise FrozenInstanceError(f"cannot delete field {name!r}")', f'super(cls, self).__delattr__(name)'), locals=locals, globals=globals))

def _hash_fn(fields, globals):
    self_tuple = _tuple_str('self', fields)
    return _create_fn('__hash__', ('self',), [f'return hash({self_tuple})'], globals=globals)

def _is_type(annotation, cls, a_module, a_type, is_type_predicate):
    match = _MODULE_IDENTIFIER_RE.match(annotation)
    if match:
        ns = None
        module_name = match.group(1)
        if not module_name:
            ns = sys.modules.get(cls.__module__).__dict__
        else:
            module = sys.modules.get(cls.__module__)
            if module and module.__dict__.get(module_name) is a_module:
                ns = sys.modules.get(a_type.__module__).__dict__
        if ns and is_type_predicate(ns.get(match.group(2)), a_module):
            return True
    return False

def _get_field(cls, a_name, a_type, default_kw_only):
    default = getattr(cls, a_name, MISSING)
    if isinstance(default, Field):
        f = default
    else:
        if isinstance(default, types.MemberDescriptorType):
            default = MISSING
        f = field(default=default)
    f.name = a_name
    f.type = a_type
    f._field_type = _FIELD
    typing = sys.modules.get('typing')
    if typing:
        if _is_classvar(a_type, typing) or (isinstance(f.type, str) and _is_type(f.type, cls, typing, typing.ClassVar, _is_classvar)):
            f._field_type = _FIELD_CLASSVAR
    if f._field_type is _FIELD:
        dataclasses = sys.modules[__name__]
        if _is_initvar(a_type, dataclasses) or (isinstance(f.type, str) and _is_type(f.type, cls, dataclasses, dataclasses.InitVar, _is_initvar)):
            f._field_type = _FIELD_INITVAR
    if f._field_type in (_FIELD_CLASSVAR, _FIELD_INITVAR):
        if f.default_factory is not MISSING:
            raise TypeError(f'field {f.name} cannot have a default factory')
    if f._field_type in (_FIELD, _FIELD_INITVAR):
        if f.kw_only is MISSING:
            f.kw_only = default_kw_only
    else:
        assert f._field_type is _FIELD_CLASSVAR
        if f.kw_only is not MISSING:
            raise TypeError(f'field {f.name} is a ClassVar but specifies kw_only')
    if f._field_type is _FIELD and f.default.__class__.__hash__ is None:
        raise ValueError(f'mutable default {type(f.default)} for field {f.name} is not allowed: use default_factory')
    return f

def _set_qualname(cls, value):
    if isinstance(value, FunctionType):
        value.__qualname__ = f'{cls.__qualname__}.{value.__name__}'
    return value

def _set_new_attribute(cls, name, value):
    if name in cls.__dict__:
        return True
    _set_qualname(cls, value)
    setattr(cls, name, value)
    return False

def _hash_add(cls, fields, globals):
    flds = [f for f in fields if (f.compare if f.hash is None else f.hash)]
    return _set_qualname(cls, _hash_fn(flds, globals))

def _dataclass_setstate(self, state):
    for field, value in zip(fields(self), state):
        object.__setattr__(self, field.name, value)

def _add_slots(cls, is_frozen, weakref_slot):
    if '__slots__' in cls.__dict__:
        raise TypeError(f'{cls.__name__} already specifies __slots__')
    cls_dict = dict(cls.__dict__)
    field_names = tuple((f.name for f in fields(cls)))
    inherited_slots = set(itertools.chain.from_iterable(map(_get_slots, cls.__mro__[1:-1])))
    cls_dict['__slots__'] = tuple(itertools.filterfalse(inherited_slots.__contains__, itertools.chain(field_names, ('__weakref__',) if weakref_slot else ())))
    for field_name in field_names:
        cls_dict.pop(field_name, None)
    cls_dict.pop('__dict__', None)
    cls_dict.pop('__weakref__', None)
    qualname = getattr(cls, '__qualname__', None)
    cls = type(cls)(cls.__name__, cls.__bases__, cls_dict)
    if qualname is not None:
        cls.__qualname__ = qualname
    if is_frozen:
        if '__getstate__' not in cls_dict:
            cls.__getstate__ = _dataclass_getstate
        if '__setstate__' not in cls_dict:
            cls.__setstate__ = _dataclass_setstate
    return cls

def dataclass(cls=None, /, *, init=True, repr=True, eq=True, order=False, unsafe_hash=False, frozen=False, match_args=True, kw_only=False, slots=False, weakref_slot=False):
    """Add dunder methods based on the fields defined in the class.

    Examines PEP 526 __annotations__ to determine fields.

    If init is true, an __init__() method is added to the class. If repr
    is true, a __repr__() method is added. If order is true, rich
    comparison dunder methods are added. If unsafe_hash is true, a
    __hash__() method is added. If frozen is true, fields may not be
    assigned to after instance creation. If match_args is true, the
    __match_args__ tuple is added. If kw_only is true, then by default
    all fields are keyword-only. If slots is true, a new class with a
    __slots__ attribute is returned."""
    def wrap(cls):
        return _process_class(cls, init, repr, eq, order, unsafe_hash, frozen, match_args, kw_only, slots, weakref_slot)
    if cls is None:
        return wrap
    return wrap(cls)

def fields(class_or_instance):
    """Return a tuple describing the fields of this dataclass.

    Accepts a dataclass or an instance of one. Tuple elements are of
    type Field."""
    try:
        fields = getattr(class_or_instance, _FIELDS)
    except AttributeError:
        raise TypeError('must be called with a dataclass type or instance') from None
    return tuple((f for f in fields.values() if f._field_type is _FIELD))

def _is_dataclass_instance(obj):
    """Returns True if obj is an instance of a dataclass."""
    return hasattr(type(obj), _FIELDS)

def asdict(obj, *, dict_factory=dict):
    """Return the fields of a dataclass instance as a new dictionary mapping
    field names to field values.

    Example usage::

      @dataclass
      class C:
          x: int
          y: int

      c = C(1, 2)
      assert asdict(c) == {'x': 1, 'y': 2}

    If given, 'dict_factory' will be used instead of built-in dict.
    The function applies recursively to field values that are
    dataclass instances. This will also look into built-in containers:
    tuples, lists, and dicts. Other objects are copied with 'copy.deepcopy()'."""
    if not _is_dataclass_instance(obj):
        raise TypeError('asdict() should be called on dataclass instances')
    return _asdict_inner(obj, dict_factory)

def _asdict_inner(obj, dict_factory):
    if type(obj) in _ATOMIC_TYPES:
        return obj
    elif _is_dataclass_instance(obj):
        if dict_factory is dict:
            return {f.name: _asdict_inner(getattr(obj, f.name), dict) for f in fields(obj)}
        else:
            result = []
            for f in fields(obj):
                value = _asdict_inner(getattr(obj, f.name), dict_factory)
                result.append((f.name, value))
            return dict_factory(result)
    elif isinstance(obj, tuple) and hasattr(obj, '_fields'):
        return type(obj)(*[_asdict_inner(v, dict_factory) for v in obj])
    elif isinstance(obj, (list, tuple)):
        return type(obj)((_asdict_inner(v, dict_factory) for v in obj))
    elif isinstance(obj, dict):
        if hasattr(type(obj), 'default_factory'):
            result = type(obj)(getattr(obj, 'default_factory'))
            for k, v in obj.items():
                result[_asdict_inner(k, dict_factory)] = _asdict_inner(v, dict_factory)
            return result
        return type(obj)(((_asdict_inner(k, dict_factory), _asdict_inner(v, dict_factory)) for k, v in obj.items()))
    else:
        return copy.deepcopy(obj)

def astuple(obj, *, tuple_factory=tuple):
    """Return the fields of a dataclass instance as a new tuple of field values.

    Example usage::

      @dataclass
      class C:
          x: int
          y: int

      c = C(1, 2)
      assert astuple(c) == (1, 2)

    If given, 'tuple_factory' will be used instead of built-in tuple.
    The function applies recursively to field values that are
    dataclass instances. This will also look into built-in containers:
    tuples, lists, and dicts. Other objects are copied with 'copy.deepcopy()'."""
    if not _is_dataclass_instance(obj):
        raise TypeError('astuple() should be called on dataclass instances')
    return _astuple_inner(obj, tuple_factory)

def _astuple_inner(obj, tuple_factory):
    if type(obj) in _ATOMIC_TYPES:
        return obj
    elif _is_dataclass_instance(obj):
        result = []
        for f in fields(obj):
            value = _astuple_inner(getattr(obj, f.name), tuple_factory)
            result.append(value)
        return tuple_factory(result)
    elif isinstance(obj, tuple) and hasattr(obj, '_fields'):
        return type(obj)(*[_astuple_inner(v, tuple_factory) for v in obj])
    elif isinstance(obj, (list, tuple)):
        return type(obj)((_astuple_inner(v, tuple_factory) for v in obj))
    elif isinstance(obj, dict):
        obj_type = type(obj)
        if hasattr(obj_type, 'default_factory'):
            result = obj_type(getattr(obj, 'default_factory'))
            for k, v in obj.items():
                result[_astuple_inner(k, tuple_factory)] = _astuple_inner(v, tuple_factory)
            return result
        return obj_type(((_astuple_inner(k, tuple_factory), _astuple_inner(v, tuple_factory)) for k, v in obj.items()))
    else:
        return copy.deepcopy(obj)

def replace(obj, /, **changes):
    """Return a new object replacing specified fields with new values.

    This is especially useful for frozen classes.  Example usage::

      @dataclass(frozen=True)
      class C:
          x: int
          y: int

      c = C(1, 2)
      c1 = replace(c, x=3)
      assert c1.x == 3 and c1.y == 2"""
    if not _is_dataclass_instance(obj):
        raise TypeError('replace() should be called on dataclass instances')
    for f in getattr(obj, _FIELDS).values():
        if f._field_type is _FIELD_CLASSVAR:
            continue
        if not f.init:
            if f.name in changes:
                raise ValueError(f'field {f.name} is declared with init=False, it cannot be specified with replace()')
            continue
        if f.name not in changes:
            if f._field_type is _FIELD_INITVAR and f.default is MISSING:
                raise ValueError(f'InitVar {f.name!r} must be specified with replace()')
            changes[f.name] = getattr(obj, f.name)
    return obj.__class__(**changes)

@functools.wraps(user_function)
def wrapper(self):
    key = (id(self), _thread.get_ident())
    if key in repr_running:
        return '...'
    repr_running.add(key)
    try:
        result = user_function(self)
    finally:
        repr_running.discard(key)
    return result

def __repr__(self):
    if isinstance(self.type, type):
        type_name = self.type.__name__
    else:
        type_name = repr(self.type)
    return f'dataclasses.InitVar[{type_name}]'

@_recursive_repr
def __repr__(self):
    return f'Field(name={self.name!r},type={self.type!r},default={self.default!r},default_factory={self.default_factory!r},init={self.init!r},repr={self.repr!r},hash={self.hash!r},compare={self.compare!r},metadata={self.metadata!r},kw_only={self.kw_only!r},_field_type={self._field_type})'

def __set_name__(self, owner, name):
    func = getattr(type(self.default), '__set_name__', None)
    if func:
        func(self.default, owner, name)

def open(file, flag='r', mode=438):
    """Open or create database at path given by *file*.

    Optional argument *flag* can be 'r' (default) for read-only access, 'w'
    for read-write access of an existing database, 'c' for read-write access
    to a new or existing database, and 'n' for read-write access to a new
    database.

    Note: 'r' and 'w' fail if the database doesn't exist; 'c' creates it
    only if it doesn't exist; and 'n' always creates a new database."""
    global _defaultmod
    if _defaultmod is None:
        for name in _names:
            try:
                mod = __import__(name, fromlist=['open'])
            except ImportError:
                continue
            if not _defaultmod:
                _defaultmod = mod
            _modules[name] = mod
        if not _defaultmod:
            raise ImportError('no dbm clone found; tried %s' % _names)
    result = whichdb(file) if 'n' not in flag else None
    if result is None:
        if 'c' in flag or 'n' in flag:
            mod = _defaultmod
        else:
            raise error[0]("db file doesn't exist; use 'c' or 'n' flag to create a new db")
    elif result == '':
        raise error[0]('db type could not be determined')
    elif result not in _modules:
        raise error[0]('db type is {0}, but the module is not available'.format(result))
    else:
        mod = _modules[result]
    return mod.open(file, flag, mode)

def open(file, flag='c', mode=438):
    """Open the database file, filename, and return corresponding object.

    The flag argument, used to control how the database is opened in the
    other DBM implementations, supports only the semantics of 'c' and 'n'
    values.  Other values will default to the semantics of 'c' value:
    the database will always opened for update and will be created if it
    does not exist.

    The optional mode argument is the UNIX mode of the file, used only when
    the database has to be created.  It defaults to octal code 0o666 (and
    will be modified by the prevailing umask)."""
    try:
        um = _os.umask(0)
        _os.umask(um)
    except AttributeError:
        pass
    else:
        mode = mode & ~um
    if flag not in ('r', 'w', 'c', 'n'):
        raise ValueError("Flag must be one of 'r', 'w', 'c', or 'n'")
    return _Database(file, mode, flag=flag)

def _create(self, flag):
    if flag == 'n':
        for filename in (self._datfile, self._bakfile, self._dirfile):
            try:
                _os.remove(filename)
            except OSError:
                pass
    try:
        f = _io.open(self._datfile, 'r', encoding='Latin-1')
    except OSError:
        if flag not in ('c', 'n'):
            raise
        with _io.open(self._datfile, 'w', encoding='Latin-1') as f:
            self._chmod(self._datfile)
    else:
        f.close()

def _update(self, flag):
    self._modified = False
    self._index = {}
    try:
        f = _io.open(self._dirfile, 'r', encoding='Latin-1')
    except OSError:
        if flag not in ('c', 'n'):
            raise
        self._modified = True
    else:
        with f:
            for line in f:
                line = line.rstrip()
                key, pos_and_siz_pair = _ast.literal_eval(line)
                key = key.encode('Latin-1')
                self._index[key] = pos_and_siz_pair

def _commit(self):
    if self._index is None or not self._modified:
        return
    try:
        self._os.unlink(self._bakfile)
    except OSError:
        pass
    try:
        self._os.rename(self._dirfile, self._bakfile)
    except OSError:
        pass
    with self._io.open(self._dirfile, 'w', encoding='Latin-1') as f:
        self._chmod(self._dirfile)
        for key, pos_and_siz_pair in self._index.items():
            entry = '%r, %r\n' % (key.decode('Latin-1'), pos_and_siz_pair)
            f.write(entry)

def _verify_open(self):
    if self._index is None:
        raise error('DBM object has already been closed')

def _setval(self, pos, val):
    with _io.open(self._datfile, 'rb+') as f:
        f.seek(pos)
        f.write(val)
    return (pos, len(val))

def __delitem__(self, key):
    if self._readonly:
        raise error('The database is opened for reading only')
    if isinstance(key, str):
        key = key.encode('utf-8')
    self._verify_open()
    self._modified = True
    del self._index[key]
    self._commit()

def keys(self):
    try:
        return list(self._index)
    except TypeError:
        raise error('DBM object has already been closed') from None

def __contains__(self, key):
    if isinstance(key, str):
        key = key.encode('utf-8')
    try:
        return key in self._index
    except TypeError:
        if self._index is None:
            raise error('DBM object has already been closed') from None
        else:
            raise

def iterkeys(self):
    try:
        return iter(self._index)
    except TypeError:
        raise error('DBM object has already been closed') from None

def __len__(self):
    try:
        return len(self._index)
    except TypeError:
        raise error('DBM object has already been closed') from None

def close(self):
    try:
        self._commit()
    finally:
        self._index = self._datfile = self._dirfile = self._bakfile = None

def _calculate_ratio(matches, length):
    if length:
        return 2.0 * matches / length
    return 1.0

def _keep_original_ws(s, tag_s):
    """Replace whitespace with the original whitespace characters in `s`"""
    return ''.join((c if tag_c == ' ' and c.isspace() else tag_c for c, tag_c in zip(s, tag_s)))

def _format_range_unified(start, stop):
    """Convert range to the "ed" format"""
    beginning = start + 1
    length = stop - start
    if length == 1:
        return '{}'.format(beginning)
    if not length:
        beginning -= 1
    return '{},{}'.format(beginning, length)

def _format_range_context(start, stop):
    """Convert range to the "ed" format"""
    beginning = start + 1
    length = stop - start
    if not length:
        beginning -= 1
    if length <= 1:
        return '{}'.format(beginning)
    return '{},{}'.format(beginning, beginning + length - 1)

def _check_types(a, b, *args):
    if a and (not isinstance(a[0], str)):
        raise TypeError('lines to compare must be str, not %s (%r)' % (type(a[0]).__name__, a[0]))
    if b and (not isinstance(b[0], str)):
        raise TypeError('lines to compare must be str, not %s (%r)' % (type(b[0]).__name__, b[0]))
    for arg in args:
        if not isinstance(arg, str):
            raise TypeError('all arguments must be str, not: %r' % (arg,))

def _test():
    import doctest, difflib
    return doctest.testmod(difflib)

def __chain_b(self):
    b = self.b
    self.b2j = b2j = {}
    for i, elt in enumerate(b):
        indices = b2j.setdefault(elt, [])
        indices.append(i)
    self.bjunk = junk = set()
    isjunk = self.isjunk
    if isjunk:
        for elt in b2j.keys():
            if isjunk(elt):
                junk.add(elt)
        for elt in junk:
            del b2j[elt]
    self.bpopular = popular = set()
    n = len(b)
    if self.autojunk and n >= 200:
        ntest = n // 100 + 1
        for elt, idxs in b2j.items():
            if len(idxs) > ntest:
                popular.add(elt)
        for elt in popular:
            del b2j[elt]

def quick_ratio(self):
    """Return an upper bound on ratio() relatively quickly.

    This isn't defined beyond that it is an upper bound on .ratio(), and
    is faster to compute."""
    if self.fullbcount is None:
        self.fullbcount = fullbcount = {}
        for elt in self.b:
            fullbcount[elt] = fullbcount.get(elt, 0) + 1
    fullbcount = self.fullbcount
    avail = {}
    availhas, matches = (avail.__contains__, 0)
    for elt in self.a:
        if availhas(elt):
            numb = avail[elt]
        else:
            numb = fullbcount.get(elt, 0)
        avail[elt] = numb - 1
        if numb > 0:
            matches = matches + 1
    return _calculate_ratio(matches, len(self.a) + len(self.b))

def real_quick_ratio(self):
    """Return an upper bound on ratio() very quickly.

    This isn't defined beyond that it is an upper bound on .ratio(), and
    is faster to compute than either .ratio() or .quick_ratio()."""
    la, lb = (len(self.a), len(self.b))
    return _calculate_ratio(min(la, lb), la + lb)

def _dump(self, tag, x, lo, hi):
    """Generate comparison results for a same-tagged range."""
    for i in range(lo, hi):
        yield ('%s %s' % (tag, x[i]))

def _plain_replace(self, a, alo, ahi, b, blo, bhi):
    assert alo < ahi and blo < bhi
    if bhi - blo < ahi - alo:
        first = self._dump('+', b, blo, bhi)
        second = self._dump('-', a, alo, ahi)
    else:
        first = self._dump('-', a, alo, ahi)
        second = self._dump('+', b, blo, bhi)
    for g in (first, second):
        yield from g

def _fancy_helper(self, a, alo, ahi, b, blo, bhi):
    g = []
    if alo < ahi:
        if blo < bhi:
            g = self._fancy_replace(a, alo, ahi, b, blo, bhi)
        else:
            g = self._dump('-', a, alo, ahi)
    elif blo < bhi:
        g = self._dump('+', b, blo, bhi)
    yield from g

def decode(s):
    try:
        return s.decode('ascii', 'surrogateescape')
    except AttributeError as err:
        msg = 'all arguments must be bytes, not %s (%r)' % (type(s).__name__, s)
        raise TypeError(msg) from err

def _line_wrapper(self, diffs):
    """Returns iterator that splits (wraps) mdiff text lines"""
    for fromdata, todata, flag in diffs:
        if flag is None:
            yield (fromdata, todata, flag)
            continue
        (fromline, fromtext), (toline, totext) = (fromdata, todata)
        fromlist, tolist = ([], [])
        self._split_line(fromlist, fromline, fromtext)
        self._split_line(tolist, toline, totext)
        while fromlist or tolist:
            if fromlist:
                fromdata = fromlist.pop(0)
            else:
                fromdata = ('', ' ')
            if tolist:
                todata = tolist.pop(0)
            else:
                todata = ('', ' ')
            yield (fromdata, todata, flag)

def _collect_lines(self, diffs):
    """Collects mdiff output into separate lists

    Before storing the mdiff from/to data into a list, it is converted
    into a single line of text with HTML markup."""
    fromlist, tolist, flaglist = ([], [], [])
    for fromdata, todata, flag in diffs:
        try:
            fromlist.append(self._format_line(0, flag, *fromdata))
            tolist.append(self._format_line(1, flag, *todata))
        except TypeError:
            fromlist.append(None)
            tolist.append(None)
        flaglist.append(flag)
    return (fromlist, tolist, flaglist)

def _convert_flags(self, fromlist, tolist, flaglist, context, numlines):
    """Makes list of "next" links"""
    toprefix = self._prefix[1]
    next_id = [''] * len(flaglist)
    next_href = [''] * len(flaglist)
    num_chg, in_change = (0, False)
    last = 0
    for i, flag in enumerate(flaglist):
        if flag:
            if not in_change:
                in_change = True
                last = i
                i = max([0, i - numlines])
                next_id[i] = ' id="difflib_chg_%s_%d"' % (toprefix, num_chg)
                num_chg += 1
                next_href[last] = '<a href="#difflib_chg_%s_%d">n</a>' % (toprefix, num_chg)
        else:
            in_change = False
    if not flaglist:
        flaglist = [False]
        next_id = ['']
        next_href = ['']
        last = 0
        if context:
            fromlist = ['<td></td><td>&nbsp;No Differences Found&nbsp;</td>']
            tolist = fromlist
        else:
            fromlist = tolist = ['<td></td><td>&nbsp;Empty File&nbsp;</td>']
    if not flaglist[0]:
        next_href[0] = '<a href="#difflib_chg_%s_0">f</a>' % toprefix
    next_href[last] = '<a href="#difflib_chg_%s_top">t</a>' % toprefix
    return (fromlist, tolist, flaglist, next_href, next_id)

def expand_tabs(line):
    line = line.replace(' ', '\x00')
    line = line.expandtabs(self._tabsize)
    line = line.replace(' ', '\t')
    return line.replace('\x00', ' ').rstrip('\n')

def record_sub_info(match_object, sub_info=sub_info):
    sub_info.append([match_object.group(1)[0], match_object.span()])
    return match_object.group(1)

def _try_compile(source, name):
    """Attempts to compile the given source, first as an expression and
    then as a statement if the first approach fails.

    Utility function to accept strings in functions that otherwise
    expect code objects"""
    try:
        return compile(source, name, 'eval')
    except SyntaxError:
        pass
    return compile(source, name, 'exec')

def dis(x=None, *, file=None, depth=None, show_caches=False, adaptive=False):
    """Disassemble classes, methods, functions, and other compiled objects.

    With no argument, disassemble the last traceback.

    Compiled objects currently include generator objects, async generator
    objects, and coroutine objects, all of which store their code object
    in a special attribute."""
    if x is None:
        distb(file=file, show_caches=show_caches, adaptive=adaptive)
        return
    if hasattr(x, '__func__'):
        x = x.__func__
    if hasattr(x, '__code__'):
        x = x.__code__
    elif hasattr(x, 'gi_code'):
        x = x.gi_code
    elif hasattr(x, 'ag_code'):
        x = x.ag_code
    elif hasattr(x, 'cr_code'):
        x = x.cr_code
    if hasattr(x, '__dict__'):
        items = sorted(x.__dict__.items())
        for name, x1 in items:
            if isinstance(x1, _have_code):
                print('Disassembly of %s:' % name, file=file)
                try:
                    dis(x1, file=file, depth=depth, show_caches=show_caches, adaptive=adaptive)
                except TypeError as msg:
                    print('Sorry:', msg, file=file)
                print(file=file)
    elif hasattr(x, 'co_code'):
        _disassemble_recursive(x, file=file, depth=depth, show_caches=show_caches, adaptive=adaptive)
    elif isinstance(x, (bytes, bytearray)):
        _disassemble_bytes(x, file=file, show_caches=show_caches)
    elif isinstance(x, str):
        _disassemble_str(x, file=file, depth=depth, show_caches=show_caches, adaptive=adaptive)
    else:
        raise TypeError("don't know how to disassemble %s objects" % type(x).__name__)

def distb(tb=None, *, file=None, show_caches=False, adaptive=False):
    """Disassemble a traceback (default: last traceback)."""
    if tb is None:
        try:
            if hasattr(sys, 'last_exc'):
                tb = sys.last_exc.__traceback__
            else:
                tb = sys.last_traceback
        except AttributeError:
            raise RuntimeError('no last traceback to disassemble') from None
        while tb.tb_next:
            tb = tb.tb_next
    disassemble(tb.tb_frame.f_code, tb.tb_lasti, file=file, show_caches=show_caches, adaptive=adaptive)

def pretty_flags(flags):
    """Return pretty representation of code flags."""
    names = []
    for i in range(32):
        flag = 1 << i
        if flags & flag:
            names.append(COMPILER_FLAG_NAMES.get(flag, hex(flag)))
            flags ^= flag
            if not flags:
                break
    else:
        names.append(hex(flags))
    return ', '.join(names)

def _get_code_object(x):
    """Helper to handle methods, compiled or raw code objects, and strings."""
    if hasattr(x, '__func__'):
        x = x.__func__
    if hasattr(x, '__code__'):
        x = x.__code__
    elif hasattr(x, 'gi_code'):
        x = x.gi_code
    elif hasattr(x, 'ag_code'):
        x = x.ag_code
    elif hasattr(x, 'cr_code'):
        x = x.cr_code
    if isinstance(x, str):
        x = _try_compile(x, '<disassembly>')
    if hasattr(x, 'co_code'):
        return x
    raise TypeError("don't know how to disassemble %s objects" % type(x).__name__)

def _deoptop(op):
    name = _all_opname[op]
    return _all_opmap[deoptmap[name]] if name in deoptmap else op

def code_info(x):
    """Formatted details of methods, functions, or code."""
    return _format_code_info(_get_code_object(x))

def _format_code_info(co):
    lines = []
    lines.append('Name:              %s' % co.co_name)
    lines.append('Filename:          %s' % co.co_filename)
    lines.append('Argument count:    %s' % co.co_argcount)
    lines.append('Positional-only arguments: %s' % co.co_posonlyargcount)
    lines.append('Kw-only arguments: %s' % co.co_kwonlyargcount)
    lines.append('Number of locals:  %s' % co.co_nlocals)
    lines.append('Stack size:        %s' % co.co_stacksize)
    lines.append('Flags:             %s' % pretty_flags(co.co_flags))
    if co.co_consts:
        lines.append('Constants:')
        for i_c in enumerate(co.co_consts):
            lines.append('%4d: %r' % i_c)
    if co.co_names:
        lines.append('Names:')
        for i_n in enumerate(co.co_names):
            lines.append('%4d: %s' % i_n)
    if co.co_varnames:
        lines.append('Variable names:')
        for i_n in enumerate(co.co_varnames):
            lines.append('%4d: %s' % i_n)
    if co.co_freevars:
        lines.append('Free variables:')
        for i_n in enumerate(co.co_freevars):
            lines.append('%4d: %s' % i_n)
    if co.co_cellvars:
        lines.append('Cell variables:')
        for i_n in enumerate(co.co_cellvars):
            lines.append('%4d: %s' % i_n)
    return '\n'.join(lines)

def _get_name_info(name_index, get_name, **extrainfo):
    """Helper to get optional details about named references

    Returns the dereferenced name as both value and repr if the name
    list is defined.
    Otherwise returns the sentinel value dis.UNKNOWN for the value
    and an empty string for its repr."""
    if get_name is not None:
        argval = get_name(name_index, **extrainfo)
        return (argval, argval)
    else:
        return (UNKNOWN, '')

def _disassemble_recursive(co, *, file=None, depth=None, show_caches=False, adaptive=False):
    disassemble(co, file=file, show_caches=show_caches, adaptive=adaptive)
    if depth is None or depth > 0:
        if depth is not None:
            depth = depth - 1
        for x in co.co_consts:
            if hasattr(x, 'co_code'):
                print(file=file)
                print('Disassembly of %r:' % (x,), file=file)
                _disassemble_recursive(x, file=file, depth=depth, show_caches=show_caches, adaptive=adaptive)

def _disassemble_bytes(code, lasti=-1, varname_from_oparg=None, names=None, co_consts=None, linestarts=None, *, file=None, line_offset=0, exception_entries=(), co_positions=None, show_caches=False):
    show_lineno = bool(linestarts)
    if show_lineno:
        maxlineno = max(linestarts.values()) + line_offset
        if maxlineno >= 1000:
            lineno_width = len(str(maxlineno))
        else:
            lineno_width = 3
    else:
        lineno_width = 0
    maxoffset = len(code) - 2
    if maxoffset >= 10000:
        offset_width = len(str(maxoffset))
    else:
        offset_width = 4
    for instr in _get_instructions_bytes(code, varname_from_oparg, names, co_consts, linestarts, line_offset=line_offset, exception_entries=exception_entries, co_positions=co_positions, show_caches=show_caches):
        new_source_line = show_lineno and instr.starts_line is not None and (instr.offset > 0)
        if new_source_line:
            print(file=file)
        if show_caches:
            is_current_instr = instr.offset == lasti
        else:
            is_current_instr = instr.offset <= lasti <= instr.offset + 2 * _inline_cache_entries[_deoptop(instr.opcode)]
        print(instr._disassemble(lineno_width, is_current_instr, offset_width), file=file)
    if exception_entries:
        print('ExceptionTable:', file=file)
        for entry in exception_entries:
            lasti = ' lasti' if entry.lasti else ''
            end = entry.end - 2
            print(f'  {entry.start} to {end} -> {entry.target} [{entry.depth}]{lasti}', file=file)

def _disassemble_str(source, **kwargs):
    """Compile the source string, then disassemble the code object."""
    _disassemble_recursive(_try_compile(source, '<dis>'), **kwargs)

def _unpack_opargs(code):
    extended_arg = 0
    caches = 0
    for i in range(0, len(code), 2):
        if caches:
            caches -= 1
            continue
        op = code[i]
        deop = _deoptop(op)
        caches = _inline_cache_entries[deop]
        if deop in hasarg:
            arg = code[i + 1] | extended_arg
            extended_arg = arg << 8 if deop == EXTENDED_ARG else 0
            if extended_arg >= _INT_OVERFLOW:
                extended_arg -= 2 * _INT_OVERFLOW
        else:
            arg = None
            extended_arg = 0
        yield (i, op, arg)

def findlabels(code):
    """Detect all offsets in a byte code which are jump targets.

    Return the list of offsets."""
    labels = []
    for offset, op, arg in _unpack_opargs(code):
        if arg is not None:
            deop = _deoptop(op)
            caches = _inline_cache_entries[deop]
            if deop in hasjrel:
                if _is_backward_jump(deop):
                    arg = -arg
                label = offset + 2 + arg * 2
                label += 2 * caches
            elif deop in hasjabs:
                label = arg * 2
            else:
                continue
            if label not in labels:
                labels.append(label)
    return labels

def findlinestarts(code):
    """Find the offsets in a byte code which are start of lines in the source.

    Generate pairs (offset, lineno)"""
    lastline = None
    for start, end, line in code.co_lines():
        if line is not None and line != lastline:
            lastline = line
            yield (start, line)
    return

def _find_store_names(co):
    """Find names of variables which are written in the code

    Generate sequence of strings"""
    STORE_OPS = {opmap['STORE_NAME'], opmap['STORE_GLOBAL']}
    names = co.co_names
    for _, op, arg in _unpack_opargs(co.co_code):
        if op in STORE_OPS:
            yield names[arg]

def _disassemble(self, lineno_width=3, mark_as_current=False, offset_width=4):
    """Format instruction details for inclusion in disassembly output

    *lineno_width* sets the width of the line number field (0 omits it)
    *mark_as_current* inserts a '-->' marker arrow as part of the line
    *offset_width* sets the width of the instruction offset field"""
    fields = []
    if lineno_width:
        if self.starts_line is not None:
            lineno_fmt = '%%%dd' % lineno_width
            fields.append(lineno_fmt % self.starts_line)
        else:
            fields.append(' ' * lineno_width)
    if mark_as_current:
        fields.append('-->')
    else:
        fields.append('   ')
    if self.is_jump_target:
        fields.append('>>')
    else:
        fields.append('  ')
    fields.append(repr(self.offset).rjust(offset_width))
    fields.append(self.opname.ljust(_OPNAME_WIDTH))
    if self.arg is not None:
        fields.append(repr(self.arg).rjust(_OPARG_WIDTH))
        if self.argrepr:
            fields.append('(' + self.argrepr + ')')
    return ' '.join(fields).rstrip()

def __iter__(self):
    co = self.codeobj
    return _get_instructions_bytes(_get_code_array(co, self.adaptive), co._varname_from_oparg, co.co_names, co.co_consts, self._linestarts, line_offset=self._line_offset, exception_entries=self.exception_entries, co_positions=co.co_positions(), show_caches=self.show_caches)

@classmethod
def from_traceback(cls, tb, *, show_caches=False, adaptive=False):
    """Construct a Bytecode from the given traceback"""
    while tb.tb_next:
        tb = tb.tb_next
    return cls(tb.tb_frame.f_code, current_offset=tb.tb_lasti, show_caches=show_caches, adaptive=adaptive)

def info(self):
    """Return formatted information about the code object."""
    return _format_code_info(self.codeobj)

def _extract_future_flags(globs):
    """Return the compiler-flags associated with the future features that
    have been imported into the given namespace (globs)."""
    flags = 0
    for fname in __future__.all_feature_names:
        feature = globs.get(fname, None)
        if feature is getattr(__future__, fname):
            flags |= feature.compiler_flag
    return flags

def _normalize_module(module, depth=2):
    """Return the module specified by `module`.  In particular:
      - If `module` is a module, then return module.
      - If `module` is a string, then import and return the
        module with that name.
      - If `module` is None, then return the calling module.
        The calling module is assumed to be the module of
        the stack frame at the given depth in the call stack."""
    if inspect.ismodule(module):
        return module
    elif isinstance(module, str):
        return __import__(module, globals(), locals(), ['*'])
    elif module is None:
        try:
            try:
                return sys.modules[sys._getframemodulename(depth)]
            except AttributeError:
                return sys.modules[sys._getframe(depth).f_globals['__name__']]
        except KeyError:
            pass
    else:
        raise TypeError('Expected a module, string, or None')

def _load_testfile(filename, package, module_relative, encoding):
    if module_relative:
        package = _normalize_module(package, 3)
        filename = _module_relative_path(package, filename)
        if (loader := getattr(package, '__loader__', None)) is None:
            try:
                loader = package.__spec__.loader
            except AttributeError:
                pass
        if hasattr(loader, 'get_data'):
            file_contents = loader.get_data(filename)
            file_contents = file_contents.decode(encoding)
            return (_newline_convert(file_contents), filename)
    with open(filename, encoding=encoding) as f:
        return (f.read(), filename)

def _indent(s, indent=4):
    """Add the given number of space characters to the beginning of
    every non-blank line in `s`, and return the result."""
    return re.sub('(?m)^(?!$)', indent * ' ', s)

def _ellipsis_match(want, got):
    """Essentially the only subtle case:
    >>> _ellipsis_match('aa...aa', 'aaa')
    False"""
    if ELLIPSIS_MARKER not in want:
        return want == got
    ws = want.split(ELLIPSIS_MARKER)
    assert len(ws) >= 2
    startpos, endpos = (0, len(got))
    w = ws[0]
    if w:
        if got.startswith(w):
            startpos = len(w)
            del ws[0]
        else:
            return False
    w = ws[-1]
    if w:
        if got.endswith(w):
            endpos -= len(w)
            del ws[-1]
        else:
            return False
    if startpos > endpos:
        return False
    for w in ws:
        startpos = got.find(w, startpos, endpos)
        if startpos < 0:
            return False
        startpos += len(w)
    return True

def _comment_line(line):
    """Return a commented form of the given line"""
    line = line.rstrip()
    if line:
        return '# ' + line
    else:
        return '#'

def _strip_exception_details(msg):
    start, end = (0, len(msg))
    i = msg.find('\n')
    if i >= 0:
        end = i
    i = msg.find(':', 0, end)
    if i >= 0:
        end = i
    i = msg.rfind('.', 0, end)
    if i >= 0:
        start = i + 1
    return msg[start:end]

def _module_relative_path(module, test_path):
    if not inspect.ismodule(module):
        raise TypeError('Expected a module: %r' % module)
    if test_path.startswith('/'):
        raise ValueError('Module-relative files may not have absolute paths')
    test_path = os.path.join(*test_path.split('/'))
    if hasattr(module, '__file__'):
        basedir = os.path.split(module.__file__)[0]
    elif module.__name__ == '__main__':
        if len(sys.argv) > 0 and sys.argv[0] != '':
            basedir = os.path.split(sys.argv[0])[0]
        else:
            basedir = os.curdir
    else:
        if hasattr(module, '__path__'):
            for directory in module.__path__:
                fullpath = os.path.join(directory, test_path)
                if os.path.exists(fullpath):
                    return fullpath
        raise ValueError("Can't resolve paths relative to the module %r (it has no __file__)" % module.__name__)
    return os.path.join(basedir, test_path)

def DocFileTest(path, module_relative=True, package=None, globs=None, parser=DocTestParser(), encoding=None, **options):
    if globs is None:
        globs = {}
    else:
        globs = globs.copy()
    if package and (not module_relative):
        raise ValueError('Package may only be specified for module-relative paths.')
    doc, path = _load_testfile(path, package, module_relative, encoding or 'utf-8')
    if '__file__' not in globs:
        globs['__file__'] = path
    name = os.path.basename(path)
    test = parser.get_doctest(doc, globs, name, path, 0)
    return DocFileCase(test, **options)

def debug_script(src, pm=False, globs=None):
    """Debug a test script.  `src` is the script, as a string."""
    import pdb
    if globs:
        globs = globs.copy()
    else:
        globs = {}
    if pm:
        try:
            exec(src, globs, globs)
        except:
            print(sys.exc_info()[1])
            p = pdb.Pdb(nosigint=True)
            p.reset()
            p.interaction(None, sys.exc_info()[2])
    else:
        pdb.Pdb(nosigint=True).run('exec(%r)' % src, globs, globs)

def getvalue(self):
    result = StringIO.getvalue(self)
    if result and (not result.endswith('\n')):
        result += '\n'
    return result

def truncate(self, size=None):
    self.seek(size)
    StringIO.truncate(self)

def set_trace(self, frame=None):
    self.__debugger_used = True
    if frame is None:
        frame = sys._getframe().f_back
    pdb.Pdb.set_trace(self, frame)

def set_continue(self):
    if self.__debugger_used:
        pdb.Pdb.set_continue(self)

def trace_dispatch(self, *args):
    save_stdout = sys.stdout
    sys.stdout = self.__out
    try:
        return pdb.Pdb.trace_dispatch(self, *args)
    finally:
        sys.stdout = save_stdout

def __init__(self, source, want, exc_msg=None, lineno=0, indent=0, options=None):
    if not source.endswith('\n'):
        source += '\n'
    if want and (not want.endswith('\n')):
        want += '\n'
    if exc_msg is not None and (not exc_msg.endswith('\n')):
        exc_msg += '\n'
    self.source = source
    self.want = want
    self.lineno = lineno
    self.indent = indent
    if options is None:
        options = {}
    self.options = options
    self.exc_msg = exc_msg

def __eq__(self, other):
    if type(self) is not type(other):
        return NotImplemented
    return self.source == other.source and self.want == other.want and (self.lineno == other.lineno) and (self.indent == other.indent) and (self.options == other.options) and (self.exc_msg == other.exc_msg)

def __eq__(self, other):
    if type(self) is not type(other):
        return NotImplemented
    return self.examples == other.examples and self.docstring == other.docstring and (self.globs == other.globs) and (self.name == other.name) and (self.filename == other.filename) and (self.lineno == other.lineno)

def __lt__(self, other):
    if not isinstance(other, DocTest):
        return NotImplemented
    self_lno = self.lineno if self.lineno is not None else -1
    other_lno = other.lineno if other.lineno is not None else -1
    return (self.name, self.filename, self_lno, id(self)) < (other.name, other.filename, other_lno, id(other))

def _find_options(self, source, name, lineno):
    """Return a dictionary containing option overrides extracted from
    option directives in the given source string.

    `name` is the string's name, and `lineno` is the line number
    where the example starts; both are used for error messages."""
    options = {}
    for m in self._OPTION_DIRECTIVE_RE.finditer(source):
        option_strings = m.group(1).replace(',', ' ').split()
        for option in option_strings:
            if option[0] not in '+-' or option[1:] not in OPTIONFLAGS_BY_NAME:
                raise ValueError('line %r of the doctest for %s has an invalid option: %r' % (lineno + 1, name, option))
            flag = OPTIONFLAGS_BY_NAME[option[1:]]
            options[flag] = option[0] == '+'
    if options and self._IS_BLANK_OR_COMMENT(source):
        raise ValueError('line %r of the doctest for %s has an option directive on a line with no example: %r' % (lineno, name, source))
    return options

def _min_indent(self, s):
    """Return the minimum indentation of any non-blank line in `s`"""
    indents = [len(indent) for indent in self._INDENT_RE.findall(s)]
    if len(indents) > 0:
        return min(indents)
    else:
        return 0

def _check_prompt_blank(self, lines, indent, name, lineno):
    """Given the lines of a source string (including prompts and
    leading indentation), check to make sure that every prompt is
    followed by a space character.  If any line is not followed by
    a space character, then raise ValueError."""
    for i, line in enumerate(lines):
        if len(line) >= indent + 4 and line[indent + 3] != ' ':
            raise ValueError('line %r of the docstring for %s lacks blank after %s: %r' % (lineno + i + 1, name, line[indent:indent + 3], line))

def _check_prefix(self, lines, prefix, name, lineno):
    """Check that every line in the given list starts with the given
    prefix; if any line does not, then raise a ValueError."""
    for i, line in enumerate(lines):
        if line and (not line.startswith(prefix)):
            raise ValueError('line %r of the docstring for %s has inconsistent leading whitespace: %r' % (lineno + i + 1, name, line))

def _from_module(self, module, object):
    """Return true if the given object is defined in the given
    module."""
    if module is None:
        return True
    elif inspect.getmodule(object) is not None:
        return module is inspect.getmodule(object)
    elif inspect.isfunction(object):
        return module.__dict__ is object.__globals__
    elif inspect.ismethoddescriptor(object) or inspect.ismethodwrapper(object):
        if hasattr(object, '__objclass__'):
            obj_mod = object.__objclass__.__module__
        elif hasattr(object, '__module__'):
            obj_mod = object.__module__
        else:
            return True
        return module.__name__ == obj_mod
    elif inspect.isclass(object):
        return module.__name__ == object.__module__
    elif hasattr(object, '__module__'):
        return module.__name__ == object.__module__
    elif isinstance(object, property):
        return True
    else:
        raise ValueError('object must be a class or function')

def _find(self, tests, obj, name, module, source_lines, globs, seen):
    """Find tests for the given object and any contained objects, and
    add them to `tests`."""
    if self._verbose:
        print('Finding tests in %s' % name)
    if id(obj) in seen:
        return
    seen[id(obj)] = 1
    test = self._get_test(obj, name, module, globs, source_lines)
    if test is not None:
        tests.append(test)
    if inspect.ismodule(obj) and self._recurse:
        for valname, val in obj.__dict__.items():
            valname = '%s.%s' % (name, valname)
            if (self._is_routine(val) or inspect.isclass(val)) and self._from_module(module, val):
                self._find(tests, val, valname, module, source_lines, globs, seen)
    if inspect.ismodule(obj) and self._recurse:
        for valname, val in getattr(obj, '__test__', {}).items():
            if not isinstance(valname, str):
                raise ValueError('DocTestFinder.find: __test__ keys must be strings: %r' % (type(valname),))
            if not (inspect.isroutine(val) or inspect.isclass(val) or inspect.ismodule(val) or isinstance(val, str)):
                raise ValueError('DocTestFinder.find: __test__ values must be strings, functions, methods, classes, or modules: %r' % (type(val),))
            valname = '%s.__test__.%s' % (name, valname)
            self._find(tests, val, valname, module, source_lines, globs, seen)
    if inspect.isclass(obj) and self._recurse:
        for valname, val in obj.__dict__.items():
            if isinstance(val, (staticmethod, classmethod)):
                val = val.__func__
            if (inspect.isroutine(val) or inspect.isclass(val) or isinstance(val, property)) and self._from_module(module, val):
                valname = '%s.%s' % (name, valname)
                self._find(tests, val, valname, module, source_lines, globs, seen)

def _get_test(self, obj, name, module, globs, source_lines):
    """Return a DocTest for the given object, if it defines a docstring;
    otherwise, return None."""
    if isinstance(obj, str):
        docstring = obj
    else:
        try:
            if obj.__doc__ is None:
                docstring = ''
            else:
                docstring = obj.__doc__
                if not isinstance(docstring, str):
                    docstring = str(docstring)
        except (TypeError, AttributeError):
            docstring = ''
    lineno = self._find_lineno(obj, source_lines)
    if self._exclude_empty and (not docstring):
        return None
    if module is None:
        filename = None
    else:
        filename = getattr(module, '__file__', None) or module.__name__
        if filename[-4:] == '.pyc':
            filename = filename[:-1]
    return self._parser.get_doctest(docstring, globs, name, filename, lineno)

def _find_lineno(self, obj, source_lines):
    """Return a line number of the given object's docstring.

    Returns `None` if the given object does not have a docstring."""
    lineno = None
    docstring = getattr(obj, '__doc__', None)
    if inspect.ismodule(obj) and docstring is not None:
        lineno = 0
    if inspect.isclass(obj) and docstring is not None:
        if source_lines is None:
            return None
        pat = re.compile('^\\s*class\\s*%s\\b' % re.escape(getattr(obj, '__name__', '-')))
        for i, line in enumerate(source_lines):
            if pat.match(line):
                lineno = i
                break
    if inspect.ismethod(obj):
        obj = obj.__func__
    if isinstance(obj, property):
        obj = obj.fget
    if inspect.isfunction(obj) and getattr(obj, '__doc__', None):
        obj = inspect.unwrap(obj)
        try:
            obj = obj.__code__
        except AttributeError:
            return None
    if inspect.istraceback(obj):
        obj = obj.tb_frame
    if inspect.isframe(obj):
        obj = obj.f_code
    if inspect.iscode(obj):
        lineno = obj.co_firstlineno - 1
    if lineno is not None:
        if source_lines is None:
            return lineno + 1
        pat = re.compile('(^|.*:)\\s*\\w*("|\\\')')
        for lineno in range(lineno, len(source_lines)):
            if pat.match(source_lines[lineno]):
                return lineno
    return None

def report_start(self, out, test, example):
    """Report that the test runner is about to process the given
    example.  (Only displays a message if verbose=True)"""
    if self._verbose:
        if example.want:
            out('Trying:\n' + _indent(example.source) + 'Expecting:\n' + _indent(example.want))
        else:
            out('Trying:\n' + _indent(example.source) + 'Expecting nothing\n')

def report_success(self, out, test, example, got):
    """Report that the given example ran successfully.  (Only
    displays a message if verbose=True)"""
    if self._verbose:
        out('ok\n')

def report_failure(self, out, test, example, got):
    """Report that the given example failed."""
    out(self._failure_header(test, example) + self._checker.output_difference(example, got, self.optionflags))

def report_unexpected_exception(self, out, test, example, exc_info):
    """Report that the given example raised an unexpected exception."""
    out(self._failure_header(test, example) + 'Exception raised:\n' + _indent(_exception_traceback(exc_info)))

def _failure_header(self, test, example):
    out = [self.DIVIDER]
    if test.filename:
        if test.lineno is not None and example.lineno is not None:
            lineno = test.lineno + example.lineno + 1
        else:
            lineno = '?'
        out.append('File "%s", line %s, in %s' % (test.filename, lineno, test.name))
    else:
        out.append('Line %s, in %s' % (example.lineno + 1, test.name))
    out.append('Failed example:')
    source = example.source
    out.append(_indent(source))
    return '\n'.join(out)

def __patched_linecache_getlines(self, filename, module_globals=None):
    m = self.__LINECACHE_FILENAME_RE.match(filename)
    if m and m.group('name') == self.test.name:
        example = self.test.examples[int(m.group('examplenum'))]
        return example.source.splitlines(keepends=True)
    else:
        return self.save_linecache_getlines(filename, module_globals)

def merge(self, other):
    d = self._name2ft
    for name, (f, t) in other._name2ft.items():
        if name in d:
            f2, t2 = d[name]
            f = f + f2
            t = t + t2
        d[name] = (f, t)

def _toAscii(self, s):
    """Convert string to hex-escaped ASCII string."""
    return str(s.encode('ASCII', 'backslashreplace'), 'ASCII')

def check_output(self, want, got, optionflags):
    """Return True iff the actual output from an example (`got`)
    matches the expected output (`want`).  These strings are
    always considered to match if they are identical; but
    depending on what option flags the test runner is using,
    several non-exact match types are also possible.  See the
    documentation for `TestRunner` for more information about
    option flags."""
    got = self._toAscii(got)
    want = self._toAscii(want)
    if got == want:
        return True
    if not optionflags & DONT_ACCEPT_TRUE_FOR_1:
        if (got, want) == ('True\n', '1\n'):
            return True
        if (got, want) == ('False\n', '0\n'):
            return True
    if not optionflags & DONT_ACCEPT_BLANKLINE:
        want = re.sub('(?m)^%s\\s*?$' % re.escape(BLANKLINE_MARKER), '', want)
        got = re.sub('(?m)^[^\\S\\n]+$', '', got)
        if got == want:
            return True
    if optionflags & NORMALIZE_WHITESPACE:
        got = ' '.join(got.split())
        want = ' '.join(want.split())
        if got == want:
            return True
    if optionflags & ELLIPSIS:
        if _ellipsis_match(want, got):
            return True
    return False

def _do_a_fancy_diff(self, want, got, optionflags):
    if not optionflags & (REPORT_UDIFF | REPORT_CDIFF | REPORT_NDIFF):
        return False
    if optionflags & REPORT_NDIFF:
        return True
    return want.count('\n') > 2 and got.count('\n') > 2

def output_difference(self, example, got, optionflags):
    """Return a string describing the differences between the
    expected output for a given example (`example`) and the actual
    output (`got`).  `optionflags` is the set of option flags used
    to compare `want` and `got`."""
    want = example.want
    if not optionflags & DONT_ACCEPT_BLANKLINE:
        got = re.sub('(?m)^[ ]*(?=\n)', BLANKLINE_MARKER, got)
    if self._do_a_fancy_diff(want, got, optionflags):
        want_lines = want.splitlines(keepends=True)
        got_lines = got.splitlines(keepends=True)
        if optionflags & REPORT_UDIFF:
            diff = difflib.unified_diff(want_lines, got_lines, n=2)
            diff = list(diff)[2:]
            kind = 'unified diff with -expected +actual'
        elif optionflags & REPORT_CDIFF:
            diff = difflib.context_diff(want_lines, got_lines, n=2)
            diff = list(diff)[2:]
            kind = 'context diff with expected followed by actual'
        elif optionflags & REPORT_NDIFF:
            engine = difflib.Differ(charjunk=difflib.IS_CHARACTER_JUNK)
            diff = list(engine.compare(want_lines, got_lines))
            kind = 'ndiff with -expected +actual'
        else:
            assert 0, 'Bad diff option'
        return 'Differences (%s):\n' % kind + _indent(''.join(diff))
    if want and got:
        return 'Expected:\n%sGot:\n%s' % (_indent(want), _indent(got))
    elif want:
        return 'Expected:\n%sGot nothing\n' % _indent(want)
    elif got:
        return 'Expected nothing\nGot:\n%s' % _indent(got)
    else:
        return 'Expected nothing\nGot nothing\n'

def run(self, test, compileflags=None, out=None, clear_globs=True):
    r = DocTestRunner.run(self, test, compileflags, out, False)
    if clear_globs:
        test.globs.clear()
    return r

def setUp(self):
    test = self._dt_test
    self._dt_globs = test.globs.copy()
    if self._dt_setUp is not None:
        self._dt_setUp(test)

def tearDown(self):
    test = self._dt_test
    if self._dt_tearDown is not None:
        self._dt_tearDown(test)
    test.globs.clear()
    test.globs.update(self._dt_globs)

def format_failure(self, err):
    test = self._dt_test
    if test.lineno is None:
        lineno = 'unknown line number'
    else:
        lineno = '%s' % test.lineno
    lname = '.'.join(test.name.split('.')[-1:])
    return 'Failed doctest test for %s\n  File "%s", line %s, in %s\n\n%s' % (test.name, test.filename, lineno, lname, err)

def __eq__(self, other):
    if type(self) is not type(other):
        return NotImplemented
    return self._dt_test == other._dt_test and self._dt_optionflags == other._dt_optionflags and (self._dt_setUp == other._dt_setUp) and (self._dt_tearDown == other._dt_tearDown) and (self._dt_checker == other._dt_checker)

def __repr__(self):
    name = self._dt_test.name.split('.')
    return '%s (%s)' % (name[-1], '.'.join(name[:-1]))

def __init__(self, module):
    self.module = module
    DocTestCase.__init__(self, None)

def out(s):
    s = str(s.encode(encoding, 'backslashreplace'), encoding)
    save_stdout.write(s)

def message_from_string(s, *args, **kws):
    """Parse a string into a Message object model.

    Optional _class and strict are passed to the Parser constructor."""
    from email.parser import Parser
    return Parser(*args, **kws).parsestr(s)

def message_from_bytes(s, *args, **kws):
    """Parse a bytes string into a Message object model.

    Optional _class and strict are passed to the Parser constructor."""
    from email.parser import BytesParser
    return BytesParser(*args, **kws).parsebytes(s)

def message_from_file(fp, *args, **kws):
    """Read a file and parse its contents into a Message object model.

    Optional _class and strict are passed to the Parser constructor."""
    from email.parser import Parser
    return Parser(*args, **kws).parse(fp)

def message_from_binary_file(fp, *args, **kws):
    """Read a binary file and parse its contents into a Message object model.

    Optional _class and strict are passed to the Parser constructor."""
    from email.parser import BytesParser
    return BytesParser(*args, **kws).parse(fp)

def decode_q(encoded):
    encoded = encoded.replace(b'_', b' ')
    return (_q_byte_subber(encoded), [])

def decode_b(encoded):
    pad_err = len(encoded) % 4
    missing_padding = b'==='[:4 - pad_err] if pad_err else b''
    try:
        return (base64.b64decode(encoded + missing_padding, validate=True), [errors.InvalidBase64PaddingDefect()] if pad_err else [])
    except binascii.Error:
        try:
            return (base64.b64decode(encoded, validate=False), [errors.InvalidBase64CharactersDefect()])
        except binascii.Error:
            try:
                return (base64.b64decode(encoded + b'==', validate=False), [errors.InvalidBase64CharactersDefect(), errors.InvalidBase64PaddingDefect()])
            except binascii.Error:
                return (encoded, [errors.InvalidBase64LengthDefect()])

def len_b(bstring):
    groups_of_3, leftover = divmod(len(bstring), 3)
    return groups_of_3 * 4 + (4 if leftover else 0)

def __missing__(self, key):
    if key in self.safe:
        self[key] = chr(key)
    else:
        self[key] = '={:02X}'.format(key)
    return self[key]

def make_quoted_pairs(value):
    """Escape dquote and backslash for use within a quoted-string."""
    return str(value).replace('\\', '\\\\').replace('"', '\\"')

def make_parenthesis_pairs(value):
    """Escape parenthesis and backslash for use within a comment."""
    return str(value).replace('\\', '\\\\').replace('(', '\\(').replace(')', '\\)')

def quote_string(value):
    escaped = make_quoted_pairs(value)
    return f'"{escaped}"'

def _validate_xtext(xtext):
    """If input token contains ASCII non-printables, register a defect."""
    non_printables = _non_printable_finder(xtext)
    if non_printables:
        xtext.defects.append(errors.NonPrintableDefect(non_printables))
    if utils._has_surrogates(xtext):
        xtext.defects.append(errors.UndecodableBytesDefect('Non-ASCII characters found in header token'))

def _get_ptext_to_endchars(value, endchars):
    """Scan printables/quoted-pairs until endchars and return unquoted ptext.

    This function turns a run of qcontent, ccontent-without-comments, or
    dtext-with-quoted-printables into a single string by unquoting any
    quoted printables.  It returns the string, the remaining value, and
    a flag that is True iff there were any quoted printables decoded."""
    fragment, *remainder = _wsp_splitter(value, 1)
    vchars = []
    escape = False
    had_qp = False
    for pos in range(len(fragment)):
        if fragment[pos] == '\\':
            if escape:
                escape = False
                had_qp = True
            else:
                escape = True
                continue
        if escape:
            escape = False
        elif fragment[pos] in endchars:
            break
        vchars.append(fragment[pos])
    else:
        pos = pos + 1
    return (''.join(vchars), ''.join([fragment[pos:]] + remainder), had_qp)

def get_bare_quoted_string(value):
    """bare-quoted-string = DQUOTE *([FWS] qcontent) [FWS] DQUOTE

    A quoted-string without the leading or trailing white space.  Its
    value is the text between the quote marks, with whitespace
    preserved and quoted pairs decoded."""
    if not value or value[0] != '"':
        raise errors.HeaderParseError('expected \'"\' but found \'{}\''.format(value))
    bare_quoted_string = BareQuotedString()
    value = value[1:]
    if value and value[0] == '"':
        token, value = get_qcontent(value)
        bare_quoted_string.append(token)
    while value and value[0] != '"':
        if value[0] in WSP:
            token, value = get_fws(value)
        elif value[:2] == '=?':
            valid_ew = False
            try:
                token, value = get_encoded_word(value)
                bare_quoted_string.defects.append(errors.InvalidHeaderDefect('encoded word inside quoted string'))
                valid_ew = True
            except errors.HeaderParseError:
                token, value = get_qcontent(value)
            if valid_ew and len(bare_quoted_string) > 1:
                if bare_quoted_string[-1].token_type == 'fws' and bare_quoted_string[-2].token_type == 'encoded-word':
                    bare_quoted_string[-1] = EWWhiteSpaceTerminal(bare_quoted_string[-1], 'fws')
        else:
            token, value = get_qcontent(value)
        bare_quoted_string.append(token)
    if not value:
        bare_quoted_string.defects.append(errors.InvalidHeaderDefect('end of header inside quoted string'))
        return (bare_quoted_string, value)
    return (bare_quoted_string, value[1:])

def get_comment(value):
    """comment = "(" *([FWS] ccontent) [FWS] ")"
       ccontent = ctext / quoted-pair / comment

    We handle nested comments here, and quoted-pair in our qp-ctext routine."""
    if value and value[0] != '(':
        raise errors.HeaderParseError("expected '(' but found '{}'".format(value))
    comment = Comment()
    value = value[1:]
    while value and value[0] != ')':
        if value[0] in WSP:
            token, value = get_fws(value)
        elif value[0] == '(':
            token, value = get_comment(value)
        else:
            token, value = get_qp_ctext(value)
        comment.append(token)
    if not value:
        comment.defects.append(errors.InvalidHeaderDefect('end of header inside comment'))
        return (comment, value)
    return (comment, value[1:])

def get_cfws(value):
    """CFWS = (1*([FWS] comment) [FWS]) / FWS

    """
    cfws = CFWSList()
    while value and value[0] in CFWS_LEADER:
        if value[0] in WSP:
            token, value = get_fws(value)
        else:
            token, value = get_comment(value)
        cfws.append(token)
    return (cfws, value)

def get_atom(value):
    """atom = [CFWS] 1*atext [CFWS]

    An atom could be an rfc2047 encoded word."""
    atom = Atom()
    if value and value[0] in CFWS_LEADER:
        token, value = get_cfws(value)
        atom.append(token)
    if value and value[0] in ATOM_ENDS:
        raise errors.HeaderParseError("expected atom but found '{}'".format(value))
    if value.startswith('=?'):
        try:
            token, value = get_encoded_word(value)
        except errors.HeaderParseError:
            token, value = get_atext(value)
    else:
        token, value = get_atext(value)
    atom.append(token)
    if value and value[0] in CFWS_LEADER:
        token, value = get_cfws(value)
        atom.append(token)
    return (atom, value)

def get_dot_atom_text(value):
    """dot-text = 1*atext *("." 1*atext)

    """
    dot_atom_text = DotAtomText()
    if not value or value[0] in ATOM_ENDS:
        raise errors.HeaderParseError("expected atom at a start of dot-atom-text but found '{}'".format(value))
    while value and value[0] not in ATOM_ENDS:
        token, value = get_atext(value)
        dot_atom_text.append(token)
        if value and value[0] == '.':
            dot_atom_text.append(DOT)
            value = value[1:]
    if dot_atom_text[-1] is DOT:
        raise errors.HeaderParseError("expected atom at end of dot-atom-text but found '{}'".format('.' + value))
    return (dot_atom_text, value)

def get_dot_atom(value):
    """dot-atom = [CFWS] dot-atom-text [CFWS]

    Any place we can have a dot atom, we could instead have an rfc2047 encoded
    word."""
    dot_atom = DotAtom()
    if value[0] in CFWS_LEADER:
        token, value = get_cfws(value)
        dot_atom.append(token)
    if value.startswith('=?'):
        try:
            token, value = get_encoded_word(value)
        except errors.HeaderParseError:
            token, value = get_dot_atom_text(value)
    else:
        token, value = get_dot_atom_text(value)
    dot_atom.append(token)
    if value and value[0] in CFWS_LEADER:
        token, value = get_cfws(value)
        dot_atom.append(token)
    return (dot_atom, value)

def get_word(value):
    """word = atom / quoted-string

    Either atom or quoted-string may start with CFWS.  We have to peel off this
    CFWS first to determine which type of word to parse.  Afterward we splice
    the leading CFWS, if any, into the parsed sub-token.

    If neither an atom or a quoted-string is found before the next special, a
    HeaderParseError is raised.

    The token returned is either an Atom or a QuotedString, as appropriate.
    This means the 'word' level of the formal grammar is not represented in the
    parse tree; this is because having that extra layer when manipulating the
    parse tree is more confusing than it is helpful."""
    if value[0] in CFWS_LEADER:
        leader, value = get_cfws(value)
    else:
        leader = None
    if not value:
        raise errors.HeaderParseError("Expected 'atom' or 'quoted-string' but found nothing.")
    if value[0] == '"':
        token, value = get_quoted_string(value)
    elif value[0] in SPECIALS:
        raise errors.HeaderParseError("Expected 'atom' or 'quoted-string' but found '{}'".format(value))
    else:
        token, value = get_atom(value)
    if leader is not None:
        token[:0] = [leader]
    return (token, value)

def get_phrase(value):
    """phrase = 1*word / obs-phrase
        obs-phrase = word *(word / "." / CFWS)

    This means a phrase can be a sequence of words, periods, and CFWS in any
    order as long as it starts with at least one word.  If anything other than
    words is detected, an ObsoleteHeaderDefect is added to the token's defect
    list.  We also accept a phrase that starts with CFWS followed by a dot;
    this is registered as an InvalidHeaderDefect, since it is not supported by
    even the obsolete grammar."""
    phrase = Phrase()
    try:
        token, value = get_word(value)
        phrase.append(token)
    except errors.HeaderParseError:
        phrase.defects.append(errors.InvalidHeaderDefect('phrase does not start with word'))
    while value and value[0] not in PHRASE_ENDS:
        if value[0] == '.':
            phrase.append(DOT)
            phrase.defects.append(errors.ObsoleteHeaderDefect("period in 'phrase'"))
            value = value[1:]
        else:
            try:
                token, value = get_word(value)
            except errors.HeaderParseError:
                if value[0] in CFWS_LEADER:
                    token, value = get_cfws(value)
                    phrase.defects.append(errors.ObsoleteHeaderDefect('comment found without atom'))
                else:
                    raise
            phrase.append(token)
    return (phrase, value)

def get_local_part(value):
    """local-part = dot-atom / quoted-string / obs-local-part

    """
    local_part = LocalPart()
    leader = None
    if value and value[0] in CFWS_LEADER:
        leader, value = get_cfws(value)
    if not value:
        raise errors.HeaderParseError("expected local-part but found '{}'".format(value))
    try:
        token, value = get_dot_atom(value)
    except errors.HeaderParseError:
        try:
            token, value = get_word(value)
        except errors.HeaderParseError:
            if value[0] != '\\' and value[0] in PHRASE_ENDS:
                raise
            token = TokenList()
    if leader is not None:
        token[:0] = [leader]
    local_part.append(token)
    if value and (value[0] == '\\' or value[0] not in PHRASE_ENDS):
        obs_local_part, value = get_obs_local_part(str(local_part) + value)
        if obs_local_part.token_type == 'invalid-obs-local-part':
            local_part.defects.append(errors.InvalidHeaderDefect('local-part is not dot-atom, quoted-string, or obs-local-part'))
        else:
            local_part.defects.append(errors.ObsoleteHeaderDefect('local-part is not a dot-atom (contains CFWS)'))
        local_part[0] = obs_local_part
    try:
        local_part.value.encode('ascii')
    except UnicodeEncodeError:
        local_part.defects.append(errors.NonASCIILocalPartDefect('local-part contains non-ASCII characters)'))
    return (local_part, value)

def get_obs_local_part(value):
    """obs-local-part = word *("." word)
    """
    obs_local_part = ObsLocalPart()
    last_non_ws_was_dot = False
    while value and (value[0] == '\\' or value[0] not in PHRASE_ENDS):
        if value[0] == '.':
            if last_non_ws_was_dot:
                obs_local_part.defects.append(errors.InvalidHeaderDefect("invalid repeated '.'"))
            obs_local_part.append(DOT)
            last_non_ws_was_dot = True
            value = value[1:]
            continue
        elif value[0] == '\\':
            obs_local_part.append(ValueTerminal(value[0], 'misplaced-special'))
            value = value[1:]
            obs_local_part.defects.append(errors.InvalidHeaderDefect("'\\' character outside of quoted-string/ccontent"))
            last_non_ws_was_dot = False
            continue
        if obs_local_part and obs_local_part[-1].token_type != 'dot':
            obs_local_part.defects.append(errors.InvalidHeaderDefect("missing '.' between words"))
        try:
            token, value = get_word(value)
            last_non_ws_was_dot = False
        except errors.HeaderParseError:
            if value[0] not in CFWS_LEADER:
                raise
            token, value = get_cfws(value)
        obs_local_part.append(token)
    if not obs_local_part:
        raise errors.HeaderParseError("expected obs-local-part but found '{}'".format(value))
    if obs_local_part[0].token_type == 'dot' or (obs_local_part[0].token_type == 'cfws' and len(obs_local_part) > 1 and (obs_local_part[1].token_type == 'dot')):
        obs_local_part.defects.append(errors.InvalidHeaderDefect("Invalid leading '.' in local part"))
    if obs_local_part[-1].token_type == 'dot' or (obs_local_part[-1].token_type == 'cfws' and len(obs_local_part) > 1 and (obs_local_part[-2].token_type == 'dot')):
        obs_local_part.defects.append(errors.InvalidHeaderDefect("Invalid trailing '.' in local part"))
    if obs_local_part.defects:
        obs_local_part.token_type = 'invalid-obs-local-part'
    return (obs_local_part, value)

def _check_for_early_dl_end(value, domain_literal):
    if value:
        return False
    domain_literal.append(errors.InvalidHeaderDefect('end of input inside domain-literal'))
    domain_literal.append(ValueTerminal(']', 'domain-literal-end'))
    return True

def get_domain_literal(value):
    """domain-literal = [CFWS] "[" *([FWS] dtext) [FWS] "]" [CFWS]

    """
    domain_literal = DomainLiteral()
    if value[0] in CFWS_LEADER:
        token, value = get_cfws(value)
        domain_literal.append(token)
    if not value:
        raise errors.HeaderParseError('expected domain-literal')
    if value[0] != '[':
        raise errors.HeaderParseError("expected '[' at start of domain-literal but found '{}'".format(value))
    value = value[1:]
    if _check_for_early_dl_end(value, domain_literal):
        return (domain_literal, value)
    domain_literal.append(ValueTerminal('[', 'domain-literal-start'))
    if value[0] in WSP:
        token, value = get_fws(value)
        domain_literal.append(token)
    token, value = get_dtext(value)
    domain_literal.append(token)
    if _check_for_early_dl_end(value, domain_literal):
        return (domain_literal, value)
    if value[0] in WSP:
        token, value = get_fws(value)
        domain_literal.append(token)
    if _check_for_early_dl_end(value, domain_literal):
        return (domain_literal, value)
    if value[0] != ']':
        raise errors.HeaderParseError("expected ']' at end of domain-literal but found '{}'".format(value))
    domain_literal.append(ValueTerminal(']', 'domain-literal-end'))
    value = value[1:]
    if value and value[0] in CFWS_LEADER:
        token, value = get_cfws(value)
        domain_literal.append(token)
    return (domain_literal, value)

def get_domain(value):
    """domain = dot-atom / domain-literal / obs-domain
    obs-domain = atom *("." atom))"""
    domain = Domain()
    leader = None
    if value and value[0] in CFWS_LEADER:
        leader, value = get_cfws(value)
    if not value:
        raise errors.HeaderParseError("expected domain but found '{}'".format(value))
    if value[0] == '[':
        token, value = get_domain_literal(value)
        if leader is not None:
            token[:0] = [leader]
        domain.append(token)
        return (domain, value)
    try:
        token, value = get_dot_atom(value)
    except errors.HeaderParseError:
        token, value = get_atom(value)
    if value and value[0] == '@':
        raise errors.HeaderParseError('Invalid Domain')
    if leader is not None:
        token[:0] = [leader]
    domain.append(token)
    if value and value[0] == '.':
        domain.defects.append(errors.ObsoleteHeaderDefect('domain is not a dot-atom (contains CFWS)'))
        if domain[0].token_type == 'dot-atom':
            domain[:] = domain[0]
        while value and value[0] == '.':
            domain.append(DOT)
            token, value = get_atom(value[1:])
            domain.append(token)
    return (domain, value)

def get_addr_spec(value):
    """addr-spec = local-part "@" domain

    """
    addr_spec = AddrSpec()
    token, value = get_local_part(value)
    addr_spec.append(token)
    if not value or value[0] != '@':
        addr_spec.defects.append(errors.InvalidHeaderDefect('addr-spec local part with no domain'))
        return (addr_spec, value)
    addr_spec.append(ValueTerminal('@', 'address-at-symbol'))
    token, value = get_domain(value[1:])
    addr_spec.append(token)
    return (addr_spec, value)

def get_obs_route(value):
    """obs-route = obs-domain-list ":"
    obs-domain-list = *(CFWS / ",") "@" domain *("," [CFWS] ["@" domain])

    Returns an obs-route token with the appropriate sub-tokens (that is,
    there is no obs-domain-list in the parse tree)."""
    obs_route = ObsRoute()
    while value and (value[0] == ',' or value[0] in CFWS_LEADER):
        if value[0] in CFWS_LEADER:
            token, value = get_cfws(value)
            obs_route.append(token)
        elif value[0] == ',':
            obs_route.append(ListSeparator)
            value = value[1:]
    if not value or value[0] != '@':
        raise errors.HeaderParseError("expected obs-route domain but found '{}'".format(value))
    obs_route.append(RouteComponentMarker)
    token, value = get_domain(value[1:])
    obs_route.append(token)
    while value and value[0] == ',':
        obs_route.append(ListSeparator)
        value = value[1:]
        if not value:
            break
        if value[0] in CFWS_LEADER:
            token, value = get_cfws(value)
            obs_route.append(token)
        if not value:
            break
        if value[0] == '@':
            obs_route.append(RouteComponentMarker)
            token, value = get_domain(value[1:])
            obs_route.append(token)
    if not value:
        raise errors.HeaderParseError('end of header while parsing obs-route')
    if value[0] != ':':
        raise errors.HeaderParseError("expected ':' marking end of obs-route but found '{}'".format(value))
    obs_route.append(ValueTerminal(':', 'end-of-obs-route-marker'))
    return (obs_route, value[1:])

def get_angle_addr(value):
    """angle-addr = [CFWS] "<" addr-spec ">" [CFWS] / obs-angle-addr
    obs-angle-addr = [CFWS] "<" obs-route addr-spec ">" [CFWS]"""
    angle_addr = AngleAddr()
    if value and value[0] in CFWS_LEADER:
        token, value = get_cfws(value)
        angle_addr.append(token)
    if not value or value[0] != '<':
        raise errors.HeaderParseError("expected angle-addr but found '{}'".format(value))
    angle_addr.append(ValueTerminal('<', 'angle-addr-start'))
    value = value[1:]
    if value and value[0] == '>':
        angle_addr.append(ValueTerminal('>', 'angle-addr-end'))
        angle_addr.defects.append(errors.InvalidHeaderDefect('null addr-spec in angle-addr'))
        value = value[1:]
        return (angle_addr, value)
    try:
        token, value = get_addr_spec(value)
    except errors.HeaderParseError:
        try:
            token, value = get_obs_route(value)
            angle_addr.defects.append(errors.ObsoleteHeaderDefect('obsolete route specification in angle-addr'))
        except errors.HeaderParseError:
            raise errors.HeaderParseError("expected addr-spec or obs-route but found '{}'".format(value))
        angle_addr.append(token)
        token, value = get_addr_spec(value)
    angle_addr.append(token)
    if value and value[0] == '>':
        value = value[1:]
    else:
        angle_addr.defects.append(errors.InvalidHeaderDefect("missing trailing '>' on angle-addr"))
    angle_addr.append(ValueTerminal('>', 'angle-addr-end'))
    if value and value[0] in CFWS_LEADER:
        token, value = get_cfws(value)
        angle_addr.append(token)
    return (angle_addr, value)

def get_name_addr(value):
    """name-addr = [display-name] angle-addr

    """
    name_addr = NameAddr()
    leader = None
    if not value:
        raise errors.HeaderParseError("expected name-addr but found '{}'".format(value))
    if value[0] in CFWS_LEADER:
        leader, value = get_cfws(value)
        if not value:
            raise errors.HeaderParseError("expected name-addr but found '{}'".format(leader))
    if value[0] != '<':
        if value[0] in PHRASE_ENDS:
            raise errors.HeaderParseError("expected name-addr but found '{}'".format(value))
        token, value = get_display_name(value)
        if not value:
            raise errors.HeaderParseError("expected name-addr but found '{}'".format(token))
        if leader is not None:
            if isinstance(token[0], TokenList):
                token[0][:0] = [leader]
            else:
                token[:0] = [leader]
            leader = None
        name_addr.append(token)
    token, value = get_angle_addr(value)
    if leader is not None:
        token[:0] = [leader]
    name_addr.append(token)
    return (name_addr, value)

def get_mailbox(value):
    """mailbox = name-addr / addr-spec

    """
    mailbox = Mailbox()
    try:
        token, value = get_name_addr(value)
    except errors.HeaderParseError:
        try:
            token, value = get_addr_spec(value)
        except errors.HeaderParseError:
            raise errors.HeaderParseError("expected mailbox but found '{}'".format(value))
    if any((isinstance(x, errors.InvalidHeaderDefect) for x in token.all_defects)):
        mailbox.token_type = 'invalid-mailbox'
    mailbox.append(token)
    return (mailbox, value)

def get_invalid_mailbox(value, endchars):
    """Read everything up to one of the chars in endchars.

    This is outside the formal grammar.  The InvalidMailbox TokenList that is
    returned acts like a Mailbox, but the data attributes are None."""
    invalid_mailbox = InvalidMailbox()
    while value and value[0] not in endchars:
        if value[0] in PHRASE_ENDS:
            invalid_mailbox.append(ValueTerminal(value[0], 'misplaced-special'))
            value = value[1:]
        else:
            token, value = get_phrase(value)
            invalid_mailbox.append(token)
    return (invalid_mailbox, value)

def get_group_list(value):
    """group-list = mailbox-list / CFWS / obs-group-list
    obs-group-list = 1*([CFWS] ",") [CFWS]"""
    group_list = GroupList()
    if not value:
        group_list.defects.append(errors.InvalidHeaderDefect('end of header before group-list'))
        return (group_list, value)
    leader = None
    if value and value[0] in CFWS_LEADER:
        leader, value = get_cfws(value)
        if not value:
            group_list.defects.append(errors.InvalidHeaderDefect('end of header in group-list'))
            group_list.append(leader)
            return (group_list, value)
        if value[0] == ';':
            group_list.append(leader)
            return (group_list, value)
    token, value = get_mailbox_list(value)
    if len(token.all_mailboxes) == 0:
        if leader is not None:
            group_list.append(leader)
        group_list.extend(token)
        group_list.defects.append(errors.ObsoleteHeaderDefect('group-list with empty entries'))
        return (group_list, value)
    if leader is not None:
        token[:0] = [leader]
    group_list.append(token)
    return (group_list, value)

def get_group(value):
    """group = display-name ":" [group-list] ";" [CFWS]

    """
    group = Group()
    token, value = get_display_name(value)
    if not value or value[0] != ':':
        raise errors.HeaderParseError("expected ':' at end of group display name but found '{}'".format(value))
    group.append(token)
    group.append(ValueTerminal(':', 'group-display-name-terminator'))
    value = value[1:]
    if value and value[0] == ';':
        group.append(ValueTerminal(';', 'group-terminator'))
        return (group, value[1:])
    token, value = get_group_list(value)
    group.append(token)
    if not value:
        group.defects.append(errors.InvalidHeaderDefect('end of header in group'))
    elif value[0] != ';':
        raise errors.HeaderParseError("expected ';' at end of group but found {}".format(value))
    group.append(ValueTerminal(';', 'group-terminator'))
    value = value[1:]
    if value and value[0] in CFWS_LEADER:
        token, value = get_cfws(value)
        group.append(token)
    return (group, value)

def get_address(value):
    """address = mailbox / group

    Note that counter-intuitively, an address can be either a single address or
    a list of addresses (a group).  This is why the returned Address object has
    a 'mailboxes' attribute which treats a single address as a list of length
    one.  When you need to differentiate between to two cases, extract the single
    element, which is either a mailbox or a group token."""
    address = Address()
    try:
        token, value = get_group(value)
    except errors.HeaderParseError:
        try:
            token, value = get_mailbox(value)
        except errors.HeaderParseError:
            raise errors.HeaderParseError("expected address but found '{}'".format(value))
    address.append(token)
    return (address, value)

def get_no_fold_literal(value):
    """no-fold-literal = "[" *dtext "]"
    """
    no_fold_literal = NoFoldLiteral()
    if not value:
        raise errors.HeaderParseError("expected no-fold-literal but found '{}'".format(value))
    if value[0] != '[':
        raise errors.HeaderParseError("expected '[' at the start of no-fold-literal but found '{}'".format(value))
    no_fold_literal.append(ValueTerminal('[', 'no-fold-literal-start'))
    value = value[1:]
    token, value = get_dtext(value)
    no_fold_literal.append(token)
    if not value or value[0] != ']':
        raise errors.HeaderParseError("expected ']' at the end of no-fold-literal but found '{}'".format(value))
    no_fold_literal.append(ValueTerminal(']', 'no-fold-literal-end'))
    return (no_fold_literal, value[1:])

def parse_message_id(value):
    """message-id      =   "Message-ID:" msg-id CRLF
    """
    message_id = MessageID()
    try:
        token, value = get_msg_id(value)
        message_id.append(token)
    except errors.HeaderParseError as ex:
        token = get_unstructured(value)
        message_id = InvalidMessageID(token)
        message_id.defects.append(errors.InvalidHeaderDefect('Invalid msg-id: {!r}'.format(ex)))
    else:
        if value:
            message_id.defects.append(errors.InvalidHeaderDefect('Unexpected {!r}'.format(value)))
    return message_id

def get_invalid_parameter(value):
    """Read everything up to the next ';'.

    This is outside the formal grammar.  The InvalidParameter TokenList that is
    returned acts like a Parameter, but the data attributes are None."""
    invalid_parameter = InvalidParameter()
    while value and value[0] != ';':
        if value[0] in PHRASE_ENDS:
            invalid_parameter.append(ValueTerminal(value[0], 'misplaced-special'))
            value = value[1:]
        else:
            token, value = get_phrase(value)
            invalid_parameter.append(token)
    return (invalid_parameter, value)

def get_extended_attribute(value):
    """[CFWS] 1*extended_attrtext [CFWS]

    This is like the non-extended version except we allow % characters, so that
    we can pick up an encoded value as a single string."""
    attribute = Attribute()
    if value and value[0] in CFWS_LEADER:
        token, value = get_cfws(value)
        attribute.append(token)
    if value and value[0] in EXTENDED_ATTRIBUTE_ENDS:
        raise errors.HeaderParseError("expected token but found '{}'".format(value))
    token, value = get_extended_attrtext(value)
    attribute.append(token)
    if value and value[0] in CFWS_LEADER:
        token, value = get_cfws(value)
        attribute.append(token)
    return (attribute, value)

def get_value(value):
    """quoted-string / attribute

    """
    v = Value()
    if not value:
        raise errors.HeaderParseError('Expected value but found end of string')
    leader = None
    if value[0] in CFWS_LEADER:
        leader, value = get_cfws(value)
    if not value:
        raise errors.HeaderParseError('Expected value but found only {}'.format(leader))
    if value[0] == '"':
        token, value = get_quoted_string(value)
    else:
        token, value = get_extended_attribute(value)
    if leader is not None:
        token[:0] = [leader]
    v.append(token)
    return (v, value)

def _find_mime_parameters(tokenlist, value):
    """Do our best to find the parameters in an invalid MIME header

    """
    while value and value[0] != ';':
        if value[0] in PHRASE_ENDS:
            tokenlist.append(ValueTerminal(value[0], 'misplaced-special'))
            value = value[1:]
        else:
            token, value = get_phrase(value)
            tokenlist.append(token)
    if not value:
        return
    tokenlist.append(ValueTerminal(';', 'parameter-separator'))
    tokenlist.append(parse_mime_parameters(value[1:]))

def parse_content_transfer_encoding_header(value):
    """mechanism

    """
    cte_header = ContentTransferEncoding()
    if not value:
        cte_header.defects.append(errors.HeaderMissingRequiredValue('Missing content transfer encoding'))
        return cte_header
    try:
        token, value = get_token(value)
    except errors.HeaderParseError:
        cte_header.defects.append(errors.InvalidHeaderDefect('Expected content transfer encoding but found {!r}'.format(value)))
    else:
        cte_header.append(token)
        cte_header.cte = token.value.strip().lower()
    if not value:
        return cte_header
    while value:
        cte_header.defects.append(errors.InvalidHeaderDefect('Extra text after content transfer encoding'))
        if value[0] in PHRASE_ENDS:
            cte_header.append(ValueTerminal(value[0], 'misplaced-special'))
            value = value[1:]
        else:
            token, value = get_phrase(value)
            cte_header.append(token)
    return cte_header

def _steal_trailing_WSP_if_exists(lines):
    wsp = ''
    if lines and lines[-1] and (lines[-1][-1] in WSP):
        wsp = lines[-1][-1]
        lines[-1] = lines[-1][:-1]
    return wsp

def __init__(self, *args, **kw):
    super().__init__(*args, **kw)
    self.defects = []

@property
def value(self):
    return ''.join((x.value for x in self if x.value))

@property
def all_defects(self):
    return sum((x.all_defects for x in self), self.defects)

@property
def as_ew_allowed(self):
    """True if all top level tokens of this part may be RFC2047 encoded."""
    return all((part.as_ew_allowed for part in self))

@property
def comments(self):
    comments = []
    for token in self:
        comments.extend(token.comments)
    return comments

def _pp(self, indent=''):
    yield '{}{}/{}('.format(indent, self.__class__.__name__, self.token_type)
    for token in self:
        if not hasattr(token, '_pp'):
            yield (indent + '    !! invalid element in token list: {!r}'.format(token))
        else:
            yield from token._pp(indent + '    ')
    if self.defects:
        extra = ' Defects: {}'.format(self.defects)
    else:
        extra = ''
    yield '{}){}'.format(indent, extra)

@property
def value(self):
    return ' '

@property
def comments(self):
    return [x.content for x in self if x.token_type == 'comment']

@property
def content(self):
    for x in self:
        if x.token_type == 'bare-quoted-string':
            return x.value

@property
def quoted_value(self):
    res = []
    for x in self:
        if x.token_type == 'bare-quoted-string':
            res.append(str(x))
        else:
            res.append(x.value)
    return ''.join(res)

@property
def stripped_value(self):
    for token in self:
        if token.token_type == 'bare-quoted-string':
            return token.value

@property
def value(self):
    return ''.join((str(x) for x in self))

def quote(self, value):
    if value.token_type == 'comment':
        return str(value)
    return str(value).replace('\\', '\\\\').replace('(', '\\(').replace(')', '\\)')

@property
def content(self):
    return ''.join((str(x) for x in self))

@property
def comments(self):
    return [self.content]

@property
def addresses(self):
    return [x for x in self if x.token_type == 'address']

@property
def mailboxes(self):
    return sum((x.mailboxes for x in self if x.token_type == 'address'), [])

@property
def all_mailboxes(self):
    return sum((x.all_mailboxes for x in self if x.token_type == 'address'), [])

@property
def display_name(self):
    if self[0].token_type == 'group':
        return self[0].display_name

@property
def mailboxes(self):
    if self[0].token_type == 'mailbox':
        return [self[0]]
    elif self[0].token_type == 'invalid-mailbox':
        return []
    return self[0].mailboxes

@property
def all_mailboxes(self):
    return [x for x in self if x.token_type in ('mailbox', 'invalid-mailbox')]

@property
def mailboxes(self):
    if not self or self[0].token_type != 'mailbox-list':
        return []
    return self[0].mailboxes

@property
def all_mailboxes(self):
    if not self or self[0].token_type != 'mailbox-list':
        return []
    return self[0].all_mailboxes

@property
def mailboxes(self):
    if self[2].token_type != 'group-list':
        return []
    return self[2].mailboxes

@property
def all_mailboxes(self):
    if self[2].token_type != 'group-list':
        return []
    return self[2].all_mailboxes

@property
def display_name(self):
    return self[0].display_name

@property
def display_name(self):
    if len(self) == 1:
        return None
    return self[0].display_name

@property
def local_part(self):
    return self[-1].local_part

@property
def domain(self):
    return self[-1].domain

@property
def route(self):
    return self[-1].route

@property
def addr_spec(self):
    return self[-1].addr_spec

@property
def local_part(self):
    for x in self:
        if x.token_type == 'addr-spec':
            return x.local_part

@property
def domain(self):
    for x in self:
        if x.token_type == 'addr-spec':
            return x.domain

@property
def route(self):
    for x in self:
        if x.token_type == 'obs-route':
            return x.domains

@property
def addr_spec(self):
    for x in self:
        if x.token_type == 'addr-spec':
            if x.local_part:
                return x.addr_spec
            else:
                return quote_string(x.local_part) + x.addr_spec
    else:
        return '<>'

@property
