    return None

@property
def domain(self):
    return ''.join(super().value.split())

@property
def domain(self):
    if len(self) < 3:
        return None
    return self[-1].domain

@property
def value(self):
    if len(self) < 3:
        return self[0].value
    return self[0].value.rstrip() + self[1].value + self[2].value.lstrip()

@property
def addr_spec(self):
    nameset = set(self.local_part)
    if len(nameset) > len(nameset - DOT_ATOM_ENDS):
        lp = quote_string(self.local_part)
    else:
        lp = self.local_part
    if self.domain is not None:
        return lp + '@' + self.domain
    return lp

@property
def display_name(self):
    res = TokenList(self)
    if len(res) == 0:
        return res.value
    if res[0].token_type == 'cfws':
        res.pop(0)
    elif isinstance(res[0], TokenList) and res[0][0].token_type == 'cfws':
        res[0] = TokenList(res[0][1:])
    if res[-1].token_type == 'cfws':
        res.pop()
    elif isinstance(res[-1], TokenList) and res[-1][-1].token_type == 'cfws':
        res[-1] = TokenList(res[-1][:-1])
    return res.value

@property
def value(self):
    quote = False
    if self.defects:
        quote = True
    else:
        for x in self:
            if x.token_type == 'quoted-string':
                quote = True
    if len(self) != 0 and quote:
        pre = post = ''
        if self[0].token_type == 'cfws' or (isinstance(self[0], TokenList) and self[0][0].token_type == 'cfws'):
            pre = ' '
        if self[-1].token_type == 'cfws' or (isinstance(self[-1], TokenList) and self[-1][-1].token_type == 'cfws'):
            post = ' '
        return pre + quote_string(self.display_name) + post
    else:
        return super().value

@property
def value(self):
    if self[0].token_type == 'quoted-string':
        return self[0].quoted_value
    else:
        return self[0].value

@property
def local_part(self):
    res = [DOT]
    last = DOT
    last_is_tl = False
    for tok in self[0] + [DOT]:
        if tok.token_type == 'cfws':
            continue
        if last_is_tl and tok.token_type == 'dot' and (last[-1].token_type == 'cfws'):
            res[-1] = TokenList(last[:-1])
        is_tl = isinstance(tok, TokenList)
        if is_tl and last.token_type == 'dot' and (tok[0].token_type == 'cfws'):
            res.append(TokenList(tok[1:]))
        else:
            res.append(tok)
        last = res[-1]
        last_is_tl = is_tl
    res = TokenList(res[1:-1])
    return res.value

@property
def ip(self):
    for x in self:
        if x.token_type == 'ptext':
            return x.value

@property
def section_number(self):
    return self[1].number if self.sectioned else 0

@property
def param_value(self):
    for token in self:
        if token.token_type == 'value':
            return token.stripped_value
        if token.token_type == 'quoted-string':
            for token in token:
                if token.token_type == 'bare-quoted-string':
                    for token in token:
                        if token.token_type == 'value':
                            return token.stripped_value
    return ''

@property
def stripped_value(self):
    for token in self:
        if token.token_type.endswith('attrtext'):
            return token.value

@property
def stripped_value(self):
    token = self[0]
    if token.token_type == 'cfws':
        token = self[1]
    if token.token_type.endswith(('quoted-string', 'attribute', 'extended-attribute')):
        return token.stripped_value
    return self.value

@property
def params(self):
    for token in reversed(self):
        if token.token_type == 'mime-parameters':
            return token.params
    return {}

@property
def all_defects(self):
    return list(self.defects)

@property
def comments(self):
    return []

@property
def value(self):
    return self

@property
def value(self):
    return ''

def parsedate_tz(data):
    """Convert a date string to a time tuple.

    Accounts for military timezones."""
    res = _parsedate_tz(data)
    if not res:
        return
    if res[9] is None:
        res[9] = 0
    return tuple(res)

def parsedate(data):
    """Convert a time string to a time tuple."""
    t = parsedate_tz(data)
    if isinstance(t, tuple):
        return t[:9]
    else:
        return t

def mktime_tz(data):
    """Turn a 10-tuple as returned by parsedate_tz() into a POSIX timestamp."""
    if data[9] is None:
        return time.mktime(data[:8] + (-1,))
    else:
        t = calendar.timegm(data)
        return t - data[9]

def quote(str):
    """Prepare string to be used in a quoted string.

    Turns backslash and double quote characters into quoted pairs.  These
    are the only characters that need to be quoted inside a quoted string.
    Does not add the surrounding double quotes."""
    return str.replace('\\', '\\\\').replace('"', '\\"')

def getaddrlist(self):
    """Parse all addresses.

    Returns a list containing all of the addresses."""
    result = []
    while self.pos < len(self.field):
        ad = self.getaddress()
        if ad:
            result += ad
        else:
            result.append(('', ''))
    return result

def getaddrspec(self):
    """Parse an RFC 2822 addr-spec."""
    aslist = []
    self.gotonext()
    while self.pos < len(self.field):
        preserve_ws = True
        if self.field[self.pos] == '.':
            if aslist and (not aslist[-1].strip()):
                aslist.pop()
            aslist.append('.')
            self.pos += 1
            preserve_ws = False
        elif self.field[self.pos] == '"':
            aslist.append('"%s"' % quote(self.getquote()))
        elif self.field[self.pos] in self.atomends:
            if aslist and (not aslist[-1].strip()):
                aslist.pop()
            break
        else:
            aslist.append(self.getatom())
        ws = self.gotonext()
        if preserve_ws and ws:
            aslist.append(ws)
    if self.pos >= len(self.field) or self.field[self.pos] != '@':
        return EMPTYSTRING.join(aslist)
    aslist.append('@')
    self.pos += 1
    self.gotonext()
    domain = self.getdomain()
    if not domain:
        return EMPTYSTRING
    return EMPTYSTRING.join(aslist) + domain

def getdomain(self):
    """Get the complete domain name from an address."""
    sdlist = []
    while self.pos < len(self.field):
        if self.field[self.pos] in self.LWS:
            self.pos += 1
        elif self.field[self.pos] == '(':
            self.commentlist.append(self.getcomment())
        elif self.field[self.pos] == '[':
            sdlist.append(self.getdomainliteral())
        elif self.field[self.pos] == '.':
            self.pos += 1
            sdlist.append('.')
        elif self.field[self.pos] == '@':
            return EMPTYSTRING
        elif self.field[self.pos] in self.atomends:
            break
        else:
            sdlist.append(self.getatom())
    return EMPTYSTRING.join(sdlist)

def getdelimited(self, beginchar, endchars, allowcomments=True):
    """Parse a header fragment delimited by special characters.

    `beginchar' is the start character for the fragment.
    If self is not looking at an instance of `beginchar' then
    getdelimited returns the empty string.

    `endchars' is a sequence of allowable end-delimiting characters.
    Parsing stops when one of these is encountered.

    If `allowcomments' is non-zero, embedded RFC 2822 comments are allowed
    within the parsed fragment."""
    if self.field[self.pos] != beginchar:
        return ''
    slist = ['']
    quote = False
    self.pos += 1
    while self.pos < len(self.field):
        if quote:
            slist.append(self.field[self.pos])
            quote = False
        elif self.field[self.pos] in endchars:
            self.pos += 1
            break
        elif allowcomments and self.field[self.pos] == '(':
            slist.append(self.getcomment())
            continue
        elif self.field[self.pos] == '\\':
            quote = True
        else:
            slist.append(self.field[self.pos])
        self.pos += 1
    return EMPTYSTRING.join(slist)

def getquote(self):
    """Get a quote-delimited fragment from self's field."""
    return self.getdelimited('"', '"\r', False)

def getcomment(self):
    """Get a parenthesis-delimited fragment from self's field."""
    return self.getdelimited('(', ')\r', True)

def getdomainliteral(self):
    """Parse an RFC 2822 domain-literal."""
    return '[%s]' % self.getdelimited('[', ']\r', False)

def getatom(self, atomends=None):
    """Parse an RFC 2822 atom.

    Optional atomends specifies a different set of end token delimiters
    (the default is to use self.atomends).  This is used e.g. in
    getphraselist() since phrase endings must not include the `.' (which
    is legal in phrases)."""
    atomlist = ['']
    if atomends is None:
        atomends = self.atomends
    while self.pos < len(self.field):
        if self.field[self.pos] in atomends:
            break
        else:
            atomlist.append(self.field[self.pos])
        self.pos += 1
    return EMPTYSTRING.join(atomlist)

def getphraselist(self):
    """Parse a sequence of RFC 2822 phrases.

    A phrase is a sequence of words, which are in turn either RFC 2822
    atoms or quoted-strings.  Phrases are canonicalized by squeezing all
    runs of continuous whitespace into one space."""
    plist = []
    while self.pos < len(self.field):
        if self.field[self.pos] in self.FWS:
            self.pos += 1
        elif self.field[self.pos] == '"':
            plist.append(self.getquote())
        elif self.field[self.pos] == '(':
            self.commentlist.append(self.getcomment())
        elif self.field[self.pos] in self.phraseends:
            break
        else:
            plist.append(self.getatom(self.phraseends))
    return plist

def __init__(self, field):
    AddrlistClass.__init__(self, field)
    if field:
        self.addresslist = self.getaddrlist()
    else:
        self.addresslist = []

def __add__(self, other):
    newaddr = AddressList(None)
    newaddr.addresslist = self.addresslist[:]
    for x in other.addresslist:
        if not x in self.addresslist:
            newaddr.addresslist.append(x)
    return newaddr

def __iadd__(self, other):
    for x in other.addresslist:
        if not x in self.addresslist:
            self.addresslist.append(x)
    return self

def __sub__(self, other):
    newaddr = AddressList(None)
    for x in self.addresslist:
        if not x in other.addresslist:
            newaddr.addresslist.append(x)
    return newaddr

def __isub__(self, other):
    for x in other.addresslist:
        if x in self.addresslist:
            self.addresslist.remove(x)
    return self

def _extend_docstrings(cls):
    if cls.__doc__ and cls.__doc__.startswith('+'):
        cls.__doc__ = _append_doc(cls.__bases__[0].__doc__, cls.__doc__)
    for name, attr in cls.__dict__.items():
        if attr.__doc__ and attr.__doc__.startswith('+'):
            for c in (c for base in cls.__bases__ for c in base.mro()):
                doc = getattr(getattr(c, name), '__doc__')
                if doc:
                    attr.__doc__ = _append_doc(doc, attr.__doc__)
                    break
    return cls

def clone(self, **kw):
    """Return a new instance with specified attributes changed.

    The new instance has the same attribute values as the current object,
    except for the changes passed in as keyword arguments."""
    newpolicy = self.__class__.__new__(self.__class__)
    for attr, value in self.__dict__.items():
        object.__setattr__(newpolicy, attr, value)
    for attr, value in kw.items():
        if not hasattr(self, attr):
            raise TypeError('{!r} is an invalid keyword argument for {}'.format(attr, self.__class__.__name__))
        object.__setattr__(newpolicy, attr, value)
    return newpolicy

def __setattr__(self, name, value):
    if hasattr(self, name):
        msg = '{!r} object attribute {!r} is read-only'
    else:
        msg = '{!r} object has no attribute {!r}'
    raise AttributeError(msg.format(self.__class__.__name__, name))

def __add__(self, other):
    """Non-default values from right operand override those from left.

    The object returned is a new instance of the subclass."""
    return self.clone(**other.__dict__)

def _sanitize_header(self, name, value):
    if not isinstance(value, str):
        return value
    if _has_surrogates(value):
        return header.Header(value, charset=_charset.UNKNOWN8BIT, header_name=name)
    else:
        return value

def header_store_parse(self, name, value):
    """+
    The name and value are returned unmodified."""
    return (name, value)

def header_fetch_parse(self, name, value):
    """+
    If the value contains binary data, it is converted into a Header object
    using the unknown-8bit charset.  Otherwise it is returned unmodified."""
    return self._sanitize_header(name, value)

def _fold(self, name, value, sanitize):
    parts = []
    parts.append('%s: ' % name)
    if isinstance(value, str):
        if _has_surrogates(value):
            if sanitize:
                h = header.Header(value, charset=_charset.UNKNOWN8BIT, header_name=name)
            else:
                parts.append(value)
                h = None
        else:
            h = header.Header(value, header_name=name)
    else:
        h = value
    if h is not None:
        maxlinelen = 0
        if self.max_line_length is not None:
            maxlinelen = self.max_line_length
        parts.append(h.encode(linesep=self.linesep, maxlinelen=maxlinelen))
    parts.append(self.linesep)
    return ''.join(parts)

def header_encode(header_bytes, charset='iso-8859-1'):
    """Encode a single header line with Base64 encoding in a given charset.

    charset names the character set to use to encode the header.  It defaults
    to iso-8859-1.  Base64 encoding is defined in RFC 2045."""
    if not header_bytes:
        return ''
    if isinstance(header_bytes, str):
        header_bytes = header_bytes.encode(charset)
    encoded = b64encode(header_bytes).decode('ascii')
    return '=?%s?b?%s?=' % (charset, encoded)

def decode(string):
    """Decode a raw base64 string, returning a bytes object.

    This function does not parse a full MIME header value encoded with
    base64 (like =?iso-8859-1?b?bmloISBuaWgh?=) -- please use the high
    level email.header class for that functionality."""
    if not string:
        return bytes()
    elif isinstance(string, str):
        return a2b_base64(string.encode('raw-unicode-escape'))
    else:
        return a2b_base64(string)

def _encode(string, codec):
    if codec == UNKNOWN8BIT:
        return string.encode('ascii', 'surrogateescape')
    else:
        return string.encode(codec)

def __init__(self, input_charset=DEFAULT_CHARSET):
    try:
        if isinstance(input_charset, str):
            input_charset.encode('ascii')
        else:
            input_charset = str(input_charset, 'ascii')
    except UnicodeError:
        raise errors.CharsetError(input_charset)
    input_charset = input_charset.lower()
    self.input_charset = ALIASES.get(input_charset, input_charset)
    henc, benc, conv = CHARSETS.get(self.input_charset, (SHORTEST, BASE64, None))
    if not conv:
        conv = self.input_charset
    self.header_encoding = henc
    self.body_encoding = benc
    self.output_charset = ALIASES.get(conv, conv)
    self.input_codec = CODEC_MAP.get(self.input_charset, self.input_charset)
    self.output_codec = CODEC_MAP.get(self.output_charset, self.output_charset)

def _get_encoder(self, header_bytes):
    if self.header_encoding == BASE64:
        return email.base64mime
    elif self.header_encoding == QP:
        return email.quoprimime
    elif self.header_encoding == SHORTEST:
        len64 = email.base64mime.header_length(header_bytes)
        lenqp = email.quoprimime.header_length(header_bytes)
        if len64 < lenqp:
            return email.base64mime
        else:
            return email.quoprimime
    else:
        return None

def body_encode(self, string):
    """Body-encode a string by converting it first to bytes.

    The type of encoding (base64 or quoted-printable) will be based on
    self.body_encoding.  If body_encoding is None, we assume the
    output charset is a 7bit encoding, so re-encoding the decoded
    string using the ascii codec produces the correct string version
    of the content."""
    if not string:
        return string
    if self.body_encoding is BASE64:
        if isinstance(string, str):
            string = string.encode(self.output_charset)
        return email.base64mime.body_encode(string)
    elif self.body_encoding is QP:
        if isinstance(string, str):
            string = string.encode(self.output_charset)
        string = string.decode('latin1')
        return email.quoprimime.body_encode(string)
    else:
        if isinstance(string, str):
            string = string.encode(self.output_charset).decode('ascii')
        return string

def get_text_content(msg, errors='replace'):
    content = msg.get_payload(decode=True)
    charset = msg.get_param('charset', 'ASCII')
    return content.decode(charset, errors=errors)

def _prepare_set(msg, maintype, subtype, headers):
    msg['Content-Type'] = '/'.join((maintype, subtype))
    if headers:
        if not hasattr(headers[0], 'name'):
            mp = msg.policy
            headers = [mp.header_factory(*mp.header_source_parse([header])) for header in headers]
        try:
            for header in headers:
                if header.defects:
                    raise header.defects[0]
                msg[header.name] = header
        except email.errors.HeaderDefect as exc:
            raise ValueError('Invalid header: {}'.format(header.fold(policy=msg.policy))) from exc

def _finalize_set(msg, disposition, filename, cid, params):
    if disposition is None and filename is not None:
        disposition = 'attachment'
    if disposition is not None:
        msg['Content-Disposition'] = disposition
    if filename is not None:
        msg.set_param('filename', filename, header='Content-Disposition', replace=True)
    if cid is not None:
        msg['Content-ID'] = cid
    if params is not None:
        for key, value in params.items():
            msg.set_param(key, value)

def _encode_base64(data, max_line_length):
    encoded_lines = []
    unencoded_bytes_per_line = max_line_length // 4 * 3
    for i in range(0, len(data), unencoded_bytes_per_line):
        thisline = data[i:i + unencoded_bytes_per_line]
        encoded_lines.append(binascii.b2a_base64(thisline).decode('ascii'))
    return ''.join(encoded_lines)

def _encode_text(string, charset, cte, policy):
    lines = string.encode(charset).splitlines()
    linesep = policy.linesep.encode('ascii')
    def embedded_body(lines):
        return linesep.join(lines) + linesep
    def normal_body(lines):
        return b'\n'.join(lines) + b'\n'
    if cte is None:
        if max((len(x) for x in lines), default=0) <= policy.max_line_length:
            try:
                return ('7bit', normal_body(lines).decode('ascii'))
            except UnicodeDecodeError:
                pass
            if policy.cte_type == '8bit':
                return ('8bit', normal_body(lines).decode('ascii', 'surrogateescape'))
        sniff = embedded_body(lines[:10])
        sniff_qp = quoprimime.body_encode(sniff.decode('latin-1'), policy.max_line_length)
        sniff_base64 = binascii.b2a_base64(sniff)
        if len(sniff_qp) > len(sniff_base64):
            cte = 'base64'
        else:
            cte = 'quoted-printable'
            if len(lines) <= 10:
                return (cte, sniff_qp)
    if cte == '7bit':
        data = normal_body(lines).decode('ascii')
    elif cte == '8bit':
        data = normal_body(lines).decode('ascii', 'surrogateescape')
    elif cte == 'quoted-printable':
        data = quoprimime.body_encode(normal_body(lines).decode('latin-1'), policy.max_line_length)
    elif cte == 'base64':
        data = _encode_base64(embedded_body(lines), policy.max_line_length)
    else:
        raise ValueError('Unknown content transfer encoding {}'.format(cte))
    return (cte, data)

def set_message_content(msg, message, subtype='rfc822', cte=None, disposition=None, filename=None, cid=None, params=None, headers=None):
    if subtype == 'partial':
        raise ValueError('message/partial is not supported for Message objects')
    if subtype == 'rfc822':
        if cte not in (None, '7bit', '8bit', 'binary'):
            raise ValueError('message/rfc822 parts do not support cte={}'.format(cte))
        cte = '8bit' if cte is None else cte
    elif subtype == 'external-body':
        if cte not in (None, '7bit'):
            raise ValueError('message/external-body parts do not support cte={}'.format(cte))
        cte = '7bit'
    elif cte is None:
        cte = '7bit'
    _prepare_set(msg, 'message', subtype, headers)
    msg.set_payload([message])
    msg['Content-Transfer-Encoding'] = cte
    _finalize_set(msg, disposition, filename, cid, params)

def set_bytes_content(msg, data, maintype, subtype, cte='base64', disposition=None, filename=None, cid=None, params=None, headers=None):
    _prepare_set(msg, maintype, subtype, headers)
    if cte == 'base64':
        data = _encode_base64(data, max_line_length=msg.policy.max_line_length)
    elif cte == 'quoted-printable':
        data = binascii.b2a_qp(data, istext=False, header=False, quotetabs=True)
        data = data.decode('ascii')
    elif cte == '7bit':
        data = data.decode('ascii')
    elif cte in ('8bit', 'binary'):
        data = data.decode('ascii', 'surrogateescape')
    msg.set_payload(data)
    msg['Content-Transfer-Encoding'] = cte
    _finalize_set(msg, disposition, filename, cid, params)

def __init__(self):
    self.get_handlers = {}
    self.set_handlers = {}

def get_content(self, msg, *args, **kw):
    content_type = msg.get_content_type()
    if content_type in self.get_handlers:
        return self.get_handlers[content_type](msg, *args, **kw)
    maintype = msg.get_content_maintype()
    if maintype in self.get_handlers:
        return self.get_handlers[maintype](msg, *args, **kw)
    if '' in self.get_handlers:
        return self.get_handlers[''](msg, *args, **kw)
    raise KeyError(content_type)

def set_content(self, msg, obj, *args, **kw):
    if msg.get_content_maintype() == 'multipart':
        raise TypeError('set_content not valid on multipart')
    handler = self._find_set_handler(msg, obj)
    msg.clear_content()
    handler(msg, obj, *args, **kw)

def _find_set_handler(self, msg, obj):
    full_path_for_error = None
    for typ in type(obj).__mro__:
        if typ in self.set_handlers:
            return self.set_handlers[typ]
        qname = typ.__qualname__
        modname = getattr(typ, '__module__', '')
        full_path = '.'.join((modname, qname)) if modname else qname
        if full_path_for_error is None:
            full_path_for_error = full_path
        if full_path in self.set_handlers:
            return self.set_handlers[full_path]
        if qname in self.set_handlers:
            return self.set_handlers[qname]
        name = typ.__name__
        if name in self.set_handlers:
            return self.set_handlers[name]
    if None in self.set_handlers:
        return self.set_handlers[None]
    raise KeyError(full_path_for_error)

def _qencode(s):
    enc = _encodestring(s, quotetabs=True)
    return enc.replace(b' ', b'=20')

def encode_7or8bit(msg):
    """Set the Content-Transfer-Encoding header to 7bit or 8bit."""
    orig = msg.get_payload(decode=True)
    if orig is None:
        msg['Content-Transfer-Encoding'] = '7bit'
        return
    try:
        orig.decode('ascii')
    except UnicodeError:
        msg['Content-Transfer-Encoding'] = '8bit'
    else:
        msg['Content-Transfer-Encoding'] = '7bit'

def __init__(self, line=None):
    if line is not None:
        super().__init__(line)
    self.line = line

def __init__(self, non_printables):
    super().__init__(non_printables)
    self.non_printables = non_printables

def readline(self):
    if not self._lines:
        if self._closed:
            return ''
        return NeedMoreData
    line = self._lines.popleft()
    for ateof in reversed(self._eofstack):
        if ateof(line):
            self._lines.appendleft(line)
            return ''
    return line

def unreadline(self, line):
    assert line is not NeedMoreData
    self._lines.appendleft(line)

def __next__(self):
    line = self.readline()
    if line == '':
        raise StopIteration
    return line

def _call_parse(self):
    try:
        self._parse()
    except StopIteration:
        pass

def _new_message(self):
    if self._old_style_factory:
        msg = self._factory()
    else:
        msg = self._factory(policy=self.policy)
    if self._cur and self._cur.get_content_type() == 'multipart/digest':
        msg.set_default_type('message/rfc822')
    if self._msgstack:
        self._msgstack[-1].attach(msg)
    self._msgstack.append(msg)
    self._cur = msg
    self._last = msg

def _pop_message(self):
    retval = self._msgstack.pop()
    if self._msgstack:
        self._cur = self._msgstack[-1]
    else:
        self._cur = None
    return retval

def _parse_headers(self, lines):
    lastheader = ''
    lastvalue = []
    for lineno, line in enumerate(lines):
        if line[0] in ' \t':
            if not lastheader:
                defect = errors.FirstHeaderLineIsContinuationDefect(line)
                self.policy.handle_defect(self._cur, defect)
                continue
            lastvalue.append(line)
            continue
        if lastheader:
            self._cur.set_raw(*self.policy.header_source_parse(lastvalue))
            lastheader, lastvalue = ('', [])
        if line.startswith('From '):
            if lineno == 0:
                mo = NLCRE_eol.search(line)
                if mo:
                    line = line[:-len(mo.group(0))]
                self._cur.set_unixfrom(line)
                continue
            elif lineno == len(lines) - 1:
                self._input.unreadline(line)
                return
            else:
                defect = errors.MisplacedEnvelopeHeaderDefect(line)
                self._cur.defects.append(defect)
                continue
        i = line.find(':')
        if i == 0:
            defect = errors.InvalidHeaderDefect('Missing header name.')
            self._cur.defects.append(defect)
            continue
        assert i > 0, '_parse_headers fed line with no : and no leading WS'
        lastheader = line[:i]
        lastvalue = [line]
    if lastheader:
        self._cur.set_raw(*self.policy.header_source_parse(lastvalue))

def clone(self, fp):
    """Clone this generator with the exact same options."""
    return self.__class__(fp, self._mangle_from_, None, policy=self.policy)

def _write_lines(self, lines):
    if not lines:
        return
    lines = NLCRE.split(lines)
    for line in lines[:-1]:
        self.write(line)
        self.write(self._NL)
    if lines[-1]:
        self.write(lines[-1])

def _write(self, msg):
    oldfp = self._fp
    try:
        self._munge_cte = None
        self._fp = sfp = self._new_buffer()
        self._dispatch(msg)
    finally:
        self._fp = oldfp
        munge_cte = self._munge_cte
        del self._munge_cte
    if munge_cte:
        msg = deepcopy(msg)
        if msg.get('content-transfer-encoding') is None:
            msg['Content-Transfer-Encoding'] = munge_cte[0]
        else:
            msg.replace_header('content-transfer-encoding', munge_cte[0])
        msg.replace_header('content-type', munge_cte[1])
    meth = getattr(msg, '_write_headers', None)
    if meth is None:
        self._write_headers(msg)
    else:
        meth(self)
    self._fp.write(sfp.getvalue())

def _write_headers(self, msg):
    for h, v in msg.raw_items():
        folded = self.policy.fold(h, v)
        if self.policy.verify_generated_headers:
            linesep = self.policy.linesep
            if not folded.endswith(self.policy.linesep):
                raise HeaderWriteError(f'folded header does not end with {linesep!r}: {folded!r}')
            if NEWLINE_WITHOUT_FWSP.search(folded.removesuffix(linesep)):
                raise HeaderWriteError(f'folded header contains newline: {folded!r}')
        self.write(folded)
    self.write(self._NL)

def _handle_text(self, msg):
    payload = msg.get_payload()
    if payload is None:
        return
    if not isinstance(payload, str):
        raise TypeError('string payload expected: %s' % type(payload))
    if _has_surrogates(msg._payload):
        charset = msg.get_param('charset')
        if charset is not None:
            msg = deepcopy(msg)
            del msg['content-transfer-encoding']
            msg.set_payload(msg._payload, charset)
            payload = msg.get_payload()
            self._munge_cte = (msg['content-transfer-encoding'], msg['content-type'])
    if self._mangle_from_:
        payload = fcre.sub('>From ', payload)
    self._write_lines(payload)

def _handle_multipart(self, msg):
    msgtexts = []
    subparts = msg.get_payload()
    if subparts is None:
        subparts = []
    elif isinstance(subparts, str):
        self.write(subparts)
        return
    elif not isinstance(subparts, list):
        subparts = [subparts]
    for part in subparts:
        s = self._new_buffer()
        g = self.clone(s)
        g.flatten(part, unixfrom=False, linesep=self._NL)
        msgtexts.append(s.getvalue())
    boundary = msg.get_boundary()
    if not boundary:
        alltext = self._encoded_NL.join(msgtexts)
        boundary = self._make_boundary(alltext)
        msg.set_boundary(boundary)
    if msg.preamble is not None:
        if self._mangle_from_:
            preamble = fcre.sub('>From ', msg.preamble)
        else:
            preamble = msg.preamble
        self._write_lines(preamble)
        self.write(self._NL)
    self.write('--' + boundary + self._NL)
    if msgtexts:
        self._fp.write(msgtexts.pop(0))
    for body_part in msgtexts:
        self.write(self._NL + '--' + boundary + self._NL)
        self._fp.write(body_part)
    self.write(self._NL + '--' + boundary + '--' + self._NL)
    if msg.epilogue is not None:
        if self._mangle_from_:
            epilogue = fcre.sub('>From ', msg.epilogue)
        else:
            epilogue = msg.epilogue
        self._write_lines(epilogue)

def _handle_message_delivery_status(self, msg):
    blocks = []
    for part in msg.get_payload():
        s = self._new_buffer()
        g = self.clone(s)
        g.flatten(part, unixfrom=False, linesep=self._NL)
        text = s.getvalue()
        lines = text.split(self._encoded_NL)
        if lines and lines[-1] == self._encoded_EMPTY:
            blocks.append(self._encoded_NL.join(lines[:-1]))
        else:
            blocks.append(text)
    self._fp.write(self._encoded_NL.join(blocks))

@classmethod
def _make_boundary(cls, text=None):
    token = random.randrange(sys.maxsize)
    boundary = '=' * 15 + _fmt % token + '=='
    if text is None:
        return boundary
    b = boundary
    counter = 0
    while True:
        cre = cls._compile_re('^--' + re.escape(b) + '(--)?$', re.MULTILINE)
        if not cre.search(text):
            break
        b = boundary + '.' + str(counter)
        counter += 1
    return b

@classmethod
def _compile_re(cls, s, flags):
    return re.compile(s, flags)

def _handle_text(self, msg):
    if msg._payload is None:
        return
    if _has_surrogates(msg._payload) and (not self.policy.cte_type == '7bit'):
        if self._mangle_from_:
            msg._payload = fcre.sub('>From ', msg._payload)
        self._write_lines(msg._payload)
    else:
        super(BytesGenerator, self)._handle_text(msg)

@classmethod
def _compile_re(cls, s, flags):
    return re.compile(s.encode('ascii'), flags)

def _dispatch(self, msg):
    for part in msg.walk():
        maintype = part.get_content_maintype()
        if maintype == 'text':
            print(part.get_payload(decode=False), file=self)
        elif maintype == 'multipart':
            pass
        else:
            print(self._fmt % {'type': part.get_content_type(), 'maintype': part.get_content_maintype(), 'subtype': part.get_content_subtype(), 'filename': part.get_filename('[no filename]'), 'description': part.get('Content-Description', '[no description]'), 'encoding': part.get('Content-Transfer-Encoding', '[no encoding]')}, file=self)

def __str__(self):
    """Return the string value of the header."""
    self._normalize()
    uchunks = []
    lastcs = None
    lastspace = None
    for string, charset in self._chunks:
        nextcs = charset
        if nextcs == _charset.UNKNOWN8BIT:
            original_bytes = string.encode('ascii', 'surrogateescape')
            string = original_bytes.decode('ascii', 'replace')
        if uchunks:
            hasspace = string and self._nonctext(string[0])
            if lastcs not in (None, 'us-ascii'):
                if nextcs in (None, 'us-ascii') and (not hasspace):
                    uchunks.append(SPACE)
                    nextcs = None
            elif nextcs not in (None, 'us-ascii') and (not lastspace):
                uchunks.append(SPACE)
        lastspace = string and self._nonctext(string[-1])
        lastcs = nextcs
        uchunks.append(string)
    return EMPTYSTRING.join(uchunks)

def _nonctext(self, s):
    """True if string s is not a ctext character of RFC822.
    """
    return s.isspace() or s in ('(', ')', '\\')

def _normalize(self):
    chunks = []
    last_charset = None
    last_chunk = []
    for string, charset in self._chunks:
        if charset == last_charset:
            last_chunk.append(string)
        else:
            if last_charset is not None:
                chunks.append((SPACE.join(last_chunk), last_charset))
            last_chunk = [string]
            last_charset = charset
    if last_chunk:
        chunks.append((SPACE.join(last_chunk), last_charset))
    self._chunks = chunks

def feed(self, fws, string, charset):
    if charset.header_encoding is None:
        self._ascii_split(fws, string, self._splitchars)
        return
    encoded_lines = charset.header_encode_lines(string, self._maxlengths())
    try:
        first_line = encoded_lines.pop(0)
    except IndexError:
        return
    if first_line is not None:
        self._append_chunk(fws, first_line)
    try:
        last_line = encoded_lines.pop()
    except IndexError:
        return
    self.newline()
    self._current_line.push(self._continuation_ws, last_line)
    for line in encoded_lines:
        self._lines.append(self._continuation_ws + line)

def _maxlengths(self):
    yield (self._maxlen - len(self._current_line))
    while True:
        yield (self._maxlen - self._continuation_ws_len)

def _ascii_split(self, fws, string, splitchars):
    parts = re.split('([' + FWS + ']+)', fws + string)
    if parts[0]:
        parts[:0] = ['']
    else:
        parts.pop(0)
    for fws, part in zip(*[iter(parts)] * 2):
        self._append_chunk(fws, part)

def _append_chunk(self, fws, string):
    self._current_line.push(fws, string)
    if len(self._current_line) > self._maxlen:
        for ch in self._splitchars:
            for i in range(self._current_line.part_count() - 1, 0, -1):
                if ch.isspace():
                    fws = self._current_line[i][0]
                    if fws and fws[0] == ch:
                        break
                prevpart = self._current_line[i - 1][1]
                if prevpart and prevpart[-1] == ch:
                    break
            else:
                continue
            break
        else:
            fws, part = self._current_line.pop()
            if self._current_line._initial_size > 0:
                self.newline()
                if not fws:
                    fws = ' '
            self._current_line.push(fws, part)
            return
        remainder = self._current_line.pop_from(i)
        self._lines.append(str(self._current_line))
        self._current_line.reset(remainder)

def __init__(self, initial_size=0):
    self._initial_size = initial_size
    super().__init__()

def pop(self):
    if self.part_count() == 0:
        return ('', '')
    return super().pop()

def reset(self, startval=None):
    if startval is None:
        startval = []
    self[:] = startval
    self._initial_size = 0

@property
def display_name(self):
    return self._display_name

@property
def username(self):
    return self._username

@property
def domain(self):
    return self._domain

@property
def addr_spec(self):
    """The addr_spec (username@domain) portion of the address, quoted
    according to RFC 5322 rules, but with no Content Transfer Encoding."""
    lp = self.username
    if not parser.DOT_ATOM_ENDS.isdisjoint(lp):
        lp = parser.quote_string(lp)
    if self.domain:
        return lp + '@' + self.domain
    if not lp:
        return '<>'
    return lp

def __str__(self):
    disp = self.display_name
    if not parser.SPECIALS.isdisjoint(disp):
        disp = parser.quote_string(disp)
    if disp:
        addr_spec = '' if self.addr_spec == '<>' else self.addr_spec
        return '{} <{}>'.format(disp, addr_spec)
    return self.addr_spec

def __eq__(self, other):
    if not isinstance(other, Address):
        return NotImplemented
    return self.display_name == other.display_name and self.username == other.username and (self.domain == other.domain)

@property
def addresses(self):
    return self._addresses

def __str__(self):
    if self.display_name is None and len(self.addresses) == 1:
        return str(self.addresses[0])
    disp = self.display_name
    if disp is not None and (not parser.SPECIALS.isdisjoint(disp)):
        disp = parser.quote_string(disp)
    adrstr = ', '.join((str(x) for x in self.addresses))
    adrstr = ' ' + adrstr if adrstr else adrstr
    return '{}:{};'.format(disp, adrstr)

def __eq__(self, other):
    if not isinstance(other, Group):
        return NotImplemented
    return self.display_name == other.display_name and self.addresses == other.addresses

def __new__(cls, name, value):
    kwds = {'defects': []}
    cls.parse(value, kwds)
    if utils._has_surrogates(kwds['decoded']):
        kwds['decoded'] = utils._sanitize(kwds['decoded'])
    self = str.__new__(cls, kwds['decoded'])
    del kwds['decoded']
    self.init(name, **kwds)
    return self

@property
def defects(self):
