def __getitem__(self, name):
    cls = self.registry.get(name.lower(), self.default_class)
    return type('_' + cls.__name__, (cls, self.base_class), {})

def walk(self):
    """Walk over the message tree, yielding each subpart.

    The walk is performed in depth-first order.  This method is a
    generator."""
    yield self
    if self.is_multipart():
        for subpart in self.get_payload():
            yield from subpart.walk()

def body_line_iterator(msg, decode=False):
    """Iterate over the parts, returning string payloads line-by-line.

    Optional decode (default False) is passed through to .get_payload()."""
    for subpart in msg.walk():
        payload = subpart.get_payload(decode=decode)
        if isinstance(payload, str):
            yield from StringIO(payload)

def typed_subpart_iterator(msg, maintype='text', subtype=None):
    """Iterate over the subparts with a given MIME type.

    Use `maintype' as the main MIME type to match against; this defaults to
    "text".  Optional `subtype' is the MIME subtype to match against; if
    omitted, only the main type is matched."""
    for subpart in msg.walk():
        if subpart.get_content_maintype() == maintype:
            if subtype is None or subpart.get_content_subtype() == subtype:
                yield subpart

def _structure(msg, fp=None, level=0, include_default=False):
    """A handy debugging aid"""
    if fp is None:
        fp = sys.stdout
    tab = ' ' * (level * 4)
    print(tab + msg.get_content_type(), end='', file=fp)
    if include_default:
        print(' [%s]' % msg.get_default_type(), file=fp)
    else:
        print(file=fp)
    if msg.is_multipart():
        for subpart in msg.get_payload():
            _structure(subpart, fp, level + 1, include_default)

def _splitparam(param):
    a, sep, b = str(param).partition(';')
    if not sep:
        return (a.strip(), None)
    return (a.strip(), b.strip())

def _formatparam(param, value=None, quote=True):
    """Convenience function to format and return a key=value pair.

    This will quote the value if needed or if quote is true.  If value is a
    three tuple (charset, language, value), it will be encoded according
    to RFC2231 rules.  If it contains non-ascii characters it will likewise
    be encoded according to RFC2231 rules, using the utf-8 charset and
    a null language."""
    if value is not None and len(value) > 0:
        if isinstance(value, tuple):
            param += '*'
            value = utils.encode_rfc2231(value[2], value[0], value[1])
            return '%s=%s' % (param, value)
        else:
            try:
                value.encode('ascii')
            except UnicodeEncodeError:
                param += '*'
                value = utils.encode_rfc2231(value, 'utf-8', '')
                return '%s=%s' % (param, value)
        if quote or tspecials.search(value):
            return '%s="%s"' % (param, utils.quote(value))
        else:
            return '%s=%s' % (param, value)
    else:
        return param

def _parseparam(s):
    s = ';' + str(s)
    plist = []
    start = 0
    while s.find(';', start) == start:
        start += 1
        end = s.find(';', start)
        ind, diff = (start, 0)
        while end > 0:
            diff += s.count('"', ind, end) - s.count('\\"', ind, end)
            if diff % 2 == 0:
                break
            end, ind = (ind, s.find(';', end + 1))
        if end < 0:
            end = len(s)
        i = s.find('=', start, end)
        if i == -1:
            f = s[start:end]
        else:
            f = s[start:i].rstrip().lower() + '=' + s[i + 1:end].lstrip()
        plist.append(f.strip())
        start = end
    return plist

def _unquotevalue(value):
    if isinstance(value, tuple):
        return (value[0], value[1], utils.unquote(value[2]))
    else:
        return utils.unquote(value)

def _decode_uu(encoded):
    """Decode uuencoded data."""
    decoded_lines = []
    encoded_lines_iter = iter(encoded.splitlines())
    for line in encoded_lines_iter:
        if line.startswith(b'begin '):
            mode, _, path = line.removeprefix(b'begin ').partition(b' ')
            try:
                int(mode, base=8)
            except ValueError:
                continue
            else:
                break
    else:
        raise ValueError('`begin` line not found')
    for line in encoded_lines_iter:
        if not line:
            raise ValueError('Truncated input')
        elif line.strip(b' \t\r\n\x0c') == b'end':
            break
        try:
            decoded_line = binascii.a2b_uu(line)
        except binascii.Error:
            nbytes = ((line[0] - 32 & 63) * 4 + 5) // 3
            decoded_line = binascii.a2b_uu(line[:nbytes])
        decoded_lines.append(decoded_line)
    return b''.join(decoded_lines)

def __str__(self):
    """Return the entire formatted message as a string.
    """
    return self.as_string()

def __bytes__(self):
    """Return the entire formatted message as a bytes object.
    """
    return self.as_bytes()

def is_multipart(self):
    """Return True if the message consists of multiple parts."""
    return isinstance(self._payload, list)

def attach(self, payload):
    """Add the given payload to the current payload.

    The current payload will always be a list of objects after this method
    is called.  If you want to set the payload to a scalar object, use
    set_payload() instead."""
    if self._payload is None:
        self._payload = [payload]
    else:
        try:
            self._payload.append(payload)
        except AttributeError:
            raise TypeError('Attach is not valid on a message with a non-multipart payload')

def set_payload(self, payload, charset=None):
    """Set the payload to the given value.

    Optional charset sets the message's default character set.  See
    set_charset() for details."""
    if hasattr(payload, 'encode'):
        if charset is None:
            self._payload = payload
            return
        if not isinstance(charset, Charset):
            charset = Charset(charset)
        payload = payload.encode(charset.output_charset, 'surrogateescape')
    if hasattr(payload, 'decode'):
        self._payload = payload.decode('ascii', 'surrogateescape')
    else:
        self._payload = payload
    if charset is not None:
        self.set_charset(charset)

def __len__(self):
    """Return the total number of headers, including duplicates."""
    return len(self._headers)

def __setitem__(self, name, val):
    """Set the value of a header.

    Note: this does not overwrite an existing header with the same field
    name.  Use __delitem__() first to delete any existing headers."""
    max_count = self.policy.header_max_count(name)
    if max_count:
        lname = name.lower()
        found = 0
        for k, v in self._headers:
            if k.lower() == lname:
                found += 1
                if found >= max_count:
                    raise ValueError('There may be at most {} {} headers in a message'.format(max_count, name))
    self._headers.append(self.policy.header_store_parse(name, val))

def __delitem__(self, name):
    """Delete all occurrences of a header, if present.

    Does not raise an exception if the header is missing."""
    name = name.lower()
    newheaders = []
    for k, v in self._headers:
        if k.lower() != name:
            newheaders.append((k, v))
    self._headers = newheaders

def __contains__(self, name):
    name_lower = name.lower()
    for k, v in self._headers:
        if name_lower == k.lower():
            return True
    return False

def __iter__(self):
    for field, value in self._headers:
        yield field

def get(self, name, failobj=None):
    """Get a header value.

    Like __getitem__() but return failobj instead of None when the field
    is missing."""
    name = name.lower()
    for k, v in self._headers:
        if k.lower() == name:
            return self.policy.header_fetch_parse(k, v)
    return failobj

def replace_header(self, _name, _value):
    """Replace a header.

    Replace the first matching header found in the message, retaining
    header order and case.  If no matching header was found, a KeyError is
    raised."""
    _name = _name.lower()
    for i, (k, v) in zip(range(len(self._headers)), self._headers):
        if k.lower() == _name:
            self._headers[i] = self.policy.header_store_parse(k, _value)
            break
    else:
        raise KeyError(_name)

def del_param(self, param, header='content-type', requote=True):
    """Remove the given parameter completely from the Content-Type header.

    The header will be re-written in place without the parameter or its
    value. All values will be quoted as necessary unless requote is
    False.  Optional header specifies an alternative to the Content-Type
    header."""
    if header not in self:
        return
    new_ctype = ''
    for p, v in self.get_params(header=header, unquote=requote):
        if p.lower() != param.lower():
            if not new_ctype:
                new_ctype = _formatparam(p, v, requote)
            else:
                new_ctype = SEMISPACE.join([new_ctype, _formatparam(p, v, requote)])
    if new_ctype != self.get(header):
        del self[header]
        self[header] = new_ctype

def get_filename(self, failobj=None):
    """Return the filename associated with the payload if present.

    The filename is extracted from the Content-Disposition header's
    `filename' parameter, and it is unquoted.  If that header is missing
    the `filename' parameter, this method falls back to looking for the
    `name' parameter."""
    missing = object()
    filename = self.get_param('filename', missing, 'content-disposition')
    if filename is missing:
        filename = self.get_param('name', missing, 'content-type')
    if filename is missing:
        return failobj
    return utils.collapse_rfc2231_value(filename).strip()

def get_boundary(self, failobj=None):
    """Return the boundary associated with the payload if present.

    The boundary is extracted from the Content-Type header's `boundary'
    parameter, and it is unquoted."""
    missing = object()
    boundary = self.get_param('boundary', missing)
    if boundary is missing:
        return failobj
    return utils.collapse_rfc2231_value(boundary).rstrip()

def set_boundary(self, boundary):
    """Set the boundary parameter in Content-Type to 'boundary'.

    This is subtly different than deleting the Content-Type header and
    adding a new one with a new boundary parameter via add_header().  The
    main difference is that using the set_boundary() method preserves the
    order of the Content-Type header in the original message.

    HeaderParseError is raised if the message has no Content-Type header."""
    missing = object()
    params = self._get_params_preserve(missing, 'content-type')
    if params is missing:
        raise errors.HeaderParseError('No Content-Type header found')
    newparams = []
    foundp = False
    for pk, pv in params:
        if pk.lower() == 'boundary':
            newparams.append(('boundary', '"%s"' % boundary))
            foundp = True
        else:
            newparams.append((pk, pv))
    if not foundp:
        newparams.append(('boundary', '"%s"' % boundary))
    newheaders = []
    for h, v in self._headers:
        if h.lower() == 'content-type':
            parts = []
            for k, v in newparams:
                if v == '':
                    parts.append(k)
                else:
                    parts.append('%s=%s' % (k, v))
            val = SEMISPACE.join(parts)
            newheaders.append(self.policy.header_store_parse(h, val))
        else:
            newheaders.append((h, v))
    self._headers = newheaders

def get_content_charset(self, failobj=None):
    """Return the charset parameter of the Content-Type header.

    The returned string is always coerced to lower case.  If there is no
    Content-Type header, or if that header has no charset parameter,
    failobj is returned."""
    missing = object()
    charset = self.get_param('charset', missing)
    if charset is missing:
        return failobj
    if isinstance(charset, tuple):
        pcharset = charset[0] or 'us-ascii'
        try:
            as_bytes = charset[2].encode('raw-unicode-escape')
            charset = str(as_bytes, pcharset)
        except (LookupError, UnicodeError):
            charset = charset[2]
    try:
        charset.encode('us-ascii')
    except UnicodeError:
        return failobj
    return charset.lower()

def __init__(self, policy=None):
    if policy is None:
        from email.policy import default
        policy = default
    super().__init__(policy)

def is_attachment(self):
    c_d = self.get('content-disposition')
    return False if c_d is None else c_d.content_disposition == 'attachment'

def _find_body(self, part, preferencelist):
    if part.is_attachment():
        return
    maintype, subtype = part.get_content_type().split('/')
    if maintype == 'text':
        if subtype in preferencelist:
            yield (preferencelist.index(subtype), part)
        return
    if maintype != 'multipart' or not self.is_multipart():
        return
    if subtype != 'related':
        for subpart in part.iter_parts():
            yield from self._find_body(subpart, preferencelist)
        return
    if 'related' in preferencelist:
        yield (preferencelist.index('related'), part)
    candidate = None
    start = part.get_param('start')
    if start:
        for subpart in part.iter_parts():
            if subpart['content-id'] == start:
                candidate = subpart
                break
    if candidate is None:
        subparts = part.get_payload()
        candidate = subparts[0] if subparts else None
    if candidate is not None:
        yield from self._find_body(candidate, preferencelist)

def iter_parts(self):
    """Return an iterator over all immediate subparts of a multipart.

    Return an empty iterator for a non-multipart."""
    if self.is_multipart():
        yield from self.get_payload()

def get_content(self, *args, content_manager=None, **kw):
    if content_manager is None:
        content_manager = self.policy.content_manager
    return content_manager.get_content(self, *args, **kw)

def set_content(self, *args, content_manager=None, **kw):
    if content_manager is None:
        content_manager = self.policy.content_manager
    content_manager.set_content(self, *args, **kw)

def _make_multipart(self, subtype, disallowed_subtypes, boundary):
    if self.get_content_maintype() == 'multipart':
        existing_subtype = self.get_content_subtype()
        disallowed_subtypes = disallowed_subtypes + (subtype,)
        if existing_subtype in disallowed_subtypes:
            raise ValueError('Cannot convert {} to {}'.format(existing_subtype, subtype))
    keep_headers = []
    part_headers = []
    for name, value in self._headers:
        if name.lower().startswith('content-'):
            part_headers.append((name, value))
        else:
            keep_headers.append((name, value))
    if part_headers:
        part = type(self)(policy=self.policy)
        part._headers = part_headers
        part._payload = self._payload
        self._payload = [part]
    else:
        self._payload = []
    self._headers = keep_headers
    self['Content-Type'] = 'multipart/' + subtype
    if boundary is not None:
        self.set_param('boundary', boundary)

def _add_multipart(self, _subtype, *args, _disp=None, **kw):
    if self.get_content_maintype() != 'multipart' or self.get_content_subtype() != _subtype:
        getattr(self, 'make_' + _subtype)()
    part = type(self)(policy=self.policy)
    part.set_content(*args, **kw)
    if _disp and 'content-disposition' not in part:
        part['Content-Disposition'] = _disp
    self.attach(part)

def clear(self):
    self._headers = []
    self._payload = None

def clear_content(self):
    self._headers = [(n, v) for n, v in self._headers if not n.lower().startswith('content-')]
    self._payload = None

def set_content(self, *args, **kw):
    super().set_content(*args, **kw)
    if 'MIME-Version' not in self:
        self['MIME-Version'] = '1.0'

def _what(data):
    hdr = data[:512]
    fakefile = BytesIO(hdr)
    for testfn in _rules:
        if (res := testfn(hdr, fakefile)):
            return res
    else:
        return None

def rule(rulefunc):
    _rules.append(rulefunc)
    return rulefunc

@rule
def _aiff(h, f):
    if not h.startswith(b'FORM'):
        return None
    if h[8:12] in {b'AIFC', b'AIFF'}:
        return 'x-aiff'
    else:
        return None

@rule
def _au(h, f):
    if h.startswith(b'.snd'):
        return 'basic'
    else:
        return None

@rule
def _wav(h, f):
    if not h.startswith(b'RIFF') or h[8:12] != b'WAVE' or h[12:16] != b'fmt ':
        return None
    else:
        return 'x-wav'

def _what(data):
    for rule in _rules:
        if (res := rule(data)):
            return res
    else:
        return None

@rule
def _jpeg(h):
    """JPEG data with JFIF or Exif markers; and raw JPEG"""
    if h[6:10] in (b'JFIF', b'Exif'):
        return 'jpeg'
    elif h[:4] == b'\xff\xd8\xff\xdb':
        return 'jpeg'

@rule
def _png(h):
    if h.startswith(b'\x89PNG\r\n\x1a\n'):
        return 'png'

@rule
def _gif(h):
    """GIF ('87 and '89 variants)"""
    if h[:6] in (b'GIF87a', b'GIF89a'):
        return 'gif'

@rule
def _tiff(h):
    """TIFF (can be in Motorola or Intel byte order)"""
    if h[:2] in (b'MM', b'II'):
        return 'tiff'

@rule
def _rgb(h):
    """SGI image library"""
    if h.startswith(b'\x01\xda'):
        return 'rgb'

@rule
def _pbm(h):
    """PBM (portable bitmap)"""
    if len(h) >= 3 and h[0] == ord(b'P') and (h[1] in b'14') and (h[2] in b' \t\n\r'):
        return 'pbm'

@rule
def _ppm(h):
    """PPM (portable pixmap)"""
    if len(h) >= 3 and h[0] == ord(b'P') and (h[1] in b'36') and (h[2] in b' \t\n\r'):
        return 'ppm'

@rule
def _rast(h):
    """Sun raster file"""
    if h.startswith(b'Y\xa6j\x95'):
        return 'rast'

@rule
def _xbm(h):
    """X bitmap (X10 or X11)"""
    if h.startswith(b'#define '):
        return 'xbm'

@rule
def _bmp(h):
    if h.startswith(b'BM'):
        return 'bmp'

@rule
def _webp(h):
    if h.startswith(b'RIFF') and h[8:12] == b'WEBP':
        return 'webp'

@rule
def _exr(h):
    if h.startswith(b'v/1\x01'):
        return 'exr'

def parse(self, fp, headersonly=False):
    """Create a message structure from the data in a file.

    Reads all the data from the file and returns the root of the message
    structure.  Optional headersonly is a flag specifying whether to stop
    parsing after reading the headers or not.  The default is False,
    meaning it parses the entire contents of the file."""
    feedparser = FeedParser(self._class, policy=self.policy)
    if headersonly:
        feedparser._set_headersonly()
    while (data := fp.read(8192)):
        feedparser.feed(data)
    return feedparser.close()

def __init__(self, **kw):
    if 'header_factory' not in kw:
        object.__setattr__(self, 'header_factory', HeaderRegistry())
    super().__init__(**kw)

def header_store_parse(self, name, value):
    """+
    The name is returned unchanged.  If the input value has a 'name'
    attribute and it matches the name ignoring case, the value is returned
    unchanged.  Otherwise the name and value are passed to header_factory
    method, and the resulting custom header object is returned as the
    value.  In this case a ValueError is raised if the input value contains
    CR or LF characters."""
    if hasattr(value, 'name') and value.name.lower() == name.lower():
        return (name, value)
    if isinstance(value, str) and len(value.splitlines()) > 1:
        raise ValueError('Header values may not contain linefeed or carriage return characters')
    return (name, self.header_factory(name, value))

def _fold(self, name, value, refold_binary=False):
    if hasattr(value, 'name'):
        return value.fold(policy=self)
    maxlen = self.max_line_length if self.max_line_length else sys.maxsize
    lines = linesep_splitter.split(value)
    refold = self.refold_source == 'all' or (self.refold_source == 'long' and (lines and len(lines[0]) + len(name) + 2 > maxlen or any((len(x) > maxlen for x in lines[1:]))))
    if not refold:
        if not self.utf8:
            refold = not value.isascii()
        elif refold_binary:
            refold = _has_surrogates(value)
    if refold:
        return self.header_factory(name, ''.join(lines)).fold(policy=self)
    return name + ': ' + self.linesep.join(lines) + self.linesep

def header_check(octet):
    """Return True if the octet should be escaped with header quopri."""
    return chr(octet) != _QUOPRI_HEADER_MAP[octet]

def body_check(octet):
    """Return True if the octet should be escaped with body quopri."""
    return chr(octet) != _QUOPRI_BODY_MAP[octet]

def body_length(bytearray):
    """Return a body quoted-printable encoding length.

    :param bytearray: An array of bytes (a.k.a. octets).
    :return: The length in bytes of the byte array when it is encoded with
        quoted-printable for bodies."""
    return sum((len(_QUOPRI_BODY_MAP[octet]) for octet in bytearray))

def _max_append(L, s, maxlen, extra=''):
    if not isinstance(s, str):
        s = chr(s)
    if not L:
        L.append(s.lstrip())
    elif len(L[-1]) + len(s) <= maxlen:
        L[-1] += extra + s
    else:
        L.append(s.lstrip())

def unquote(s):
    """Turn a string in the form =AB to the ASCII character with value 0xab"""
    return chr(int(s[1:3], 16))

def decode(encoded, eol=NL):
    """Decode a quoted-printable string.

    Lines are separated with eol, which defaults to \\n."""
    if not encoded:
        return encoded
    decoded = ''
    for line in encoded.splitlines():
        line = line.rstrip()
        if not line:
            decoded += eol
            continue
        i = 0
        n = len(line)
        while i < n:
            c = line[i]
            if c != '=':
                decoded += c
                i += 1
            elif i + 1 == n:
                i += 1
                continue
            elif i + 2 < n and line[i + 1] in hexdigits and (line[i + 2] in hexdigits):
                decoded += unquote(line[i:i + 3])
                i += 3
            else:
                decoded += c
                i += 1
            if i == n:
                decoded += eol
    if encoded[-1] not in '\r\n' and decoded.endswith(eol):
        decoded = decoded[:-1]
    return decoded

def _unquote_match(match):
    """Turn a match in the form =AB to the ASCII character with value 0xab"""
    s = match.group(0)
    return unquote(s)

def _has_surrogates(s):
    """Return True if s may contain surrogate-escaped binary data."""
    try:
        s.encode()
        return False
    except UnicodeEncodeError:
        return True

def _sanitize(string):
    original_bytes = string.encode('utf-8', 'surrogateescape')
    return original_bytes.decode('utf-8', 'replace')

def formataddr(pair, charset='utf-8'):
    """The inverse of parseaddr(), this takes a 2-tuple of the form
    (realname, email_address) and returns the string value suitable
    for an RFC 2822 From, To or Cc header.

    If the first element of pair is false, then the second element is
    returned unmodified.

    The optional charset is the character set that is used to encode
    realname in case realname is not ASCII safe.  Can be an instance of str or
    a Charset-like object which has a header_encode method.  Default is
    'utf-8'."""
    name, address = pair
    address.encode('ascii')
    if name:
        try:
            name.encode('ascii')
        except UnicodeEncodeError:
            if isinstance(charset, str):
                charset = Charset(charset)
            encoded_name = charset.header_encode(name)
            return '%s <%s>' % (encoded_name, address)
        else:
            quotes = ''
            if specialsre.search(name):
                quotes = '"'
            name = escapesre.sub('\\\\\\g<0>', name)
            return '%s%s%s <%s>' % (quotes, name, quotes, address)
    return address

def _iter_escaped_chars(addr):
    pos = 0
    escape = False
    for pos, ch in enumerate(addr):
        if escape:
            yield (pos, '\\' + ch)
            escape = False
        elif ch == '\\':
            escape = True
        else:
            yield (pos, ch)
    if escape:
        yield (pos, '\\')

def _strip_quoted_realnames(addr):
    """Strip real names between quotes."""
    if '"' not in addr:
        return addr
    start = 0
    open_pos = None
    result = []
    for pos, ch in _iter_escaped_chars(addr):
        if ch == '"':
            if open_pos is None:
                open_pos = pos
            else:
                if start != open_pos:
                    result.append(addr[start:open_pos])
                start = pos + 1
                open_pos = None
    if start < len(addr):
        result.append(addr[start:])
    return ''.join(result)

def _check_parenthesis(addr):
    addr = _strip_quoted_realnames(addr)
    opens = 0
    for pos, ch in _iter_escaped_chars(addr):
        if ch == '(':
            opens += 1
        elif ch == ')':
            opens -= 1
            if opens < 0:
                return False
    return opens == 0

def _pre_parse_validation(email_header_fields):
    accepted_values = []
    for v in email_header_fields:
        if not _check_parenthesis(v):
            v = "('', '')"
        accepted_values.append(v)
    return accepted_values

def _post_parse_validation(parsed_email_header_tuples):
    accepted_values = []
    for v in parsed_email_header_tuples:
        if '[' in v[1]:
            v = ('', '')
        accepted_values.append(v)
    return accepted_values

def format_datetime(dt, usegmt=False):
    """Turn a datetime into a date string as specified in RFC 2822.

    If usegmt is True, dt must be an aware datetime with an offset of zero.  In
    this case 'GMT' will be rendered instead of the normal +0000 required by
    RFC2822.  This is to support HTTP headers involving date stamps."""
    now = dt.timetuple()
    if usegmt:
        if dt.tzinfo is None or dt.tzinfo != datetime.timezone.utc:
            raise ValueError('usegmt option requires a UTC datetime')
        zone = 'GMT'
    elif dt.tzinfo is None:
        zone = '-0000'
    else:
        zone = dt.strftime('%z')
    return _format_timetuple_and_zone(now, zone)

def parsedate_to_datetime(data):
    parsed_date_tz = _parsedate_tz(data)
    if parsed_date_tz is None:
        raise ValueError('Invalid date value or format "%s"' % str(data))
    *dtuple, tz = parsed_date_tz
    if tz is None:
        return datetime.datetime(*dtuple[:6])
    return datetime.datetime(*dtuple[:6], tzinfo=datetime.timezone(datetime.timedelta(seconds=tz)))

def parseaddr(addr, *, strict=True):
    """Parse addr into its constituent realname and email address parts.

    Return a tuple of realname and email address, unless the parse fails, in
    which case return a 2-tuple of ('', '').

    If strict is True, use a strict parser which rejects malformed inputs."""
    if not strict:
        addrs = _AddressList(addr).addresslist
        if not addrs:
            return ('', '')
        return addrs[0]
    if isinstance(addr, list):
        addr = addr[0]
    if not isinstance(addr, str):
        return ('', '')
    addr = _pre_parse_validation([addr])[0]
    addrs = _post_parse_validation(_AddressList(addr).addresslist)
    if not addrs or len(addrs) > 1:
        return ('', '')
    return addrs[0]

def unquote(str):
    """Remove quotes from a string."""
    if len(str) > 1:
        if str.startswith('"') and str.endswith('"'):
            return str[1:-1].replace('\\\\', '\\').replace('\\"', '"')
        if str.startswith('<') and str.endswith('>'):
            return str[1:-1]
    return str

def decode_rfc2231(s):
    """Decode string according to RFC 2231"""
    parts = s.split(TICK, 2)
    if len(parts) <= 2:
        return (None, None, s)
    return parts

def encode_rfc2231(s, charset=None, language=None):
    """Encode string according to RFC 2231.

    If neither charset nor language is given, then s is returned as-is.  If
    charset is given but not language, the string is encoded using the empty
    string for language."""
    s = urllib.parse.quote(s, safe='', encoding=charset or 'ascii')
    if charset is None and language is None:
        return s
    if language is None:
        language = ''
    return "%s'%s'%s" % (charset, language, s)

def decode_params(params):
    """Decode parameters list according to RFC 2231.

    params is a sequence of 2-tuples containing (param name, string value)."""
    new_params = [params[0]]
    rfc2231_params = {}
    for name, value in params[1:]:
        encoded = name.endswith('*')
        value = unquote(value)
        mo = rfc2231_continuation.match(name)
        if mo:
            name, num = mo.group('name', 'num')
            if num is not None:
                num = int(num)
            rfc2231_params.setdefault(name, []).append((num, value, encoded))
        else:
            new_params.append((name, '"%s"' % quote(value)))
    if rfc2231_params:
        for name, continuations in rfc2231_params.items():
            value = []
            extended = False
            continuations.sort()
            for num, s, encoded in continuations:
                if encoded:
                    s = urllib.parse.unquote(s, encoding='latin-1')
                    extended = True
                value.append(s)
            value = quote(EMPTYSTRING.join(value))
            if extended:
                charset, language, value = decode_rfc2231(value)
                new_params.append((name, (charset, language, '"%s"' % value)))
            else:
                new_params.append((name, '"%s"' % value))
    return new_params

def collapse_rfc2231_value(value, errors='replace', fallback_charset='us-ascii'):
    if not isinstance(value, tuple) or len(value) != 3:
        return unquote(value)
    charset, language, text = value
    if charset is None:
        charset = fallback_charset
    rawbytes = bytes(text, 'raw-unicode-escape')
    try:
        return str(rawbytes, charset, errors)
    except LookupError:
        return unquote(text)

def localtime(dt=None, isdst=None):
    """Return local time as an aware datetime object.

    If called without arguments, return current time.  Otherwise *dt*
    argument should be a datetime instance, and it is converted to the
    local time zone according to the system time zone database.  If *dt* is
    naive (that is, dt.tzinfo is None), it is assumed to be in local time.
    The isdst parameter is ignored."""
    if isdst is not None:
        import warnings
        warnings._deprecated("The 'isdst' parameter to 'localtime'", message='{name} is deprecated and slated for removal in Python {remove}', remove=(3, 14))
    if dt is None:
        dt = datetime.datetime.now()
    return dt.astimezone()

def normalize_encoding(encoding):
    """Normalize an encoding name.

    Normalization works as follows: all non-alphanumeric
    characters except the dot used for Python package names are
    collapsed and replaced with a single underscore, e.g. '  -;#'
    becomes '_'. Leading and trailing underscores are removed.

    Note that encoding names should be ASCII only."""
    if isinstance(encoding, bytes):
        encoding = str(encoding, 'ascii')
    chars = []
    punct = False
    for c in encoding:
        if c.isalnum() or c == '.':
            if punct and chars:
                chars.append('_')
            if c.isascii():
                chars.append(c)
            punct = False
        else:
            punct = True
    return ''.join(chars)

def _alias_mbcs(encoding):
    try:
        import _winapi
        ansi_code_page = 'cp%s' % _winapi.GetACP()
        if encoding == ansi_code_page:
            import encodings.mbcs
            return encodings.mbcs.getregentry()
    except ImportError:
        pass

def base64_encode(input, errors='strict'):
    assert errors == 'strict'
    return (base64.encodebytes(input), len(input))

def base64_decode(input, errors='strict'):
    assert errors == 'strict'
    return (base64.decodebytes(input), len(input))

