    labels = dots.split(input)
    trailing_dot = b''
    if labels:
        if not labels[-1]:
            trailing_dot = b'.'
            del labels[-1]
        elif not final:
            del labels[-1]
            if labels:
                trailing_dot = b'.'
    result = bytearray()
    size = 0
    for label in labels:
        if size:
            result.extend(b'.')
            size += 1
        result.extend(ToASCII(label))
        size += len(label)
    result += trailing_dot
    size += len(trailing_dot)
    return (bytes(result), size)

