def __init__(self, a, b, ignore=None, hide=None):
    self.left = a
    self.right = b
    if hide is None:
        self.hide = [os.curdir, os.pardir]
    else:
        self.hide = hide
    if ignore is None:
        self.ignore = DEFAULT_IGNORES
    else:
        self.ignore = ignore

def phase2(self):
    self.common_dirs = []
    self.common_files = []
    self.common_funny = []
    for x in self.common:
        a_path = os.path.join(self.left, x)
        b_path = os.path.join(self.right, x)
        ok = True
        try:
            a_stat = os.stat(a_path)
        except (OSError, ValueError):
            ok = False
        try:
            b_stat = os.stat(b_path)
        except (OSError, ValueError):
            ok = False
        if ok:
            a_type = stat.S_IFMT(a_stat.st_mode)
            b_type = stat.S_IFMT(b_stat.st_mode)
            if a_type != b_type:
                self.common_funny.append(x)
            elif stat.S_ISDIR(a_type):
                self.common_dirs.append(x)
            elif stat.S_ISREG(a_type):
                self.common_files.append(x)
            else:
                self.common_funny.append(x)
        else:
            self.common_funny.append(x)

def phase3(self):
    xx = cmpfiles(self.left, self.right, self.common_files)
    self.same_files, self.diff_files, self.funny_files = xx

def phase4(self):
    self.subdirs = {}
    for x in self.common_dirs:
        a_x = os.path.join(self.left, x)
        b_x = os.path.join(self.right, x)
        self.subdirs[x] = self.__class__(a_x, b_x, self.ignore, self.hide)

def phase4_closure(self):
    self.phase4()
    for sd in self.subdirs.values():
        sd.phase4_closure()

def report(self):
    print('diff', self.left, self.right)
    if self.left_only:
        self.left_only.sort()
        print('Only in', self.left, ':', self.left_only)
    if self.right_only:
        self.right_only.sort()
        print('Only in', self.right, ':', self.right_only)
    if self.same_files:
        self.same_files.sort()
        print('Identical files :', self.same_files)
    if self.diff_files:
        self.diff_files.sort()
        print('Differing files :', self.diff_files)
    if self.funny_files:
        self.funny_files.sort()
        print('Trouble with common files :', self.funny_files)
    if self.common_dirs:
        self.common_dirs.sort()
        print('Common subdirectories :', self.common_dirs)
    if self.common_funny:
        self.common_funny.sort()
        print('Common funny cases :', self.common_funny)

def report_full_closure(self):
    self.report()
    for sd in self.subdirs.values():
        print()
        sd.report_full_closure()

def __getattr__(self, attr):
    if attr not in self.methodmap:
        raise AttributeError(attr)
    self.methodmap[attr](self)
    return getattr(self, attr)

def nextfile():
    """Close the current file so that the next iteration will read the first
    line from the next file (if any); lines not read from the file will
    not count towards the cumulative line count. The filename is not
    changed until after the first line of the next file has been read.
    Before the first line has been read, this function has no effect;
    it cannot be used to skip the first file. After the last line of the
    last file has been read, this function has no effect."""
    if not _state:
        raise RuntimeError('no active input()')
    return _state.nextfile()

def filename():
    """Return the name of the file currently being read.
    Before the first line has been read, returns None."""
    if not _state:
        raise RuntimeError('no active input()')
    return _state.filename()

def lineno():
    """Return the cumulative line number of the line that has just been read.
    Before the first line has been read, returns 0. After the last line
    of the last file has been read, returns the line number of that line."""
    if not _state:
        raise RuntimeError('no active input()')
    return _state.lineno()

def filelineno():
    """Return the line number in the current file. Before the first line
    has been read, returns 0. After the last line of the last file has
    been read, returns the line number of that line within the file."""
    if not _state:
        raise RuntimeError('no active input()')
    return _state.filelineno()

def fileno():
    """Return the file number of the current file. When no file is currently
    opened, returns -1."""
    if not _state:
        raise RuntimeError('no active input()')
    return _state.fileno()

def isfirstline():
    """Returns true the line just read is the first line of its file,
    otherwise returns false."""
    if not _state:
        raise RuntimeError('no active input()')
    return _state.isfirstline()

def isstdin():
    """Returns true if the last line was read from sys.stdin,
    otherwise returns false."""
    if not _state:
        raise RuntimeError('no active input()')
    return _state.isstdin()

def hook_compressed(filename, mode, *, encoding=None, errors=None):
    if encoding is None and 'b' not in mode:
        encoding = 'locale'
    ext = os.path.splitext(filename)[1]
    if ext == '.gz':
        import gzip
        stream = gzip.open(filename, mode)
    elif ext == '.bz2':
        import bz2
        stream = bz2.BZ2File(filename, mode)
    else:
        return open(filename, mode, encoding=encoding, errors=errors)
    if 'b' not in mode:
        stream = io.TextIOWrapper(stream, encoding=encoding, errors=errors)
    return stream

def hook_encoded(encoding, errors=None):
    def openhook(filename, mode):
        return open(filename, mode, encoding=encoding, errors=errors)
    return openhook

def _test():
    import getopt
    inplace = False
    backup = False
    opts, args = getopt.getopt(sys.argv[1:], 'ib:')
    for o, a in opts:
        if o == '-i':
            inplace = True
        if o == '-b':
            backup = a
    for line in input(args, inplace=inplace, backup=backup):
        if line[-1:] == '\n':
            line = line[:-1]
        if line[-1:] == '\r':
            line = line[:-1]
        print('%d: %s[%d]%s %s' % (lineno(), filename(), filelineno(), isfirstline() and '*' or '', line))
    print('%d: %s[%d]' % (lineno(), filename(), filelineno()))

def __init__(self, files=None, inplace=False, backup='', *, mode='r', openhook=None, encoding=None, errors=None):
    if isinstance(files, str):
        files = (files,)
    elif isinstance(files, os.PathLike):
        files = (os.fspath(files),)
    else:
        if files is None:
            files = sys.argv[1:]
        if not files:
            files = ('-',)
        else:
            files = tuple(files)
    self._files = files
    self._inplace = inplace
    self._backup = backup
    self._savestdout = None
    self._output = None
    self._filename = None
    self._startlineno = 0
    self._filelineno = 0
    self._file = None
    self._isstdin = False
    self._backupfilename = None
    self._encoding = encoding
    self._errors = errors
    if sys.flags.warn_default_encoding and 'b' not in mode and (encoding is None) and (openhook is None):
        import warnings
        warnings.warn("'encoding' argument not specified.", EncodingWarning, 2)
    if mode not in ('r', 'rb'):
        raise ValueError("FileInput opening mode must be 'r' or 'rb'")
    self._mode = mode
    self._write_mode = mode.replace('r', 'w')
    if openhook:
        if inplace:
            raise ValueError('FileInput cannot use an opening hook in inplace mode')
        if not callable(openhook):
            raise ValueError('FileInput openhook must be callable')
    self._openhook = openhook

def close(self):
    try:
        self.nextfile()
    finally:
        self._files = ()

def __next__(self):
    while True:
        line = self._readline()
        if line:
            self._filelineno += 1
            return line
        if not self._file:
            raise StopIteration
        self.nextfile()

def nextfile(self):
    savestdout = self._savestdout
    self._savestdout = None
    if savestdout:
        sys.stdout = savestdout
    output = self._output
    self._output = None
    try:
        if output:
            output.close()
    finally:
        file = self._file
        self._file = None
        try:
            del self._readline
        except AttributeError:
            pass
        try:
            if file and (not self._isstdin):
                file.close()
        finally:
            backupfilename = self._backupfilename
            self._backupfilename = None
            if backupfilename and (not self._backup):
                try:
                    os.unlink(backupfilename)
                except OSError:
                    pass
            self._isstdin = False

def readline(self):
    while True:
        line = self._readline()
        if line:
            self._filelineno += 1
            return line
        if not self._file:
            return line
        self.nextfile()

def fileno(self):
    if self._file:
        try:
            return self._file.fileno()
        except ValueError:
            return -1
    else:
        return -1

@functools.lru_cache(maxsize=32768, typed=True)
def _compile_pattern(pat):
    if isinstance(pat, bytes):
        pat_str = str(pat, 'ISO-8859-1')
        res_str = translate(pat_str)
        res = bytes(res_str, 'ISO-8859-1')
    else:
        res = translate(pat)
    return re.compile(res).match

@functools.lru_cache(maxsize=1 << 14)
def _hash_algorithm(numerator, denominator):
    try:
        dinv = pow(denominator, -1, _PyHASH_MODULUS)
    except ValueError:
        hash_ = _PyHASH_INF
    else:
        hash_ = hash(hash(abs(numerator)) * dinv)
    result = hash_ if numerator >= 0 else -hash_
    return -2 if result == -1 else result

@classmethod
def from_float(cls, f):
    """Converts a finite float to a rational number, exactly.

    Beware that Fraction.from_float(0.3) != Fraction(3, 10)."""
    if isinstance(f, numbers.Integral):
        return cls(f)
    elif not isinstance(f, float):
        raise TypeError('%s.from_float() only takes floats, not %r (%s)' % (cls.__name__, f, type(f).__name__))
    return cls._from_coprime_ints(*f.as_integer_ratio())

@classmethod
def from_decimal(cls, dec):
    """Converts a finite Decimal instance to a rational number, exactly."""
    from decimal import Decimal
    if isinstance(dec, numbers.Integral):
        dec = Decimal(int(dec))
    elif not isinstance(dec, Decimal):
        raise TypeError('%s.from_decimal() only takes Decimals, not %r (%s)' % (cls.__name__, dec, type(dec).__name__))
    return cls._from_coprime_ints(*dec.as_integer_ratio())

def as_integer_ratio(self):
    """Return a pair of integers, whose ratio is equal to the original Fraction.

    The ratio is in lowest terms and has a positive denominator."""
    return (self._numerator, self._denominator)

def limit_denominator(self, max_denominator=1000000):
    """Closest Fraction to self with denominator at most max_denominator.

    >>> Fraction('3.141592653589793').limit_denominator(10)
    Fraction(22, 7)
    >>> Fraction('3.141592653589793').limit_denominator(100)
    Fraction(311, 99)
    >>> Fraction(4321, 8765).limit_denominator(10000)
    Fraction(4321, 8765)"""
    if max_denominator < 1:
        raise ValueError('max_denominator should be at least 1')
    if self._denominator <= max_denominator:
        return Fraction(self)
    p0, q0, p1, q1 = (0, 1, 1, 0)
    n, d = (self._numerator, self._denominator)
    while True:
        a = n // d
        q2 = q0 + a * q1
        if q2 > max_denominator:
            break
        p0, q0, p1, q1 = (p1, q1, p0 + a * p1, q2)
        n, d = (d, n - a * d)
    k = (max_denominator - q0) // q1
    if 2 * d * (q0 + k * q1) <= self._denominator:
        return Fraction._from_coprime_ints(p1, q1)
    else:
        return Fraction._from_coprime_ints(p0 + k * p1, q0 + k * q1)

@property
def numerator(a):
    return a._numerator

@property
def denominator(a):
    return a._denominator

def __repr__(self):
    """repr(self)"""
    return '%s(%s, %s)' % (self.__class__.__name__, self._numerator, self._denominator)

def __str__(self):
    """str(self)"""
    if self._denominator == 1:
        return str(self._numerator)
    else:
        return '%s/%s' % (self._numerator, self._denominator)

def _add(a, b):
    """a + b"""
    na, da = (a._numerator, a._denominator)
    nb, db = (b._numerator, b._denominator)
    g = math.gcd(da, db)
    if g == 1:
        return Fraction._from_coprime_ints(na * db + da * nb, da * db)
    s = da // g
    t = na * (db // g) + nb * s
    g2 = math.gcd(t, g)
    if g2 == 1:
        return Fraction._from_coprime_ints(t, s * db)
    return Fraction._from_coprime_ints(t // g2, s * (db // g2))

def _sub(a, b):
    """a - b"""
    na, da = (a._numerator, a._denominator)
    nb, db = (b._numerator, b._denominator)
    g = math.gcd(da, db)
    if g == 1:
        return Fraction._from_coprime_ints(na * db - da * nb, da * db)
    s = da // g
    t = na * (db // g) - nb * s
    g2 = math.gcd(t, g)
    if g2 == 1:
        return Fraction._from_coprime_ints(t, s * db)
    return Fraction._from_coprime_ints(t // g2, s * (db // g2))

def _mul(a, b):
    """a * b"""
    na, da = (a._numerator, a._denominator)
    nb, db = (b._numerator, b._denominator)
    g1 = math.gcd(na, db)
    if g1 > 1:
        na //= g1
        db //= g1
    g2 = math.gcd(nb, da)
    if g2 > 1:
        nb //= g2
        da //= g2
    return Fraction._from_coprime_ints(na * nb, db * da)

def _div(a, b):
    """a / b"""
    nb, db = (b._numerator, b._denominator)
    if nb == 0:
        raise ZeroDivisionError('Fraction(%s, 0)' % db)
    na, da = (a._numerator, a._denominator)
    g1 = math.gcd(na, nb)
    if g1 > 1:
        na //= g1
        nb //= g1
    g2 = math.gcd(db, da)
    if g2 > 1:
        da //= g2
        db //= g2
    n, d = (na * db, nb * da)
    if d < 0:
        n, d = (-n, -d)
    return Fraction._from_coprime_ints(n, d)

def _floordiv(a, b):
    """a // b"""
    return a.numerator * b.denominator // (a.denominator * b.numerator)

def _divmod(a, b):
    """(a // b, a % b)"""
    da, db = (a.denominator, b.denominator)
    div, n_mod = divmod(a.numerator * db, da * b.numerator)
    return (div, Fraction(n_mod, da * db))

def _mod(a, b):
    """a % b"""
    da, db = (a.denominator, b.denominator)
    return Fraction(a.numerator * db % (b.numerator * da), da * db)

def __pow__(a, b):
    """a ** b

    If b is not an integer, the result will be a float or complex
    since roots are generally irrational. If b is an integer, the
    result will be rational."""
    if isinstance(b, numbers.Rational):
        if b.denominator == 1:
            power = b.numerator
            if power >= 0:
                return Fraction._from_coprime_ints(a._numerator ** power, a._denominator ** power)
            elif a._numerator > 0:
                return Fraction._from_coprime_ints(a._denominator ** (-power), a._numerator ** (-power))
            elif a._numerator == 0:
                raise ZeroDivisionError('Fraction(%s, 0)' % a._denominator ** (-power))
            else:
                return Fraction._from_coprime_ints((-a._denominator) ** (-power), (-a._numerator) ** (-power))
        else:
            return float(a) ** float(b)
    elif isinstance(b, (float, complex)):
        return float(a) ** b
    else:
        return NotImplemented

def __rpow__(b, a):
    """a ** b"""
    if b._denominator == 1 and b._numerator >= 0:
        return a ** b._numerator
    if isinstance(a, numbers.Rational):
        return Fraction(a.numerator, a.denominator) ** b
    if b._denominator == 1:
        return a ** b._numerator
    return a ** float(b)

def __pos__(a):
    """+a: Coerces a subclass instance to Fraction"""
    return Fraction._from_coprime_ints(a._numerator, a._denominator)

def __neg__(a):
    """-a"""
    return Fraction._from_coprime_ints(-a._numerator, a._denominator)

def __abs__(a):
    """abs(a)"""
    return Fraction._from_coprime_ints(abs(a._numerator), a._denominator)

def __int__(a, _index=operator.index):
    """int(a)"""
    if a._numerator < 0:
        return _index(-(-a._numerator // a._denominator))
    else:
        return _index(a._numerator // a._denominator)

def __trunc__(a):
    """math.trunc(a)"""
    if a._numerator < 0:
        return -(-a._numerator // a._denominator)
    else:
        return a._numerator // a._denominator

def __floor__(a):
    """math.floor(a)"""
    return a._numerator // a._denominator

def __ceil__(a):
    """math.ceil(a)"""
    return -(-a._numerator // a._denominator)

def __round__(self, ndigits=None):
    """round(self, ndigits)

    Rounds half toward even."""
    if ndigits is None:
        d = self._denominator
        floor, remainder = divmod(self._numerator, d)
        if remainder * 2 < d:
            return floor
        elif remainder * 2 > d:
            return floor + 1
        elif floor % 2 == 0:
            return floor
        else:
            return floor + 1
    shift = 10 ** abs(ndigits)
    if ndigits > 0:
        return Fraction(round(self * shift), shift)
    else:
        return Fraction(round(self / shift) * shift)

def __hash__(self):
    """hash(self)"""
    return _hash_algorithm(self._numerator, self._denominator)

def __eq__(a, b):
    """a == b"""
    if type(b) is int:
        return a._numerator == b and a._denominator == 1
    if isinstance(b, numbers.Rational):
        return a._numerator == b.numerator and a._denominator == b.denominator
    if isinstance(b, numbers.Complex) and b.imag == 0:
        b = b.real
    if isinstance(b, float):
        if math.isnan(b) or math.isinf(b):
            return 0.0 == b
        else:
            return a == a.from_float(b)
    else:
        return NotImplemented

def _richcmp(self, other, op):
    """Helper for comparison operators, for internal use only.

    Implement comparison between a Rational instance `self`, and
    either another Rational instance or a float `other`.  If
    `other` is not a Rational instance or a float, return
    NotImplemented. `op` should be one of the six standard
    comparison operators."""
    if isinstance(other, numbers.Rational):
        return op(self._numerator * other.denominator, self._denominator * other.numerator)
    if isinstance(other, float):
        if math.isnan(other) or math.isinf(other):
            return op(0.0, other)
        else:
            return op(self, self.from_float(other))
    else:
        return NotImplemented

def __lt__(a, b):
    """a < b"""
    return a._richcmp(b, operator.lt)

def __gt__(a, b):
    """a > b"""
    return a._richcmp(b, operator.gt)

def __le__(a, b):
    """a <= b"""
    return a._richcmp(b, operator.le)

def __ge__(a, b):
    """a >= b"""
    return a._richcmp(b, operator.ge)

def __bool__(a):
    """a != 0"""
    return bool(a._numerator)

def __copy__(self):
    if type(self) == Fraction:
        return self
    return self.__class__(self._numerator, self._denominator)

def __deepcopy__(self, memo):
    if type(self) == Fraction:
        return self
    return self.__class__(self._numerator, self._denominator)

def forward(a, b):
    if isinstance(b, Fraction):
        return monomorphic_operator(a, b)
    elif isinstance(b, int):
        return monomorphic_operator(a, Fraction(b))
    elif isinstance(b, float):
        return fallback_operator(float(a), b)
    elif isinstance(b, complex):
        return fallback_operator(complex(a), b)
    else:
        return NotImplemented

def reverse(b, a):
    if isinstance(a, numbers.Rational):
        return monomorphic_operator(Fraction(a), b)
    elif isinstance(a, numbers.Real):
        return fallback_operator(float(a), float(b))
    elif isinstance(a, numbers.Complex):
        return fallback_operator(complex(a), complex(b))
    else:
        return NotImplemented

def parse150(resp):
    """Parse the '150' response for a RETR request.
    Returns the expected transfer size or None; size is not guaranteed to
    be present in the 150 message."""
    if resp[:3] != '150':
        raise error_reply(resp)
    global _150_re
    if _150_re is None:
        import re
        _150_re = re.compile('150 .* \\((\\d+) bytes\\)', re.IGNORECASE | re.ASCII)
    m = _150_re.match(resp)
    if not m:
        return None
    return int(m.group(1))

def parse229(resp, peer):
    """Parse the '229' response for an EPSV request.
    Raises error_proto if it does not contain '(|||port|)'
    Return ('host.addr.as.numbers', port#) tuple."""
    if resp[:3] != '229':
        raise error_reply(resp)
    left = resp.find('(')
    if left < 0:
        raise error_proto(resp)
    right = resp.find(')', left + 1)
    if right < 0:
        raise error_proto(resp)
    if resp[left + 1] != resp[right - 1]:
        raise error_proto(resp)
    parts = resp[left + 1:right].split(resp[left + 1])
    if len(parts) != 5:
        raise error_proto(resp)
    host = peer[0]
    port = int(parts[3])
    return (host, port)

def parse257(resp):
    """Parse the '257' response for a MKD or PWD request.
    This is a response to a MKD or PWD request: a directory name.
    Returns the directoryname in the 257 reply."""
    if resp[:3] != '257':
        raise error_reply(resp)
    if resp[3:5] != ' "':
        return ''
    dirname = ''
    i = 5
    n = len(resp)
    while i < n:
        c = resp[i]
        i = i + 1
        if c == '"':
            if i >= n or resp[i] != '"':
                break
            i = i + 1
        dirname = dirname + c
    return dirname

def print_line(line):
    """Default retrlines callback to print a line."""
    print(line)

def getwelcome(self):
    """Get the welcome message from the server.
    (this is read and squirreled away by connect())"""
    if self.debugging:
        print('*welcome*', self.sanitize(self.welcome))
    return self.welcome

def sanitize(self, s):
    if s[:5] in {'pass ', 'PASS '}:
        i = len(s.rstrip('\r\n'))
        s = s[:5] + '*' * (i - 5) + s[i:]
    return repr(s)

def putcmd(self, line):
    if self.debugging:
        print('*cmd*', self.sanitize(line))
    self.putline(line)

def getline(self):
    line = self.file.readline(self.maxline + 1)
    if len(line) > self.maxline:
        raise Error('got more than %d bytes' % self.maxline)
    if self.debugging > 1:
        print('*get*', self.sanitize(line))
    if not line:
        raise EOFError
    if line[-2:] == CRLF:
        line = line[:-2]
    elif line[-1:] in CRLF:
        line = line[:-1]
    return line

def getmultiline(self):
    line = self.getline()
    if line[3:4] == '-':
        code = line[:3]
        while 1:
            nextline = self.getline()
            line = line + ('\n' + nextline)
            if nextline[:3] == code and nextline[3:4] != '-':
                break
    return line

def getresp(self):
    resp = self.getmultiline()
    if self.debugging:
        print('*resp*', self.sanitize(resp))
    self.lastresp = resp[:3]
    c = resp[:1]
    if c in {'1', '2', '3'}:
        return resp
    if c == '4':
        raise error_temp(resp)
    if c == '5':
        raise error_perm(resp)
    raise error_proto(resp)

def voidresp(self):
    """Expect a response beginning with '2'."""
    resp = self.getresp()
    if resp[:1] != '2':
        raise error_reply(resp)
    return resp

def sendcmd(self, cmd):
    """Send a command and return the response."""
    self.putcmd(cmd)
    return self.getresp()

def voidcmd(self, cmd):
    """Send a command and expect a response beginning with '2'."""
    self.putcmd(cmd)
    return self.voidresp()

def sendeprt(self, host, port):
    """Send an EPRT command with the current host and the given port number."""
    af = 0
    if self.af == socket.AF_INET:
        af = 1
    if self.af == socket.AF_INET6:
        af = 2
    if af == 0:
        raise error_proto('unsupported address family')
    fields = ['', repr(af), host, repr(port), '']
    cmd = 'EPRT ' + '|'.join(fields)
    return self.voidcmd(cmd)

def makeport(self):
    """Create a new socket and send a PORT command for it."""
    sock = socket.create_server(('', 0), family=self.af, backlog=1)
    port = sock.getsockname()[1]
    host = self.sock.getsockname()[0]
    if self.af == socket.AF_INET:
        resp = self.sendport(host, port)
    else:
        resp = self.sendeprt(host, port)
    if self.timeout is not _GLOBAL_DEFAULT_TIMEOUT:
        sock.settimeout(self.timeout)
    return sock

def makepasv(self):
    """Internal: Does the PASV or EPSV handshake -> (address, port)"""
    if self.af == socket.AF_INET:
        untrusted_host, port = parse227(self.sendcmd('PASV'))
        if self.trust_server_pasv_ipv4_address:
            host = untrusted_host
        else:
            host = self.sock.getpeername()[0]
    else:
        host, port = parse229(self.sendcmd('EPSV'), self.sock.getpeername())
    return (host, port)

def transfercmd(self, cmd, rest=None):
    """Like ntransfercmd() but returns only the socket."""
    return self.ntransfercmd(cmd, rest)[0]

def login(self, user='', passwd='', acct=''):
    """Login, default anonymous."""
    if not user:
        user = 'anonymous'
    if not passwd:
        passwd = ''
    if not acct:
        acct = ''
    if user == 'anonymous' and passwd in {'', '-'}:
        passwd = passwd + 'anonymous@'
    resp = self.sendcmd('USER ' + user)
    if resp[0] == '3':
        resp = self.sendcmd('PASS ' + passwd)
    if resp[0] == '3':
        resp = self.sendcmd('ACCT ' + acct)
    if resp[0] != '2':
        raise error_reply(resp)
    return resp

def retrlines(self, cmd, callback=None):
    """Retrieve data in line mode.  A new port is created for you.

    Args:
      cmd: A RETR, LIST, or NLST command.
      callback: An optional single parameter callable that is called
                for each line with the trailing CRLF stripped.
                [default: print_line()]

    Returns:
      The response code."""
    if callback is None:
        callback = print_line
    resp = self.sendcmd('TYPE A')
    with self.transfercmd(cmd) as conn, conn.makefile('r', encoding=self.encoding) as fp:
        while 1:
            line = fp.readline(self.maxline + 1)
            if len(line) > self.maxline:
                raise Error('got more than %d bytes' % self.maxline)
            if self.debugging > 2:
                print('*retr*', repr(line))
            if not line:
                break
            if line[-2:] == CRLF:
                line = line[:-2]
            elif line[-1:] == '\n':
                line = line[:-1]
            callback(line)
        if _SSLSocket is not None and isinstance(conn, _SSLSocket):
            conn.unwrap()
    return self.voidresp()

def storlines(self, cmd, fp, callback=None):
    """Store a file in line mode.  A new port is created for you.

    Args:
      cmd: A STOR command.
      fp: A file-like object with a readline() method.
      callback: An optional single parameter callable that is called on
                each line after it is sent.  [default: None]

    Returns:
      The response code."""
    self.voidcmd('TYPE A')
    with self.transfercmd(cmd) as conn:
        while 1:
            buf = fp.readline(self.maxline + 1)
            if len(buf) > self.maxline:
                raise Error('got more than %d bytes' % self.maxline)
            if not buf:
                break
            if buf[-2:] != B_CRLF:
                if buf[-1] in B_CRLF:
                    buf = buf[:-1]
                buf = buf + B_CRLF
            conn.sendall(buf)
            if callback:
                callback(buf)
        if _SSLSocket is not None and isinstance(conn, _SSLSocket):
            conn.unwrap()
    return self.voidresp()

def acct(self, password):
    """Send new account name."""
    cmd = 'ACCT ' + password
    return self.voidcmd(cmd)

def rename(self, fromname, toname):
    """Rename a file."""
    resp = self.sendcmd('RNFR ' + fromname)
    if resp[0] != '3':
        raise error_reply(resp)
    return self.voidcmd('RNTO ' + toname)

def delete(self, filename):
    """Delete a file."""
    resp = self.sendcmd('DELE ' + filename)
    if resp[:3] in {'250', '200'}:
        return resp
    else:
        raise error_reply(resp)

def cwd(self, dirname):
    """Change to a directory."""
    if dirname == '..':
        try:
            return self.voidcmd('CDUP')
        except error_perm as msg:
            if msg.args[0][:3] != '500':
                raise
    elif dirname == '':
        dirname = '.'
    cmd = 'CWD ' + dirname
    return self.voidcmd(cmd)

def size(self, filename):
    """Retrieve the size of a file."""
    resp = self.sendcmd('SIZE ' + filename)
    if resp[:3] == '213':
        s = resp[3:].strip()
        return int(s)

def mkd(self, dirname):
    """Make a directory, return its full pathname."""
    resp = self.voidcmd('MKD ' + dirname)
    if not resp.startswith('257'):
        return ''
    return parse257(resp)

def rmd(self, dirname):
    """Remove a directory."""
    return self.voidcmd('RMD ' + dirname)

def pwd(self):
    """Return current working directory."""
    resp = self.voidcmd('PWD')
    if not resp.startswith('257'):
        return ''
    return parse257(resp)

def close(self):
    """Close the connection without assuming anything about it."""
    try:
        file = self.file
        self.file = None
        if file is not None:
            file.close()
    finally:
        sock = self.sock
        self.sock = None
        if sock is not None:
            sock.close()

def __init__(self, host='', user='', passwd='', acct='', *, context=None, timeout=_GLOBAL_DEFAULT_TIMEOUT, source_address=None, encoding='utf-8'):
    if context is None:
        context = ssl._create_stdlib_context()
    self.context = context
    self._prot_p = False
    super().__init__(host, user, passwd, acct, timeout, source_address, encoding=encoding)

def login(self, user='', passwd='', acct='', secure=True):
    if secure and (not isinstance(self.sock, ssl.SSLSocket)):
        self.auth()
    return super().login(user, passwd, acct)

def auth(self):
    """Set up secure control connection by using TLS/SSL."""
    if isinstance(self.sock, ssl.SSLSocket):
        raise ValueError('Already using TLS')
    if self.context.protocol >= ssl.PROTOCOL_TLS:
        resp = self.voidcmd('AUTH TLS')
    else:
        resp = self.voidcmd('AUTH SSL')
    self.sock = self.context.wrap_socket(self.sock, server_hostname=self.host)
    self.file = self.sock.makefile(mode='r', encoding=self.encoding)
    return resp

def ntransfercmd(self, cmd, rest=None):
    conn, size = super().ntransfercmd(cmd, rest)
    if self._prot_p:
        conn = self.context.wrap_socket(conn, server_hostname=self.host)
    return (conn, size)

def _gt_from_lt(self, other):
    """Return a > b.  Computed by @total_ordering from (not a < b) and (a != b)."""
    op_result = type(self).__lt__(self, other)
    if op_result is NotImplemented:
        return op_result
    return not op_result and self != other

def _le_from_lt(self, other):
    """Return a <= b.  Computed by @total_ordering from (a < b) or (a == b)."""
    op_result = type(self).__lt__(self, other)
    if op_result is NotImplemented:
        return op_result
    return op_result or self == other

