def total_ordering(cls):
    """Class decorator that fills in missing ordering methods"""
    roots = {op for op in _convert if getattr(cls, op, None) is not getattr(object, op, None)}
    if not roots:
        raise ValueError('must define at least one ordering operation: < > <= >=')
    root = max(roots)
    for opname, opfunc in _convert[root]:
        if opname not in roots:
            opfunc.__name__ = opname
            setattr(cls, opname, opfunc)
    return cls

def cmp_to_key(mycmp):
    """Convert a cmp= function into a key= function"""
    class K(object):
        __slots__ = ['obj']
        def __init__(self, obj):
            self.obj = obj
        def __lt__(self, other):
            return mycmp(self.obj, other.obj) < 0
        def __gt__(self, other):
            return mycmp(self.obj, other.obj) > 0
        def __eq__(self, other):
            return mycmp(self.obj, other.obj) == 0
        def __le__(self, other):
            return mycmp(self.obj, other.obj) <= 0
        def __ge__(self, other):
            return mycmp(self.obj, other.obj) >= 0
        __hash__ = None
    return K

def reduce(function, sequence, initial=_initial_missing):
    """reduce(function, iterable[, initial]) -> value

    Apply a function of two arguments cumulatively to the items of an iterable, from left to right.

    This effectively reduces the iterable to a single value.  If initial is present,
    it is placed before the items of the iterable in the calculation, and serves as
    a default when the iterable is empty.

    For example, reduce(lambda x, y: x+y, [1, 2, 3, 4, 5])
    calculates ((((1 + 2) + 3) + 4) + 5)."""
    it = iter(sequence)
    if initial is _initial_missing:
        try:
            value = next(it)
        except StopIteration:
            raise TypeError('reduce() of empty iterable with no initial value') from None
    else:
        value = initial
    for element in it:
        value = function(value, element)
    return value

def _make_key(args, kwds, typed, kwd_mark=(object(),), fasttypes={int, str}, tuple=tuple, type=type, len=len):
    """Make a cache key from optionally typed positional and keyword arguments

    The key is constructed in a way that is flat as possible rather than
    as a nested structure that would take more memory.

    If there is only a single argument and its data type is known to cache
    its hash value, then that argument is returned without a wrapper.  This
    saves space and improves lookup speed."""
    key = args
    if kwds:
        key += kwd_mark
        for item in kwds.items():
            key += item
    if typed:
        key += tuple((type(v) for v in args))
        if kwds:
            key += tuple((type(v) for v in kwds.values()))
    elif len(key) == 1 and type(key[0]) in fasttypes:
        return key[0]
    return _HashedSeq(key)

def lru_cache(maxsize=128, typed=False):
    """Least-recently-used cache decorator.

    If *maxsize* is set to None, the LRU features are disabled and the cache
    can grow without bound.

    If *typed* is True, arguments of different types will be cached separately.
    For example, f(3.0) and f(3) will be treated as distinct calls with
    distinct results.

    Arguments to the cached function must be hashable.

    View the cache statistics named tuple (hits, misses, maxsize, currsize)
    with f.cache_info().  Clear the cache and statistics with f.cache_clear().
    Access the underlying function with f.__wrapped__.

    See:  https://en.wikipedia.org/wiki/Cache_replacement_policies#Least_recently_used_(LRU)"""
    if isinstance(maxsize, int):
        if maxsize < 0:
            maxsize = 0
    elif callable(maxsize) and isinstance(typed, bool):
        user_function, maxsize = (maxsize, 128)
        wrapper = _lru_cache_wrapper(user_function, maxsize, typed, _CacheInfo)
        wrapper.cache_parameters = lambda: {'maxsize': maxsize, 'typed': typed}
        return update_wrapper(wrapper, user_function)
    elif maxsize is not None:
        raise TypeError('Expected first argument to be an integer, a callable, or None')
    def decorating_function(user_function):
        wrapper = _lru_cache_wrapper(user_function, maxsize, typed, _CacheInfo)
        wrapper.cache_parameters = lambda: {'maxsize': maxsize, 'typed': typed}
        return update_wrapper(wrapper, user_function)
    return decorating_function

def cache(user_function, /):
    """Simple lightweight unbounded cache.  Sometimes called "memoize"."""
    return lru_cache(maxsize=None)(user_function)

def _c3_merge(sequences):
    """Merges MROs in *sequences* to a single MRO using the C3 algorithm.

    Adapted from https://docs.python.org/3/howto/mro.html."""
    result = []
    while True:
        sequences = [s for s in sequences if s]
        if not sequences:
            return result
        for s1 in sequences:
            candidate = s1[0]
            for s2 in sequences:
                if candidate in s2[1:]:
                    candidate = None
                    break
            else:
                break
        if candidate is None:
            raise RuntimeError('Inconsistent hierarchy')
        result.append(candidate)
        for seq in sequences:
            if seq[0] == candidate:
                del seq[0]

def _compose_mro(cls, types):
    """Calculates the method resolution order for a given class *cls*.

    Includes relevant abstract base classes (with their respective bases) from
    the *types* iterable. Uses a modified C3 linearization algorithm."""
    bases = set(cls.__mro__)
    def is_related(typ):
        return typ not in bases and hasattr(typ, '__mro__') and (not isinstance(typ, GenericAlias)) and issubclass(cls, typ)
    types = [n for n in types if is_related(n)]
    def is_strict_base(typ):
        for other in types:
            if typ != other and typ in other.__mro__:
                return True
        return False
    types = [n for n in types if not is_strict_base(n)]
    type_set = set(types)
    mro = []
    for typ in types:
        found = []
        for sub in typ.__subclasses__():
            if sub not in bases and issubclass(cls, sub):
                found.append([s for s in sub.__mro__ if s in type_set])
        if not found:
            mro.append(typ)
            continue
        found.sort(key=len, reverse=True)
        for sub in found:
            for subcls in sub:
                if subcls not in mro:
                    mro.append(subcls)
    return _c3_mro(cls, abcs=mro)

def _find_impl(cls, registry):
    """Returns the best matching implementation from *registry* for type *cls*.

    Where there is no registered implementation for a specific type, its method
    resolution order is used to find a more generic implementation.

    Note: if *registry* does not contain an implementation for the base
    *object* type, this function may return None."""
    mro = _compose_mro(cls, registry.keys())
    match = None
    for t in mro:
        if match is not None:
            if t in registry and t not in cls.__mro__ and (match not in cls.__mro__) and (not issubclass(match, t)):
                raise RuntimeError('Ambiguous dispatch: {} or {}'.format(match, t))
            break
        if t in registry:
            match = t
    return registry.get(match)

def __new__(cls, func, /, *args, **keywords):
    if not callable(func):
        raise TypeError('the first argument must be callable')
    if hasattr(func, 'func'):
        args = func.args + args
        keywords = {**func.keywords, **keywords}
        func = func.func
    self = super(partial, cls).__new__(cls)
    self.func = func
    self.args = args
    self.keywords = keywords
    return self

def __call__(self, /, *args, **keywords):
    keywords = {**self.keywords, **keywords}
    return self.func(*self.args, *args, **keywords)

@recursive_repr()
def __repr__(self):
    qualname = type(self).__qualname__
    args = [repr(self.func)]
    args.extend((repr(x) for x in self.args))
    args.extend((f'{k}={v!r}' for k, v in self.keywords.items()))
    if type(self).__module__ == 'functools':
        return f"functools.{qualname}({', '.join(args)})"
    return f"{qualname}({', '.join(args)})"

def __setstate__(self, state):
    if not isinstance(state, tuple):
        raise TypeError('argument to __setstate__ must be a tuple')
    if len(state) != 4:
        raise TypeError(f'expected 4 items in state, got {len(state)}')
    func, args, kwds, namespace = state
    if not callable(func) or not isinstance(args, tuple) or (kwds is not None and (not isinstance(kwds, dict))) or (namespace is not None and (not isinstance(namespace, dict))):
        raise TypeError('invalid partial state')
    args = tuple(args)
    if kwds is None:
        kwds = {}
    elif type(kwds) is not dict:
        kwds = dict(kwds)
    if namespace is None:
        namespace = {}
    self.__dict__ = namespace
    self.func = func
    self.args = args
    self.keywords = kwds

def __init__(self, func, /, *args, **keywords):
    if not callable(func) and (not hasattr(func, '__get__')):
        raise TypeError('{!r} is not callable or a descriptor'.format(func))
    if isinstance(func, partialmethod):
        self.func = func.func
        self.args = func.args + args
        self.keywords = {**func.keywords, **keywords}
    else:
        self.func = func
        self.args = args
        self.keywords = keywords

def _make_unbound_method(self):
    def _method(cls_or_self, /, *args, **keywords):
        keywords = {**self.keywords, **keywords}
        return self.func(cls_or_self, *self.args, *args, **keywords)
    _method.__isabstractmethod__ = self.__isabstractmethod__
    _method._partialmethod = self
    return _method

def __get__(self, obj, cls=None):
    get = getattr(self.func, '__get__', None)
    result = None
    if get is not None:
        new_func = get(obj, cls)
        if new_func is not self.func:
            result = partial(new_func, *self.args, **self.keywords)
            try:
                result.__self__ = new_func.__self__
            except AttributeError:
                pass
    if result is None:
        result = self._make_unbound_method().__get__(obj, cls)
    return result

@property
def __isabstractmethod__(self):
    return getattr(self.func, '__isabstractmethod__', False)

def decorating_function(user_function):
    wrapper = _lru_cache_wrapper(user_function, maxsize, typed, _CacheInfo)
    wrapper.cache_parameters = lambda: {'maxsize': maxsize, 'typed': typed}
    return update_wrapper(wrapper, user_function)

def cache_info():
    """Report cache statistics"""
    with lock:
        return _CacheInfo(hits, misses, maxsize, cache_len())

def is_strict_base(typ):
    for other in types:
        if typ != other and typ in other.__mro__:
            return True
    return False

def dispatch(cls):
    """generic_func.dispatch(cls) -> <function implementation>

    Runs the dispatch algorithm to return the best available implementation
    for the given *cls* registered on *generic_func*."""
    nonlocal cache_token
    if cache_token is not None:
        current_token = get_cache_token()
        if cache_token != current_token:
            dispatch_cache.clear()
            cache_token = current_token
    try:
        impl = dispatch_cache[cls]
    except KeyError:
        try:
            impl = registry[cls]
        except KeyError:
            impl = _find_impl(cls, registry)
        dispatch_cache[cls] = impl
    return impl

def _is_union_type(cls):
    from typing import get_origin, Union
    return get_origin(cls) in {Union, types.UnionType}

def _is_valid_dispatch_type(cls):
    if isinstance(cls, type):
        return True
    from typing import get_args
    return _is_union_type(cls) and all((isinstance(arg, type) for arg in get_args(cls)))

def register(cls, func=None):
    """generic_func.register(cls, func) -> func

    Registers a new implementation for the given *cls* on a *generic_func*."""
    nonlocal cache_token
    if _is_valid_dispatch_type(cls):
        if func is None:
            return lambda f: register(cls, f)
    else:
        if func is not None:
            raise TypeError(f'Invalid first argument to `register()`. {cls!r} is not a class or union type.')
        ann = getattr(cls, '__annotations__', {})
        if not ann:
            raise TypeError(f'Invalid first argument to `register()`: {cls!r}. Use either `@register(some_class)` or plain `@register` on an annotated function.')
        func = cls
        from typing import get_type_hints
        argname, cls = next(iter(get_type_hints(func).items()))
        if not _is_valid_dispatch_type(cls):
            if _is_union_type(cls):
                raise TypeError(f'Invalid annotation for {argname!r}. {cls!r} not all arguments are classes.')
            else:
                raise TypeError(f'Invalid annotation for {argname!r}. {cls!r} is not a class.')
    if _is_union_type(cls):
        from typing import get_args
        for arg in get_args(cls):
            registry[arg] = func
    else:
        registry[cls] = func
    if cache_token is None and hasattr(cls, '__abstractmethods__'):
        cache_token = get_cache_token()
    dispatch_cache.clear()
    return func

def wrapper(*args, **kw):
    if not args:
        raise TypeError(f'{funcname} requires at least 1 positional argument')
    return dispatch(args[0].__class__)(*args, **kw)

def __init__(self, func):
    if not callable(func) and (not hasattr(func, '__get__')):
        raise TypeError(f'{func!r} is not callable or a descriptor')
    self.dispatcher = singledispatch(func)
    self.func = func

def register(self, cls, method=None):
    """generic_method.register(cls, func) -> func

    Registers a new implementation for the given *cls* on a *generic_method*."""
    return self.dispatcher.register(cls, func=method)

def __get__(self, obj, cls=None):
    def _method(*args, **kwargs):
        method = self.dispatcher.dispatch(args[0].__class__)
        return method.__get__(obj, cls)(*args, **kwargs)
    _method.__isabstractmethod__ = self.__isabstractmethod__
    _method.register = self.register
    update_wrapper(_method, self.func)
    return _method

def __set_name__(self, owner, name):
    if self.attrname is None:
        self.attrname = name
    elif name != self.attrname:
        raise TypeError(f'Cannot assign the same cached_property to two different names ({self.attrname!r} and {name!r}).')

def __get__(self, instance, owner=None):
    if instance is None:
        return self
    if self.attrname is None:
        raise TypeError('Cannot use cached_property instance without calling __set_name__ on it.')
    try:
        cache = instance.__dict__
    except AttributeError:
        msg = f"No '__dict__' attribute on {type(instance).__name__!r} instance to cache {self.attrname!r} property."
        raise TypeError(msg) from None
    val = cache.get(self.attrname, _NOT_FOUND)
    if val is _NOT_FOUND:
        val = self.func(instance)
        try:
            cache[self.attrname] = val
        except TypeError:
            msg = f"The '__dict__' attribute on {type(instance).__name__!r} instance does not support item assignment for caching {self.attrname!r} property."
            raise TypeError(msg) from None
    return val

def _method(cls_or_self, /, *args, **keywords):
    keywords = {**self.keywords, **keywords}
    return self.func(cls_or_self, *self.args, *args, **keywords)

def _method(*args, **kwargs):
    method = self.dispatcher.dispatch(args[0].__class__)
    return method.__get__(obj, cls)(*args, **kwargs)

def exists(path):
    """Test whether a path exists.  Returns False for broken symbolic links"""
    try:
        os.stat(path)
    except (OSError, ValueError):
        return False
    return True

def isfile(path):
    """Test whether a path is a regular file"""
    try:
        st = os.stat(path)
    except (OSError, ValueError):
        return False
    return stat.S_ISREG(st.st_mode)

def isdir(s):
    """Return true if the pathname refers to an existing directory."""
    try:
        st = os.stat(s)
    except (OSError, ValueError):
        return False
    return stat.S_ISDIR(st.st_mode)

def islink(path):
    """Test whether a path is a symbolic link"""
    try:
        st = os.lstat(path)
    except (OSError, ValueError, AttributeError):
        return False
    return stat.S_ISLNK(st.st_mode)

def getsize(filename):
    """Return the size of a file, reported by os.stat()."""
    return os.stat(filename).st_size

def getmtime(filename):
    """Return the last modification time of a file, reported by os.stat()."""
    return os.stat(filename).st_mtime

def getatime(filename):
    """Return the last access time of a file, reported by os.stat()."""
    return os.stat(filename).st_atime

def getctime(filename):
    """Return the metadata change time of a file, reported by os.stat()."""
    return os.stat(filename).st_ctime

def commonprefix(m):
    """Given a list of pathnames, returns the longest common leading component"""
    if not m:
        return ''
    if not isinstance(m[0], (list, tuple)):
        m = tuple(map(os.fspath, m))
    s1 = min(m)
    s2 = max(m)
    for i, c in enumerate(s1):
        if c != s2[i]:
            return s1[:i]
    return s1

def samestat(s1, s2):
    """Test whether two stat buffers reference the same file"""
    return s1.st_ino == s2.st_ino and s1.st_dev == s2.st_dev

def sameopenfile(fp1, fp2):
    """Test whether two open file objects reference the same file"""
    s1 = os.fstat(fp1)
    s2 = os.fstat(fp2)
    return samestat(s1, s2)

def _splitext(p, sep, altsep, extsep):
    """Split the extension from a pathname.

    Extension is everything from the last dot to the end, ignoring
    leading dots.  Returns "(root, ext)"; ext may be empty."""
    sepIndex = p.rfind(sep)
    if altsep:
        altsepIndex = p.rfind(altsep)
        sepIndex = max(sepIndex, altsepIndex)
    dotIndex = p.rfind(extsep)
    if dotIndex > sepIndex:
        filenameIndex = sepIndex + 1
        while filenameIndex < dotIndex:
            if p[filenameIndex:filenameIndex + 1] != extsep:
                return (p[:dotIndex], p[dotIndex:])
            filenameIndex += 1
    return (p, p[:0])

def _check_arg_types(funcname, *args):
    hasstr = hasbytes = False
    for s in args:
        if isinstance(s, str):
            hasstr = True
        elif isinstance(s, bytes):
            hasbytes = True
        else:
            raise TypeError(f'{funcname}() argument must be str, bytes, or os.PathLike object, not {s.__class__.__name__!r}') from None
    if hasstr and hasbytes:
        raise TypeError("Can't mix strings and bytes in path components") from None

def gnu_getopt(args, shortopts, longopts=[]):
    """getopt(args, options[, long_options]) -> opts, args

    This function works like getopt(), except that GNU style scanning
    mode is used by default. This means that option and non-option
    arguments may be intermixed. The getopt() function stops
    processing options as soon as a non-option argument is
    encountered.

    If the first character of the option string is `+', or if the
    environment variable POSIXLY_CORRECT is set, then option
    processing stops as soon as a non-option argument is encountered."""
    opts = []
    prog_args = []
    if isinstance(longopts, str):
        longopts = [longopts]
    else:
        longopts = list(longopts)
    if shortopts.startswith('+'):
        shortopts = shortopts[1:]
        all_options_first = True
    elif os.environ.get('POSIXLY_CORRECT'):
        all_options_first = True
    else:
        all_options_first = False
    while args:
        if args[0] == '--':
            prog_args += args[1:]
            break
        if args[0][:2] == '--':
            opts, args = do_longs(opts, args[0][2:], longopts, args[1:])
        elif args[0][:1] == '-' and args[0] != '-':
            opts, args = do_shorts(opts, args[0][1:], shortopts, args[1:])
        elif all_options_first:
            prog_args += args
            break
        else:
            prog_args.append(args[0])
            args = args[1:]
    return (opts, prog_args)

def do_longs(opts, opt, longopts, args):
    try:
        i = opt.index('=')
    except ValueError:
        optarg = None
    else:
        opt, optarg = (opt[:i], opt[i + 1:])
    has_arg, opt = long_has_args(opt, longopts)
    if has_arg:
        if optarg is None:
            if not args:
                raise GetoptError(_('option --%s requires argument') % opt, opt)
            optarg, args = (args[0], args[1:])
    elif optarg is not None:
        raise GetoptError(_('option --%s must not have an argument') % opt, opt)
    opts.append(('--' + opt, optarg or ''))
    return (opts, args)

def long_has_args(opt, longopts):
    possibilities = [o for o in longopts if o.startswith(opt)]
    if not possibilities:
        raise GetoptError(_('option --%s not recognized') % opt, opt)
    if opt in possibilities:
        return (False, opt)
    elif opt + '=' in possibilities:
        return (True, opt)
    if len(possibilities) > 1:
        raise GetoptError(_('option --%s not a unique prefix') % opt, opt)
    assert len(possibilities) == 1
    unique_match = possibilities[0]
    has_arg = unique_match.endswith('=')
    if has_arg:
        unique_match = unique_match[:-1]
    return (has_arg, unique_match)

def do_shorts(opts, optstring, shortopts, args):
    while optstring != '':
        opt, optstring = (optstring[0], optstring[1:])
        if short_has_arg(opt, shortopts):
            if optstring == '':
                if not args:
                    raise GetoptError(_('option -%s requires argument') % opt, opt)
                optstring, args = (args[0], args[1:])
            optarg, optstring = (optstring, '')
        else:
            optarg = ''
        opts.append(('-' + opt, optarg))
    return (opts, args)

def short_has_arg(opt, shortopts):
    for i in range(len(shortopts)):
        if opt == shortopts[i] != ':':
            return shortopts.startswith(':', i + 1)
    raise GetoptError(_('option -%s not recognized') % opt, opt)

def win_getpass(prompt='Password: ', stream=None):
    """Prompt for password with echo off, using Windows getwch()."""
    if sys.stdin is not sys.__stdin__:
        return fallback_getpass(prompt, stream)
    for c in prompt:
        msvcrt.putwch(c)
    pw = ''
    while 1:
        c = msvcrt.getwch()
        if c == '\r' or c == '\n':
            break
        if c == '\x03':
            raise KeyboardInterrupt
        if c == '\x08':
            pw = pw[:-1]
        else:
            pw = pw + c
    msvcrt.putwch('\r')
    msvcrt.putwch('\n')
    return pw

def fallback_getpass(prompt='Password: ', stream=None):
    warnings.warn('Can not control echo on the terminal.', GetPassWarning, stacklevel=2)
    if not stream:
        stream = sys.stderr
    print('Warning: Password input may be echoed.', file=stream)
    return _raw_input(prompt, stream)

def _raw_input(prompt='', stream=None, input=None):
    if not stream:
        stream = sys.stderr
    if not input:
        input = sys.stdin
    prompt = str(prompt)
    if prompt:
        try:
            stream.write(prompt)
        except UnicodeEncodeError:
            prompt = prompt.encode(stream.encoding, 'replace')
            prompt = prompt.decode(stream.encoding)
            stream.write(prompt)
        stream.flush()
    line = input.readline()
    if not line:
        raise EOFError
    if line[-1] == '\n':
        line = line[:-1]
    return line

def getuser():
    """Get the username from the environment or password database.

    First try various environment variables, then the password
    database.  This works on Windows as long as USERNAME is set."""
    for name in ('LOGNAME', 'USER', 'LNAME', 'USERNAME'):
        user = os.environ.get(name)
        if user:
            return user
    import pwd
    return pwd.getpwuid(os.getuid())[0]

def _tokenize(plural):
    for mo in re.finditer(_token_pattern, plural):
        kind = mo.lastgroup
        if kind == 'WHITESPACES':
            continue
        value = mo.group(kind)
        if kind == 'INVALID':
            raise ValueError('invalid token in plural form: %s' % value)
        yield value
    yield ''

def _error(value):
    if value:
        return ValueError('unexpected token in plural form: %s' % value)
    else:
        return ValueError('unexpected end of plural form')

def _as_int(n):
    try:
        round(n)
    except TypeError:
        raise TypeError('Plural value must be an integer, got %s' % (n.__class__.__name__,)) from None
    import warnings
    frame = sys._getframe(1)
    stacklevel = 2
    while frame.f_back is not None and frame.f_globals.get('__name__') == __name__:
        stacklevel += 1
        frame = frame.f_back
    warnings.warn('Plural value must be an integer, got %s' % (n.__class__.__name__,), DeprecationWarning, stacklevel)
    return n

def c2py(plural):
    """Gets a C expression as used in PO files for plural forms and returns a
    Python function that implements an equivalent expression."""
    if len(plural) > 1000:
        raise ValueError('plural form expression is too long')
    try:
        result, nexttok = _parse(_tokenize(plural))
        if nexttok:
            raise _error(nexttok)
        depth = 0
        for c in result:
            if c == '(':
                depth += 1
                if depth > 20:
                    raise ValueError('plural form expression is too complex')
            elif c == ')':
                depth -= 1
        ns = {'_as_int': _as_int, '__name__': __name__}
        exec('if True:\n            def func(n):\n                if not isinstance(n, int):\n                    n = _as_int(n)\n                return int(%s)\n            ' % result, ns)
        return ns['func']
    except RecursionError:
        raise ValueError('plural form expression is too complex')

def find(domain, localedir=None, languages=None, all=False):
    if localedir is None:
        localedir = _default_localedir
    if languages is None:
        languages = []
        for envar in ('LANGUAGE', 'LC_ALL', 'LC_MESSAGES', 'LANG'):
            val = os.environ.get(envar)
            if val:
                languages = val.split(':')
                break
        if 'C' not in languages:
            languages.append('C')
    nelangs = []
    for lang in languages:
        for nelang in _expand_lang(lang):
            if nelang not in nelangs:
                nelangs.append(nelang)
    if all:
        result = []
    else:
        result = None
    for lang in nelangs:
        if lang == 'C':
            break
        mofile = os.path.join(localedir, lang, 'LC_MESSAGES', '%s.mo' % domain)
        if os.path.exists(mofile):
            if all:
                result.append(mofile)
            else:
                return mofile
    return result

def translation(domain, localedir=None, languages=None, class_=None, fallback=False):
    if class_ is None:
        class_ = GNUTranslations
    mofiles = find(domain, localedir, languages, all=True)
    if not mofiles:
        if fallback:
            return NullTranslations()
        from errno import ENOENT
        raise FileNotFoundError(ENOENT, 'No translation file found for domain', domain)
    result = None
    for mofile in mofiles:
        key = (class_, os.path.abspath(mofile))
        t = _translations.get(key)
        if t is None:
            with open(mofile, 'rb') as fp:
                t = _translations.setdefault(key, class_(fp))
        import copy
        t = copy.copy(t)
        if result is None:
            result = t
        else:
            result.add_fallback(t)
    return result

def install(domain, localedir=None, *, names=None):
    t = translation(domain, localedir, fallback=True)
    t.install(names)

def textdomain(domain=None):
    global _current_domain
    if domain is not None:
        _current_domain = domain
    return _current_domain

def bindtextdomain(domain, localedir=None):
    global _localedirs
    if localedir is not None:
        _localedirs[domain] = localedir
    return _localedirs.get(domain, _default_localedir)

def dgettext(domain, message):
    try:
        t = translation(domain, _localedirs.get(domain, None))
    except OSError:
        return message
    return t.gettext(message)

def dngettext(domain, msgid1, msgid2, n):
    try:
        t = translation(domain, _localedirs.get(domain, None))
    except OSError:
        if n == 1:
            return msgid1
        else:
            return msgid2
    return t.ngettext(msgid1, msgid2, n)

def dpgettext(domain, context, message):
    try:
        t = translation(domain, _localedirs.get(domain, None))
    except OSError:
        return message
    return t.pgettext(context, message)

def dnpgettext(domain, context, msgid1, msgid2, n):
    try:
        t = translation(domain, _localedirs.get(domain, None))
    except OSError:
        if n == 1:
            return msgid1
        else:
            return msgid2
    return t.npgettext(context, msgid1, msgid2, n)

def __init__(self, fp=None):
    self._info = {}
    self._charset = None
    self._fallback = None
    if fp is not None:
        self._parse(fp)

def add_fallback(self, fallback):
    if self._fallback:
        self._fallback.add_fallback(fallback)
    else:
        self._fallback = fallback

def gettext(self, message):
    if self._fallback:
        return self._fallback.gettext(message)
    return message

def pgettext(self, context, message):
    if self._fallback:
        return self._fallback.pgettext(context, message)
    return message

def npgettext(self, context, msgid1, msgid2, n):
    if self._fallback:
        return self._fallback.npgettext(context, msgid1, msgid2, n)
    if n == 1:
        return msgid1
    else:
        return msgid2

def install(self, names=None):
    import builtins
    builtins.__dict__['_'] = self.gettext
    if names is not None:
        allowed = {'gettext', 'ngettext', 'npgettext', 'pgettext'}
        for name in allowed & set(names):
            builtins.__dict__[name] = getattr(self, name)

def _get_versions(self, version):
    """Returns a tuple of major version, minor version"""
    return (version >> 16, version & 65535)

def gettext(self, message):
    missing = object()
    tmsg = self._catalog.get(message, missing)
    if tmsg is missing:
        tmsg = self._catalog.get((message, self.plural(1)), missing)
    if tmsg is not missing:
        return tmsg
    if self._fallback:
        return self._fallback.gettext(message)
    return message

def ngettext(self, msgid1, msgid2, n):
    try:
        tmsg = self._catalog[msgid1, self.plural(n)]
    except KeyError:
        if self._fallback:
            return self._fallback.ngettext(msgid1, msgid2, n)
        if n == 1:
            tmsg = msgid1
        else:
            tmsg = msgid2
    return tmsg

def pgettext(self, context, message):
    ctxt_msg_id = self.CONTEXT % (context, message)
    missing = object()
    tmsg = self._catalog.get(ctxt_msg_id, missing)
    if tmsg is missing:
        tmsg = self._catalog.get((ctxt_msg_id, self.plural(1)), missing)
    if tmsg is not missing:
        return tmsg
    if self._fallback:
        return self._fallback.pgettext(context, message)
    return message

def npgettext(self, context, msgid1, msgid2, n):
    ctxt_msg_id = self.CONTEXT % (context, msgid1)
    try:
        tmsg = self._catalog[ctxt_msg_id, self.plural(n)]
    except KeyError:
        if self._fallback:
            return self._fallback.npgettext(context, msgid1, msgid2, n)
        if n == 1:
            tmsg = msgid1
        else:
            tmsg = msgid2
    return tmsg

def iglob(pathname, *, root_dir=None, dir_fd=None, recursive=False, include_hidden=False):
    """Return an iterator which yields the paths matching a pathname pattern.

    The pattern may contain simple shell-style wildcards a la
    fnmatch. However, unlike fnmatch, filenames starting with a
    dot are special cases that are not matched by '*' and '?'
    patterns.

    If recursive is true, the pattern '**' will match any files and
    zero or more directories and subdirectories."""
    sys.audit('glob.glob', pathname, recursive)
    sys.audit('glob.glob/2', pathname, recursive, root_dir, dir_fd)
    if root_dir is not None:
        root_dir = os.fspath(root_dir)
    else:
        root_dir = pathname[:0]
    it = _iglob(pathname, root_dir, dir_fd, recursive, False, include_hidden=include_hidden)
    if not pathname or (recursive and _isrecursive(pathname[:2])):
        try:
            s = next(it)
            if s:
                it = itertools.chain((s,), it)
        except StopIteration:
            pass
    return it

def _iglob(pathname, root_dir, dir_fd, recursive, dironly, include_hidden=False):
    dirname, basename = os.path.split(pathname)
    if not has_magic(pathname):
        assert not dironly
        if basename:
            if _lexists(_join(root_dir, pathname), dir_fd):
                yield pathname
        elif _isdir(_join(root_dir, dirname), dir_fd):
            yield pathname
        return
    if not dirname:
        if recursive and _isrecursive(basename):
            yield from _glob2(root_dir, basename, dir_fd, dironly, include_hidden=include_hidden)
        else:
            yield from _glob1(root_dir, basename, dir_fd, dironly, include_hidden=include_hidden)
        return
    if dirname != pathname and has_magic(dirname):
        dirs = _iglob(dirname, root_dir, dir_fd, recursive, True, include_hidden=include_hidden)
    else:
        dirs = [dirname]
    if has_magic(basename):
        if recursive and _isrecursive(basename):
            glob_in_dir = _glob2
        else:
            glob_in_dir = _glob1
    else:
        glob_in_dir = _glob0
    for dirname in dirs:
        for name in glob_in_dir(_join(root_dir, dirname), basename, dir_fd, dironly, include_hidden=include_hidden):
            yield os.path.join(dirname, name)

def _glob1(dirname, pattern, dir_fd, dironly, include_hidden=False):
    names = _listdir(dirname, dir_fd, dironly)
    if include_hidden or not _ishidden(pattern):
        names = (x for x in names if include_hidden or not _ishidden(x))
    return fnmatch.filter(names, pattern)

def _glob0(dirname, basename, dir_fd, dironly, include_hidden=False):
    if basename:
        if _lexists(_join(dirname, basename), dir_fd):
            return [basename]
    elif _isdir(dirname, dir_fd):
        return [basename]
    return []

def _glob2(dirname, pattern, dir_fd, dironly, include_hidden=False):
    assert _isrecursive(pattern)
    if not dirname or _isdir(dirname, dir_fd):
        yield pattern[:0]
    yield from _rlistdir(dirname, dir_fd, dironly, include_hidden=include_hidden)

def _iterdir(dirname, dir_fd, dironly):
    try:
        fd = None
        fsencode = None
        if dir_fd is not None:
            if dirname:
                fd = arg = os.open(dirname, _dir_open_flags, dir_fd=dir_fd)
            else:
                arg = dir_fd
            if isinstance(dirname, bytes):
                fsencode = os.fsencode
        elif dirname:
            arg = dirname
        elif isinstance(dirname, bytes):
            arg = bytes(os.curdir, 'ASCII')
        else:
            arg = os.curdir
        try:
            with os.scandir(arg) as it:
                for entry in it:
                    try:
                        if not dironly or entry.is_dir():
                            if fsencode is not None:
                                yield fsencode(entry.name)
                            else:
                                yield entry.name
                    except OSError:
                        pass
        finally:
            if fd is not None:
                os.close(fd)
    except OSError:
        return

def _listdir(dirname, dir_fd, dironly):
    with contextlib.closing(_iterdir(dirname, dir_fd, dironly)) as it:
        return list(it)

def _rlistdir(dirname, dir_fd, dironly, include_hidden=False):
    names = _listdir(dirname, dir_fd, dironly)
    for x in names:
        if include_hidden or not _ishidden(x):
            yield x
            path = _join(dirname, x) if dirname else x
            for y in _rlistdir(path, dir_fd, dironly, include_hidden=include_hidden):
                yield _join(x, y)

def _lexists(pathname, dir_fd):
    if dir_fd is None:
        return os.path.lexists(pathname)
    try:
        os.lstat(pathname, dir_fd=dir_fd)
    except (OSError, ValueError):
        return False
    else:
        return True

def _isdir(pathname, dir_fd):
    if dir_fd is None:
        return os.path.isdir(pathname)
    try:
        st = os.stat(pathname, dir_fd=dir_fd)
    except (OSError, ValueError):
        return False
    else:
        return stat.S_ISDIR(st.st_mode)

def _join(dirname, basename):
    if not dirname or not basename:
        return dirname or basename
    return os.path.join(dirname, basename)

def has_magic(s):
    if isinstance(s, bytes):
        match = magic_check_bytes.search(s)
    else:
        match = magic_check.search(s)
    return match is not None

def _isrecursive(pattern):
    if isinstance(pattern, bytes):
        return pattern == b'**'
    else:
        return pattern == '**'

def escape(pathname):
    """Escape all special characters.
    """
    drive, pathname = os.path.splitdrive(pathname)
    if isinstance(pathname, bytes):
        pathname = magic_check_bytes.sub(b'[\\1]', pathname)
    else:
        pathname = magic_check.sub('[\\1]', pathname)
    return drive + pathname

def __init__(self, graph=None):
    self._node2info = {}
    self._ready_nodes = None
    self._npassedout = 0
    self._nfinished = 0
    if graph is not None:
        for node, predecessors in graph.items():
            self.add(node, *predecessors)

def _get_nodeinfo(self, node):
    if (result := self._node2info.get(node)) is None:
        self._node2info[node] = result = _NodeInfo(node)
    return result

def is_active(self):
    """Return ``True`` if more progress can be made and ``False`` otherwise.

    Progress can be made if cycles do not block the resolution and either there
    are still nodes ready that haven't yet been returned by "get_ready" or the
    number of nodes marked "done" is less than the number that have been returned
    by "get_ready".

    Raises ValueError if called without calling "prepare" previously."""
    if self._ready_nodes is None:
        raise ValueError('prepare() must be called first')
    return self._nfinished < self._npassedout or bool(self._ready_nodes)

def done(self, *nodes):
    """Marks a set of nodes returned by "get_ready" as processed.

    This method unblocks any successor of each node in *nodes* for being returned
    in the future by a call to "get_ready".

    Raises ValueError if any node in *nodes* has already been marked as
    processed by a previous call to this method, if a node was not added to the
    graph by using "add" or if called without calling "prepare" previously or if
    node has not yet been returned by "get_ready"."""
    if self._ready_nodes is None:
        raise ValueError('prepare() must be called first')
    n2i = self._node2info
    for node in nodes:
        if (nodeinfo := n2i.get(node)) is None:
            raise ValueError(f'node {node!r} was not added using add()')
        stat = nodeinfo.npredecessors
        if stat != _NODE_OUT:
            if stat >= 0:
                raise ValueError(f'node {node!r} was not passed out (still not ready)')
            elif stat == _NODE_DONE:
                raise ValueError(f'node {node!r} was already marked done')
            else:
                assert False, f'node {node!r}: unknown status {stat}'
        nodeinfo.npredecessors = _NODE_DONE
        for successor in nodeinfo.successors:
            successor_info = n2i[successor]
            successor_info.npredecessors -= 1
            if successor_info.npredecessors == 0:
                self._ready_nodes.append(successor)
        self._nfinished += 1

def _find_cycle(self):
    n2i = self._node2info
    stack = []
    itstack = []
    seen = set()
    node2stacki = {}
    for node in n2i:
        if node in seen:
            continue
        while True:
            if node in seen:
                if node in node2stacki:
                    return stack[node2stacki[node]:] + [node]
            else:
                seen.add(node)
                itstack.append(iter(n2i[node].successors).__next__)
                node2stacki[node] = len(stack)
                stack.append(node)
            while stack:
                try:
                    node = itstack[-1]()
                    break
                except StopIteration:
                    del node2stacki[stack.pop()]
                    itstack.pop()
            else:
                break
    return None

def _read_gzip_header(fp):
    """Read a gzip header from `fp` and progress to the end of the header.

    Returns last mtime if header was present or None otherwise."""
    magic = fp.read(2)
    if magic == b'':
        return None
    if magic != b'\x1f\x8b':
        raise BadGzipFile('Not a gzipped file (%r)' % magic)
    method, flag, last_mtime = struct.unpack('<BBIxx', _read_exact(fp, 8))
    if method != 8:
        raise BadGzipFile('Unknown compression method')
    if flag & FEXTRA:
        extra_len, = struct.unpack('<H', _read_exact(fp, 2))
        _read_exact(fp, extra_len)
    if flag & FNAME:
        while True:
            s = fp.read(1)
            if not s or s == b'\x00':
                break
    if flag & FCOMMENT:
        while True:
            s = fp.read(1)
            if not s or s == b'\x00':
                break
    if flag & FHCRC:
        _read_exact(fp, 2)
    return last_mtime

def _create_simple_gzip_header(compresslevel: int, mtime=None) -> bytes:
    """Write a simple gzip header with no extra fields.
    :param compresslevel: Compresslevel used to determine the xfl bytes.
    :param mtime: The mtime (must support conversion to a 32-bit integer).
    :return: A bytes object representing the gzip header."""
    if mtime is None:
        mtime = time.time()
    if compresslevel == _COMPRESS_LEVEL_BEST:
        xfl = 2
    elif compresslevel == _COMPRESS_LEVEL_FAST:
        xfl = 4
    else:
        xfl = 0
    return struct.pack('<BBBBLBB', 31, 139, 8, 0, int(mtime), xfl, 255)

def compress(data, compresslevel=_COMPRESS_LEVEL_BEST, *, mtime=None):
    """Compress data in one shot and return the compressed string.

    compresslevel sets the compression level in range of 0-9.
    mtime can be used to set the modification time. The modification time is
    set to the current time by default."""
    if mtime == 0:
        return zlib.compress(data, level=compresslevel, wbits=31)
    header = _create_simple_gzip_header(compresslevel, mtime)
    trailer = struct.pack('<LL', zlib.crc32(data), len(data) & 4294967295)
    return header + zlib.compress(data, level=compresslevel, wbits=-15) + trailer

def decompress(data):
    """Decompress a gzip compressed string in one shot.
    Return the decompressed string."""
    decompressed_members = []
    while True:
        fp = io.BytesIO(data)
        if _read_gzip_header(fp) is None:
            return b''.join(decompressed_members)
        do = zlib.decompressobj(wbits=-zlib.MAX_WBITS)
        decompressed = do.decompress(data[fp.tell():])
        if not do.eof or len(do.unused_data) < 8:
            raise EOFError('Compressed file ended before the end-of-stream marker was reached')
        crc, length = struct.unpack('<II', do.unused_data[:8])
        if crc != zlib.crc32(decompressed):
            raise BadGzipFile('CRC check failed')
        if length != len(decompressed) & 4294967295:
            raise BadGzipFile('Incorrect length of data produced')
        decompressed_members.append(decompressed)
        data = do.unused_data[8:].lstrip(b'\x00')

def main():
    from argparse import ArgumentParser
    parser = ArgumentParser(description='A simple command line interface for the gzip module: act like gzip, but do not delete the input file.')
    group = parser.add_mutually_exclusive_group()
    group.add_argument('--fast', action='store_true', help='compress faster')
    group.add_argument('--best', action='store_true', help='compress better')
    group.add_argument('-d', '--decompress', action='store_true', help='act like gunzip instead of gzip')
    parser.add_argument('args', nargs='*', default=['-'], metavar='file')
    args = parser.parse_args()
    compresslevel = _COMPRESS_LEVEL_TRADEOFF
    if args.fast:
        compresslevel = _COMPRESS_LEVEL_FAST
    elif args.best:
        compresslevel = _COMPRESS_LEVEL_BEST
    for arg in args.args:
        if args.decompress:
            if arg == '-':
                f = GzipFile(filename='', mode='rb', fileobj=sys.stdin.buffer)
                g = sys.stdout.buffer
            else:
                if arg[-3:] != '.gz':
                    sys.exit(f"filename doesn't end in .gz: {arg!r}")
                f = open(arg, 'rb')
                g = builtins.open(arg[:-3], 'wb')
        elif arg == '-':
            f = sys.stdin.buffer
            g = GzipFile(filename='', mode='wb', fileobj=sys.stdout.buffer, compresslevel=compresslevel)
        else:
            f = builtins.open(arg, 'rb')
            g = open(arg + '.gz', 'wb')
        while True:
            chunk = f.read(READ_BUFFER_SIZE)
            if not chunk:
                break
            g.write(chunk)
        if g is not sys.stdout.buffer:
            g.close()
        if f is not sys.stdin.buffer:
            f.close()

def read(self, size):
    if self._read is None:
        return self.file.read(size)
    if self._read + size <= self._length:
        read = self._read
        self._read += size
        return self._buffer[read:self._read]
    else:
        read = self._read
        self._read = None
        return self._buffer[read:] + self.file.read(size - self._length + read)

def prepend(self, prepend=b''):
    if self._read is None:
        self._buffer = prepend
    else:
        self._read -= len(prepend)
        return
    self._length = len(self._buffer)
    self._read = 0

def seek(self, off):
    self._read = None
    self._buffer = None
    return self.file.seek(off)

def write(self, data):
    gzip_file = self.gzip_file()
    if gzip_file is None:
        raise RuntimeError('lost gzip_file')
    return gzip_file._write_raw(data)

def __repr__(self):
    s = repr(self.fileobj)
    return '<gzip ' + s[1:-1] + ' ' + hex(id(self)) + '>'

def tell(self):
    self._check_not_closed()
    self._buffer.flush()
    return super().tell()

def _write_gzip_header(self, compresslevel):
    self.fileobj.write(b'\x1f\x8b')
    self.fileobj.write(b'\x08')
    try:
        fname = os.path.basename(self.name)
        if not isinstance(fname, bytes):
            fname = fname.encode('latin-1')
        if fname.endswith(b'.gz'):
            fname = fname[:-3]
    except UnicodeEncodeError:
        fname = b''
    flags = 0
    if fname:
        flags = FNAME
    self.fileobj.write(chr(flags).encode('latin-1'))
    mtime = self._write_mtime
    if mtime is None:
        mtime = time.time()
    write32u(self.fileobj, int(mtime))
    if compresslevel == _COMPRESS_LEVEL_BEST:
        xfl = b'\x02'
    elif compresslevel == _COMPRESS_LEVEL_FAST:
        xfl = b'\x04'
    else:
        xfl = b'\x00'
    self.fileobj.write(xfl)
    self.fileobj.write(b'\xff')
    if fname:
        self.fileobj.write(fname + b'\x00')

def write(self, data):
    self._check_not_closed()
    if self.mode != WRITE:
        import errno
        raise OSError(errno.EBADF, 'write() on read-only GzipFile object')
    if self.fileobj is None:
        raise ValueError('write() on closed GzipFile object')
    return self._buffer.write(data)

def _write_raw(self, data):
    if isinstance(data, (bytes, bytearray)):
        length = len(data)
    else:
        data = memoryview(data)
        length = data.nbytes
    if length > 0:
        self.fileobj.write(self.compress.compress(data))
        self.size += length
        self.crc = zlib.crc32(data, self.crc)
        self.offset += length
    return length

def read(self, size=-1):
    self._check_not_closed()
    if self.mode != READ:
        import errno
        raise OSError(errno.EBADF, 'read() on write-only GzipFile object')
    return self._buffer.read(size)

def read1(self, size=-1):
    """Implements BufferedIOBase.read1()

    Reads up to a buffer's worth of data if size is negative."""
    self._check_not_closed()
    if self.mode != READ:
        import errno
        raise OSError(errno.EBADF, 'read1() on write-only GzipFile object')
    if size < 0:
        size = io.DEFAULT_BUFFER_SIZE
    return self._buffer.read1(size)

def peek(self, n):
    self._check_not_closed()
    if self.mode != READ:
        import errno
        raise OSError(errno.EBADF, 'peek() on write-only GzipFile object')
    return self._buffer.peek(n)

@property
def closed(self):
    return self.fileobj is None

def close(self):
    fileobj = self.fileobj
    if fileobj is None:
        return
    try:
        if self.mode == WRITE:
            self._buffer.flush()
            fileobj.write(self.compress.flush())
            write32u(fileobj, self.crc)
            write32u(fileobj, self.size & 4294967295)
        elif self.mode == READ:
            self._buffer.close()
    finally:
        self._close()

def _close(self):
    self.fileobj = None
    myfileobj = self.myfileobj
    if myfileobj is not None:
        self.myfileobj = None
        myfileobj.close()

def flush(self, zlib_mode=zlib.Z_SYNC_FLUSH):
    self._check_not_closed()
    if self.mode == WRITE:
        self._buffer.flush()
        self.fileobj.write(self.compress.flush(zlib_mode))
        self.fileobj.flush()

def fileno(self):
    """Invoke the underlying file object's fileno() method.

    This will raise AttributeError if the underlying file object
    doesn't support fileno()."""
    return self.fileobj.fileno()

def rewind(self):
    """Return the uncompressed stream file position indicator to the
    beginning of the file"""
    if self.mode != READ:
        raise OSError("Can't rewind in write mode")
    self._buffer.seek(0)

def seek(self, offset, whence=io.SEEK_SET):
    if self.mode == WRITE:
        self._check_not_closed()
        self._buffer.flush()
        if whence != io.SEEK_SET:
            if whence == io.SEEK_CUR:
                offset = self.offset + offset
            else:
                raise ValueError('Seek from end not supported')
        if offset < self.offset:
            raise OSError('Negative seek in write mode')
        count = offset - self.offset
        chunk = b'\x00' * self._buffer_size
        for i in range(count // self._buffer_size):
            self.write(chunk)
        self.write(b'\x00' * (count % self._buffer_size))
    elif self.mode == READ:
        self._check_not_closed()
        return self._buffer.seek(offset, whence)
    return self.offset

def readline(self, size=-1):
    self._check_not_closed()
    return self._buffer.readline(size)

def _read_gzip_header(self):
    last_mtime = _read_gzip_header(self._fp)
    if last_mtime is None:
        return False
    self._last_mtime = last_mtime
    return True

def read(self, size=-1):
    if size < 0:
        return self.readall()
    if not size:
        return b''
    while True:
        if self._decompressor.eof:
            self._read_eof()
            self._new_member = True
            self._decompressor = self._decomp_factory(**self._decomp_args)
        if self._new_member:
            self._init_read()
            if not self._read_gzip_header():
                self._size = self._pos
                return b''
            self._new_member = False
        if self._decompressor.needs_input:
            buf = self._fp.read(READ_BUFFER_SIZE)
            uncompress = self._decompressor.decompress(buf, size)
        else:
            uncompress = self._decompressor.decompress(b'', size)
        if self._decompressor.unused_data != b'':
            self._fp.prepend(self._decompressor.unused_data)
        if uncompress != b'':
            break
        if buf == b'':
            raise EOFError('Compressed file ended before the end-of-stream marker was reached')
    self._crc = zlib.crc32(uncompress, self._crc)
    self._stream_size += len(uncompress)
    self._pos += len(uncompress)
    return uncompress

def _read_eof(self):
    crc32, isize = struct.unpack('<II', _read_exact(self._fp, 8))
    if crc32 != self._crc:
        raise BadGzipFile('CRC check failed %s != %s' % (hex(crc32), hex(self._crc)))
    elif isize != self._stream_size & 4294967295:
        raise BadGzipFile('Incorrect length of data produced')
    c = b'\x00'
    while c == b'\x00':
        c = self._fp.read(1)
    if c:
        self._fp.prepend(c)

def _rewind(self):
    super()._rewind()
    self._new_member = True

def __get_builtin_constructor(name):
    cache = __builtin_constructor_cache
    constructor = cache.get(name)
    if constructor is not None:
        return constructor
    try:
        if name in {'SHA1', 'sha1'}:
            import _sha1
            cache['SHA1'] = cache['sha1'] = _sha1.sha1
        elif name in {'MD5', 'md5'}:
            import _md5
            cache['MD5'] = cache['md5'] = _md5.md5
        elif name in {'SHA256', 'sha256', 'SHA224', 'sha224'}:
            import _sha2
            cache['SHA224'] = cache['sha224'] = _sha2.sha224
            cache['SHA256'] = cache['sha256'] = _sha2.sha256
        elif name in {'SHA512', 'sha512', 'SHA384', 'sha384'}:
            import _sha2
            cache['SHA384'] = cache['sha384'] = _sha2.sha384
            cache['SHA512'] = cache['sha512'] = _sha2.sha512
        elif name in {'blake2b', 'blake2s'}:
            import _blake2
            cache['blake2b'] = _blake2.blake2b
            cache['blake2s'] = _blake2.blake2s
        elif name in {'sha3_224', 'sha3_256', 'sha3_384', 'sha3_512'}:
            import _sha3
            cache['sha3_224'] = _sha3.sha3_224
            cache['sha3_256'] = _sha3.sha3_256
            cache['sha3_384'] = _sha3.sha3_384
            cache['sha3_512'] = _sha3.sha3_512
        elif name in {'shake_128', 'shake_256'}:
            import _sha3
            cache['shake_128'] = _sha3.shake_128
            cache['shake_256'] = _sha3.shake_256
    except ImportError:
        pass
    constructor = cache.get(name)
    if constructor is not None:
        return constructor
    raise ValueError('unsupported hash type ' + name)

def __get_openssl_constructor(name):
    if name in __block_openssl_constructor:
        return __get_builtin_constructor(name)
    try:
        f = getattr(_hashlib, 'openssl_' + name)
        f(usedforsecurity=False)
        return f
    except (AttributeError, ValueError):
        return __get_builtin_constructor(name)

def __py_new(name, data=b'', **kwargs):
    """new(name, data=b'', **kwargs) - Return a new hashing object using the
    named algorithm; optionally initialized with data (which must be
    a bytes-like object)."""
    return __get_builtin_constructor(name)(data, **kwargs)

def heappushpop(heap, item):
    """Fast version of a heappush followed by a heappop."""
    if heap and heap[0] < item:
        item, heap[0] = (heap[0], item)
        _siftup(heap, 0)
    return item

def heapify(x):
    """Transform list into a heap, in-place, in O(len(x)) time."""
    n = len(x)
    for i in reversed(range(n // 2)):
        _siftup(x, i)

def _heapify_max(x):
    """Transform list into a maxheap, in-place, in O(len(x)) time."""
    n = len(x)
    for i in reversed(range(n // 2)):
        _siftup_max(x, i)

def digest(key, msg, digest):
    """Fast inline implementation of HMAC.

    key: bytes or buffer, The key for the keyed hash object.
    msg: bytes or buffer, Input message.
    digest: A hash name suitable for hashlib.new() for best performance. *OR*
            A hashlib constructor returning a new hash object. *OR*
            A module supporting PEP 247."""
    if _hashopenssl is not None and isinstance(digest, (str, _functype)):
        try:
            return _hashopenssl.hmac_digest(key, msg, digest)
        except _hashopenssl.UnsupportedDigestmodError:
            pass
    if callable(digest):
        digest_cons = digest
    elif isinstance(digest, str):
        digest_cons = lambda d=b'': _hashlib.new(digest, d)
    else:
        digest_cons = lambda d=b'': digest.new(d)
    inner = digest_cons()
    outer = digest_cons()
    blocksize = getattr(inner, 'block_size', 64)
    if len(key) > blocksize:
        key = digest_cons(key).digest()
    key = key + b'\x00' * (blocksize - len(key))
    inner.update(key.translate(trans_36))
    outer.update(key.translate(trans_5C))
    inner.update(msg)
    outer.update(inner.digest())
    return outer.digest()

def __init__(self, key, msg=None, digestmod=''):
    """Create a new HMAC object.

    key: bytes or buffer, key for the keyed hash object.
    msg: bytes or buffer, Initial input for the hash or None.
    digestmod: A hash name suitable for hashlib.new(). *OR*
               A hashlib constructor returning a new hash object. *OR*
               A module supporting PEP 247.

               Required as of 3.8, despite its position after the optional
               msg argument.  Passing it as a keyword argument is
               recommended, though not required for legacy API reasons."""
    if not isinstance(key, (bytes, bytearray)):
        raise TypeError('key: expected bytes or bytearray, but got %r' % type(key).__name__)
    if not digestmod:
        raise TypeError("Missing required argument 'digestmod'.")
    if _hashopenssl and isinstance(digestmod, (str, _functype)):
        try:
            self._init_hmac(key, msg, digestmod)
        except _hashopenssl.UnsupportedDigestmodError:
            self._init_old(key, msg, digestmod)
    else:
        self._init_old(key, msg, digestmod)

def _init_old(self, key, msg, digestmod):
    if callable(digestmod):
        digest_cons = digestmod
    elif isinstance(digestmod, str):
        digest_cons = lambda d=b'': _hashlib.new(digestmod, d)
    else:
        digest_cons = lambda d=b'': digestmod.new(d)
    self._hmac = None
    self._outer = digest_cons()
    self._inner = digest_cons()
    self.digest_size = self._inner.digest_size
    if hasattr(self._inner, 'block_size'):
        blocksize = self._inner.block_size
        if blocksize < 16:
            _warnings.warn('block_size of %d seems too small; using our default of %d.' % (blocksize, self.blocksize), RuntimeWarning, 2)
            blocksize = self.blocksize
    else:
        _warnings.warn('No block_size attribute on given digest object; Assuming %d.' % self.blocksize, RuntimeWarning, 2)
        blocksize = self.blocksize
    if len(key) > blocksize:
        key = digest_cons(key).digest()
    self.block_size = blocksize
    key = key.ljust(blocksize, b'\x00')
    self._outer.update(key.translate(trans_5C))
    self._inner.update(key.translate(trans_36))
    if msg is not None:
        self.update(msg)

@property
def name(self):
    if self._hmac:
        return self._hmac.name
    else:
        return f'hmac-{self._inner.name}'

def _current(self):
    """Return a hash object for the current state.

    To be used only internally with digest() and hexdigest()."""
    if self._hmac:
        return self._hmac
    else:
        h = self._outer.copy()
        h.update(self._inner.digest())
        return h

def hexdigest(self):
    """Like digest(), but returns a string of hexadecimal digits instead.
    """
    h = self._current()
    return h.hexdigest()

def unescape(s):
    """Convert all named and numeric character references (e.g. &gt;, &#62;,
    &x3e;) in the string s to the corresponding unicode characters.
    This function uses the rules defined by the HTML 5 standard
    for both valid and invalid character references, and the list of
    HTML 5 named character references defined in html.entities.html5."""
    if '&' not in s:
        return s
    return _charref.sub(_replace_charref, s)

def close(self):
    """Handle any buffered data."""
    self.goahead(1)

def get_starttag_text(self):
    """Return full source of start tag: '<...>'."""
    return self.__starttag_text

def set_cdata_mode(self, elem, *, escapable=False):
    self.cdata_elem = elem.lower()
    self._escapable = escapable
    if self.cdata_elem == 'plaintext':
        self.interesting = re.compile('\\Z')
    elif escapable and (not self.convert_charrefs):
        self.interesting = re.compile('&|</%s(?=[\\t\\n\\r\\f />])' % self.cdata_elem, re.IGNORECASE | re.ASCII)
    else:
        self.interesting = re.compile('</%s(?=[\\t\\n\\r\\f />])' % self.cdata_elem, re.IGNORECASE | re.ASCII)

def parse_html_declaration(self, i):
    rawdata = self.rawdata
    assert rawdata[i:i + 2] == '<!', 'unexpected call to parse_html_declaration()'
    if rawdata[i:i + 4] == '<!--':
        return self.parse_comment(i)
    elif rawdata[i:i + 9] == '<![CDATA[' and self._support_cdata:
        j = rawdata.find(']]>', i + 9)
        if j < 0:
            return -1
        self.unknown_decl(rawdata[i + 3:j])
        return j + 3
    elif rawdata[i:i + 9].lower() == '<!doctype':
        gtpos = rawdata.find('>', i + 9)
        if gtpos == -1:
            return -1
        self.handle_decl(rawdata[i + 2:gtpos])
        return gtpos + 1
    elif rawdata[i:i + 3] == '<![':
        j = rawdata.find('>', i + 3)
        if j < 0:
            return -1
        if rawdata[j - 1] == ']':
            self.unknown_decl(rawdata[i + 3:j - 1])
        else:
            self.handle_comment(rawdata[i + 2:j])
        return j + 1
    else:
        return self.parse_bogus_comment(i)

def parse_comment(self, i, report=True):
    rawdata = self.rawdata
    assert rawdata.startswith('<!--', i), 'unexpected call to parse_comment()'
    match = commentclose.search(rawdata, i + 4)
    if not match:
        match = commentabruptclose.match(rawdata, i + 4)
        if not match:
            return -1
    if report:
        j = match.start()
        self.handle_comment(rawdata[i + 4:j])
    return match.end()

def parse_bogus_comment(self, i, report=1):
    rawdata = self.rawdata
    assert rawdata[i:i + 2] in ('<!', '</'), 'unexpected call to parse_comment()'
    pos = rawdata.find('>', i + 2)
    if pos == -1:
        return -1
    if report:
        self.handle_comment(rawdata[i + 2:pos])
    return pos + 1

def parse_starttag(self, i):
    self.__starttag_text = None
    endpos = self.check_for_whole_start_tag(i)
    if endpos < 0:
        return endpos
    rawdata = self.rawdata
    self.__starttag_text = rawdata[i:endpos]
    attrs = []
    match = tagfind_tolerant.match(rawdata, i + 1)
    assert match, 'unexpected call to parse_starttag()'
    k = match.end()
    self.lasttag = tag = match.group(1).lower()
    while k < endpos:
        m = attrfind_tolerant.match(rawdata, k)
        if not m:
            break
        attrname, rest, attrvalue = m.group(1, 2, 3)
        if not rest:
            attrvalue = None
        elif attrvalue[:1] == "'" == attrvalue[-1:] or attrvalue[:1] == '"' == attrvalue[-1:]:
            attrvalue = attrvalue[1:-1]
        if attrvalue:
            attrvalue = unescape(attrvalue)
        attrs.append((attrname.lower(), attrvalue))
        k = m.end()
    end = rawdata[k:endpos].strip()
    if end not in ('>', '/>'):
        self.handle_data(rawdata[i:endpos])
        return endpos
    if end.endswith('/>'):
        self.handle_startendtag(tag, attrs)
    else:
        self.handle_starttag(tag, attrs)
        if tag in self.CDATA_CONTENT_ELEMENTS or (self.scripting and tag == 'noscript') or tag == 'plaintext':
            self.set_cdata_mode(tag, escapable=False)
        elif tag in self.RCDATA_CONTENT_ELEMENTS:
            self.set_cdata_mode(tag, escapable=True)
    return endpos

def parse_endtag(self, i):
    rawdata = self.rawdata
    assert rawdata[i:i + 2] == '</', 'unexpected call to parse_endtag'
    if rawdata.find('>', i + 2) < 0:
        return -1
    if not endtagopen.match(rawdata, i):
        if rawdata[i + 2:i + 3] == '>':
            return i + 3
        else:
            return self.parse_bogus_comment(i)
    match = locatetagend.match(rawdata, i + 2)
    assert match
    j = match.end()
    if rawdata[j - 1] != '>':
        return -1
    match = tagfind_tolerant.match(rawdata, i + 2)
    assert match
    tag = match.group(1).lower()
    self.handle_endtag(tag)
    self.clear_cdata_mode()
    return j

def handle_startendtag(self, tag, attrs):
    self.handle_starttag(tag, attrs)
    self.handle_endtag(tag)

@property
def is_informational(self):
    return 100 <= self <= 199

@property
def is_success(self):
    return 200 <= self <= 299

@property
def is_redirection(self):
    return 300 <= self <= 399

@property
def is_client_error(self):
    return 400 <= self <= 499

@property
def is_server_error(self):
    return 500 <= self <= 599

def _encode(data, name='data'):
    """Call data.encode("latin-1") but show a better error message."""
    try:
        return data.encode('latin-1')
    except UnicodeEncodeError as err:
        raise UnicodeEncodeError(err.encoding, err.object, err.start, err.end, "%s (%.20r) is not valid Latin-1. Use %s.encode('utf-8') if you want to send it encoded in UTF-8." % (name.title(), data[err.start:err.end], name)) from None

def _read_headers(fp):
    """Reads potential header lines into a list from a file pointer.

    Length of line is limited by _MAXLINE, and number of
    headers is limited by _MAXHEADERS."""
    headers = []
    while True:
        line = fp.readline(_MAXLINE + 1)
        if len(line) > _MAXLINE:
            raise LineTooLong('header line')
        headers.append(line)
        if len(headers) > _MAXHEADERS:
            raise HTTPException('got more than %d headers' % _MAXHEADERS)
        if line in (b'\r\n', b'\n', b''):
            break
    return headers

def parse_headers(fp, _class=HTTPMessage):
    """Parses only RFC2822 headers from a file pointer."""
    headers = _read_headers(fp)
    return _parse_header_lines(headers, _class)

def _create_https_context(http_version):
    context = ssl._create_default_https_context()
    if http_version == 11:
        context.set_alpn_protocols(['http/1.1'])
    if context.post_handshake_auth is not None:
        context.post_handshake_auth = True
    return context

def _read_status(self):
    line = str(self.fp.readline(_MAXLINE + 1), 'iso-8859-1')
    if len(line) > _MAXLINE:
        raise LineTooLong('status line')
    if self.debuglevel > 0:
        print('reply:', repr(line))
    if not line:
        raise RemoteDisconnected('Remote end closed connection without response')
    try:
        version, status, reason = line.split(None, 2)
    except ValueError:
        try:
            version, status = line.split(None, 1)
            reason = ''
        except ValueError:
            version = ''
    if not version.startswith('HTTP/'):
        self._close_conn()
        raise BadStatusLine(line)
    try:
        status = int(status)
        if status < 100 or status > 999:
            raise BadStatusLine(line)
    except ValueError:
        raise BadStatusLine(line)
    return (version, status, reason)

def _check_close(self):
    conn = self.headers.get('connection')
    if self.version == 11:
        if conn and 'close' in conn.lower():
            return True
        return False
    if self.headers.get('keep-alive'):
        return False
    if conn and 'keep-alive' in conn.lower():
        return False
    pconn = self.headers.get('proxy-connection')
    if pconn and 'keep-alive' in pconn.lower():
        return False
    return True

def close(self):
    try:
        super().close()
    finally:
        if self.fp:
            self._close_conn()

def flush(self):
    super().flush()
    if self.fp:
        self.fp.flush()

def readable(self):
    """Always returns True"""
    return True

def isclosed(self):
    """True if the connection is closed."""
    return self.fp is None

def read(self, amt=None):
    """Read and return the response body, or up to the next amt bytes."""
    if self.fp is None:
        return b''
    if self._method == 'HEAD':
        self._close_conn()
        return b''
    if self.chunked:
        return self._read_chunked(amt)
    if amt is not None and amt >= 0:
        if self.length is not None and amt > self.length:
            amt = self.length
        s = self.fp.read(amt)
        if not s and amt:
            self._close_conn()
        elif self.length is not None:
            self.length -= len(s)
            if not self.length:
                self._close_conn()
        return s
    else:
        if self.length is None:
            s = self.fp.read()
        else:
            try:
                s = self._safe_read(self.length)
            except IncompleteRead:
                self._close_conn()
                raise
            self.length = 0
        self._close_conn()
        return s

def readinto(self, b):
    """Read up to len(b) bytes into bytearray b and return the number
    of bytes read."""
    if self.fp is None:
        return 0
    if self._method == 'HEAD':
        self._close_conn()
        return 0
    if self.chunked:
        return self._readinto_chunked(b)
    if self.length is not None:
        if len(b) > self.length:
            b = memoryview(b)[0:self.length]
    n = self.fp.readinto(b)
    if not n and b:
        self._close_conn()
    elif self.length is not None:
        self.length -= n
        if not self.length:
            self._close_conn()
    return n

def _read_next_chunk_size(self):
    line = self.fp.readline(_MAXLINE + 1)
    if len(line) > _MAXLINE:
        raise LineTooLong('chunk size')
    i = line.find(b';')
    if i >= 0:
        line = line[:i]
    try:
        return int(line, 16)
    except ValueError:
        self._close_conn()
        raise

def _read_and_discard_trailer(self):
    while True:
        line = self.fp.readline(_MAXLINE + 1)
        if len(line) > _MAXLINE:
            raise LineTooLong('trailer line')
        if not line:
            break
        if line in (b'\r\n', b'\n', b''):
            break

def _get_chunk_left(self):
    chunk_left = self.chunk_left
    if not chunk_left:
        if chunk_left is not None:
            self._safe_read(2)
        try:
            chunk_left = self._read_next_chunk_size()
        except ValueError:
            raise IncompleteRead(b'')
        if chunk_left == 0:
            self._read_and_discard_trailer()
            self._close_conn()
            chunk_left = None
        self.chunk_left = chunk_left
    return chunk_left

def _read_chunked(self, amt=None):
    assert self.chunked != _UNKNOWN
    if amt is not None and amt < 0:
        amt = None
    value = []
    try:
        while (chunk_left := self._get_chunk_left()) is not None:
            if amt is not None and amt <= chunk_left:
                value.append(self._safe_read(amt))
                self.chunk_left = chunk_left - amt
                break
            value.append(self._safe_read(chunk_left))
            if amt is not None:
                amt -= chunk_left
            self.chunk_left = 0
        return b''.join(value)
    except IncompleteRead as exc:
        raise IncompleteRead(b''.join(value)) from exc

def _readinto_chunked(self, b):
    assert self.chunked != _UNKNOWN
    total_bytes = 0
    mvb = memoryview(b)
    try:
        while True:
            chunk_left = self._get_chunk_left()
            if chunk_left is None:
                return total_bytes
            if len(mvb) <= chunk_left:
                n = self._safe_readinto(mvb)
                self.chunk_left = chunk_left - n
                return total_bytes + n
            temp_mvb = mvb[:chunk_left]
            n = self._safe_readinto(temp_mvb)
            mvb = mvb[n:]
            total_bytes += n
            self.chunk_left = 0
    except IncompleteRead:
        raise IncompleteRead(bytes(b[0:total_bytes]))

def _safe_read(self, amt):
    """Read the number of bytes requested.

    This function should be used when <amt> bytes "should" be present for
    reading. If the bytes are truly not available (due to EOF), then the
    IncompleteRead exception can be used to detect the problem."""
    cursize = min(amt, _MIN_READ_BUF_SIZE)
    data = self.fp.read(cursize)
    if len(data) >= amt:
        return data
    if len(data) < cursize:
        raise IncompleteRead(data, amt - len(data))
    data = io.BytesIO(data)
    data.seek(0, 2)
    while True:
        delta = min(cursize, amt - cursize)
        data.write(self.fp.read(delta))
        if data.tell() >= amt:
            return data.getvalue()
        cursize += delta
        if data.tell() < cursize:
            raise IncompleteRead(data.getvalue(), amt - data.tell())

def read1(self, n=-1):
    """Read with at most one underlying system call.  If at least one
    byte is buffered, return that instead."""
    if self.fp is None or self._method == 'HEAD':
        return b''
    if self.chunked:
        return self._read1_chunked(n)
    if self.length is not None and (n < 0 or n > self.length):
        n = self.length
    result = self.fp.read1(n)
    if not result and n:
        self._close_conn()
    elif self.length is not None:
        self.length -= len(result)
        if not self.length:
            self._close_conn()
    return result

def peek(self, n=-1):
    if self.fp is None or self._method == 'HEAD':
        return b''
    if self.chunked:
        return self._peek_chunked(n)
    return self.fp.peek(n)

def readline(self, limit=-1):
    if self.fp is None or self._method == 'HEAD':
        return b''
    if self.chunked:
        return super().readline(limit)
    if self.length is not None and (limit < 0 or limit > self.length):
        limit = self.length
    result = self.fp.readline(limit)
    if not result and limit:
        self._close_conn()
    elif self.length is not None:
        self.length -= len(result)
        if not self.length:
            self._close_conn()
    return result

def _read1_chunked(self, n):
    chunk_left = self._get_chunk_left()
    if chunk_left is None or n == 0:
        return b''
    if not 0 <= n <= chunk_left:
        n = chunk_left
    read = self.fp.read1(n)
    self.chunk_left -= len(read)
    if not read:
        raise IncompleteRead(b'')
    return read

def _peek_chunked(self, n):
    try:
        chunk_left = self._get_chunk_left()
    except IncompleteRead:
        return b''
    if chunk_left is None:
        return b''
    return self.fp.peek(chunk_left)[:chunk_left]

def getheader(self, name, default=None):
    """Returns the value of the header matching *name*.

    If there are multiple matching headers, the values are
    combined into a single string separated by commas and spaces.

    If no matching header is found, returns *default* or None if
    the *default* is not specified.

    If the headers are unknown, raises http.client.ResponseNotReady."""
    if self.headers is None:
        raise ResponseNotReady()
    headers = self.headers.get_all(name) or default
    if isinstance(headers, str) or not hasattr(headers, '__iter__'):
        return headers
    else:
        return ', '.join(headers)

def getheaders(self):
    """Return list of (header, value) tuples."""
    if self.headers is None:
        raise ResponseNotReady()
    return list(self.headers.items())

@staticmethod
def _is_textIO(stream):
    """Test whether a file-like object is a text or a binary stream.
    """
    return isinstance(stream, io.TextIOBase)

@staticmethod
def _get_content_length(body, method):
    """Get the content-length based on the body.

    If the body is None, we set Content-Length: 0 for methods that expect
    a body (RFC 7230, Section 3.3.2). We also set the Content-Length for
    any method if the body is a str or bytes-like object and not a file."""
    if body is None:
        if method.upper() in _METHODS_EXPECTING_BODY:
            return 0
        else:
            return None
    if hasattr(body, 'read'):
        return None
    try:
        mv = memoryview(body)
        return mv.nbytes
    except TypeError:
        pass
    if isinstance(body, str):
        return len(body)
    return None

def _get_hostport(self, host, port):
    if port is None:
        i = host.rfind(':')
        j = host.rfind(']')
        if i > j:
            try:
                port = int(host[i + 1:])
            except ValueError:
                if host[i + 1:] == '':
                    port = self.default_port
                else:
                    raise InvalidURL("nonnumeric port: '%s'" % host[i + 1:])
            host = host[:i]
        else:
            port = self.default_port
    if host and host[0] == '[' and (host[-1] == ']'):
        host = host[1:-1]
    return (host, port)

def _wrap_ipv6(self, ip):
    if b':' in ip and ip[0] != b'['[0]:
        return b'[' + ip + b']'
    return ip

def _tunnel(self):
    connect = b'CONNECT %s:%d %s\r\n' % (self._wrap_ipv6(self._tunnel_host.encode('idna')), self._tunnel_port, self._http_vsn_str.encode('ascii'))
    headers = [connect]
    for header, value in self._tunnel_headers.items():
        headers.append(f'{header}: {value}\r\n'.encode('latin-1'))
    headers.append(b'\r\n')
    self.send(b''.join(headers))
    del headers
    response = self.response_class(self.sock, method=self._method)
    try:
        version, code, message = response._read_status()
        self._raw_proxy_headers = _read_headers(response.fp)
        if self.debuglevel > 0:
            for header in self._raw_proxy_headers:
                print('header:', header.decode())
        if code != http.HTTPStatus.OK:
            self.close()
            raise OSError(f'Tunnel connection failed: {code} {message.strip()}')
    finally:
        response.close()

def connect(self):
    """Connect to the host and port specified in __init__."""
    sys.audit('http.client.connect', self, self.host, self.port)
    self.sock = self._create_connection((self.host, self.port), self.timeout, self.source_address)
    try:
        self.sock.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
    except OSError as e:
        if e.errno != errno.ENOPROTOOPT:
            raise
    if self._tunnel_host:
        self._tunnel()

def close(self):
    """Close the connection to the HTTP server."""
    self.__state = _CS_IDLE
    try:
        sock = self.sock
        if sock:
            self.sock = None
            sock.close()
    finally:
        response = self.__response
        if response:
            self.__response = None
            response.close()

def send(self, data):
    """Send `data' to the server.
    ``data`` can be a string object, a bytes object, an array object, a
    file-like object that supports a .read() method, or an iterable object."""
    if self.sock is None:
        if self.auto_open:
            self.connect()
        else:
            raise NotConnected()
    if self.debuglevel > 0:
        print('send:', repr(data))
    if hasattr(data, 'read'):
        if self.debuglevel > 0:
            print('sending a readable')
        encode = self._is_textIO(data)
        if encode and self.debuglevel > 0:
            print('encoding file using iso-8859-1')
        while (datablock := data.read(self.blocksize)):
            if encode:
                datablock = datablock.encode('iso-8859-1')
            sys.audit('http.client.send', self, datablock)
            self.sock.sendall(datablock)
        return
    sys.audit('http.client.send', self, data)
    try:
        self.sock.sendall(data)
    except TypeError:
        if isinstance(data, collections.abc.Iterable):
            for d in data:
                self.sock.sendall(d)
        else:
            raise TypeError('data should be a bytes-like object or an iterable, got %r' % type(data))

def _read_readable(self, readable):
    if self.debuglevel > 0:
        print('reading a readable')
    encode = self._is_textIO(readable)
    if encode and self.debuglevel > 0:
        print('encoding file using iso-8859-1')
    while (datablock := readable.read(self.blocksize)):
        if encode:
            datablock = datablock.encode('iso-8859-1')
        yield datablock

def _send_output(self, message_body=None, encode_chunked=False):
    """Send the currently buffered request and clear the buffer.

    Appends an extra \\r\\n to the buffer.
    A message_body may be specified, to be appended to the request."""
    self._buffer.extend((b'', b''))
    msg = b'\r\n'.join(self._buffer)
    del self._buffer[:]
    self.send(msg)
    if message_body is not None:
        if hasattr(message_body, 'read'):
            chunks = self._read_readable(message_body)
        else:
            try:
                memoryview(message_body)
            except TypeError:
                try:
                    chunks = iter(message_body)
                except TypeError:
                    raise TypeError('message_body should be a bytes-like object or an iterable, got %r' % type(message_body))
            else:
                chunks = (message_body,)
        for chunk in chunks:
            if not chunk:
                if self.debuglevel > 0:
                    print('Zero length chunk ignored')
                continue
            if encode_chunked and self._http_vsn == 11:
                chunk = f'{len(chunk):X}\r\n'.encode('ascii') + chunk + b'\r\n'
            self.send(chunk)
        if encode_chunked and self._http_vsn == 11:
            self.send(b'0\r\n\r\n')

def _validate_method(self, method):
    """Validate a method name for putrequest."""
    match = _contains_disallowed_method_pchar_re.search(method)
    if match:
        raise ValueError(f"method can't contain control characters. {method!r} (found at least {match.group()!r})")

def _validate_path(self, url):
    """Validate a url for putrequest."""
    match = _contains_disallowed_url_pchar_re.search(url)
    if match:
        raise InvalidURL(f"URL can't contain control characters. {url!r} (found at least {match.group()!r})")

def _validate_host(self, host):
    """Validate a host so it doesn't contain control characters."""
    match = _contains_disallowed_url_pchar_re.search(host)
    if match:
        raise InvalidURL(f"URL can't contain control characters. {host!r} (found at least {match.group()!r})")

def putheader(self, header, *values):
    """Send a request header line to the server.

    For example: h.putheader('Accept', 'text/html')"""
    if self.__state != _CS_REQ_STARTED:
        raise CannotSendHeader()
    if hasattr(header, 'encode'):
        header = header.encode('ascii')
    if not _is_legal_header_name(header):
        raise ValueError('Invalid header name %r' % (header,))
    values = list(values)
    for i, one_value in enumerate(values):
        if hasattr(one_value, 'encode'):
            values[i] = one_value.encode('latin-1')
        elif isinstance(one_value, int):
            values[i] = str(one_value).encode('ascii')
        if _is_illegal_header_value(values[i]):
            raise ValueError('Invalid header value %r' % (values[i],))
    value = b'\r\n\t'.join(values)
    header = header + b': ' + value
    self._output(header)

def endheaders(self, message_body=None, *, encode_chunked=False):
    """Indicate that the last header line has been sent to the server.

    This method sends the request to the server.  The optional message_body
    argument can be used to pass a message body associated with the
    request."""
    if self.__state == _CS_REQ_STARTED:
        self.__state = _CS_REQ_SENT
    else:
        raise CannotSendHeader()
    self._send_output(message_body, encode_chunked=encode_chunked)

def request(self, method, url, body=None, headers={}, *, encode_chunked=False):
    """Send a complete request to the server."""
    self._send_request(method, url, body, headers, encode_chunked)

def _send_request(self, method, url, body, headers, encode_chunked):
    header_names = frozenset((k.lower() for k in headers))
    skips = {}
    if 'host' in header_names:
        skips['skip_host'] = 1
    if 'accept-encoding' in header_names:
        skips['skip_accept_encoding'] = 1
    self.putrequest(method, url, **skips)
    if 'content-length' not in header_names:
        if 'transfer-encoding' not in header_names:
            encode_chunked = False
            content_length = self._get_content_length(body, method)
            if content_length is None:
                if body is not None:
                    if self.debuglevel > 0:
                        print('Unable to determine size of %r' % body)
                    encode_chunked = True
                    self.putheader('Transfer-Encoding', 'chunked')
            else:
                self.putheader('Content-Length', str(content_length))
    else:
        encode_chunked = False
    for hdr, value in headers.items():
        self.putheader(hdr, value)
    if isinstance(body, str):
        body = _encode(body, 'body')
    self.endheaders(body, encode_chunked=encode_chunked)

def getresponse(self):
    """Get the response from the server.

    If the HTTPConnection is in the correct state, returns an
    instance of HTTPResponse or of whatever object is returned by
    the response_class variable.

    If a request has not been sent or if a previous response has
    not be handled, ResponseNotReady is raised.  If the HTTP
    response indicates that the connection should be closed, then
    it will be closed before the response is returned.  When the
    connection is closed, the underlying socket is closed."""
    if self.__response and self.__response.isclosed():
        self.__response = None
    if self.__state != _CS_REQ_SENT or self.__response:
        raise ResponseNotReady(self.__state)
    if self.debuglevel > 0:
        response = self.response_class(self.sock, self.debuglevel, method=self._method)
    else:
        response = self.response_class(self.sock, method=self._method)
    try:
        try:
            response.begin()
        except ConnectionError:
            self.close()
            raise
        assert response.will_close != _UNKNOWN
        self.__state = _CS_IDLE
        if response.will_close:
            self.close()
        else:
            self.__response = response
        return response
    except:
        response.close()
        raise

def __init__(self, version):
    self.args = (version,)
    self.version = version

def __repr__(self):
    if self.expected is not None:
        e = ', %i more expected' % self.expected
    else:
        e = ''
    return '%s(%i bytes read%s)' % (self.__class__.__name__, len(self.partial), e)

def __init__(self, line):
    if not line:
        line = repr(line)
    self.args = (line,)
    self.line = line

def __init__(self, *pos, **kw):
    BadStatusLine.__init__(self, '')
    ConnectionResetError.__init__(self, *pos, **kw)

def __init__(self, host, port=None, *, timeout=socket._GLOBAL_DEFAULT_TIMEOUT, source_address=None, context=None, blocksize=8192):
    super(HTTPSConnection, self).__init__(host, port, timeout, source_address, blocksize=blocksize)
    if context is None:
        context = _create_https_context(self._http_vsn)
    self._context = context

def connect(self):
    """Connect to a host on a given (SSL) port."""
    super().connect()
    if self._tunnel_host:
        server_hostname = self._tunnel_host
    else:
        server_hostname = self.host
    self.sock = self._context.wrap_socket(self.sock, server_hostname=server_hostname)

def _debug(*args):
    if not debug:
        return
    global logger
    if not logger:
        import logging
        logger = logging.getLogger('http.cookiejar')
    return logger.debug(*args)

def _timegm(tt):
    year, month, mday, hour, min, sec = tt[:6]
    if year >= EPOCH_YEAR and 1 <= month <= 12 and (1 <= mday <= 31) and (0 <= hour <= 24) and (0 <= min <= 59) and (0 <= sec <= 61):
        return timegm(tt)
    else:
        return None

def time2netscape(t=None):
    """Return a string representing time in seconds since epoch, t.

    If the function is called without an argument, it will use the current
    time.

    The format of the returned string is like this:

    Wed, DD-Mon-YYYY HH:MM:SS GMT"""
    if t is None:
        dt = datetime.datetime.now(tz=datetime.UTC)
    else:
        dt = datetime.datetime.fromtimestamp(t, tz=datetime.UTC)
    return '%s, %02d-%s-%04d %02d:%02d:%02d GMT' % (DAYS[dt.weekday()], dt.day, MONTHS[dt.month - 1], dt.year, dt.hour, dt.minute, dt.second)

def offset_from_tz_string(tz):
    offset = None
    if tz in UTC_ZONES:
        offset = 0
    else:
        m = TIMEZONE_RE.search(tz)
        if m:
            offset = 3600 * int(m.group(2))
            if m.group(3):
                offset = offset + 60 * int(m.group(3))
            if m.group(1) == '-':
                offset = -offset
    return offset

def join_header_words(lists):
    """Do the inverse (almost) of the conversion done by split_header_words.

    Takes a list of lists of (key, value) pairs and produces a single header
    value.  Attribute values are quoted if needed.

    >>> join_header_words([[("text/plain", None), ("charset", "iso-8859-1")]])
    'text/plain; charset="iso-8859-1"'
    >>> join_header_words([[("text/plain", None)], [("charset", "iso-8859-1")]])
    'text/plain, charset="iso-8859-1"'"""
    headers = []
    for pairs in lists:
        attr = []
        for k, v in pairs:
            if v is not None:
                if not re.search('^\\w+$', v):
                    v = HEADER_JOIN_ESCAPE_RE.sub('\\\\\\1', v)
                    v = '"%s"' % v
                k = '%s=%s' % (k, v)
            attr.append(k)
        if attr:
            headers.append('; '.join(attr))
    return ', '.join(headers)

def strip_quotes(text):
    if text.startswith('"'):
        text = text[1:]
    if text.endswith('"'):
        text = text[:-1]
    return text

def is_HDN(text):
    """Return True if text is a host domain name."""
    if IPV4_RE.search(text):
        return False
    if text == '':
        return False
    if text[0] == '.' or text[-1] == '.':
        return False
    return True

def liberal_is_HDN(text):
    """Return True if text is a sort-of-like a host domain name.

    For accepting/blocking domains."""
    if IPV4_RE.search(text):
        return False
    return True

def user_domain_match(A, B):
    """For blocking/accepting domains.

    A and B may be host domain names or IP addresses."""
    A = A.lower()
    B = B.lower()
    if not (liberal_is_HDN(A) and liberal_is_HDN(B)):
        if A == B:
            return True
        return False
    initial_dot = B.startswith('.')
    if initial_dot and A.endswith(B):
        return True
    if not initial_dot and A == B:
        return True
    return False

def request_host(request):
    """Return request-host, as defined by RFC 2965.

    Variation from RFC: returned value is lowercased, for convenient
    comparison."""
    url = request.get_full_url()
    host = urllib.parse.urlparse(url)[1]
    if host == '':
        host = request.get_header('Host', '')
    host = cut_port_re.sub('', host, 1)
    return host.lower()

def eff_request_host(request):
    """Return a tuple (request-host, effective request-host name).

    As defined by RFC 2965, except both are lowercased."""
    erhn = req_host = request_host(request)
    if '.' not in req_host:
        erhn = req_host + '.local'
    return (req_host, erhn)

def request_port(request):
    host = request.host
    i = host.find(':')
    if i >= 0:
        port = host[i + 1:]
        try:
            int(port)
        except ValueError:
            _debug("nonnumeric port: '%s'", port)
            return None
    else:
        port = DEFAULT_HTTP_PORT
    return port

def is_third_party(request):
    """RFC 2965, section 3.3.6:

        An unverifiable transaction is to a third-party host if its request-
        host U does not domain-match the reach R of the request-host O in the
        origin transaction."""
    req_host = request_host(request)
    if not domain_match(req_host, reach(request.origin_req_host)):
        return True
    else:
        return False

def lwp_cookie_str(cookie):
    """Return string representation of Cookie in the LWP cookie file format.

    Actually, the format is extended a bit -- see module docstring."""
    h = [(cookie.name, cookie.value), ('path', cookie.path), ('domain', cookie.domain)]
    if cookie.port is not None:
        h.append(('port', cookie.port))
    if cookie.path_specified:
        h.append(('path_spec', None))
    if cookie.port_specified:
        h.append(('port_spec', None))
    if cookie.domain_initial_dot:
        h.append(('domain_dot', None))
    if cookie.secure:
        h.append(('secure', None))
    if cookie.expires:
        h.append(('expires', time2isoz(float(cookie.expires))))
    if cookie.discard:
        h.append(('discard', None))
    if cookie.comment:
        h.append(('comment', cookie.comment))
    if cookie.comment_url:
        h.append(('commenturl', cookie.comment_url))
    keys = sorted(cookie._rest.keys())
    for k in keys:
        h.append((k, str(cookie._rest[k])))
    h.append(('version', str(cookie.version)))
    return join_header_words([h])

def is_expired(self, now=None):
    if now is None:
        now = time.time()
    if self.expires is not None and self.expires <= now:
        return True
    return False

def __str__(self):
    if self.port is None:
        p = ''
    else:
        p = ':' + self.port
    limit = self.domain + p + self.path
    if self.value is not None:
        namevalue = '%s=%s' % (self.name, self.value)
    else:
        namevalue = self.name
    return '<Cookie %s for %s>' % (namevalue, limit)

def __repr__(self):
    args = []
    for name in ('version', 'name', 'value', 'port', 'port_specified', 'domain', 'domain_specified', 'domain_initial_dot', 'path', 'path_specified', 'secure', 'expires', 'discard', 'comment', 'comment_url'):
        attr = getattr(self, name)
        args.append('%s=%s' % (name, repr(attr)))
    args.append('rest=%s' % repr(self._rest))
    args.append('rfc2109=%s' % repr(self.rfc2109))
    return '%s(%s)' % (self.__class__.__name__, ', '.join(args))

def return_ok(self, cookie, request):
    """Return true if (and only if) cookie should be returned to server."""
    raise NotImplementedError()

def blocked_domains(self):
    """Return the sequence of blocked domains (as a tuple)."""
    return self._blocked_domains

def set_blocked_domains(self, blocked_domains):
    """Set the sequence of blocked domains."""
    self._blocked_domains = tuple(blocked_domains)

def is_blocked(self, domain):
    for blocked_domain in self._blocked_domains:
        if user_domain_match(domain, blocked_domain):
            return True
    return False

def allowed_domains(self):
    """Return None, or the sequence of allowed domains (as a tuple)."""
    return self._allowed_domains

def set_allowed_domains(self, allowed_domains):
    """Set the sequence of allowed domains, or None."""
    if allowed_domains is not None:
        allowed_domains = tuple(allowed_domains)
    self._allowed_domains = allowed_domains

def is_not_allowed(self, domain):
    if self._allowed_domains is None:
        return False
    for allowed_domain in self._allowed_domains:
        if user_domain_match(domain, allowed_domain):
            return False
    return True

def set_ok(self, cookie, request):
    """If you override .set_ok(), be sure to call this method.  If it returns
    false, so should your subclass (assuming your subclass wants to be more
    strict about which cookies to accept)."""
    _debug(' - checking cookie %s=%s', cookie.name, cookie.value)
    assert cookie.name is not None
    for n in ('version', 'verifiability', 'name', 'path', 'domain', 'port'):
        fn_name = 'set_ok_' + n
        fn = getattr(self, fn_name)
        if not fn(cookie, request):
            return False
    return True

def set_ok_verifiability(self, cookie, request):
    if request.unverifiable and is_third_party(request):
        if cookie.version > 0 and self.strict_rfc2965_unverifiable:
            _debug('   third-party RFC 2965 cookie during unverifiable transaction')
            return False
        elif cookie.version == 0 and self.strict_ns_unverifiable:
            _debug('   third-party Netscape cookie during unverifiable transaction')
            return False
    return True

def set_ok_name(self, cookie, request):
    if cookie.version == 0 and self.strict_ns_set_initial_dollar and cookie.name.startswith('$'):
        _debug("   illegal name (starts with '$'): '%s'", cookie.name)
        return False
    return True

def set_ok_path(self, cookie, request):
    if cookie.path_specified:
        req_path = request_path(request)
        if (cookie.version > 0 or (cookie.version == 0 and self.strict_ns_set_path)) and (not self.path_return_ok(cookie.path, request)):
            _debug('   path attribute %s is not a prefix of request path %s', cookie.path, req_path)
            return False
    return True

def set_ok_port(self, cookie, request):
    if cookie.port_specified:
        req_port = request_port(request)
        if req_port is None:
            req_port = '80'
        else:
            req_port = str(req_port)
        for p in cookie.port.split(','):
            try:
                int(p)
            except ValueError:
                _debug('   bad port %s (not numeric)', p)
                return False
            if p == req_port:
                break
        else:
            _debug('   request port (%s) not found in %s', req_port, cookie.port)
            return False
    return True

def return_ok(self, cookie, request):
    """If you override .return_ok(), be sure to call this method.  If it
    returns false, so should your subclass (assuming your subclass wants to
    be more strict about which cookies to return)."""
    _debug(' - checking cookie %s=%s', cookie.name, cookie.value)
    for n in ('version', 'verifiability', 'secure', 'expires', 'port', 'domain'):
        fn_name = 'return_ok_' + n
        fn = getattr(self, fn_name)
        if not fn(cookie, request):
            return False
    return True

def return_ok_version(self, cookie, request):
    if cookie.version > 0 and (not self.rfc2965):
        _debug('   RFC 2965 cookies are switched off')
        return False
    elif cookie.version == 0 and (not self.netscape):
        _debug('   Netscape cookies are switched off')
        return False
    return True

def return_ok_verifiability(self, cookie, request):
    if request.unverifiable and is_third_party(request):
        if cookie.version > 0 and self.strict_rfc2965_unverifiable:
            _debug('   third-party RFC 2965 cookie during unverifiable transaction')
            return False
        elif cookie.version == 0 and self.strict_ns_unverifiable:
            _debug('   third-party Netscape cookie during unverifiable transaction')
            return False
    return True

def return_ok_secure(self, cookie, request):
    if cookie.secure and request.type not in self.secure_protocols:
        _debug('   secure cookie with non-secure request')
        return False
    return True

def return_ok_port(self, cookie, request):
    if cookie.port:
        req_port = request_port(request)
        if req_port is None:
            req_port = '80'
        for p in cookie.port.split(','):
            if p == req_port:
                break
        else:
            _debug('   request port %s does not match cookie port %s', req_port, cookie.port)
            return False
    return True

def return_ok_domain(self, cookie, request):
    req_host, erhn = eff_request_host(request)
    domain = cookie.domain
    if domain and (not domain.startswith('.')):
        dotdomain = '.' + domain
    else:
        dotdomain = domain
    if cookie.version == 0 and self.strict_ns_domain & self.DomainStrictNonDomain and (not cookie.domain_specified) and (domain != erhn):
        _debug('   cookie with unspecified domain does not string-compare equal to request domain')
        return False
    if cookie.version > 0 and (not domain_match(erhn, domain)):
        _debug('   effective request-host name %s does not domain-match RFC 2965 cookie domain %s', erhn, domain)
        return False
    if cookie.version == 0 and (not ('.' + erhn).endswith(dotdomain)):
        _debug('   request-host %s does not match Netscape cookie domain %s', req_host, domain)
        return False
    return True

def domain_return_ok(self, domain, request):
    req_host, erhn = eff_request_host(request)
    if not req_host.startswith('.'):
        req_host = '.' + req_host
    if not erhn.startswith('.'):
        erhn = '.' + erhn
    if domain and (not domain.startswith('.')):
        dotdomain = '.' + domain
    else:
        dotdomain = domain
    if not (req_host.endswith(dotdomain) or erhn.endswith(dotdomain)):
        return False
    if self.is_blocked(domain):
        _debug('   domain %s is in user block-list', domain)
        return False
    if self.is_not_allowed(domain):
        _debug('   domain %s is not in user allow-list', domain)
        return False
    return True

def _cookies_for_domain(self, domain, request):
    cookies = []
    if not self._policy.domain_return_ok(domain, request):
        return []
    _debug('Checking %s for cookies to return', domain)
    cookies_by_path = self._cookies[domain]
    for path in cookies_by_path.keys():
        if not self._policy.path_return_ok(path, request):
            continue
        cookies_by_name = cookies_by_path[path]
        for cookie in cookies_by_name.values():
            if not self._policy.return_ok(cookie, request):
                _debug('   not returning cookie')
                continue
            _debug("   it's a match")
            cookies.append(cookie)
    return cookies

def _cookies_for_request(self, request):
    """Return a list of cookies to be returned to server."""
    cookies = []
    for domain in self._cookies.keys():
        cookies.extend(self._cookies_for_domain(domain, request))
    return cookies

def _cookie_attrs(self, cookies):
    """Return a list of cookie-attributes to be returned to server.

    like ['foo="bar"; $Path="/"', ...]

    The $Version attribute is also added when appropriate (currently only
    once per request)."""
    cookies.sort(key=lambda a: len(a.path), reverse=True)
    version_set = False
    attrs = []
    for cookie in cookies:
        version = cookie.version
        if not version_set:
            version_set = True
            if version > 0:
                attrs.append('$Version=%s' % version)
        if cookie.value is not None and self.non_word_re.search(cookie.value) and (version > 0):
            value = self.quote_re.sub('\\\\\\1', cookie.value)
        else:
            value = cookie.value
        if cookie.value is None:
            attrs.append(cookie.name)
        else:
            attrs.append('%s=%s' % (cookie.name, value))
        if version > 0:
            if cookie.path_specified:
                attrs.append('$Path="%s"' % cookie.path)
            if cookie.domain.startswith('.'):
                domain = cookie.domain
                if not cookie.domain_initial_dot and domain.startswith('.'):
                    domain = domain[1:]
                attrs.append('$Domain="%s"' % domain)
            if cookie.port is not None:
                p = '$Port'
                if cookie.port_specified:
                    p = p + '="%s"' % cookie.port
                attrs.append(p)
    return attrs

def add_cookie_header(self, request):
    """Add correct Cookie: header to request (urllib.request.Request object).

    The Cookie2 header is also added unless policy.hide_cookie2 is true."""
    _debug('add_cookie_header')
    self._cookies_lock.acquire()
    try:
        self._policy._now = self._now = int(time.time())
        cookies = self._cookies_for_request(request)
        attrs = self._cookie_attrs(cookies)
        if attrs:
            if not request.has_header('Cookie'):
                request.add_unredirected_header('Cookie', '; '.join(attrs))
        if self._policy.rfc2965 and (not self._policy.hide_cookie2) and (not request.has_header('Cookie2')):
            for cookie in cookies:
                if cookie.version != 1:
                    request.add_unredirected_header('Cookie2', '$Version="1"')
                    break
    finally:
        self._cookies_lock.release()
    self.clear_expired_cookies()

def _cookies_from_attrs_set(self, attrs_set, request):
    cookie_tuples = self._normalized_cookie_tuples(attrs_set)
    cookies = []
    for tup in cookie_tuples:
        cookie = self._cookie_from_cookie_tuple(tup, request)
        if cookie:
            cookies.append(cookie)
    return cookies

def _process_rfc2109_cookies(self, cookies):
    rfc2109_as_ns = getattr(self._policy, 'rfc2109_as_netscape', None)
    if rfc2109_as_ns is None:
        rfc2109_as_ns = not self._policy.rfc2965
    for cookie in cookies:
        if cookie.version == 1:
            cookie.rfc2109 = True
            if rfc2109_as_ns:
                cookie.version = 0

def set_cookie_if_ok(self, cookie, request):
    """Set a cookie if policy says it's OK to do so."""
    self._cookies_lock.acquire()
    try:
        self._policy._now = self._now = int(time.time())
        if self._policy.set_ok(cookie, request):
            self.set_cookie(cookie)
    finally:
        self._cookies_lock.release()

def set_cookie(self, cookie):
    """Set a cookie, without checking whether or not it should be set."""
    c = self._cookies
    self._cookies_lock.acquire()
    try:
        if cookie.domain not in c:
            c[cookie.domain] = {}
        c2 = c[cookie.domain]
        if cookie.path not in c2:
            c2[cookie.path] = {}
        c3 = c2[cookie.path]
        c3[cookie.name] = cookie
    finally:
        self._cookies_lock.release()

def extract_cookies(self, response, request):
    """Extract cookies from response, where allowable given the request."""
    _debug('extract_cookies: %s', response.info())
    self._cookies_lock.acquire()
    try:
        for cookie in self.make_cookies(response, request):
            if self._policy.set_ok(cookie, request):
                _debug(' setting cookie: %s', cookie)
                self.set_cookie(cookie)
    finally:
        self._cookies_lock.release()

def clear_session_cookies(self):
    """Discard all session cookies.

    Note that the .save() method won't save session cookies anyway, unless
    you ask otherwise by passing a true ignore_discard argument."""
    self._cookies_lock.acquire()
    try:
        for cookie in self:
            if cookie.discard:
                self.clear(cookie.domain, cookie.path, cookie.name)
    finally:
        self._cookies_lock.release()

def __len__(self):
    """Return number of contained cookies."""
    i = 0
    for cookie in self:
        i = i + 1
    return i

def __repr__(self):
    r = []
    for cookie in self:
        r.append(repr(cookie))
    return '<%s[%s]>' % (self.__class__.__name__, ', '.join(r))

def __str__(self):
    r = []
    for cookie in self:
        r.append(str(cookie))
    return '<%s[%s]>' % (self.__class__.__name__, ', '.join(r))

def save(self, filename=None, ignore_discard=False, ignore_expires=False):
    """Save cookies to a file."""
    raise NotImplementedError()

def load(self, filename=None, ignore_discard=False, ignore_expires=False):
    """Load cookies from a file."""
    if filename is None:
        if self.filename is not None:
            filename = self.filename
        else:
            raise ValueError(MISSING_FILENAME_TEXT)
    with open(filename) as f:
        self._really_load(f, filename, ignore_discard, ignore_expires)

def revert(self, filename=None, ignore_discard=False, ignore_expires=False):
    """Clear all cookies and reload cookies from a saved file.

    Raises LoadError (or OSError) if reversion is not successful; the
    object's state will not be altered if this happens."""
    if filename is None:
        if self.filename is not None:
            filename = self.filename
        else:
            raise ValueError(MISSING_FILENAME_TEXT)
    self._cookies_lock.acquire()
    try:
        old_state = copy.deepcopy(self._cookies)
        self._cookies = {}
        try:
            self.load(filename, ignore_discard, ignore_expires)
        except OSError:
            self._cookies = old_state
            raise
    finally:
        self._cookies_lock.release()

def as_lwp_str(self, ignore_discard=True, ignore_expires=True):
    """Return cookies as a string of "\\n"-separated "Set-Cookie3" headers.

    ignore_discard and ignore_expires: see docstring for FileCookieJar.save"""
    now = time.time()
    r = []
    for cookie in self:
        if not ignore_discard and cookie.discard:
            continue
        if not ignore_expires and cookie.is_expired(now):
            continue
        r.append('Set-Cookie3: %s' % lwp_cookie_str(cookie))
    return '\n'.join(r + [''])

def save(self, filename=None, ignore_discard=False, ignore_expires=False):
    if filename is None:
        if self.filename is not None:
            filename = self.filename
        else:
            raise ValueError(MISSING_FILENAME_TEXT)
    with os.fdopen(os.open(filename, os.O_CREAT | os.O_WRONLY | os.O_TRUNC, 384), 'w') as f:
        f.write('#LWP-Cookies-2.0\n')
        f.write(self.as_lwp_str(ignore_discard, ignore_expires))

def _really_load(self, f, filename, ignore_discard, ignore_expires):
    now = time.time()
    if not NETSCAPE_MAGIC_RGX.match(f.readline()):
        raise LoadError('%r does not look like a Netscape format cookies file' % filename)
    try:
        while (line := f.readline()) != '':
            rest = {}
            if line.startswith(HTTPONLY_PREFIX):
                rest[HTTPONLY_ATTR] = ''
                line = line[len(HTTPONLY_PREFIX):]
            if line.endswith('\n'):
                line = line[:-1]
            if line.strip().startswith(('#', '$')) or line.strip() == '':
                continue
            domain, domain_specified, path, secure, expires, name, value = line.split('\t')
            secure = secure == 'TRUE'
            domain_specified = domain_specified == 'TRUE'
            if name == '':
                name = value
                value = None
            initial_dot = domain.startswith('.')
            assert domain_specified == initial_dot
            discard = False
            if expires == '':
                expires = None
                discard = True
            c = Cookie(0, name, value, None, False, domain, domain_specified, initial_dot, path, False, secure, expires, discard, None, None, rest)
            if not ignore_discard and c.discard:
                continue
            if not ignore_expires and c.is_expired(now):
                continue
            self.set_cookie(c)
    except OSError:
        raise
    except Exception:
        _warn_unhandled_exception()
        raise LoadError('invalid Netscape format cookies file %r: %r' % (filename, line))

def save(self, filename=None, ignore_discard=False, ignore_expires=False):
    if filename is None:
        if self.filename is not None:
            filename = self.filename
        else:
            raise ValueError(MISSING_FILENAME_TEXT)
    with os.fdopen(os.open(filename, os.O_CREAT | os.O_WRONLY | os.O_TRUNC, 384), 'w') as f:
        f.write(NETSCAPE_HEADER_TEXT)
        now = time.time()
        for cookie in self:
            domain = cookie.domain
            if not ignore_discard and cookie.discard:
                continue
            if not ignore_expires and cookie.is_expired(now):
                continue
            if cookie.secure:
                secure = 'TRUE'
            else:
                secure = 'FALSE'
            if domain.startswith('.'):
                initial_dot = 'TRUE'
            else:
                initial_dot = 'FALSE'
            if cookie.expires is not None:
                expires = str(cookie.expires)
            else:
                expires = ''
            if cookie.value is None:
                name = ''
                value = cookie.name
            else:
                name = cookie.name
                value = cookie.value
            if cookie.has_nonstandard_attr(HTTPONLY_ATTR):
                domain = HTTPONLY_PREFIX + domain
            f.write('\t'.join([domain, initial_dot, cookie.path, secure, expires, name, value]) + '\n')

def no_matching_rfc2965(ns_cookie, lookup=lookup):
    key = (ns_cookie.domain, ns_cookie.path, ns_cookie.name)
    return key not in lookup

def _has_control_character(*val):
    """Detects control characters within a value.
    Supports any type, as header values can be any type."""
    return any((_control_character_re.search(str(v)) for v in val))

def _quote(str):
    """Quote a string for use in a cookie header.

    If the string does not need to be double-quoted, then just return the
    string.  Otherwise, surround the string in doublequotes and quote
    (with a \\) special characters."""
    if str is None or _is_legal_key(str):
        return str
    else:
        return '"' + str.translate(_Translator) + '"'

def _unquote_replace(m):
    if m[1]:
        return chr(int(m[1], 8))
    else:
        return m[2]

def _unquote(str):
    if str is None or len(str) < 2:
        return str
    if str[0] != '"' or str[-1] != '"':
        return str
    str = str[1:-1]
    return _unquote_sub(_unquote_replace, str)

def _getdate(future=0, weekdayname=_weekdayname, monthname=_monthname):
    from time import gmtime, time
    now = time()
    year, month, day, hh, mm, ss, wd, y, z = gmtime(now + future)
    return '%s, %02d %3s %4d %02d:%02d:%02d GMT' % (weekdayname[wd], day, monthname[month], year, hh, mm, ss)

def __init__(self):
    self._key = self._value = self._coded_value = None
    for key in self._reserved:
        dict.__setitem__(self, key, '')

@property
def key(self):
    return self._key

@property
def value(self):
    return self._value

@property
def coded_value(self):
    return self._coded_value

def __setitem__(self, K, V):
    K = K.lower()
    if not K in self._reserved:
        raise CookieError('Invalid attribute %r' % (K,))
    if _has_control_character(K, V):
        raise CookieError(f'Control characters are not allowed in cookies {K!r} {V!r}')
    dict.__setitem__(self, K, V)

def setdefault(self, key, val=None):
    key = key.lower()
    if key not in self._reserved:
        raise CookieError('Invalid attribute %r' % (key,))
    if _has_control_character(key, val):
        raise CookieError('Control characters are not allowed in cookies %r %r' % (key, val))
    return dict.setdefault(self, key, val)

def __eq__(self, morsel):
    if not isinstance(morsel, Morsel):
        return NotImplemented
    return dict.__eq__(self, morsel) and self._value == morsel._value and (self._key == morsel._key) and (self._coded_value == morsel._coded_value)

def update(self, values):
    data = {}
    for key, val in dict(values).items():
        key = key.lower()
        if key not in self._reserved:
            raise CookieError('Invalid attribute %r' % (key,))
        data[key] = val
    dict.update(self, data)

def set(self, key, val, coded_val):
    if key.lower() in self._reserved:
        raise CookieError('Attempt to set a reserved key %r' % (key,))
    if not _is_legal_key(key):
        raise CookieError('Illegal key %r' % (key,))
    if _has_control_character(key, val, coded_val):
        raise CookieError('Control characters are not allowed in cookies %r %r %r' % (key, val, coded_val))
    self._key = key
    self._value = val
    self._coded_value = coded_val

def js_output(self, attrs=None):
    return '
        <script type="text/javascript">
        <!-- begin hiding
        document.cookie = "%s";
        // end hiding -->
        </script>
        ' % self.OutputString(attrs).replace('"', '\"')

def OutputString(self, attrs=None):
    result = []
    append = result.append
    append('%s=%s' % (self.key, self.coded_value))
    if attrs is None:
        attrs = self._reserved
    items = sorted(self.items())
    for key, value in items:
        if value == '':
            continue
        if key not in attrs:
            continue
        if key == 'expires' and isinstance(value, int):
            append('%s=%s' % (self._reserved[key], _getdate(value)))
        elif key == 'max-age' and isinstance(value, int):
            append('%s=%d' % (self._reserved[key], value))
        elif key == 'comment' and isinstance(value, str):
            append('%s=%s' % (self._reserved[key], _quote(value)))
        elif key in self._flags:
            if value:
                append(str(self._reserved[key]))
        else:
            append('%s=%s' % (self._reserved[key], value))
    return _semispacejoin(result)

def __init__(self, input=None):
    if input:
        self.load(input)

def __setitem__(self, key, value):
    """Dictionary style assignment."""
    if isinstance(value, Morsel):
        dict.__setitem__(self, key, value)
    else:
        rval, cval = self.value_encode(value)
        self.__set(key, rval, cval)

def output(self, attrs=None, header='Set-Cookie:', sep='\r\n'):
    """Return a string suitable for HTTP."""
    result = []
    items = sorted(self.items())
    for key, value in items:
        value_output = value.output(attrs, header)
        if _has_control_character(value_output):
            raise CookieError('Control characters are not allowed in cookies')
        result.append(value_output)
    return sep.join(result)

def __repr__(self):
    l = []
    items = sorted(self.items())
    for key, value in items:
        l.append('%s=%s' % (key, repr(value.value)))
    return '<%s: %s>' % (self.__class__.__name__, _spacejoin(l))

def js_output(self, attrs=None):
    """Return a string suitable for JavaScript."""
    result = []
    items = sorted(self.items())
    for key, value in items:
        result.append(value.js_output(attrs))
    return _nulljoin(result)

def load(self, rawdata):
    """Load cookies from a string (presumably HTTP_COOKIE) or
    from a dictionary.  Loading cookies from a dictionary 'd'
    is equivalent to calling:
        map(Cookie.__setitem__, d.keys(), d.values())"""
    if isinstance(rawdata, str):
        self.__parse_string(rawdata)
    else:
        for key, value in rawdata.items():
            self[key] = value
    return

def value_encode(self, val):
    strval = str(val)
    return (strval, _quote(strval))

def _url_collapse_path(path):
    """Given a URL path, remove extra '/'s and '.' path elements and collapse
    any '..' references and returns a collapsed path.

    Implements something akin to RFC-2396 5.2 step 6 to parse relative paths.
    The utility of this function is limited to is_cgi method and helps
    preventing some security attacks.

    Returns: The reconstituted URL, which will always start with a '/'.

    Raises: IndexError if too many '..' occur within the path."""
    path, _, query = path.partition('?')
    path = urllib.parse.unquote(path)
    path_parts = path.split('/')
    head_parts = []
    for part in path_parts[:-1]:
        if part == '..':
            head_parts.pop()
        elif part and part != '.':
            head_parts.append(part)
    if path_parts:
        tail_part = path_parts.pop()
        if tail_part:
            if tail_part == '..':
                head_parts.pop()
                tail_part = ''
            elif tail_part == '.':
                tail_part = ''
    else:
        tail_part = ''
    if query:
        tail_part = '?'.join((tail_part, query))
    splitpath = ('/' + '/'.join(head_parts), tail_part)
    collapsed_path = '/'.join(splitpath)
    return collapsed_path

def nobody_uid():
    """Internal routine to get nobody's uid"""
    global nobody
    if nobody:
        return nobody
    try:
        import pwd
    except ImportError:
        return -1
    try:
        nobody = pwd.getpwnam('nobody')[2]
    except KeyError:
        nobody = 1 + max((x[2] for x in pwd.getpwall()))
    return nobody

def executable(path):
    """Test for executable file."""
    return os.access(path, os.X_OK)

def _get_best_family(*address):
    infos = socket.getaddrinfo(*address, type=socket.SOCK_STREAM, flags=socket.AI_PASSIVE)
    family, type, proto, canonname, sockaddr = next(iter(infos))
    return (family, sockaddr)

def send_response_only(self, code, message=None):
    """Send the response header only."""
    if self.request_version != 'HTTP/0.9':
        if message is None:
            if code in self.responses:
                message = self.responses[code][0]
            else:
                message = ''
        if not hasattr(self, '_headers_buffer'):
            self._headers_buffer = []
        self._headers_buffer.append(('%s %d %s\r\n' % (self.protocol_version, code, message)).encode('latin-1', 'strict'))

def send_header(self, keyword, value):
    """Send a MIME header to the headers buffer."""
    if self.request_version != 'HTTP/0.9':
        if not hasattr(self, '_headers_buffer'):
            self._headers_buffer = []
        self._headers_buffer.append(('%s: %s\r\n' % (keyword, value)).encode('latin-1', 'strict'))
    if keyword.lower() == 'connection':
        if value.lower() == 'close':
            self.close_connection = True
        elif value.lower() == 'keep-alive':
            self.close_connection = False

def end_headers(self):
    """Send the blank line ending the MIME headers."""
    if self.request_version != 'HTTP/0.9':
        self._headers_buffer.append(b'\r\n')
        self.flush_headers()

def flush_headers(self):
    if hasattr(self, '_headers_buffer'):
        self.wfile.write(b''.join(self._headers_buffer))
        self._headers_buffer = []

def log_request(self, code='-', size='-'):
    """Log an accepted request.

    This is called by send_response()."""
    if isinstance(code, HTTPStatus):
        code = code.value
    self.log_message('"%s" %s %s', self.requestline, str(code), str(size))

def version_string(self):
    """Return the server software version string."""
    return self.server_version + ' ' + self.sys_version

def date_time_string(self, timestamp=None):
    """Return the current date and time formatted for a message header."""
    if timestamp is None:
        timestamp = time.time()
    return email.utils.formatdate(timestamp, usegmt=True)

def address_string(self):
    """Return the client address."""
    return self.client_address[0]

def __init__(self, *args, directory=None, **kwargs):
    if directory is None:
        directory = os.getcwd()
    self.directory = os.fspath(directory)
    super().__init__(*args, **kwargs)

def do_GET(self):
    """Serve a GET request."""
    f = self.send_head()
    if f:
        try:
            self.copyfile(f, self.wfile)
        finally:
            f.close()

def do_HEAD(self):
    """Serve a HEAD request."""
    f = self.send_head()
    if f:
        f.close()

def send_head(self):
    """Version of send_head that support CGI scripts"""
    if self.is_cgi():
        return self.run_cgi()
    else:
        return SimpleHTTPRequestHandler.send_head(self)

def is_executable(self, path):
    """Test whether argument path is an executable file."""
    return executable(path)

def is_python(self, path):
    """Test whether argument path is a Python script."""
    head, tail = os.path.splitext(path)
    return tail.lower() in ('.py', '.pyw')

def server_bind(self):
    with contextlib.suppress(Exception):
        self.socket.setsockopt(socket.IPPROTO_IPV6, socket.IPV6_V6ONLY, 0)
    return super().server_bind()

