        self._change_start(self.completions[cursel])

def keyrelease_event(self, event):
    if not self.is_active():
        return
    if self.widget.index('insert') != self.widget.index('%s+%dc' % (self.startindex, len(self.start))):
        self.hide_window()

def transform_children(child_dict, modname=None):
    """Transform a child dictionary to an ordered sequence of objects.

    The dictionary maps names to pyclbr information objects.
    Filter out imported objects.
    Augment class names with bases.
    The insertion order of the dictionary is assumed to have been in line
    number order, so sorting is not necessary.

    The current tree only calls this once per child_dict as it saves
    TreeItems once created.  A future tree and tests might violate this,
    so a check prevents multiple in-place augmentations."""
    obs = []
    for key, obj in child_dict.items():
        if modname is None or obj.module == modname:
            if hasattr(obj, 'super') and obj.super and (obj.name == key):
                supers = []
                for sup in obj.super:
                    if isinstance(sup, str):
                        sname = sup
                    else:
                        sname = sup.name
                        if sup.module != obj.module:
                            sname = f'{sup.module}.{sname}'
                    supers.append(sname)
                obj.name += '({})'.format(', '.join(supers))
            obs.append(obj)
    return obs

def _module_browser(parent):
    if len(sys.argv) > 1:
        file = sys.argv[1]
    else:
        file = __file__
        class Nested_in_func(TreeNode):
            def nested_in_class():
                pass
        def closure():
            class Nested_in_closure:
                pass
    ModuleBrowser(parent, file, _htest=True)

def rootnode(self):
