def closure():
    class Nested_in_closure:
        pass

def get_entity(expression):
    """Return the object corresponding to expression evaluated
    in a namespace spanning sys.modules and __main.dict__."""
    if expression:
        namespace = {**sys.modules, **__main__.__dict__}
        try:
            return eval(expression, namespace)
        except BaseException:
            return None

def get_argspec(ob):
    """Return a string describing the signature of a callable object, or ''.

    For Python-coded functions and methods, the first line is introspected.
    Delete 'self' parameter for classes (.__init__) and bound methods.
    The next lines are the first lines of the doc string up to the first
    empty line or _MAX_LINES.    For builtins, this typically includes
    the arguments in addition to the return value."""
    try:
        ob_call = ob.__call__
    except BaseException:
        return ''
    fob = ob_call if isinstance(ob_call, types.MethodType) else ob
    try:
        argspec = str(inspect.signature(fob))
    except Exception as err:
        msg = str(err)
        if msg.startswith(_invalid_method):
            return _invalid_method
        else:
            argspec = ''
    if isinstance(fob, type) and argspec == '()':
        argspec = _default_callable_argspec
    lines = textwrap.wrap(argspec, _MAX_COLS, subsequent_indent=_INDENT) if len(argspec) > _MAX_COLS else [argspec] if argspec else []
    doc = inspect.getdoc(ob)
    if doc:
        for line in doc.split('\n', _MAX_LINES)[:_MAX_LINES]:
            line = line.strip()
            if not line:
                break
            if len(line) > _MAX_COLS:
                line = line[:_MAX_COLS - 3] + '...'
            lines.append(line)
    argspec = '\n'.join(lines)
    return argspec or _default_callable_argspec

def __init__(self, editwin=None):
    if editwin is None:
        self.editwin = None
    else:
        self.editwin = editwin
        self.text = editwin.text
        self.active_calltip = None
        self._calltip_window = self._make_tk_calltip_window

def remove_calltip_window(self, event=None):
    if self.active_calltip:
        self.active_calltip.hidetip()
        self.active_calltip = None

def refresh_calltip_event(self, event):
    if self.active_calltip and self.active_calltip.tipwindow:
        self.open_calltip(False)

def open_calltip(self, evalfuncs):
    """Maybe close an existing calltip and maybe open a new calltip.

    Called from (force_open|try_open|refresh)_calltip_event functions."""
    hp = HyperParser(self.editwin, 'insert')
    sur_paren = hp.get_surrounding_brackets('(')
    if not sur_paren:
        self.remove_calltip_window()
        return
    if self.active_calltip:
        opener_line, opener_col = map(int, sur_paren[0].split('.'))
        if (opener_line, opener_col) == (self.active_calltip.parenline, self.active_calltip.parencol):
            return
    hp.set_index(sur_paren[0])
    try:
        expression = hp.get_expression()
    except ValueError:
        expression = None
    if not expression:
        return
    self.remove_calltip_window()
    if not evalfuncs and expression.find('(') != -1:
        return
    argspec = self.fetch_tip(expression)
    if not argspec:
        return
    self.active_calltip = self._calltip_window()
    self.active_calltip.showtip(argspec, sur_paren[0], sur_paren[1])

def fetch_tip(self, expression):
    """Return the argument list and docstring of a function or class.

    If there is a Python subprocess, get the calltip there.  Otherwise,
    either this fetch_tip() is running in the subprocess or it was
    called in an IDLE running without the subprocess.

    The subprocess environment is that of the most recently run script.  If
    two unrelated modules are being edited some calltips in the current
    module may be inoperative if the module was not the last to run.

    To find methods, fetch_tip must be fed a fully qualified name."""
    try:
        rpcclt = self.editwin.flist.pyshell.interp.rpcclt
    except AttributeError:
        rpcclt = None
    if rpcclt:
        return rpcclt.remotecall('exec', 'get_the_calltip', (expression,), {})
    else:
        return get_argspec(get_entity(expression))

def get_position(self):
    """Choose the position of the call-tip."""
    curline = int(self.anchor_widget.index('insert').split('.')[0])
    if curline == self.parenline:
        anchor_index = (self.parenline, self.parencol)
    else:
        anchor_index = (curline, 0)
    box = self.anchor_widget.bbox('%d.%d' % anchor_index)
    if not box:
        box = list(self.anchor_widget.bbox('insert'))
        box[0] = 0
        box[2] = 0
    return (box[0] + 2, box[1] + box[3])

def checkhide_event(self, event=None):
    """Handle CHECK_HIDE_EVENT: call hidetip or reschedule."""
    if not self.tipwindow:
        return None
    curline, curcol = map(int, self.anchor_widget.index('insert').split('.'))
    if curline < self.parenline or (curline == self.parenline and curcol <= self.parencol) or self.anchor_widget.compare('insert', '>', MARK_RIGHT):
        self.hidetip()
        return 'break'
    self.position_window()
    if self.checkhide_after_id is not None:
        self.anchor_widget.after_cancel(self.checkhide_after_id)
    self.checkhide_after_id = self.anchor_widget.after(CHECKHIDE_TIME, self.checkhide_event)
    return None

def hide_event(self, event):
    """Handle HIDE_EVENT by calling hidetip."""
    if not self.tipwindow:
        return None
    self.hidetip()
    return 'break'

def hidetip(self):
    """Hide the call-tip."""
    if not self.tipwindow:
        return
    try:
        self.label.destroy()
    except TclError:
        pass
    self.label = None
    self.parenline = self.parencol = self.lastline = None
    try:
        self.anchor_widget.mark_unset(MARK_RIGHT)
    except TclError:
        pass
    try:
        self._unbind_events()
    except (TclError, ValueError):
        pass
    super().hidetip()

def _bind_events(self):
    """Bind event handlers."""
    self.checkhideid = self.anchor_widget.bind(CHECKHIDE_EVENT, self.checkhide_event)
    for seq in CHECKHIDE_SEQUENCES:
        self.anchor_widget.event_add(CHECKHIDE_EVENT, seq)
    self.anchor_widget.after(CHECKHIDE_TIME, self.checkhide_event)
    self.hideid = self.anchor_widget.bind(HIDE_EVENT, self.hide_event)
    for seq in HIDE_SEQUENCES:
        self.anchor_widget.event_add(HIDE_EVENT, seq)

def _unbind_events(self):
    """Unbind event handlers."""
    for seq in CHECKHIDE_SEQUENCES:
        self.anchor_widget.event_delete(CHECKHIDE_EVENT, seq)
    self.anchor_widget.unbind(CHECKHIDE_EVENT, self.checkhideid)
    self.checkhideid = None
    for seq in HIDE_SEQUENCES:
        self.anchor_widget.event_delete(HIDE_EVENT, seq)
    self.anchor_widget.unbind(HIDE_EVENT, self.hideid)
    self.hideid = None

def get_spaces_firstword(codeline, c=re.compile('^(\\s*)(\\w*)')):
    """Extract the beginning whitespace and first word from codeline."""
    return c.match(codeline).groups()

