        self.cell00.config(bg=line_number_colors['background'])

def any(name, alternates):
    """Return a named group pattern matching list of alternates."""
    return '(?P<%s>' % name + '|'.join(alternates) + ')'

def matched_named_groups(re_match):
    """Get only the non-empty named groups from an re.Match object."""
    return ((k, v) for k, v in re_match.groupdict().items() if v)

def notify_range(self, index1, index2=None):
    """Mark text changes for processing and restart colorizing, if active."""
    self.tag_add('TODO', index1, index2)
    if self.after_id:
        if DEBUG:
            print('colorizing already scheduled')
        return
    if self.colorizing:
        self.stop_colorizing = True
        if DEBUG:
            print('stop colorizing')
    if self.allow_colorizing:
        if DEBUG:
            print('schedule colorizing')
        self.after_id = self.after(1, self.recolorize)
    return

def toggle_colorize_event(self, event=None):
    """Toggle colorizing on and off.

    When toggling off, if colorizing is scheduled or is in
    process, it will be cancelled and/or stopped.

    When toggling on, colorizing will be scheduled."""
    if self.after_id:
        after_id = self.after_id
        self.after_id = None
        if DEBUG:
            print('cancel scheduled recolorizer')
        self.after_cancel(after_id)
    if self.allow_colorizing and self.colorizing:
        if DEBUG:
            print('stop colorizing')
        self.stop_colorizing = True
    self.allow_colorizing = not self.allow_colorizing
    if self.allow_colorizing and (not self.colorizing):
        self.after_id = self.after(1, self.recolorize)
    if DEBUG:
        print('auto colorizing turned', 'on' if self.allow_colorizing else 'off')
    return 'break'

def recolorize(self):
    """Timer event (every 1ms) to colorize text.

    Colorizing is only attempted when the text widget exists,
    when colorizing is toggled on, and when the colorizing
    process is not already running.

    After colorizing is complete, some cleanup is done to
    make sure that all the text has been colorized."""
    self.after_id = None
    if not self.delegate:
        if DEBUG:
            print('no delegate')
        return
    if not self.allow_colorizing:
        if DEBUG:
            print('auto colorizing is off')
        return
    if self.colorizing:
        if DEBUG:
            print('already colorizing')
        return
    try:
        self.stop_colorizing = False
        self.colorizing = True
        if DEBUG:
            print('colorizing...')
        t0 = time.perf_counter()
        self.recolorize_main()
        t1 = time.perf_counter()
        if DEBUG:
            print('%.3f seconds' % (t1 - t0))
    finally:
        self.colorizing = False
    if self.allow_colorizing and self.tag_nextrange('TODO', '1.0'):
        if DEBUG:
            print('reschedule colorizing')
        self.after_id = self.after(1, self.recolorize)

def _add_tags_in_section(self, chars, head):
    """Parse and add highlighting tags to a given part of the text.

    `chars` is a string with the text to parse and to which
    highlighting is to be applied.

        `head` is the index in the text widget where the text is found."""
    for m in self.prog.finditer(chars):
        for name, matched_text in matched_named_groups(m):
            a, b = m.span(name)
            self._add_tag(a, b, head, name)
            if matched_text in ('def', 'class'):
                if (m1 := self.idprog.match(chars, b)):
                    a, b = m1.span(1)
                    self._add_tag(a, b, head, 'DEFINITION')

def removecolors(self):
    """Remove all colorizing tags."""
    for tag in self.tagdefs:
        self.tag_remove(tag, '1.0', 'end')

def _warn(msg, *key):
    key = (msg,) + key
    if key not in _warned:
        try:
            print(msg, file=sys.stderr)
        except OSError:
            pass
        _warned.add(key)

def Get(self, section, option, type=None, default=None, raw=False):
    """Get an option value for given section/option or return default.
    If type is specified, return as type."""
    if not self.has_option(section, option):
        return default
    if type == 'bool':
        return self.getboolean(section, option)
    elif type == 'int':
        return self.getint(section, option)
    else:
        return self.get(section, option, raw=raw)

def GetOptionList(self, section):
    """Return a list of options for given section, else []."""
    if self.has_section(section):
        return self.options(section)
    else:
        return []

def Load(self):
    """Load the configuration file from disk."""
    if self.file:
        self.read(self.file)

def SetOption(self, section, option, value):
    """Return True if option is added or changed to value, else False.

    Add section if required.  False means option already had value."""
    if self.has_option(section, option):
        if self.get(section, option) == value:
            return False
        else:
            self.set(section, option, value)
            return True
    else:
        if not self.has_section(section):
            self.add_section(section)
        self.set(section, option, value)
        return True

def RemoveOption(self, section, option):
    """Return True if option is removed from section, else False.

    False if either section does not exist or did not have option."""
    if self.has_section(section):
        return self.remove_option(section, option)
    return False

def AddSection(self, section):
    """If section doesn't exist, add it."""
    if not self.has_section(section):
        self.add_section(section)

def IsEmpty(self):
    """Return True if no sections after removing empty sections."""
    self.RemoveEmptySections()
    return not self.sections()

def Save(self):
    """Update user configuration file.

    If self not empty after removing empty sections, write the file
    to disk. Otherwise, remove the file from disk if it exists."""
    fname = self.file
    if fname and fname[0] != '#':
        if not self.IsEmpty():
            try:
                cfgFile = open(fname, 'w')
            except OSError:
                os.unlink(fname)
                cfgFile = open(fname, 'w')
            with cfgFile:
                self.write(cfgFile)
        elif os.path.exists(self.file):
            os.remove(self.file)

def __init__(self, _utest=False):
    self.config_types = ('main', 'highlight', 'keys', 'extensions')
    self.defaultCfg = {}
    self.userCfg = {}
    self.cfg = {}
    if not _utest:
        self.CreateConfigHandlers()
