def __init__(self):
    """Create a page for each configuration file"""
    self.pages = []
    for config_type in idleConf.config_types:
        self[config_type] = {}
        self.pages.append(self[config_type])

def add_option(self, config_type, section, item, value):
    """Add item/value pair for config_type and section."""
    page = self[config_type]
    value = str(value)
    if section not in page:
        page[section] = {}
    page[section][item] = value

@staticmethod
def save_option(config_type, section, item, value):
    """Return True if the configuration value was added or changed.

    Helper for save_all."""
    if idleConf.defaultCfg[config_type].has_option(section, item):
        if idleConf.defaultCfg[config_type].Get(section, item) == value:
            return idleConf.userCfg[config_type].RemoveOption(section, item)
    return idleConf.userCfg[config_type].SetOption(section, item, value)

def save_all(self):
    """Save configuration changes to the user config file.

    Clear self in preparation for additional changes.
    Return changed for testing."""
    idleConf.userCfg['main'].Save()
    changed = False
    for config_type in self:
        cfg_type_changed = False
        page = self[config_type]
        for section in page:
            if section == 'HelpFiles':
                idleConf.userCfg['main'].remove_section('HelpFiles')
                cfg_type_changed = True
            for item, value in page[section].items():
                if self.save_option(config_type, section, item, value):
                    cfg_type_changed = True
        if cfg_type_changed:
            idleConf.userCfg[config_type].Save()
            changed = True
    for config_type in ['keys', 'highlight']:
        idleConf.userCfg[config_type].Save()
    self.clear()
    return changed

def clear(self):
    """Clear all 4 pages.

    Called in save_all after saving to idleConf.
    XXX Mark window *title* when there are changes; unmark here."""
    for page in self.pages:
        page.clear()

def dumpCfg(cfg):
    print('\n', cfg, '\n')
    for key in sorted(cfg):
        sections = cfg[key].sections()
        sprint(key)
        sprint(sections)
        for section in sections:
            options = cfg[key].options(section)
            sprint(section)
            sprint(options)
            for option in options:
                sprint(option + ' = ' + cfg[key].Get(section, option))

def translate_key(key, modifiers):
    """Translate from keycap symbol to the Tkinter keysym."""
    mapping = {'Space': 'space', '~': 'asciitilde', '!': 'exclam', '@': 'at', '#': 'numbersign', '%': 'percent', '^': 'asciicircum', '&': 'ampersand', '*': 'asterisk', '(': 'parenleft', ')': 'parenright', '_': 'underscore', '-': 'minus', '+': 'plus', '=': 'equal', '{': 'braceleft', '}': 'braceright', '[': 'bracketleft', ']': 'bracketright', '|': 'bar', ';': 'semicolon', ':': 'colon', ',': 'comma', '.': 'period', '<': 'less', '>': 'greater', '/': 'slash', '?': 'question', 'Page Up': 'Prior', 'Page Down': 'Next', 'Left Arrow': 'Left', 'Right Arrow': 'Right', 'Up Arrow': 'Up', 'Down Arrow': 'Down', 'Tab': 'Tab'}
    key = mapping.get(key, key)
    if 'Shift' in modifiers and key in string.ascii_lowercase:
        key = key.upper()
    return f'Key-{key}'

def set_modifiers_for_platform(self):
    """Determine list of names of key modifiers for this platform.

    The names are used to build Tk bindings -- it doesn't matter if the
    keyboard has these keys; it matters if Tk understands them.  The
    order is also important: key binding equality depends on it, so
    config-keys.def must use the same ordering."""
    if sys.platform == 'darwin':
        self.modifiers = ['Shift', 'Control', 'Option', 'Command']
    else:
        self.modifiers = ['Control', 'Alt', 'Shift']
    self.modifier_label = {'Control': 'Ctrl'}

def final_key_selected(self, event=None):
