def ok(self):
    self.result = ''
    keys = self.key_string.get().strip()
    if not keys:
        self.showerror(title=self.keyerror_title, parent=self, message='No key specified.')
        return
    if (self.advanced or self.keys_ok(keys)) and self.bind_ok(keys):
        self.result = keys
    return

def bind_ok(self, keys):
    """Return True if Tcl accepts the new keys else show message."""
    try:
        binding = self.bind(keys, lambda: None)
    except TclError as err:
        self.showerror(title=self.keyerror_title, parent=self, message=f'The entered key sequence is not accepted.\n\nError: {err}')
        return False
    else:
        self.unbind(keys, binding)
        return True

