def GetSubList(self):
    keys = dir(self.object)
    sublist = []
    for key in keys:
        try:
            value = getattr(self.object, key)
        except AttributeError:
            continue
        item = make_objecttreeitem(str(key) + ' =', value, lambda value, key=key, object_=self.object: setattr(object_, key, value))
        sublist.append(item)
    return sublist

def GetSubList(self):
    sublist = ObjectTreeItem.GetSubList(self)
    if len(self.object.__bases__) == 1:
        item = make_objecttreeitem('__bases__[0] =', self.object.__bases__[0])
    else:
        item = make_objecttreeitem('__bases__ =', self.object.__bases__)
    sublist.insert(0, item)
    return sublist

def GetSubList(self):
    sublist = []
    for key in self.keys():
        try:
            value = self.object[key]
        except KeyError:
            continue
        def setfunction(value, key=key, object_=self.object):
            object_[key] = value
        item = make_objecttreeitem(f'{key!r}:', value, setfunction)
        sublist.append(item)
    return sublist

