def home_callback(self, event):
    if event.state & 4 != 0 and event.keysym == 'Home':
        return None
    if self.text.index('iomark') and self.text.compare('iomark', '<=', 'insert lineend') and self.text.compare('insert linestart', '<=', 'iomark'):
        insertpt = int(self.text.index('iomark').split('.')[1])
    else:
        line = self.text.get('insert linestart', 'insert lineend')
        for insertpt in range(len(line)):
            if line[insertpt] not in (' ', '\t'):
                break
        else:
            insertpt = len(line)
    lineat = int(self.text.index('insert').split('.')[1])
    if insertpt == lineat:
        insertpt = 0
    dest = 'insert linestart+' + str(insertpt) + 'c'
    if event.state & 1 == 0:
        self.text.tag_remove('sel', '1.0', 'end')
    else:
        if not self.text.index('sel.first'):
            self.text.mark_set('my_anchor', 'insert')
        elif self.text.compare(self.text.index('sel.first'), '<', self.text.index('insert')):
            self.text.mark_set('my_anchor', 'sel.first')
        else:
            self.text.mark_set('my_anchor', 'sel.last')
        first = self.text.index(dest)
        last = self.text.index('my_anchor')
        if self.text.compare(first, '>', last):
            first, last = (last, first)
        self.text.tag_remove('sel', '1.0', 'end')
        self.text.tag_add('sel', first, last)
    self.text.mark_set('insert', dest)
    self.text.see('insert')
    return 'break'

def postwindowsmenu(self):
    """Callback to register window.

    Only called when Window menu exists."""
    menu = self.menudict['window']
    end = menu.index('end')
    if end is None:
        end = -1
    if end > self.wmenu_end:
        menu.delete(self.wmenu_end + 1, end)
    window.add_windows_to_menu(menu)

def right_menu_event(self, event):
    text = self.text
    newdex = text.index(f'@{event.x},{event.y}')
    try:
        in_selection = text.compare('sel.first', '<=', newdex) and text.compare(newdex, '<=', 'sel.last')
    except TclError:
        in_selection = False
    if not in_selection:
        text.tag_remove('sel', '1.0', 'end')
        text.mark_set('insert', newdex)
    if not self.rmenu:
        self.make_rmenu()
    rmenu = self.rmenu
    self.event = event
    iswin = sys.platform[:3] == 'win'
    if iswin:
        text.config(cursor='arrow')
    for item in self.rmenu_specs:
        try:
            label, eventname, verify_state = item
        except ValueError:
            continue
        if verify_state is None:
            continue
        state = getattr(self, verify_state)()
        rmenu.entryconfigure(label, state=state)
    rmenu.tk_popup(event.x_root, event.y_root)
    if iswin:
        self.text.config(cursor='ibeam')
    return 'break'

def make_rmenu(self):
    rmenu = Menu(self.text, tearoff=0)
    for item in self.rmenu_specs:
        label, eventname = (item[0], item[1])
        if label is not None:
            def command(text=self.text, eventname=eventname):
                text.event_generate(eventname)
            rmenu.add_command(label=label, command=command)
        else:
            rmenu.add_separator()
    self.rmenu = rmenu

