def load_standard_extensions(self):
    for name in self.get_standard_extension_names():
        try:
            self.load_extension(name)
        except:
            print('Failed to load extension', repr(name))
            traceback.print_exc()

def load_extension(self, name):
    fname = self.extfiles.get(name, name)
    try:
        try:
            mod = importlib.import_module('.' + fname, package=__package__)
        except (ImportError, TypeError):
            mod = importlib.import_module(fname)
    except ImportError:
        print('\nFailed to import extension: ', name)
        raise
    cls = getattr(mod, name)
    keydefs = idleConf.GetExtensionBindings(name)
    if hasattr(cls, 'menudefs'):
        self.fill_menus(cls.menudefs, keydefs)
    ins = cls(self)
    self.extensions[name] = ins
    if keydefs:
        self.apply_bindings(keydefs)
        for vevent in keydefs:
            methodname = vevent.replace('-', '_')
            while methodname[:1] == '<':
                methodname = methodname[1:]
            while methodname[-1:] == '>':
                methodname = methodname[:-1]
            methodname = methodname + '_event'
            if hasattr(ins, methodname):
                self.text.bind(vevent, getattr(ins, methodname))

def apply_bindings(self, keydefs=None):
    """Add events with keys to self.text."""
    if keydefs is None:
        keydefs = self.mainmenu.default_keydefs
    text = self.text
    text.keydefs = keydefs
    for event, keylist in keydefs.items():
        if keylist:
            text.event_add(event, *keylist)

def fill_menus(self, menudefs=None, keydefs=None):
    """Fill in dropdown menus used by this window.

    Items whose name begins with '!' become checkbuttons.
    Other names indicate commands.  None becomes a separator."""
    if menudefs is None:
        menudefs = self.mainmenu.menudefs
    if keydefs is None:
        keydefs = self.mainmenu.default_keydefs
    menudict = self.menudict
    text = self.text
    for mname, entrylist in menudefs:
        menu = menudict.get(mname)
        if not menu:
            continue
        for entry in entrylist:
            if entry is None:
                menu.add_separator()
            else:
                label, eventname = entry
                checkbutton = label[:1] == '!'
                if checkbutton:
                    label = label[1:]
                underline, label = prepstr(label)
                accelerator = get_accelerator(keydefs, eventname)
                def command(text=text, eventname=eventname):
                    text.event_generate(eventname)
                if checkbutton:
                    var = self.get_var_obj(eventname, BooleanVar)
                    menu.add_checkbutton(label=label, underline=underline, command=command, accelerator=accelerator, variable=var)
                else:
                    menu.add_command(label=label, underline=underline, command=command, accelerator=accelerator)

def getvar(self, name):
    var = self.get_var_obj(name)
    if var:
        value = var.get()
        return value
    else:
        raise NameError(name)

def setvar(self, name, value, vartype=None):
    var = self.get_var_obj(name, vartype)
    if var:
        var.set(value)
    else:
        raise NameError(name)

def get_var_obj(self, eventname, vartype=None):
    """Return a tkinter variable instance for the event.
    """
    var = self.tkinter_vars.get(eventname)
    if not var and vartype:
        self.tkinter_vars[eventname] = var = vartype(self.text)
    return var

def is_char_in_string(self, text_index):
    if self.color:
        return self.text.tag_prevrange('TODO', text_index) or 'STRING' in self.text.tag_names(text_index)
    else:
        return 1

def get_tk_tabwidth(self):
