    if self.get_tk_tabwidth() != newtabwidth:
        pixels = text.tk.call('font', 'measure', text['font'], '-displayof', text.master, 'n' * newtabwidth)
        text.configure(tabs=pixels)

def set_indentation_params(self, is_py_src, guess=True):
    if is_py_src and guess:
        i = self.guess_indent()
        if 2 <= i <= 8:
            self.indentwidth = i
        if self.indentwidth != self.tabwidth:
            self.usetabs = False
    self.set_tk_tabwidth(self.tabwidth)

def smart_indent_event(self, event):
    text = self.text
    first, last = self.get_selection_indices()
    text.undo_block_start()
    try:
        if first and last:
            if index2line(first) != index2line(last):
                return self.fregion.indent_region_event(event)
            text.delete(first, last)
            text.mark_set('insert', first)
        prefix = text.get('insert linestart', 'insert')
        raw, effective = get_line_indent(prefix, self.tabwidth)
        if raw == len(prefix):
            self.reindent_to(effective + self.indentwidth)
        else:
            if self.usetabs:
                pad = '\t'
            else:
                effective = len(prefix.expandtabs(self.tabwidth))
                n = self.indentwidth
                pad = ' ' * (n - effective % n)
            text.insert('insert', pad, self.user_input_insert_tags)
        text.see('insert')
        return 'break'
    finally:
        text.undo_block_stop()

def _build_char_in_string_func(self, startindex):
    def inner(offset, _startindex=startindex, _icis=self.is_char_in_string):
        return _icis(_startindex + '+%dc' % offset)
    return inner

def _make_blanks(self, n):
    if self.usetabs:
        ntabs, nspaces = divmod(n, self.tabwidth)
        return '\t' * ntabs + ' ' * nspaces
    else:
        return ' ' * n

def reindent_to(self, column):
    text = self.text
    text.undo_block_start()
    if text.compare('insert linestart', '!=', 'insert'):
        text.delete('insert linestart', 'insert')
    if column:
        text.insert('insert', self._make_blanks(column), self.user_input_insert_tags)
    text.undo_block_stop()

def guess_indent(self):
    opener, indented = IndentSearcher(self.text).run()
    if opener and indented:
        raw, indentsmall = get_line_indent(opener, self.tabwidth)
        raw, indentlarge = get_line_indent(indented, self.tabwidth)
    else:
        indentsmall = indentlarge = 0
    return indentlarge - indentsmall

