def readline(self):
    if self.finished:
        return ''
    i = self.i = self.i + 1
    mark = repr(i) + '.0'
    if self.text.compare(mark, '>=', 'end'):
        return ''
    return self.text.get(mark, mark + ' lineend+1c')

def tokeneater(self, type, token, start, end, line, INDENT=tokenize.INDENT, NAME=tokenize.NAME, OPENERS=('class', 'def', 'for', 'if', 'match', 'try', 'while', 'with')):
    if self.finished:
        pass
    elif type == NAME and token in OPENERS:
        self.blkopenline = line
    elif type == INDENT and self.blkopenline:
        self.indentedline = line
        self.finished = 1

def run(self):
    """Return 2 lines containing block opener and and indent.

    Either the indent line or both may be None."""
    try:
        tokens = tokenize.generate_tokens(self.readline)
        for token in tokens:
            self.tokeneater(*token)
    except (tokenize.TokenError, SyntaxError):
        pass
    return (self.blkopenline, self.indentedline)

