def __init__(self, root):
    self.root = root
    self.dict = {}
    self.inversedict = {}
    self.vars = {}

def open(self, filename, action=None):
    assert filename
    filename = self.canonize(filename)
    if os.path.isdir(filename):
        messagebox.showerror('File Error', f'{filename!r} is a directory.', master=self.root)
        return None
    key = os.path.normcase(filename)
    if key in self.dict:
        edit = self.dict[key]
        edit.top.wakeup()
        return edit
    if action:
        return action(filename)
    else:
        edit = self.EditorWindow(self, filename, key)
        if edit.good_load:
            return edit
        else:
            edit._close()
            return None

def gotofileline(self, filename, lineno=None):
    edit = self.open(filename)
    if edit is not None and lineno is not None:
        edit.gotoline(lineno)

def close_all_callback(self, *args, **kwds):
    for edit in list(self.inversedict):
        reply = edit.close()
        if reply == 'cancel':
            break
    return 'break'

def unregister_maybe_terminate(self, edit):
    try:
        key = self.inversedict[edit]
    except KeyError:
        print("Don't know this EditorWindow object.  (close)")
        return
    if key:
        del self.dict[key]
    del self.inversedict[edit]
    if not self.inversedict:
        self.root.quit()

def filename_changed_edit(self, edit):
    edit.saved_change_hook()
    try:
        key = self.inversedict[edit]
    except KeyError:
        print("Don't know this EditorWindow object.  (rename)")
        return
    filename = edit.io.filename
    if not filename:
        if key:
            del self.dict[key]
        self.inversedict[edit] = None
        return
    filename = self.canonize(filename)
    newkey = os.path.normcase(filename)
    if newkey == key:
        return
    if newkey in self.dict:
        conflict = self.dict[newkey]
        self.inversedict[conflict] = None
        messagebox.showerror('Name Conflict', f'You now have multiple edit windows open for {filename!r}', master=self.root)
    self.dict[newkey] = edit
    self.inversedict[edit] = newkey
    if key:
        try:
            del self.dict[key]
        except KeyError:
            pass

def canonize(self, filename):
    if not os.path.isabs(filename):
        try:
            pwd = os.getcwd()
        except OSError:
            pass
        else:
            filename = os.path.join(pwd, filename)
    return os.path.normpath(filename)

def reformat_paragraph(data, limit):
    """Return data reformatted to specified width (limit)."""
    lines = data.split('\n')
    i = 0
    n = len(lines)
    while i < n and is_all_white(lines[i]):
        i = i + 1
    if i >= n:
        return data
    indent1 = get_indent(lines[i])
    if i + 1 < n and (not is_all_white(lines[i + 1])):
        indent2 = get_indent(lines[i + 1])
    else:
        indent2 = indent1
    new = lines[:i]
    partial = indent1
    while i < n and (not is_all_white(lines[i])):
        words = re.split('(\\s+)', lines[i])
        for j in range(0, len(words), 2):
            word = words[j]
            if not word:
                continue
            if len((partial + word).expandtabs()) > limit and partial != indent1:
                new.append(partial.rstrip())
                partial = indent2
            partial = partial + word + ' '
            if j + 1 < len(words) and words[j + 1] != ' ':
                partial = partial + ' '
        i = i + 1
    new.append(partial.rstrip())
    new.extend(lines[i:])
    return '\n'.join(new)

def get_indent(line):
    """Return the initial space or tab indent of line."""
    return re.match('^([ \\t]*)', line).group()

def get_comment_header(line):
    """Return string with leading whitespace and '#' from line or ''.

    A null return indicates that the line is not a comment line. A non-
    null return, such as '    #', will be used to find the other lines of
    a comment block with the same  indent."""
    m = re.match('^([ \\t]*#*)', line)
    if m is None:
        return ''
    return m.group(1)

@classmethod
def reload(cls):
