def uncomment_region_event(self, event=None):
    """Uncomment each line in region.

    Remove ## or # in the first positions of a line.  If the comment
    is not in the beginning position, this command will have no effect."""
    head, tail, chars, lines = self.get_region()
    for pos in range(len(lines)):
        line = lines[pos]
        if not line:
            continue
        if line[:2] == '##':
            line = line[2:]
        elif line[:1] == '#':
            line = line[1:]
        lines[pos] = line
    self.set_region(head, tail, chars, lines)
    return 'break'

def untabify_region_event(self, event=None):
    """Expand tabs to spaces for each line in region."""
    head, tail, chars, lines = self.get_region()
    tabwidth = self._asktabwidth()
    if tabwidth is None:
        return
    for pos in range(len(lines)):
        lines[pos] = lines[pos].expandtabs(tabwidth)
    self.set_region(head, tail, chars, lines)
    return 'break'

def _asktabwidth(self):
    """Return value for tab width."""
    return askinteger('Tab width', 'Columns per tab? (2-16)', parent=self.editwin.text, initialvalue=self.editwin.indentwidth, minvalue=2, maxvalue=16)

def change_indentwidth_event(self, event):
    editwin = self.editwin
    new = askinteger('Indent width', 'New indent width (2-16)\n(Always use 8 when using tabs)', parent=editwin.text, initialvalue=editwin.indentwidth, minvalue=2, maxvalue=16)
    if new and new != editwin.indentwidth and (not editwin.usetabs):
        editwin.indentwidth = new
    return 'break'

def do_rstrip(self, event=None):
    text = self.editwin.text
    undo = self.editwin.undo
    undo.undo_block_start()
    end_line = int(float(text.index('end')))
    for cur in range(1, end_line):
        txt = text.get('%i.0' % cur, '%i.end' % cur)
        raw = len(txt)
        cut = len(txt.rstrip())
        if cut < raw:
            text.delete('%i.%i' % (cur, cut), '%i.end' % cur)
    if text.get('end-2c') == '\n' and (not hasattr(self.editwin, 'interp')):
        while text.index('end-1c') > '1.0' and text.get('end-3c') == '\n':
            text.delete('end-3c')
    undo.undo_block_stop()

def walk_error(msg):
    """Handle os.walk error."""
    print(msg)

def findfiles(folder, pattern, recursive):
    """Generate file names in dir that match pattern.

    Args:
        folder: Root directory to search.
        pattern: File pattern to match.
        recursive: True to include subdirectories."""
    for dirpath, _, filenames in os.walk(folder, onerror=walk_error):
        yield from (os.path.join(dirpath, name) for name in filenames if fnmatch.fnmatch(name, pattern))
        if not recursive:
            break

def grep_it(self, prog, path):
    """Search for prog within the lines of the files in path.

    For the each file in the path directory, open the file and
    search each line for the matching pattern.  If the pattern is
    found,  write the file and line information to stdout (which
    is an OutputWindow).

    Args:
        prog: The compiled, cooked search pattern.
        path: String containing the search path."""
    folder, filepat = os.path.split(path)
    if not folder:
        folder = os.curdir
    filelist = sorted(findfiles(folder, filepat, self.recvar.get()))
    self.close()
    pat = self.engine.getpat()
    print(f'Searching {pat!r} in {path} ...')
    hits = 0
    try:
        for fn in filelist:
            try:
                with open(fn, errors='replace') as f:
                    for lineno, line in enumerate(f, 1):
                        if line[-1:] == '\n':
                            line = line[:-1]
                        if prog.search(line):
                            sys.stdout.write(f'{fn}: {lineno}: {line}\n')
                            hits += 1
            except OSError as msg:
                print(msg)
        print(f'Hits found: {hits}\n(Hint: right-click to open locations.)' if hits else 'No hits.')
    except AttributeError:
        pass

def show_idlehelp(parent):
    """Create HelpWindow; called from Idle Help event handler."""
