def handle_endtag(self, tag):
    """Handle endtags in help.html."""
    if tag in ['h1', 'h2', 'h3']:
        assert self.level == 0
        indent = '        ' if tag == 'h3' else '    ' if tag == 'h2' else ''
        self.toc.append((indent + self.header, self.text.index('insert')))
        self.tags = ''
    elif tag in ['span', 'em']:
        self.chartags = ''
    elif tag == 'a':
        self.hdrlink = False
    elif tag == 'pre':
        self.pre = False
        self.tags = ''
    elif tag in ['ul', 'dd', 'ol']:
        self.indent(-1)
    self.prevtag = (False, tag)

def handle_data(self, data):
    """Handle date segments in help.html."""
    if not self.hdrlink:
        d = data if self.pre else data.replace('\n', ' ')
        if self.tags == 'h1':
            try:
                self.hprefix = d[:d.index(' ')]
                if not self.hprefix.isdigit():
                    self.hprefix = ''
            except ValueError:
                self.hprefix = ''
        if self.tags in ['h1', 'h2', 'h3']:
            if self.hprefix != '' and d[0:len(self.hprefix)] == self.hprefix:
                d = d[len(self.hprefix):]
            self.header += d.strip()
        self.text.insert('end', d, (self.tags, self.chartags))

def findfont(self, names):
    """Return name of first font family derived from names."""
    for name in names:
        if name.lower() in (x.lower() for x in tkfont.names(root=self)):
            font = tkfont.Font(name=name, exists=True, root=self)
            return font.actual()['family']
        elif name.lower() in (x.lower() for x in tkfont.families(root=self)):
            return name

