def set_filename(self, filename):
    if filename and os.path.isdir(filename):
        self.filename = None
        self.dirname = filename
    else:
        self.filename = filename
        self.dirname = None
        self.set_saved(1)
        if self.filename_change_hook:
            self.filename_change_hook()

def open(self, event=None, editFile=None):
    flist = self.editwin.flist
    if flist:
        if not editFile:
            filename = self.askopenfile()
        else:
            filename = editFile
        if filename:
            if self.editwin and (not getattr(self.editwin, 'interp', None)) and (not self.filename) and self.get_saved():
                flist.open(filename, self.loadfile)
            else:
                flist.open(filename)
        elif self.text:
            self.text.focus_set()
        return 'break'
    if self.get_saved():
        reply = self.maybesave()
        if reply == 'cancel':
            self.text.focus_set()
            return 'break'
    if not editFile:
        filename = self.askopenfile()
    else:
        filename = editFile
    if filename:
        self.loadfile(filename)
    else:
        self.text.focus_set()
    return 'break'

def save(self, event):
    if not self.filename:
        self.save_as(event)
    elif self.writefile(self.filename):
        self.set_saved(True)
        try:
            self.editwin.store_file_breaks()
        except AttributeError:
            pass
    self.text.focus_set()
    return 'break'

def save_as(self, event):
    filename = self.asksavefile()
    if filename:
        if self.writefile(filename):
            self.set_filename(filename)
            self.set_saved(1)
            try:
                self.editwin.store_file_breaks()
            except AttributeError:
                pass
    self.text.focus_set()
    self.updaterecentfileslist(filename)
    return 'break'

def fixnewlines(self):
    """Return text with os eols.

           Add prompts if shell else final
    if missing.
    """
    if hasattr(self.editwin, 'interp'):
        text = self.editwin.get_prompt_text('1.0', self.text.index('end-1c'))
    else:
        if self.text.get('end-2c') != '\n':
            self.text.insert('end-1c', '\n')
        text = self.text.get('1.0', 'end-1c')
    if self.eol_convention != '\n':
        text = text.replace('\n', self.eol_convention)
    return text

def encode(self, chars):
    if isinstance(chars, bytes):
        return chars
    if self.fileencoding == 'utf-8-sig':
        return chars.encode('utf-8-sig')
    try:
        return chars.encode('ascii')
    except UnicodeEncodeError:
        pass
    try:
        encoded = chars.encode('ascii', 'replace')
        enc, _ = tokenize.detect_encoding(io.BytesIO(encoded).readline)
        return chars.encode(enc)
    except SyntaxError as err:
        failed = str(err)
    except UnicodeEncodeError:
        failed = "Invalid encoding '%s'" % enc
    messagebox.showerror('I/O Error', '%s.\nSaving as UTF-8' % failed, parent=self.text)
    return chars.encode('utf-8-sig')

def askopenfile(self):
    dir, base = self.defaultfilename('open')
    if not self.opendialog:
        self.opendialog = filedialog.Open(parent=self.text, filetypes=self.filetypes)
    filename = self.opendialog.show(initialdir=dir, initialfile=base)
    return filename

def defaultfilename(self, mode='open'):
    if self.filename:
        return os.path.split(self.filename)
    elif self.dirname:
        return (self.dirname, '')
    else:
        try:
            pwd = os.getcwd()
        except OSError:
            pwd = ''
        return (pwd, '')

def asksavefile(self):
    dir, base = self.defaultfilename('save')
    if not self.savedialog:
        self.savedialog = filedialog.SaveAs(parent=self.text, filetypes=self.filetypes, defaultextension=self.defaultextension)
    filename = self.savedialog.show(initialdir=dir, initialfile=base)
    return filename

