def poll_subprocess(self):
    clt = self.rpcclt
    if clt is None:
        return
    try:
        response = clt.pollresponse(self.active_seq, wait=0.05)
    except (EOFError, OSError, KeyboardInterrupt):
        if self.tkconsole.closing:
            return
        response = None
        self.restart_subprocess()
    if response:
        self.tkconsole.resetoutput()
        self.active_seq = None
        how, what = response
        console = self.tkconsole.console
        if how == 'OK':
            if what is not None:
                print(repr(what), file=console)
        elif how == 'EXCEPTION':
            if self.tkconsole.getvar('<<toggle-jit-stack-viewer>>'):
                self.remote_stack_viewer()
        elif how == 'ERROR':
            errmsg = 'pyshell.ModifiedInterpreter: Subprocess ERROR:\n'
            print(errmsg, what, file=sys.__stderr__)
            print(errmsg, what, file=console)
        try:
            self.tkconsole.endexecuting()
        except AttributeError:
            pass
    if not self.tkconsole.closing:
        self._afterid = self.tkconsole.text.after(self.tkconsole.pollinterval, self.poll_subprocess)

def execfile(self, filename, source=None):
    """Execute an existing file"""
    if source is None:
        with tokenize.open(filename) as fp:
            source = fp.read()
            if use_subprocess:
                source = f"__file__ = r'''{os.path.abspath(filename)}'''\n" + source + '\ndel __file__'
    try:
        code = compile(source, filename, 'exec')
    except (OverflowError, SyntaxError):
        self.tkconsole.resetoutput()
        print('*** Error in script or command!\nTraceback (most recent call last):', file=self.tkconsole.stderr)
        InteractiveInterpreter.showsyntaxerror(self, filename)
        self.tkconsole.showprompt()
    else:
        self.runcode(code)

