def readline(self):
    save = self.reading
    try:
        self.reading = True
        self.top.mainloop()
    finally:
        self.reading = save
    if self._stop_readline_flag:
        self._stop_readline_flag = False
        return ''
    line = self.text.get('iomark', 'end-1c')
    if len(line) == 0:
        line = '\n'
    self.resetoutput()
    if self.canceled:
        self.canceled = False
