    if not (self.text.compare('iomark', '==', 'insert') and self.text.compare('insert', '==', 'end-1c')):
        return
    if not self.executing:
        self.resetoutput()
        self.close()
    else:
        self.canceled = False
        self.endoffile = True
        self.top.quit()
    return 'break'

