def install_recursionlimit_wrappers():
    """Install wrappers to always add 30 to the recursion limit."""
    @functools.wraps(sys.setrecursionlimit)
    def setrecursionlimit(*args, **kwargs):
        if kwargs:
            raise TypeError('setrecursionlimit() takes no keyword arguments')
        try:
            limit, = args
        except ValueError:
            raise TypeError(f'setrecursionlimit() takes exactly one argument ({len(args)} given)')
        if not limit > 0:
            raise ValueError('recursion limit must be greater or equal than 1')
        return setrecursionlimit.__wrapped__(limit + RECURSIONLIMIT_DELTA)
    fixdoc(setrecursionlimit, f'            This IDLE wrapper adds {RECURSIONLIMIT_DELTA} to prevent possible\n            uninterruptible loops.')
    @functools.wraps(sys.getrecursionlimit)
    def getrecursionlimit():
        return getrecursionlimit.__wrapped__() - RECURSIONLIMIT_DELTA
    fixdoc(getrecursionlimit, f'            This IDLE wrapper subtracts {RECURSIONLIMIT_DELTA} to compensate\n            for the {RECURSIONLIMIT_DELTA} IDLE adds when setting the limit.')
    sys.setrecursionlimit(sys.getrecursionlimit() + RECURSIONLIMIT_DELTA)
    sys.setrecursionlimit = setrecursionlimit
    sys.getrecursionlimit = getrecursionlimit

@functools.wraps(sys.setrecursionlimit)
def setrecursionlimit(*args, **kwargs):
    if kwargs:
        raise TypeError('setrecursionlimit() takes no keyword arguments')
    try:
        limit, = args
    except ValueError:
        raise TypeError(f'setrecursionlimit() takes exactly one argument ({len(args)} given)')
    if not limit > 0:
        raise ValueError('recursion limit must be greater or equal than 1')
    return setrecursionlimit.__wrapped__(limit + RECURSIONLIMIT_DELTA)

@functools.wraps(sys.getrecursionlimit)
def getrecursionlimit():
    return getrecursionlimit.__wrapped__() - RECURSIONLIMIT_DELTA

def __init__(self, shell, tags, encoding='utf-8', errors='strict'):
    self.shell = shell
    self.shell._RPCProxy__attributes = {'width': 1}
    self.tags = tags
    self._encoding = encoding
    self._errors = errors

@property
def name(self):
    return '<%s>' % self.tags

def write(self, s):
    if self.closed:
        raise ValueError('write to closed file')
    s = str.encode(s, self.encoding, self.errors).decode(self.encoding, self.errors)
    return self.shell.write(s, self.tags)

def read(self, size=-1):
    if self.closed:
        raise ValueError('read from closed file')
    if size is None:
        size = -1
    elif not isinstance(size, int):
        raise TypeError('must be int, not ' + type(size).__name__)
    result = self._line_buffer
    self._line_buffer = ''
    if size < 0:
        while (line := self.shell.readline()):
            result += line
    else:
        while len(result) < size:
            line = self.shell.readline()
            if not line:
                break
            result += line
        self._line_buffer = result[size:]
        result = result[:size]
    return result

def readline(self, size=-1):
    if self.closed:
        raise ValueError('read from closed file')
    if size is None:
        size = -1
    elif not isinstance(size, int):
        raise TypeError('must be int, not ' + type(size).__name__)
    line = self._line_buffer or self.shell.readline()
    if size < 0:
        size = len(line)
    eol = line.find('\n', 0, size)
    if eol >= 0:
        size = eol + 1
    self._line_buffer = line[size:]
    return line[:size]

