def undo_block_start(self):
    if self.undoblock == 0:
        self.undoblock = CommandSequence()
    self.undoblock.bump_depth()

def undo_block_stop(self):
    if self.undoblock.bump_depth(-1) == 0:
        cmd = self.undoblock
        self.undoblock = 0
        if len(cmd) > 0:
            if len(cmd) == 1:
                cmd = cmd.getcmd(0)
            self.addcmd(cmd, 0)

def addcmd(self, cmd, execute=True):
    if execute:
        cmd.do(self.delegate)
    if self.undoblock != 0:
        self.undoblock.append(cmd)
        return
    if self.can_merge and self.pointer > 0:
        lastcmd = self.undolist[self.pointer - 1]
        if lastcmd.merge(cmd):
            return
    self.undolist[self.pointer:] = [cmd]
    if self.saved > self.pointer:
        self.saved = -1
    self.pointer = self.pointer + 1
    if len(self.undolist) > self.max_undo:
        del self.undolist[0]
        self.pointer = self.pointer - 1
        if self.saved >= 0:
            self.saved = self.saved - 1
    self.can_merge = True
    self.check_saved()

def __init__(self, index1, index2, chars, tags=None):
    self.marks_before = {}
    self.marks_after = {}
    self.index1 = index1
    self.index2 = index2
    self.chars = chars
    if tags:
        self.tags = tags

def __repr__(self):
    s = self.__class__.__name__
    t = (self.index1, self.index2, self.chars, self.tags)
    if self.tags is None:
        t = t[:-1]
    return s + repr(t)

def save_marks(self, text):
    marks = {}
    for name in text.mark_names():
        if name != 'insert' and name != 'current':
            marks[name] = text.index(name)
    return marks

def set_marks(self, text, marks):
    for name, index in marks.items():
        text.mark_set(name, index)

def merge(self, cmd):
    if self.__class__ is not cmd.__class__:
        return False
    if self.index2 != cmd.index1:
        return False
    if self.tags != cmd.tags:
        return False
    if len(cmd.chars) != 1:
        return False
    if self.chars and self.classify(self.chars[-1]) != self.classify(cmd.chars):
        return False
    self.index2 = cmd.index2
    self.chars = self.chars + cmd.chars
    return True

def classify(self, c):
    if c in self.alphanumeric:
        return 'alphanumeric'
    if c == '\n':
        return 'newline'
    return 'punctuation'

def do(self, text):
    self.marks_before = self.save_marks(text)
    self.index1 = text.index(self.index1)
    if self.index2:
        self.index2 = text.index(self.index2)
    else:
        self.index2 = text.index(self.index1 + ' +1c')
    if text.compare(self.index2, '>', 'end-1c'):
        self.index2 = text.index('end-1c')
    self.chars = text.get(self.index1, self.index2)
    text.delete(self.index1, self.index2)
    self.marks_after = self.save_marks(text)

def __init__(self):
    self.cmds = []
    self.depth = 0

def __repr__(self):
    s = self.__class__.__name__
    strs = []
    for cmd in self.cmds:
        strs.append(f'    {cmd!r}')
    return s + '(\n' + ',\n'.join(strs) + '\n)'

def redo(self, text):
    for cmd in self.cmds:
        cmd.redo(text)

def undo(self, text):
    cmds = self.cmds[:]
    cmds.reverse()
    for cmd in cmds:
        cmd.undo(text)

def bump_depth(self, incr=1):
    self.depth = self.depth + incr
    return self.depth

def fix_win_hidpi():
    try:
        import ctypes
        PROCESS_SYSTEM_DPI_AWARE = 1
        ctypes.OleDLL('shcore').SetProcessDpiAwareness(PROCESS_SYSTEM_DPI_AWARE)
    except (ImportError, AttributeError, OSError):
        pass

def __init__(self):
    self.dict = {}
    self.callbacks = []

def add(self, window):
    window.after_idle(self.call_callbacks)
    self.dict[str(window)] = window

def delete(self, window):
    try:
        del self.dict[str(window)]
    except KeyError:
        pass
    self.call_callbacks()

def add_windows_to_menu(self, menu):
    list = []
    for key in self.dict:
        window = self.dict[key]
        try:
            title = window.get_title()
        except TclError:
            continue
        list.append((title, key, window))
    list.sort()
    for title, key, window in list:
        menu.add_command(label=title, command=window.wakeup)

def unregister_callback(self, callback):
    try:
        self.callbacks.remove(callback)
    except ValueError:
        pass

def call_callbacks(self):
    for callback in self.callbacks:
        try:
            callback()
        except:
            t, v, tb = sys.exc_info()
            print('warning: callback failed in WindowList', t, ':', v)

def destroy(self):
    registry.delete(self)
    Toplevel.destroy(self)
    if not registry.dict:
        self.quit()

def wakeup(self):
    try:
        if self.wm_state() == 'iconic':
            self.wm_withdraw()
            self.wm_deiconify()
        self.tkraise()
        self.focused_widget.focus_set()
    except TclError:
        pass

def get_window_geometry(top):
    geom = top.wm_geometry()
    m = re.match('(\\d+)x(\\d+)\\+(-?\\d+)\\+(-?\\d+)', geom)
    return tuple(map(int, m.groups()))

def __init__(self, editwin):
    self.editwin = editwin
    self.top = self.editwin.top

def zoom_height_event(self, event=None):
    zoomed = self.zoom_height()
    if zoomed is None:
        self.top.bell()
    else:
        menu_status = 'Restore' if zoomed else 'Zoom'
        self.editwin.update_menu_label(menu='options', index='* Height', label=f'{menu_status} Height')
    return 'break'

def zoom_height(self):
    top = self.top
    width, height, x, y = get_window_geometry(top)
    if top.wm_state() != 'normal':
        return None
    try:
        maxheight, maxy = self.get_max_height_and_y_coord()
    except WmInfoGatheringError:
        return None
    if height != maxheight:
        set_window_geometry(top, (width, maxheight, x, maxy))
        return True
    else:
        top.wm_geometry('')
        return False

def format_selection(format_line):
    """Apply a formatting function to all of the selected lines."""
    @wraps(format_line)
    def apply(self, event=None):
        head, tail, chars, lines = self.formatter.get_region()
        for pos in range(len(lines) - 1):
            line = lines[pos]
            lines[pos] = format_line(self, line)
        self.formatter.set_region(head, tail, chars, lines)
        return 'break'
    return apply

@wraps(format_line)
def apply(self, event=None):
    head, tail, chars, lines = self.formatter.get_region()
    for pos in range(len(lines) - 1):
        line = lines[pos]
        lines[pos] = format_line(self, line)
    self.formatter.set_region(head, tail, chars, lines)
    return 'break'

@classmethod
def reload(cls):
    """Load class variables from config."""
    cls.ztext = idleConf.GetOption('extensions', 'ZzDummy', 'z-text')

@format_selection
def z_in_event(self, line):
    """Insert text at the beginning of each selected line.

    This is bound to the <<z-in>> virtual event when the extensions
    are loaded."""
    return f'{self.ztext}{line}'

def ParseFlags(resp):
    """Convert IMAP4 flags response to python tuple."""
    mo = Flags.match(resp)
    if not mo:
        return ()
    return tuple(mo.group('flags').split())

def Time2Internaldate(date_time):
    """Convert date_time to IMAP4 INTERNALDATE representation.

    Return string in form: '"DD-Mmm-YYYY HH:MM:SS +HHMM"'.  The
    date_time argument can be a number (int or float) representing
    seconds since epoch (as returned by time.time()), a 9-tuple
    representing local time, an instance of time.struct_time (as
    returned by time.localtime()), an aware datetime instance or a
    double-quoted string.  In the last case, it is assumed to already
    be in the correct format."""
    if isinstance(date_time, (int, float)):
        dt = datetime.fromtimestamp(date_time, timezone.utc).astimezone()
    elif isinstance(date_time, tuple):
        try:
            gmtoff = date_time.tm_gmtoff
        except AttributeError:
            if time.daylight:
                dst = date_time[8]
                if dst == -1:
                    dst = time.localtime(time.mktime(date_time))[8]
                gmtoff = -(time.timezone, time.altzone)[dst]
            else:
                gmtoff = -time.timezone
        delta = timedelta(seconds=gmtoff)
        dt = datetime(*date_time[:6], tzinfo=timezone(delta))
    elif isinstance(date_time, datetime):
        if date_time.tzinfo is None:
            raise ValueError('date_time must be aware')
        dt = date_time
    elif isinstance(date_time, str) and (date_time[0], date_time[-1]) == ('"', '"'):
        return date_time
    else:
        raise ValueError('date_time not of a known type')
    fmt = '"%d-{}-%Y %H:%M:%S %z"'.format(Months[dt.month])
    return dt.strftime(fmt)

def __init__(self, host='', port=IMAP4_PORT, timeout=None):
    self.debug = Debug
    self.state = 'LOGOUT'
    self.literal = None
    self.tagged_commands = {}
    self.untagged_responses = {}
    self.continuation_response = ''
    self.is_readonly = False
    self.tagnum = 0
    self._tls_established = False
    self._mode_ascii()
    self.open(host, port, timeout)
    try:
        self._connect()
    except Exception:
        try:
            self.shutdown()
        except OSError:
            pass
        raise

def _connect(self):
    self.tagpre = Int2AP(random.randint(4096, 65535))
    self.tagre = re.compile(b'(?P<tag>' + self.tagpre + b'\\d+) (?P<type>[A-Z]+) (?P<data>.*)', re.ASCII)
    if __debug__:
        self._cmd_log_len = 10
        self._cmd_log_idx = 0
        self._cmd_log = {}
        if self.debug >= 1:
            self._mesg('imaplib version %s' % __version__)
            self._mesg('new IMAP4 connection, tag=%s' % self.tagpre)
    self.welcome = self._get_response()
    if 'PREAUTH' in self.untagged_responses:
        self.state = 'AUTH'
    elif 'OK' in self.untagged_responses:
        self.state = 'NONAUTH'
    else:
        raise self.error(self.welcome)
    self._get_capabilities()
    if __debug__:
        if self.debug >= 3:
            self._mesg('CAPABILITIES: %r' % (self.capabilities,))
    for version in AllowedVersions:
        if not version in self.capabilities:
            continue
        self.PROTOCOL_VERSION = version
        return
    raise self.error('server not IMAP4 compliant')

def __getattr__(self, attr):
    if attr in Commands:
        return getattr(self, attr.lower())
    raise AttributeError("Unknown IMAP4 command: '%s'" % attr)

def __exit__(self, *args):
    if self.state == 'LOGOUT':
        return
    try:
        self.logout()
    except OSError:
        pass

def _create_socket(self, timeout):
    if timeout is not None and (not timeout):
        raise ValueError('Non-blocking socket (timeout=0) is not supported')
    host = None if not self.host else self.host
    sys.audit('imaplib.open', self, self.host, self.port)
    address = (host, self.port)
    if timeout is not None:
        return socket.create_connection(address, timeout)
    return socket.create_connection(address)

def readline(self):
    """Read line from remote."""
    line = self.file.readline(_MAXLINE + 1)
    if len(line) > _MAXLINE:
        raise self.error('got more than %d bytes' % _MAXLINE)
    return line

def shutdown(self):
    """Close I/O established in "open"."""
    self.file.close()
    try:
        self.sock.shutdown(socket.SHUT_RDWR)
    except OSError as exc:
        if exc.errno != errno.ENOTCONN and getattr(exc, 'winerror', 0) != 10022:
            raise
    finally:
        self.sock.close()

def recent(self):
    """Return most recent 'RECENT' responses if any exist,
    else prompt server for an update using the 'NOOP' command.

    (typ, [data]) = <instance>.recent()

    'data' is None if no new messages,
    else list of RECENT responses, most recent last."""
    name = 'RECENT'
    typ, dat = self._untagged_response('OK', [None], name)
    if dat[-1]:
        return (typ, dat)
    typ, dat = self.noop()
    return self._untagged_response(typ, dat, name)

def response(self, code):
    """Return data for response 'code' if received, or None.

    Old value for response 'code' is cleared.

    (code, [data]) = <instance>.response(code)"""
    return self._untagged_response(code, [None], code.upper())

def append(self, mailbox, flags, date_time, message):
    """Append message to named mailbox.

    (typ, [data]) = <instance>.append(mailbox, flags, date_time, message)

            All args except `message' can be None."""
    name = 'APPEND'
    if not mailbox:
        mailbox = 'INBOX'
    if flags:
        if (flags[0], flags[-1]) != ('(', ')'):
            flags = '(%s)' % flags
    else:
        flags = None
    if date_time:
        date_time = Time2Internaldate(date_time)
    else:
        date_time = None
    literal = MapCRLF.sub(CRLF, message)
    if self.utf8_enabled:
        literal = b'UTF8 (' + literal + b')'
    self.literal = literal
    return self._simple_command(name, mailbox, flags, date_time)

def capability(self):
    """(typ, [data]) = <instance>.capability()
    Fetch capabilities list from server."""
    name = 'CAPABILITY'
    typ, dat = self._simple_command(name)
    return self._untagged_response(typ, dat, name)

def check(self):
    """Checkpoint mailbox on server.

    (typ, [data]) = <instance>.check()"""
    return self._simple_command('CHECK')

def close(self):
    """Close currently selected mailbox.

    Deleted messages are removed from writable mailbox.
    This is the recommended command before 'LOGOUT'.

    (typ, [data]) = <instance>.close()"""
    try:
        typ, dat = self._simple_command('CLOSE')
    finally:
        self.state = 'AUTH'
    return (typ, dat)

def copy(self, message_set, new_mailbox):
    """Copy 'message_set' messages onto end of 'new_mailbox'.

    (typ, [data]) = <instance>.copy(message_set, new_mailbox)"""
    return self._simple_command('COPY', message_set, new_mailbox)

def create(self, mailbox):
    """Create new mailbox.

    (typ, [data]) = <instance>.create(mailbox)"""
    return self._simple_command('CREATE', mailbox)

def delete(self, mailbox):
    """Delete old mailbox.

    (typ, [data]) = <instance>.delete(mailbox)"""
    return self._simple_command('DELETE', mailbox)

def deleteacl(self, mailbox, who):
    """Delete the ACLs (remove any rights) set for who on mailbox.

    (typ, [data]) = <instance>.deleteacl(mailbox, who)"""
    return self._simple_command('DELETEACL', mailbox, who)

def enable(self, capability):
    """Send an RFC5161 enable string to the server.

    (typ, [data]) = <instance>.enable(capability)"""
    if 'ENABLE' not in self.capabilities:
        raise IMAP4.error('Server does not support ENABLE')
    typ, data = self._simple_command('ENABLE', capability)
    if typ == 'OK' and 'UTF8=ACCEPT' in capability.upper():
        self._mode_utf8()
    return (typ, data)

def getacl(self, mailbox):
    """Get the ACLs for a mailbox.

    (typ, [data]) = <instance>.getacl(mailbox)"""
    typ, dat = self._simple_command('GETACL', mailbox)
    return self._untagged_response(typ, dat, 'ACL')

def getannotation(self, mailbox, entry, attribute):
    """(typ, [data]) = <instance>.getannotation(mailbox, entry, attribute)
    Retrieve ANNOTATIONs."""
    typ, dat = self._simple_command('GETANNOTATION', mailbox, entry, attribute)
    return self._untagged_response(typ, dat, 'ANNOTATION')

def getquota(self, root):
    """Get the quota root's resource usage and limits.

    Part of the IMAP4 QUOTA extension defined in rfc2087.

    (typ, [data]) = <instance>.getquota(root)"""
    typ, dat = self._simple_command('GETQUOTA', root)
    return self._untagged_response(typ, dat, 'QUOTA')

def login(self, user, password):
    """Identify client using plaintext password.

    (typ, [data]) = <instance>.login(user, password)

    NB: 'password' will be quoted."""
    typ, dat = self._simple_command('LOGIN', user, self._quote(password))
    if typ != 'OK':
        raise self.error(dat[-1])
    self.state = 'AUTH'
    return (typ, dat)

def login_cram_md5(self, user, password):
    """Force use of CRAM-MD5 authentication.

    (typ, [data]) = <instance>.login_cram_md5(user, password)"""
    self.user, self.password = (user, password)
    return self.authenticate('CRAM-MD5', self._CRAM_MD5_AUTH)

def _CRAM_MD5_AUTH(self, challenge):
    """Authobject to use with CRAM-MD5 authentication."""
    import hmac
    pwd = self.password.encode('utf-8') if isinstance(self.password, str) else self.password
    return self.user + ' ' + hmac.HMAC(pwd, challenge, 'md5').hexdigest()

def myrights(self, mailbox):
    """Show my ACLs for a mailbox (i.e. the rights that I have on mailbox).

    (typ, [data]) = <instance>.myrights(mailbox)"""
    typ, dat = self._simple_command('MYRIGHTS', mailbox)
    return self._untagged_response(typ, dat, 'MYRIGHTS')

def namespace(self):
    """Returns IMAP namespaces ala rfc2342

    (typ, [data, ...]) = <instance>.namespace()"""
    name = 'NAMESPACE'
    typ, dat = self._simple_command(name)
    return self._untagged_response(typ, dat, name)

def noop(self):
    """Send NOOP command.

    (typ, [data]) = <instance>.noop()"""
    if __debug__:
        if self.debug >= 3:
            self._dump_ur(self.untagged_responses)
    return self._simple_command('NOOP')

def rename(self, oldmailbox, newmailbox):
    """Rename old mailbox name to new.

    (typ, [data]) = <instance>.rename(oldmailbox, newmailbox)"""
    return self._simple_command('RENAME', oldmailbox, newmailbox)

def search(self, charset, *criteria):
    """Search mailbox for matching messages.

    (typ, [data]) = <instance>.search(charset, criterion, ...)

    'data' is space separated list of matching message numbers.
    If UTF8 is enabled, charset MUST be None."""
    name = 'SEARCH'
    if charset:
        if self.utf8_enabled:
            raise IMAP4.error('Non-None charset not valid in UTF8 mode')
        typ, dat = self._simple_command(name, 'CHARSET', charset, *criteria)
    else:
        typ, dat = self._simple_command(name, *criteria)
    return self._untagged_response(typ, dat, name)

def setacl(self, mailbox, who, what):
    """Set a mailbox acl.

    (typ, [data]) = <instance>.setacl(mailbox, who, what)"""
    return self._simple_command('SETACL', mailbox, who, what)

def setannotation(self, *args):
    """(typ, [data]) = <instance>.setannotation(mailbox[, entry, attribute]+)
    Set ANNOTATIONs."""
    typ, dat = self._simple_command('SETANNOTATION', *args)
    return self._untagged_response(typ, dat, 'ANNOTATION')

def sort(self, sort_criteria, charset, *search_criteria):
    """IMAP4rev1 extension SORT command.

    (typ, [data]) = <instance>.sort(sort_criteria, charset, search_criteria, ...)"""
    name = 'SORT'
    if (sort_criteria[0], sort_criteria[-1]) != ('(', ')'):
        sort_criteria = '(%s)' % sort_criteria
    typ, dat = self._simple_command(name, sort_criteria, charset, *search_criteria)
    return self._untagged_response(typ, dat, name)

def starttls(self, ssl_context=None):
    name = 'STARTTLS'
    if not HAVE_SSL:
        raise self.error('SSL support missing')
    if self._tls_established:
        raise self.abort('TLS session already established')
    if name not in self.capabilities:
        raise self.abort('TLS not supported by server')
    if ssl_context is None:
        ssl_context = ssl._create_stdlib_context()
    typ, dat = self._simple_command(name)
    if typ == 'OK':
        self.sock = ssl_context.wrap_socket(self.sock, server_hostname=self.host)
        self.file = self.sock.makefile('rb')
        self._tls_established = True
        self._get_capabilities()
    else:
        raise self.error("Couldn't establish TLS session")
    return self._untagged_response(typ, dat, name)

def store(self, message_set, command, flags):
    """Alters flag dispositions for messages in mailbox.

    (typ, [data]) = <instance>.store(message_set, command, flags)"""
    if (flags[0], flags[-1]) != ('(', ')'):
        flags = '(%s)' % flags
    typ, dat = self._simple_command('STORE', message_set, command, flags)
    return self._untagged_response(typ, dat, 'FETCH')

def subscribe(self, mailbox):
    """Subscribe to new mailbox.

    (typ, [data]) = <instance>.subscribe(mailbox)"""
    return self._simple_command('SUBSCRIBE', mailbox)

def thread(self, threading_algorithm, charset, *search_criteria):
    """IMAPrev1 extension THREAD command.

    (type, [data]) = <instance>.thread(threading_algorithm, charset, search_criteria, ...)"""
    name = 'THREAD'
    typ, dat = self._simple_command(name, threading_algorithm, charset, *search_criteria)
    return self._untagged_response(typ, dat, name)

def uid(self, command, *args):
    """Execute "command arg ..." with messages identified by UID,
            rather than message number.

    (typ, [data]) = <instance>.uid(command, arg1, arg2, ...)

    Returns response appropriate to 'command'."""
    command = command.upper()
    if not command in Commands:
        raise self.error('Unknown IMAP4 UID command: %s' % command)
    if self.state not in Commands[command]:
        raise self.error('command %s illegal in state %s, only allowed in states %s' % (command, self.state, ', '.join(Commands[command])))
    name = 'UID'
    typ, dat = self._simple_command(name, command, *args)
    if command in ('SEARCH', 'SORT', 'THREAD'):
        name = command
    else:
        name = 'FETCH'
    return self._untagged_response(typ, dat, name)

def xatom(self, name, *args):
    """Allow simple extension commands
            notified by server in CAPABILITY response.

    Assumes command is legal in current state.

    (typ, [data]) = <instance>.xatom(name, arg, ...)

    Returns response appropriate to extension command `name'."""
    name = name.upper()
    if not name in Commands:
        Commands[name] = (self.state,)
    return self._simple_command(name, *args)

def _append_untagged(self, typ, dat):
    if dat is None:
        dat = b''
    ur = self.untagged_responses
    if __debug__:
        if self.debug >= 5:
            self._mesg('untagged_responses[%s] %s += ["%r"]' % (typ, len(ur.get(typ, '')), dat))
    if typ in ur:
        ur[typ].append(dat)
    else:
        ur[typ] = [dat]

def _check_bye(self):
    bye = self.untagged_responses.get('BYE')
    if bye:
        raise self.abort(bye[-1].decode(self._encoding, 'replace'))

def _command_complete(self, name, tag):
    logout = name == 'LOGOUT'
    if not logout:
        self._check_bye()
    try:
        typ, data = self._get_tagged_response(tag, expect_bye=logout)
    except self.abort as val:
        raise self.abort('command: %s => %s' % (name, val))
    except self.error as val:
        raise self.error('command: %s => %s' % (name, val))
    if not logout:
        self._check_bye()
    if typ == 'BAD':
        raise self.error('%s command error: %s %s' % (name, typ, data))
    return (typ, data)

def _get_tagged_response(self, tag, expect_bye=False):
    while 1:
        result = self.tagged_commands[tag]
        if result is not None:
            del self.tagged_commands[tag]
            return result
        if expect_bye:
            typ = 'BYE'
            bye = self.untagged_responses.pop(typ, None)
            if bye is not None:
                return (typ, bye)
        self._check_bye()
        try:
            self._get_response()
        except self.abort as val:
            if __debug__:
                if self.debug >= 1:
                    self.print_log()
            raise

def _get_line(self):
    line = self.readline()
    if not line:
        raise self.abort('socket error: EOF')
    if not line.endswith(b'\r\n'):
        raise self.abort('socket error: unterminated line: %r' % line)
    line = line[:-2]
    if __debug__:
        if self.debug >= 4:
            self._mesg('< %r' % line)
        else:
            self._log('< %r' % line)
    return line

def _match(self, cre, s):
    self.mo = cre.match(s)
    if __debug__:
        if self.mo is not None and self.debug >= 5:
            self._mesg('\tmatched %r => %r' % (cre.pattern, self.mo.groups()))
    return self.mo is not None

def _untagged_response(self, typ, dat, name):
    if typ == 'NO':
        return (typ, dat)
    if not name in self.untagged_responses:
        return (typ, [None])
    data = self.untagged_responses.pop(name)
    if __debug__:
        if self.debug >= 5:
            self._mesg('untagged_responses[%s] => %s' % (name, data))
    return (typ, data)

def __init__(self, command):
    self.command = command
    IMAP4.__init__(self)

def read(self, size):
    """Read 'size' bytes from remote."""
    return self.readfile.read(size)

def readline(self):
    """Read line from remote."""
    return self.readfile.readline()

def process(self, data):
    ret = self.mech(self.decode(data))
    if ret is None:
        return b'*'
    return self.encode(ret)

def encode(self, inp):
    oup = b''
    if isinstance(inp, str):
        inp = inp.encode('utf-8')
    while inp:
        if len(inp) > 48:
            t = inp[:48]
            inp = inp[48:]
        else:
            t = inp
            inp = b''
        e = binascii.b2a_base64(t)
        if e:
            oup = oup + e[:-1]
    return oup

def decode(self, inp):
    if not inp:
        return b''
    return binascii.a2b_base64(inp)

def _mesg(self, s, secs=None):
    if secs is None:
        secs = time.time()
    tm = time.strftime('%M:%S', time.localtime(secs))
    sys.stderr.write('  %s.%02d %s\n' % (tm, secs * 100 % 100, s))
    sys.stderr.flush()

def _dump_ur(self, untagged_resp_dict):
    if not untagged_resp_dict:
        return
    items = (f'{key}: {value!r}' for key, value in untagged_resp_dict.items())
    self._mesg('untagged responses dump:' + '\n\t\t'.join(items))

def _log(self, line):
    self._cmd_log[self._cmd_log_idx] = (line, time.time())
    self._cmd_log_idx += 1
    if self._cmd_log_idx >= self._cmd_log_len:
        self._cmd_log_idx = 0

def print_log(self):
    self._mesg('last %d IMAP4 interactions:' % len(self._cmd_log))
    i, n = (self._cmd_log_idx, self._cmd_log_len)
    while n:
        try:
            self._mesg(*self._cmd_log[i])
        except:
            pass
        i += 1
        if i >= self._cmd_log_len:
            i = 0
        n -= 1

def _create_socket(self, timeout):
    sock = IMAP4._create_socket(self, timeout)
    return self.ssl_context.wrap_socket(sock, server_hostname=self.host)

def what(file, h=None):
    """Return the type of image contained in a file or byte stream."""
    f = None
    try:
        if h is None:
            if isinstance(file, (str, PathLike)):
                f = open(file, 'rb')
                h = f.read(32)
            else:
                location = file.tell()
                h = file.read(32)
                file.seek(location)
        for tf in tests:
            res = tf(h, f)
            if res:
                return res
    finally:
        if f:
            f.close()
    return None

