    elif 'map_lambda' in results:
        new = ListComp(results['xp'].clone(), results['fp'].clone(), results['it'].clone())
        new = Node(syms.power, [new] + trailers, prefix='')
    else:
        if 'map_none' in results:
            new = results['arg'].clone()
