    sep = end = file = None
    if args and args[-1] == Comma():
        args = args[:-1]
        end = ' '
    if args and args[0] == pytree.Leaf(token.RIGHTSHIFT, '>>'):
        assert len(args) >= 2
        file = args[1].clone()
        args = args[3:]
    l_args = [arg.clone() for arg in args]
    if l_args:
        l_args[0].prefix = ''
    if sep is not None or end is not None or file is not None:
        if sep is not None:
