    args = results['args'].clone()
    args.prefix = ''
    trailers = []
    if 'trailers' in results:
        trailers = [n.clone() for n in results['trailers']]
        for n in trailers:
            n.prefix = ''
    new = Node(syms.power, [Name('zip'), args], prefix='')
    new = Node(syms.power, [Name('list'), ArgList([new])] + trailers)
    new.prefix = node.prefix
    return new

def diff_texts(a, b, filename):
    """Return a unified diff of two strings."""
    a = a.splitlines()
    b = b.splitlines()
    return difflib.unified_diff(a, b, filename, filename, '(original)', '(refactored)', lineterm='')

def log_error(self, msg, *args, **kwargs):
    self.errors.append((msg, args, kwargs))
    self.logger.error(msg, *args, **kwargs)

def write_file(self, new_text, filename, old_text, encoding):
    orig_filename = filename
    if self._output_dir:
        if filename.startswith(self._input_base_dir):
            filename = os.path.join(self._output_dir, filename[len(self._input_base_dir):])
        else:
            raise ValueError('filename %s does not start with the input_base_dir %s' % (filename, self._input_base_dir))
    if self._append_suffix:
        filename += self._append_suffix
    if orig_filename != filename:
        output_dir = os.path.dirname(filename)
        if not os.path.isdir(output_dir) and output_dir:
            os.makedirs(output_dir)
        self.log_message('Writing converted %s to %s.', orig_filename, filename)
    if not self.nobackups:
        backup = filename + '.bak'
        if os.path.lexists(backup):
            try:
                os.remove(backup)
            except OSError:
                self.log_message("Can't remove backup %s", backup)
        try:
            os.rename(filename, backup)
        except OSError:
            self.log_message("Can't rename %s to %s", filename, backup)
    write = super(StdoutRefactoringTool, self).write_file
    write(new_text, filename, old_text, encoding)
    if not self.nobackups:
        shutil.copymode(backup, filename)
    if orig_filename != filename:
        shutil.copymode(orig_filename, filename)

def print_output(self, old, new, filename, equal):
    if equal:
        self.log_message('No changes to %s', filename)
    else:
        self.log_message('Refactored %s', filename)
        if self.show_diffs:
            diff_lines = diff_texts(old, new, filename)
            try:
                if self.output_lock is not None:
                    with self.output_lock:
                        for line in diff_lines:
                            print(line)
                        sys.stdout.flush()
                else:
                    for line in diff_lines:
                        print(line)
            except UnicodeEncodeError:
                warn("couldn't encode %s's diff for your terminal" % (filename,))
                return

def tokenize_wrapper(input):
    """Tokenizes a string suppressing significant whitespace."""
    skip = {token.NEWLINE, token.INDENT, token.DEDENT}
    tokens = tokenize.generate_tokens(io.StringIO(input).readline)
    for quintuple in tokens:
        type, value, start, end, line_text = quintuple
        if type not in skip:
            yield quintuple

def _type_of_literal(value):
    if value[0].isalpha():
        return token.NAME
    elif value in grammar.opmap:
        return grammar.opmap[value]
    else:
        return None

def pattern_convert(grammar, raw_node_info):
    """Converts raw node information to a Node or Leaf instance."""
    type, value, context, children = raw_node_info
    if children or type in grammar.number2symbol:
        return pytree.Node(type, children, context=context)
    else:
        return pytree.Leaf(type, value, context=context)

def compile_pattern(self, input, debug=False, with_tree=False):
    """Compiles a pattern string to a nested pytree.*Pattern object."""
    tokens = tokenize_wrapper(input)
    try:
        root = self.driver.parse_tokens(tokens, debug=debug)
    except parse.ParseError as e:
        raise PatternSyntaxError(str(e)) from None
    if with_tree:
        return (self.compile_node(root), root)
    else:
        return self.compile_node(root)

def get_int(self, node):
    assert node.type == token.NUMBER
    return int(node.value)

def parse_graminit_h(self, filename):
    """Parse the .h file written by pgen.  (Internal)

    This file is a sequence of #define statements defining the
    nonterminals of the grammar as numbers.  We build two tables
    mapping the numbers to names and back."""
    try:
        f = open(filename)
    except OSError as err:
        print("Can't open %s: %s" % (filename, err))
        return False
    self.symbol2number = {}
    self.number2symbol = {}
    lineno = 0
    for line in f:
        lineno += 1
        mo = re.match('^#define\\s+(\\w+)\\s+(\\d+)$', line)
        if not mo and line.strip():
            print("%s(%s): can't parse %s" % (filename, lineno, line.strip()))
        else:
            symbol, number = mo.groups()
            number = int(number)
            assert symbol not in self.symbol2number
            assert number not in self.number2symbol
            self.symbol2number[symbol] = number
            self.number2symbol[number] = symbol
    return True

def finish_off(self):
    """Create additional useful structures.  (Internal)."""
    self.keywords = {}
    self.tokens = {}
    for ilabel, (type, value) in enumerate(self.labels):
        if type == token.NAME and value is not None:
            self.keywords[value] = ilabel
        elif value is None:
            self.tokens[type] = ilabel

def _generate_pickle_name(gt):
    head, tail = os.path.splitext(gt)
    if tail == '.txt':
        tail = ''
    return head + tail + '.'.join(map(str, sys.version_info)) + '.pickle'

def load_grammar(gt='Grammar.txt', gp=None, save=True, force=False, logger=None):
    """Load the grammar (maybe from a pickle)."""
    if logger is None:
        logger = logging.getLogger()
    gp = _generate_pickle_name(gt) if gp is None else gp
    if force or not _newer(gp, gt):
        logger.info('Generating grammar tables from %s', gt)
        g = pgen.generate_grammar(gt)
        if save:
            logger.info('Writing grammar tables to %s', gp)
            try:
                g.dump(gp)
            except OSError as e:
                logger.info('Writing failed: %s', e)
    else:
        g = grammar.Grammar()
        g.load(gp)
    return g

def _newer(a, b):
    """Inquire whether file a was written since file b."""
    if not os.path.exists(a):
        return False
    if not os.path.exists(b):
        return True
    return os.path.getmtime(a) >= os.path.getmtime(b)

def main(*args):
    """Main program, when run as a script: produce grammar pickle files.

    Calls load_grammar for each argument, a path to a grammar text file."""
    if not args:
        args = sys.argv[1:]
    logging.basicConfig(level=logging.INFO, stream=sys.stdout, format='%(message)s')
    for gt in args:
        load_grammar(gt, save=True, force=True)
    return True

def __init__(self, grammar, convert=None, logger=None):
    self.grammar = grammar
    if logger is None:
        logger = logging.getLogger()
    self.logger = logger
    self.convert = convert

def parse_stream_raw(self, stream, debug=False):
    """Parse a stream and return the syntax tree."""
    tokens = tokenize.generate_tokens(stream.readline)
    return self.parse_tokens(tokens, debug)

def parse_stream(self, stream, debug=False):
    """Parse a stream and return the syntax tree."""
    return self.parse_stream_raw(stream, debug)

def parse_file(self, filename, encoding=None, debug=False):
    """Parse a file and return the syntax tree."""
    with io.open(filename, 'r', encoding=encoding) as stream:
        return self.parse_stream(stream, debug)

def parse_string(self, text, debug=False):
    """Parse a string and return the syntax tree."""
    tokens = tokenize.generate_tokens(io.StringIO(text).readline)
    return self.parse_tokens(tokens, debug)

def __init__(self):
    self.symbol2number = {}
    self.number2symbol = {}
    self.states = []
    self.dfas = {}
    self.labels = [(0, 'EMPTY')]
    self.keywords = {}
    self.tokens = {}
    self.symbol2label = {}
    self.start = 256

def loads(self, pkl):
    """Load the grammar tables from a pickle bytes object."""
    self.__dict__.update(pickle.loads(pkl))

def escape(m):
    all, tail = m.group(0, 1)
    assert all.startswith('\\')
    esc = simple_escapes.get(tail)
    if esc is not None:
        return esc
    if tail.startswith('x'):
        hexes = tail[1:]
        if len(hexes) < 2:
            raise ValueError("invalid hex string escape ('\\%s')" % tail)
        try:
            i = int(hexes, 16)
        except ValueError:
            raise ValueError("invalid hex string escape ('\\%s')" % tail) from None
    else:
        try:
            i = int(tail, 8)
        except ValueError:
            raise ValueError("invalid octal string escape ('\\%s')" % tail) from None
    return chr(i)

def evalString(s):
    assert s.startswith("'") or s.startswith('"'), repr(s[:1])
    q = s[0]
    if s[:3] == q * 3:
        q = q * 3
    assert s.endswith(q), repr(s[-len(q):])
    assert len(s) >= 2 * len(q)
    s = s[len(q):-len(q)]
    return re.sub('\\\\(\\\'|\\"|\\\\|[abfnrtv]|x.{0,2}|[0-7]{1,3})', escape, s)

def test():
    for i in range(256):
        c = chr(i)
        s = repr(c)
        e = evalString(s)
        if e != c:
            print(i, c, s, e)

def addtoken(self, type, value, context):
    """Add a token; return True iff this is the end of the program."""
    ilabel = self.classify(type, value, context)
    while True:
        dfa, state, node = self.stack[-1]
        states, first = dfa
        arcs = states[state]
        for i, newstate in arcs:
            t, v = self.grammar.labels[i]
            if ilabel == i:
                assert t < 256
                self.shift(type, value, newstate, context)
                state = newstate
                while states[state] == [(0, state)]:
                    self.pop()
                    if not self.stack:
                        return True
                    dfa, state, node = self.stack[-1]
                    states, first = dfa
                return False
            elif t >= 256:
                itsdfa = self.grammar.dfas[t]
                itsstates, itsfirst = itsdfa
                if ilabel in itsfirst:
                    self.push(t, self.grammar.dfas[t], newstate, context)
                    break
        else:
            if (0, state) in arcs:
                self.pop()
                if not self.stack:
                    raise ParseError('too much input', type, value, context)
            else:
                raise ParseError('bad input', type, value, context)

def classify(self, type, value, context):
    """Turn a token into a label.  (Internal)"""
    if type == token.NAME:
        self.used_names.add(value)
        ilabel = self.grammar.keywords.get(value)
        if ilabel is not None:
            return ilabel
    ilabel = self.grammar.tokens.get(type)
    if ilabel is None:
        raise ParseError('bad token', type, value, context)
    return ilabel

def pop(self):
    """Pop a nonterminal.  (Internal)"""
    popdfa, popstate, popnode = self.stack.pop()
    newnode = self.convert(self.grammar, popnode)
    if newnode is not None:
        if self.stack:
            dfa, state, node = self.stack[-1]
            node[-1].append(newnode)
        else:
            self.rootnode = newnode
            self.rootnode.used_names = self.used_names

def generate_grammar(filename='Grammar.txt'):
    p = ParserGenerator(filename)
    return p.make_grammar()

def make_first(self, c, name):
    rawfirst = self.first[name]
    first = {}
    for label in sorted(rawfirst):
        ilabel = self.make_label(c, label)
        first[ilabel] = 1
    return first

def make_label(self, c, label):
    ilabel = len(c.labels)
    if label[0].isalpha():
        if label in c.symbol2number:
            if label in c.symbol2label:
                return c.symbol2label[label]
            else:
                c.labels.append((c.symbol2number[label], None))
                c.symbol2label[label] = ilabel
                return ilabel
        else:
            itoken = getattr(token, label, None)
            assert isinstance(itoken, int), label
            assert itoken in token.tok_name, label
            if itoken in c.tokens:
                return c.tokens[itoken]
            else:
                c.labels.append((itoken, None))
                c.tokens[itoken] = ilabel
                return ilabel
    else:
        assert label[0] in ('"', "'"), label
        value = eval(label)
        if value[0].isalpha():
            if value in c.keywords:
                return c.keywords[value]
            else:
                c.labels.append((token.NAME, value))
                c.keywords[value] = ilabel
                return ilabel
        else:
            itoken = grammar.opmap[value]
            if itoken in c.tokens:
                return c.tokens[itoken]
            else:
                c.labels.append((itoken, None))
                c.tokens[itoken] = ilabel
                return ilabel

def addfirstsets(self):
    names = list(self.dfas.keys())
    names.sort()
    for name in names:
        if name not in self.first:
            self.calcfirst(name)

def calcfirst(self, name):
    dfa = self.dfas[name]
    self.first[name] = None
    state = dfa[0]
    totalset = {}
    overlapcheck = {}
    for label, next in state.arcs.items():
        if label in self.dfas:
            if label in self.first:
                fset = self.first[label]
                if fset is None:
                    raise ValueError('recursion for rule %r' % name)
            else:
                self.calcfirst(label)
                fset = self.first[label]
            totalset.update(fset)
            overlapcheck[label] = fset
        else:
            totalset[label] = 1
            overlapcheck[label] = {label: 1}
    inverse = {}
    for label, itsfirst in overlapcheck.items():
        for symbol in itsfirst:
            if symbol in inverse:
                raise ValueError('rule %s is ambiguous; %s is in the first sets of %s as well as %s' % (name, symbol, label, inverse[symbol]))
            inverse[symbol] = label
    self.first[name] = totalset

def parse(self):
    dfas = {}
    startsymbol = None
    while self.type != token.ENDMARKER:
        while self.type == token.NEWLINE:
            self.gettoken()
        name = self.expect(token.NAME)
        self.expect(token.OP, ':')
        a, z = self.parse_rhs()
        self.expect(token.NEWLINE)
        dfa = self.make_dfa(a, z)
        oldlen = len(dfa)
        self.simplify_dfa(dfa)
        newlen = len(dfa)
        dfas[name] = dfa
        if startsymbol is None:
            startsymbol = name
    return (dfas, startsymbol)

def make_dfa(self, start, finish):
    assert isinstance(start, NFAState)
    assert isinstance(finish, NFAState)
    def closure(state):
        base = {}
        addclosure(state, base)
        return base
    def addclosure(state, base):
        assert isinstance(state, NFAState)
        if state in base:
            return
        base[state] = 1
        for label, next in state.arcs:
            if label is None:
                addclosure(next, base)
    states = [DFAState(closure(start), finish)]
    for state in states:
        arcs = {}
        for nfastate in state.nfaset:
            for label, next in nfastate.arcs:
                if label is not None:
                    addclosure(next, arcs.setdefault(label, {}))
        for label, nfaset in sorted(arcs.items()):
            for st in states:
                if st.nfaset == nfaset:
                    break
            else:
                st = DFAState(nfaset, finish)
                states.append(st)
            state.addarc(st, label)
    return states

def dump_dfa(self, name, dfa):
    print('Dump of DFA for', name)
    for i, state in enumerate(dfa):
        print('  State', i, state.isfinal and '(final)' or '')
        for label, next in sorted(state.arcs.items()):
            print('    %s -> %d' % (label, dfa.index(next)))

def simplify_dfa(self, dfa):
    changes = True
    while changes:
        changes = False
        for i, state_i in enumerate(dfa):
            for j in range(i + 1, len(dfa)):
                state_j = dfa[j]
                if state_i == state_j:
                    del dfa[j]
                    for state in dfa:
                        state.unifystate(state_j, state_i)
                    changes = True
                    break

def parse_rhs(self):
    a, z = self.parse_alt()
    if self.value != '|':
        return (a, z)
    else:
        aa = NFAState()
        zz = NFAState()
        aa.addarc(a)
        z.addarc(zz)
        while self.value == '|':
            self.gettoken()
            a, z = self.parse_alt()
            aa.addarc(a)
            z.addarc(zz)
        return (aa, zz)

def parse_alt(self):
    a, b = self.parse_item()
    while self.value in ('(', '[') or self.type in (token.NAME, token.STRING):
        c, d = self.parse_item()
        b.addarc(c)
        b = d
    return (a, b)

def parse_item(self):
    if self.value == '[':
        self.gettoken()
        a, z = self.parse_rhs()
        self.expect(token.OP, ']')
        a.addarc(z)
        return (a, z)
    else:
        a, z = self.parse_atom()
        value = self.value
        if value not in ('+', '*'):
            return (a, z)
        self.gettoken()
        z.addarc(a)
        if value == '+':
            return (a, z)
        else:
            return (a, a)

def parse_atom(self):
    if self.value == '(':
        self.gettoken()
        a, z = self.parse_rhs()
        self.expect(token.OP, ')')
        return (a, z)
    elif self.type in (token.NAME, token.STRING):
        a = NFAState()
        z = NFAState()
        a.addarc(z, self.value)
        self.gettoken()
        return (a, z)
    else:
        self.raise_error('expected (...) or NAME or STRING, got %s/%s', self.type, self.value)

def expect(self, type, value=None):
    if self.type != type or (value is not None and self.value != value):
        self.raise_error('expected %s/%s, got %s/%s', type, value, self.type, self.value)
    value = self.value
    self.gettoken()
    return value

def gettoken(self):
    tup = next(self.generator)
    while tup[0] in (tokenize.COMMENT, tokenize.NL):
        tup = next(self.generator)
    self.type, self.value, self.begin, self.end, self.line = tup

def raise_error(self, msg, *args):
    if args:
        try:
            msg = msg % args
        except:
            msg = ' '.join([msg] + list(map(str, args)))
    raise SyntaxError(msg, (self.filename, self.end[0], self.end[1], self.line))

def unifystate(self, old, new):
    for label, next in self.arcs.items():
        if next is old:
            self.arcs[label] = new

def __eq__(self, other):
    assert isinstance(other, DFAState)
    if self.isfinal != other.isfinal:
        return False
    if len(self.arcs) != len(other.arcs):
        return False
    for label, next in self.arcs.items():
        if next is not other.arcs.get(label):
            return False
    return True

def closure(state):
    base = {}
    addclosure(state, base)
    return base

def tokenize_loop(readline, tokeneater):
    for token_info in generate_tokens(readline):
        tokeneater(*token_info)

def _get_normal_name(orig_enc):
    """Imitates get_normal_name in tokenizer.c."""
    enc = orig_enc[:12].lower().replace('_', '-')
    if enc == 'utf-8' or enc.startswith('utf-8-'):
        return 'utf-8'
    if enc in ('latin-1', 'iso-8859-1', 'iso-latin-1') or enc.startswith(('latin-1-', 'iso-8859-1-', 'iso-latin-1-')):
        return 'iso-8859-1'
    return orig_enc

def untokenize(self, iterable):
    for t in iterable:
        if len(t) == 2:
            self.compat(t, iterable)
            break
        tok_type, token, start, end, line = t
        self.add_whitespace(start)
        self.tokens.append(token)
        self.prev_row, self.prev_col = end
        if tok_type in (NEWLINE, NL):
            self.prev_row += 1
            self.prev_col = 0
    return ''.join(self.tokens)

def compat(self, token, iterable):
    startline = False
    indents = []
    toks_append = self.tokens.append
    toknum, tokval = token
    if toknum in (NAME, NUMBER):
        tokval += ' '
    if toknum in (NEWLINE, NL):
        startline = True
    for tok in iterable:
        toknum, tokval = tok[:2]
        if toknum in (NAME, NUMBER, ASYNC, AWAIT):
            tokval += ' '
        if toknum == INDENT:
            indents.append(tokval)
            continue
        elif toknum == DEDENT:
            indents.pop()
            continue
        elif toknum in (NEWLINE, NL):
            startline = True
        elif startline and indents:
            toks_append(indents[-1])
            startline = False
        toks_append(tokval)

def read_or_stop():
    try:
        return readline()
    except StopIteration:
        return bytes()

def find_cookie(line):
    try:
        line_string = line.decode('ascii')
    except UnicodeDecodeError:
        return None
    match = cookie_re.match(line_string)
    if not match:
        return None
    encoding = _get_normal_name(match.group(1))
    try:
        codec = lookup(encoding)
    except LookupError:
        raise SyntaxError('unknown encoding: ' + encoding)
    if bom_found:
        if codec.name != 'utf-8':
            raise SyntaxError('encoding problem: utf-8')
        encoding += '-sig'
    return encoding

def __init__(self, grammar):
    """Initializer.

    Creates an attribute for each grammar symbol (nonterminal),
    whose value is the symbol's type (an int >= 256)."""
    for name, symbol in grammar.symbol2number.items():
        setattr(self, name, symbol)

def convert(gr, raw_node):
    """Convert raw node information to a Node or Leaf instance.

    This is passed to the parser driver which calls it whenever a reduction of a
    grammar rule produces a new complete node, so that the tree is build
    strictly bottom-up."""
    type, value, context, children = raw_node
    if children or type in gr.number2symbol:
        if len(children) == 1:
            return children[0]
        return Node(type, children, context=context)
    else:
        return Leaf(type, value, context=context)

def generate_matches(patterns, nodes):
    """Generator yielding matches for a sequence of patterns and nodes.

    Args:
        patterns: a sequence of patterns
        nodes: a sequence of nodes

    Yields:
        (count, results) tuples where:
        count: the entire sequence of patterns matches nodes[:count];
        results: dict containing named submatches.
    """
    if not patterns:
        yield (0, {})
    else:
        p, rest = (patterns[0], patterns[1:])
        for c0, r0 in p.generate_matches(nodes):
            if not rest:
                yield (c0, r0)
            else:
                for c1, r1 in generate_matches(rest, nodes[c0:]):
                    r = {}
                    r.update(r0)
                    r.update(r1)
                    yield (c0 + c1, r)

def __new__(cls, *args, **kwds):
    """Constructor that prevents Base from being instantiated."""
    assert cls is not Base, 'Cannot instantiate Base'
    return object.__new__(cls)

def __eq__(self, other):
    """Compare two nodes for equality.

    This calls the method _eq()."""
    if self.__class__ is not other.__class__:
        return NotImplemented
    return self._eq(other)

def replace(self, new):
    """Replace this node with a new one in the parent."""
    assert self.parent is not None, str(self)
    assert new is not None
    if not isinstance(new, list):
        new = [new]
    l_children = []
    found = False
    for ch in self.parent.children:
        if ch is self:
            assert not found, (self.parent.children, self, new)
            if new is not None:
                l_children.extend(new)
            found = True
        else:
            l_children.append(ch)
    assert found, (self.children, self, new)
    self.parent.changed()
    self.parent.children = l_children
    for x in new:
        x.parent = self.parent
    self.parent = None

def get_lineno(self):
    """Return the line number which generated the invocant node."""
    node = self
    while not isinstance(node, Leaf):
        if not node.children:
            return
        node = node.children[0]
    return node.lineno

def changed(self):
    if self.parent:
        self.parent.changed()
    self.was_changed = True

def remove(self):
    """Remove the node from the tree. Returns the position of the node in its
    parent's children before it was removed."""
    if self.parent:
        for i, node in enumerate(self.parent.children):
            if node is self:
                self.parent.changed()
                del self.parent.children[i]
                self.parent = None
                return i

@property
def next_sibling(self):
    """The node immediately following the invocant in their parent's children
    list. If the invocant does not have a next sibling, it is None"""
    if self.parent is None:
        return None
    for i, child in enumerate(self.parent.children):
        if child is self:
            try:
                return self.parent.children[i + 1]
            except IndexError:
                return None

@property
def prev_sibling(self):
    """The node immediately preceding the invocant in their parent's children
    list. If the invocant does not have a previous sibling, it is None."""
    if self.parent is None:
        return None
    for i, child in enumerate(self.parent.children):
        if child is self:
            if i == 0:
                return None
            return self.parent.children[i - 1]

def leaves(self):
    for child in self.children:
        yield from child.leaves()

def depth(self):
    if self.parent is None:
        return 0
    return 1 + self.parent.depth()

def __repr__(self):
    """Return a canonical string representation."""
    return '%s(%s, %r)' % (self.__class__.__name__, type_repr(self.type), self.children)

def __unicode__(self):
    """Return a pretty string representation.

    This reproduces the input source exactly."""
    return ''.join(map(str, self.children))

def _eq(self, other):
    """Compare two nodes for equality."""
    return (self.type, self.children) == (other.type, other.children)

def clone(self):
    """Return a cloned (deep) copy of self."""
    return Node(self.type, [ch.clone() for ch in self.children], fixers_applied=self.fixers_applied)

def pre_order(self):
    """Return a pre-order iterator for the tree."""
    yield self
    for child in self.children:
        yield from child.pre_order()

@property
def prefix(self):
    """The whitespace and comments preceding this node in the input."""
    if not self.children:
        return ''
    return self.children[0].prefix

@prefix.setter
def prefix(self, prefix):
    if self.children:
        self.children[0].prefix = prefix

def __repr__(self):
    """Return a canonical string representation."""
    return '%s(%r, %r)' % (self.__class__.__name__, self.type, self.value)

def __unicode__(self):
    """Return a pretty string representation.

    This reproduces the input source exactly."""
    return self.prefix + str(self.value)

def _eq(self, other):
    """Compare two nodes for equality."""
    return (self.type, self.value) == (other.type, other.value)

def clone(self):
    """Return a cloned (deep) copy of self."""
    return Leaf(self.type, self.value, (self.prefix, (self.lineno, self.column)), fixers_applied=self.fixers_applied)

def post_order(self):
    """Return a post-order iterator for the tree."""
    yield self

@property
def prefix(self):
    """The whitespace and comments preceding this token in the input."""
    return self._prefix

@prefix.setter
def prefix(self, prefix):
    self.changed()
    self._prefix = prefix

def __new__(cls, *args, **kwds):
    """Constructor that prevents BasePattern from being instantiated."""
    assert cls is not BasePattern, 'Cannot instantiate BasePattern'
    return object.__new__(cls)

def __repr__(self):
    args = [type_repr(self.type), self.content, self.name]
    while args and args[-1] is None:
        del args[-1]
    return '%s(%s)' % (self.__class__.__name__, ', '.join(map(repr, args)))

def match(self, node, results=None):
    """Does this pattern exactly match a node?

    Returns True if it matches, False if not.

    If results is not None, it must be a dict which will be
    updated with the nodes matching named subpatterns.

    Default implementation for non-wildcard patterns."""
    if self.type is not None and node.type != self.type:
        return False
    if self.content is not None:
        r = None
        if results is not None:
            r = {}
        if not self._submatch(node, r):
            return False
        if r:
            results.update(r)
    if results is not None and self.name:
        results[self.name] = node
    return True

def generate_matches(self, nodes):
    """Generator yielding all matches for this pattern.

    Default implementation for non-wildcard patterns."""
    r = {}
    if nodes and self.match(nodes[0], r):
        yield (1, r)

def match(self, node, results=None):
    """Override match() to insist on a leaf node."""
    if not isinstance(node, Leaf):
        return False
    return BasePattern.match(self, node, results)

def _submatch(self, node, results=None):
    """Match the pattern's content to the node's children.

    This assumes the node type matches and self.content is not None.

    Returns True if it matches, False if not.

    If results is not None, it must be a dict which will be
    updated with the nodes matching named subpatterns.

    When returning False, the results dict may still be updated."""
    if self.wildcards:
        for c, r in generate_matches(self.content, node.children):
            if c == len(node.children):
                if results is not None:
                    results.update(r)
                return True
        return False
    if len(self.content) != len(node.children):
        return False
    for subpattern, child in zip(self.content, node.children):
        if not subpattern.match(child, results):
            return False
    return True

def optimize(self):
    """Optimize certain stacked wildcard patterns."""
    subpattern = None
    if self.content is not None and len(self.content) == 1 and (len(self.content[0]) == 1):
        subpattern = self.content[0][0]
    if self.min == 1 and self.max == 1:
        if self.content is None:
            return NodePattern(name=self.name)
        if subpattern is not None and self.name == subpattern.name:
            return subpattern.optimize()
    if self.min <= 1 and isinstance(subpattern, WildcardPattern) and (subpattern.min <= 1) and (self.name == subpattern.name):
        return WildcardPattern(subpattern.content, self.min * subpattern.min, self.max * subpattern.max, subpattern.name)
    return self

def match(self, node, results=None):
    """Does this pattern exactly match a node?"""
    return self.match_seq([node], results)

def match_seq(self, nodes, results=None):
    """Does this pattern exactly match a sequence of nodes?"""
    for c, r in self.generate_matches(nodes):
        if c == len(nodes):
            if results is not None:
                results.update(r)
                if self.name:
                    results[self.name] = list(nodes)
            return True
    return False

def generate_matches(self, nodes):
    """Generator yielding matches for a sequence of nodes.

    Args:
        nodes: sequence of nodes

    Yields:
        (count, results) tuples where:
        count: the match comprises nodes[:count];
        results: dict containing named submatches."""
    if self.content is None:
        for count in range(self.min, 1 + min(len(nodes), self.max)):
            r = {}
            if self.name:
                r[self.name] = nodes[:count]
            yield (count, r)
    elif self.name == 'bare_name':
        yield self._bare_name_matches(nodes)
    else:
        if hasattr(sys, 'getrefcount'):
            save_stderr = sys.stderr
            sys.stderr = StringIO()
        try:
            for count, r in self._recursive_matches(nodes, 0):
                if self.name:
                    r[self.name] = nodes[:count]
                yield (count, r)
        except RuntimeError:
            for count, r in self._iterative_matches(nodes):
                if self.name:
                    r[self.name] = nodes[:count]
                yield (count, r)
        finally:
            if hasattr(sys, 'getrefcount'):
                sys.stderr = save_stderr

def _iterative_matches(self, nodes):
    """Helper to iteratively yield the matches."""
    nodelen = len(nodes)
    if 0 >= self.min:
        yield (0, {})
    results = []
    for alt in self.content:
        for c, r in generate_matches(alt, nodes):
            yield (c, r)
            results.append((c, r))
    while results:
        new_results = []
        for c0, r0 in results:
            if c0 < nodelen and c0 <= self.max:
                for alt in self.content:
                    for c1, r1 in generate_matches(alt, nodes[c0:]):
                        if c1 > 0:
                            r = {}
                            r.update(r0)
                            r.update(r1)
                            yield (c0 + c1, r)
                            new_results.append((c0 + c1, r))
        results = new_results

def _bare_name_matches(self, nodes):
    """Special optimized matcher for bare_name."""
    count = 0
    r = {}
    done = False
    max = len(nodes)
    while not done and count < max:
        done = True
        for leaf in self.content:
            if leaf[0].match(nodes[count], r):
                count += 1
                done = False
                break
    r[self.name] = nodes[:count]
    return (count, r)

def _recursive_matches(self, nodes, count):
    """Helper to recursively yield the matches."""
    assert self.content is not None
    if count >= self.min:
        yield (0, {})
    if count < self.max:
        for alt in self.content:
            for c0, r0 in generate_matches(alt, nodes):
                for c1, r1 in self._recursive_matches(nodes[c0:], count + 1):
                    r = {}
                    r.update(r0)
                    r.update(r1)
                    yield (c0 + c1, r)

def generate_matches(self, nodes):
    if self.content is None:
        if len(nodes) == 0:
            yield (0, {})
    else:
        for c, r in self.content.generate_matches(nodes):
            return
        yield (0, {})

def get_all_fix_names(fixer_pkg, remove_prefix=True):
    """Return a sorted list of all available fix names in the given package."""
    pkg = __import__(fixer_pkg, [], [], ['*'])
    fix_names = []
    for finder, name, ispkg in pkgutil.iter_modules(pkg.__path__):
        if name.startswith('fix_'):
            if remove_prefix:
                name = name[4:]
            fix_names.append(name)
    return fix_names

def _get_head_types(pat):
    """Accepts a pytree Pattern Node and returns a set
    of the pattern types which will match first."""
    if isinstance(pat, (pytree.NodePattern, pytree.LeafPattern)):
        if pat.type is None:
            raise _EveryNode
        return {pat.type}
    if isinstance(pat, pytree.NegatedPattern):
        if pat.content:
            return _get_head_types(pat.content)
        raise _EveryNode
    if isinstance(pat, pytree.WildcardPattern):
        r = set()
        for p in pat.content:
            for x in p:
                r.update(_get_head_types(x))
        return r
    raise Exception("Oh no! I don't understand pattern %s" % pat)

def _get_headnode_dict(fixer_list):
    """Accepts a list of fixers and returns a dictionary
    of head node type --> fixer list."""
    head_nodes = collections.defaultdict(list)
    every = []
    for fixer in fixer_list:
        if fixer.pattern:
            try:
                heads = _get_head_types(fixer.pattern)
            except _EveryNode:
                every.append(fixer)
            else:
                for node_type in heads:
                    head_nodes[node_type].append(fixer)
        elif fixer._accept_type is not None:
            head_nodes[fixer._accept_type].append(fixer)
        else:
            every.append(fixer)
    for node_type in chain(pygram.python_grammar.symbol2number.values(), pygram.python_grammar.tokens):
        head_nodes[node_type].extend(every)
    return dict(head_nodes)

def get_fixers_from_package(pkg_name):
    """Return the fully qualified names for fixers in the package pkg_name."""
    return [pkg_name + '.' + fix_name for fix_name in get_all_fix_names(pkg_name, False)]

def _detect_future_features(source):
    have_docstring = False
    gen = tokenize.generate_tokens(io.StringIO(source).readline)
    def advance():
        tok = next(gen)
        return (tok[0], tok[1])
    ignore = frozenset({token.NEWLINE, tokenize.NL, token.COMMENT})
    features = set()
    try:
        while True:
            tp, value = advance()
            if tp in ignore:
                continue
            elif tp == token.STRING:
                if have_docstring:
                    break
                have_docstring = True
            elif tp == token.NAME and value == 'from':
                tp, value = advance()
                if tp != token.NAME or value != '__future__':
                    break
                tp, value = advance()
                if tp != token.NAME or value != 'import':
                    break
                tp, value = advance()
                if tp == token.OP and value == '(':
                    tp, value = advance()
                while tp == token.NAME:
                    features.add(value)
                    tp, value = advance()
                    if tp != token.OP or value != ',':
                        break
                    tp, value = advance()
            else:
                break
    except StopIteration:
        pass
    return frozenset(features)

def advance():
    tok = next(gen)
    return (tok[0], tok[1])

def log_error(self, msg, *args, **kwds):
    """Called when an error occurs."""
    raise

def log_message(self, msg, *args):
    """Hook to log a message."""
    if args:
        msg = msg % args
    self.logger.info(msg)

def log_debug(self, msg, *args):
    if args:
        msg = msg % args
    self.logger.debug(msg)

def _read_python_source(self, filename):
    """Do our best to decode a Python source file correctly."""
    try:
        f = open(filename, 'rb')
    except OSError as err:
        self.log_error("Can't open %s: %s", filename, err)
        return (None, None)
    try:
        encoding = tokenize.detect_encoding(f.readline)[0]
    finally:
        f.close()
    with io.open(filename, 'r', encoding=encoding, newline='') as f:
        return (f.read(), encoding)

def refactor_file(self, filename, write=False, doctests_only=False):
    """Refactors a file."""
    input, encoding = self._read_python_source(filename)
    if input is None:
        return
    input += '\n'
    if doctests_only:
        self.log_debug('Refactoring doctests in %s', filename)
        output = self.refactor_docstring(input, filename)
        if self.write_unchanged_files or output != input:
            self.processed_file(output, filename, input, write, encoding)
        else:
            self.log_debug('No doctest changes in %s', filename)
    else:
        tree = self.refactor_string(input, filename)
        if self.write_unchanged_files or (tree and tree.was_changed):
            self.processed_file(str(tree)[:-1], filename, write=write, encoding=encoding)
        else:
            self.log_debug('No changes in %s', filename)

def refactor_stdin(self, doctests_only=False):
    input = sys.stdin.read()
    if doctests_only:
        self.log_debug('Refactoring doctests in stdin')
        output = self.refactor_docstring(input, '<stdin>')
        if self.write_unchanged_files or output != input:
            self.processed_file(output, '<stdin>', input)
        else:
            self.log_debug('No doctest changes in stdin')
    else:
        tree = self.refactor_string(input, '<stdin>')
        if self.write_unchanged_files or (tree and tree.was_changed):
            self.processed_file(str(tree), '<stdin>', input)
        else:
            self.log_debug('No changes in stdin')

def traverse_by(self, fixers, traversal):
    """Traverse an AST, applying a set of fixers to each node.

    This is a helper method for refactor_tree().

    Args:
        fixers: a list of fixer instances.
        traversal: a generator that yields AST nodes.

    Returns:
        None"""
    if not fixers:
        return
    for node in traversal:
        for fixer in fixers[node.type]:
            results = fixer.match(node)
            if results:
                new = fixer.transform(node, results)
                if new is not None:
                    node.replace(new)
                    node = new

def processed_file(self, new_text, filename, old_text=None, write=False, encoding=None):
    """Called when a file has been refactored and there may be changes."""
    self.files.append(filename)
    if old_text is None:
        old_text = self._read_python_source(filename)[0]
        if old_text is None:
            return
    equal = old_text == new_text
    self.print_output(old_text, new_text, filename, equal)
    if equal:
        self.log_debug('No changes to %s', filename)
        if not self.write_unchanged_files:
            return
    if write:
        self.write_file(new_text, filename, old_text, encoding)
    else:
        self.log_debug('Not writing changes to %s', filename)

def refactor_doctest(self, block, lineno, indent, filename):
    """Refactors one doctest.

    A doctest is given as a block of lines, the first of which starts
    with ">>>" (possibly indented), while the remaining lines start
    with "..." (identically indented)."""
    try:
        tree = self.parse_block(block, lineno, indent)
    except Exception as err:
        if self.logger.isEnabledFor(logging.DEBUG):
            for line in block:
                self.log_debug('Source: %s', line.rstrip('\n'))
        self.log_error("Can't parse docstring in %s line %s: %s: %s", filename, lineno, err.__class__.__name__, err)
        return block
    if self.refactor_tree(tree, filename):
        new = str(tree).splitlines(keepends=True)
        clipped, new = (new[:lineno - 1], new[lineno - 1:])
        assert clipped == ['\n'] * (lineno - 1), clipped
        if not new[-1].endswith('\n'):
            new[-1] += '\n'
        block = [indent + self.PS1 + new.pop(0)]
        if new:
            block += [indent + self.PS2 + line for line in new]
    return block

def summarize(self):
    if self.wrote:
        were = 'were'
    else:
        were = 'need to be'
    if not self.files:
        self.log_message('No files %s modified.', were)
    else:
        self.log_message('Files that %s modified:', were)
        for file in self.files:
            self.log_message(file)
    if self.fixer_log:
        self.log_message('Warnings/messages while refactoring:')
        for message in self.fixer_log:
            self.log_message(message)
    if self.errors:
        if len(self.errors) == 1:
            self.log_message('There was 1 error:')
        else:
            self.log_message('There were %d errors:', len(self.errors))
        for msg, args, kwds in self.errors:
            self.log_message(msg, *args, **kwds)

def gen_lines(self, block, indent):
    """Generates lines as expected by tokenize from a list of lines.

    This strips the first len(indent + self.PS1) characters off each line."""
    prefix1 = indent + self.PS1
    prefix2 = indent + self.PS2
    prefix = prefix1
    for line in block:
        if line.startswith(prefix):
            yield line[len(prefix):]
        elif line == prefix.rstrip() + '\n':
            yield '\n'
        else:
            raise AssertionError('line=%r, prefix=%r' % (line, prefix))
        prefix = prefix2
    while True:
        yield ''

def refactor(self, items, write=False, doctests_only=False, num_processes=1):
    if num_processes == 1:
        return super(MultiprocessRefactoringTool, self).refactor(items, write, doctests_only)
    try:
        import multiprocessing
    except ImportError:
        raise MultiprocessingUnsupported
    if self.queue is not None:
        raise RuntimeError('already doing multiple processes')
    self.queue = multiprocessing.JoinableQueue()
    self.output_lock = multiprocessing.Lock()
    processes = [multiprocessing.Process(target=self._child) for i in range(num_processes)]
    try:
        for p in processes:
            p.start()
        super(MultiprocessRefactoringTool, self).refactor(items, write, doctests_only)
    finally:
        self.queue.join()
        for i in range(num_processes):
            self.queue.put(None)
        for p in processes:
            if p.is_alive():
                p.join()
        self.queue = None

def _child(self):
    task = self.queue.get()
    while task is not None:
        args, kwargs = task
        try:
            super(MultiprocessRefactoringTool, self).refactor_file(*args, **kwargs)
        finally:
            self.queue.task_done()
        task = self.queue.get()

def refactor_file(self, *args, **kwargs):
    if self.queue is not None:
        self.queue.put((args, kwargs))
    else:
        return super(MultiprocessRefactoringTool, self).refactor_file(*args, **kwargs)

def clearcache():
    """Clear the cache entirely."""
    cache.clear()

def getlines(filename, module_globals=None):
    """Get the lines for a Python source file from the cache.
    Update the cache if it doesn't contain an entry for this file already."""
    if filename in cache:
        entry = cache[filename]
        if len(entry) != 1:
            return cache[filename][2]
    try:
        return updatecache(filename, module_globals)
    except MemoryError:
        clearcache()
        return []

def checkcache(filename=None):
    """Discard cache entries that are out of date.
    (This is not checked upon each call!)"""
    if filename is None:
        filenames = cache.copy().keys()
    else:
        filenames = [filename]
    for filename in filenames:
        try:
            entry = cache[filename]
        except KeyError:
            continue
        if len(entry) == 1:
            continue
        size, mtime, lines, fullname = entry
        if mtime is None:
            continue
        try:
            stat = os.stat(fullname)
        except (OSError, ValueError):
            cache.pop(filename, None)
            continue
        if size != stat.st_size or mtime != stat.st_mtime:
            cache.pop(filename, None)

def _strcoll(a, b):
    """strcoll(string,string) -> int.
    Compares two strings according to the locale."""
    return (a > b) - (a < b)

@functools.wraps(_localeconv)
def localeconv():
    d = _localeconv()
    if _override_localeconv:
        d.update(_override_localeconv)
    return d

def _grouping_intervals(grouping):
    last_interval = None
    for interval in grouping:
        if interval == CHAR_MAX:
            return
        if interval == 0:
            if last_interval is None:
                raise ValueError('invalid grouping')
            while True:
                yield last_interval
        yield interval
        last_interval = interval

def _group(s, monetary=False):
    conv = localeconv()
    thousands_sep = conv[monetary and 'mon_thousands_sep' or 'thousands_sep']
    grouping = conv[monetary and 'mon_grouping' or 'grouping']
    if not grouping:
        return (s, 0)
    if s[-1] == ' ':
        stripped = s.rstrip()
        right_spaces = s[len(stripped):]
        s = stripped
    else:
        right_spaces = ''
    left_spaces = ''
    groups = []
    for interval in _grouping_intervals(grouping):
        if not s or s[-1] not in '0123456789':
            left_spaces = s
            s = ''
            break
        groups.append(s[-interval:])
        s = s[:-interval]
    if s:
        groups.append(s)
    groups.reverse()
    return (left_spaces + thousands_sep.join(groups) + right_spaces, len(thousands_sep) * (len(groups) - 1))

def _strip_padding(s, amount):
    lpos = 0
    while amount and s[lpos] == ' ':
        lpos += 1
        amount -= 1
    rpos = len(s) - 1
    while amount and s[rpos] == ' ':
        rpos -= 1
        amount -= 1
    return s[lpos:rpos + 1]

def _format(percent, value, grouping=False, monetary=False, *additional):
    if additional:
        formatted = percent % ((value,) + additional)
    else:
        formatted = percent % value
    if percent[-1] in 'eEfFgGdiu':
        formatted = _localize(formatted, grouping, monetary)
    return formatted

def format_string(f, val, grouping=False, monetary=False):
    """Formats a string in the same way that the % formatting would use,
    but takes the current locale into account.

    Grouping is applied if the third parameter is true.
    Conversion uses monetary thousands separator and grouping strings if
    forth parameter monetary is true."""
    percents = list(_percent_re.finditer(f))
    new_f = _percent_re.sub('%s', f)
    if isinstance(val, _collections_abc.Mapping):
        new_val = []
        for perc in percents:
            if perc.group()[-1] == '%':
                new_val.append('%')
            else:
                new_val.append(_format(perc.group(), val, grouping, monetary))
    else:
        if not isinstance(val, tuple):
            val = (val,)
        new_val = []
        i = 0
        for perc in percents:
            if perc.group()[-1] == '%':
                new_val.append('%')
            else:
                starcount = perc.group('modifiers').count('*')
                new_val.append(_format(perc.group(), val[i], grouping, monetary, *val[i + 1:i + 1 + starcount]))
                i += 1 + starcount
    val = tuple(new_val)
    return new_f % val

def str(val):
    """Convert float to string, taking the locale into account."""
    return _format('%.12g', val)

def localize(string, grouping=False, monetary=False):
    """Parses a string as locale number according to the locale settings."""
    return _localize(string, grouping, monetary)

def atof(string, func=float):
    """Parses a string as a float according to the locale settings."""
    return func(delocalize(string))

def atoi(string):
    """Converts a string to an integer according to the locale settings."""
    return int(delocalize(string))

def _replace_encoding(code, encoding):
    if '.' in code:
        langname = code[:code.index('.')]
    else:
        langname = code
    norm_encoding = encodings.normalize_encoding(encoding)
    norm_encoding = encodings.aliases.aliases.get(norm_encoding.lower(), norm_encoding)
    encoding = norm_encoding
    norm_encoding = norm_encoding.lower()
    if norm_encoding in locale_encoding_alias:
        encoding = locale_encoding_alias[norm_encoding]
    else:
        norm_encoding = norm_encoding.replace('_', '')
        norm_encoding = norm_encoding.replace('-', '')
        if norm_encoding in locale_encoding_alias:
            encoding = locale_encoding_alias[norm_encoding]
    return langname + '.' + encoding

def _append_modifier(code, modifier):
    if modifier == 'euro':
        if '.' not in code:
            return code + '.ISO8859-15'
        _, _, encoding = code.partition('.')
        if encoding in ('ISO8859-15', 'UTF-8'):
            return code
        if encoding == 'ISO8859-1':
            return _replace_encoding(code, 'ISO8859-15')
    return code + '@' + modifier

def _parse_localename(localename):
    """Parses the locale code for localename and returns the
    result as tuple (language code, encoding).

    The localename is normalized and passed through the locale
    alias engine. A ValueError is raised in case the locale name
    cannot be parsed.

    The language code corresponds to RFC 1766.  code and encoding
    can be None in case the values cannot be determined or are
    unknown to this implementation."""
    code = normalize(localename)
    if '@' in code:
        code, modifier = code.split('@', 1)
        if modifier == 'euro' and '.' not in code:
            return (code, 'iso-8859-15')
    if '.' in code:
        return tuple(code.split('.')[:2])
    elif code == 'C':
        return (None, None)
    elif code == 'UTF-8':
        return (None, 'UTF-8')
    raise ValueError('unknown locale: %s' % localename)

def _build_localename(localetuple):
    """Builds a locale code from the given tuple (language code,
    encoding).

    No aliasing or normalizing takes place."""
    try:
        language, encoding = localetuple
        if language is None:
            language = 'C'
        if encoding is None:
            return language
        else:
            return language + '.' + encoding
    except (TypeError, ValueError):
        raise TypeError('Locale must be None, a string, or an iterable of two strings -- language code, encoding.') from None

def _getdefaultlocale(envvars=('LC_ALL', 'LC_CTYPE', 'LANG', 'LANGUAGE')):
    try:
        import _locale
        code, encoding = _locale._getdefaultlocale()
    except (ImportError, AttributeError):
        pass
    else:
        if sys.platform == 'win32' and code and (code[:2] == '0x'):
            code = windows_locale.get(int(code, 0))
        return (code, encoding)
    import os
    lookup = os.environ.get
    for variable in envvars:
        localename = lookup(variable, None)
        if localename:
            if variable == 'LANGUAGE':
                localename = localename.split(':')[0]
            break
    else:
        localename = 'C'
    return _parse_localename(localename)

def setlocale(category, locale=None):
    """Set the locale for the given category.  The locale can be
    a string, an iterable of two strings (language code and encoding),
    or None.

    Iterables are converted to strings using the locale aliasing
    engine.  Locale strings are passed directly to the C lib.

    category may be given as one of the LC_* values."""
    if locale and (not isinstance(locale, _builtin_str)):
        locale = normalize(_build_localename(locale))
    return _setlocale(category, locale)

def getpreferredencoding(do_setlocale=True):
    """Return the charset that the user is likely using,
    according to the system configuration."""
    if sys.flags.warn_default_encoding:
        import warnings
        warnings.warn('UTF-8 Mode affects locale.getpreferredencoding(). Consider locale.getencoding() instead.', EncodingWarning, 2)
    if sys.flags.utf8_mode:
        return 'utf-8'
    if not do_setlocale:
        return getencoding()
    old_loc = setlocale(LC_CTYPE)
    try:
        try:
            setlocale(LC_CTYPE, '')
        except Error:
            pass
        return getencoding()
    finally:
        setlocale(LC_CTYPE, old_loc)

def _init_categories(categories=categories):
    for k, v in globals().items():
        if k[:3] == 'LC_':
            categories[k] = v

def localeconv():
    """localeconv() -> dict.
    Returns numeric and monetary locale-specific parameters."""
    return {'grouping': [127], 'currency_symbol': '', 'n_sign_posn': 127, 'p_cs_precedes': 127, 'n_cs_precedes': 127, 'mon_grouping': [], 'n_sep_by_space': 127, 'decimal_point': '.', 'negative_sign': '', 'positive_sign': '', 'p_sep_by_space': 127, 'int_curr_symbol': '', 'p_sign_posn': 127, 'thousands_sep': '', 'mon_thousands_sep': '', 'frac_digits': 127, 'mon_decimal_point': '', 'int_frac_digits': 127}

def setlocale(category, value=None):
    """setlocale(integer,string=None) -> string.
    Activates/queries locale processing."""
    if value not in (None, '', 'C'):
        raise Error('_locale emulation only supports "C" locale')
    return 'C'

def getencoding():
    if hasattr(sys, 'getandroidapilevel'):
        return 'utf-8'
    encoding = _getdefaultlocale()[1]
    if encoding is None:
        encoding = 'utf-8'
    return encoding

def getpreferredencoding(do_setlocale=True):
    """Return the charset that the user is likely using."""
    if sys.flags.warn_default_encoding:
        import warnings
        warnings.warn('UTF-8 Mode affects locale.getpreferredencoding(). Consider locale.getencoding() instead.', EncodingWarning, 2)
    if sys.flags.utf8_mode:
