    """Get a handler with the specified *name*, or None if there isn't one with
    that name."""
    return _handlers.get(name)

def getHandlerNames():
    """Return all known handler names as an immutable set."""
    result = set(_handlers.keys())
    return frozenset(result)

def setLoggerClass(klass):
    """Set the class to be used when instantiating a logger. The class should
    define __init__() such that only a name argument is required, and the
    __init__() should call Logger.__init__()"""
    if klass != Logger:
        if not issubclass(klass, Logger):
            raise TypeError('logger not derived from logging.Logger: ' + klass.__name__)
    global _loggerClass
    _loggerClass = klass

def getLoggerClass():
    """Return the class to be used when instantiating a logger."""
    return _loggerClass

def fatal(msg, *args, **kwargs):
    """Don't use this function, use critical() instead."""
    critical(msg, *args, **kwargs)

def warn(msg, *args, **kwargs):
    warnings.warn("The 'warn' function is deprecated, use 'warning' instead", DeprecationWarning, 2)
    warning(msg, *args, **kwargs)

def shutdown(handlerList=_handlerList):
    """Perform any cleanup actions in the logging system (e.g. flushing
    buffers).

    Should be called at application exit."""
    for wr in reversed(handlerList[:]):
        try:
            h = wr()
            if h:
                try:
                    h.acquire()
                    if getattr(h, 'flushOnClose', True):
                        h.flush()
                    h.close()
                except (OSError, ValueError):
                    pass
                finally:
                    h.release()
        except:
            if raiseExceptions:
                raise

def _showwarning(message, category, filename, lineno, file=None, line=None):
    """Implementation of showwarnings which redirects to logging, which will first
    check to see if the file parameter is None. If a file is specified, it will
    delegate to the original warnings implementation of showwarning. Otherwise,
    it will call warnings.formatwarning and will log the resulting string to a
    warnings logger named "py.warnings" with level logging.WARNING."""
    if file is not None:
        if _warnings_showwarning is not None:
            _warnings_showwarning(message, category, filename, lineno, file, line)
    else:
        s = warnings.formatwarning(message, category, filename, lineno, line)
        logger = getLogger('py.warnings')
        if not logger.handlers:
            logger.addHandler(NullHandler())
        logger.warning(str(s))

def currentframe():
    """Return the frame object for the caller's stack frame."""
    try:
        raise Exception
    except Exception as exc:
        return exc.__traceback__.tb_frame.f_back

def _register_at_fork_reinit_lock(instance):
    _acquireLock()
    try:
        _at_fork_reinit_lock_weakset.add(instance)
    finally:
        _releaseLock()

def _after_at_fork_child_reinit_locks():
    for handler in _at_fork_reinit_lock_weakset:
        handler._at_fork_reinit()
    _lock._at_fork_reinit()

def __init__(self, fmt, *, defaults=None):
    self._fmt = fmt or self.default_format
    self._defaults = defaults

def validate(self):
    """Validate the input format, ensure it matches the correct style"""
    if not self.validation_pattern.search(self._fmt):
        raise ValueError("Invalid format '%s' for '%s' style" % (self._fmt, self.default_format[0]))

def _format(self, record):
    if (defaults := self._defaults):
        values = defaults | record.__dict__
    else:
        values = record.__dict__
    return self._fmt % values

def format(self, record):
    try:
        return self._format(record)
    except KeyError as e:
        raise ValueError('Formatting field not found in record: %s' % e)

def _format(self, record):
    if (defaults := self._defaults):
        values = defaults | record.__dict__
    else:
        values = record.__dict__
    return self._fmt.format(**values)

def validate(self):
    """Validate the input format, ensure it is the correct string formatting style"""
    fields = set()
    try:
        for _, fieldname, spec, conversion in _str_formatter.parse(self._fmt):
            if fieldname:
                if not self.field_spec.match(fieldname):
                    raise ValueError('invalid field name/expression: %r' % fieldname)
                fields.add(fieldname)
            if conversion and conversion not in 'rsa':
                raise ValueError('invalid conversion: %r' % conversion)
            if spec and (not self.fmt_spec.match(spec)):
                raise ValueError('bad specifier: %r' % spec)
    except ValueError as e:
        raise ValueError('invalid format: %s' % e)
    if not fields:
        raise ValueError('invalid format: no fields')

def __init__(self, *args, **kwargs):
    super().__init__(*args, **kwargs)
    self._tpl = Template(self._fmt)

def usesTime(self):
    fmt = self._fmt
    return fmt.find('$asctime') >= 0 or fmt.find(self.asctime_search) >= 0

def validate(self):
    pattern = Template.pattern
    fields = set()
    for m in pattern.finditer(self._fmt):
        d = m.groupdict()
        if d['named']:
            fields.add(d['named'])
        elif d['braced']:
            fields.add(d['braced'])
        elif m.group(0) == '$':
            raise ValueError("invalid format: bare '$' not allowed")
    if not fields:
        raise ValueError('invalid format: no fields')

def _format(self, record):
    if (defaults := self._defaults):
        values = defaults | record.__dict__
    else:
        values = record.__dict__
    return self._tpl.substitute(**values)

def usesTime(self):
    """Check if the format uses the creation time of the record."""
    return self._style.usesTime()

def format(self, record):
    """Format the specified record as text.

    The record's attribute dictionary is used as the operand to a
    string formatting operation which yields the returned string.
    Before formatting the dictionary, a couple of preparatory steps
    are carried out. The message attribute of the record is computed
    using LogRecord.getMessage(). If the formatting string uses the
    time (as determined by a call to usesTime(), formatTime() is
    called to format the event time. If there is exception information,
    it is formatted using formatException() and appended to the message."""
    record.message = record.getMessage()
    if self.usesTime():
        record.asctime = self.formatTime(record, self.datefmt)
    s = self.formatMessage(record)
    if record.exc_info:
        if not record.exc_text:
            record.exc_text = self.formatException(record.exc_info)
    if record.exc_text:
        if s[-1:] != '\n':
            s = s + '\n'
        s = s + record.exc_text
    if record.stack_info:
        if s[-1:] != '\n':
            s = s + '\n'
        s = s + self.formatStack(record.stack_info)
    return s

def __init__(self, linefmt=None):
    """Optionally specify a formatter which will be used to format each
    individual record."""
    if linefmt:
        self.linefmt = linefmt
    else:
        self.linefmt = _defaultFormatter

def formatHeader(self, records):
    """Return the header string for the specified records."""
    return ''

def format(self, records):
    """Format the specified records and return the result as a string."""
    rv = ''
    if len(records) > 0:
        rv = rv + self.formatHeader(records)
        for record in records:
            rv = rv + self.linefmt.format(record)
        rv = rv + self.formatFooter(records)
    return rv

def filter(self, record):
    """Determine if the specified record is to be logged.

    Returns True if the record should be logged, or False otherwise.
    If deemed appropriate, the record may be modified in-place."""
    if self.nlen == 0:
        return True
    elif self.name == record.name:
        return True
    elif record.name.find(self.name, 0, self.nlen) != 0:
        return False
    return record.name[self.nlen] == '.'

def __init__(self):
    """Initialize the list of filters to be an empty list."""
    self.filters = []

def addFilter(self, filter):
    """Add the specified filter to this handler."""
    if not filter in self.filters:
        self.filters.append(filter)

def removeFilter(self, filter):
    """Remove the specified filter from this handler."""
    if filter in self.filters:
        self.filters.remove(filter)

def set_name(self, name):
    _acquireLock()
    try:
        if self._name in _handlers:
            del _handlers[self._name]
        self._name = name
        if name:
            _handlers[name] = self
    finally:
        _releaseLock()

def acquire(self):
    """Acquire the I/O thread lock."""
    if self.lock:
        self.lock.acquire()

def release(self):
    """Release the I/O thread lock."""
    if self.lock:
        self.lock.release()

def setLevel(self, level):
    """Set the logging level of this handler.  level must be an int or a str."""
    self.level = _checkLevel(level)

def format(self, record):
    """Format the specified record.

    If a formatter is set, use it. Otherwise, use the default formatter
    for the module."""
    if self.formatter:
        fmt = self.formatter
    else:
        fmt = _defaultFormatter
    return fmt.format(record)

def setFormatter(self, fmt):
    """Set the formatter for this handler."""
    self.formatter = fmt

def handleError(self, record):
    """Handle errors which occur during an emit() call.

    This method should be called from handlers when an exception is
    encountered during an emit() call. If raiseExceptions is false,
    exceptions get silently ignored. This is what is mostly wanted
    for a logging system - most users will not care about errors in
    the logging system, they are more interested in application errors.
    You could, however, replace this with a custom handler if you wish.
    The record which was being processed is passed in to this method."""
    if raiseExceptions and sys.stderr:
        t, v, tb = sys.exc_info()
        try:
            sys.stderr.write('--- Logging error ---\n')
            traceback.print_exception(t, v, tb, None, sys.stderr)
            sys.stderr.write('Call stack:\n')
            frame = tb.tb_frame
            while frame and os.path.dirname(frame.f_code.co_filename) == __path__[0]:
                frame = frame.f_back
            if frame:
                traceback.print_stack(frame, file=sys.stderr)
            else:
                sys.stderr.write('Logged from file %s, line %s\n' % (record.filename, record.lineno))
            try:
                sys.stderr.write('Message: %r\nArguments: %s\n' % (record.msg, record.args))
            except RecursionError:
                raise
            except Exception:
                sys.stderr.write('Unable to print the message and arguments - possible formatting error.\nUse the traceback above to help find the error.\n')
        except OSError:
            pass
        finally:
            del t, v, tb

def __repr__(self):
    level = getLevelName(self.level)
    return '<%s (%s)>' % (self.__class__.__name__, level)

def flush(self):
    """Flushes the stream."""
    self.acquire()
    try:
        if self.stream and hasattr(self.stream, 'flush'):
            self.stream.flush()
    finally:
        self.release()

def __repr__(self):
    level = getLevelName(self.level)
    name = getattr(self.stream, 'name', '')
    name = str(name)
    if name:
        name += ' '
    return '<%s %s(%s)>' % (self.__class__.__name__, name, level)

def close(self):
    """Closes the stream."""
    self.acquire()
    try:
        try:
            if self.stream:
                try:
                    self.flush()
                finally:
                    stream = self.stream
                    self.stream = None
                    if hasattr(stream, 'close'):
                        stream.close()
        finally:
            StreamHandler.close(self)
    finally:
        self.release()

def _open(self):
    """Open the current base file with the (original) mode and encoding.
    Return the resulting stream."""
    open_func = self._builtin_open
    return open_func(self.baseFilename, self.mode, encoding=self.encoding, errors=self.errors)

def emit(self, record):
    """Emit a record.

    If the stream was not opened because 'delay' was specified in the
    constructor, open it before calling the superclass's emit.

    If stream is not open, current mode is 'w' and `_closed=True`, record
    will not be emitted (see Issue #42378)."""
    if self.stream is None:
        if self.mode != 'w' or not self._closed:
            self.stream = self._open()
    if self.stream:
        StreamHandler.emit(self, record)

def __repr__(self):
    level = getLevelName(self.level)
    return '<%s %s (%s)>' % (self.__class__.__name__, self.baseFilename, level)

def __init__(self, level=NOTSET):
    """Initialize the handler."""
    Handler.__init__(self, level)

def __init__(self, alogger):
    """Initialize with the specified logger being a child of this placeholder."""
    self.loggerMap = {alogger: None}

def append(self, alogger):
    """Add the specified logger as a child of this placeholder."""
    if alogger not in self.loggerMap:
        self.loggerMap[alogger] = None

@property
def disable(self):
    return self._disable

@disable.setter
def disable(self, value):
    self._disable = _checkLevel(value)

def setLoggerClass(self, klass):
    """Set the class to be used when instantiating a logger with this Manager."""
    if klass != Logger:
        if not issubclass(klass, Logger):
            raise TypeError('logger not derived from logging.Logger: ' + klass.__name__)
    self.loggerClass = klass

def _fixupParents(self, alogger):
    """Ensure that there are either loggers or placeholders all the way
    from the specified logger to the root of the logger hierarchy."""
    name = alogger.name
    i = name.rfind('.')
    rv = None
    while i > 0 and (not rv):
        substr = name[:i]
        if substr not in self.loggerDict:
            self.loggerDict[substr] = PlaceHolder(alogger)
        else:
            obj = self.loggerDict[substr]
            if isinstance(obj, Logger):
                rv = obj
            else:
                assert isinstance(obj, PlaceHolder)
                obj.append(alogger)
        i = name.rfind('.', 0, i - 1)
    if not rv:
        rv = self.root
    alogger.parent = rv

def _fixupChildren(self, ph, alogger):
    """Ensure that children of the placeholder ph are connected to the
    specified logger."""
    name = alogger.name
    namelen = len(name)
    for c in ph.loggerMap.keys():
        if c.parent.name[:namelen] != name:
            alogger.parent = c.parent
            c.parent = alogger

def _clear_cache(self):
    """Clear the cache for all loggers in loggerDict
    Called when level changes are made"""
    _acquireLock()
    for logger in self.loggerDict.values():
        if isinstance(logger, Logger):
            logger._cache.clear()
    self.root._cache.clear()
    _releaseLock()

def warn(self, msg, *args, **kwargs):
    warnings.warn("The 'warn' method is deprecated, use 'warning' instead", DeprecationWarning, 2)
    self.warning(msg, *args, **kwargs)

def exception(self, msg, *args, exc_info=True, **kwargs):
    """Convenience method for logging an ERROR with exception information."""
    self.error(msg, *args, exc_info=exc_info, **kwargs)

def fatal(self, msg, *args, **kwargs):
    """Don't use this method, use critical() instead."""
    self.critical(msg, *args, **kwargs)

def log(self, level, msg, *args, **kwargs):
    """Log 'msg % args' with the integer severity 'level'.

    To pass exception information, use the keyword argument exc_info with
    a true value, e.g.

    logger.log(level, "We have a %s", "mysterious problem", exc_info=True)"""
    if not isinstance(level, int):
        if raiseExceptions:
            raise TypeError('level must be an integer')
        else:
            return
    if self.isEnabledFor(level):
        self._log(level, msg, args, **kwargs)

def findCaller(self, stack_info=False, stacklevel=1):
    """Find the stack frame of the caller so that we can note the source
    file name, line number and function name."""
    f = currentframe()
    if f is None:
        return ('(unknown file)', 0, '(unknown function)', None)
    while stacklevel > 0:
        next_f = f.f_back
        if next_f is None:
            break
        f = next_f
        if not _is_internal_frame(f):
            stacklevel -= 1
    co = f.f_code
    sinfo = None
    if stack_info:
        with io.StringIO() as sio:
            sio.write('Stack (most recent call last):\n')
            traceback.print_stack(f, file=sio)
            sinfo = sio.getvalue()
            if sinfo[-1] == '\n':
                sinfo = sinfo[:-1]
    return (co.co_filename, f.f_lineno, co.co_name, sinfo)

def makeRecord(self, name, level, fn, lno, msg, args, exc_info, func=None, extra=None, sinfo=None):
    """A factory method which can be overridden in subclasses to create
    specialized LogRecords."""
    rv = _logRecordFactory(name, level, fn, lno, msg, args, exc_info, func, sinfo)
    if extra is not None:
        for key in extra:
            if key in ['message', 'asctime'] or key in rv.__dict__:
                raise KeyError('Attempt to overwrite %r in LogRecord' % key)
            rv.__dict__[key] = extra[key]
    return rv

def _log(self, level, msg, args, exc_info=None, extra=None, stack_info=False, stacklevel=1):
    """Low-level logging routine which creates a LogRecord and then calls
    all the handlers of this logger to handle the record."""
    sinfo = None
    if _srcfile:
        try:
            fn, lno, func, sinfo = self.findCaller(stack_info, stacklevel)
        except ValueError:
            fn, lno, func = ('(unknown file)', 0, '(unknown function)')
    else:
        fn, lno, func = ('(unknown file)', 0, '(unknown function)')
    if exc_info:
        if isinstance(exc_info, BaseException):
            exc_info = (type(exc_info), exc_info, exc_info.__traceback__)
        elif not isinstance(exc_info, tuple):
            exc_info = sys.exc_info()
    record = self.makeRecord(self.name, level, fn, lno, msg, args, exc_info, func, extra, sinfo)
    self.handle(record)

def handle(self, record):
    """Call the handlers for the specified record.

    This method is used for unpickled records received from a socket, as
    well as those created locally. Logger-level filtering is applied."""
    if self.disabled:
        return
    maybe_record = self.filter(record)
    if not maybe_record:
        return
    if isinstance(maybe_record, LogRecord):
        record = maybe_record
    self.callHandlers(record)

def addHandler(self, hdlr):
    """Add the specified handler to this logger."""
    _acquireLock()
    try:
        if not hdlr in self.handlers:
            self.handlers.append(hdlr)
    finally:
        _releaseLock()

def removeHandler(self, hdlr):
    """Remove the specified handler from this logger."""
    _acquireLock()
    try:
        if hdlr in self.handlers:
            self.handlers.remove(hdlr)
    finally:
        _releaseLock()

def callHandlers(self, record):
    """Pass a record to all relevant handlers.

    Loop through all handlers for this logger and its parents in the
    logger hierarchy. If no handler was found, output a one-off error
    message to sys.stderr. Stop searching up the hierarchy whenever a
    logger with the "propagate" attribute set to zero is found - that
    will be the last logger whose handlers are called."""
    c = self
    found = 0
    while c:
        for hdlr in c.handlers:
            found = found + 1
            if record.levelno >= hdlr.level:
                hdlr.handle(record)
        if not c.propagate:
            c = None
        else:
            c = c.parent
    if found == 0:
        if lastResort:
            if record.levelno >= lastResort.level:
                lastResort.handle(record)
        elif raiseExceptions and (not self.manager.emittedNoHandlerWarning):
            sys.stderr.write('No handlers could be found for logger "%s"\n' % self.name)
            self.manager.emittedNoHandlerWarning = True

def getEffectiveLevel(self):
    """Get the effective level for this logger.

    Loop through this logger and its parents in the logger hierarchy,
    looking for a non-zero logging level. Return the first one found."""
    logger = self
    while logger:
        if logger.level:
            return logger.level
        logger = logger.parent
    return NOTSET

def isEnabledFor(self, level):
    """Is this logger enabled for level 'level'?"""
    if self.disabled:
        return False
    try:
        return self._cache[level]
    except KeyError:
        _acquireLock()
        try:
            if self.manager.disable >= level:
                is_enabled = self._cache[level] = False
            else:
                is_enabled = self._cache[level] = level >= self.getEffectiveLevel()
        finally:
            _releaseLock()
        return is_enabled

def getChildren(self):
    def _hierlevel(logger):
        if logger is logger.manager.root:
            return 0
        return 1 + logger.name.count('.')
    d = self.manager.loggerDict
    _acquireLock()
    try:
        return set((item for item in d.values() if isinstance(item, Logger) and item.parent is self and (_hierlevel(item) == 1 + _hierlevel(item.parent))))
    finally:
        _releaseLock()

def __init__(self, level):
    """Initialize the logger with the name "root"."""
    Logger.__init__(self, 'root', level)

def debug(self, msg, *args, **kwargs):
    """Delegate a debug call to the underlying logger."""
    self.log(DEBUG, msg, *args, **kwargs)

def info(self, msg, *args, **kwargs):
    """Delegate an info call to the underlying logger."""
    self.log(INFO, msg, *args, **kwargs)

def warning(self, msg, *args, **kwargs):
    """Delegate a warning call to the underlying logger."""
    self.log(WARNING, msg, *args, **kwargs)

def error(self, msg, *args, **kwargs):
    """Delegate an error call to the underlying logger."""
    self.log(ERROR, msg, *args, **kwargs)

def exception(self, msg, *args, exc_info=True, **kwargs):
    """Delegate an exception call to the underlying logger."""
    self.log(ERROR, msg, *args, exc_info=exc_info, **kwargs)

def critical(self, msg, *args, **kwargs):
    """Delegate a critical call to the underlying logger."""
    self.log(CRITICAL, msg, *args, **kwargs)

def log(self, level, msg, *args, **kwargs):
    """Delegate a log call to the underlying logger, after adding
    contextual information from this adapter instance."""
    if self.isEnabledFor(level):
        msg, kwargs = self.process(msg, kwargs)
        self.logger.log(level, msg, *args, **kwargs)

def isEnabledFor(self, level):
    """Is this logger enabled for level 'level'?"""
    return self.logger.isEnabledFor(level)

def setLevel(self, level):
    """Set the specified level on the underlying logger."""
    self.logger.setLevel(level)

def getEffectiveLevel(self):
    """Get the effective level for the underlying logger."""
    return self.logger.getEffectiveLevel()

def hasHandlers(self):
    """See if the underlying logger has any handlers."""
    return self.logger.hasHandlers()

def _log(self, level, msg, args, **kwargs):
    """Low-level log implementation, proxied to allow nested logger adapters."""
    return self.logger._log(level, msg, args, **kwargs)

@property
def manager(self):
    return self.logger.manager

@manager.setter
def manager(self, value):
    self.logger.manager = value

@property
def name(self):
    return self.logger.name

def __repr__(self):
    logger = self.logger
    level = getLevelName(logger.getEffectiveLevel())
    return '<%s %s (%s)>' % (self.__class__.__name__, logger.name, level)

def _hierlevel(logger):
    if logger is logger.manager.root:
        return 0
    return 1 + logger.name.count('.')

def fileConfig(fname, defaults=None, disable_existing_loggers=True, encoding=None):
    """Read the logging configuration from a ConfigParser-format file.

    This can be called several times from an application, allowing an end user
    the ability to select from various pre-canned configurations (if the
    developer provides a mechanism to present the choices and load the chosen
    configuration)."""
    import configparser
    if isinstance(fname, str):
        if not os.path.exists(fname):
            raise FileNotFoundError(f"{fname} doesn't exist")
        elif not os.path.getsize(fname):
            raise RuntimeError(f'{fname} is an empty file')
    if isinstance(fname, configparser.RawConfigParser):
        cp = fname
    else:
        try:
            cp = configparser.ConfigParser(defaults)
            if hasattr(fname, 'readline'):
                cp.read_file(fname)
            else:
                encoding = io.text_encoding(encoding)
                cp.read(fname, encoding=encoding)
        except configparser.ParsingError as e:
            raise RuntimeError(f'{fname} is invalid: {e}')
    formatters = _create_formatters(cp)
    logging._acquireLock()
    try:
        _clearExistingHandlers()
        handlers = _install_handlers(cp, formatters)
        _install_loggers(cp, handlers, disable_existing_loggers)
    finally:
        logging._releaseLock()

def _resolve(name):
    """Resolve a dotted name to a global object."""
    name = name.split('.')
    used = name.pop(0)
    found = __import__(used)
    for n in name:
        used = used + '.' + n
        try:
            found = getattr(found, n)
        except AttributeError:
            __import__(used)
            found = getattr(found, n)
    return found

def _create_formatters(cp):
    """Create and return formatters"""
    flist = cp['formatters']['keys']
    if not len(flist):
        return {}
    flist = flist.split(',')
    flist = _strip_spaces(flist)
    formatters = {}
    for form in flist:
        sectname = 'formatter_%s' % form
        fs = cp.get(sectname, 'format', raw=True, fallback=None)
        dfs = cp.get(sectname, 'datefmt', raw=True, fallback=None)
        stl = cp.get(sectname, 'style', raw=True, fallback='%')
        defaults = cp.get(sectname, 'defaults', raw=True, fallback=None)
        c = logging.Formatter
        class_name = cp[sectname].get('class')
        if class_name:
            c = _resolve(class_name)
        if defaults is not None:
            defaults = eval(defaults, vars(logging))
            f = c(fs, dfs, stl, defaults=defaults)
        else:
            f = c(fs, dfs, stl)
        formatters[form] = f
    return formatters

def _install_handlers(cp, formatters):
    """Install and return handlers"""
    hlist = cp['handlers']['keys']
    if not len(hlist):
        return {}
    hlist = hlist.split(',')
    hlist = _strip_spaces(hlist)
    handlers = {}
    fixups = []
    for hand in hlist:
        section = cp['handler_%s' % hand]
        klass = section['class']
        fmt = section.get('formatter', '')
        try:
            klass = eval(klass, vars(logging))
        except (AttributeError, NameError):
            klass = _resolve(klass)
        args = section.get('args', '()')
        args = eval(args, vars(logging))
        kwargs = section.get('kwargs', '{}')
        kwargs = eval(kwargs, vars(logging))
        h = klass(*args, **kwargs)
        h.name = hand
        if 'level' in section:
            level = section['level']
            h.setLevel(level)
        if len(fmt):
            h.setFormatter(formatters[fmt])
        if issubclass(klass, logging.handlers.MemoryHandler):
            target = section.get('target', '')
            if len(target):
                fixups.append((h, target))
        handlers[hand] = h
    for h, t in fixups:
        h.setTarget(handlers[t])
    return handlers

def _handle_existing_loggers(existing, child_loggers, disable_existing):
    """When (re)configuring logging, handle loggers which were in the previous
    configuration but are not in the new configuration. There's no point
    deleting them as other threads may continue to hold references to them;
    and by disabling them, you stop them doing any logging.

    However, don't disable children of named loggers, as that's probably not
    what was intended by the user. Also, allow existing loggers to NOT be
    disabled if disable_existing is false."""
    root = logging.root
    for log in existing:
        logger = root.manager.loggerDict[log]
        if log in child_loggers:
            if not isinstance(logger, logging.PlaceHolder):
                logger.setLevel(logging.NOTSET)
                logger.handlers = []
                logger.propagate = True
        else:
            logger.disabled = disable_existing

def valid_ident(s):
    m = IDENTIFIER.match(s)
    if not m:
        raise ValueError('Not a valid Python identifier: %r' % s)
    return True

def _is_queue_like_object(obj):
    """Check that *obj* implements the Queue API."""
    if isinstance(obj, (queue.Queue, queue.SimpleQueue)):
        return True
    from multiprocessing.queues import Queue as MPQueue
    if isinstance(obj, MPQueue):
        return True
    minimal_queue_interface = ['put_nowait', 'get']
    return all((callable(getattr(obj, method, None)) for method in minimal_queue_interface))

def dictConfig(config):
    """Configure logging using a dictionary."""
    dictConfigClass(config).configure()

def stopListening():
    """Stop the listening server which was created with a call to listen()."""
    global _listener
    logging._acquireLock()
    try:
        if _listener:
            _listener.abort = 1
            _listener = None
    finally:
        logging._releaseLock()

def convert_with_key(self, key, value, replace=True):
    result = self.configurator.convert(value)
    if value is not result:
        if replace:
            self[key] = result
        if type(result) in (ConvertingDict, ConvertingList, ConvertingTuple):
            result.parent = self
            result.key = key
    return result

def convert(self, value):
    result = self.configurator.convert(value)
    if value is not result:
        if type(result) in (ConvertingDict, ConvertingList, ConvertingTuple):
            result.parent = self
    return result

def __getitem__(self, key):
    value = dict.__getitem__(self, key)
    return self.convert_with_key(key, value)

def pop(self, key, default=None):
    value = dict.pop(self, key, default)
    return self.convert_with_key(key, value, replace=False)

def __getitem__(self, key):
    value = list.__getitem__(self, key)
    return self.convert_with_key(key, value)

def pop(self, idx=-1):
    value = list.pop(self, idx)
    return self.convert(value)

def __getitem__(self, key):
    value = tuple.__getitem__(self, key)
    return self.convert_with_key(key, value, replace=False)

def __init__(self, config):
    self.config = ConvertingDict(config)
    self.config.configurator = self

def resolve(self, s):
    """Resolve strings to objects using standard import and attribute
    syntax."""
    name = s.split('.')
    used = name.pop(0)
    try:
        found = self.importer(used)
        for frag in name:
            used += '.' + frag
            try:
                found = getattr(found, frag)
            except AttributeError:
                self.importer(used)
                found = getattr(found, frag)
        return found
    except ImportError as e:
        v = ValueError('Cannot resolve %r: %s' % (s, e))
        raise v from e

def cfg_convert(self, value):
    """Default converter for the cfg:// protocol."""
    rest = value
    m = self.WORD_PATTERN.match(rest)
    if m is None:
        raise ValueError('Unable to convert %r' % value)
    else:
        rest = rest[m.end():]
        d = self.config[m.groups()[0]]
        while rest:
            m = self.DOT_PATTERN.match(rest)
            if m:
                d = d[m.groups()[0]]
            else:
                m = self.INDEX_PATTERN.match(rest)
                if m:
                    idx = m.groups()[0]
                    if not self.DIGIT_PATTERN.match(idx):
                        d = d[idx]
                    else:
                        try:
                            n = int(idx)
                            d = d[n]
                        except TypeError:
                            d = d[idx]
            if m:
                rest = rest[m.end():]
            else:
                raise ValueError('Unable to convert %r at %r' % (value, rest))
    return d

def configure_custom(self, config):
    """Configure an object with a user-supplied factory."""
    c = config.pop('()')
    if not callable(c):
        c = self.resolve(c)
    kwargs = {k: config[k] for k in config if k != '.' and valid_ident(k)}
    result = c(**kwargs)
    props = config.pop('.', None)
    if props:
        for name, value in props.items():
            setattr(result, name, value)
    return result

def as_tuple(self, value):
    """Utility function which converts lists to tuples."""
    if isinstance(value, list):
        value = tuple(value)
    return value

def configure_formatter(self, config):
    """Configure a formatter from a dictionary."""
    if '()' in config:
        factory = config['()']
        try:
            result = self.configure_custom(config)
        except TypeError as te:
            if "'format'" not in str(te):
                raise
            config['fmt'] = config.pop('format')
            config['()'] = factory
            result = self.configure_custom(config)
    else:
        fmt = config.get('format', None)
        dfmt = config.get('datefmt', None)
        style = config.get('style', '%')
        cname = config.get('class', None)
        defaults = config.get('defaults', None)
        if not cname:
            c = logging.Formatter
        else:
            c = _resolve(cname)
        kwargs = {}
        if defaults is not None:
            kwargs['defaults'] = defaults
        if 'validate' in config:
            result = c(fmt, dfmt, style, config['validate'], **kwargs)
        else:
            result = c(fmt, dfmt, style, **kwargs)
    return result

def configure_filter(self, config):
    """Configure a filter from a dictionary."""
    if '()' in config:
        result = self.configure_custom(config)
    else:
        name = config.get('name', '')
        result = logging.Filter(name)
    return result

def add_filters(self, filterer, filters):
    """Add filters to a filterer from a list of names."""
    for f in filters:
        try:
            if callable(f) or callable(getattr(f, 'filter', None)):
                filter_ = f
            else:
                filter_ = self.config['filters'][f]
            filterer.addFilter(filter_)
        except Exception as e:
            raise ValueError('Unable to add filter %r' % f) from e

def add_handlers(self, logger, handlers):
    """Add handlers to a logger from a list of names."""
    for h in handlers:
        try:
            logger.addHandler(self.config['handlers'][h])
        except Exception as e:
            raise ValueError('Unable to add handler %r' % h) from e

def common_logger_config(self, logger, config, incremental=False):
    """Perform configuration which is common to root and non-root loggers."""
    level = config.get('level', None)
    if level is not None:
        logger.setLevel(logging._checkLevel(level))
    if not incremental:
        for h in logger.handlers[:]:
            logger.removeHandler(h)
        handlers = config.get('handlers', None)
        if handlers:
            self.add_handlers(logger, handlers)
        filters = config.get('filters', None)
        if filters:
            self.add_filters(logger, filters)

def handle(self):
    """Handle a request.

    Each request is expected to be a 4-byte length, packed using
    struct.pack(">L", n), followed by the config file.
    Uses fileConfig() to do the grunt work."""
    try:
        conn = self.connection
        chunk = conn.recv(4)
        if len(chunk) == 4:
            slen = struct.unpack('>L', chunk)[0]
            chunk = self.connection.recv(slen)
            while len(chunk) < slen:
                chunk = chunk + conn.recv(slen - len(chunk))
            if self.server.verify is not None:
                chunk = self.server.verify(chunk)
            if chunk is not None:
                chunk = chunk.decode('utf-8')
                try:
                    import json
                    d = json.loads(chunk)
                    assert isinstance(d, dict)
                    dictConfig(d)
                except Exception:
                    file = io.StringIO(chunk)
                    try:
                        fileConfig(file)
                    except Exception:
                        traceback.print_exc()
            if self.server.ready:
                self.server.ready.set()
    except OSError as e:
        if e.errno != RESET_ERROR:
            raise

def emit(self, record):
    """Emit a record.

    Output the record to the file, catering for rollover as described
    in doRollover()."""
    try:
        if self.shouldRollover(record):
            self.doRollover()
        logging.FileHandler.emit(self, record)
    except Exception:
        self.handleError(record)

def doRollover(self):
    """Do a rollover, as described in __init__()."""
    if self.stream:
        self.stream.close()
        self.stream = None
    if self.backupCount > 0:
        for i in range(self.backupCount - 1, 0, -1):
            sfn = self.rotation_filename('%s.%d' % (self.baseFilename, i))
            dfn = self.rotation_filename('%s.%d' % (self.baseFilename, i + 1))
            if os.path.exists(sfn):
                if os.path.exists(dfn):
                    os.remove(dfn)
                os.rename(sfn, dfn)
        dfn = self.rotation_filename(self.baseFilename + '.1')
        if os.path.exists(dfn):
            os.remove(dfn)
        self.rotate(self.baseFilename, dfn)
    if not self.delay:
        self.stream = self._open()

def shouldRollover(self, record):
    """Determine if rollover should occur.

    Basically, see if the supplied record would cause the file to exceed
    the size limit we have."""
    if self.stream is None:
        self.stream = self._open()
    if self.maxBytes > 0:
        pos = self.stream.tell()
        if not pos:
            return False
        msg = '%s\n' % self.format(record)
        if pos + len(msg) >= self.maxBytes:
            if os.path.exists(self.baseFilename) and (not os.path.isfile(self.baseFilename)):
                return False
            return True
    return False

def getFilesToDelete(self):
    """Determine the files to delete when rolling over.

    More specific than the earlier method, which just used glob.glob()."""
    dirName, baseName = os.path.split(self.baseFilename)
    fileNames = os.listdir(dirName)
    result = []
    if self.namer is None:
        prefix = baseName + '.'
        plen = len(prefix)
        for fileName in fileNames:
            if fileName[:plen] == prefix:
                suffix = fileName[plen:]
                if self.extMatch.fullmatch(suffix):
                    result.append(os.path.join(dirName, fileName))
    else:
        for fileName in fileNames:
            m = self.extMatch.search(fileName)
            while m:
                dfn = self.namer(self.baseFilename + '.' + m[0])
                if os.path.basename(dfn) == fileName:
                    result.append(os.path.join(dirName, fileName))
                    break
                m = self.extMatch.search(fileName, m.start() + 1)
    if len(result) < self.backupCount:
        result = []
    else:
        result.sort()
        result = result[:len(result) - self.backupCount]
    return result

def doRollover(self):
    """do a rollover; in this case, a date/time stamp is appended to the filename
    when the rollover happens.  However, you want the file to be named for the
    start of the interval, not the current time.  If there is a backup count,
    then we have to get a list of matching filenames, sort them and remove
    the one with the oldest suffix."""
    currentTime = int(time.time())
    t = self.rolloverAt - self.interval
    if self.utc:
        timeTuple = time.gmtime(t)
    else:
        timeTuple = time.localtime(t)
        dstNow = time.localtime(currentTime)[-1]
        dstThen = timeTuple[-1]
        if dstNow != dstThen:
            if dstNow:
                addend = 3600
            else:
                addend = -3600
            timeTuple = time.localtime(t + addend)
    dfn = self.rotation_filename(self.baseFilename + '.' + time.strftime(self.suffix, timeTuple))
    if os.path.exists(dfn):
        return
    if self.stream:
        self.stream.close()
        self.stream = None
    self.rotate(self.baseFilename, dfn)
    if self.backupCount > 0:
        for s in self.getFilesToDelete():
            os.remove(s)
    if not self.delay:
        self.stream = self._open()
    self.rolloverAt = self.computeRollover(currentTime)

def __init__(self, filename, mode='a', encoding=None, delay=False, errors=None):
    if 'b' not in mode:
        encoding = io.text_encoding(encoding)
    logging.FileHandler.__init__(self, filename, mode=mode, encoding=encoding, delay=delay, errors=errors)
    self.dev, self.ino = (-1, -1)
    self._statstream()

def _statstream(self):
    if self.stream:
        sres = os.fstat(self.stream.fileno())
        self.dev, self.ino = (sres[ST_DEV], sres[ST_INO])

def reopenIfNeeded(self):
    """Reopen log file if needed.

    Checks if the underlying file has changed, and if it
    has, close the old stream and reopen the file to get the
    current stream."""
    try:
        sres = os.stat(self.baseFilename)
    except FileNotFoundError:
        sres = None
    if not sres or sres[ST_DEV] != self.dev or sres[ST_INO] != self.ino:
        if self.stream is not None:
            self.stream.flush()
            self.stream.close()
            self.stream = None
            self.stream = self._open()
            self._statstream()

def makeSocket(self, timeout=1):
    """A factory method which allows subclasses to define the precise
    type of socket they want."""
    if self.port is not None:
        result = socket.create_connection(self.address, timeout=timeout)
    else:
        result = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        result.settimeout(timeout)
        try:
            result.connect(self.address)
        except OSError:
            result.close()
            raise
    return result

def createSocket(self):
    """Try to create a socket, using an exponential backoff with
    a max retry time. Thanks to Robert Olson for the original patch
    (SF #815911) which has been slightly refactored."""
    now = time.time()
    if self.retryTime is None:
        attempt = True
    else:
        attempt = now >= self.retryTime
    if attempt:
        try:
            self.sock = self.makeSocket()
            self.retryTime = None
        except OSError:
            if self.retryTime is None:
                self.retryPeriod = self.retryStart
            else:
                self.retryPeriod = self.retryPeriod * self.retryFactor
                if self.retryPeriod > self.retryMax:
                    self.retryPeriod = self.retryMax
            self.retryTime = now + self.retryPeriod

def send(self, s):
    """Send a pickled string to the socket.

    This function allows for partial sends which can happen when the
    network is busy."""
    if self.sock is None:
        self.createSocket()
    if self.sock:
        try:
            self.sock.sendall(s)
        except OSError:
            self.sock.close()
            self.sock = None

def handleError(self, record):
    """Handle an error during logging.

    An error has occurred during logging. Most likely cause -
    connection lost. Close the socket so that we can retry on the
    next event."""
    if self.closeOnError and self.sock:
        self.sock.close()
        self.sock = None
    else:
        logging.Handler.handleError(self, record)

def makeSocket(self):
    """The factory method of SocketHandler is here overridden to create
    a UDP socket (SOCK_DGRAM)."""
    if self.port is None:
        family = socket.AF_UNIX
    else:
        family = socket.AF_INET
    s = socket.socket(family, socket.SOCK_DGRAM)
    return s

def _connect_unixsocket(self, address):
    use_socktype = self.socktype
    if use_socktype is None:
        use_socktype = socket.SOCK_DGRAM
    self.socket = socket.socket(socket.AF_UNIX, use_socktype)
    try:
        self.socket.connect(address)
        self.socktype = use_socktype
    except OSError:
        self.socket.close()
        if self.socktype is not None:
            raise
        use_socktype = socket.SOCK_STREAM
        self.socket = socket.socket(socket.AF_UNIX, use_socktype)
        try:
            self.socket.connect(address)
            self.socktype = use_socktype
        except OSError:
            self.socket.close()
            raise

def createSocket(self):
    """Try to create a socket and, if it's not a datagram socket, connect it
    to the other end. This method is called during handler initialization,
    but it's not regarded as an error if the other end isn't listening yet
    --- the method will be called again when emitting an event,
    if there is no socket at that point."""
    address = self.address
    socktype = self.socktype
    if isinstance(address, str):
        self.unixsocket = True
        try:
            self._connect_unixsocket(address)
        except OSError:
            pass
    else:
        self.unixsocket = False
        if socktype is None:
            socktype = socket.SOCK_DGRAM
        host, port = address
        ress = socket.getaddrinfo(host, port, 0, socktype)
        if not ress:
            raise OSError('getaddrinfo returns an empty list')
        for res in ress:
            af, socktype, proto, _, sa = res
            err = sock = None
            try:
                sock = socket.socket(af, socktype, proto)
                if socktype == socket.SOCK_STREAM:
                    sock.connect(sa)
                break
            except OSError as exc:
                err = exc
                if sock is not None:
                    sock.close()
        if err is not None:
            raise err
        self.socket = sock
        self.socktype = socktype

def encodePriority(self, facility, priority):
    """Encode the facility and priority. You can pass in strings or
    integers - if strings are passed, the facility_names and
    priority_names mapping dictionaries are used to convert them to
    integers."""
    if isinstance(facility, str):
        facility = self.facility_names[facility]
    if isinstance(priority, str):
        priority = self.priority_names[priority]
    return facility << 3 | priority

def emit(self, record):
    """Emit a record.

    The record is formatted, and then sent to the syslog server. If
    exception information is present, it is NOT sent to the server."""
    try:
        msg = self.format(record)
        if self.ident:
            msg = self.ident + msg
        if self.append_nul:
            msg += '\x00'
        prio = '<%d>' % self.encodePriority(self.facility, self.mapPriority(record.levelname))
        prio = prio.encode('utf-8')
        msg = msg.encode('utf-8')
        msg = prio + msg
        if not self.socket:
            self.createSocket()
        if self.unixsocket:
            try:
                self.socket.send(msg)
            except OSError:
                self.socket.close()
                self._connect_unixsocket(self.address)
                self.socket.send(msg)
        elif self.socktype == socket.SOCK_DGRAM:
            self.socket.sendto(msg, self.address)
        else:
            self.socket.sendall(msg)
    except Exception:
        self.handleError(record)

def __init__(self, appname, dllname=None, logtype='Application'):
    logging.Handler.__init__(self)
    try:
        import win32evtlogutil, win32evtlog
        self.appname = appname
        self._welu = win32evtlogutil
        if not dllname:
            dllname = os.path.split(self._welu.__file__)
            dllname = os.path.split(dllname[0])
            dllname = os.path.join(dllname[0], 'win32service.pyd')
        self.dllname = dllname
        self.logtype = logtype
        try:
            self._welu.AddSourceToRegistry(appname, dllname, logtype)
        except Exception as e:
            if getattr(e, 'winerror', None) != 5:
                raise
        self.deftype = win32evtlog.EVENTLOG_ERROR_TYPE
        self.typemap = {logging.DEBUG: win32evtlog.EVENTLOG_INFORMATION_TYPE, logging.INFO: win32evtlog.EVENTLOG_INFORMATION_TYPE, logging.WARNING: win32evtlog.EVENTLOG_WARNING_TYPE, logging.ERROR: win32evtlog.EVENTLOG_ERROR_TYPE, logging.CRITICAL: win32evtlog.EVENTLOG_ERROR_TYPE}
    except ImportError:
        print('The Python Win32 extensions for NT (service, event logging) appear not to be available.')
        self._welu = None

def emit(self, record):
    """Emit a record.

    Determine the message ID, event category and event type. Then
    log the message in the NT event log."""
    if self._welu:
        try:
            id = self.getMessageID(record)
            cat = self.getEventCategory(record)
            type = self.getEventType(record)
            msg = self.format(record)
            self._welu.ReportEvent(self.appname, id, cat, type, [msg])
        except Exception:
            self.handleError(record)

def getConnection(self, host, secure):
    """get a HTTP[S]Connection.

    Override when a custom connection is required, for example if
    there is a proxy."""
    import http.client
    if secure:
        connection = http.client.HTTPSConnection(host, context=self.context)
    else:
        connection = http.client.HTTPConnection(host)
    return connection

def emit(self, record):
    """Emit a record.

    Send the record to the web server as a percent-encoded dictionary"""
    try:
        import urllib.parse
        host = self.host
        h = self.getConnection(host, self.secure)
        url = self.url
        data = urllib.parse.urlencode(self.mapLogRecord(record))
        if self.method == 'GET':
            if url.find('?') >= 0:
                sep = '&'
            else:
                sep = '?'
            url = url + '%c%s' % (sep, data)
        h.putrequest(self.method, url)
        i = host.find(':')
        if i >= 0:
            host = host[:i]
        if self.method == 'POST':
            h.putheader('Content-type', 'application/x-www-form-urlencoded')
            h.putheader('Content-length', str(len(data)))
        if self.credentials:
            import base64
            s = ('%s:%s' % self.credentials).encode('utf-8')
            s = 'Basic ' + base64.b64encode(s).strip().decode('ascii')
            h.putheader('Authorization', s)
        h.endheaders()
        if self.method == 'POST':
            h.send(data.encode('utf-8'))
        h.getresponse()
    except Exception:
        self.handleError(record)

def shouldFlush(self, record):
    """Check for buffer full or a record at the flushLevel or higher."""
    return len(self.buffer) >= self.capacity or record.levelno >= self.flushLevel

def flush(self):
    """For a MemoryHandler, flushing means just sending the buffered
    records to the target, if there is one. Override if you want
    different behaviour.

    The record buffer is only cleared if a target has been set."""
    self.acquire()
    try:
        if self.target:
            for record in self.buffer:
                self.target.handle(record)
            self.buffer.clear()
    finally:
        self.release()

def close(self):
    """Flush, if appropriately configured, set the target to None and lose the
    buffer."""
    try:
        if self.flushOnClose:
            self.flush()
    finally:
        self.acquire()
        try:
            self.target = None
            BufferingHandler.close(self)
        finally:
            self.release()

def emit(self, record):
    """Emit a record.

    Writes the LogRecord to the queue, preparing it for pickling first."""
    try:
        self.enqueue(self.prepare(record))
    except Exception:
        self.handleError(record)

def dequeue(self, block):
    """Dequeue a record and return it, optionally blocking.

    The base implementation uses get. You may want to override this method
    if you want to use timeouts or work with custom queue implementations."""
    return self.queue.get(block)

def handle(self, record):
    """Handle a record.

    This just loops through the handlers offering them the record
    to handle."""
    record = self.prepare(record)
    for handler in self.handlers:
        if not self.respect_handler_level:
            process = True
        else:
            process = record.levelno >= handler.level
        if process:
            handler.handle(record)

def _monitor(self):
    """Monitor the queue for records, and ask the handler
    to deal with them.

    This method runs on a separate, internal thread.
    The thread will terminate if it sees a sentinel object in the queue."""
    q = self.queue
    has_task_done = hasattr(q, 'task_done')
    while True:
        try:
            record = self.dequeue(True)
            if record is self._sentinel:
                if has_task_done:
                    q.task_done()
                break
            self.handle(record)
            if has_task_done:
                q.task_done()
        except queue.Empty:
            break

def decompress(data, format=FORMAT_AUTO, memlimit=None, filters=None):
    """Decompress a block of data.

    Refer to LZMADecompressor's docstring for a description of the
    optional arguments *format*, *check* and *filters*.

    For incremental decompression, use an LZMADecompressor instead."""
    results = []
    while True:
        decomp = LZMADecompressor(format, memlimit, filters)
        try:
            res = decomp.decompress(data)
        except LZMAError:
            if results:
                break
            else:
                raise
        results.append(res)
        if not decomp.eof:
            raise LZMAError('Compressed data ended before the end-of-stream marker was reached')
        data = decomp.unused_data
        if not data:
            break
    return b''.join(results)

def close(self):
    """Flush and close the file.

    May be called more than once without error. Once the file is
    closed, any other operation on it will raise a ValueError."""
    if self._mode == _MODE_CLOSED:
        return
    try:
        if self._mode == _MODE_READ:
            self._buffer.close()
            self._buffer = None
        elif self._mode == _MODE_WRITE:
            self._fp.write(self._compressor.flush())
            self._compressor = None
    finally:
        try:
            if self._closefp:
                self._fp.close()
        finally:
            self._fp = None
            self._closefp = False
            self._mode = _MODE_CLOSED

def read(self, size=-1):
    """Read up to size uncompressed bytes from the file.

    If size is negative or omitted, read until EOF is reached.
    Returns b"" if the file is already at EOF."""
    self._check_can_read()
    return self._buffer.read(size)

def read1(self, size=-1):
    """Read up to size uncompressed bytes, while trying to avoid
    making multiple reads from the underlying stream. Reads up to a
    buffer's worth of data if size is negative.

    Returns b"" if the file is at EOF."""
    self._check_can_read()
    if size < 0:
        size = io.DEFAULT_BUFFER_SIZE
    return self._buffer.read1(size)

def _lock_file(f, dotlock=True):
    """Lock file f using lockf and dot locking."""
    dotlock_done = False
    try:
        if fcntl:
            try:
                fcntl.lockf(f, fcntl.LOCK_EX | fcntl.LOCK_NB)
            except OSError as e:
                if e.errno in (errno.EAGAIN, errno.EACCES, errno.EROFS):
                    raise ExternalClashError('lockf: lock unavailable: %s' % f.name)
                else:
                    raise
        if dotlock:
            try:
                pre_lock = _create_temporary(f.name + '.lock')
                pre_lock.close()
            except OSError as e:
                if e.errno in (errno.EACCES, errno.EROFS):
                    return
                else:
                    raise
            try:
                try:
                    os.link(pre_lock.name, f.name + '.lock')
                    dotlock_done = True
                except (AttributeError, PermissionError):
                    os.rename(pre_lock.name, f.name + '.lock')
                    dotlock_done = True
                else:
                    os.unlink(pre_lock.name)
            except FileExistsError:
                os.remove(pre_lock.name)
                raise ExternalClashError('dot lock unavailable: %s' % f.name)
    except:
        if fcntl:
            fcntl.lockf(f, fcntl.LOCK_UN)
        if dotlock_done:
            os.remove(f.name + '.lock')
        raise

def _unlock_file(f):
    """Unlock file f using lockf and dot locking."""
    if fcntl:
        fcntl.lockf(f, fcntl.LOCK_UN)
    if os.path.exists(f.name + '.lock'):
        os.remove(f.name + '.lock')

def _create_carefully(path):
    """Create a file if it doesn't exist and open for reading and writing."""
