def _main():
    import getopt
    USAGE = 'Usage: mimetypes.py [options] type\n\nOptions:\n    --help / -h       -- print this message and exit\n    --lenient / -l    -- additionally search of some common, but non-standard\n                         types.\n    --extension / -e  -- guess extension instead of type\n\nMore than one type argument may be given.\n'
    def usage(code, msg=''):
        print(USAGE)
        if msg:
            print(msg)
        sys.exit(code)
    try:
        opts, args = getopt.getopt(sys.argv[1:], 'hle', ['help', 'lenient', 'extension'])
    except getopt.error as msg:
        usage(1, msg)
    strict = 1
    extension = 0
    for opt, arg in opts:
        if opt in ('-h', '--help'):
            usage(0)
        elif opt in ('-l', '--lenient'):
            strict = 0
        elif opt in ('-e', '--extension'):
            extension = 1
    for gtype in args:
        if extension:
            guess = guess_extension(gtype, strict)
            if not guess:
                print("I don't know anything about type", gtype)
            else:
                print(guess)
        else:
            guess, encoding = guess_type(gtype, strict)
            if not guess:
                print("I don't know anything about type", gtype)
            else:
                print('type:', guess, 'encoding:', encoding)

def __init__(self, filenames=(), strict=True):
    if not inited:
        init()
    self.encodings_map = _encodings_map_default.copy()
    self.suffix_map = _suffix_map_default.copy()
    self.types_map = ({}, {})
    self.types_map_inv = ({}, {})
    for ext, type in _types_map_default.items():
        self.add_type(type, ext, True)
    for ext, type in _common_types_default.items():
        self.add_type(type, ext, False)
    for name in filenames:
        self.read(name, strict)

def readfp(self, fp, strict=True):
    """Read a single mime.types-format file.

    If strict is true, information will be added to
    list of standard types, else to the list of non-standard
    types."""
    while (line := fp.readline()):
        words = line.split()
        for i in range(len(words)):
            if words[i][0] == '#':
                del words[i:]
                break
        if not words:
            continue
        type, suffixes = (words[0], words[1:])
        for suff in suffixes:
            self.add_type(type, '.' + suff, strict)

def read_windows_registry(self, strict=True):
    """Load the MIME types database from Windows registry.

    If strict is true, information will be added to
    list of standard types, else to the list of non-standard
    types."""
    if not _mimetypes_read_windows_registry and (not _winreg):
        return
    add_type = self.add_type
    if strict:
        add_type = lambda type, ext: self.add_type(type, ext, True)
    if _mimetypes_read_windows_registry:
        _mimetypes_read_windows_registry(add_type)
    elif _winreg:
        self._read_windows_registry(add_type)

@classmethod
def _read_windows_registry(cls, add_type):
    def enum_types(mimedb):
        i = 0
        while True:
            try:
                ctype = _winreg.EnumKey(mimedb, i)
            except OSError:
                break
            else:
                if '\x00' not in ctype:
                    yield ctype
            i += 1
    with _winreg.OpenKey(_winreg.HKEY_CLASSES_ROOT, '') as hkcr:
        for subkeyname in enum_types(hkcr):
            try:
                with _winreg.OpenKey(hkcr, subkeyname) as subkey:
                    if not subkeyname.startswith('.'):
                        continue
                    mimetype, datatype = _winreg.QueryValueEx(subkey, 'Content Type')
                    if datatype != _winreg.REG_SZ:
                        continue
                    add_type(mimetype, subkeyname)
            except OSError:
                continue

def usage(code, msg=''):
    print(USAGE)
    if msg:
        print(msg)
    sys.exit(code)

def enum_types(mimedb):
    i = 0
    while True:
        try:
            ctype = _winreg.EnumKey(mimedb, i)
        except OSError:
            break
        else:
            if '\x00' not in ctype:
                yield ctype
        i += 1

def _find_module(name, path=None):
    """An importlib reimplementation of imp.find_module (for our purposes)."""
    importlib.machinery.PathFinder.invalidate_caches()
    spec = importlib.machinery.PathFinder.find_spec(name, path)
    if spec is None:
        raise ImportError('No module named {name!r}'.format(name=name), name=name)
    if spec.loader is importlib.machinery.BuiltinImporter:
        return (None, None, ('', '', _C_BUILTIN))
    if spec.loader is importlib.machinery.FrozenImporter:
        return (None, None, ('', '', _PY_FROZEN))
    file_path = spec.origin
    if spec.loader.is_package(name):
        return (None, os.path.dirname(file_path), ('', '', _PKG_DIRECTORY))
    if isinstance(spec.loader, importlib.machinery.SourceFileLoader):
        kind = _PY_SOURCE
    elif isinstance(spec.loader, importlib.machinery.ExtensionFileLoader):
        kind = _C_EXTENSION
    elif isinstance(spec.loader, importlib.machinery.SourcelessFileLoader):
        kind = _PY_COMPILED
    else:
        return (None, None, ('', '', _SEARCH_ERROR))
    file = io.open_code(file_path)
    suffix = os.path.splitext(file_path)[-1]
    return (file, file_path, (suffix, 'rb', kind))

def __init__(self, name, file=None, path=None):
    self.__name__ = name
    self.__file__ = file
    self.__path__ = path
    self.__code__ = None
    self.globalnames = {}
    self.starimports = {}

def __repr__(self):
    s = 'Module(%r' % (self.__name__,)
    if self.__file__ is not None:
        s = s + ', %r' % (self.__file__,)
    if self.__path__ is not None:
        s = s + ', %r' % (self.__path__,)
    s = s + ')'
    return s

def __init__(self, path=None, debug=0, excludes=None, replace_paths=None):
    if path is None:
        path = sys.path
    self.path = path
    self.modules = {}
    self.badmodules = {}
    self.debug = debug
    self.indent = 0
    self.excludes = excludes if excludes is not None else []
    self.replace_paths = replace_paths if replace_paths is not None else []
    self.processed_paths = []

def msg(self, level, str, *args):
    if level <= self.debug:
        for i in range(self.indent):
            print('   ', end=' ')
        print(str, end=' ')
        for arg in args:
            print(repr(arg), end=' ')
        print()

def msgin(self, *args):
    level = args[0]
    if level <= self.debug:
        self.indent = self.indent + 1
        self.msg(*args)

def msgout(self, *args):
    level = args[0]
    if level <= self.debug:
        self.indent = self.indent - 1
        self.msg(*args)

def import_hook(self, name, caller=None, fromlist=None, level=-1):
    self.msg(3, 'import_hook', name, caller, fromlist, level)
    parent = self.determine_parent(caller, level=level)
    q, tail = self.find_head_package(parent, name)
    m = self.load_tail(q, tail)
    if not fromlist:
        return q
    if m.__path__:
        self.ensure_fromlist(m, fromlist)
    return None

def find_head_package(self, parent, name):
    self.msgin(4, 'find_head_package', parent, name)
    if '.' in name:
        i = name.find('.')
        head = name[:i]
        tail = name[i + 1:]
    else:
        head = name
        tail = ''
    if parent:
        qname = '%s.%s' % (parent.__name__, head)
    else:
        qname = head
    q = self.import_module(head, qname, parent)
    if q:
        self.msgout(4, 'find_head_package ->', (q, tail))
        return (q, tail)
    if parent:
        qname = head
        parent = None
        q = self.import_module(head, qname, parent)
        if q:
            self.msgout(4, 'find_head_package ->', (q, tail))
            return (q, tail)
    self.msgout(4, 'raise ImportError: No module named', qname)
    raise ImportError('No module named ' + qname)

def ensure_fromlist(self, m, fromlist, recursive=0):
    self.msg(4, 'ensure_fromlist', m, fromlist, recursive)
    for sub in fromlist:
        if sub == '*':
            if not recursive:
                all = self.find_all_submodules(m)
                if all:
                    self.ensure_fromlist(m, all, 1)
        elif not hasattr(m, sub):
            subname = '%s.%s' % (m.__name__, sub)
            submod = self.import_module(sub, subname, m)
            if not submod:
                raise ImportError('No module named ' + subname)

def find_all_submodules(self, m):
    if not m.__path__:
        return
    modules = {}
    suffixes = []
    suffixes += importlib.machinery.EXTENSION_SUFFIXES[:]
    suffixes += importlib.machinery.SOURCE_SUFFIXES[:]
    suffixes += importlib.machinery.BYTECODE_SUFFIXES[:]
    for dir in m.__path__:
        try:
            names = os.listdir(dir)
        except OSError:
            self.msg(2, "can't list directory", dir)
            continue
        for name in names:
            mod = None
            for suff in suffixes:
                n = len(suff)
                if name[-n:] == suff:
                    mod = name[:-n]
                    break
            if mod and mod != '__init__':
                modules[mod] = mod
    return modules.keys()

def import_module(self, partname, fqname, parent):
    self.msgin(3, 'import_module', partname, fqname, parent)
    try:
        m = self.modules[fqname]
    except KeyError:
        pass
    else:
        self.msgout(3, 'import_module ->', m)
        return m
    if fqname in self.badmodules:
        self.msgout(3, 'import_module -> None')
        return None
    if parent and parent.__path__ is None:
        self.msgout(3, 'import_module -> None')
        return None
    try:
        fp, pathname, stuff = self.find_module(partname, parent and parent.__path__, parent)
    except ImportError:
        self.msgout(3, 'import_module ->', None)
        return None
    try:
        m = self.load_module(fqname, fp, pathname, stuff)
    finally:
        if fp:
            fp.close()
    if parent:
        setattr(parent, partname, m)
    self.msgout(3, 'import_module ->', m)
    return m

def load_module(self, fqname, fp, pathname, file_info):
    suffix, mode, type = file_info
    self.msgin(2, 'load_module', fqname, fp and 'fp', pathname)
    if type == _PKG_DIRECTORY:
        m = self.load_package(fqname, pathname)
        self.msgout(2, 'load_module ->', m)
        return m
    if type == _PY_SOURCE:
        co = compile(fp.read(), pathname, 'exec')
    elif type == _PY_COMPILED:
        try:
            data = fp.read()
            importlib._bootstrap_external._classify_pyc(data, fqname, {})
        except ImportError as exc:
            self.msgout(2, 'raise ImportError: ' + str(exc), pathname)
            raise
        co = marshal.loads(memoryview(data)[16:])
    else:
        co = None
    m = self.add_module(fqname)
    m.__file__ = pathname
    if co:
        if self.replace_paths:
            co = self.replace_paths_in_code(co)
        m.__code__ = co
        self.scan_code(co, m)
    self.msgout(2, 'load_module ->', m)
    return m

def _add_badmodule(self, name, caller):
    if name not in self.badmodules:
        self.badmodules[name] = {}
    if caller:
        self.badmodules[name][caller.__name__] = 1
    else:
        self.badmodules[name]['-'] = 1

def _safe_import_hook(self, name, caller, fromlist, level=-1):
    if name in self.badmodules:
        self._add_badmodule(name, caller)
        return
    try:
        self.import_hook(name, caller, level=level)
    except ImportError as msg:
        self.msg(2, 'ImportError:', str(msg))
        self._add_badmodule(name, caller)
    except SyntaxError as msg:
        self.msg(2, 'SyntaxError:', str(msg))
        self._add_badmodule(name, caller)
    else:
        if fromlist:
            for sub in fromlist:
                fullname = name + '.' + sub
                if fullname in self.badmodules:
                    self._add_badmodule(fullname, caller)
                    continue
                try:
                    self.import_hook(name, caller, [sub], level=level)
                except ImportError as msg:
                    self.msg(2, 'ImportError:', str(msg))
                    self._add_badmodule(fullname, caller)

def scan_opcodes(self, co):
    for name in dis._find_store_names(co):
        yield ('store', (name,))
    for name, level, fromlist in dis._find_imports(co):
        if level == 0:
            yield ('absolute_import', (fromlist, name))
        else:
            yield ('relative_import', (level, fromlist, name))

def scan_code(self, co, m):
    code = co.co_code
    scanner = self.scan_opcodes
    for what, args in scanner(co):
        if what == 'store':
            name, = args
            m.globalnames[name] = 1
        elif what == 'absolute_import':
            fromlist, name = args
            have_star = 0
            if fromlist is not None:
                if '*' in fromlist:
                    have_star = 1
                fromlist = [f for f in fromlist if f != '*']
            self._safe_import_hook(name, m, fromlist, level=0)
            if have_star:
                mm = None
                if m.__path__:
                    mm = self.modules.get(m.__name__ + '.' + name)
                if mm is None:
                    mm = self.modules.get(name)
                if mm is not None:
                    m.globalnames.update(mm.globalnames)
                    m.starimports.update(mm.starimports)
                    if mm.__code__ is None:
                        m.starimports[name] = 1
                else:
                    m.starimports[name] = 1
        elif what == 'relative_import':
            level, fromlist, name = args
            if name:
                self._safe_import_hook(name, m, fromlist, level=level)
            else:
                parent = self.determine_parent(m, level=level)
                self._safe_import_hook(parent.__name__, None, fromlist, level=0)
        else:
            raise RuntimeError(what)
    for c in co.co_consts:
        if isinstance(c, type(co)):
            self.scan_code(c, m)

def add_module(self, fqname):
    if fqname in self.modules:
        return self.modules[fqname]
    self.modules[fqname] = m = Module(fqname)
    return m

def find_module(self, name, path, parent=None):
    if parent is not None:
        fullname = parent.__name__ + '.' + name
    else:
        fullname = name
    if fullname in self.excludes:
        self.msgout(3, 'find_module -> Excluded', fullname)
        raise ImportError(name)
    if path is None:
        if name in sys.builtin_module_names:
            return (None, None, ('', '', _C_BUILTIN))
        path = self.path
    return _find_module(name, path)

def any_missing_maybe(self):
    """Return two lists, one with modules that are certainly missing
    and one with modules that *may* be missing. The latter names could
    either be submodules *or* just global names in the package.

    The reason it can't always be determined is that it's impossible to
    tell which names are imported when "from module import *" is done
    with an extension module, short of actually importing it."""
    missing = []
    maybe = []
    for name in self.badmodules:
        if name in self.excludes:
            continue
        i = name.rfind('.')
        if i < 0:
            missing.append(name)
            continue
        subname = name[i + 1:]
        pkgname = name[:i]
        pkg = self.modules.get(pkgname)
        if pkg is not None:
            if pkgname in self.badmodules[name]:
                missing.append(name)
            elif subname in pkg.globalnames:
                pass
            elif pkg.starimports:
                maybe.append(name)
            else:
                missing.append(name)
        else:
            missing.append(name)
    missing.sort()
    maybe.sort()
    return (missing, maybe)

def replace_paths_in_code(self, co):
    new_filename = original_filename = os.path.normpath(co.co_filename)
    for f, r in self.replace_paths:
        if original_filename.startswith(f):
            new_filename = r + original_filename[len(f):]
            break
    if self.debug and original_filename not in self.processed_paths:
        if new_filename != original_filename:
            self.msgout(2, 'co_filename %r changed to %r' % (original_filename, new_filename))
        else:
            self.msgout(2, 'co_filename %r remains unchanged' % (original_filename,))
        self.processed_paths.append(original_filename)
    consts = list(co.co_consts)
    for i in range(len(consts)):
        if isinstance(consts[i], type(co)):
            consts[i] = self.replace_paths_in_code(consts[i])
    return co.replace(co_consts=tuple(consts), co_filename=new_filename)

def arbitrary_address(family):
    """Return an arbitrary free address for the given family"""
    if family == 'AF_INET':
        return ('localhost', 0)
    elif family == 'AF_UNIX':
        return tempfile.mktemp(prefix='listener-', dir=util.get_temp_dir())
    elif family == 'AF_PIPE':
        return tempfile.mktemp(prefix='\\\\.\\pipe\\pyc-%d-%d-' % (os.getpid(), next(_mmap_counter)), dir='')
    else:
        raise ValueError('unrecognized family')

def _validate_family(family):
    """Checks if the family is valid for the current environment."""
    if sys.platform != 'win32' and family == 'AF_PIPE':
        raise ValueError('Family %s is not recognized.' % family)
    if sys.platform == 'win32' and family == 'AF_UNIX':
        if not hasattr(socket, family):
            raise ValueError('Family %s is not recognized.' % family)

def address_type(address):
    """Return the types of the address

    This can be 'AF_INET', 'AF_UNIX', or 'AF_PIPE'"""
    if type(address) == tuple:
        return 'AF_INET'
    elif type(address) is str and address.startswith('\\\\'):
        return 'AF_PIPE'
    elif type(address) is str or util.is_abstract_socket_namespace(address):
        return 'AF_UNIX'
    else:
        raise ValueError('address type of %r unrecognized' % address)

def Client(address, family=None, authkey=None):
    """Returns a connection to the address of a `Listener`"""
    family = family or address_type(address)
    _validate_family(family)
    if family == 'AF_PIPE':
        c = PipeClient(address)
    else:
        c = SocketClient(address)
    if authkey is not None and (not isinstance(authkey, bytes)):
        raise TypeError('authkey should be a byte string')
    if authkey is not None:
        answer_challenge(c, authkey)
        deliver_challenge(c, authkey)
    return c

def _get_digest_name_and_payload(message):
    """Returns a digest name and the payload for a response hash.

    If a legacy protocol is detected based on the message length
    or contents the digest name returned will be empty to indicate
    legacy mode where MD5 and no digest prefix should be sent."""
    if len(message) in _LEGACY_LENGTHS:
        return ('', message)
    if message.startswith(b'{') and (curly := message.find(b'}', 1, _MAX_DIGEST_LEN + 2)) > 0:
        digest = message[1:curly]
        if digest in _ALLOWED_DIGESTS:
            payload = message[curly + 1:]
            return (digest.decode('ascii'), payload)
    raise AuthenticationError(f'unsupported message length, missing digest prefix, or unsupported digest: message={message!r}')

def _create_response(authkey, message):
    """Create a MAC based on authkey and message

    The MAC algorithm defaults to HMAC-MD5, unless MD5 is not available or
    the message has a '{digest_name}' prefix. For legacy HMAC-MD5, the response
    is the raw MAC, otherwise the response is prefixed with '{digest_name}',
    e.g. b'{sha256}abcdefg...'

    Note: The MAC protects the entire message including the digest_name prefix."""
    import hmac
    digest_name = _get_digest_name_and_payload(message)[0]
    if not digest_name:
        try:
            return hmac.new(authkey, message, 'md5').digest()
        except ValueError:
            digest_name = 'sha256'
    response = hmac.new(authkey, message, digest_name).digest()
    return b'{%s}%s' % (digest_name.encode('ascii'), response)

def deliver_challenge(connection, authkey: bytes, digest_name='sha256'):
    if not isinstance(authkey, bytes):
        raise ValueError('Authkey must be bytes, not {0!s}'.format(type(authkey)))
    assert MESSAGE_LENGTH > _MD5ONLY_MESSAGE_LENGTH, 'protocol constraint'
    message = os.urandom(MESSAGE_LENGTH)
    message = b'{%s}%s' % (digest_name.encode('ascii'), message)
    connection.send_bytes(_CHALLENGE + message)
    response = connection.recv_bytes(256)
    try:
        _verify_challenge(authkey, message, response)
    except AuthenticationError:
        connection.send_bytes(_FAILURE)
        raise
    else:
        connection.send_bytes(_WELCOME)

def answer_challenge(connection, authkey: bytes):
    if not isinstance(authkey, bytes):
        raise ValueError('Authkey must be bytes, not {0!s}'.format(type(authkey)))
    message = connection.recv_bytes(256)
    if not message.startswith(_CHALLENGE):
        raise AuthenticationError(f'Protocol error, expected challenge: message={message!r}')
    message = message[len(_CHALLENGE):]
    if len(message) < _MD5ONLY_MESSAGE_LENGTH:
        raise AuthenticationError(f'challenge too short: {len(message)} bytes')
    digest = _create_response(authkey, message)
    connection.send_bytes(digest)
    response = connection.recv_bytes(256)
    if response != _WELCOME:
        raise AuthenticationError('digest sent was rejected')

def _xml_loads(s):
    (obj,), method = xmlrpclib.loads(s.decode('utf-8'))
    return obj

def __init__(self, handle, readable=True, writable=True):
    handle = handle.__index__()
    if handle < 0:
        raise ValueError('invalid handle')
    if not readable and (not writable):
        raise ValueError('at least one of `readable` and `writable` must be True')
    self._handle = handle
    self._readable = readable
    self._writable = writable

def __del__(self):
    if self._handle is not None:
        self._close()

def _check_closed(self):
    if self._handle is None:
        raise OSError('handle is closed')

def _check_readable(self):
    if not self._readable:
        raise OSError('connection is write-only')

def _check_writable(self):
    if not self._writable:
        raise OSError('connection is read-only')

def _bad_message_length(self):
    if self._writable:
        self._readable = False
    else:
        self.close()
    raise OSError('bad message length')

@property
def closed(self):
    """True if the connection is closed"""
    return self._handle is None

@property
def readable(self):
    """True if the connection is readable"""
    return self._readable

@property
def writable(self):
    """True if the connection is writable"""
    return self._writable

def close(self):
    """Close the connection"""
    if self._handle is not None:
        try:
            self._close()
        finally:
            self._handle = None

def send_bytes(self, buf, offset=0, size=None):
    """Send the bytes data from a bytes-like object"""
    self._check_closed()
    self._check_writable()
    m = memoryview(buf)
    if m.itemsize > 1:
        m = m.cast('B')
    n = m.nbytes
    if offset < 0:
        raise ValueError('offset is negative')
    if n < offset:
        raise ValueError('buffer length < offset')
    if size is None:
        size = n - offset
    elif size < 0:
        raise ValueError('size is negative')
    elif offset + size > n:
        raise ValueError('buffer length < offset + size')
    self._send_bytes(m[offset:offset + size])

def recv_bytes(self, maxlength=None):
    """Receive bytes data as a bytes object."""
    self._check_closed()
    self._check_readable()
    if maxlength is not None and maxlength < 0:
        raise ValueError('negative maxlength')
    buf = self._recv_bytes(maxlength)
    if buf is None:
        self._bad_message_length()
    return buf.getvalue()

def recv(self):
    """Receive a (picklable) object"""
    self._check_closed()
    self._check_readable()
    buf = self._recv_bytes()
    return _ForkingPickler.loads(buf.getbuffer())

def poll(self, timeout=0.0):
    """Whether there is any input available to be read"""
    self._check_closed()
    self._check_readable()
    return self._poll(timeout)

def _send(self, buf, write=_write):
    remaining = len(buf)
    while True:
        n = write(self._handle, buf)
        remaining -= n
        if remaining == 0:
            break
        buf = buf[n:]

def _recv(self, size, read=_read):
    buf = io.BytesIO()
    handle = self._handle
    remaining = size
    while remaining > 0:
        chunk = read(handle, remaining)
        n = len(chunk)
        if n == 0:
            if remaining == size:
                raise EOFError
            else:
                raise OSError('got end of file during message')
        buf.write(chunk)
        remaining -= n
    return buf

def _recv_bytes(self, maxsize=None):
    buf = self._recv(4)
    size, = struct.unpack('!i', buf.getvalue())
    if size == -1:
        buf = self._recv(8)
        size, = struct.unpack('!Q', buf.getvalue())
    if maxsize is not None and size > maxsize:
        return None
    return self._recv(size)

def _poll(self, timeout):
    r = wait([self], timeout)
    return bool(r)

def __init__(self, address=None, family=None, backlog=1, authkey=None):
    family = family or (address and address_type(address)) or default_family
    address = address or arbitrary_address(family)
    _validate_family(family)
    if family == 'AF_PIPE':
        self._listener = PipeListener(address, backlog)
    else:
        self._listener = SocketListener(address, family, backlog)
    if authkey is not None and (not isinstance(authkey, bytes)):
        raise TypeError('authkey should be a byte string')
    self._authkey = authkey

def accept(self):
    """Accept a connection on the bound socket or named pipe of `self`.

    Returns a `Connection` object."""
    if self._listener is None:
        raise OSError('listener is closed')
    c = self._listener.accept()
    if self._authkey is not None:
        deliver_challenge(c, self._authkey)
        answer_challenge(c, self._authkey)
    return c

def close(self):
    """Close the bound socket or named pipe of `self`."""
    listener = self._listener
    if listener is not None:
        self._listener = None
        listener.close()

@property
def address(self):
    return self._listener._address

@property
def last_accepted(self):
    return self._listener._last_accepted

def Pipe(duplex=True):
    """Returns pair of connection objects at either end of a pipe"""
    if duplex:
        s1, s2 = socket.socketpair()
        s1.setblocking(True)
        s2.setblocking(True)
        c1 = Connection(s1.detach())
        c2 = Connection(s2.detach())
    else:
        fd1, fd2 = os.pipe()
        c1 = Connection(fd1, writable=False)
        c2 = Connection(fd2, readable=False)
    return (c1, c2)

def __init__(self, address, family, backlog=1):
    self._socket = socket.socket(getattr(socket, family))
    try:
        if os.name == 'posix':
            self._socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        self._socket.setblocking(True)
        self._socket.bind(address)
        self._socket.listen(backlog)
        self._address = self._socket.getsockname()
    except OSError:
        self._socket.close()
        raise
    self._family = family
    self._last_accepted = None
    if family == 'AF_UNIX' and (not util.is_abstract_socket_namespace(address)):
        self._unlink = util.Finalize(self, os.unlink, args=(address,), exitpriority=0)
    else:
        self._unlink = None

def accept(self):
    s, self._last_accepted = self._socket.accept()
    s.setblocking(True)
    return Connection(s.detach())

def close(self):
    try:
        self._socket.close()
    finally:
        unlink = self._unlink
        if unlink is not None:
            self._unlink = None
            unlink()

def PipeClient(address):
    """Return a connection object connected to the pipe given by `address`"""
    t = _init_timeout()
    while 1:
        try:
            _winapi.WaitNamedPipe(address, 1000)
            h = _winapi.CreateFile(address, _winapi.GENERIC_READ | _winapi.GENERIC_WRITE, 0, _winapi.NULL, _winapi.OPEN_EXISTING, _winapi.FILE_FLAG_OVERLAPPED, _winapi.NULL)
        except OSError as e:
            if e.winerror not in (_winapi.ERROR_SEM_TIMEOUT, _winapi.ERROR_PIPE_BUSY) or _check_timeout(t):
                raise
        else:
            break
    else:
        raise
    _winapi.SetNamedPipeHandleState(h, _winapi.PIPE_READMODE_MESSAGE, None, None)
    return PipeConnection(h)

def send(self, obj):
    s = self._dumps(obj)
    self._conn.send_bytes(s)

def recv(self):
    s = self._conn.recv_bytes()
    return self._loads(s)

def accept(self):
    global xmlrpclib
    import xmlrpc.client as xmlrpclib
    obj = Listener.accept(self)
    return ConnectionWrapper(obj, _xml_dumps, _xml_loads)

def _exhaustive_wait(handles, timeout):
    L = list(handles)
    ready = []
    while L:
        res = _winapi.WaitForMultipleObjects(L, False, timeout)
        if res == WAIT_TIMEOUT:
            break
        elif WAIT_OBJECT_0 <= res < WAIT_OBJECT_0 + len(L):
            res -= WAIT_OBJECT_0
        elif WAIT_ABANDONED_0 <= res < WAIT_ABANDONED_0 + len(L):
            res -= WAIT_ABANDONED_0
        else:
            raise RuntimeError('Should not get here')
        ready.append(L[res])
        L = L[res + 1:]
        timeout = 0
    return ready

def wait(object_list, timeout=None):
    """Wait till an object in object_list is ready/readable.

    Returns list of those objects in object_list which are ready/readable."""
    with _WaitSelector() as selector:
        for obj in object_list:
            selector.register(obj, selectors.EVENT_READ)
        if timeout is not None:
            deadline = time.monotonic() + timeout
        while True:
            ready = selector.select(timeout)
            if ready:
                return [key.fileobj for key, events in ready]
            elif timeout is not None:
                timeout = deadline - time.monotonic()
                if timeout < 0:
                    return ready

def reduce_connection(conn):
    handle = conn.fileno()
    with socket.fromfd(handle, socket.AF_INET, socket.SOCK_STREAM) as s:
        from . import resource_sharer
        ds = resource_sharer.DupSocket(s)
        return (rebuild_connection, (ds, conn.readable, conn.writable))

def rebuild_connection(ds, readable, writable):
    sock = ds.detach()
    return Connection(sock.detach(), readable, writable)

def reduce_pipe_connection(conn):
    access = (_winapi.FILE_GENERIC_READ if conn.readable else 0) | (_winapi.FILE_GENERIC_WRITE if conn.writable else 0)
    dh = reduction.DupHandle(conn.fileno(), access)
    return (rebuild_pipe_connection, (dh, conn.readable, conn.writable))

def reduce_connection(conn):
    df = reduction.DupFd(conn.fileno())
    return (rebuild_connection, (df, conn.readable, conn.writable))

def rebuild_connection(df, readable, writable):
    fd = df.detach()
    return Connection(fd, readable, writable)

def _close(self, _CloseHandle=_winapi.CloseHandle):
    ov = self._send_ov
    if ov is not None:
        ov.cancel()
    _CloseHandle(self._handle)

def _send_bytes(self, buf):
    if self._send_ov is not None:
        raise ValueError('concurrent send_bytes() calls are not supported')
    ov, err = _winapi.WriteFile(self._handle, buf, overlapped=True)
    self._send_ov = ov
    try:
        if err == _winapi.ERROR_IO_PENDING:
            waitres = _winapi.WaitForMultipleObjects([ov.event], False, INFINITE)
            assert waitres == WAIT_OBJECT_0
    except:
        ov.cancel()
        raise
    finally:
        self._send_ov = None
        nwritten, err = ov.GetOverlappedResult(True)
    if err == _winapi.ERROR_OPERATION_ABORTED:
        raise OSError(errno.EPIPE, 'handle is closed')
    assert err == 0
    assert nwritten == len(buf)

def _recv_bytes(self, maxsize=None):
    if self._got_empty_message:
        self._got_empty_message = False
        return io.BytesIO()
    else:
        bsize = 128 if maxsize is None else min(maxsize, 128)
        try:
            ov, err = _winapi.ReadFile(self._handle, bsize, overlapped=True)
            try:
                if err == _winapi.ERROR_IO_PENDING:
                    waitres = _winapi.WaitForMultipleObjects([ov.event], False, INFINITE)
                    assert waitres == WAIT_OBJECT_0
            except:
                ov.cancel()
                raise
            finally:
                nread, err = ov.GetOverlappedResult(True)
                if err == 0:
                    f = io.BytesIO()
                    f.write(ov.getbuffer())
                    return f
                elif err == _winapi.ERROR_MORE_DATA:
                    return self._get_more_data(ov, maxsize)
        except OSError as e:
            if e.winerror == _winapi.ERROR_BROKEN_PIPE:
                raise EOFError
            else:
                raise
    raise RuntimeError("shouldn't get here; expected KeyboardInterrupt")

def _poll(self, timeout):
    if self._got_empty_message or _winapi.PeekNamedPipe(self._handle)[0] != 0:
        return True
    return bool(wait([self], timeout))

def _new_handle(self, first=False):
    flags = _winapi.PIPE_ACCESS_DUPLEX | _winapi.FILE_FLAG_OVERLAPPED
    if first:
        flags |= _winapi.FILE_FLAG_FIRST_PIPE_INSTANCE
    return _winapi.CreateNamedPipe(self._address, flags, _winapi.PIPE_TYPE_MESSAGE | _winapi.PIPE_READMODE_MESSAGE | _winapi.PIPE_WAIT, _winapi.PIPE_UNLIMITED_INSTANCES, BUFSIZE, BUFSIZE, _winapi.NMPWAIT_WAIT_FOREVER, _winapi.NULL)

def accept(self):
    self._handle_queue.append(self._new_handle())
    handle = self._handle_queue.pop(0)
    try:
        ov = _winapi.ConnectNamedPipe(handle, overlapped=True)
    except OSError as e:
        if e.winerror != _winapi.ERROR_NO_DATA:
            raise
    else:
        try:
            res = _winapi.WaitForMultipleObjects([ov.event], False, INFINITE)
        except:
            ov.cancel()
            _winapi.CloseHandle(handle)
            raise
        finally:
            _, err = ov.GetOverlappedResult(True)
            assert err == 0
    return PipeConnection(handle)

@staticmethod
def _finalize_pipe_listener(queue, address):
    util.sub_debug('closing listener with address=%r', address)
    for handle in queue:
        _winapi.CloseHandle(handle)

def assert_spawning(obj):
    if get_spawning_popen() is None:
        raise RuntimeError('%s objects should only be shared between processes through inheritance' % type(obj).__name__)

