def reduce_arena(a):
    if a.fd == -1:
        raise ValueError('Arena is unpicklable because forking was enabled when it was created')
    return (rebuild_arena, (a.size, reduction.DupFd(a.fd)))

def __init__(self, size=mmap.PAGESIZE):
    self._lastpid = os.getpid()
    self._lock = threading.Lock()
    self._size = size
    self._lengths = []
    self._len_to_seq = {}
    self._start_to_block = {}
    self._stop_to_block = {}
    self._allocated_blocks = defaultdict(set)
    self._arenas = []
    self._pending_free_blocks = []
    self._n_mallocs = 0
    self._n_frees = 0

@staticmethod
def _roundup(n, alignment):
    mask = alignment - 1
    return n + mask & ~mask

def _new_arena(self, size):
    length = self._roundup(max(self._size, size), mmap.PAGESIZE)
    if self._size < self._DOUBLE_ARENA_SIZE_UNTIL:
        self._size *= 2
    util.info('allocating a new mmap of length %d', length)
    arena = Arena(length)
    self._arenas.append(arena)
    return (arena, 0, length)

def _malloc(self, size):
    i = bisect.bisect_left(self._lengths, size)
    if i == len(self._lengths):
        return self._new_arena(size)
    else:
        length = self._lengths[i]
        seq = self._len_to_seq[length]
        block = seq.pop()
        if not seq:
            del self._len_to_seq[length], self._lengths[i]
    arena, start, stop = block
    del self._start_to_block[arena, start]
    del self._stop_to_block[arena, stop]
    return block

def _add_free_block(self, block):
    arena, start, stop = block
    try:
        prev_block = self._stop_to_block[arena, start]
    except KeyError:
        pass
    else:
        start, _ = self._absorb(prev_block)
    try:
        next_block = self._start_to_block[arena, stop]
    except KeyError:
        pass
    else:
        _, stop = self._absorb(next_block)
    block = (arena, start, stop)
    length = stop - start
    try:
        self._len_to_seq[length].append(block)
    except KeyError:
        self._len_to_seq[length] = [block]
        bisect.insort(self._lengths, length)
    self._start_to_block[arena, start] = block
    self._stop_to_block[arena, stop] = block

def _remove_allocated_block(self, block):
    arena, start, stop = block
    blocks = self._allocated_blocks[arena]
    blocks.remove((start, stop))
    if not blocks:
        self._discard_arena(arena)

def _free_pending_blocks(self):
    while True:
        try:
            block = self._pending_free_blocks.pop()
        except IndexError:
            break
        self._add_free_block(block)
        self._remove_allocated_block(block)

def free(self, block):
    if os.getpid() != self._lastpid:
        raise ValueError('My pid ({0:n}) is not last pid {1:n}'.format(os.getpid(), self._lastpid))
    if not self._lock.acquire(False):
        self._pending_free_blocks.append(block)
    else:
        try:
            self._n_frees += 1
            self._free_pending_blocks()
            self._add_free_block(block)
            self._remove_allocated_block(block)
        finally:
            self._lock.release()

def malloc(self, size):
    if size < 0:
        raise ValueError('Size {0:n} out of range'.format(size))
    if sys.maxsize <= size:
        raise OverflowError('Size {0:n} too large'.format(size))
    if os.getpid() != self._lastpid:
        self.__init__()
    with self._lock:
        self._n_mallocs += 1
        self._free_pending_blocks()
        size = self._roundup(max(size, 1), self._alignment)
        arena, start, stop = self._malloc(size)
        real_stop = start + size
        if real_stop < stop:
            self._add_free_block((arena, real_stop, stop))
        self._allocated_blocks[arena].add((start, real_stop))
        return (arena, start, real_stop)

def __init__(self, size):
    if size < 0:
        raise ValueError('Size {0:n} out of range'.format(size))
    if sys.maxsize <= size:
        raise OverflowError('Size {0:n} too large'.format(size))
    block = BufferWrapper._heap.malloc(size)
    self._state = (block, size)
    util.Finalize(self, BufferWrapper._heap.free, args=(block,))

def create_memoryview(self):
    (arena, start, stop), size = self._state
    return memoryview(arena.buffer)[start:start + size]

def __init__(self, size):
    self.size = size
    for i in range(100):
        name = 'pym-%d-%s' % (os.getpid(), next(self._rand))
        buf = mmap.mmap(-1, size, tagname=name)
        if _winapi.GetLastError() == 0:
            break
        buf.close()
    else:
        raise FileExistsError('Cannot find name for new mmap')
    self.name = name
    self.buffer = buf
    self._state = (self.size, self.name)

def __getstate__(self):
    assert_spawning(self)
    return self._state

def __setstate__(self, state):
    self.size, self.name = self._state = state
    self.buffer = mmap.mmap(-1, self.size, tagname=self.name)

def _choose_dir(self, size):
    for d in self._dir_candidates:
        st = os.statvfs(d)
        if st.f_bavail * st.f_frsize >= size:
            return d
    return util.get_temp_dir()

def convert_to_error(kind, result):
    if kind == '#ERROR':
        return result
    elif kind in ('#TRACEBACK', '#UNSERIALIZABLE'):
        if not isinstance(result, str):
            raise TypeError("Result {0!r} (kind '{1}') type is {2}, not str".format(result, kind, type(result)))
        if kind == '#UNSERIALIZABLE':
            return RemoteError('Unserializable message: %s\n' % result)
        else:
            return RemoteError(result)
    else:
        return ValueError('Unrecognized message type {!r}'.format(kind))

def all_methods(obj):
    """Return a list of names of methods of `obj`"""
    temp = []
    for name in dir(obj):
        func = getattr(obj, name)
        if callable(func):
            temp.append(name)
    return temp

def RebuildProxy(func, token, serializer, kwds):
    """Function used for unpickling proxy objects."""
    server = getattr(process.current_process(), '_manager_server', None)
    if server and server.address == token.address:
        util.debug('Rebuild a proxy owned by manager, token=%r', token)
        kwds['manager_owned'] = True
        if token.id not in server.id_to_local_proxy_obj:
            server.id_to_local_proxy_obj[token.id] = server.id_to_obj[token.id]
    incref = kwds.pop('incref', True) and (not getattr(process.current_process(), '_inheriting', False))
    return func(token, serializer, incref=incref, **kwds)

def MakeProxyType(name, exposed, _cache={}):
    """Return a proxy type whose methods are given by `exposed`"""
    exposed = tuple(exposed)
    try:
        return _cache[name, exposed]
    except KeyError:
        pass
    dic = {}
    for meth in exposed:
        exec('def %s(self, /, *args, **kwds):\n        return self._callmethod(%r, args, kwds)' % (meth, meth), dic)
    ProxyType = type(name, (BaseProxy,), dic)
    ProxyType._exposed_ = exposed
    _cache[name, exposed] = ProxyType
    return ProxyType

def __init__(self, registry, address, authkey, serializer):
    if not isinstance(authkey, bytes):
        raise TypeError('Authkey {0!r} is type {1!s}, not bytes'.format(authkey, type(authkey)))
    self.registry = registry
    self.authkey = process.AuthenticationString(authkey)
    Listener, Client = listener_client[serializer]
    self.listener = Listener(address=address, backlog=128)
    self.address = self.listener.address
    self.id_to_obj = {'0': (None, ())}
    self.id_to_refcount = {}
    self.id_to_local_proxy_obj = {}
    self.mutex = threading.Lock()

def serve_forever(self):
    """Run the server forever"""
    self.stop_event = threading.Event()
    process.current_process()._manager_server = self
    try:
        accepter = threading.Thread(target=self.accepter)
        accepter.daemon = True
        accepter.start()
        try:
            while not self.stop_event.is_set():
                self.stop_event.wait(1)
        except (KeyboardInterrupt, SystemExit):
            pass
    finally:
        if sys.stdout != sys.__stdout__:
            util.debug('resetting stdout, stderr')
            sys.stdout = sys.__stdout__
            sys.stderr = sys.__stderr__
        sys.exit(0)

def accepter(self):
    while True:
        try:
            c = self.listener.accept()
        except OSError:
            continue
        t = threading.Thread(target=self.handle_request, args=(c,))
        t.daemon = True
        t.start()

def _handle_request(self, c):
    request = None
    try:
        connection.deliver_challenge(c, self.authkey)
        connection.answer_challenge(c, self.authkey)
        request = c.recv()
        ignore, funcname, args, kwds = request
        assert funcname in self.public, '%r unrecognized' % funcname
        func = getattr(self, funcname)
    except Exception:
        msg = ('#TRACEBACK', format_exc())
    else:
        try:
            result = func(c, *args, **kwds)
        except Exception:
            msg = ('#TRACEBACK', format_exc())
        else:
            msg = ('#RETURN', result)
    try:
        c.send(msg)
    except Exception as e:
        try:
            c.send(('#TRACEBACK', format_exc()))
        except Exception:
            pass
        util.info('Failure to send message: %r', msg)
        util.info(' ... request was %r', request)
        util.info(' ... exception was %r', e)

def handle_request(self, conn):
    """Handle a new connection"""
    try:
        self._handle_request(conn)
    except SystemExit:
        pass
    finally:
        conn.close()

def debug_info(self, c):
    """Return some info --- useful to spot problems with refcounting"""
    with self.mutex:
        result = []
        keys = list(self.id_to_refcount.keys())
        keys.sort()
        for ident in keys:
            if ident != '0':
                result.append('  %s:       refcount=%s\n    %s' % (ident, self.id_to_refcount[ident], str(self.id_to_obj[ident][0])[:75]))
        return '\n'.join(result)

def number_of_objects(self, c):
    """Number of shared objects"""
    return len(self.id_to_refcount)

def shutdown(self, c):
    """Shutdown this process"""
    try:
        util.debug('manager received shutdown message')
        c.send(('#RETURN', None))
    except:
        import traceback
        traceback.print_exc()
    finally:
        self.stop_event.set()

def create(self, c, typeid, /, *args, **kwds):
    """Create a new shared object and return its id"""
    with self.mutex:
        callable, exposed, method_to_typeid, proxytype = self.registry[typeid]
        if callable is None:
            if kwds or len(args) != 1:
                raise ValueError('Without callable, must have one non-keyword argument')
            obj = args[0]
        else:
            obj = callable(*args, **kwds)
        if exposed is None:
            exposed = public_methods(obj)
        if method_to_typeid is not None:
            if not isinstance(method_to_typeid, dict):
                raise TypeError('Method_to_typeid {0!r}: type {1!s}, not dict'.format(method_to_typeid, type(method_to_typeid)))
            exposed = list(exposed) + list(method_to_typeid)
        ident = '%x' % id(obj)
        util.debug('%r callable returned object with id %r', typeid, ident)
        self.id_to_obj[ident] = (obj, set(exposed), method_to_typeid)
        if ident not in self.id_to_refcount:
            self.id_to_refcount[ident] = 0
    self.incref(c, ident)
    return (ident, tuple(exposed))

def get_methods(self, c, token):
    """Return the methods of the shared object indicated by token"""
    return tuple(self.id_to_obj[token.id][1])

def incref(self, c, ident):
    with self.mutex:
        try:
            self.id_to_refcount[ident] += 1
        except KeyError as ke:
            if ident in self.id_to_local_proxy_obj:
                self.id_to_refcount[ident] = 1
                self.id_to_obj[ident] = self.id_to_local_proxy_obj[ident]
                util.debug('Server re-enabled tracking & INCREF %r', ident)
            else:
                raise ke

def decref(self, c, ident):
    if ident not in self.id_to_refcount and ident in self.id_to_local_proxy_obj:
        util.debug('Server DECREF skipping %r', ident)
        return
    with self.mutex:
        if self.id_to_refcount[ident] <= 0:
            raise AssertionError('Id {0!s} ({1!r}) has refcount {2:n}, not 1+'.format(ident, self.id_to_obj[ident], self.id_to_refcount[ident]))
        self.id_to_refcount[ident] -= 1
        if self.id_to_refcount[ident] == 0:
            del self.id_to_refcount[ident]
    if ident not in self.id_to_refcount:
        self.id_to_obj[ident] = (None, (), None)
        util.debug('disposing of obj with id %r', ident)
        with self.mutex:
            del self.id_to_obj[ident]

def get_server(self):
    """Return server object with serve_forever() method and address attribute"""
    if self._state.value != State.INITIAL:
        if self._state.value == State.STARTED:
            raise ProcessError('Already started server')
        elif self._state.value == State.SHUTDOWN:
            raise ProcessError('Manager has shut down')
        else:
            raise ProcessError('Unknown state {!r}'.format(self._state.value))
    return Server(self._registry, self._address, self._authkey, self._serializer)

def _create(self, typeid, /, *args, **kwds):
    """Create a new shared object; return the token and exposed tuple"""
    assert self._state.value == State.STARTED, 'server not yet started'
    conn = self._Client(self._address, authkey=self._authkey)
    try:
        id, exposed = dispatch(conn, None, 'create', (typeid,) + args, kwds)
    finally:
        conn.close()
    return (Token(typeid, self._address, id), exposed)

def join(self, timeout=None):
    """Join the manager process (if it has been spawned)"""
    if self._process is not None:
        self._process.join(timeout)
        if not self._process.is_alive():
            self._process = None

def _debug_info(self):
    """Return some info about the servers shared objects and connections"""
    conn = self._Client(self._address, authkey=self._authkey)
    try:
        return dispatch(conn, None, 'debug_info')
    finally:
        conn.close()

def _number_of_objects(self):
    """Return the number of shared objects"""
    conn = self._Client(self._address, authkey=self._authkey)
    try:
        return dispatch(conn, None, 'number_of_objects')
    finally:
        conn.close()

def __enter__(self):
    if self._state.value == State.INITIAL:
        self.start()
    if self._state.value != State.STARTED:
        if self._state.value == State.INITIAL:
            raise ProcessError('Unable to start server')
        elif self._state.value == State.SHUTDOWN:
            raise ProcessError('Manager has shut down')
        else:
            raise ProcessError('Unknown state {!r}'.format(self._state.value))
    return self

@staticmethod
def _finalize_manager(process, address, authkey, state, _Client, shutdown_timeout):
    """Shutdown the manager process; will be registered as a finalizer"""
    if process.is_alive():
        util.info('sending shutdown message to manager')
        try:
            conn = _Client(address, authkey=authkey)
            try:
                dispatch(conn, None, 'shutdown')
            finally:
                conn.close()
        except Exception:
            pass
        process.join(timeout=shutdown_timeout)
        if process.is_alive():
            util.info('manager still alive')
            if hasattr(process, 'terminate'):
                util.info('trying to `terminate()` manager process')
                process.terminate()
                process.join(timeout=shutdown_timeout)
                if process.is_alive():
                    util.info('manager still alive after terminate')
                    process.kill()
                    process.join()
    state.value = State.SHUTDOWN
    try:
        del BaseProxy._address_to_local[address]
    except KeyError:
        pass

@property
def address(self):
    return self._address

def _getvalue(self):
    """Get a copy of the value of the referent"""
    return self._callmethod('#GETVALUE')

@staticmethod
def _decref(token, serial, authkey, state, tls, idset, _Client):
    idset.discard(serial)
    if state is None or state.value == State.STARTED:
        try:
            util.debug('DECREF %r', token.id)
            conn = _Client(token.address, authkey=authkey)
            dispatch(conn, None, 'decref', (token.id,))
        except Exception as e:
            util.debug('... decref failed %s', e)
    else:
        util.debug('DECREF %r -- manager already shutdown', token.id)
    if not idset and hasattr(tls, 'connection'):
        util.debug('thread %r has no more proxies so closing conn', threading.current_thread().name)
        tls.connection.close()
        del tls.connection

def _after_fork(self):
    self._manager = None
    try:
