    if getattr(self, '_isauto', False):
        kwds['exposed'] = self._exposed_
        return (RebuildProxy, (AutoProxy, self._token, self._serializer, kwds))
    else:
        return (RebuildProxy, (type(self), self._token, self._serializer, kwds))

