    BaseManager.__init__(self, *args, **kwargs)
    util.debug(f'{self.__class__.__name__} created by pid {getpid()}')

def get_server(self):
    """Better than monkeypatching for now; merge into Server ultimately"""
    if self._state.value != State.INITIAL:
        if self._state.value == State.STARTED:
            raise ProcessError('Already started SharedMemoryServer')
        elif self._state.value == State.SHUTDOWN:
            raise ProcessError('SharedMemoryManager has shut down')
        else:
            raise ProcessError('Unknown state {!r}'.format(self._state.value))
    return self._Server(self._registry, self._address, self._authkey, self._serializer)

def rebuild_exc(exc, tb):
    exc.__cause__ = RemoteTraceback(tb)
    return exc

def worker(inqueue, outqueue, initializer=None, initargs=(), maxtasks=None, wrap_exception=False):
    if maxtasks is not None and (not (isinstance(maxtasks, int) and maxtasks >= 1)):
        raise AssertionError('Maxtasks {!r} is not valid'.format(maxtasks))
    put = outqueue.put
    get = inqueue.get
    if hasattr(inqueue, '_writer'):
        inqueue._writer.close()
        outqueue._reader.close()
    if initializer is not None:
        initializer(*initargs)
    completed = 0
    while maxtasks is None or (maxtasks and completed < maxtasks):
        try:
            task = get()
        except (EOFError, OSError):
            util.debug('worker got EOFError or OSError -- exiting')
            break
        if task is None:
            util.debug('worker got sentinel -- exiting')
            break
        job, i, func, args, kwds = task
        try:
            result = (True, func(*args, **kwds))
        except Exception as e:
            if wrap_exception and func is not _helper_reraises_exception:
                e = ExceptionWithTraceback(e, e.__traceback__)
            result = (False, e)
        try:
            put((job, i, result))
        except Exception as e:
            wrapped = MaybeEncodingError(e, result[1])
            util.debug('Possible encoding error while sending result: %s' % wrapped)
            put((job, i, (False, wrapped)))
        task = job = result = func = args = kwds = None
        completed += 1
    util.debug('worker exiting after %d tasks' % completed)

def _helper_reraises_exception(ex):
    """Pickle-able helper function for use by _guarded_task_generation."""
    raise ex

def __init__(self, /, *args, notifier=None, **kwds):
    self.notifier = notifier
    super().__init__(*args, **kwds)

def __delitem__(self, item):
    super().__delitem__(item)
    if not self:
        self.notifier.put(None)

@staticmethod
def Process(ctx, *args, **kwds):
    return ctx.Process(*args, **kwds)

def __del__(self, _warn=warnings.warn, RUN=RUN):
    if self._state == RUN:
        _warn(f'unclosed running multiprocessing pool {self!r}', ResourceWarning, source=self)
        if getattr(self, '_change_notifier', None) is not None:
            self._change_notifier.put(None)

def __repr__(self):
    cls = self.__class__
    return f'<{cls.__module__}.{cls.__qualname__} state={self._state} pool_size={len(self._pool)}>'

@staticmethod
def _get_worker_sentinels(workers):
    return [worker.sentinel for worker in workers if hasattr(worker, 'sentinel')]

@staticmethod
def _join_exited_workers(pool):
    """Cleanup after any worker processes which have exited due to reaching
    their specified lifetime.  Returns True if any workers were cleaned up."""
    cleaned = False
    for i in reversed(range(len(pool))):
        worker = pool[i]
        if worker.exitcode is not None:
            util.debug('cleaning up worker %d' % i)
            worker.join()
            cleaned = True
            del pool[i]
    return cleaned

@staticmethod
def _maintain_pool(ctx, Process, processes, pool, inqueue, outqueue, initializer, initargs, maxtasksperchild, wrap_exception):
    """Clean up any exited workers and start replacements for them.
    """
    if Pool._join_exited_workers(pool):
        Pool._repopulate_pool_static(ctx, Process, processes, pool, inqueue, outqueue, initializer, initargs, maxtasksperchild, wrap_exception)

def _check_running(self):
    if self._state != RUN:
        raise ValueError('Pool not running')

def apply(self, func, args=(), kwds={}):
    """Equivalent of `func(*args, **kwds)`.
    Pool must be running."""
    return self.apply_async(func, args, kwds).get()

def map(self, func, iterable, chunksize=None):
    """Apply `func` to each element in `iterable`, collecting the results
    in a list that is returned."""
    return self._map_async(func, iterable, mapstar, chunksize).get()

def starmap(self, func, iterable, chunksize=None):
    """Like `map()` method but the elements of the `iterable` are expected to
    be iterables as well and will be unpacked as arguments. Hence
    `func` and (a, b) becomes func(a, b)."""
    return self._map_async(func, iterable, starmapstar, chunksize).get()

def starmap_async(self, func, iterable, chunksize=None, callback=None, error_callback=None):
    """Asynchronous version of `starmap()` method."""
    return self._map_async(func, iterable, starmapstar, chunksize, callback, error_callback)

def _guarded_task_generation(self, result_job, func, iterable):
    """Provides a generator of tasks for imap and imap_unordered with
    appropriate handling for iterables which throw exceptions during
    iteration."""
    try:
        i = -1
        for i, x in enumerate(iterable):
            yield (result_job, i, func, (x,), {})
    except Exception as e:
        yield (result_job, i + 1, _helper_reraises_exception, (e,), {})

def imap(self, func, iterable, chunksize=1):
    """Equivalent of `map()` -- can be MUCH slower than `Pool.map()`."""
    self._check_running()
    if chunksize == 1:
        result = IMapIterator(self)
        self._taskqueue.put((self._guarded_task_generation(result._job, func, iterable), result._set_length))
        return result
    else:
        if chunksize < 1:
            raise ValueError('Chunksize must be 1+, not {0:n}'.format(chunksize))
        task_batches = Pool._get_tasks(func, iterable, chunksize)
        result = IMapIterator(self)
        self._taskqueue.put((self._guarded_task_generation(result._job, mapstar, task_batches), result._set_length))
        return (item for chunk in result for item in chunk)

def imap_unordered(self, func, iterable, chunksize=1):
    """Like `imap()` method but ordering of results is arbitrary."""
    self._check_running()
    if chunksize == 1:
        result = IMapUnorderedIterator(self)
        self._taskqueue.put((self._guarded_task_generation(result._job, func, iterable), result._set_length))
        return result
    else:
        if chunksize < 1:
            raise ValueError('Chunksize must be 1+, not {0!r}'.format(chunksize))
        task_batches = Pool._get_tasks(func, iterable, chunksize)
        result = IMapUnorderedIterator(self)
        self._taskqueue.put((self._guarded_task_generation(result._job, mapstar, task_batches), result._set_length))
        return (item for chunk in result for item in chunk)

@staticmethod
def _wait_for_updates(sentinels, change_notifier, timeout=None):
    wait(sentinels, timeout=timeout)
    while not change_notifier.empty():
        change_notifier.get()

@classmethod
def _handle_workers(cls, cache, taskqueue, ctx, Process, processes, pool, inqueue, outqueue, initializer, initargs, maxtasksperchild, wrap_exception, sentinels, change_notifier):
    thread = threading.current_thread()
    while thread._state == RUN or (cache and thread._state != TERMINATE):
        cls._maintain_pool(ctx, Process, processes, pool, inqueue, outqueue, initializer, initargs, maxtasksperchild, wrap_exception)
        current_sentinels = [*cls._get_worker_sentinels(pool), *sentinels]
        cls._wait_for_updates(current_sentinels, change_notifier)
    taskqueue.put(None)
    util.debug('worker handler exiting')

@staticmethod
def _handle_tasks(taskqueue, put, outqueue, pool, cache):
    thread = threading.current_thread()
    for taskseq, set_length in iter(taskqueue.get, None):
        task = None
        try:
            for task in taskseq:
                if thread._state != RUN:
                    util.debug('task handler found thread._state != RUN')
                    break
                try:
                    put(task)
                except Exception as e:
                    job, idx = task[:2]
                    try:
                        cache[job]._set(idx, (False, e))
                    except KeyError:
                        pass
            else:
                if set_length:
                    util.debug('doing set_length()')
                    idx = task[1] if task else -1
                    set_length(idx + 1)
                continue
            break
        finally:
            task = taskseq = job = None
    else:
        util.debug('task handler got sentinel')
    try:
        util.debug('task handler sending sentinel to result handler')
        outqueue.put(None)
        util.debug('task handler sending sentinel to workers')
        for p in pool:
            put(None)
    except OSError:
        util.debug('task handler got OSError when sending sentinels')
    util.debug('task handler exiting')

@staticmethod
def _get_tasks(func, it, size):
    it = iter(it)
    while 1:
        x = tuple(itertools.islice(it, size))
        if not x:
            return
        yield (func, x)

def close(self):
    util.debug('closing pool')
    if self._state == RUN:
        self._state = CLOSE
        self._worker_handler._state = CLOSE
        self._change_notifier.put(None)

def join(self):
    util.debug('joining pool')
    if self._state == RUN:
        raise ValueError('Pool is still running')
    elif self._state not in (CLOSE, TERMINATE):
        raise ValueError('In unknown state')
    self._worker_handler.join()
    self._task_handler.join()
    self._result_handler.join()
    for p in self._pool:
        p.join()

@staticmethod
def _help_stuff_finish(inqueue, task_handler, size):
    util.debug('removing tasks from inqueue until task handler finished')
    inqueue._rlock.acquire()
    while task_handler.is_alive() and inqueue._reader.poll():
        inqueue._reader.recv()
        time.sleep(0)

@classmethod
def _terminate_pool(cls, taskqueue, inqueue, outqueue, pool, change_notifier, worker_handler, task_handler, result_handler, cache):
    util.debug('finalizing pool')
    worker_handler._state = TERMINATE
    change_notifier.put(None)
    task_handler._state = TERMINATE
    util.debug('helping task handler/workers to finish')
    cls._help_stuff_finish(inqueue, task_handler, len(pool))
    if not result_handler.is_alive() and len(cache) != 0:
        raise AssertionError('Cannot have cache with result_handler not alive')
    result_handler._state = TERMINATE
    change_notifier.put(None)
    outqueue.put(None)
    util.debug('joining worker handler')
    if threading.current_thread() is not worker_handler:
        worker_handler.join()
    if pool and hasattr(pool[0], 'terminate'):
        util.debug('terminating workers')
        for p in pool:
            if p.exitcode is None:
                p.terminate()
    util.debug('joining task handler')
    if threading.current_thread() is not task_handler:
        task_handler.join()
    util.debug('joining result handler')
    if threading.current_thread() is not result_handler:
        result_handler.join()
    if pool and hasattr(pool[0], 'terminate'):
        util.debug('joining pool workers')
        for p in pool:
            if p.is_alive():
                util.debug('cleaning up worker %d' % p.pid)
                p.join()

def __enter__(self):
    self._check_running()
    return self

def successful(self):
    if not self.ready():
        raise ValueError('{0!r} not ready'.format(self))
    return self._success

def get(self, timeout=None):
    self.wait(timeout)
    if not self.ready():
        raise TimeoutError
    if self._success:
        return self._value
    else:
        raise self._value

def _set(self, i, obj):
    self._success, self._value = obj
    if self._callback and self._success:
        self._callback(self._value)
    if self._error_callback and (not self._success):
        self._error_callback(self._value)
    self._event.set()
    del self._cache[self._job]
    self._pool = None

def _set(self, i, success_result):
    self._number_left -= 1
    success, result = success_result
    if success and self._success:
        self._value[i * self._chunksize:(i + 1) * self._chunksize] = result
        if self._number_left == 0:
            if self._callback:
                self._callback(self._value)
            del self._cache[self._job]
            self._event.set()
            self._pool = None
    else:
        if not success and self._success:
            self._success = False
            self._value = result
        if self._number_left == 0:
            if self._error_callback:
                self._error_callback(self._value)
            del self._cache[self._job]
            self._event.set()
            self._pool = None

def next(self, timeout=None):
    with self._cond:
        try:
            item = self._items.popleft()
        except IndexError:
            if self._index == self._length:
                self._pool = None
                raise StopIteration from None
            self._cond.wait(timeout)
            try:
                item = self._items.popleft()
            except IndexError:
                if self._index == self._length:
                    self._pool = None
                    raise StopIteration from None
                raise TimeoutError from None
    success, value = item
    if success:
        return value
    raise value

def _set(self, i, obj):
    with self._cond:
        if self._index == i:
            self._items.append(obj)
            self._index += 1
            while self._index in self._unsorted:
                obj = self._unsorted.pop(self._index)
                self._items.append(obj)
                self._index += 1
            self._cond.notify()
        else:
            self._unsorted[i] = obj
        if self._index == self._length:
            del self._cache[self._job]
            self._pool = None

@staticmethod
def Process(ctx, *args, **kwds):
    from .dummy import Process
    return Process(*args, **kwds)

@staticmethod
def _get_worker_sentinels(workers):
    return []

def poll(self, flag=os.WNOHANG):
    if self.returncode is None:
        try:
            pid, sts = os.waitpid(self.pid, flag)
        except OSError:
            return None
        if pid == self.pid:
            self.returncode = os.waitstatus_to_exitcode(sts)
    return self.returncode

def wait(self, timeout=None):
    if self.returncode is None:
        if timeout is not None:
            from multiprocessing.connection import wait
            if not wait([self.sentinel], timeout):
                return None
        return self.poll(os.WNOHANG if timeout == 0.0 else 0)
    return self.returncode

def _send_signal(self, sig):
    if self.returncode is None:
        try:
            os.kill(self.pid, sig)
        except ProcessLookupError:
            pass
        except OSError:
            if self.wait(timeout=0.1) is None:
                raise

def close(self):
    if self.finalizer is not None:
        self.finalizer()

def __init__(self, process_obj):
    self._fds = []
    super().__init__(process_obj)

def duplicate_for_child(self, fd):
    self._fds.append(fd)
    return len(self._fds) - 1

def poll(self, flag=os.WNOHANG):
    if self.returncode is None:
        from multiprocessing.connection import wait
        timeout = 0 if flag == os.WNOHANG else None
        if not wait([self.sentinel], timeout):
            return None
        try:
            self.returncode = forkserver.read_signed(self.sentinel)
        except (OSError, EOFError):
            self.returncode = 255
    return self.returncode

def duplicate_for_child(self, fd):
    self._fds.append(fd)
    return fd

def _close_handles(*handles):
    for handle in handles:
        _winapi.CloseHandle(handle)

def duplicate_for_child(self, handle):
    assert self is get_spawning_popen()
    return reduction.duplicate(handle, self.sentinel)

def terminate(self):
    if self.returncode is not None:
        return
    try:
        _winapi.TerminateProcess(int(self._handle), TERMINATE)
    except PermissionError:
        code = _winapi.GetExitCodeProcess(int(self._handle))
        if code == _winapi.STILL_ACTIVE:
            raise

def current_process():
    """Return process object representing the current process"""
    return _current_process

def active_children():
    """Return list of process objects corresponding to live child processes"""
    _cleanup()
    return list(_children)

def parent_process():
    """Return process object representing the parent process"""
    return _parent_process

def _cleanup():
    for p in list(_children):
        if (child_popen := p._popen) and child_popen.poll() is not None:
            _children.discard(p)

def _check_closed(self):
    if self._closed:
        raise ValueError('process object is closed')

def run(self):
    """Method to be run in sub-process; can be overridden in sub-class"""
    if self._target:
        self._target(*self._args, **self._kwargs)

def is_alive(self):
    """Return whether process is alive"""
    self._check_closed()
    if self is _current_process:
        return True
    assert self._parent_pid == os.getpid(), 'can only test a child process'
    if self._popen is None:
        return False
    returncode = self._popen.poll()
    if returncode is None:
        return True
    else:
        _children.discard(self)
        return False

@name.setter
def name(self, name):
    assert isinstance(name, str), 'name must be a string'
    self._name = name

@property
def daemon(self):
    """Return whether process is a daemon"""
    return self._config.get('daemon', False)

@daemon.setter
def daemon(self, daemonic):
    """Set whether process is a daemon"""
    assert self._popen is None, 'process has already started'
    self._config['daemon'] = daemonic

@property
def authkey(self):
    return self._config['authkey']

@authkey.setter
def authkey(self, authkey):
    """Set authorization key of process"""
    self._config['authkey'] = AuthenticationString(authkey)

@property
def exitcode(self):
    """Return exit code of process or `None` if it has yet to stop"""
    self._check_closed()
    if self._popen is None:
        return self._popen
    return self._popen.poll()

@property
def sentinel(self):
    """Return a file descriptor (Unix) or handle (Windows) suitable for
    waiting for process termination."""
    self._check_closed()
    try:
        return self._sentinel
    except AttributeError:
        raise ValueError('process not started') from None

def __repr__(self):
    exitcode = None
    if self is _current_process:
        status = 'started'
    elif self._closed:
        status = 'closed'
    elif self._parent_pid != os.getpid():
        status = 'unknown'
    elif self._popen is None:
        status = 'initial'
    else:
        exitcode = self._popen.poll()
        if exitcode is not None:
            status = 'stopped'
        else:
            status = 'started'
    info = [type(self).__name__, 'name=%r' % self._name]
    if self._popen is not None:
        info.append('pid=%s' % self._popen.pid)
    info.append('parent=%s' % self._parent_pid)
    info.append(status)
    if exitcode is not None:
        exitcode = _exitcode_to_name.get(exitcode, exitcode)
        info.append('exitcode=%s' % exitcode)
    if self.daemon:
        info.append('daemon')
    return '<%s>' % ' '.join(info)

@staticmethod
def _after_fork():
    from . import util
    util._finalizer_registry.clear()
    util._run_after_forkers()

def __reduce__(self):
    from .context import get_spawning_popen
    if get_spawning_popen() is None:
        raise TypeError('Pickling an AuthenticationString object is disallowed for security reasons')
    return (AuthenticationString, (bytes(self),))

def is_alive(self):
    from multiprocessing.connection import wait
    return not wait([self._sentinel], timeout=0)

@property
def ident(self):
    return self._pid

def __init__(self, maxsize=0, *, ctx):
    if maxsize <= 0:
        from .synchronize import SEM_VALUE_MAX as maxsize
    self._maxsize = maxsize
    self._reader, self._writer = connection.Pipe(duplex=False)
    self._rlock = ctx.Lock()
    self._opid = os.getpid()
    if sys.platform == 'win32':
        self._wlock = None
    else:
        self._wlock = ctx.Lock()
    self._sem = ctx.BoundedSemaphore(maxsize)
    self._ignore_epipe = False
    self._reset()
    if sys.platform != 'win32':
        register_after_fork(self, Queue._after_fork)

def __getstate__(self):
    context.assert_spawning(self)
    return (self._ignore_epipe, self._maxsize, self._reader, self._writer, self._rlock, self._wlock, self._sem, self._opid)

def __setstate__(self, state):
    self._ignore_epipe, self._maxsize, self._reader, self._writer, self._rlock, self._wlock, self._sem, self._opid = state
    self._reset()

def _after_fork(self):
    debug('Queue._after_fork()')
    self._reset(after_fork=True)

def put(self, obj, block=True, timeout=None):
    if self._closed:
        raise ValueError(f'Queue {self!r} is closed')
    if not self._sem.acquire(block, timeout):
        raise Full
    with self._notempty:
        if self._thread is None:
            self._start_thread()
        self._buffer.append(obj)
        self._notempty.notify()

def get(self, block=True, timeout=None):
    if self._closed:
        raise ValueError(f'Queue {self!r} is closed')
    if block and timeout is None:
        with self._rlock:
            res = self._recv_bytes()
        self._sem.release()
    else:
        if block:
            deadline = time.monotonic() + timeout
        if not self._rlock.acquire(block, timeout):
            raise Empty
        try:
            if block:
                timeout = deadline - time.monotonic()
                if not self._poll(timeout):
                    raise Empty
            elif not self._poll():
                raise Empty
            res = self._recv_bytes()
            self._sem.release()
        finally:
            self._rlock.release()
    return _ForkingPickler.loads(res)

def close(self):
    self._closed = True
    close = self._close
    if close:
        self._close = None
        close()

def join_thread(self):
    debug('Queue.join_thread()')
    assert self._closed, 'Queue {0!r} not closed'.format(self)
    if self._jointhread:
        self._jointhread()

def cancel_join_thread(self):
    debug('Queue.cancel_join_thread()')
    self._joincancelled = True
    try:
        self._jointhread.cancel()
    except AttributeError:
        pass

def _terminate_broken(self):
    self._reader.close()
