def _rebuild_socket(df, family, type, proto):
    fd = df.detach()
    return socket.socket(family, type, proto, fileno=fd)

def __init__(self, handle, access, pid=None):
    if pid is None:
        pid = os.getpid()
    proc = _winapi.OpenProcess(_winapi.PROCESS_DUP_HANDLE, False, pid)
    try:
        self._handle = _winapi.DuplicateHandle(_winapi.GetCurrentProcess(), handle, proc, access, False, 0)
    finally:
        _winapi.CloseHandle(proc)
    self._access = access
    self._pid = pid

def detach(self):
    """Get the handle.  This should only be called once."""
    if self._pid == os.getpid():
        return self._handle
    proc = _winapi.OpenProcess(_winapi.PROCESS_DUP_HANDLE, False, self._pid)
    try:
        return _winapi.DuplicateHandle(proc, self._handle, _winapi.GetCurrentProcess(), self._access, False, _winapi.DUPLICATE_CLOSE_SOURCE)
    finally:
        _winapi.CloseHandle(proc)

def register(self, send, close):
    """Register resource, returning an identifier."""
    with self._lock:
        if self._address is None:
            self._start()
        self._key += 1
        self._cache[self._key] = (send, close)
        return (self._address, self._key)

def _afterfork(self):
    for key, (send, close) in self._cache.items():
        close()
    self._cache.clear()
    self._lock._at_fork_reinit()
    if self._listener is not None:
        self._listener.close()
    self._listener = None
    self._address = None
    self._thread = None

def _serve(self):
    if hasattr(signal, 'pthread_sigmask'):
        signal.pthread_sigmask(signal.SIG_BLOCK, signal.valid_signals())
    while 1:
        try:
            with self._listener.accept() as conn:
                msg = conn.recv()
                if msg is None:
                    break
                key, destination_pid = msg
                send, close = self._cache.pop(key)
                try:
                    send(conn, destination_pid)
                finally:
                    close()
        except:
            if not util.is_exiting():
                sys.excepthook(*sys.exc_info())

def __init__(self, sock):
