def send(conn, pid):
    share = new_sock.share(pid)
    conn.send_bytes(share)

def _stop(self, use_blocking_lock=True):
    if use_blocking_lock:
        with self._lock:
            self._stop_locked()
    else:
        acquired = self._lock.acquire(blocking=False)
        try:
            self._stop_locked()
        finally:
            if acquired:
                self._lock.release()

def _stop_locked(self, close=os.close, waitpid=os.waitpid, waitstatus_to_exitcode=os.waitstatus_to_exitcode):
    if self._lock._recursion_count() > 1:
        return self._reentrant_call_error()
    if self._fd is None:
        return
    if self._pid is None:
        return
    close(self._fd)
    self._fd = None
    waitpid(self._pid, 0)
    self._pid = None

def getfd(self):
    self.ensure_running()
    return self._fd

def _check_alive(self):
    """Check that the pipe has not been closed by sending a probe."""
    try:
        os.write(self._fd, b'PROBE:0:noop\n')
    except OSError:
        return False
    else:
        return True

def register(self, name, rtype):
    """Register name of resource with resource tracker."""
    self._send('REGISTER', name, rtype)

def unregister(self, name, rtype):
    """Unregister name of resource with resource tracker."""
    self._send('UNREGISTER', name, rtype)

def _send(self, cmd, name, rtype):
    try:
        self.ensure_running()
    except ReentrantCallError:
        warnings.warn(f'ResourceTracker called reentrantly for resource cleanup, which is unsupported. The {rtype} object {name!r} might leak.')
    msg = '{0}:{1}:{2}\n'.format(cmd, name, rtype).encode('ascii')
    if len(msg) > 512:
        raise ValueError('msg too long')
    nbytes = os.write(self._fd, msg)
    assert nbytes == len(msg), 'nbytes {0:n} but len(msg) {1:n}'.format(nbytes, len(msg))

def __del__(self):
    try:
        self.close()
    except OSError:
        pass

@property
def buf(self):
    """A memoryview of contents of the shared memory block."""
    return self._buf

@property
def name(self):
    """Unique name that identifies the shared memory block."""
    reported_name = self._name
    if _USE_POSIX and self._prepend_leading_slash:
        if self._name.startswith('/'):
            reported_name = self._name[1:]
    return reported_name

def close(self):
    """Closes access to the shared memory from this instance but does
    not destroy the shared memory block."""
    if self._buf is not None:
        self._buf.release()
        self._buf = None
    if self._mmap is not None:
        self._mmap.close()
        self._mmap = None
    if _USE_POSIX and self._fd >= 0:
        os.close(self._fd)
        self._fd = -1

@staticmethod
def _extract_recreation_code(value):
    """Used in concert with _back_transforms_mapping to convert values
    into the appropriate Python objects when retrieving them from
    the list as well as when storing them."""
    if not isinstance(value, (str, bytes, None.__class__)):
        return 0
    elif isinstance(value, str):
        return 1
    elif isinstance(value, bytes):
        return 2
    else:
        return 3

def __getitem__(self, position):
    position = position if position >= 0 else position + self._list_len
    try:
        offset = self._offset_data_start + self._allocated_offsets[position]
        v, = struct.unpack_from(self._get_packing_format(position), self.shm.buf, offset)
    except IndexError:
        raise IndexError('index out of range')
    back_transform = self._get_back_transform(position)
    v = back_transform(v)
    return v

def __setitem__(self, position, value):
    position = position if position >= 0 else position + self._list_len
    try:
        item_offset = self._allocated_offsets[position]
        offset = self._offset_data_start + item_offset
        current_format = self._get_packing_format(position)
    except IndexError:
        raise IndexError('assignment index out of range')
    if not isinstance(value, (str, bytes)):
        new_format = self._types_mapping[type(value)]
        encoded_value = value
    else:
        allocated_length = self._allocated_offsets[position + 1] - item_offset
        encoded_value = value.encode(_encoding) if isinstance(value, str) else value
        if len(encoded_value) > allocated_length:
            raise ValueError('bytes/str item exceeds available storage')
        if current_format[-1] == 's':
            new_format = current_format
        else:
            new_format = self._types_mapping[str] % (allocated_length,)
    self._set_packing_format_and_transform(position, new_format, value)
    struct.pack_into(new_format, self.shm.buf, offset, encoded_value)

@property
def format(self):
    """The struct packing format used by all currently stored items."""
    return ''.join((self._get_packing_format(i) for i in range(self._list_len)))

@property
def _format_size_metainfo(self):
    """The struct packing format used for the items' storage offsets."""
    return 'q' * (self._list_len + 1)

@property
def _format_packing_metainfo(self):
    """The struct packing format used for the items' packing formats."""
    return '8s' * self._list_len

@property
def _format_back_transform_codes(self):
    """The struct packing format used for the items' back transforms."""
    return 'b' * self._list_len

@property
def _offset_data_start(self):
    return (self._list_len + 2) * 8

@property
def _offset_packing_formats(self):
    return self._offset_data_start + self._allocated_offsets[-1]

@property
def _offset_back_transform_codes(self):
    return self._offset_packing_formats + self._list_len * 8

def count(self, value):
    """L.count(value) -> integer -- return number of occurrences of value."""
    return sum((value == entry for entry in self))

def index(self, value):
    """L.index(value) -> integer -- return first index of value.
    Raises ValueError if the value is not present."""
    for position, entry in enumerate(self):
        if value == entry:
            return position
    else:
        raise ValueError(f'{value!r} not in this container')

def _new_value(type_):
    size = ctypes.sizeof(type_)
    wrapper = heap.BufferWrapper(size)
    return rebuild_ctype(type_, wrapper, None)

def Value(typecode_or_type, *args, lock=True, ctx=None):
    """Return a synchronization wrapper for a Value"""
    obj = RawValue(typecode_or_type, *args)
    if lock is False:
        return obj
    if lock in (True, None):
        ctx = ctx or get_context()
        lock = ctx.RLock()
    if not hasattr(lock, 'acquire'):
        raise AttributeError("%r has no method 'acquire'" % lock)
    return synchronized(obj, lock, ctx=ctx)

def Array(typecode_or_type, size_or_initializer, *, lock=True, ctx=None):
    """Return a synchronization wrapper for a RawArray"""
    obj = RawArray(typecode_or_type, size_or_initializer)
    if lock is False:
        return obj
    if lock in (True, None):
        ctx = ctx or get_context()
        lock = ctx.RLock()
    if not hasattr(lock, 'acquire'):
        raise AttributeError("%r has no method 'acquire'" % lock)
    return synchronized(obj, lock, ctx=ctx)

def synchronized(obj, lock=None, ctx=None):
    assert not isinstance(obj, SynchronizedBase), 'object already synchronized'
    ctx = ctx or get_context()
    if isinstance(obj, ctypes._SimpleCData):
        return Synchronized(obj, lock, ctx)
    elif isinstance(obj, ctypes.Array):
        if obj._type_ is ctypes.c_char:
            return SynchronizedString(obj, lock, ctx)
        return SynchronizedArray(obj, lock, ctx)
    else:
        cls = type(obj)
        try:
            scls = class_cache[cls]
        except KeyError:
            names = [field[0] for field in cls._fields_]
            d = {name: make_property(name) for name in names}
            classname = 'Synchronized' + cls.__name__
            scls = class_cache[cls] = type(classname, (SynchronizedBase,), d)
        return scls(obj, lock, ctx)

def reduce_ctype(obj):
    assert_spawning(obj)
    if isinstance(obj, ctypes.Array):
        return (rebuild_ctype, (obj._type_, obj._wrapper, obj._length_))
    else:
        return (rebuild_ctype, (type(obj), obj._wrapper, None))

def make_property(name):
    try:
        return prop_cache[name]
    except KeyError:
        d = {}
        exec(template % ((name,) * 7), d)
        prop_cache[name] = d[name]
        return d[name]

def __init__(self, obj, lock=None, ctx=None):
    self._obj = obj
    if lock:
        self._lock = lock
    else:
        ctx = ctx or get_context(force=True)
        self._lock = ctx.RLock()
    self.acquire = self._lock.acquire
    self.release = self._lock.release

def __reduce__(self):
    assert_spawning(self)
    return (synchronized, (self._obj, self._lock))

def __getitem__(self, i):
    with self:
        return self._obj[i]

def __setitem__(self, i, value):
    with self:
        self._obj[i] = value

def __getslice__(self, start, stop):
    with self:
