def set_executable(exe):
    global _python_exe
    if exe is None:
        _python_exe = exe
    elif sys.platform == 'win32':
        _python_exe = os.fsdecode(exe)
    else:
        _python_exe = os.fsencode(exe)

def is_forking(argv):
    """Return whether commandline indicates we are forking"""
    if len(argv) >= 2 and argv[1] == '--multiprocessing-fork':
        return True
    else:
        return False

def freeze_support():
    """Run code for process object if this in not the main process"""
    if is_forking(sys.argv):
        kwds = {}
        for arg in sys.argv[2:]:
            name, value = arg.split('=')
            if value == 'None':
                kwds[name] = None
            else:
                kwds[name] = int(value)
        spawn_main(**kwds)
        sys.exit()

def get_command_line(**kwds):
    """Returns prefix of command line used for spawning a child process"""
    if getattr(sys, 'frozen', False):
        return [sys.executable, '--multiprocessing-fork'] + ['%s=%r' % item for item in kwds.items()]
    else:
        prog = 'from multiprocessing.spawn import spawn_main; spawn_main(%s)'
        prog %= ', '.join(('%s=%r' % item for item in kwds.items()))
        opts = util._args_from_interpreter_flags()
        exe = get_executable()
        return [exe] + opts + ['-c', prog, '--multiprocessing-fork']

def _main(fd, parent_sentinel):
    with os.fdopen(fd, 'rb', closefd=True) as from_parent:
        process.current_process()._inheriting = True
        try:
            preparation_data = reduction.pickle.load(from_parent)
            prepare(preparation_data)
            self = reduction.pickle.load(from_parent)
        finally:
            del process.current_process()._inheriting
    return self._bootstrap(parent_sentinel)

def get_preparation_data(name):
    """Return info about parent needed by child to unpickle process object"""
    _check_not_importing_main()
    d = dict(log_to_stderr=util._log_to_stderr, authkey=process.current_process().authkey)
    if util._logger is not None:
        d['log_level'] = util._logger.getEffectiveLevel()
    sys_path = sys.path.copy()
    try:
        i = sys_path.index('')
    except ValueError:
        pass
    else:
        sys_path[i] = process.ORIGINAL_DIR
    d.update(name=name, sys_path=sys_path, sys_argv=sys.argv, orig_dir=process.ORIGINAL_DIR, dir=os.getcwd(), start_method=get_start_method())
    main_module = sys.modules['__main__']
    main_mod_name = getattr(main_module.__spec__, 'name', None)
    if main_mod_name is not None:
        d['init_main_from_name'] = main_mod_name
    elif sys.platform != 'win32' or (not WINEXE and (not WINSERVICE)):
        main_path = getattr(main_module, '__file__', None)
        if main_path is not None:
            if not os.path.isabs(main_path) and process.ORIGINAL_DIR is not None:
                main_path = os.path.join(process.ORIGINAL_DIR, main_path)
            d['init_main_from_path'] = os.path.normpath(main_path)
    return d

def prepare(data):
    """Try to get current process ready to unpickle process object"""
    if 'name' in data:
        process.current_process().name = data['name']
    if 'authkey' in data:
        process.current_process().authkey = data['authkey']
    if 'log_to_stderr' in data and data['log_to_stderr']:
        util.log_to_stderr()
    if 'log_level' in data:
        util.get_logger().setLevel(data['log_level'])
    if 'sys_path' in data:
        sys.path = data['sys_path']
    if 'sys_argv' in data:
        sys.argv = data['sys_argv']
    if 'dir' in data:
        os.chdir(data['dir'])
    if 'orig_dir' in data:
        process.ORIGINAL_DIR = data['orig_dir']
    if 'start_method' in data:
        set_start_method(data['start_method'], force=True)
    if 'init_main_from_name' in data:
        _fixup_main_from_name(data['init_main_from_name'])
    elif 'init_main_from_path' in data:
        _fixup_main_from_path(data['init_main_from_path'])

def import_main_path(main_path):
    """Set sys.modules['__main__'] to module at main_path"""
    _fixup_main_from_path(main_path)

def __init__(self, kind, value, maxvalue, *, ctx):
    if ctx is None:
        ctx = context._default_context.get_context()
    self._is_fork_ctx = ctx.get_start_method() == 'fork'
    unlink_now = sys.platform == 'win32' or self._is_fork_ctx
    for i in range(100):
        try:
            sl = self._semlock = _multiprocessing.SemLock(kind, value, maxvalue, self._make_name(), unlink_now)
        except FileExistsError:
            pass
        else:
            break
    else:
        raise FileExistsError('cannot find name for semaphore')
    util.debug('created semlock with handle %s' % sl.handle)
    self._make_methods()
    if sys.platform != 'win32':
        def _after_fork(obj):
            obj._semlock._after_fork()
        util.register_after_fork(self, _after_fork)
    if self._semlock.name is not None:
        from .resource_tracker import register
        register(self._semlock.name, 'semaphore')
        util.Finalize(self, SemLock._cleanup, (self._semlock.name,), exitpriority=0)

@staticmethod
def _cleanup(name):
    from .resource_tracker import unregister
    sem_unlink(name)
    unregister(name, 'semaphore')

def _make_methods(self):
    self.acquire = self._semlock.acquire
    self.release = self._semlock.release

def __getstate__(self):
    context.assert_spawning(self)
    sl = self._semlock
    if sys.platform == 'win32':
        h = context.get_spawning_popen().duplicate_for_child(sl.handle)
    else:
        if self._is_fork_ctx:
            raise RuntimeError('A SemLock created in a fork context is being shared with a process in a spawn context. This is not supported. Please use the same context to create multiprocessing objects and Process.')
        h = sl.handle
    return (h, sl.kind, sl.maxvalue, sl.name)

@staticmethod
def _make_name():
    return '%s-%s' % (process.current_process()._config['semprefix'], next(SemLock._rand))

def __repr__(self):
    try:
        value = self._semlock._get_value()
    except Exception:
        value = 'unknown'
    return '<%s(value=%s)>' % (self.__class__.__name__, value)

def __repr__(self):
    try:
        value = self._semlock._get_value()
    except Exception:
        value = 'unknown'
    return '<%s(value=%s, maxvalue=%s)>' % (self.__class__.__name__, value, self._semlock.maxvalue)

def __repr__(self):
    try:
        if self._semlock._is_mine():
            name = process.current_process().name
            if threading.current_thread().name != 'MainThread':
                name += '|' + threading.current_thread().name
        elif not self._semlock._is_zero():
            name = 'None'
        elif self._semlock._count() > 0:
            name = 'SomeOtherThread'
        else:
            name = 'SomeOtherProcess'
    except Exception:
        name = 'unknown'
    return '<%s(owner=%s)>' % (self.__class__.__name__, name)

def __repr__(self):
    try:
        if self._semlock._is_mine():
            name = process.current_process().name
            if threading.current_thread().name != 'MainThread':
                name += '|' + threading.current_thread().name
            count = self._semlock._count()
        elif not self._semlock._is_zero():
            name, count = ('None', 0)
        elif self._semlock._count() > 0:
            name, count = ('SomeOtherThread', 'nonzero')
        else:
            name, count = ('SomeOtherProcess', 'nonzero')
    except Exception:
        name, count = ('unknown', 'unknown')
    return '<%s(%s, %s)>' % (self.__class__.__name__, name, count)

def __getstate__(self):
    context.assert_spawning(self)
    return (self._lock, self._sleeping_count, self._woken_count, self._wait_semaphore)

def _make_methods(self):
    self.acquire = self._lock.acquire
    self.release = self._lock.release

def __repr__(self):
    try:
        num_waiters = self._sleeping_count._semlock._get_value() - self._woken_count._semlock._get_value()
    except Exception:
        num_waiters = 'unknown'
    return '<%s(%s, %s)>' % (self.__class__.__name__, self._lock, num_waiters)

def wait(self, timeout=None):
    assert self._lock._semlock._is_mine(), 'must acquire() condition before using wait()'
    self._sleeping_count.release()
    count = self._lock._semlock._count()
    for i in range(count):
        self._lock.release()
    try:
        return self._wait_semaphore.acquire(True, timeout)
    finally:
        self._woken_count.release()
        for i in range(count):
            self._lock.acquire()

def notify(self, n=1):
    assert self._lock._semlock._is_mine(), 'lock is not owned'
    assert not self._wait_semaphore.acquire(False), 'notify: Should not have been able to acquire ' + '_wait_semaphore'
    while self._woken_count.acquire(False):
        res = self._sleeping_count.acquire(False)
        assert res, 'notify: Bug in sleeping_count.acquire' + '- res should not be False'
    sleepers = 0
    while sleepers < n and self._sleeping_count.acquire(False):
        self._wait_semaphore.release()
        sleepers += 1
    if sleepers:
        for i in range(sleepers):
            self._woken_count.acquire()
        while self._wait_semaphore.acquire(False):
            pass

def __init__(self, *, ctx):
    self._cond = ctx.Condition(ctx.Lock())
    self._flag = ctx.Semaphore(0)

def is_set(self):
    with self._cond:
        if self._flag.acquire(False):
            self._flag.release()
            return True
        return False

def clear(self):
    with self._cond:
        self._flag.acquire(False)

def __repr__(self):
    set_status = 'set' if self.is_set() else 'unset'
    return f'<{type(self).__qualname__} at {id(self):#x} {set_status}>'

def __setstate__(self, state):
    self._parties, self._action, self._timeout, self._cond, self._wrapper = state
    self._array = self._wrapper.create_memoryview().cast('i')

@property
def _state(self):
    return self._array[0]

@_state.setter
def _state(self, value):
    self._array[0] = value

@property
def _count(self):
    return self._array[1]

@_count.setter
def _count(self, value):
    self._array[1] = value

def sub_debug(msg, *args):
    if _logger:
        _logger.log(SUBDEBUG, msg, *args, stacklevel=2)

def debug(msg, *args):
    if _logger:
        _logger.log(DEBUG, msg, *args, stacklevel=2)

def info(msg, *args):
    if _logger:
        _logger.log(INFO, msg, *args, stacklevel=2)

def _platform_supports_abstract_sockets():
    if sys.platform == 'linux':
        return True
    if hasattr(sys, 'getandroidapilevel'):
        return True
    return False

def is_abstract_socket_namespace(address):
    if not address:
        return False
    if isinstance(address, bytes):
        return address[0] == 0
    elif isinstance(address, str):
        return address[0] == '\x00'
    raise TypeError(f'address type of {address!r} unrecognized')

def _remove_temp_dir(rmtree, tempdir):
    def onerror(func, path, err_info):
        if not issubclass(err_info[0], FileNotFoundError):
            raise
    rmtree(tempdir, onerror=onerror)
    current_process = process.current_process()
    if current_process is not None:
        current_process._config['tempdir'] = None

def _run_after_forkers():
    items = list(_afterfork_registry.items())
    items.sort()
    for (index, ident, func), obj in items:
        try:
            func(obj)
        except Exception as e:
            info('after forker raised exception %s', e)

def _run_finalizers(minpriority=None):
    """Run all finalizers whose exit priority is not None and at least minpriority

    Finalizers with highest priority are called first; finalizers with
    the same priority will be called in reverse order of creation."""
    if _finalizer_registry is None:
        return
    if minpriority is None:
        f = lambda p: p[0] is not None
    else:
        f = lambda p: p[0] is not None and p[0] >= minpriority
    keys = [key for key in list(_finalizer_registry) if f(key)]
    keys.sort(reverse=True)
    for key in keys:
        finalizer = _finalizer_registry.get(key)
        if finalizer is not None:
            sub_debug('calling %s', finalizer)
            try:
                finalizer()
            except Exception:
                import traceback
                traceback.print_exc()
    if minpriority is None:
        _finalizer_registry.clear()

def is_exiting():
    """Returns true if the process is shutting down"""
    return _exiting or _exiting is None

def _exit_function(info=info, debug=debug, _run_finalizers=_run_finalizers, active_children=process.active_children, current_process=process.current_process):
    global _exiting
    if not _exiting:
        _exiting = True
        info('process shutting down')
        debug('running all "atexit" finalizers with priority >= 0')
        _run_finalizers(0)
        if current_process() is not None:
            for p in active_children():
                if p.daemon:
                    info('calling terminate() for daemon %s', p.name)
                    p._popen.terminate()
            for p in active_children():
                info('calling join() for process %s', p.name)
                p.join()
        debug('running the remaining "atexit" finalizers')
        _run_finalizers()

def close_all_fds_except(fds):
    fds = list(fds) + [-1, MAXFD]
    fds.sort()
    assert fds[-1] == MAXFD, 'fd too large'
    for i in range(len(fds) - 1):
        os.closerange(fds[i] + 1, fds[i + 1])

def _flush_std_streams():
    try:
        sys.stdout.flush()
    except (AttributeError, ValueError):
        pass
    try:
        sys.stderr.flush()
    except (AttributeError, ValueError):
        pass

def spawnv_passfds(path, args, passfds):
    import _posixsubprocess
    import subprocess
    passfds = tuple(sorted(map(int, passfds)))
    errpipe_read, errpipe_write = os.pipe()
    try:
        return _posixsubprocess.fork_exec(args, [path], True, passfds, None, None, -1, -1, -1, -1, -1, -1, errpipe_read, errpipe_write, False, False, -1, None, None, None, -1, None, subprocess._USE_VFORK)
    finally:
        os.close(errpipe_read)
        os.close(errpipe_write)

def close_fds(*fds):
    """Close each file descriptor given as an argument"""
    for fd in fds:
        os.close(fd)

def onerror(func, path, err_info):
    if not issubclass(err_info[0], FileNotFoundError):
        raise

def __init__(self, obj, callback, args=(), kwargs=None, exitpriority=None):
    if exitpriority is not None and (not isinstance(exitpriority, int)):
        raise TypeError('Exitpriority ({0!r}) must be None or int, not {1!s}'.format(exitpriority, type(exitpriority)))
    if obj is not None:
        self._weakref = weakref.ref(obj, self)
    elif exitpriority is None:
        raise ValueError('Without object, exitpriority cannot be None')
    self._callback = callback
    self._args = args
    self._kwargs = kwargs or {}
    self._key = (exitpriority, next(_finalizer_counter))
    self._pid = os.getpid()
    _finalizer_registry[self._key] = self

def __call__(self, wr=None, _finalizer_registry=_finalizer_registry, sub_debug=sub_debug, getpid=os.getpid):
    """Run the callback unless it has already been called or cancelled"""
    try:
        del _finalizer_registry[self._key]
    except KeyError:
        sub_debug('finalizer no longer registered')
    else:
        if self._pid != getpid():
            sub_debug('finalizer ignored because different process')
            res = None
        else:
            sub_debug('finalizer calling %s with args %s and kwargs %s', self._callback, self._args, self._kwargs)
            res = self._callback(*self._args, **self._kwargs)
        self._weakref = self._callback = self._args = self._kwargs = self._key = None
        return res

def cancel(self):
    """Cancel finalization of the object"""
    try:
        del _finalizer_registry[self._key]
    except KeyError:
        pass
    else:
        self._weakref = self._callback = self._args = self._kwargs = self._key = None

def still_active(self):
    """Return whether this finalizer is still waiting to invoke callback"""
    return self._key in _finalizer_registry

def __repr__(self):
    try:
        obj = self._weakref()
    except (AttributeError, TypeError):
        obj = None
    if obj is None:
        return '<%s object, dead>' % self.__class__.__name__
    x = '<%s object, callback=%s' % (self.__class__.__name__, getattr(self._callback, '__name__', self._callback))
    if self._args:
        x += ', args=' + str(self._args)
    if self._kwargs:
        x += ', kwargs=' + str(self._kwargs)
    if self._key[0] is not None:
        x += ', exitpriority=' + str(self._key[0])
    return x + '>'

def _read_char(self):
    ch = self.instream.read(1)
    if ch == '\n':
        self.lineno += 1
    return ch

def get_token(self):
    if self.pushback:
        return self.pushback.pop(0)
    token = ''
    fiter = iter(self._read_char, '')
    for ch in fiter:
        if ch in self.whitespace:
            continue
        if ch == '"':
            for ch in fiter:
                if ch == '"':
                    return token
                elif ch == '\\':
                    ch = self._read_char()
                token += ch
        else:
            if ch == '\\':
                ch = self._read_char()
            token += ch
            for ch in fiter:
                if ch in self.whitespace:
                    return token
                elif ch == '\\':
                    ch = self._read_char()
                token += ch
    return token

def __init__(self, file=None):
    default_netrc = file is None
    if file is None:
        file = os.path.join(os.path.expanduser('~'), '.netrc')
    self.hosts = {}
    self.macros = {}
    try:
        with open(file, encoding='utf-8') as fp:
            self._parse(file, fp, default_netrc)
    except UnicodeDecodeError:
        with open(file, encoding='locale') as fp:
            self._parse(file, fp, default_netrc)

def authenticators(self, host):
    """Return a (user, account, password) tuple for given host."""
    if host in self.hosts:
        return self.hosts[host]
    elif 'default' in self.hosts:
        return self.hosts['default']
    else:
        return None

def __repr__(self):
    """Dump the class data in the format of a .netrc file."""
    rep = ''
    for host in self.hosts.keys():
        attrs = self.hosts[host]
        rep += f'machine {host}\n\tlogin {attrs[0]}\n'
        if attrs[1]:
            rep += f'\taccount {attrs[1]}\n'
        rep += f'\tpassword {attrs[2]}\n'
    for macro in self.macros.keys():
        rep += f'macdef {macro}\n'
        for line in self.macros[macro]:
            rep += line
        rep += '\n'
    return rep

def _parse_overview(lines, fmt, data_process_func=None):
    """Parse the response to an OVER or XOVER command according to the
    overview format `fmt`."""
    n_defaults = len(_DEFAULT_OVERVIEW_FMT)
    overview = []
    for line in lines:
        fields = {}
        article_number, *tokens = line.split('\t')
        article_number = int(article_number)
        for i, token in enumerate(tokens):
            if i >= len(fmt):
                continue
            field_name = fmt[i]
            is_metadata = field_name.startswith(':')
            if i >= n_defaults and (not is_metadata):
                h = field_name + ': '
                if token and token[:len(h)].lower() != h:
                    raise NNTPDataError("OVER/XOVER response doesn't include names of additional headers")
                token = token[len(h):] if token else None
            fields[fmt[i]] = token
        overview.append((article_number, fields))
    return overview

def __init__(self, *args):
    Exception.__init__(self, *args)
    try:
        self.response = args[0]
    except IndexError:
        self.response = 'No response given'

def _encrypt_on(sock, context, hostname):
    """Wrap a socket in SSL/TLS. Arguments:
    - sock: Socket to wrap
    - context: SSL context to use for the encrypted connection
    Returns:
    - sock: New, encrypted socket."""
    if context is None:
        context = ssl._create_stdlib_context()
    return context.wrap_socket(sock, server_hostname=hostname)

def __exit__(self, *args):
    is_connected = lambda: hasattr(self, 'file')
    if is_connected():
        try:
            self.quit()
        except (OSError, EOFError):
            pass
        finally:
            if is_connected():
                self._close()

def _create_socket(self, timeout):
    if timeout is not None and (not timeout):
        raise ValueError('Non-blocking socket (timeout=0) is not supported')
    sys.audit('nntplib.connect', self, self.host, self.port)
    return socket.create_connection((self.host, self.port), timeout)

def getwelcome(self):
    """Get the welcome message from the server
    (this is read and squirreled away by __init__()).
    If the response code is 200, posting is allowed;
    if it 201, posting is not allowed."""
    if self.debugging:
        print('*welcome*', repr(self.welcome))
    return self.welcome

def getcapabilities(self):
    """Get the server capabilities, as read by __init__().
    If the CAPABILITIES command is not supported, an empty dict is
    returned."""
    if self._caps is None:
        self.nntp_version = 1
        self.nntp_implementation = None
        try:
            resp, caps = self.capabilities()
        except (NNTPPermanentError, NNTPTemporaryError):
            self._caps = {}
        else:
            self._caps = caps
            if 'VERSION' in caps:
                self.nntp_version = max(map(int, caps['VERSION']))
            if 'IMPLEMENTATION' in caps:
                self.nntp_implementation = ' '.join(caps['IMPLEMENTATION'])
    return self._caps

def _getline(self, strip_crlf=True):
    """Internal: return one line from the server, stripping _CRLF.
    Raise EOFError if the connection is closed.
    Returns a bytes object."""
    line = self.file.readline(_MAXLINE + 1)
    if len(line) > _MAXLINE:
        raise NNTPDataError('line too long')
    if self.debugging > 1:
        print('*get*', repr(line))
    if not line:
        raise EOFError
    if strip_crlf:
        if line[-2:] == _CRLF:
            line = line[:-2]
        elif line[-1:] in _CRLF:
            line = line[:-1]
    return line

def _getresp(self):
    """Internal: get a response from the server.
    Raise various errors if the response indicates an error.
    Returns a unicode string."""
    resp = self._getline()
    if self.debugging:
        print('*resp*', repr(resp))
    resp = resp.decode(self.encoding, self.errors)
    c = resp[:1]
    if c == '4':
        raise NNTPTemporaryError(resp)
    if c == '5':
        raise NNTPPermanentError(resp)
    if c not in '123':
        raise NNTPProtocolError(resp)
    return resp

def _getlongresp(self, file=None):
    """Internal: get a response plus following text from the server.
    Raise various errors if the response indicates an error.

    Returns a (response, lines) tuple where `response` is a unicode
    string and `lines` is a list of bytes objects.
    If `file` is a file-like object, it must be open in binary mode."""
    openedFile = None
    try:
        if isinstance(file, (str, bytes)):
            openedFile = file = open(file, 'wb')
        resp = self._getresp()
        if resp[:3] not in _LONGRESP:
            raise NNTPReplyError(resp)
        lines = []
        if file is not None:
            terminators = (b'.' + _CRLF, b'.\n')
            while 1:
                line = self._getline(False)
                if line in terminators:
                    break
                if line.startswith(b'..'):
                    line = line[1:]
                file.write(line)
        else:
            terminator = b'.'
            while 1:
                line = self._getline()
                if line == terminator:
                    break
                if line.startswith(b'..'):
                    line = line[1:]
                lines.append(line)
    finally:
        if openedFile:
            openedFile.close()
    return (resp, lines)

def _shortcmd(self, line):
    """Internal: send a command and get the response.
    Same return value as _getresp()."""
    self._putcmd(line)
    return self._getresp()

def _longcmd(self, line, file=None):
    """Internal: send a command and get the response plus following text.
    Same return value as _getlongresp()."""
    self._putcmd(line)
    return self._getlongresp(file)

def _getoverviewfmt(self):
    """Internal: get the overview format. Queries the server if not
    already done, else returns the cached value."""
    try:
        return self._cachedoverviewfmt
    except AttributeError:
        pass
    try:
        resp, lines = self._longcmdstring('LIST OVERVIEW.FMT')
    except NNTPPermanentError:
        fmt = _DEFAULT_OVERVIEW_FMT[:]
    else:
        fmt = _parse_overview_fmt(lines)
    self._cachedoverviewfmt = fmt
    return fmt

def capabilities(self):
    """Process a CAPABILITIES command.  Not supported by all servers.
    Return:
    - resp: server response if successful
    - caps: a dictionary mapping capability names to lists of tokens
    (for example {'VERSION': ['2'], 'OVER': [], LIST: ['ACTIVE', 'HEADERS'] })"""
    caps = {}
    resp, lines = self._longcmdstring('CAPABILITIES')
    for line in lines:
        name, *tokens = line.split()
        caps[name] = tokens
    return (resp, caps)

def list(self, group_pattern=None, *, file=None):
    """Process a LIST or LIST ACTIVE command. Arguments:
    - group_pattern: a pattern indicating which groups to query
    - file: Filename string or file object to store the result in
    Returns:
    - resp: server response if successful
    - list: list of (group, last, first, flag) (strings)"""
    if group_pattern is not None:
        command = 'LIST ACTIVE ' + group_pattern
    else:
        command = 'LIST'
    resp, lines = self._longcmdstring(command, file)
    return (resp, self._grouplist(lines))

def _getdescriptions(self, group_pattern, return_all):
    line_pat = re.compile('^(?P<group>[^ \t]+)[ \t]+(.*)$')
    resp, lines = self._longcmdstring('LIST NEWSGROUPS ' + group_pattern)
    if not resp.startswith('215'):
        resp, lines = self._longcmdstring('XGTITLE ' + group_pattern)
    groups = {}
    for raw_line in lines:
        match = line_pat.search(raw_line.strip())
        if match:
            name, desc = match.group(1, 2)
            if not return_all:
                return desc
            groups[name] = desc
    if return_all:
        return (resp, groups)
    else:
        return ''

def descriptions(self, group_pattern):
    """Get descriptions for a range of groups."""
    return self._getdescriptions(group_pattern, True)

def _statparse(self, resp):
    """Internal: parse the response line of a STAT, NEXT, LAST,
    ARTICLE, HEAD or BODY command."""
    if not resp.startswith('22'):
        raise NNTPReplyError(resp)
    words = resp.split()
    art_num = int(words[1])
    message_id = words[2]
    return (resp, art_num, message_id)

def _statcmd(self, line):
    """Internal: process a STAT, NEXT or LAST command."""
    resp = self._shortcmd(line)
    return self._statparse(resp)

def stat(self, message_spec=None):
    """Process a STAT command.  Argument:
    - message_spec: article number or message id (if not specified,
      the current article is selected)
    Returns:
    - resp: server response if successful
    - art_num: the article number
    - message_id: the message id"""
    if message_spec:
        return self._statcmd('STAT {0}'.format(message_spec))
    else:
        return self._statcmd('STAT')

def next(self):
    """Process a NEXT command.  No arguments.  Return as for STAT."""
    return self._statcmd('NEXT')

def last(self):
    """Process a LAST command.  No arguments.  Return as for STAT."""
    return self._statcmd('LAST')

def _artcmd(self, line, file=None):
    """Internal: process a HEAD, BODY or ARTICLE command."""
    resp, lines = self._longcmd(line, file)
    resp, art_num, message_id = self._statparse(resp)
    return (resp, ArticleInfo(art_num, message_id, lines))

def head(self, message_spec=None, *, file=None):
    """Process a HEAD command.  Argument:
    - message_spec: article number or message id
    - file: filename string or file object to store the headers in
    Returns:
    - resp: server response if successful
    - ArticleInfo: (article number, message id, list of header lines)"""
    if message_spec is not None:
        cmd = 'HEAD {0}'.format(message_spec)
    else:
        cmd = 'HEAD'
    return self._artcmd(cmd, file)

def body(self, message_spec=None, *, file=None):
    """Process a BODY command.  Argument:
    - message_spec: article number or message id
    - file: filename string or file object to store the body in
    Returns:
    - resp: server response if successful
    - ArticleInfo: (article number, message id, list of body lines)"""
    if message_spec is not None:
        cmd = 'BODY {0}'.format(message_spec)
    else:
        cmd = 'BODY'
    return self._artcmd(cmd, file)

def article(self, message_spec=None, *, file=None):
    """Process an ARTICLE command.  Argument:
    - message_spec: article number or message id
    - file: filename string or file object to store the article in
    Returns:
    - resp: server response if successful
    - ArticleInfo: (article number, message id, list of article lines)"""
    if message_spec is not None:
        cmd = 'ARTICLE {0}'.format(message_spec)
    else:
        cmd = 'ARTICLE'
    return self._artcmd(cmd, file)

def slave(self):
    """Process a SLAVE command.  Returns:
    - resp: server response if successful"""
    return self._shortcmd('SLAVE')

def date(self):
    """Process the DATE command.
    Returns:
    - resp: server response if successful
    - date: datetime object"""
    resp = self._shortcmd('DATE')
    if not resp.startswith('111'):
        raise NNTPReplyError(resp)
    elem = resp.split()
    if len(elem) != 2:
        raise NNTPDataError(resp)
    date = elem[1]
    if len(date) != 14:
        raise NNTPDataError(resp)
    return (resp, _parse_datetime(date, None))

def _post(self, command, f):
    resp = self._shortcmd(command)
    if not resp.startswith('3'):
        raise NNTPReplyError(resp)
    if isinstance(f, (bytes, bytearray)):
        f = f.splitlines()
    for line in f:
        if not line.endswith(_CRLF):
            line = line.rstrip(b'\r\n') + _CRLF
        if line.startswith(b'.'):
            line = b'.' + line
        self.file.write(line)
    self.file.write(b'.\r\n')
    self.file.flush()
    return self._getresp()

def post(self, data):
    """Process a POST command.  Arguments:
    - data: bytes object, iterable or file containing the article
    Returns:
    - resp: server response if successful"""
    return self._post('POST', data)

def _close(self):
    try:
        if self.file:
            self.file.close()
            del self.file
    finally:
        self.sock.close()

def login(self, user=None, password=None, usenetrc=True):
    if self.authenticated:
        raise ValueError('Already logged in.')
    if not user and (not usenetrc):
        raise ValueError('At least one of `user` and `usenetrc` must be specified')
    try:
        if usenetrc and (not user):
            import netrc
            credentials = netrc.netrc()
            auth = credentials.authenticators(self.host)
            if auth:
                user = auth[0]
                password = auth[2]
    except OSError:
        pass
    if not user:
        return
    resp = self._shortcmd('authinfo user ' + user)
    if resp.startswith('381'):
        if not password:
            raise NNTPReplyError(resp)
        else:
            resp = self._shortcmd('authinfo pass ' + password)
            if not resp.startswith('281'):
                raise NNTPPermanentError(resp)
    self._caps = None
    self.getcapabilities()
    if self.readermode_afterauth and 'READER' not in self._caps:
        self._setreadermode()
        self._caps = None
        self.getcapabilities()

def _setreadermode(self):
    try:
        self.welcome = self._shortcmd('mode reader')
    except NNTPPermanentError:
        pass
    except NNTPTemporaryError as e:
        if e.response.startswith('480'):
            self.readermode_afterauth = True
        else:
            raise

