def lexists(path):
    """Test whether a path exists.  Returns True for broken symbolic links"""
    try:
        st = os.lstat(path)
    except (OSError, ValueError):
        return False
    return True

def ismount(path):
    """Test whether a path is a mount point (a drive root, the root of a
    share, or a mounted volume)"""
    path = os.fspath(path)
    seps = _get_bothseps(path)
    path = abspath(path)
    drive, root, rest = splitroot(path)
    if drive and drive[0] in seps:
        return not rest
    if root and (not rest):
        return True
    if _getvolumepathname:
        x = path.rstrip(seps)
        y = _getvolumepathname(path).rstrip(seps)
        return x.casefold() == y.casefold()
    else:
        return False

def expanduser(path):
    """Expand ~ and ~user constructs.

    If user or $HOME is unknown, do nothing."""
    path = os.fspath(path)
    if isinstance(path, bytes):
        tilde = b'~'
    else:
        tilde = '~'
    if not path.startswith(tilde):
        return path
    i, n = (1, len(path))
    while i < n and path[i] not in _get_bothseps(path):
        i += 1
    if 'USERPROFILE' in os.environ:
        userhome = os.environ['USERPROFILE']
    elif not 'HOMEPATH' in os.environ:
        return path
    else:
        try:
            drive = os.environ['HOMEDRIVE']
        except KeyError:
            drive = ''
        userhome = join(drive, os.environ['HOMEPATH'])
    if i != 1:
        target_user = path[1:i]
        if isinstance(target_user, bytes):
            target_user = os.fsdecode(target_user)
        current_user = os.environ.get('USERNAME')
        if target_user != current_user:
            if current_user != basename(userhome):
                return path
            userhome = join(dirname(userhome), target_user)
    if isinstance(path, bytes):
        userhome = os.fsencode(userhome)
    return userhome + path[i:]

def commonpath(paths):
    """Given a sequence of path names, returns the longest common sub-path."""
    if not paths:
        raise ValueError('commonpath() arg is an empty sequence')
    paths = tuple(map(os.fspath, paths))
    if isinstance(paths[0], bytes):
        sep = b'\\'
        altsep = b'/'
        curdir = b'.'
    else:
        sep = '\\'
        altsep = '/'
        curdir = '.'
    try:
        drivesplits = [splitroot(p.replace(altsep, sep).lower()) for p in paths]
        split_paths = [p.split(sep) for d, r, p in drivesplits]
        if len({r for d, r, p in drivesplits}) != 1:
            raise ValueError("Can't mix absolute and relative paths")
        if len({d for d, r, p in drivesplits}) != 1:
            raise ValueError("Paths don't have the same drive")
        drive, root, path = splitroot(paths[0].replace(altsep, sep))
        common = path.split(sep)
        common = [c for c in common if c and c != curdir]
        split_paths = [[c for c in s if c and c != curdir] for s in split_paths]
        s1 = min(split_paths)
        s2 = max(split_paths)
        for i, c in enumerate(s1):
            if c != s2[i]:
                common = common[:i]
                break
        else:
            common = common[:len(s1)]
        return drive + root + sep.join(common)
    except (TypeError, AttributeError):
        genericpath._check_arg_types('commonpath', *paths)
        raise

def normcase(s):
    """Normalize case of pathname.

    Makes all characters lowercase and all slashes into backslashes."""
    s = os.fspath(s)
    if not s:
        return s
    if isinstance(s, bytes):
        encoding = sys.getfilesystemencoding()
        s = s.decode(encoding, 'surrogateescape').replace('/', '\\')
        s = _LCMapStringEx(_LOCALE_NAME_INVARIANT, _LCMAP_LOWERCASE, s)
        return s.encode(encoding, 'surrogateescape')
    else:
        return _LCMapStringEx(_LOCALE_NAME_INVARIANT, _LCMAP_LOWERCASE, s.replace('/', '\\'))

def isjunction(path):
    """Test whether a path is a junction"""
    try:
        st = os.lstat(path)
    except (OSError, ValueError, AttributeError):
        return False
    return bool(st.st_reparse_tag == stat.IO_REPARSE_TAG_MOUNT_POINT)

def repl(m):
    lastindex = m.lastindex
    if lastindex is None:
        return m[0]
    name = m[lastindex]
    if lastindex == 1:
        if name == percent:
            return name
        if not name.endswith(percent):
            return m[0]
        name = name[:-1]
    else:
        if name == dollar:
            return name
        if name.startswith(brace):
            if not name.endswith(rbrace):
                return m[0]
            name = name[1:-1]
    try:
        if environ is None:
            return os.fsencode(os.environ[os.fsdecode(name)])
        else:
            return environ[name]
    except KeyError:
        return m[0]

def abspath(path):
    """Return the absolute version of a path."""
    try:
        return _getfullpathname(normpath(path))
    except (OSError, ValueError):
        pass
    path = os.fspath(path)
    if not isabs(path):
        if isinstance(path, bytes):
            sep = b'\\'
            getcwd = os.getcwdb
        else:
            sep = '\\'
            getcwd = os.getcwd
        drive, root, path = splitroot(path)
        if drive or root:
            try:
                path = join(_getfullpathname(drive + root), path)
            except (OSError, ValueError):
                path = drive + sep + path
        else:
            path = join(getcwd(), path)
    return normpath(path)

def _readlink_deep(path, ignored_error=OSError):
    allowed_winerror = (1, 2, 3, 5, 21, 32, 50, 67, 87, 4390, 4392, 4393)
    seen = set()
    while normcase(path) not in seen:
        seen.add(normcase(path))
        try:
            old_path = path
            path = _nt_readlink(path)
            if not isabs(path):
                if not islink(old_path):
                    path = old_path
                    break
                path = normpath(join(dirname(old_path), path))
        except ignored_error as ex:
            if ex.winerror in allowed_winerror:
                break
            raise
        except ValueError:
            break
    return path

def _getfinalpathname_nonstrict(path, ignored_error=OSError):
    allowed_winerror = (1, 2, 3, 5, 21, 32, 50, 53, 65, 67, 87, 123, 161, 1920, 1921)
    tail = path[:0]
    while path:
        try:
            path = _getfinalpathname(path)
            return join(path, tail) if tail else path
        except ignored_error as ex:
            if ex.winerror not in allowed_winerror:
                raise
            try:
                new_path = _readlink_deep(path, ignored_error=ignored_error)
                if new_path != path:
                    return join(new_path, tail) if tail else new_path
            except ignored_error:
                pass
            path, name = split(path)
            if path and (not name):
                return path + tail
            tail = join(name, tail) if tail else name
    return tail

