def __init__(self, attr, *attrs):
    if not attrs:
        if not isinstance(attr, str):
            raise TypeError('attribute name must be a string')
        self._attrs = (attr,)
        names = attr.split('.')
        def func(obj):
            for name in names:
                obj = getattr(obj, name)
            return obj
        self._call = func
    else:
        self._attrs = (attr,) + attrs
        getters = tuple(map(attrgetter, self._attrs))
        def func(obj):
            return tuple((getter(obj) for getter in getters))
        self._call = func

def __init__(self, item, *items):
    if not items:
        self._items = (item,)
        def func(obj):
            return obj[item]
        self._call = func
    else:
        self._items = items = (item,) + items
        def func(obj):
            return tuple((obj[i] for i in items))
        self._call = func

def __init__(self, name, /, *args, **kwargs):
    self._name = name
    if not isinstance(self._name, str):
        raise TypeError('method name must be a string')
    self._args = args
    self._kwargs = kwargs

def __repr__(self):
    args = [repr(self._name)]
    args.extend(map(repr, self._args))
    args.extend(('%s=%r' % (k, v) for k, v in self._kwargs.items()))
    return '%s.%s(%s)' % (self.__class__.__module__, self.__class__.__name__, ', '.join(args))

def __reduce__(self):
    if not self._kwargs:
        return (self.__class__, (self._name,) + self._args)
    else:
        from functools import partial
        return (partial(self.__class__, self._name, **self._kwargs), self._args)

def func(obj):
    for name in names:
        obj = getattr(obj, name)
    return obj

def _parse_num(val, type):
    if val[:2].lower() == '0x':
        radix = 16
    elif val[:2].lower() == '0b':
        radix = 2
        val = val[2:] or '0'
    elif val[:1] == '0':
        radix = 8
    else:
        radix = 10
    return type(val, radix)

def check_builtin(option, opt, value):
    cvt, what = _builtin_cvt[option.type]
    try:
        return cvt(value)
    except ValueError:
        raise OptionValueError(_('option %s: invalid %s value: %r') % (opt, what, value))

def check_choice(option, opt, value):
    if value in option.choices:
        return value
    else:
        choices = ', '.join(map(repr, option.choices))
        raise OptionValueError(_('option %s: invalid choice: %r (choose from %s)') % (opt, value, choices))

def _match_abbrev(s, wordmap):
    """_match_abbrev(s : string, wordmap : {string : Option}) -> string

    Return the string key in 'wordmap' for which 's' is an unambiguous
    abbreviation.  If 's' is found to be ambiguous or doesn't match any of
    'words', raise BadOptionError."""
    if s in wordmap:
        return s
    else:
        possibilities = [word for word in wordmap.keys() if word.startswith(s)]
        if len(possibilities) == 1:
            return possibilities[0]
        elif not possibilities:
            raise BadOptionError(s)
        else:
            possibilities.sort()
            raise AmbiguousOptionError(s, possibilities)

def __init__(self, msg, option):
    self.msg = msg
    self.option_id = str(option)

def __str__(self):
    if self.option_id:
        return 'option %s: %s' % (self.option_id, self.msg)
    else:
        return self.msg

def __init__(self, opt_str, possibilities):
    BadOptionError.__init__(self, opt_str)
    self.possibilities = possibilities

def set_short_opt_delimiter(self, delim):
    if delim not in ('', ' '):
        raise ValueError('invalid metavar delimiter for short options: %r' % delim)
    self._short_opt_fmt = '%s' + delim + '%s'

def set_long_opt_delimiter(self, delim):
    if delim not in ('=', ' '):
        raise ValueError('invalid metavar delimiter for long options: %r' % delim)
    self._long_opt_fmt = '%s' + delim + '%s'

def indent(self):
    self.current_indent += self.indent_increment
    self.level += 1

def _format_text(self, text):
    """Format a paragraph of free-form text for inclusion in the
    help output at the current indentation level."""
    text_width = max(self.width - self.current_indent, 11)
    indent = ' ' * self.current_indent
    return textwrap.fill(text, text_width, initial_indent=indent, subsequent_indent=indent)

def format_description(self, description):
    if description:
        return self._format_text(description) + '\n'
    else:
        return ''

def format_epilog(self, epilog):
    if epilog:
        return '\n' + self._format_text(epilog) + '\n'
    else:
        return ''

def expand_default(self, option):
    if self.parser is None or not self.default_tag:
        return option.help
    default_value = self.parser.defaults.get(option.dest)
    if default_value is NO_DEFAULT or default_value is None:
        default_value = self.NO_DEFAULT_VALUE
    return option.help.replace(self.default_tag, str(default_value))

def format_option(self, option):
    result = []
    opts = self.option_strings[option]
    opt_width = self.help_position - self.current_indent - 2
    if len(opts) > opt_width:
        opts = '%*s%s\n' % (self.current_indent, '', opts)
        indent_first = self.help_position
    else:
        opts = '%*s%-*s  ' % (self.current_indent, '', opt_width, opts)
        indent_first = 0
    result.append(opts)
    if option.help:
        help_text = self.expand_default(option)
        help_lines = textwrap.wrap(help_text, self.help_width)
        result.append('%*s%s\n' % (indent_first, '', help_lines[0]))
        result.extend(['%*s%s\n' % (self.help_position, '', line) for line in help_lines[1:]])
    elif opts[-1] != '\n':
        result.append('\n')
    return ''.join(result)

def format_option_strings(self, option):
    """Return a comma-separated list of option strings & metavariables."""
    if option.takes_value():
        metavar = option.metavar or option.dest.upper()
        short_opts = [self._short_opt_fmt % (sopt, metavar) for sopt in option._short_opts]
        long_opts = [self._long_opt_fmt % (lopt, metavar) for lopt in option._long_opts]
    else:
        short_opts = option._short_opts
        long_opts = option._long_opts
    if self.short_first:
        opts = short_opts + long_opts
    else:
        opts = long_opts + short_opts
    return ', '.join(opts)

def _check_opt_strings(self, opts):
    opts = [opt for opt in opts if opt]
    if not opts:
        raise TypeError('at least one option string must be supplied')
    return opts

def _set_opt_strings(self, opts):
    for opt in opts:
        if len(opt) < 2:
            raise OptionError('invalid option string %r: must be at least two characters long' % opt, self)
        elif len(opt) == 2:
            if not (opt[0] == '-' and opt[1] != '-'):
                raise OptionError('invalid short option string %r: must be of the form -x, (x any non-dash char)' % opt, self)
            self._short_opts.append(opt)
        else:
            if not (opt[0:2] == '--' and opt[2] != '-'):
                raise OptionError('invalid long option string %r: must start with --, followed by non-dash' % opt, self)
            self._long_opts.append(opt)

def _set_attrs(self, attrs):
    for attr in self.ATTRS:
        if attr in attrs:
            setattr(self, attr, attrs[attr])
            del attrs[attr]
        elif attr == 'default':
            setattr(self, attr, NO_DEFAULT)
        else:
            setattr(self, attr, None)
    if attrs:
        attrs = sorted(attrs.keys())
        raise OptionError('invalid keyword arguments: %s' % ', '.join(attrs), self)

def _check_type(self):
    if self.type is None:
        if self.action in self.ALWAYS_TYPED_ACTIONS:
            if self.choices is not None:
                self.type = 'choice'
            else:
                self.type = 'string'
    else:
        if isinstance(self.type, type):
            self.type = self.type.__name__
        if self.type == 'str':
            self.type = 'string'
        if self.type not in self.TYPES:
            raise OptionError('invalid option type: %r' % self.type, self)
        if self.action not in self.TYPED_ACTIONS:
            raise OptionError('must not supply a type for action %r' % self.action, self)

def _check_choice(self):
    if self.type == 'choice':
        if self.choices is None:
            raise OptionError("must supply a list of choices for type 'choice'", self)
        elif not isinstance(self.choices, (tuple, list)):
            raise OptionError("choices must be a list of strings ('%s' supplied)" % str(type(self.choices)).split("'")[1], self)
    elif self.choices is not None:
        raise OptionError('must not supply choices for type %r' % self.type, self)

def _check_dest(self):
    takes_value = self.action in self.STORE_ACTIONS or self.type is not None
    if self.dest is None and takes_value:
        if self._long_opts:
            self.dest = self._long_opts[0][2:].replace('-', '_')
        else:
            self.dest = self._short_opts[0][1]

def _check_const(self):
    if self.action not in self.CONST_ACTIONS and self.const is not None:
        raise OptionError("'const' must not be supplied for action %r" % self.action, self)

def _check_nargs(self):
    if self.action in self.TYPED_ACTIONS:
        if self.nargs is None:
            self.nargs = 1
    elif self.nargs is not None:
        raise OptionError("'nargs' must not be supplied for action %r" % self.action, self)

def _check_callback(self):
    if self.action == 'callback':
        if not callable(self.callback):
            raise OptionError('callback not callable: %r' % self.callback, self)
        if self.callback_args is not None and (not isinstance(self.callback_args, tuple)):
            raise OptionError('callback_args, if supplied, must be a tuple: not %r' % self.callback_args, self)
        if self.callback_kwargs is not None and (not isinstance(self.callback_kwargs, dict)):
            raise OptionError('callback_kwargs, if supplied, must be a dict: not %r' % self.callback_kwargs, self)
    else:
        if self.callback is not None:
            raise OptionError('callback supplied (%r) for non-callback option' % self.callback, self)
        if self.callback_args is not None:
            raise OptionError('callback_args supplied for non-callback option', self)
        if self.callback_kwargs is not None:
            raise OptionError('callback_kwargs supplied for non-callback option', self)

def get_opt_string(self):
    if self._long_opts:
        return self._long_opts[0]
    else:
        return self._short_opts[0]

def check_value(self, opt, value):
    checker = self.TYPE_CHECKER.get(self.type)
    if checker is None:
        return value
    else:
        return checker(self, opt, value)

def convert_value(self, opt, value):
    if value is not None:
        if self.nargs == 1:
            return self.check_value(opt, value)
        else:
            return tuple([self.check_value(opt, v) for v in value])

def process(self, opt, value, values, parser):
    value = self.convert_value(opt, value)
    return self.take_action(self.action, self.dest, opt, value, values, parser)

def take_action(self, action, dest, opt, value, values, parser):
    if action == 'store':
        setattr(values, dest, value)
    elif action == 'store_const':
        setattr(values, dest, self.const)
    elif action == 'store_true':
        setattr(values, dest, True)
    elif action == 'store_false':
        setattr(values, dest, False)
    elif action == 'append':
        values.ensure_value(dest, []).append(value)
    elif action == 'append_const':
        values.ensure_value(dest, []).append(self.const)
    elif action == 'count':
        setattr(values, dest, values.ensure_value(dest, 0) + 1)
    elif action == 'callback':
        args = self.callback_args or ()
        kwargs = self.callback_kwargs or {}
        self.callback(self, opt, value, parser, *args, **kwargs)
    elif action == 'help':
        parser.print_help()
        parser.exit()
    elif action == 'version':
        parser.print_version()
        parser.exit()
    else:
        raise ValueError('unknown action %r' % self.action)
    return 1

def __init__(self, defaults=None):
    if defaults:
        for attr, val in defaults.items():
            setattr(self, attr, val)

def __eq__(self, other):
    if isinstance(other, Values):
        return self.__dict__ == other.__dict__
    elif isinstance(other, dict):
        return self.__dict__ == other
    else:
        return NotImplemented

def _update_careful(self, dict):
    """Update the option values from an arbitrary dictionary, but only
    use keys from dict that already have a corresponding attribute
    in self.  Any keys in dict without a corresponding attribute
    are silently ignored."""
    for attr in dir(self):
        if attr in dict:
            dval = dict[attr]
            if dval is not None:
                setattr(self, attr, dval)

def _update(self, dict, mode):
    if mode == 'careful':
        self._update_careful(dict)
    elif mode == 'loose':
        self._update_loose(dict)
    else:
        raise ValueError('invalid update mode: %r' % mode)

def read_file(self, filename, mode='careful'):
    vars = {}
    exec(open(filename).read(), vars)
    self._update(vars, mode)

def ensure_value(self, attr, value):
    if not hasattr(self, attr) or getattr(self, attr) is None:
        setattr(self, attr, value)
    return getattr(self, attr)

def _create_option_mappings(self):
    self._short_opt = {}
    self._long_opt = {}
    self.defaults = {}

def set_conflict_handler(self, handler):
    if handler not in ('error', 'resolve'):
        raise ValueError('invalid conflict_resolution value %r' % handler)
    self.conflict_handler = handler

def _check_conflict(self, option):
    conflict_opts = []
    for opt in option._short_opts:
        if opt in self._short_opt:
            conflict_opts.append((opt, self._short_opt[opt]))
    for opt in option._long_opts:
        if opt in self._long_opt:
            conflict_opts.append((opt, self._long_opt[opt]))
    if conflict_opts:
        handler = self.conflict_handler
        if handler == 'error':
            raise OptionConflictError('conflicting option string(s): %s' % ', '.join([co[0] for co in conflict_opts]), option)
        elif handler == 'resolve':
            for opt, c_option in conflict_opts:
                if opt.startswith('--'):
                    c_option._long_opts.remove(opt)
                    del self._long_opt[opt]
                else:
                    c_option._short_opts.remove(opt)
                    del self._short_opt[opt]
                if not (c_option._short_opts or c_option._long_opts):
                    c_option.container.option_list.remove(c_option)

def add_option(self, *args, **kwargs):
    """add_option(Option)
    add_option(opt_str, ..., kwarg=val, ...)"""
    if isinstance(args[0], str):
        option = self.option_class(*args, **kwargs)
    elif len(args) == 1 and (not kwargs):
        option = args[0]
        if not isinstance(option, Option):
            raise TypeError('not an Option instance: %r' % option)
    else:
        raise TypeError('invalid arguments')
    self._check_conflict(option)
    self.option_list.append(option)
    option.container = self
    for opt in option._short_opts:
        self._short_opt[opt] = option
    for opt in option._long_opts:
        self._long_opt[opt] = option
    if option.dest is not None:
        if option.default is not NO_DEFAULT:
            self.defaults[option.dest] = option.default
        elif option.dest not in self.defaults:
            self.defaults[option.dest] = None
    return option

def remove_option(self, opt_str):
    option = self._short_opt.get(opt_str)
    if option is None:
        option = self._long_opt.get(opt_str)
    if option is None:
        raise ValueError('no such option %r' % opt_str)
    for opt in option._short_opts:
        del self._short_opt[opt]
    for opt in option._long_opts:
        del self._long_opt[opt]
    option.container.option_list.remove(option)

def format_option_help(self, formatter):
    if not self.option_list:
        return ''
    result = []
    for option in self.option_list:
        if not option.help is SUPPRESS_HELP:
            result.append(formatter.format_option(option))
    return ''.join(result)

def format_help(self, formatter):
    result = []
    if self.description:
        result.append(self.format_description(formatter))
    if self.option_list:
        result.append(self.format_option_help(formatter))
    return '\n'.join(result)

def _create_option_list(self):
    self.option_list = []
    self._share_option_mappings(self.parser)

def _populate_option_list(self, option_list, add_help=True):
    if self.standard_option_list:
        self.add_options(self.standard_option_list)
    if option_list:
        self.add_options(option_list)
    if self.version:
        self._add_version_option()
    if add_help:
        self._add_help_option()

def set_usage(self, usage):
    if usage is None:
        self.usage = _('%prog [options]')
    elif usage is SUPPRESS_USAGE:
        self.usage = None
    elif usage.lower().startswith('usage: '):
        self.usage = usage[7:]
    else:
        self.usage = usage

def _get_all_options(self):
    options = self.option_list[:]
    for group in self.option_groups:
        options.extend(group.option_list)
    return options

def get_default_values(self):
    if not self.process_default_values:
        return Values(self.defaults)
    defaults = self.defaults.copy()
    for option in self._get_all_options():
        default = defaults.get(option.dest)
        if isinstance(default, str):
            opt_str = option.get_opt_string()
            defaults[option.dest] = option.check_value(opt_str, default)
    return Values(defaults)

def add_option_group(self, *args, **kwargs):
    if isinstance(args[0], str):
        group = OptionGroup(self, *args, **kwargs)
    elif len(args) == 1 and (not kwargs):
        group = args[0]
        if not isinstance(group, OptionGroup):
            raise TypeError('not an OptionGroup instance: %r' % group)
        if group.parser is not self:
            raise ValueError('invalid OptionGroup (wrong parser)')
    else:
        raise TypeError('invalid arguments')
    self.option_groups.append(group)
    return group

def get_option_group(self, opt_str):
    option = self._short_opt.get(opt_str) or self._long_opt.get(opt_str)
    if option and option.container is not self:
        return option.container
    return None

def _get_args(self, args):
    if args is None:
        return sys.argv[1:]
    else:
        return args[:]

def _process_args(self, largs, rargs, values):
    """_process_args(largs : [string],
                     rargs : [string],
                     values : Values)

    Process command-line arguments and populate 'values', consuming
    options and arguments from 'rargs'.  If 'allow_interspersed_args' is
    false, stop at the first non-option argument.  If true, accumulate any
    interspersed non-option arguments in 'largs'."""
    while rargs:
        arg = rargs[0]
        if arg == '--':
            del rargs[0]
            return
        elif arg[0:2] == '--':
            self._process_long_opt(rargs, values)
        elif arg[:1] == '-' and len(arg) > 1:
            self._process_short_opts(rargs, values)
        elif self.allow_interspersed_args:
            largs.append(arg)
            del rargs[0]
        else:
            return

def _match_long_opt(self, opt):
    """_match_long_opt(opt : string) -> string

    Determine which long option string 'opt' matches, ie. which one
    it is an unambiguous abbreviation for.  Raises BadOptionError if
    'opt' doesn't unambiguously match any long option string."""
    return _match_abbrev(opt, self._long_opt)

def _process_long_opt(self, rargs, values):
    arg = rargs.pop(0)
    if '=' in arg:
        opt, next_arg = arg.split('=', 1)
        rargs.insert(0, next_arg)
        had_explicit_value = True
    else:
        opt = arg
        had_explicit_value = False
    opt = self._match_long_opt(opt)
    option = self._long_opt[opt]
    if option.takes_value():
        nargs = option.nargs
        if len(rargs) < nargs:
            self.error(ngettext('%(option)s option requires %(number)d argument', '%(option)s option requires %(number)d arguments', nargs) % {'option': opt, 'number': nargs})
        elif nargs == 1:
            value = rargs.pop(0)
        else:
            value = tuple(rargs[0:nargs])
            del rargs[0:nargs]
    elif had_explicit_value:
        self.error(_('%s option does not take a value') % opt)
    else:
        value = None
    option.process(opt, value, values, self)

def _process_short_opts(self, rargs, values):
    arg = rargs.pop(0)
    stop = False
    i = 1
    for ch in arg[1:]:
        opt = '-' + ch
        option = self._short_opt.get(opt)
        i += 1
        if not option:
            raise BadOptionError(opt)
        if option.takes_value():
            if i < len(arg):
                rargs.insert(0, arg[i:])
                stop = True
            nargs = option.nargs
            if len(rargs) < nargs:
                self.error(ngettext('%(option)s option requires %(number)d argument', '%(option)s option requires %(number)d arguments', nargs) % {'option': opt, 'number': nargs})
            elif nargs == 1:
                value = rargs.pop(0)
            else:
                value = tuple(rargs[0:nargs])
                del rargs[0:nargs]
        else:
            value = None
        option.process(opt, value, values, self)
        if stop:
            break

def get_prog_name(self):
    if self.prog is None:
        return os.path.basename(sys.argv[0])
    else:
        return self.prog

def exit(self, status=0, msg=None):
    if msg:
        sys.stderr.write(msg)
    sys.exit(status)

def get_usage(self):
    if self.usage:
        return self.formatter.format_usage(self.expand_prog_name(self.usage))
    else:
        return ''

def get_version(self):
    if self.version:
        return self.expand_prog_name(self.version)
    else:
        return ''

def format_option_help(self, formatter=None):
    if formatter is None:
        formatter = self.formatter
    formatter.store_option_strings(self)
    result = []
    result.append(formatter.format_heading(_('Options')))
    formatter.indent()
    if self.option_list:
        result.append(OptionContainer.format_option_help(self, formatter))
        result.append('\n')
    for group in self.option_groups:
        result.append(group.format_help(formatter))
        result.append('\n')
    formatter.dedent()
    return ''.join(result[:-1])

def format_help(self, formatter=None):
    if formatter is None:
        formatter = self.formatter
    result = []
    if self.usage:
        result.append(self.get_usage() + '\n')
    if self.description:
        result.append(self.format_description(formatter) + '\n')
    result.append(self.format_option_help(formatter))
    result.append(self.format_epilog(formatter))
    return ''.join(result)

def ngettext(singular, plural, n):
    if n == 1:
        return singular
    return plural

def _get_exports_list(module):
    try:
        return list(module.__all__)
    except AttributeError:
        return [n for n in dir(module) if n[0] != '_']

def makedirs(name, mode=511, exist_ok=False):
    """makedirs(name [, mode=0o777][, exist_ok=False])

    Super-mkdir; create a leaf directory and all intermediate ones.  Works like
    mkdir, except that any intermediate path segment (not just the rightmost)
    will be created if it does not exist. If the target directory already
    exists, raise an OSError if exist_ok is False. Otherwise no exception is
    raised.  This is recursive."""
    head, tail = path.split(name)
    if not tail:
        head, tail = path.split(head)
    if head and tail and (not path.exists(head)):
        try:
            makedirs(head, exist_ok=exist_ok)
        except FileExistsError:
            pass
        cdir = curdir
        if isinstance(tail, bytes):
            cdir = bytes(curdir, 'ASCII')
        if tail == cdir:
            return
    try:
        mkdir(name, mode)
    except OSError:
        if not exist_ok or not path.isdir(name):
            raise

def get_exec_path(env=None):
    """Returns the sequence of directories that will be searched for the
    named executable (similar to a shell) when launching a process.

    *env* must be an environment variable dict or None.  If *env* is None,
    os.environ will be used."""
    import warnings
    if env is None:
        env = environ
    with warnings.catch_warnings():
        warnings.simplefilter('ignore', BytesWarning)
        try:
            path_list = env.get('PATH')
        except TypeError:
            path_list = None
        if supports_bytes_environ:
            try:
                path_listb = env[b'PATH']
            except (KeyError, TypeError):
                pass
            else:
                if path_list is not None:
                    raise ValueError("env cannot contain 'PATH' and b'PATH' keys")
                path_list = path_listb
            if path_list is not None and isinstance(path_list, bytes):
                path_list = fsdecode(path_list)
    if path_list is None:
        path_list = defpath
    return path_list.split(pathsep)

def _createenviron():
    if name == 'nt':
        def check_str(value):
            if not isinstance(value, str):
                raise TypeError('str expected, not %s' % type(value).__name__)
            return value
        encode = check_str
        decode = str
        def encodekey(key):
            return encode(key).upper()
        data = {}
        for key, value in environ.items():
            data[encodekey(key)] = value
