    except OSError as e:
        if not _ignore_error(e):
            raise
        return False
    except ValueError:
        return False
    return True

def is_dir(self):
    """Whether this path is a directory."""
    try:
        return S_ISDIR(self.stat().st_mode)
    except OSError as e:
        if not _ignore_error(e):
            raise
        return False
    except ValueError:
        return False

def is_file(self):
    """Whether this path is a regular file (also True for symlinks pointing
    to regular files)."""
    try:
        return S_ISREG(self.stat().st_mode)
    except OSError as e:
        if not _ignore_error(e):
            raise
        return False
    except ValueError:
        return False

def is_mount(self):
    """Check if this path is a mount point"""
    return self._flavour.ismount(self)

def is_symlink(self):
