def samefile(self, other_path):
    """Return whether other_path is the same or not as this file
    (as returned by os.path.samefile())."""
    st = self.stat()
    try:
        other_st = other_path.stat()
    except AttributeError:
        other_st = self.with_segments(other_path).stat()
    return self._flavour.samestat(st, other_st)

def open(self, mode='r', buffering=-1, encoding=None, errors=None, newline=None):
    """Open the file pointed to by this path and return a file object, as
    the built-in open() function does."""
    if 'b' not in mode:
        encoding = io.text_encoding(encoding)
    return io.open(self, mode, buffering, encoding, errors, newline)

def read_bytes(self):
    """Open the file in bytes mode, read it, and close the file."""
    with self.open(mode='rb') as f:
        return f.read()

def read_text(self, encoding=None, errors=None):
    """Open the file in text mode, read it, and close the file."""
    encoding = io.text_encoding(encoding)
    with self.open(mode='r', encoding=encoding, errors=errors) as f:
        return f.read()

def write_text(self, data, encoding=None, errors=None, newline=None):
    """Open the file in text mode, write to it, and close the file."""
    if not isinstance(data, str):
        raise TypeError('data must be str, not %s' % data.__class__.__name__)
    encoding = io.text_encoding(encoding)
    with self.open(mode='w', encoding=encoding, errors=errors, newline=newline) as f:
        return f.write(data)

def iterdir(self):
    """Yield path objects of the directory contents.

    The children are yielded in arbitrary order, and the
    special entries '.' and '..' are not included."""
    for name in os.listdir(self):
        yield self._make_child_relpath(name)

def glob(self, pattern, *, case_sensitive=None):
    """Iterate over this subtree and yield all existing files (of any
    kind, including directories) matching the given relative pattern."""
    sys.audit('pathlib.Path.glob', self, pattern)
    if not pattern:
        raise ValueError('Unacceptable pattern: {!r}'.format(pattern))
    drv, root, pattern_parts = self._parse_path(pattern)
    if drv or root:
        raise NotImplementedError('Non-relative patterns are unsupported')
    if pattern[-1] in (self._flavour.sep, self._flavour.altsep):
        pattern_parts.append('')
    selector = _make_selector(tuple(pattern_parts), self._flavour, case_sensitive)
    for p in selector.select_from(self):
        yield p

def rglob(self, pattern, *, case_sensitive=None):
    """Recursively yield all existing files (of any kind, including
    directories) matching the given relative pattern, anywhere in
    this subtree."""
    sys.audit('pathlib.Path.rglob', self, pattern)
    drv, root, pattern_parts = self._parse_path(pattern)
    if drv or root:
        raise NotImplementedError('Non-relative patterns are unsupported')
    if pattern and pattern[-1] in (self._flavour.sep, self._flavour.altsep):
        pattern_parts.append('')
    selector = _make_selector(('**',) + tuple(pattern_parts), self._flavour, case_sensitive)
    for p in selector.select_from(self):
        yield p

def walk(self, top_down=True, on_error=None, follow_symlinks=False):
    """Walk the directory tree from this directory, similar to os.walk()."""
    sys.audit('pathlib.Path.walk', self, on_error, follow_symlinks)
    paths = [self]
    while paths:
        path = paths.pop()
        if isinstance(path, tuple):
            yield path
            continue
        try:
            scandir_it = path._scandir()
        except OSError as error:
            if on_error is not None:
                on_error(error)
            continue
        with scandir_it:
            dirnames = []
            filenames = []
            for entry in scandir_it:
                try:
                    is_dir = entry.is_dir(follow_symlinks=follow_symlinks)
                except OSError:
                    is_dir = False
                if is_dir:
                    dirnames.append(entry.name)
                else:
                    filenames.append(entry.name)
        if top_down:
            yield (path, dirnames, filenames)
        else:
            paths.append((path, dirnames, filenames))
        paths += [path._make_child_relpath(d) for d in reversed(dirnames)]

def __init__(self, *args, **kwargs):
    if kwargs:
        msg = 'support for supplying keyword arguments to pathlib.PurePath is deprecated and scheduled for removal in Python {remove}'
        warnings._deprecated('pathlib.PurePath(**kwargs)', msg, remove=(3, 14))
    super().__init__(*args)

def __new__(cls, *args, **kwargs):
    if cls is Path:
        cls = WindowsPath if os.name == 'nt' else PosixPath
    return object.__new__(cls)

def __enter__(self):
    warnings.warn('pathlib.Path.__enter__() is deprecated and scheduled for removal in Python 3.13; Path objects as a context manager is a no-op', DeprecationWarning, stacklevel=2)
    return self

@classmethod
def cwd(cls):
    """Return a new path pointing to the current working directory."""
    return cls().absolute()

@classmethod
def home(cls):
    """Return a new path pointing to the user's home directory (as
    returned by os.path.expanduser('~'))."""
    return cls('~').expanduser()

def absolute(self):
    """Return an absolute version of this path by prepending the current
    working directory. No normalization or symlink resolution is performed.

    Use resolve() to get the canonical path to a file."""
    if self.is_absolute():
        return self
    elif self.drive:
        cwd = self._flavour.abspath(self.drive)
    else:
        cwd = os.getcwd()
        if not self.root and (not self._tail):
            result = self.with_segments(cwd)
            result._str = cwd
            return result
    return self.with_segments(cwd, self)

def resolve(self, strict=False):
    """Make the path absolute, resolving all symlinks on the way and also
    normalizing it."""
    def check_eloop(e):
        winerror = getattr(e, 'winerror', 0)
        if e.errno == ELOOP or winerror == _WINERROR_CANT_RESOLVE_FILENAME:
            raise RuntimeError('Symlink loop from %r' % e.filename)
    try:
        s = self._flavour.realpath(self, strict=strict)
    except OSError as e:
        check_eloop(e)
        raise
    p = self.with_segments(s)
    if not strict:
        try:
            p.stat()
        except OSError as e:
            check_eloop(e)
    return p

def owner(self):
    """Return the login name of the file owner."""
    try:
        import pwd
        return pwd.getpwuid(self.stat().st_uid).pw_name
    except ImportError:
        raise NotImplementedError('Path.owner() is unsupported on this system')

def group(self):
    """Return the group name of the file gid."""
    try:
        import grp
        return grp.getgrgid(self.stat().st_gid).gr_name
    except ImportError:
        raise NotImplementedError('Path.group() is unsupported on this system')

def readlink(self):
    """Return the path to which the symbolic link points."""
    if not hasattr(os, 'readlink'):
        raise NotImplementedError('os.readlink() not available on this system')
    return self.with_segments(os.readlink(self))

def touch(self, mode=438, exist_ok=True):
    """Create this file with the given access mode, if it doesn't exist."""
    if exist_ok:
        try:
            os.utime(self, None)
        except OSError:
            pass
        else:
            return
    flags = os.O_CREAT | os.O_WRONLY
    if not exist_ok:
        flags |= os.O_EXCL
    fd = os.open(self, flags, mode)
    os.close(fd)

def mkdir(self, mode=511, parents=False, exist_ok=False):
    """Create a new directory at this given path."""
    try:
        os.mkdir(self, mode)
    except FileNotFoundError:
        if not parents or self.parent == self:
            raise
        self.parent.mkdir(parents=True, exist_ok=True)
        self.mkdir(mode, parents=False, exist_ok=exist_ok)
    except OSError:
        if not exist_ok or not self.is_dir():
            raise

def chmod(self, mode, *, follow_symlinks=True):
    """Change the permissions of the path, like os.chmod()."""
    os.chmod(self, mode, follow_symlinks=follow_symlinks)

def unlink(self, missing_ok=False):
    """Remove this file or link.
    If the path is a directory, use rmdir() instead."""
    try:
        os.unlink(self)
    except FileNotFoundError:
        if not missing_ok:
            raise

def rmdir(self):
    """Remove this directory.  The directory must be empty."""
    os.rmdir(self)

def symlink_to(self, target, target_is_directory=False):
    """Make this path a symlink pointing to the target path.
    Note the order of arguments (link, target) is the reverse of os.symlink."""
    if not hasattr(os, 'symlink'):
        raise NotImplementedError('os.symlink() not available on this system')
    os.symlink(target, self, target_is_directory)

def hardlink_to(self, target):
    """Make this path a hard link pointing to the same file as *target*.

    Note the order of arguments (self, target) is the reverse of os.link's."""
    if not hasattr(os, 'link'):
        raise NotImplementedError('os.link() not available on this system')
    os.link(target, self)

def expanduser(self):
    """Return a new path with expanded ~ and ~user constructs
    (as returned by os.path.expanduser)"""
    if not (self.drive or self.root) and self._tail and (self._tail[0][:1] == '~'):
        homedir = self._flavour.expanduser(self._tail[0])
        if homedir[:1] == '~':
            raise RuntimeError('Could not determine home directory.')
        drv, root, tail = self._parse_path(homedir)
        return self._from_parsed_parts(drv, root, tail + self._tail[1:])
    return self

def check_eloop(e):
    winerror = getattr(e, 'winerror', 0)
    if e.errno == ELOOP or winerror == _WINERROR_CANT_RESOLVE_FILENAME:
        raise RuntimeError('Symlink loop from %r' % e.filename)

def find_function(funcname, filename):
    cre = re.compile('def\\s+%s(\\s*\\[.+\\])?\\s*[(]' % re.escape(funcname))
    try:
        fp = tokenize.open(filename)
    except OSError:
        return None
    with fp:
        for lineno, line in enumerate(fp, start=1):
            if cre.match(line):
                return (funcname, filename, lineno)
    return None

def lasti2lineno(code, lasti):
    linestarts = list(dis.findlinestarts(code))
    linestarts.reverse()
    for i, lineno in linestarts:
        if lasti >= i:
            return lineno
    return 0

def runeval(expression, globals=None, locals=None):
    """Evaluate the *expression* (given as a string or a code object)
    under debugger control.

    When runeval() returns, it returns the value of the expression.
    Otherwise this function is similar to run()."""
    return Pdb().runeval(expression, globals, locals)

def pm():
    """Enter post-mortem debugging of the traceback found in sys.last_traceback."""
    if hasattr(sys, 'last_exc'):
        tb = sys.last_exc.__traceback__
    else:
        tb = sys.last_traceback
    post_mortem(tb)

def help():
    import pydoc
    pydoc.pager(__doc__)

def check(self):
    if not os.path.exists(self):
        print('Error:', self.orig, 'does not exist')
        sys.exit(1)
    if os.path.isdir(self):
        print('Error:', self.orig, 'is a directory')
        sys.exit(1)
    sys.path[0] = os.path.dirname(self)

@property
def filename(self):
    return self

@property
def namespace(self):
    return dict(__name__='__main__', __file__=self, __builtins__=__builtins__, __spec__=None)

@property
def code(self):
    with io.open_code(self) as fp:
        return f"exec(compile({fp.read()!r}, {self!r}, 'exec'))"

def check(self):
    try:
        self._details
    except ImportError as e:
        print(f'ImportError: {e}')
        sys.exit(1)
    except Exception:
        traceback.print_exc()
        sys.exit(1)

@functools.cached_property
def _details(self):
    import runpy
    return runpy._get_module_details(self)

@property
def filename(self):
    return self.code.co_filename

@property
def code(self):
    name, spec, code = self._details
    return code

@property
def _spec(self):
    name, spec, code = self._details
    return spec

@property
def namespace(self):
    return dict(__name__='__main__', __file__=os.path.normcase(os.path.abspath(self.filename)), __package__=self._spec.parent, __loader__=self._spec.loader, __spec__=self._spec, __builtins__=__builtins__)

def __init__(self, completekey='tab', stdin=None, stdout=None, skip=None, nosigint=False, readrc=True):
    bdb.Bdb.__init__(self, skip=skip)
    cmd.Cmd.__init__(self, completekey, stdin, stdout)
    sys.audit('pdb.Pdb')
    if stdout:
        self.use_rawinput = 0
    self.prompt = '(Pdb) '
    self.aliases = {}
    self.displaying = {}
    self.mainpyfile = ''
    self._wait_for_mainpyfile = False
    self.tb_lineno = {}
    try:
        import readline
        readline.set_completer_delims(' \t\n`@#$%^&*()=+[{]}\\|;:\'",<>?')
    except ImportError:
        pass
    self.allow_kbdint = False
    self.nosigint = nosigint
    self.rcLines = []
    if readrc:
        try:
            with open(os.path.expanduser('~/.pdbrc'), encoding='utf-8') as rcFile:
                self.rcLines.extend(rcFile)
        except OSError:
            pass
        try:
            with open('.pdbrc', encoding='utf-8') as rcFile:
                self.rcLines.extend(rcFile)
        except OSError:
            pass
    self.commands = {}
    self.commands_doprompt = {}
    self.commands_silent = {}
    self.commands_defining = False
    self.commands_bnum = None

def sigint_handler(self, signum, frame):
    if self.allow_kbdint:
        raise KeyboardInterrupt
    self.message("\nProgram interrupted. (Use 'cont' to resume).")
    self.set_step()
    self.set_trace(frame)

def reset(self):
    bdb.Bdb.reset(self)
    self.forget()

def forget(self):
    self.lineno = None
    self.stack = []
    self.curindex = 0
    if hasattr(self, 'curframe') and self.curframe:
        self.curframe.f_globals.pop('__pdb_convenience_variables', None)
    self.curframe = None
    self.curframe_locals = {}
    self.tb_lineno.clear()

def user_call(self, frame, argument_list):
    """This method is called when there is the remote possibility
    that we ever need to stop in this function."""
    if self._wait_for_mainpyfile:
        return
    if self.stop_here(frame):
        self.message('--Call--')
        self.interaction(frame, None)

def user_line(self, frame):
    """This function is called when we stop or break at this line."""
    if self._wait_for_mainpyfile:
        if self.mainpyfile != self.canonic(frame.f_code.co_filename):
            return
        self._wait_for_mainpyfile = False
    if self.bp_commands(frame):
        self.interaction(frame, None)

def _cmdloop(self):
    while True:
        try:
            self.allow_kbdint = True
            self.cmdloop()
            self.allow_kbdint = False
            break
        except KeyboardInterrupt:
            self.message('--KeyboardInterrupt--')

def _show_display(self):
    displaying = self.displaying.get(self.curframe)
    if displaying:
        for expr, oldvalue in displaying.items():
            newvalue = self._getval_except(expr)
            if newvalue is not oldvalue and newvalue != oldvalue:
                displaying[expr] = newvalue
                self.message('display %s: %s  [old: %s]' % (expr, self._safe_repr(newvalue, expr), self._safe_repr(oldvalue, expr)))

def displayhook(self, obj):
    """Custom displayhook for the exec in default(), which prevents
    assignment of the _ variable in the builtins."""
    if obj is not None:
        self.message(repr(obj))

def _replace_convenience_variables(self, line):
    """Replace the convenience variables in 'line' with their values.
    e.g. $foo is replaced by __pdb_convenience_variables["foo"].
    Note: such pattern in string literals will be skipped"""
    if '$' not in line:
        return line
    dollar_start = dollar_end = -1
    replace_variables = []
    try:
        for t in tokenize.generate_tokens(io.StringIO(line).readline):
            token_type, token_string, start, end, _ = t
            if token_type == token.OP and token_string == '$':
                dollar_start, dollar_end = (start, end)
            elif start == dollar_end and token_type == token.NAME:
                replace_variables.append((dollar_start[1], end[1], token_string))
    except tokenize.TokenError:
        return line
    if not replace_variables:
        return line
    last_end = 0
    line_pieces = []
    for start, end, name in replace_variables:
        line_pieces.append(line[last_end:start] + f'__pdb_convenience_variables["{name}"]')
        last_end = end
    line_pieces.append(line[last_end:])
    return ''.join(line_pieces)

def onecmd(self, line):
    """Interpret the argument as though it had been typed in response
    to the prompt.

    Checks whether this line is typed at the normal prompt or in
    a breakpoint command list definition."""
    if not self.commands_defining:
        if line.startswith('_pdbcmd'):
            command, arg, line = self.parseline(line)
            if hasattr(self, command):
                return getattr(self, command)(arg)
        return cmd.Cmd.onecmd(self, line)
    else:
        return self.handle_command_def(line)

def handle_command_def(self, line):
    """Handles one command line during command list definition."""
    cmd, arg, line = self.parseline(line)
    if not cmd:
        return False
    if cmd == 'silent':
        self.commands_silent[self.commands_bnum] = True
        return False
    elif cmd == 'end':
        return True
    cmdlist = self.commands[self.commands_bnum]
    if arg:
        cmdlist.append(cmd + ' ' + arg)
    else:
        cmdlist.append(cmd)
    try:
        func = getattr(self, 'do_' + cmd)
    except AttributeError:
        func = self.default
    if func.__name__ in self.commands_resuming:
        self.commands_doprompt[self.commands_bnum] = False
        return True
    return False

def set_convenience_variable(self, frame, name, value):
    if '__pdb_convenience_variables' not in frame.f_globals:
        frame.f_globals['__pdb_convenience_variables'] = {}
    frame.f_globals['__pdb_convenience_variables'][name] = value

def _complete_location(self, text, line, begidx, endidx):
    if line.strip().endswith((':', ',')):
        return []
    try:
        ret = self._complete_expression(text, line, begidx, endidx)
    except Exception:
        ret = []
    globs = glob.glob(glob.escape(text) + '*')
    for fn in globs:
        if os.path.isdir(fn):
            ret.append(fn + '/')
        elif os.path.isfile(fn) and fn.lower().endswith(('.py', '.pyw')):
            ret.append(fn + ':')
    return ret

def _complete_expression(self, text, line, begidx, endidx):
    if not self.curframe:
        return []
    ns = {**self.curframe.f_globals, **self.curframe_locals}
    if '.' in text:
        dotted = text.split('.')
        try:
            obj = ns[dotted[0]]
            for part in dotted[1:-1]:
                obj = getattr(obj, part)
        except (KeyError, AttributeError):
            return []
        prefix = '.'.join(dotted[:-1]) + '.'
        return [prefix + n for n in dir(obj) if n.startswith(dotted[-1])]
    else:
        return [n for n in ns.keys() if n.startswith(text)]

def defaultFile(self):
    """Produce a reasonable default."""
    filename = self.curframe.f_code.co_filename
    if filename == '<string>' and self.mainpyfile:
        filename = self.mainpyfile
    return filename

def lineinfo(self, identifier):
    failed = (None, None, None)
    idstring = identifier.split("'")
    if len(idstring) == 1:
        id = idstring[0].strip()
    elif len(idstring) == 3:
        id = idstring[1].strip()
    else:
        return failed
    if id == '':
        return failed
    parts = id.split('.')
    if parts[0] == 'self':
        del parts[0]
        if len(parts) == 0:
            return failed
    fname = self.defaultFile()
    if len(parts) == 1:
        item = parts[0]
    else:
        f = self.lookupmodule(parts[0])
        if f:
            fname = f
        item = parts[1]
    answer = find_function(item, fname)
    return answer or failed

def do_enable(self, arg):
    """enable bpnumber [bpnumber ...]

    Enables the breakpoints given as a space separated list of
    breakpoint numbers."""
    args = arg.split()
    for i in args:
        try:
            bp = self.get_bpbynumber(i)
        except ValueError as err:
            self.error(err)
        else:
            bp.enable()
            self.message('Enabled %s' % bp)

def do_disable(self, arg):
    """disable bpnumber [bpnumber ...]

    Disables the breakpoints given as a space separated list of
    breakpoint numbers.  Disabling a breakpoint means it cannot
    cause the program to stop execution, but unlike clearing a
    breakpoint, it remains in the list of breakpoints and can be
    (re-)enabled."""
    args = arg.split()
    for i in args:
        try:
            bp = self.get_bpbynumber(i)
        except ValueError as err:
            self.error(err)
        else:
            bp.disable()
            self.message('Disabled %s' % bp)

def do_condition(self, arg):
    """condition bpnumber [condition]

    Set a new condition for the breakpoint, an expression which
    must evaluate to true before the breakpoint is honored.  If
    condition is absent, any existing condition is removed; i.e.,
    the breakpoint is made unconditional."""
    args = arg.split(' ', 1)
    try:
        cond = args[1]
        if (err := self._compile_error_message(cond)):
            self.error('Invalid condition %s: %r' % (cond, err))
            return
    except IndexError:
        cond = None
    try:
        bp = self.get_bpbynumber(args[0].strip())
    except IndexError:
        self.error('Breakpoint number expected')
    except ValueError as err:
        self.error(err)
    else:
        bp.cond = cond
        if not cond:
            self.message('Breakpoint %d is now unconditional.' % bp.number)
        else:
            self.message('New condition set for breakpoint %d.' % bp.number)

def do_ignore(self, arg):
    """ignore bpnumber [count]

    Set the ignore count for the given breakpoint number.  If
    count is omitted, the ignore count is set to 0.  A breakpoint
    becomes active when the ignore count is zero.  When non-zero,
    the count is decremented each time the breakpoint is reached
    and the breakpoint is not disabled and any associated
    condition evaluates to true."""
    args = arg.split()
    try:
        count = int(args[1].strip())
    except:
        count = 0
    try:
        bp = self.get_bpbynumber(args[0].strip())
    except IndexError:
        self.error('Breakpoint number expected')
    except ValueError as err:
        self.error(err)
    else:
        bp.ignore = count
        if count > 0:
            if count > 1:
                countstr = '%d crossings' % count
            else:
                countstr = '1 crossing'
            self.message('Will ignore next %s of breakpoint %d.' % (countstr, bp.number))
        else:
            self.message('Will stop next time breakpoint %d is reached.' % bp.number)

def do_up(self, arg):
    """u(p) [count]

    Move the current frame count (default one) levels up in the
    stack trace (to an older frame)."""
    if self.curindex == 0:
        self.error('Oldest frame')
        return
    try:
        count = int(arg or 1)
    except ValueError:
        self.error('Invalid frame count (%s)' % arg)
        return
    if count < 0:
        newframe = 0
    else:
        newframe = max(0, self.curindex - count)
    self._select_frame(newframe)

def do_down(self, arg):
    """d(own) [count]

    Move the current frame count (default one) levels down in the
    stack trace (to a newer frame)."""
    if self.curindex + 1 == len(self.stack):
        self.error('Newest frame')
        return
    try:
        count = int(arg or 1)
    except ValueError:
        self.error('Invalid frame count (%s)' % arg)
        return
    if count < 0:
        newframe = len(self.stack) - 1
    else:
        newframe = min(len(self.stack) - 1, self.curindex + count)
    self._select_frame(newframe)

def do_until(self, arg):
    """unt(il) [lineno]

    Without argument, continue execution until the line with a
    number greater than the current one is reached.  With a line
    number, continue execution until a line with a number greater
    or equal to that is reached.  In both cases, also stop when
    the current frame returns."""
    if arg:
        try:
            lineno = int(arg)
        except ValueError:
            self.error('Error in argument: %r' % arg)
            return
        if lineno <= self.curframe.f_lineno:
            self.error('"until" line number is smaller than current line number')
            return
    else:
        lineno = None
    self.set_until(self.curframe, lineno)
    return 1

def do_jump(self, arg):
    """j(ump) lineno

    Set the next line that will be executed.  Only available in
    the bottom-most frame.  This lets you jump back and execute
    code again, or jump forward to skip code that you don't want
    to run.

    It should be noted that not all jumps are allowed -- for
    instance it is not possible to jump into the middle of a
    for loop or out of a finally clause."""
    if self.curindex + 1 != len(self.stack):
        self.error('You can only jump within the bottom frame')
        return
    try:
        arg = int(arg)
    except ValueError:
        self.error("The 'jump' command requires a line number")
    else:
        try:
            self.curframe.f_lineno = arg
            self.stack[self.curindex] = (self.stack[self.curindex][0], arg)
            self.print_stack_entry(self.stack[self.curindex])
        except ValueError as e:
            self.error('Jump failed: %s' % e)

def do_args(self, arg):
    """a(rgs)

    Print the argument list of the current function."""
    co = self.curframe.f_code
    dict = self.curframe_locals
    n = co.co_argcount + co.co_kwonlyargcount
    if co.co_flags & inspect.CO_VARARGS:
        n = n + 1
    if co.co_flags & inspect.CO_VARKEYWORDS:
        n = n + 1
    for i in range(n):
        name = co.co_varnames[i]
        if name in dict:
            self.message('%s = %s' % (name, self._safe_repr(dict[name], name)))
        else:
            self.message('%s = *** undefined ***' % (name,))

def do_retval(self, arg):
    """retval

    Print the return value for the last return of a function."""
    if '__return__' in self.curframe_locals:
        self.message(self._safe_repr(self.curframe_locals['__return__'], 'retval'))
    else:
        self.error('Not yet returned!')

def _getval(self, arg):
    try:
        return eval(arg, self.curframe.f_globals, self.curframe_locals)
    except:
        self._error_exc()
        raise

def _getval_except(self, arg, frame=None):
    try:
        if frame is None:
            return eval(arg, self.curframe.f_globals, self.curframe_locals)
        else:
            return eval(arg, frame.f_globals, frame.f_locals)
    except BaseException as exc:
        return _rstr('** raised %s **' % self._format_exc(exc))

def _error_exc(self):
    exc = sys.exception()
    self.error(self._format_exc(exc))

def _msg_val_func(self, arg, func):
    try:
        val = self._getval(arg)
    except:
        return
    try:
        self.message(func(val))
    except:
        self._error_exc()

def _safe_repr(self, obj, expr):
    try:
        return repr(obj)
    except Exception as e:
        return _rstr(f'*** repr({expr}) failed: {self._format_exc(e)} ***')

def do_source(self, arg):
    """source expression

    Try to get source code for the given object and display it."""
    try:
        obj = self._getval(arg)
    except:
        return
    try:
        lines, lineno = self._getsourcelines(obj)
    except (OSError, TypeError) as err:
        self.error(err)
        return
    self._print_lines(lines, lineno)

def _print_lines(self, lines, start, breaks=(), frame=None):
    """Print a range of lines."""
    if frame:
        current_lineno = frame.f_lineno
        exc_lineno = self.tb_lineno.get(frame, -1)
    else:
        current_lineno = exc_lineno = -1
    for lineno, line in enumerate(lines, start):
        s = str(lineno).rjust(3)
        if len(s) < 4:
            s += ' '
        if lineno in breaks:
            s += 'B'
        else:
            s += ' '
        if lineno == current_lineno:
            s += '->'
        elif lineno == exc_lineno:
            s += '>>'
        self.message(s + '\t' + line.rstrip())

def do_whatis(self, arg):
    """whatis expression

    Print the type of the argument."""
    try:
        value = self._getval(arg)
    except:
        return
    code = None
    try:
        code = value.__func__.__code__
    except Exception:
        pass
    if code:
        self.message('Method %s' % code.co_name)
        return
    try:
        code = value.__code__
    except Exception:
        pass
    if code:
        self.message('Function %s' % code.co_name)
        return
    if value.__class__ is type:
        self.message('Class %s.%s' % (value.__module__, value.__qualname__))
        return
    self.message(type(value))

def do_display(self, arg):
    """display [expression]

    Display the value of the expression if it changed, each time execution
    stops in the current frame.

    Without expression, list all display expressions for the current frame."""
    if not arg:
        if self.displaying:
            self.message('Currently displaying:')
            for key, val in self.displaying.get(self.curframe, {}).items():
                self.message('%s: %s' % (key, self._safe_repr(val, key)))
        else:
            self.message('No expression is being displayed')
    elif (err := self._compile_error_message(arg)):
        self.error('Unable to display %s: %r' % (arg, err))
    else:
        val = self._getval_except(arg)
        self.displaying.setdefault(self.curframe, {})[arg] = val
        self.message('display %s: %s' % (arg, self._safe_repr(val, arg)))

def do_undisplay(self, arg):
    """undisplay [expression]

    Do not display the expression any more in the current frame.

    Without expression, clear all display expressions for the current frame."""
    if arg:
        try:
            del self.displaying.get(self.curframe, {})[arg]
        except KeyError:
            self.error('not displaying %s' % arg)
    else:
        self.displaying.pop(self.curframe, None)

def do_interact(self, arg):
    """interact

    Start an interactive interpreter whose global namespace
    contains all the (global and local) names found in the current scope."""
    ns = {**self.curframe.f_globals, **self.curframe_locals}
    code.interact('*interactive*', local=ns)

def do_unalias(self, arg):
    """unalias name

    Delete the specified alias."""
    args = arg.split()
    if len(args) == 0:
        return
    if args[0] in self.aliases:
        del self.aliases[args[0]]

def print_stack_trace(self):
    try:
        for frame_lineno in self.stack:
            self.print_stack_entry(frame_lineno)
    except KeyboardInterrupt:
        pass

def print_stack_entry(self, frame_lineno, prompt_prefix=line_prefix):
    frame, lineno = frame_lineno
    if frame is self.curframe:
        prefix = '> '
    else:
        prefix = '  '
    self.message(prefix + self.format_stack_entry(frame_lineno, prompt_prefix))

def do_help(self, arg):
    """h(elp)

    Without argument, print the list of available commands.
    With a command name as argument, print help about that command.
    "help pdb" shows the full pdb documentation.
    "help exec" gives help on the ! command."""
    if not arg:
        return cmd.Cmd.do_help(self, arg)
    try:
        try:
            topic = getattr(self, 'help_' + arg)
            return topic()
        except AttributeError:
            command = getattr(self, 'do_' + arg)
    except AttributeError:
        self.error('No help for %r' % arg)
    else:
        if sys.flags.optimize >= 2:
            self.error('No help for %r; please do not run Python with -OO if you need command help' % arg)
            return
        if command.__doc__ is None:
            self.error('No help for %r; __doc__ string missing' % arg)
            return
        self.message(self._help_message_from_doc(command.__doc__))

def lookupmodule(self, filename):
    """Helper function for break/clear parsing -- may be overridden.

    lookupmodule() translates (possibly incomplete) file or module name
    into an absolute file name."""
    if os.path.isabs(filename) and os.path.exists(filename):
        return filename
    f = os.path.join(sys.path[0], filename)
    if os.path.exists(f) and self.canonic(f) == self.mainpyfile:
        return f
    root, ext = os.path.splitext(filename)
    if ext == '':
        filename = filename + '.py'
    if os.path.isabs(filename):
        return filename
    for dirname in sys.path:
        while os.path.islink(dirname):
            dirname = os.readlink(dirname)
        fullname = os.path.join(dirname, filename)
        if os.path.exists(fullname):
            return fullname
    return None

def _compile_error_message(self, expr):
    """Return the error message as string if compiling `expr` fails."""
    try:
        compile(expr, '<stdin>', 'eval')
    except SyntaxError as exc:
        return _rstr(self._format_exc(exc))
    return ''

def _getsourcelines(self, obj):
    lines, lineno = inspect.getsourcelines(obj)
    lineno = max(1, lineno)
    return (lines, lineno)

def _help_message_from_doc(self, doc):
    lines = [line.strip() for line in doc.rstrip().splitlines()]
    if not lines:
        return 'No help message found.'
    if '' in lines:
        usage_end = lines.index('')
    else:
        usage_end = 1
    formatted = []
    indent = ' ' * len(self.prompt)
    for i, line in enumerate(lines):
        if i == 0:
            prefix = 'Usage: '
        elif i < usage_end:
            prefix = '       '
        else:
            prefix = ''
        formatted.append(indent + prefix + line)
    return '\n'.join(formatted)

def _getattribute(obj, name):
    top = obj
    for subpath in name.split('.'):
        if subpath == '<locals>':
            raise AttributeError("Can't get local attribute {!r} on {!r}".format(name, top))
        try:
            parent = obj
            obj = getattr(obj, subpath)
        except AttributeError:
            raise AttributeError("Can't get attribute {!r} on {!r}".format(name, top)) from None
    return (obj, parent)

def whichmodule(obj, name):
    """Find the module an object belong to."""
    module_name = getattr(obj, '__module__', None)
    if module_name is not None:
        return module_name
    for module_name, module in sys.modules.copy().items():
        if module_name == '__main__' or module_name == '__mp_main__' or module is None:
            continue
        try:
            if _getattribute(module, name)[0] is obj:
                return module_name
        except AttributeError:
            pass
    return '__main__'

def _loads(s, /, *, fix_imports=True, encoding='ASCII', errors='strict', buffers=None):
    if isinstance(s, str):
        raise TypeError("Can't load pickle from unicode string")
    file = io.BytesIO(s)
    return _Unpickler(file, fix_imports=fix_imports, buffers=buffers, encoding=encoding, errors=errors).load()

def _test():
    import doctest
    return doctest.testmod()

def __init__(self, file_write):
    self.file_write = file_write
    self.current_frame = None

def end_framing(self):
    if self.current_frame and self.current_frame.tell() > 0:
        self.commit_frame(force=True)
        self.current_frame = None

def commit_frame(self, force=False):
    if self.current_frame:
        f = self.current_frame
        if f.tell() >= self._FRAME_SIZE_TARGET or force:
            data = f.getbuffer()
            write = self.file_write
            if len(data) >= self._FRAME_SIZE_MIN:
                write(FRAME + pack('<Q', len(data)))
            write(data)
            self.current_frame = io.BytesIO()

def write(self, data):
    if self.current_frame:
        return self.current_frame.write(data)
    else:
        return self.file_write(data)

def write_large_bytes(self, header, payload):
    write = self.file_write
    if self.current_frame:
        self.commit_frame(force=True)
    write(header)
    write(payload)

def readinto(self, buf):
    if self.current_frame:
        n = self.current_frame.readinto(buf)
        if n == 0 and len(buf) != 0:
            self.current_frame = None
            n = len(buf)
            buf[:] = self.file_read(n)
            return n
        if n < len(buf):
            raise UnpicklingError('pickle exhausted before end of frame')
        return n
    else:
        n = len(buf)
        buf[:] = self.file_read(n)
        return n

def read(self, n):
    if self.current_frame:
        data = self.current_frame.read(n)
        if not data and n != 0:
            self.current_frame = None
            return self.file_read(n)
        if len(data) < n:
            raise UnpicklingError('pickle exhausted before end of frame')
        return data
    else:
        return self.file_read(n)

def readline(self):
    if self.current_frame:
        data = self.current_frame.readline()
        if not data:
            self.current_frame = None
            return self.file_readline()
        if data[-1] != b'\n'[0]:
            raise UnpicklingError('pickle exhausted before end of frame')
        return data
    else:
        return self.file_readline()

def dump(self, obj):
    """Write a pickled representation of obj to the open file."""
    if not hasattr(self, '_file_write'):
        raise PicklingError('Pickler.__init__() was not called by %s.__init__()' % (self.__class__.__name__,))
    if self.proto >= 2:
        self.write(PROTO + pack('<B', self.proto))
    if self.proto >= 4:
        self.framer.start_framing()
    self.save(obj)
    self.write(STOP)
    self.framer.end_framing()

def put(self, idx):
    if self.proto >= 4:
        return MEMOIZE
    elif self.bin:
        if idx < 256:
            return BINPUT + pack('<B', idx)
        else:
            return LONG_BINPUT + pack('<I', idx)
    else:
        return PUT + repr(idx).encode('ascii') + b'\n'

def get(self, i):
    if self.bin:
        if i < 256:
            return BINGET + pack('<B', i)
        else:
            return LONG_BINGET + pack('<I', i)
    return GET + repr(i).encode('ascii') + b'\n'

def save_pers(self, pid):
    if self.bin:
        self.save(pid, save_persistent_id=False)
        self.write(BINPERSID)
    else:
        try:
            self.write(PERSID + str(pid).encode('ascii') + b'\n')
        except UnicodeEncodeError:
            raise PicklingError('persistent IDs in protocol 0 must be ASCII strings')

def save_bool(self, obj):
    if self.proto >= 2:
        self.write(NEWTRUE if obj else NEWFALSE)
    else:
        self.write(TRUE if obj else FALSE)

def save_long(self, obj):
    if self.bin:
        if obj >= 0:
            if obj <= 255:
                self.write(BININT1 + pack('<B', obj))
                return
            if obj <= 65535:
                self.write(BININT2 + pack('<H', obj))
                return
        if -2147483648 <= obj <= 2147483647:
            self.write(BININT + pack('<i', obj))
            return
    if self.proto >= 2:
        encoded = encode_long(obj)
        n = len(encoded)
        if n < 256:
            self.write(LONG1 + pack('<B', n) + encoded)
        else:
            self.write(LONG4 + pack('<i', n) + encoded)
        return
    if -2147483648 <= obj <= 2147483647:
        self.write(INT + repr(obj).encode('ascii') + b'\n')
    else:
        self.write(LONG + repr(obj).encode('ascii') + b'L\n')

def save_float(self, obj):
    if self.bin:
        self.write(BINFLOAT + pack('>d', obj))
    else:
        self.write(FLOAT + repr(obj).encode('ascii') + b'\n')

def _save_bytes_no_memo(self, obj):
    assert self.proto >= 3
    n = len(obj)
    if n <= 255:
        self.write(SHORT_BINBYTES + pack('<B', n) + obj)
    elif n > 4294967295 and self.proto >= 4:
        self._write_large_bytes(BINBYTES8 + pack('<Q', n), obj)
    elif n >= self.framer._FRAME_SIZE_TARGET:
        self._write_large_bytes(BINBYTES + pack('<I', n), obj)
    else:
        self.write(BINBYTES + pack('<I', n) + obj)

def save_bytes(self, obj):
    if self.proto < 3:
        if not obj:
            self.save_reduce(bytes, (), obj=obj)
        else:
            self.save_reduce(codecs.encode, (str(obj, 'latin1'), 'latin1'), obj=obj)
        return
    self._save_bytes_no_memo(obj)
    self.memoize(obj)

def _save_bytearray_no_memo(self, obj):
    assert self.proto >= 5
    n = len(obj)
    if n >= self.framer._FRAME_SIZE_TARGET:
        self._write_large_bytes(BYTEARRAY8 + pack('<Q', n), obj)
    else:
        self.write(BYTEARRAY8 + pack('<Q', n) + obj)

def save_bytearray(self, obj):
    if self.proto < 5:
        if not obj:
            self.save_reduce(bytearray, (), obj=obj)
        else:
            self.save_reduce(bytearray, (bytes(obj),), obj=obj)
        return
    self._save_bytearray_no_memo(obj)
    self.memoize(obj)

def save_str(self, obj):
    if self.bin:
        encoded = obj.encode('utf-8', 'surrogatepass')
        n = len(encoded)
        if n <= 255 and self.proto >= 4:
            self.write(SHORT_BINUNICODE + pack('<B', n) + encoded)
        elif n > 4294967295 and self.proto >= 4:
            self._write_large_bytes(BINUNICODE8 + pack('<Q', n), encoded)
        elif n >= self.framer._FRAME_SIZE_TARGET:
            self._write_large_bytes(BINUNICODE + pack('<I', n), encoded)
        else:
            self.write(BINUNICODE + pack('<I', n) + encoded)
    else:
        tmp = obj.replace('\\', '\\u005c')
        tmp = tmp.replace('\x00', '\\u0000')
        tmp = tmp.replace('\n', '\\u000a')
        tmp = tmp.replace('\r', '\\u000d')
        tmp = tmp.replace('\x1a', '\\u001a')
        self.write(UNICODE + tmp.encode('raw-unicode-escape') + b'\n')
    self.memoize(obj)

def save_tuple(self, obj):
    if not obj:
        if self.bin:
            self.write(EMPTY_TUPLE)
        else:
            self.write(MARK + TUPLE)
        return
    n = len(obj)
    save = self.save
    memo = self.memo
    if n <= 3 and self.proto >= 2:
        for element in obj:
            save(element)
        if id(obj) in memo:
            get = self.get(memo[id(obj)][0])
            self.write(POP * n + get)
        else:
            self.write(_tuplesize2code[n])
            self.memoize(obj)
        return
    write = self.write
    write(MARK)
    for element in obj:
        save(element)
    if id(obj) in memo:
        get = self.get(memo[id(obj)][0])
        if self.bin:
            write(POP_MARK + get)
        else:
            write(POP * (n + 1) + get)
        return
    write(TUPLE)
    self.memoize(obj)

def save_list(self, obj):
    if self.bin:
        self.write(EMPTY_LIST)
    else:
        self.write(MARK + LIST)
    self.memoize(obj)
    self._batch_appends(obj)

def _batch_appends(self, items):
    save = self.save
    write = self.write
    if not self.bin:
        for x in items:
            save(x)
            write(APPEND)
        return
    it = iter(items)
    while True:
        tmp = list(islice(it, self._BATCHSIZE))
        n = len(tmp)
        if n > 1:
            write(MARK)
            for x in tmp:
                save(x)
            write(APPENDS)
        elif n:
            save(tmp[0])
            write(APPEND)
        if n < self._BATCHSIZE:
            return

def save_dict(self, obj):
    if self.bin:
        self.write(EMPTY_DICT)
    else:
        self.write(MARK + DICT)
    self.memoize(obj)
    self._batch_setitems(obj.items())

def _batch_setitems(self, items):
    save = self.save
    write = self.write
    if not self.bin:
        for k, v in items:
            save(k)
            save(v)
            write(SETITEM)
        return
    it = iter(items)
    while True:
        tmp = list(islice(it, self._BATCHSIZE))
        n = len(tmp)
        if n > 1:
            write(MARK)
            for k, v in tmp:
                save(k)
                save(v)
            write(SETITEMS)
        elif n:
            k, v = tmp[0]
            save(k)
            save(v)
            write(SETITEM)
        if n < self._BATCHSIZE:
            return

def save_set(self, obj):
    save = self.save
    write = self.write
    if self.proto < 4:
        self.save_reduce(set, (list(obj),), obj=obj)
        return
    write(EMPTY_SET)
    self.memoize(obj)
    it = iter(obj)
    while True:
        batch = list(islice(it, self._BATCHSIZE))
        n = len(batch)
        if n > 0:
            write(MARK)
            for item in batch:
                save(item)
            write(ADDITEMS)
        if n < self._BATCHSIZE:
            return

def _save_toplevel_by_name(self, module_name, name):
    if self.proto >= 3:
        self.write(GLOBAL + bytes(module_name, 'utf-8') + b'\n' + bytes(name, 'utf-8') + b'\n')
    else:
        if self.fix_imports:
            r_name_mapping = _compat_pickle.REVERSE_NAME_MAPPING
            r_import_mapping = _compat_pickle.REVERSE_IMPORT_MAPPING
            if (module_name, name) in r_name_mapping:
                module_name, name = r_name_mapping[module_name, name]
            elif module_name in r_import_mapping:
                module_name = r_import_mapping[module_name]
        try:
            self.write(GLOBAL + bytes(module_name, 'ascii') + b'\n' + bytes(name, 'ascii') + b'\n')
        except UnicodeEncodeError:
            raise PicklingError("can't pickle global identifier '%s.%s' using pickle protocol %i" % (module_name, name, self.proto)) from None

def save_type(self, obj):
    if obj is type(None):
        return self.save_reduce(type, (None,), obj=obj)
    elif obj is type(NotImplemented):
        return self.save_reduce(type, (NotImplemented,), obj=obj)
    elif obj is type(...):
        return self.save_reduce(type, (...,), obj=obj)
    return self.save_global(obj)

def load_proto(self):
    proto = self.read(1)[0]
    if not 0 <= proto <= HIGHEST_PROTOCOL:
        raise ValueError('unsupported pickle protocol: %d' % proto)
    self.proto = proto

def load_frame(self):
    frame_size, = unpack('<Q', self.read(8))
    if frame_size > sys.maxsize:
        raise ValueError('frame size > sys.maxsize: %d' % frame_size)
    self._unframer.load_frame(frame_size)

def load_persid(self):
    try:
        pid = self.readline()[:-1].decode('ascii')
    except UnicodeDecodeError:
        raise UnpicklingError('persistent IDs in protocol 0 must be ASCII strings')
    self.append(self.persistent_load(pid))

def load_binpersid(self):
    pid = self.stack.pop()
    self.append(self.persistent_load(pid))

def load_int(self):
    data = self.readline()
    if data == FALSE[1:]:
        val = False
    elif data == TRUE[1:]:
        val = True
    else:
        val = int(data, 0)
    self.append(val)

def load_long4(self):
    n, = unpack('<i', self.read(4))
    if n < 0:
        raise UnpicklingError('LONG pickle has negative byte count')
    data = self.read(n)
    self.append(decode_long(data))

def _decode_string(self, value):
    if self.encoding == 'bytes':
        return value
    else:
        return value.decode(self.encoding, self.errors)

def load_string(self):
    data = self.readline()[:-1]
    if len(data) >= 2 and data[0] == data[-1] and (data[0] in b'"\''):
        data = data[1:-1]
    else:
        raise UnpicklingError('the STRING opcode argument must be quoted')
    self.append(self._decode_string(codecs.escape_decode(data)[0]))

def load_binstring(self):
    len, = unpack('<i', self.read(4))
    if len < 0:
        raise UnpicklingError('BINSTRING pickle has negative byte count')
    data = self.read(len)
    self.append(self._decode_string(data))

def load_binbytes(self):
    len, = unpack('<I', self.read(4))
    if len > maxsize:
        raise UnpicklingError("BINBYTES exceeds system's maximum size of %d bytes" % maxsize)
    self.append(self.read(len))

def load_binunicode(self):
    len, = unpack('<I', self.read(4))
    if len > maxsize:
        raise UnpicklingError("BINUNICODE exceeds system's maximum size of %d bytes" % maxsize)
    self.append(str(self.read(len), 'utf-8', 'surrogatepass'))

def load_binbytes8(self):
    len, = unpack('<Q', self.read(8))
    if len > maxsize:
        raise UnpicklingError("BINBYTES8 exceeds system's maximum size of %d bytes" % maxsize)
    self.append(self.read(len))

def load_next_buffer(self):
    if self._buffers is None:
        raise UnpicklingError('pickle stream refers to out-of-band data but no *buffers* argument was given')
    try:
        buf = next(self._buffers)
    except StopIteration:
        raise UnpicklingError('not enough out-of-band buffers')
    self.append(buf)

def load_readonly_buffer(self):
    buf = self.stack[-1]
    with memoryview(buf) as m:
        if not m.readonly:
            self.stack[-1] = m.toreadonly()

def load_short_binbytes(self):
    len = self.read(1)[0]
    self.append(self.read(len))

def load_short_binunicode(self):
    len = self.read(1)[0]
    self.append(str(self.read(len), 'utf-8', 'surrogatepass'))

def load_tuple(self):
    items = self.pop_mark()
    self.append(tuple(items))

def load_frozenset(self):
    items = self.pop_mark()
    self.append(frozenset(items))

def load_list(self):
    items = self.pop_mark()
    self.append(items)

def load_dict(self):
    items = self.pop_mark()
    d = {items[i]: items[i + 1] for i in range(0, len(items), 2)}
    self.append(d)

def load_stack_global(self):
    name = self.stack.pop()
    module = self.stack.pop()
    if type(name) is not str or type(module) is not str:
        raise UnpicklingError('STACK_GLOBAL requires str')
    self.append(self.find_class(module, name))

def load_ext1(self):
    code = self.read(1)[0]
    self.get_extension(code)

def load_ext2(self):
    code, = unpack('<H', self.read(2))
    self.get_extension(code)

def load_ext4(self):
    code, = unpack('<i', self.read(4))
    self.get_extension(code)

def get_extension(self, code):
    obj = _extension_cache.get(code, _NoValue)
    if obj is not _NoValue:
        self.append(obj)
        return
    key = _inverted_registry.get(code)
    if not key:
        if code <= 0:
            raise UnpicklingError('EXT specifies code <= 0')
        raise ValueError('unregistered extension code %d' % code)
    obj = self.find_class(*key)
    _extension_cache[code] = obj
    self.append(obj)

def find_class(self, module, name):
    sys.audit('pickle.find_class', module, name)
    if self.proto < 3 and self.fix_imports:
        if (module, name) in _compat_pickle.NAME_MAPPING:
            module, name = _compat_pickle.NAME_MAPPING[module, name]
        elif module in _compat_pickle.IMPORT_MAPPING:
            module = _compat_pickle.IMPORT_MAPPING[module]
    __import__(module, level=0)
    if self.proto >= 4:
        return _getattribute(sys.modules[module], name)[0]
    else:
        return getattr(sys.modules[module], name)

def load_pop(self):
    if self.stack:
        del self.stack[-1]
    else:
        self.pop_mark()

def load_get(self):
    i = int(self.readline()[:-1])
    try:
        self.append(self.memo[i])
    except KeyError:
        msg = f'Memo value not found at index {i}'
        raise UnpicklingError(msg) from None

def load_binget(self):
    i = self.read(1)[0]
    try:
        self.append(self.memo[i])
    except KeyError as exc:
        msg = f'Memo value not found at index {i}'
        raise UnpicklingError(msg) from None

def load_long_binget(self):
    i, = unpack('<I', self.read(4))
    try:
        self.append(self.memo[i])
    except KeyError as exc:
        msg = f'Memo value not found at index {i}'
        raise UnpicklingError(msg) from None

def load_put(self):
    i = int(self.readline()[:-1])
    if i < 0:
        raise ValueError('negative PUT argument')
    self.memo[i] = self.stack[-1]

def load_binput(self):
    i = self.read(1)[0]
    if i < 0:
        raise ValueError('negative BINPUT argument')
    self.memo[i] = self.stack[-1]

def load_long_binput(self):
    i, = unpack('<I', self.read(4))
    if i > maxsize:
        raise ValueError('negative LONG_BINPUT argument')
    self.memo[i] = self.stack[-1]

def load_memoize(self):
    memo = self.memo
    memo[len(memo)] = self.stack[-1]

def load_additems(self):
    items = self.pop_mark()
    set_obj = self.stack[-1]
    if isinstance(set_obj, set):
        set_obj.update(items)
    else:
        add = set_obj.add
        for item in items:
            add(item)

def load_build(self):
    stack = self.stack
    state = stack.pop()
    inst = stack[-1]
    setstate = getattr(inst, '__setstate__', None)
    if setstate is not None:
        setstate(state)
        return
    slotstate = None
    if isinstance(state, tuple) and len(state) == 2:
        state, slotstate = state
    if state:
        inst_dict = inst.__dict__
        intern = sys.intern
        for k, v in state.items():
            if type(k) is str:
                inst_dict[intern(k)] = v
            else:
                inst_dict[k] = v
    if slotstate:
        for k, v in slotstate.items():
            setattr(inst, k, v)

def load_stop(self):
    value = self.stack.pop()
    raise _Stop(value)

def save_picklebuffer(self, obj):
    if self.proto < 5:
        raise PicklingError('PickleBuffer can only be pickled with protocol >= 5')
    with obj.raw() as m:
        if not m.contiguous:
            raise PicklingError('PickleBuffer can not be pickled when pointing to a non-contiguous buffer')
        in_band = True
        if self._buffer_callback is not None:
            in_band = bool(self._buffer_callback(obj))
        if in_band:
            buf = m.tobytes()
            in_memo = id(buf) in self.memo
            if m.readonly:
                if in_memo:
                    self._save_bytes_no_memo(buf)
                else:
                    self.save_bytes(buf)
            elif in_memo:
                self._save_bytearray_no_memo(buf)
            else:
                self.save_bytearray(buf)
        else:
            self.write(NEXT_BUFFER)
            if m.readonly:
                self.write(READONLY_BUFFER)

def read_stringnl_noescape_pair(f):
    """>>> import io
    >>> read_stringnl_noescape_pair(io.BytesIO(b"Queue\\nEmpty\\njunk"))
    'Queue Empty'"""
    return '%s %s' % (read_stringnl_noescape(f), read_stringnl_noescape(f))

def read_unicodestringnl(f):
    """>>> import io
    >>> read_unicodestringnl(io.BytesIO(b"abc\\\\uabcd\\njunk")) == 'abc\\uabcd'
    True"""
    data = f.readline()
    if not data.endswith(b'\n'):
        raise ValueError('no newline found when trying to read unicodestringnl')
    data = data[:-1]
    return str(data, 'raw-unicode-escape')

def read_decimalnl_long(f):
    """>>> import io

    >>> read_decimalnl_long(io.BytesIO(b"1234L\\n56"))
    1234

    >>> read_decimalnl_long(io.BytesIO(b"123456789012345678901234L\\n6"))
    123456789012345678901234"""
    s = read_stringnl(f, decode=False, stripquotes=False)
    if s[-1:] == b'L':
        s = s[:-1]
    return int(s)

def read_floatnl(f):
    """>>> import io
    >>> read_floatnl(io.BytesIO(b"-1.25\\n6"))
    -1.25"""
    s = read_stringnl(f, decode=False, stripquotes=False)
    return float(s)

def assure_pickle_consistency(verbose=False):
    copy = code2op.copy()
    for name in pickle.__all__:
        if not re.match('[A-Z][A-Z0-9_]+$', name):
            if verbose:
                print("skipping %r: it doesn't look like an opcode name" % name)
            continue
        picklecode = getattr(pickle, name)
        if not isinstance(picklecode, bytes) or len(picklecode) != 1:
            if verbose:
                print("skipping %r: value %r doesn't look like a pickle code" % (name, picklecode))
            continue
        picklecode = picklecode.decode('latin-1')
        if picklecode in copy:
            if verbose:
                print('checking name %r w/ code %r for consistency' % (name, picklecode))
            d = copy[picklecode]
            if d.name != name:
                raise ValueError("for pickle code %r, pickle.py uses name %r but we're using name %r" % (picklecode, name, d.name))
            del copy[picklecode]
        else:
            raise ValueError("pickle.py appears to have a pickle opcode with name %r and code %r, but we don't" % (name, picklecode))
    if copy:
        msg = ["we appear to have pickle opcodes that pickle.py doesn't have:"]
        for code, d in copy.items():
            msg.append('    name %r with code %r' % (d.name, code))
        raise ValueError('\n'.join(msg))

def _genops(data, yield_end_pos=False):
    if isinstance(data, bytes_types):
        data = io.BytesIO(data)
    if hasattr(data, 'tell'):
        getpos = data.tell
    else:
        getpos = lambda: None
    while True:
        pos = getpos()
        code = data.read(1)
        opcode = code2op.get(code.decode('latin-1'))
        if opcode is None:
            if code == b'':
                raise ValueError('pickle exhausted before seeing STOP')
            else:
                raise ValueError('at position %s, opcode %r unknown' % ('<unknown>' if pos is None else pos, code))
        if opcode.arg is None:
            arg = None
        else:
            arg = opcode.arg.reader(data)
        if yield_end_pos:
            yield (opcode, arg, pos, getpos())
        else:
            yield (opcode, arg, pos)
        if code == b'.':
            assert opcode.name == 'STOP'
            break

def __init__(self, name, obtype, doc):
    assert isinstance(name, str)
    self.name = name
    assert isinstance(obtype, type) or isinstance(obtype, tuple)
    if isinstance(obtype, tuple):
        for contained in obtype:
            assert isinstance(contained, type)
    self.obtype = obtype
    assert isinstance(doc, str)
    self.doc = doc

def __repr__(self):
    """t.__repr__() implements repr(t)."""
    return '<Template instance, steps=%r>' % (self.steps,)

def reset(self):
    """t.reset() restores a pipeline template to its initial state."""
    self.steps = []

def debug(self, flag):
    """t.debug(flag) turns debugging on or off."""
    self.debugging = flag

def append(self, cmd, kind):
    """t.append(cmd, kind) adds a new step at the end."""
    if not isinstance(cmd, str):
        raise TypeError('Template.append: cmd must be a string')
    if kind not in stepkinds:
        raise ValueError('Template.append: bad kind %r' % (kind,))
    if kind == SOURCE:
        raise ValueError('Template.append: SOURCE can only be prepended')
    if self.steps and self.steps[-1][1] == SINK:
        raise ValueError('Template.append: already ends with SINK')
    if kind[0] == 'f' and (not re.search('\\$IN\\b', cmd)):
        raise ValueError('Template.append: missing $IN in cmd')
    if kind[1] == 'f' and (not re.search('\\$OUT\\b', cmd)):
        raise ValueError('Template.append: missing $OUT in cmd')
    self.steps.append((cmd, kind))

def prepend(self, cmd, kind):
    """t.prepend(cmd, kind) adds a new step at the front."""
    if not isinstance(cmd, str):
        raise TypeError('Template.prepend: cmd must be a string')
    if kind not in stepkinds:
        raise ValueError('Template.prepend: bad kind %r' % (kind,))
    if kind == SINK:
        raise ValueError('Template.prepend: SINK can only be appended')
    if self.steps and self.steps[0][1] == SOURCE:
        raise ValueError('Template.prepend: already begins with SOURCE')
    if kind[0] == 'f' and (not re.search('\\$IN\\b', cmd)):
        raise ValueError('Template.prepend: missing $IN in cmd')
    if kind[1] == 'f' and (not re.search('\\$OUT\\b', cmd)):
        raise ValueError('Template.prepend: missing $OUT in cmd')
    self.steps.insert(0, (cmd, kind))

def open_r(self, file):
    """t.open_r(file) and t.open_w(file) implement
    t.open(file, 'r') and t.open(file, 'w') respectively."""
    if not self.steps:
        return open(file, 'r')
    if self.steps[-1][1] == SINK:
        raise ValueError('Template.open_r: pipeline ends width SINK')
    cmd = self.makepipeline(file, '')
    return os.popen(cmd, 'r')

def open_w(self, file):
    if not self.steps:
        return open(file, 'w')
    if self.steps[0][1] == SOURCE:
        raise ValueError('Template.open_w: pipeline begins with SOURCE')
    cmd = self.makepipeline('', file)
    return os.popen(cmd, 'w')

def makepipeline(self, infile, outfile):
    cmd = makepipeline(infile, self.steps, outfile)
    if self.debugging:
        print(cmd)
        cmd = 'set -x; ' + cmd
    return cmd

def read_code(stream):
    import marshal
    magic = stream.read(4)
    if magic != importlib.util.MAGIC_NUMBER:
        return None
    stream.read(12)
    return marshal.load(stream)

def iter_modules(path=None, prefix=''):
    """Yields ModuleInfo for all submodules on path,
    or, if path is None, all top-level modules on sys.path.

    'path' should be either None or a list of paths to look for
    modules in.

    'prefix' is a string to output on the front of every module name
    on output."""
    if path is None:
        importers = iter_importers()
    elif isinstance(path, str):
        raise ValueError('path must be None or list of paths to look for modules in')
    else:
        importers = map(get_importer, path)
    yielded = {}
    for i in importers:
        for name, ispkg in iter_importer_modules(i, prefix):
            if name not in yielded:
                yielded[name] = 1
                yield ModuleInfo(i, name, ispkg)

def _iter_file_finder_modules(importer, prefix=''):
    if importer.path is None or not os.path.isdir(importer.path):
        return
    yielded = {}
    import inspect
    try:
        filenames = os.listdir(importer.path)
    except OSError:
        filenames = []
    filenames.sort()
    for fn in filenames:
        modname = inspect.getmodulename(fn)
        if modname == '__init__' or modname in yielded:
            continue
        path = os.path.join(importer.path, fn)
        ispkg = False
        if not modname and os.path.isdir(path) and ('.' not in fn):
            modname = fn
            try:
                dircontents = os.listdir(path)
            except OSError:
                dircontents = []
            for fn in dircontents:
                subname = inspect.getmodulename(fn)
                if subname == '__init__':
                    ispkg = True
                    break
            else:
                continue
        if modname and '.' not in modname:
            yielded[modname] = 1
            yield (prefix + modname, ispkg)

def get_importer(path_item):
    """Retrieve a finder for the given path item

    The returned finder is cached in sys.path_importer_cache
    if it was newly created by a path hook.

    The cache (or part of it) can be cleared manually if a
    rescan of sys.path_hooks is necessary."""
    path_item = os.fsdecode(path_item)
    try:
        importer = sys.path_importer_cache[path_item]
    except KeyError:
        for path_hook in sys.path_hooks:
            try:
                importer = path_hook(path_item)
                sys.path_importer_cache.setdefault(path_item, importer)
                break
            except ImportError:
                pass
        else:
            importer = None
    return importer

def get_loader(module_or_name):
    """Get a "loader" object for module_or_name

    Returns None if the module cannot be found or imported.
    If the named module is not already imported, its containing package
    (if any) is imported, in order to establish the package __path__."""
    warnings._deprecated('pkgutil.get_loader', f'{warnings._DEPRECATED_MSG}; use importlib.util.find_spec() instead', remove=(3, 14))
    if module_or_name in sys.modules:
        module_or_name = sys.modules[module_or_name]
        if module_or_name is None:
            return None
    if isinstance(module_or_name, ModuleType):
        module = module_or_name
        loader = getattr(module, '__loader__', None)
        if loader is not None:
            return loader
        if getattr(module, '__spec__', None) is None:
            return None
        fullname = module.__name__
    else:
        fullname = module_or_name
    return find_loader(fullname)

def seen(p, m={}):
    if p in m:
        return True
    m[p] = True

def iter_zipimport_modules(importer, prefix=''):
    dirlist = sorted(zipimport._zip_directory_cache[importer.archive])
    _prefix = importer.prefix
    plen = len(_prefix)
    yielded = {}
    import inspect
    for fn in dirlist:
        if not fn.startswith(_prefix):
            continue
        fn = fn[plen:].split(os.sep)
        if len(fn) == 2 and fn[1].startswith('__init__.py'):
            if fn[0] not in yielded:
                yielded[fn[0]] = 1
                yield (prefix + fn[0], True)
        if len(fn) != 1:
            continue
        modname = inspect.getmodulename(fn[0])
        if modname == '__init__':
            continue
        if modname and '.' not in modname and (modname not in yielded):
            yielded[modname] = 1
            yield (prefix + modname, False)

def _comparable_version(version):
    component_re = re.compile('([0-9]+|[._+-])')
    result = []
    for v in component_re.split(version):
        if v not in '._+-':
            try:
                v = int(v, 10)
                t = 100
            except ValueError:
                t = _ver_stages.get(v, 0)
            result.extend((t, v))
    return result

def _norm_version(version, build=''):
    """Normalize the version and build strings and return a single
    version string using the format major.minor.build (or patchlevel)."""
    l = version.split('.')
    if build:
        l.append(build)
    try:
        strings = list(map(str, map(int, l)))
    except ValueError:
        strings = l
    version = '.'.join(strings[:3])
    return version

def _syscmd_ver(system='', release='', version='', supported_platforms=('win32', 'win16', 'dos')):
    """Tries to figure out the OS version used and returns
    a tuple (system, release, version).

    It uses the "ver" shell command for this which is known
    to exists on Windows, DOS. XXX Others too ?

    In case this fails, the given parameters are used as
    defaults."""
    if sys.platform not in supported_platforms:
        return (system, release, version)
    import subprocess
    for cmd in ('ver', 'command /c ver', 'cmd /c ver'):
        try:
            info = subprocess.check_output(cmd, stdin=subprocess.DEVNULL, stderr=subprocess.DEVNULL, text=True, encoding='locale', shell=True)
        except (OSError, subprocess.CalledProcessError) as why:
            continue
        else:
            break
    else:
        return (system, release, version)
    ver_output = re.compile('(?:([\\w ]+) ([\\w.]+) .*\\[.* ([\\d.]+)\\])')
    info = info.strip()
    m = ver_output.match(info)
    if m is not None:
        system, release, version = m.groups()
        if release[-1] == '.':
            release = release[:-1]
        if version[-1] == '.':
            version = version[:-1]
        version = _norm_version(version)
    return (system, release, version)

def win32_edition():
    try:
        try:
            import winreg
        except ImportError:
            import _winreg as winreg
    except ImportError:
        pass
    else:
        try:
            cvkey = 'SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion'
            with winreg.OpenKeyEx(winreg.HKEY_LOCAL_MACHINE, cvkey) as key:
                return winreg.QueryValueEx(key, 'EditionId')[0]
        except OSError:
            pass
    return None

def win32_ver(release='', version='', csd='', ptype=''):
    is_client = False
    version, csd, ptype, is_client = _win32_ver(version, csd, ptype)
    if version:
        intversion = tuple(map(int, version.split('.')))
        releases = _WIN32_CLIENT_RELEASES if is_client else _WIN32_SERVER_RELEASES
        release = next((r for v, r in releases if v <= intversion), release)
    return (release, version, csd, ptype)

def _mac_ver_xml():
    fn = '/System/Library/CoreServices/SystemVersion.plist'
    if not os.path.exists(fn):
        return None
    try:
        import plistlib
    except ImportError:
        return None
    with open(fn, 'rb') as f:
        pl = plistlib.load(f)
    release = pl['ProductVersion']
    versioninfo = ('', '', '')
    machine = os.uname().machine
    if machine in ('ppc', 'Power Macintosh'):
        machine = 'PowerPC'
    return (release, versioninfo, machine)

def mac_ver(release='', versioninfo=('', '', ''), machine=''):
    """Get macOS version information and return it as tuple (release,
    versioninfo, machine) with versioninfo being a tuple (version,
    dev_stage, non_release_version).

    Entries which cannot be determined are set to the parameter values
    which default to ''. All tuple entries are strings."""
    info = _mac_ver_xml()
    if info is not None:
        return info
    return (release, versioninfo, machine)

def _java_getprop(name, default):
    from java.lang import System
    try:
        value = System.getProperty(name)
        if value is None:
            return default
        return value
    except AttributeError:
        return default

def system_alias(system, release, version):
    """Returns (system, release, version) aliased to common
    marketing names used for some systems.

    It also does some reordering of the information in some cases
    where it would otherwise cause confusion."""
    if system == 'SunOS':
        if release < '5':
            return (system, release, version)
        l = release.split('.')
        if l:
            try:
                major = int(l[0])
            except ValueError:
                pass
            else:
                major = major - 3
                l[0] = str(major)
                release = '.'.join(l)
        if release < '6':
            system = 'Solaris'
        else:
            system = 'Solaris'
    elif system in ('win32', 'win16'):
        system = 'Windows'
    return (system, release, version)

def _node(default=''):
    """Helper to determine the node name of this machine.
    """
    try:
        import socket
    except ImportError:
        return default
    try:
        return socket.gethostname()
    except OSError:
        return default

def _syscmd_file(target, default=''):
    """Interface to the system's file command.

    The function uses the -b option of the file command to have it
    omit the filename in its output. Follow the symlinks. It returns
    default in case the command should fail."""
    if sys.platform in ('dos', 'win32', 'win16'):
        return default
    try:
        import subprocess
    except ImportError:
        return default
    target = _follow_symlinks(target)
    env = dict(os.environ, LC_ALL='C')
    try:
        output = subprocess.check_output(['file', '-b', target], stderr=subprocess.DEVNULL, env=env)
    except (OSError, subprocess.CalledProcessError):
        return default
    if not output:
        return default
    return output.decode('latin-1')

def _get_machine_win32():
    try:
        [arch, *_] = _wmi_query('CPU', 'Architecture')
    except OSError:
        pass
    else:
        try:
            arch = ['x86', 'MIPS', 'Alpha', 'PowerPC', None, 'ARM', 'ia64', None, None, 'AMD64', None, None, 'ARM64'][int(arch)]
        except (ValueError, IndexError):
            pass
        else:
            if arch:
                return arch
    return os.environ.get('PROCESSOR_ARCHITEW6432', '') or os.environ.get('PROCESSOR_ARCHITECTURE', '')

def _parse_os_release(lines):
    info = {'NAME': 'Linux', 'ID': 'linux', 'PRETTY_NAME': 'Linux'}
    os_release_line = re.compile('^(?P<name>[a-zA-Z0-9_]+)=(?P<quote>["\']?)(?P<value>.*)(?P=quote)$')
    os_release_unescape = re.compile('\\\\([\\\\\\$\\"\\\'`])')
    for line in lines:
        mo = os_release_line.match(line)
        if mo is not None:
            info[mo.group('name')] = os_release_unescape.sub('\\1', mo.group('value'))
    return info

def freedesktop_os_release():
    """Return operation system identification from freedesktop.org os-release
    """
    global _os_release_cache
    if _os_release_cache is None:
        errno = None
        for candidate in _os_release_candidates:
            try:
                with open(candidate, encoding='utf-8') as f:
                    _os_release_cache = _parse_os_release(f)
                break
            except OSError as e:
                errno = e.errno
        else:
            raise OSError(errno, f"Unable to read files {', '.join(_os_release_candidates)}")
    return _os_release_cache.copy()

def _wmi_query(table, *keys):
    table = {'OS': 'Win32_OperatingSystem', 'CPU': 'Win32_Processor'}[table]
    data = _wmi.exec_query('SELECT {} FROM {}'.format(','.join(keys), table)).split('\x00')
    split_data = (i.partition('=') for i in data)
    dict_data = {i[0]: i[2] for i in split_data}
    return (dict_data[k] for k in keys)

def get_win32():
    try:
        manufacturer, caption = _wmi_query('CPU', 'Manufacturer', 'Caption')
    except OSError:
        return os.environ.get('PROCESSOR_IDENTIFIER', _get_machine_win32())
    else:
        return f'{caption}, {manufacturer}'

def get_OpenVMS():
    try:
        import vms_lib
    except ImportError:
        pass
    else:
        csid, cpu_number = vms_lib.getsyi('SYI$_CPU', 0)
        return 'Alpha' if cpu_number >= 128 else 'VAX'

def from_subprocess():
    """Fall back to `uname -p`"""
    try:
        import subprocess
    except ImportError:
        return None
    try:
        return subprocess.check_output(['uname', '-p'], stderr=subprocess.DEVNULL, text=True, encoding='utf8').strip()
    except (OSError, subprocess.CalledProcessError):
        pass

@functools.cached_property
def processor(self):
    return _unknown_as_blank(_Processor.get())

@classmethod
def _make(cls, iterable):
    num_fields = len(cls._fields) - 1
    result = cls.__new__(cls, *iterable)
    if len(result) != num_fields + 1:
        msg = f'Expected {num_fields} arguments, got {len(result)}'
        raise TypeError(msg)
    return result

def _encode_base64(s, maxlinelength=76):
    maxbinsize = maxlinelength // 4 * 3
    pieces = []
    for i in range(0, len(s), maxbinsize):
        chunk = s[i:i + maxbinsize]
        pieces.append(binascii.b2a_base64(chunk))
    return b''.join(pieces)

def _decode_base64(s):
    if isinstance(s, str):
        return binascii.a2b_base64(s.encode('utf-8'))
    else:
        return binascii.a2b_base64(s)

def _date_from_string(s):
    order = ('year', 'month', 'day', 'hour', 'minute', 'second')
    gd = _dateParser.match(s).groupdict()
    lst = []
    for key in order:
        val = gd[key]
        if val is None:
            break
        lst.append(int(val))
    return datetime.datetime(*lst)

def _is_fmt_xml(header):
    prefixes = (b'<?xml', b'<plist')
    for pfx in prefixes:
        if header.startswith(pfx):
            return True
    for bom, encoding in ((codecs.BOM_UTF8, 'utf-8'), (codecs.BOM_UTF16_BE, 'utf-16-be'), (codecs.BOM_UTF16_LE, 'utf-16-le')):
        if not header.startswith(bom):
            continue
        for start in prefixes:
            prefix = bom + start.decode('ascii').encode(encoding)
            if header[:len(prefix)] == prefix:
                return True
    return False

def _count_to_size(count):
    if count < 1 << 8:
        return 1
    elif count < 1 << 16:
        return 2
    elif count < 1 << 32:
        return 4
    else:
        return 8

def load(fp, *, fmt=None, dict_type=dict):
    """Read a .plist file. 'fp' should be a readable and binary file object.
    Return the unpacked root object (which usually is a dictionary)."""
    if fmt is None:
        header = fp.read(32)
        fp.seek(0)
        for info in _FORMATS.values():
            if info['detect'](header):
                P = info['parser']
                break
        else:
            raise InvalidFileException()
    else:
        P = _FORMATS[fmt]['parser']
    p = P(dict_type=dict_type)
    return p.parse(fp)

def loads(value, *, fmt=None, dict_type=dict):
    """Read a .plist file from a bytes object.
    Return the unpacked root object (which usually is a dictionary)."""
    fp = BytesIO(value)
    return load(fp, fmt=fmt, dict_type=dict_type)

def dumps(value, *, fmt=FMT_XML, skipkeys=False, sort_keys=True):
    """Return a bytes object with the contents for a .plist file.
    """
    fp = BytesIO()
    dump(value, fp, fmt=fmt, skipkeys=skipkeys, sort_keys=sort_keys)
    return fp.getvalue()

def __init__(self, data):
    if not isinstance(data, int):
        raise TypeError('data must be an int')
    if data >= 1 << 64:
        raise ValueError('UIDs cannot be >= 2**64')
    if data < 0:
        raise ValueError('UIDs must be positive')
    self.data = data

def handle_begin_element(self, element, attrs):
    self.data = []
    handler = getattr(self, 'begin_' + element, None)
    if handler is not None:
        handler(attrs)

def handle_end_element(self, element):
    handler = getattr(self, 'end_' + element, None)
    if handler is not None:
        handler()

def add_object(self, value):
    if self.current_key is not None:
        if not isinstance(self.stack[-1], dict):
            raise ValueError('unexpected element at line %d' % self.parser.CurrentLineNumber)
        self.stack[-1][self.current_key] = value
        self.current_key = None
    elif not self.stack:
        self.root = value
    else:
        if not isinstance(self.stack[-1], list):
            raise ValueError('unexpected element at line %d' % self.parser.CurrentLineNumber)
        self.stack[-1].append(value)

def end_dict(self):
    if self.current_key:
        raise ValueError("missing value for key '%s' at line %d" % (self.current_key, self.parser.CurrentLineNumber))
    self.stack.pop()

def end_integer(self):
    raw = self.get_data()
    if raw.startswith('0x') or raw.startswith('0X'):
        self.add_object(int(raw, 16))
    else:
        self.add_object(int(raw))

def simple_element(self, element, value=None):
    if value is not None:
        value = _escape(value)
        self.writeln('<%s>%s</%s>' % (element, value, element))
    else:
        self.writeln('<%s/>' % element)

def writeln(self, line):
    if line:
        if isinstance(line, str):
            line = line.encode('utf-8')
        self.file.write(self._indent_level * self.indent)
        self.file.write(line)
    self.file.write(b'\n')

def __init__(self, file, indent_level=0, indent=b'\t', writeHeader=1, sort_keys=True, skipkeys=False):
    if writeHeader:
        file.write(PLISTHEADER)
    _DumbXMLWriter.__init__(self, file, indent_level, indent)
    self._sort_keys = sort_keys
    self._skipkeys = skipkeys

def write_value(self, value):
    if isinstance(value, str):
        self.simple_element('string', value)
    elif value is True:
        self.simple_element('true')
    elif value is False:
        self.simple_element('false')
    elif isinstance(value, int):
        if -1 << 63 <= value < 1 << 64:
            self.simple_element('integer', '%d' % value)
        else:
            raise OverflowError(value)
    elif isinstance(value, float):
        self.simple_element('real', repr(value))
    elif isinstance(value, dict):
        self.write_dict(value)
    elif isinstance(value, (bytes, bytearray)):
        self.write_bytes(value)
    elif isinstance(value, datetime.datetime):
        self.simple_element('date', _date_to_string(value))
    elif isinstance(value, (tuple, list)):
        self.write_array(value)
    else:
        raise TypeError('unsupported type: %s' % type(value))

def write_dict(self, d):
    if d:
        self.begin_element('dict')
        if self._sort_keys:
            items = sorted(d.items())
        else:
            items = d.items()
        for key, value in items:
            if not isinstance(key, str):
                if self._skipkeys:
                    continue
                raise TypeError('keys must be strings')
            self.simple_element('key', key)
            self.write_value(value)
        self.end_element('dict')
    else:
        self.simple_element('dict')

def write_array(self, array):
    if array:
        self.begin_element('array')
        for value in array:
            self.write_value(value)
        self.end_element('array')
    else:
        self.simple_element('array')

def parse(self, fp):
    try:
        self._fp = fp
        self._fp.seek(-32, os.SEEK_END)
        trailer = self._fp.read(32)
        if len(trailer) != 32:
            raise InvalidFileException()
        offset_size, self._ref_size, num_objects, top_object, offset_table_offset = struct.unpack('>6xBBQQQ', trailer)
        self._fp.seek(offset_table_offset)
        self._object_offsets = self._read_ints(num_objects, offset_size)
        self._objects = [_undefined] * num_objects
        return self._read_object(top_object)
    except (OSError, IndexError, struct.error, OverflowError, ValueError):
        raise InvalidFileException()

def _read(self, size):
    cursize = min(size, _MIN_READ_BUF_SIZE)
    data = self._fp.read(cursize)
    while True:
        if len(data) != cursize:
            raise InvalidFileException
        if cursize == size:
            return data
        delta = min(cursize, size - cursize)
        data += self._fp.read(delta)
        cursize += delta

def _read_ints(self, n, size):
    data = self._read(size * n)
    if size in _BINARY_FORMAT:
        return struct.unpack(f'>{n}{_BINARY_FORMAT[size]}', data)
    else:
        if not size:
            raise InvalidFileException()
        return tuple((int.from_bytes(data[i:i + size], 'big') for i in range(0, size * n, size)))

def _flatten(self, value):
    if isinstance(value, _scalars):
        if (type(value), value) in self._objtable:
            return
    elif id(value) in self._objidtable:
        return
    refnum = len(self._objlist)
    self._objlist.append(value)
    if isinstance(value, _scalars):
        self._objtable[type(value), value] = refnum
    else:
        self._objidtable[id(value)] = refnum
    if isinstance(value, dict):
        keys = []
        values = []
        items = value.items()
        if self._sort_keys:
            items = sorted(items)
        for k, v in items:
            if not isinstance(k, str):
                if self._skipkeys:
                    continue
                raise TypeError('keys must be strings')
            keys.append(k)
            values.append(v)
        for o in itertools.chain(keys, values):
            self._flatten(o)
    elif isinstance(value, (list, tuple)):
        for o in value:
            self._flatten(o)

def _getrefnum(self, value):
    if isinstance(value, _scalars):
        return self._objtable[type(value), value]
    else:
        return self._objidtable[id(value)]

def _write_size(self, token, size):
    if size < 15:
        self._fp.write(struct.pack('>B', token | size))
    elif size < 1 << 8:
        self._fp.write(struct.pack('>BBB', token | 15, 16, size))
    elif size < 1 << 16:
        self._fp.write(struct.pack('>BBH', token | 15, 17, size))
    elif size < 1 << 32:
        self._fp.write(struct.pack('>BBL', token | 15, 18, size))
    else:
        self._fp.write(struct.pack('>BBQ', token | 15, 19, size))

def _create_socket(self, timeout):
    if timeout is not None and (not timeout):
        raise ValueError('Non-blocking socket (timeout=0) is not supported')
    return socket.create_connection((self.host, self.port), timeout)

def _putline(self, line):
    if self._debugging > 1:
        print('*put*', repr(line))
    sys.audit('poplib.putline', self, line)
    self.sock.sendall(line + CRLF)

def _putcmd(self, line):
    if self._debugging:
        print('*cmd*', repr(line))
    line = bytes(line, self.encoding)
    self._putline(line)

def _getline(self):
    line = self.file.readline(_MAXLINE + 1)
    if len(line) > _MAXLINE:
        raise error_proto('line too long')
    if self._debugging > 1:
        print('*get*', repr(line))
    if not line:
        raise error_proto('-ERR EOF')
    octets = len(line)
    if line[-2:] == CRLF:
        return (line[:-2], octets)
    if line[:1] == CR:
        return (line[1:-1], octets)
    return (line[:-1], octets)

def _getlongresp(self):
    resp = self._getresp()
    list = []
    octets = 0
    line, o = self._getline()
    while line != b'.':
        if line.startswith(b'..'):
            o = o - 1
            line = line[1:]
        octets = octets + o
        list.append(line)
        line, o = self._getline()
    return (resp, list, octets)

def _shortcmd(self, line):
    self._putcmd(line)
    return self._getresp()

def _longcmd(self, line):
    self._putcmd(line)
    return self._getlongresp()

def user(self, user):
    """Send user name, return response

    (should indicate password required)."""
    return self._shortcmd('USER %s' % user)

def pass_(self, pswd):
    """Send password, return response

    (response includes message count, mailbox size).

    NB: mailbox is locked by server from here to 'quit()'"""
    return self._shortcmd('PASS %s' % pswd)

def stat(self):
    """Get mailbox status.

    Result is tuple of 2 ints (message count, mailbox size)"""
    retval = self._shortcmd('STAT')
    rets = retval.split()
    if self._debugging:
        print('*stat*', repr(rets))
    if len(rets) < 3:
        raise error_proto('Invalid STAT response format')
    try:
        numMessages = int(rets[1])
        sizeMessages = int(rets[2])
    except ValueError:
        raise error_proto('Invalid STAT response data: non-numeric values')
    return (numMessages, sizeMessages)

def list(self, which=None):
    """Request listing, return result.

    Result without a message number argument is in form
    ['response', ['mesg_num octets', ...], octets].

    Result when a message number argument is given is a
    single response: the "scan listing" for that message."""
    if which is not None:
        return self._shortcmd('LIST %s' % which)
    return self._longcmd('LIST')

def retr(self, which):
    """Retrieve whole message number 'which'.

    Result is in form ['response', ['line', ...], octets]."""
    return self._longcmd('RETR %s' % which)

def noop(self):
    """Does nothing.

    One supposes the response indicates the server is alive."""
    return self._shortcmd('NOOP')

def rset(self):
    """Unmark all messages marked for deletion."""
    return self._shortcmd('RSET')

def close(self):
    """Close the connection without assuming anything about it."""
    try:
        file = self.file
        self.file = None
        if file is not None:
            file.close()
    finally:
        sock = self.sock
        self.sock = None
        if sock is not None:
            try:
                sock.shutdown(socket.SHUT_RDWR)
            except OSError as exc:
                if exc.errno != errno.ENOTCONN and getattr(exc, 'winerror', 0) != 10022:
                    raise
            finally:
                sock.close()

def rpop(self, user):
    """Send RPOP command to access the mailbox with an alternate user."""
    return self._shortcmd('RPOP %s' % user)

def top(self, which, howmuch):
    """Retrieve message header of message number 'which'
    and first 'howmuch' lines of message body.

    Result is in form ['response', ['line', ...], octets]."""
    return self._longcmd('TOP %s %s' % (which, howmuch))

def utf8(self):
    """Try to enter UTF-8 mode (see RFC 6856). Returns server response.
    """
    return self._shortcmd('UTF8')

def capa(self):
    """Return server capabilities (RFC 2449) as a dictionary
    >>> c=poplib.POP3('localhost')
    >>> c.capa()
    {'IMPLEMENTATION': ['Cyrus', 'POP3', 'server', 'v2.2.12'],
     'TOP': [], 'LOGIN-DELAY': ['0'], 'AUTH-RESP-CODE': [],
     'EXPIRE': ['NEVER'], 'USER': [], 'STLS': [], 'PIPELINING': [],
     'UIDL': [], 'RESP-CODES': []}
    >>>

    Really, according to RFC 2449, the cyrus folks should avoid
    having the implementation split into multiple arguments..."""
    def _parsecap(line):
        lst = line.decode('ascii').split()
        return (lst[0], lst[1:])
    caps = {}
    try:
        resp = self._longcmd('CAPA')
        rawcaps = resp[1]
        for capline in rawcaps:
            capnm, capargs = _parsecap(capline)
            caps[capnm] = capargs
    except error_proto:
        raise error_proto('-ERR CAPA not supported by server')
    return caps

def _parsecap(line):
    lst = line.decode('ascii').split()
    return (lst[0], lst[1:])

def __init__(self, host, port=POP3_SSL_PORT, *, timeout=socket._GLOBAL_DEFAULT_TIMEOUT, context=None):
    if context is None:
        context = ssl._create_stdlib_context()
    self.context = context
    POP3.__init__(self, host, port, timeout)

def _get_sep(path):
    if isinstance(path, bytes):
        return b'/'
    else:
        return '/'

def normcase(s):
    """Normalize case of pathname.  Has no effect under Posix"""
    return os.fspath(s)

def isabs(s):
    """Test whether a path is absolute"""
    s = os.fspath(s)
    sep = _get_sep(s)
    return s.startswith(sep)

def join(a, *p):
    """Join two or more pathname components, inserting '/' as needed.
    If any component is an absolute path, all previous path components
    will be discarded.  An empty last part will result in a path that
    ends with a separator."""
    a = os.fspath(a)
    sep = _get_sep(a)
    path = a
    try:
        if not p:
            path[:0] + sep
        for b in map(os.fspath, p):
            if b.startswith(sep):
                path = b
            elif not path or path.endswith(sep):
                path += b
            else:
                path += sep + b
    except (TypeError, AttributeError, BytesWarning):
        genericpath._check_arg_types('join', a, *p)
        raise
    return path

def splitext(p):
    p = os.fspath(p)
    if isinstance(p, bytes):
        sep = b'/'
        extsep = b'.'
    else:
        sep = '/'
        extsep = '.'
    return genericpath._splitext(p, sep, None, extsep)

def splitdrive(p):
    """Split a pathname into drive and path. On Posix, drive is always
    empty."""
    p = os.fspath(p)
    return (p[:0], p)

def splitroot(p):
    """Split a pathname into drive, root and tail. On Posix, drive is always
    empty; the root may be empty, a single slash, or two slashes. The tail
    contains anything after the root. For example:

        splitroot('foo/bar') == ('', '', 'foo/bar')
        splitroot('/foo/bar') == ('', '/', 'foo/bar')
        splitroot('//foo/bar') == ('', '//', 'foo/bar')
        splitroot('///foo/bar') == ('', '/', '//foo/bar')"""
    p = os.fspath(p)
    if isinstance(p, bytes):
        sep = b'/'
        empty = b''
    else:
        sep = '/'
        empty = ''
    if p[:1] != sep:
        return (empty, empty, p)
    elif p[1:2] != sep or p[2:3] == sep:
        return (empty, sep, p[1:])
    else:
        return (empty, p[:2], p[2:])

def lexists(path):
    """Test whether a path exists.  Returns True for broken symbolic links"""
    try:
        os.lstat(path)
    except (OSError, ValueError):
        return False
    return True

def ismount(path):
    """Test whether a path is a mount point"""
    try:
        s1 = os.lstat(path)
    except (OSError, ValueError):
        return False
    else:
        if stat.S_ISLNK(s1.st_mode):
            return False
    path = os.fspath(path)
    if isinstance(path, bytes):
        parent = join(path, b'..')
    else:
        parent = join(path, '..')
    parent = realpath(parent)
    try:
        s2 = os.lstat(parent)
    except (OSError, ValueError):
        return False
    dev1 = s1.st_dev
    dev2 = s2.st_dev
    if dev1 != dev2:
        return True
    ino1 = s1.st_ino
    ino2 = s2.st_ino
    if ino1 == ino2:
        return True
    return False

def abspath(path):
    """Return an absolute path."""
    path = os.fspath(path)
    if not isabs(path):
        if isinstance(path, bytes):
            cwd = os.getcwdb()
        else:
            cwd = os.getcwd()
        path = join(cwd, path)
    return normpath(path)

def realpath(filename, *, strict=False):
    """Return the canonical path of the specified filename, eliminating any
    symbolic links encountered in the path."""
    filename = os.fspath(filename)
    path, ok = _joinrealpath(filename[:0], filename, strict, {})
    return abspath(path)

def relpath(path, start=None):
    """Return a relative version of a path"""
    if not path:
        raise ValueError('no path specified')
    path = os.fspath(path)
    if isinstance(path, bytes):
        curdir = b'.'
        sep = b'/'
        pardir = b'..'
    else:
        curdir = '.'
        sep = '/'
        pardir = '..'
    if start is None:
        start = curdir
    else:
        start = os.fspath(start)
    try:
        start_list = [x for x in abspath(start).split(sep) if x]
        path_list = [x for x in abspath(path).split(sep) if x]
        i = len(commonprefix([start_list, path_list]))
        rel_list = [pardir] * (len(start_list) - i) + path_list[i:]
        if not rel_list:
            return curdir
        return join(*rel_list)
    except (TypeError, AttributeError, BytesWarning, DeprecationWarning):
        genericpath._check_arg_types('relpath', path, start)
        raise

def commonpath(paths):
    """Given a sequence of path names, returns the longest common sub-path."""
    if not paths:
        raise ValueError('commonpath() arg is an empty sequence')
    paths = tuple(map(os.fspath, paths))
    if isinstance(paths[0], bytes):
        sep = b'/'
        curdir = b'.'
    else:
        sep = '/'
        curdir = '.'
    try:
        split_paths = [path.split(sep) for path in paths]
        try:
            isabs, = set((p[:1] == sep for p in paths))
        except ValueError:
            raise ValueError("Can't mix absolute and relative paths") from None
        split_paths = [[c for c in s if c and c != curdir] for s in split_paths]
        s1 = min(split_paths)
        s2 = max(split_paths)
        common = s1
        for i, c in enumerate(s1):
            if c != s2[i]:
                common = s1[:i]
                break
        prefix = sep if isabs else sep[:0]
        return prefix + sep.join(common)
    except (TypeError, AttributeError):
        genericpath._check_arg_types('commonpath', *paths)
        raise

def repl(m):
    name = m[1]
    if name.startswith(start):
        if not name.endswith(end):
            return m[0]
        name = name[1:-1]
    try:
        if environ is None:
            value = os.fsencode(os.environ[os.fsdecode(name)])
        else:
            value = environ[name]
    except KeyError:
        return m[0]
    else:
        return value

def pformat(object, indent=1, width=80, depth=None, *, compact=False, sort_dicts=True, underscore_numbers=False):
    """Format a Python object into a pretty-printed representation."""
    return PrettyPrinter(indent=indent, width=width, depth=depth, compact=compact, sort_dicts=sort_dicts, underscore_numbers=underscore_numbers).pformat(object)

def pp(object, *args, sort_dicts=False, **kwargs):
    """Pretty-print a Python object"""
    pprint(object, *args, sort_dicts=sort_dicts, **kwargs)

def saferepr(object):
    """Version of repr() which can handle recursive data structures."""
    return PrettyPrinter()._safe_repr(object, {}, None, 0)[0]

def isreadable(object):
    """Determine if saferepr(object) is readable by eval()."""
    return PrettyPrinter()._safe_repr(object, {}, None, 0)[1]

def isrecursive(object):
    """Determine if object requires a recursive representation."""
    return PrettyPrinter()._safe_repr(object, {}, None, 0)[2]

def _safe_tuple(t):
    """Helper function for comparing 2-tuples"""
    return (_safe_key(t[0]), _safe_key(t[1]))

def _wrap_bytes_repr(object, width, allowance):
    current = b''
    last = len(object) // 4 * 4
    for i in range(0, len(object), 4):
        part = object[i:i + 4]
        candidate = current + part
        if i == last:
            width -= allowance
        if len(repr(candidate)) > width:
            if current:
                yield repr(current)
            current = part
        else:
            current = candidate
    if current:
        yield repr(current)

def __lt__(self, other):
    try:
        return self.obj < other.obj
    except TypeError:
        return (str(type(self.obj)), id(self.obj)) < (str(type(other.obj)), id(other.obj))

def pprint(self, object):
    if self._stream is not None:
        self._format(object, self._stream, 0, 0, {}, 0)
        self._stream.write('\n')

def pformat(self, object):
    sio = _StringIO()
    self._format(object, sio, 0, 0, {}, 0)
    return sio.getvalue()

def isreadable(self, object):
    s, readable, recursive = self.format(object, {}, 0, 0)
    return readable and (not recursive)

def _pprint_dict(self, object, stream, indent, allowance, context, level):
    write = stream.write
    write('{')
    if self._indent_per_level > 1:
        write((self._indent_per_level - 1) * ' ')
    length = len(object)
    if length:
        if self._sort_dicts:
            items = sorted(object.items(), key=_safe_tuple)
        else:
            items = object.items()
        self._format_dict_items(items, stream, indent, allowance + 1, context, level)
    write('}')

def _pprint_simplenamespace(self, object, stream, indent, allowance, context, level):
    if type(object) is _types.SimpleNamespace:
        cls_name = 'namespace'
    else:
        cls_name = object.__class__.__name__
    indent += len(cls_name) + 1
    items = object.__dict__.items()
    stream.write(cls_name + '(')
    self._format_namespace_items(items, stream, indent, allowance, context, level)
    stream.write(')')

def _format_namespace_items(self, items, stream, indent, allowance, context, level):
    write = stream.write
    delimnl = ',\n' + ' ' * indent
    last_index = len(items) - 1
    for i, (key, ent) in enumerate(items):
        last = i == last_index
        write(key)
        write('=')
        if id(ent) in context:
            write('...')
        else:
            self._format(ent, stream, indent + len(key) + 1, allowance if last else 1, context, level)
        if not last:
            write(delimnl)

def _repr(self, object, context, level):
    repr, readable, recursive = self.format(object, context.copy(), self._depth, level)
    if not readable:
        self._readable = False
    if recursive:
        self._recursive = True
    return repr

def format(self, object, context, maxlevels, level):
    """Format object for a specific context, returning a string
    and flags indicating whether the representation is 'readable'
    and whether the object represents a recursive construct."""
    return self._safe_repr(object, context, maxlevels, level)

def _pprint_chain_map(self, object, stream, indent, allowance, context, level):
    if not len(object.maps):
        stream.write(repr(object))
        return
    cls = object.__class__
    stream.write(cls.__name__ + '(')
    indent += len(cls.__name__) + 1
    for i, m in enumerate(object.maps):
        if i == len(object.maps) - 1:
            self._format(m, stream, indent, allowance + 1, context, level)
            stream.write(')')
        else:
            self._format(m, stream, indent, 1, context, level)
            stream.write(',\n' + ' ' * indent)

def runctx(statement, globals, locals, filename=None, sort=-1):
    """Run statement under profiler, supplying your own globals and locals,
    optionally saving results in filename.

    statement and filename have the same semantics as profile.run"""
    return _Utils(Profile).runctx(statement, globals, locals, filename, sort)

def main():
    import os
    from optparse import OptionParser
    usage = 'profile.py [-o output_file_path] [-s sort] [-m module | scriptfile] [arg] ...'
    parser = OptionParser(usage=usage)
    parser.allow_interspersed_args = False
    parser.add_option('-o', '--outfile', dest='outfile', help='Save stats to <outfile>', default=None)
    parser.add_option('-m', dest='module', action='store_true', help='Profile a library module.', default=False)
    parser.add_option('-s', '--sort', dest='sort', help='Sort order when printing to stdout, based on pstats.Stats class', default=-1)
    if not sys.argv[1:]:
        parser.print_usage()
        sys.exit(2)
    options, args = parser.parse_args()
    sys.argv[:] = args
    if options.outfile is not None:
        options.outfile = os.path.abspath(options.outfile)
    if len(args) > 0:
        if options.module:
            import runpy
            code = "run_module(modname, run_name='__main__')"
            globs = {'run_module': runpy.run_module, 'modname': args[0]}
        else:
            progname = args[0]
            sys.path.insert(0, os.path.dirname(progname))
            with io.open_code(progname) as fp:
                code = compile(fp.read(), progname, 'exec')
            spec = importlib.machinery.ModuleSpec(name='__main__', loader=None, origin=progname)
            globs = {'__spec__': spec, '__file__': spec.origin, '__name__': spec.name, '__package__': None, '__cached__': None}
        try:
            runctx(code, globs, None, options.outfile, options.sort)
        except BrokenPipeError as exc:
            sys.stdout = None
            sys.exit(exc.errno)
    else:
        parser.print_usage()
    return parser

def run(self, statement, filename, sort):
    prof = self.profiler()
    try:
        prof.run(statement)
    except SystemExit:
        pass
    finally:
        self._show(prof, filename, sort)

def runctx(self, statement, globals, locals, filename, sort):
    prof = self.profiler()
    try:
        prof.runctx(statement, globals, locals)
    except SystemExit:
        pass
    finally:
        self._show(prof, filename, sort)

def _show(self, prof, filename, sort):
    if filename is not None:
        prof.dump_stats(filename)
    else:
        prof.print_stats(sort)

def __init__(self, timer=None, bias=None):
    self.timings = {}
    self.cur = None
    self.cmd = ''
    self.c_func_name = ''
    if bias is None:
        bias = self.bias
    self.bias = bias
    if not timer:
        self.timer = self.get_time = time.process_time
        self.dispatcher = self.trace_dispatch_i
    else:
        self.timer = timer
        t = self.timer()
        try:
            length = len(t)
        except TypeError:
            self.get_time = timer
            self.dispatcher = self.trace_dispatch_i
        else:
            if length == 2:
                self.dispatcher = self.trace_dispatch
            else:
                self.dispatcher = self.trace_dispatch_l
            def get_time_timer(timer=timer, sum=sum):
                return sum(timer())
            self.get_time = get_time_timer
    self.t = self.get_time()
    self.simulate_call('profiler')

def trace_dispatch(self, frame, event, arg):
    timer = self.timer
    t = timer()
    t = t[0] + t[1] - self.t - self.bias
    if event == 'c_call':
        self.c_func_name = arg.__name__
    if self.dispatch[event](self, frame, t):
        t = timer()
        self.t = t[0] + t[1]
    else:
        r = timer()
        self.t = r[0] + r[1] - t

def trace_dispatch_i(self, frame, event, arg):
    timer = self.timer
    t = timer() - self.t - self.bias
    if event == 'c_call':
        self.c_func_name = arg.__name__
    if self.dispatch[event](self, frame, t):
        self.t = timer()
    else:
        self.t = timer() - t

def trace_dispatch_mac(self, frame, event, arg):
    timer = self.timer
    t = timer() / 60.0 - self.t - self.bias
    if event == 'c_call':
        self.c_func_name = arg.__name__
    if self.dispatch[event](self, frame, t):
        self.t = timer() / 60.0
    else:
        self.t = timer() / 60.0 - t

def trace_dispatch_l(self, frame, event, arg):
    get_time = self.get_time
    t = get_time() - self.t - self.bias
    if event == 'c_call':
        self.c_func_name = arg.__name__
    if self.dispatch[event](self, frame, t):
        self.t = get_time()
    else:
        self.t = get_time() - t

def trace_dispatch_exception(self, frame, t):
    rpt, rit, ret, rfn, rframe, rcur = self.cur
    if rframe is not frame and rcur:
        return self.trace_dispatch_return(rframe, t)
    self.cur = (rpt, rit + t, ret, rfn, rframe, rcur)
    return 1

def trace_dispatch_call(self, frame, t):
    if self.cur and frame.f_back is not self.cur[-2]:
        rpt, rit, ret, rfn, rframe, rcur = self.cur
        if not isinstance(rframe, Profile.fake_frame):
            assert rframe.f_back is frame.f_back, ('Bad call', rfn, rframe, rframe.f_back, frame, frame.f_back)
            self.trace_dispatch_return(rframe, 0)
            assert self.cur is None or frame.f_back is self.cur[-2], ('Bad call', self.cur[-3])
    fcode = frame.f_code
    fn = (fcode.co_filename, fcode.co_firstlineno, fcode.co_name)
    self.cur = (t, 0, 0, fn, frame, self.cur)
    timings = self.timings
    if fn in timings:
        cc, ns, tt, ct, callers = timings[fn]
        timings[fn] = (cc, ns + 1, tt, ct, callers)
    else:
        timings[fn] = (0, 0, 0, 0, {})
    return 1

def trace_dispatch_c_call(self, frame, t):
    fn = ('', 0, self.c_func_name)
    self.cur = (t, 0, 0, fn, frame, self.cur)
    timings = self.timings
    if fn in timings:
        cc, ns, tt, ct, callers = timings[fn]
        timings[fn] = (cc, ns + 1, tt, ct, callers)
    else:
        timings[fn] = (0, 0, 0, 0, {})
    return 1

def set_cmd(self, cmd):
    if self.cur[-1]:
        return
    self.cmd = cmd
    self.simulate_call(cmd)

def simulate_call(self, name):
    code = self.fake_code('profile', 0, name)
    if self.cur:
        pframe = self.cur[-2]
    else:
        pframe = None
    frame = self.fake_frame(code, pframe)
    self.dispatch['call'](self, frame, 0)

def create_stats(self):
    self.simulate_cmd_complete()
    self.snapshot_stats()

def snapshot_stats(self):
    self.stats = {}
    for func, (cc, ns, tt, ct, callers) in self.timings.items():
        callers = callers.copy()
        nc = 0
        for callcnt in callers.values():
            nc += callcnt
        self.stats[func] = (cc, nc, tt, ct, callers)

def runcall(self, func, /, *args, **kw):
    self.set_cmd(repr(func))
    sys.setprofile(self.dispatcher)
    try:
        return func(*args, **kw)
    finally:
        sys.setprofile(None)

def calibrate(self, m, verbose=0):
    if self.__class__ is not Profile:
        raise TypeError('Subclasses must override .calibrate().')
    saved_bias = self.bias
    self.bias = 0
    try:
        return self._calibrate_inner(m, verbose)
    finally:
        self.bias = saved_bias

def _calibrate_inner(self, m, verbose):
    get_time = self.get_time
    def f1(n):
        for i in range(n):
            x = 1
    def f(m, f1=f1):
        for i in range(m):
            f1(100)
    f(m)
    t0 = get_time()
    f(m)
    t1 = get_time()
    elapsed_noprofile = t1 - t0
    if verbose:
        print('elapsed time without profiling =', elapsed_noprofile)
    p = Profile()
    t0 = get_time()
    p.runctx('f(m)', globals(), locals())
    t1 = get_time()
    elapsed_profile = t1 - t0
    if verbose:
        print('elapsed time with profiling =', elapsed_profile)
    total_calls = 0.0
    reported_time = 0.0
    for (filename, line, funcname), (cc, ns, tt, ct, callers) in p.timings.items():
        if funcname in ('f', 'f1'):
            total_calls += cc
            reported_time += tt
    if verbose:
        print("'CPU seconds' profiler reported =", reported_time)
        print('total # calls =', total_calls)
    if total_calls != m + 1:
        raise ValueError('internal error: total calls = %d' % total_calls)
    mean = (reported_time - elapsed_noprofile) / 2.0 / total_calls
    if verbose:
        print('mean stopwatch overhead per profile event =', mean)
    return mean

def __init__(self, code, prior):
    self.f_code = code
    self.f_back = prior

def f1(n):
    for i in range(n):
        x = 1

def f(m, f1=f1):
    for i in range(m):
        f1(100)

def func_strip_path(func_name):
    filename, line, name = func_name
    return (os.path.basename(filename), line, name)

def func_std_string(func_name):
    if func_name[:2] == ('~', 0):
        name = func_name[2]
        if name.startswith('<') and name.endswith('>'):
            return '{%s}' % name[1:-1]
        else:
            return name
    else:
        return '%s:%d(%s)' % func_name

def add_func_stats(target, source):
    """Add together all the stats for two profile entries."""
    cc, nc, tt, ct, callers = source
    t_cc, t_nc, t_tt, t_ct, t_callers = target
    return (cc + t_cc, nc + t_nc, tt + t_tt, ct + t_ct, add_callers(t_callers, callers))

def add_callers(target, source):
    """Combine two caller lists in a single list."""
    new_callers = {}
    for func, caller in target.items():
        new_callers[func] = caller
    for func, caller in source.items():
        if func in new_callers:
            if isinstance(caller, tuple):
                new_callers[func] = tuple((i + j for i, j in zip(caller, new_callers[func])))
            else:
                new_callers[func] += caller
        else:
            new_callers[func] = caller
    return new_callers

def count_calls(callers):
    """Sum the caller statistics to get total number of calls received."""
    nc = 0
    for calls in callers.values():
        nc += calls
    return nc

def __init__(self, *args, stream=None):
    self.stream = stream or sys.stdout
    if not len(args):
        arg = None
    else:
        arg = args[0]
        args = args[1:]
    self.init(arg)
    self.add(*args)

def load_stats(self, arg):
    if arg is None:
        self.stats = {}
        return
    elif isinstance(arg, str):
        with open(arg, 'rb') as f:
            self.stats = marshal.load(f)
        try:
            file_stats = os.stat(arg)
            arg = time.ctime(file_stats.st_mtime) + '    ' + arg
        except:
            pass
        self.files = [arg]
    elif hasattr(arg, 'create_stats'):
        arg.create_stats()
        self.stats = arg.stats
        arg.stats = {}
    if not self.stats:
        raise TypeError('Cannot create or construct a %r object from %r' % (self.__class__, arg))
    return

def get_top_level_stats(self):
    for func, (cc, nc, tt, ct, callers) in self.stats.items():
        self.total_calls += nc
        self.prim_calls += cc
        self.total_tt += tt
        if ('jprofile', 0, 'profiler') in callers:
            self.top_level.add(func)
        if len(func_std_string(func)) > self.max_name_len:
            self.max_name_len = len(func_std_string(func))

def add(self, *arg_list):
    if not arg_list:
        return self
    for item in reversed(arg_list):
        if type(self) != type(item):
            item = Stats(item)
        self.files += item.files
        self.total_calls += item.total_calls
        self.prim_calls += item.prim_calls
        self.total_tt += item.total_tt
        for func in item.top_level:
            self.top_level.add(func)
        if self.max_name_len < item.max_name_len:
            self.max_name_len = item.max_name_len
        self.fcn_list = None
        for func, stat in item.stats.items():
            if func in self.stats:
                old_func_stat = self.stats[func]
            else:
                old_func_stat = (0, 0, 0, 0, {})
            self.stats[func] = add_func_stats(old_func_stat, stat)
    return self

def get_sort_arg_defs(self):
    """Expand all abbreviations that are unique."""
    if not self.sort_arg_dict:
        self.sort_arg_dict = dict = {}
        bad_list = {}
        for word, tup in self.sort_arg_dict_default.items():
            fragment = word
            while fragment:
                if fragment in dict:
                    bad_list[fragment] = 0
                    break
                dict[fragment] = tup
                fragment = fragment[:-1]
        for word in bad_list:
            del dict[word]
    return self.sort_arg_dict

def sort_stats(self, *field):
    if not field:
        self.fcn_list = 0
        return self
    if len(field) == 1 and isinstance(field[0], int):
        field = [{-1: 'stdname', 0: 'calls', 1: 'time', 2: 'cumulative'}[field[0]]]
    elif len(field) >= 2:
        for arg in field[1:]:
            if type(arg) != type(field[0]):
                raise TypeError("Can't have mixed argument type")
    sort_arg_defs = self.get_sort_arg_defs()
    sort_tuple = ()
    self.sort_type = ''
    connector = ''
    for word in field:
        if isinstance(word, SortKey):
            word = word.value
        sort_tuple = sort_tuple + sort_arg_defs[word][0]
        self.sort_type += connector + sort_arg_defs[word][1]
        connector = ', '
    stats_list = []
    for func, (cc, nc, tt, ct, callers) in self.stats.items():
        stats_list.append((cc, nc, tt, ct) + func + (func_std_string(func), func))
    stats_list.sort(key=cmp_to_key(TupleComp(sort_tuple).compare))
    self.fcn_list = fcn_list = []
    for tuple in stats_list:
        fcn_list.append(tuple[-1])
    return self

def reverse_order(self):
    if self.fcn_list:
        self.fcn_list.reverse()
    return self

def strip_dirs(self):
    oldstats = self.stats
    self.stats = newstats = {}
    max_name_len = 0
    for func, (cc, nc, tt, ct, callers) in oldstats.items():
        newfunc = func_strip_path(func)
        if len(func_std_string(newfunc)) > max_name_len:
            max_name_len = len(func_std_string(newfunc))
        newcallers = {}
        for func2, caller in callers.items():
            newcallers[func_strip_path(func2)] = caller
        if newfunc in newstats:
            newstats[newfunc] = add_func_stats(newstats[newfunc], (cc, nc, tt, ct, newcallers))
        else:
            newstats[newfunc] = (cc, nc, tt, ct, newcallers)
    old_top = self.top_level
    self.top_level = new_top = set()
    for func in old_top:
        new_top.add(func_strip_path(func))
    self.max_name_len = max_name_len
    self.fcn_list = None
    self.all_callees = None
    return self

def calc_callees(self):
    if self.all_callees:
        return
    self.all_callees = all_callees = {}
    for func, (cc, nc, tt, ct, callers) in self.stats.items():
        if not func in all_callees:
            all_callees[func] = {}
        for func2, caller in callers.items():
            if not func2 in all_callees:
                all_callees[func2] = {}
            all_callees[func2][func] = caller
    return

def eval_print_amount(self, sel, list, msg):
    new_list = list
    if isinstance(sel, str):
        try:
            rex = re.compile(sel)
        except re.error:
            msg += '   <Invalid regular expression %r>\n' % sel
            return (new_list, msg)
        new_list = []
        for func in list:
            if rex.search(func_std_string(func)):
                new_list.append(func)
    else:
        count = len(list)
        if isinstance(sel, float) and 0.0 <= sel < 1.0:
            count = int(count * sel + 0.5)
            new_list = list[:count]
        elif isinstance(sel, int) and 0 <= sel < count:
            count = sel
            new_list = list[:count]
    if len(list) != len(new_list):
        msg += '   List reduced from %r to %r due to restriction <%r>\n' % (len(list), len(new_list), sel)
    return (new_list, msg)

def get_print_list(self, sel_list):
    width = self.max_name_len
    if self.fcn_list:
        stat_list = self.fcn_list[:]
        msg = '   Ordered by: ' + self.sort_type + '\n'
    else:
        stat_list = list(self.stats.keys())
        msg = '   Random listing order was used\n'
    for selection in sel_list:
        stat_list, msg = self.eval_print_amount(selection, stat_list, msg)
    count = len(stat_list)
    if not stat_list:
        return (0, stat_list)
    print(msg, file=self.stream)
    if count < len(self.stats):
        width = 0
        for func in stat_list:
            if len(func_std_string(func)) > width:
                width = len(func_std_string(func))
    return (width + 2, stat_list)

def print_stats(self, *amount):
    for filename in self.files:
        print(filename, file=self.stream)
    if self.files:
        print(file=self.stream)
    indent = ' ' * 8
    for func in self.top_level:
        print(indent, func_get_function_name(func), file=self.stream)
    print(indent, self.total_calls, 'function calls', end=' ', file=self.stream)
    if self.total_calls != self.prim_calls:
        print('(%d primitive calls)' % self.prim_calls, end=' ', file=self.stream)
    print('in %.3f seconds' % self.total_tt, file=self.stream)
    print(file=self.stream)
    width, list = self.get_print_list(amount)
    if list:
        self.print_title()
        for func in list:
            self.print_line(func)
        print(file=self.stream)
        print(file=self.stream)
    return self

def print_callees(self, *amount):
    width, list = self.get_print_list(amount)
    if list:
        self.calc_callees()
        self.print_call_heading(width, 'called...')
        for func in list:
            if func in self.all_callees:
                self.print_call_line(width, func, self.all_callees[func])
            else:
                self.print_call_line(width, func, {})
        print(file=self.stream)
        print(file=self.stream)
    return self

def print_callers(self, *amount):
    width, list = self.get_print_list(amount)
    if list:
        self.print_call_heading(width, 'was called by...')
        for func in list:
            cc, nc, tt, ct, callers = self.stats[func]
            self.print_call_line(width, func, callers, '<-')
        print(file=self.stream)
        print(file=self.stream)
    return self

def print_call_heading(self, name_size, column_title):
    print('Function '.ljust(name_size) + column_title, file=self.stream)
    subheader = False
    for cc, nc, tt, ct, callers in self.stats.values():
        if callers:
            value = next(iter(callers.values()))
            subheader = isinstance(value, tuple)
            break
    if subheader:
        print(' ' * name_size + '    ncalls  tottime  cumtime', file=self.stream)

def print_call_line(self, name_size, source, call_dict, arrow='->'):
    print(func_std_string(source).ljust(name_size) + arrow, end=' ', file=self.stream)
    if not call_dict:
        print(file=self.stream)
        return
    clist = sorted(call_dict.keys())
    indent = ''
    for func in clist:
        name = func_std_string(func)
        value = call_dict[func]
        if isinstance(value, tuple):
            nc, cc, tt, ct = value
            if nc != cc:
                substats = '%d/%d' % (nc, cc)
            else:
                substats = '%d' % (nc,)
            substats = '%s %s %s  %s' % (substats.rjust(7 + 2 * len(indent)), f8(tt), f8(ct), name)
            left_width = name_size + 1
        else:
            substats = '%s(%r) %s' % (name, value, f8(self.stats[func][3]))
            left_width = name_size + 3
        print(indent * left_width + substats, file=self.stream)
        indent = ' '

def print_title(self):
    print('   ncalls  tottime  percall  cumtime  percall', end=' ', file=self.stream)
    print('filename:lineno(function)', file=self.stream)

def print_line(self, func):
    cc, nc, tt, ct, callers = self.stats[func]
    c = str(nc)
    if nc != cc:
        c = c + '/' + str(cc)
    print(c.rjust(9), end=' ', file=self.stream)
    print(f8(tt), end=' ', file=self.stream)
    if nc == 0:
        print(' ' * 8, end=' ', file=self.stream)
    else:
        print(f8(tt / nc), end=' ', file=self.stream)
    print(f8(ct), end=' ', file=self.stream)
    if cc == 0:
        print(' ' * 8, end=' ', file=self.stream)
    else:
        print(f8(ct / cc), end=' ', file=self.stream)
    print(func_std_string(func), file=self.stream)

def compare(self, left, right):
    for index, direction in self.comp_select_list:
        l = left[index]
        r = right[index]
        if l < r:
            return -direction
        if l > r:
            return direction
    return 0

def generic(self, fn, line):
    args = line.split()
    processed = []
    for term in args:
        try:
            processed.append(int(term))
            continue
        except ValueError:
            pass
        try:
            frac = float(term)
            if frac > 1 or frac < 0:
                print('Fraction argument must be in [0, 1]', file=self.stream)
                continue
            processed.append(frac)
            continue
        except ValueError:
            pass
        processed.append(term)
    if self.stats:
        getattr(self.stats, fn)(*processed)
    else:
        print('No statistics object is loaded.', file=self.stream)
    return 0

def do_add(self, line):
    if self.stats:
        try:
            self.stats.add(line)
        except OSError as e:
            print('Failed to load statistics for %s: %s' % (line, e), file=self.stream)
    else:
        print('No statistics object is loaded.', file=self.stream)
    return 0

