def qsize(self):
    """Return the approximate size of the queue (not reliable!)."""
    with self.mutex:
        return self._qsize()

def put(self, item, block=True, timeout=None):
    """Put an item into the queue.

    If optional args 'block' is true and 'timeout' is None (the default),
    block if necessary until a free slot is available. If 'timeout' is
    a non-negative number, it blocks at most 'timeout' seconds and raises
    the Full exception if no free slot was available within that time.
    Otherwise ('block' is false), put an item on the queue if a free slot
    is immediately available, else raise the Full exception ('timeout'
    is ignored in that case)."""
    with self.not_full:
        if self.maxsize > 0:
            if not block:
                if self._qsize() >= self.maxsize:
                    raise Full
            elif timeout is None:
                while self._qsize() >= self.maxsize:
                    self.not_full.wait()
            elif timeout < 0:
                raise ValueError("'timeout' must be a non-negative number")
            else:
                endtime = time() + timeout
                while self._qsize() >= self.maxsize:
                    remaining = endtime - time()
                    if remaining <= 0.0:
                        raise Full
                    self.not_full.wait(remaining)
        self._put(item)
        self.unfinished_tasks += 1
        self.not_empty.notify()

def put_nowait(self, item):
    """Put an item into the queue without blocking.

    Only enqueue the item if a free slot is immediately available.
    Otherwise raise the Full exception."""
    return self.put(item, block=False)

def get_nowait(self):
    """Remove and return an item from the queue without blocking.

    Only get an item if one is immediately available. Otherwise
    raise the Empty exception."""
    return self.get(block=False)

def put_nowait(self, item):
    """Put an item into the queue without blocking.

    This is exactly equivalent to `put(item, block=False)` and is only provided
    for compatibility with the Queue class."""
    return self.put(item, block=False)

def empty(self):
    """Return True if the queue is empty, False otherwise (not reliable!)."""
    return len(self._queue) == 0

def qsize(self):
    """Return the approximate size of the queue (not reliable!)."""
    return len(self._queue)

def quote(c):
    """Quote a single character."""
    assert isinstance(c, bytes) and len(c) == 1
    c = ord(c)
    return ESCAPE + bytes((HEX[c // 16], HEX[c % 16]))

def encodestring(s, quotetabs=False, header=False):
    if b2a_qp is not None:
        return b2a_qp(s, quotetabs=quotetabs, header=header)
    from io import BytesIO
    infp = BytesIO(s)
    outfp = BytesIO()
    encode(infp, outfp, quotetabs, header)
    return outfp.getvalue()

def decodestring(s, header=False):
    if a2b_qp is not None:
        return a2b_qp(s, header=header)
    from io import BytesIO
    infp = BytesIO(s)
    outfp = BytesIO()
    decode(infp, outfp, header=header)
    return outfp.getvalue()

def unhex(s):
    """Get the integer value of a hexadecimal number."""
    bits = 0
    for c in s:
        c = bytes((c,))
        if b'0' <= c <= b'9':
            i = ord('0')
        elif b'a' <= c <= b'f':
            i = ord('a') - 10
        elif b'A' <= c <= b'F':
            i = ord(b'A') - 10
        else:
            assert False, 'non-hex digit ' + repr(c)
        bits = bits * 16 + (ord(c) - i)
    return bits

def write(s, output=output, lineEnd=b'\n'):
    if s and s[-1:] in b' \t':
        output.write(s[:-1] + quote(s[-1:]) + lineEnd)
    elif s == b'.':
        output.write(quote(s) + lineEnd)
    else:
        output.write(s + lineEnd)

def getstate(self):
    """Return internal state; can be passed to setstate() later."""
    return (self.VERSION, super().getstate(), self.gauss_next)

def setstate(self, state):
    """Restore internal state from object returned by getstate()."""
    version = state[0]
    if version == 3:
        version, internalstate, self.gauss_next = state
        super().setstate(internalstate)
    elif version == 2:
        version, internalstate, self.gauss_next = state
        try:
            internalstate = tuple((x % 2 ** 32 for x in internalstate))
        except ValueError as e:
            raise TypeError from e
        super().setstate(internalstate)
    else:
        raise ValueError('state with version %s passed to Random.setstate() of version %s' % (version, self.VERSION))

def __init_subclass__(cls, /, **kwargs):
    """Control how subclasses generate random integers.

    The algorithm a subclass can use depends on the random() and/or
    getrandbits() implementation available to it and determines
    whether it can generate random integers from arbitrarily large
    ranges."""
    for c in cls.__mro__:
        if '_randbelow' in c.__dict__:
            break
        if 'getrandbits' in c.__dict__:
            cls._randbelow = cls._randbelow_with_getrandbits
            break
        if 'random' in c.__dict__:
            cls._randbelow = cls._randbelow_without_getrandbits
            break

def randbytes(self, n):
    """Generate n random bytes."""
    return self.getrandbits(n * 8).to_bytes(n, 'little')

def randrange(self, start, stop=None, step=_ONE):
    """Choose a random item from range(stop) or range(start, stop[, step]).

    Roughly equivalent to ``choice(range(start, stop, step))`` but
    supports arbitrarily large ranges and is optimized for common cases."""
    istart = _index(start)
    if stop is None:
        if step is not _ONE:
            raise TypeError('Missing a non-None stop argument')
        if istart > 0:
            return self._randbelow(istart)
        raise ValueError('empty range for randrange()')
    istop = _index(stop)
    width = istop - istart
    istep = _index(step)
    if istep == 1:
        if width > 0:
            return istart + self._randbelow(width)
        raise ValueError(f'empty range in randrange({start}, {stop})')
    if istep > 0:
        n = (width + istep - 1) // istep
    elif istep < 0:
        n = (width + istep + 1) // istep
    else:
        raise ValueError('zero step for randrange()')
    if n <= 0:
        raise ValueError(f'empty range in randrange({start}, {stop}, {step})')
    return istart + istep * self._randbelow(n)

def randint(self, a, b):
    """Return random integer in range [a, b], including both end points.
    """
    return self.randrange(a, b + 1)

def choice(self, seq):
    """Choose a random element from a non-empty sequence."""
    if not len(seq):
        raise IndexError('Cannot choose from an empty sequence')
    return seq[self._randbelow(len(seq))]

def shuffle(self, x):
    """Shuffle list x in place, and return None."""
    randbelow = self._randbelow
    for i in reversed(range(1, len(x))):
        j = randbelow(i + 1)
        x[i], x[j] = (x[j], x[i])

def choices(self, population, weights=None, *, cum_weights=None, k=1):
    """Return a k sized list of population elements chosen with replacement.

    If the relative weights or cumulative weights are not specified,
    the selections are made with equal probability."""
    random = self.random
    n = len(population)
    if cum_weights is None:
        if weights is None:
            floor = _floor
            n += 0.0
            return [population[floor(random() * n)] for i in _repeat(None, k)]
        try:
            cum_weights = list(_accumulate(weights))
        except TypeError:
            if not isinstance(weights, int):
                raise
            k = weights
            raise TypeError(f'The number of choices must be a keyword argument: k={k!r}') from None
    elif weights is not None:
        raise TypeError('Cannot specify both weights and cumulative weights')
    if len(cum_weights) != n:
        raise ValueError('The number of weights does not match the population')
    total = cum_weights[-1] + 0.0
    if total <= 0.0:
        raise ValueError('Total of weights must be greater than zero')
    if not _isfinite(total):
        raise ValueError('Total of weights must be finite')
    bisect = _bisect
    hi = n - 1
    return [population[bisect(cum_weights, random() * total, 0, hi)] for i in _repeat(None, k)]

def uniform(self, a, b):
    """Get a random number in the range [a, b) or [a, b] depending on rounding.

    The mean (expected value) and variance of the random variable are:

        E[X] = (a + b) / 2
        Var[X] = (b - a) ** 2 / 12"""
    return a + (b - a) * self.random()

def lognormvariate(self, mu, sigma):
    """Log normal distribution.

    If you take the natural logarithm of this distribution, you'll get a
    normal distribution with mean mu and standard deviation sigma.
    mu can have any value, and sigma must be greater than zero."""
    return _exp(self.normalvariate(mu, sigma))

def paretovariate(self, alpha):
    """Pareto distribution.  alpha is the shape parameter."""
    u = 1.0 - self.random()
    return u ** (-1.0 / alpha)

def weibullvariate(self, alpha, beta):
    """Weibull distribution.

    alpha is the scale parameter and beta is the shape parameter."""
    u = 1.0 - self.random()
    return alpha * (-_log(u)) ** (1.0 / beta)

def random(self):
    """Get the next random number in the range 0.0 <= X < 1.0."""
    return (int.from_bytes(_urandom(7)) >> 3) * RECIP_BPF

def randbytes(self, n):
    """Generate n random bytes."""
    return _urandom(n)

def seed(self, *args, **kwds):
