def print_2(*args):
    print(end=' ' * (offset_width + 2 * level))
    print(*args)

def __init__(self, msg, pattern=None, pos=None):
    self.msg = msg
    self.pattern = pattern
    self.pos = pos
    if pattern is not None and pos is not None:
        msg = '%s at position %d' % (msg, pos)
        if isinstance(pattern, str):
            newline = '\n'
        else:
            newline = b'\n'
        self.lineno = pattern.count(newline, 0, pos) + 1
        self.colno = pos - pattern.rfind(newline, 0, pos)
        if newline in pattern:
            msg = '%s (line %d, column %d)' % (msg, self.lineno, self.colno)
    else:
        self.lineno = self.colno = None
    super().__init__(msg)

def fix_flags(src, flags):
    if isinstance(src, str):
        if flags & SRE_FLAG_LOCALE:
            raise ValueError('cannot use LOCALE flag with a str pattern')
        if not flags & SRE_FLAG_ASCII:
            flags |= SRE_FLAG_UNICODE
        elif flags & SRE_FLAG_UNICODE:
            raise ValueError('ASCII and UNICODE flags are incompatible')
    else:
        if flags & SRE_FLAG_UNICODE:
            raise ValueError('cannot use UNICODE flag with a bytes pattern')
        if flags & SRE_FLAG_LOCALE and flags & SRE_FLAG_ASCII:
            raise ValueError('ASCII and LOCALE flags are incompatible')
    return flags

def parse(str, flags=0, state=None):
    source = Tokenizer(str)
    if state is None:
        state = State()
    state.flags = flags
    state.str = str
    p = _parse_sub(source, state, flags & SRE_FLAG_VERBOSE, 0)
    p.state.flags = fix_flags(str, p.state.flags)
    if source.next is not None:
        assert source.next == ')'
        raise source.error('unbalanced parenthesis')
    for g in p.state.grouprefpos:
        if g >= p.state.groups:
            msg = 'invalid group reference %d' % g
            raise error(msg, str, p.state.grouprefpos[g])
    if flags & SRE_FLAG_DEBUG:
        p.dump()
    return p

def __init__(self):
    self.flags = 0
    self.groupdict = {}
    self.groupwidths = [None]
    self.lookbehindgroups = None
    self.grouprefpos = {}

@property
def groups(self):
    return len(self.groupwidths)

def opengroup(self, name=None):
    gid = self.groups
    self.groupwidths.append(None)
    if self.groups > MAXGROUPS:
        raise error('too many groups')
    if name is not None:
        ogid = self.groupdict.get(name, None)
        if ogid is not None:
            raise error('redefinition of group name %r as group %d; was group %d' % (name, gid, ogid))
        self.groupdict[name] = gid
    return gid

def checklookbehindgroup(self, gid, source):
    if self.lookbehindgroups is not None:
        if not self.checkgroup(gid):
            raise source.error('cannot refer to an open group')
        if gid >= self.lookbehindgroups:
            raise source.error('cannot refer to group defined in the same lookbehind subpattern')

def __init__(self, state, data=None):
    self.state = state
    if data is None:
        data = []
    self.data = data
    self.width = None

def __getitem__(self, index):
    if isinstance(index, slice):
        return SubPattern(self.state, self.data[index])
    return self.data[index]

def __next(self):
    index = self.index
    try:
        char = self.decoded_string[index]
    except IndexError:
        self.next = None
        return
    if char == '\\':
        index += 1
        try:
            char += self.decoded_string[index]
        except IndexError:
            raise error('bad escape (end of pattern)', self.string, len(self.string) - 1) from None
    self.index = index + 1
    self.next = char

def match(self, char):
    if char == self.next:
        self.__next()
        return True
    return False

def getwhile(self, n, charset):
    result = ''
    for _ in range(n):
        c = self.next
        if c not in charset:
            break
        result += c
        self.__next()
    return result

def getuntil(self, terminator, name):
    result = ''
    while True:
        c = self.next
        self.__next()
        if c is None:
            if not result:
                raise self.error('missing ' + name)
            raise self.error('missing %s, unterminated name' % terminator, len(result))
        if c == terminator:
            if not result:
                raise self.error('missing ' + name, 1)
            break
        result += c
    return result

@property
def pos(self):
    return self.index - len(self.next or '')

def seek(self, index):
    self.index = index
    self.__next()

def error(self, msg, offset=0):
    if not self.istext:
        msg = msg.encode('ascii', 'backslashreplace').decode('ascii')
    return error(msg, self.string, self.tell() - offset)

def checkgroupname(self, name, offset):
    if not (self.istext or name.isascii()):
        msg = 'bad character in group name %a' % name
        raise self.error(msg, len(name) + offset)
    if not name.isidentifier():
        msg = 'bad character in group name %r' % name
        raise self.error(msg, len(name) + offset)

def addliteral():
    if s.istext:
        result.append(''.join(literal))
    else:
        result.append(''.join(literal).encode('latin-1'))
    del literal[:]

def addgroup(index, pos):
    if index > pattern.groups:
        raise s.error('invalid group reference %d' % index, pos)
    addliteral()
    result.append(index)

def _possibly_sorted(x):
    try:
        return sorted(x)
    except Exception:
        return list(x)

def repr1(self, x, level):
    cls = type(x)
    typename = cls.__name__
    if ' ' in typename:
        parts = typename.split()
        typename = '_'.join(parts)
    method = getattr(self, 'repr_' + typename, None)
    if method:
        if typename not in self._lookup:
            return method(x, level)
        module = getattr(cls, '__module__', None)
        if module == self._lookup[typename]:
            return method(x, level)
    return self.repr_instance(x, level)

def _join(self, pieces, level):
    if self.indent is None:
        return ', '.join(pieces)
    if not pieces:
        return ''
    indent = self.indent
    if isinstance(indent, int):
        if indent < 0:
            raise ValueError(f'Repr.indent cannot be negative int (was {indent!r})')
        indent *= ' '
    try:
        sep = ',\n' + (self.maxlevel - level + 1) * indent
    except TypeError as error:
        raise TypeError(f'Repr.indent must be a str, int or None, not {type(indent)}') from error
    return sep.join(('', *pieces, ''))[1:-len(indent) or None]

def _repr_iterable(self, x, level, left, right, maxiter, trail=''):
    n = len(x)
    if level <= 0 and n:
        s = self.fillvalue
    else:
        newlevel = level - 1
        repr1 = self.repr1
        pieces = [repr1(elem, newlevel) for elem in islice(x, maxiter)]
        if n > maxiter:
            pieces.append(self.fillvalue)
        s = self._join(pieces, level)
        if n == 1 and trail and (self.indent is None):
            right = trail + right
    return '%s%s%s' % (left, s, right)

def repr_array(self, x, level):
    if not x:
        return "array('%s')" % x.typecode
    header = "array('%s', [" % x.typecode
    return self._repr_iterable(x, level, header, '])', self.maxarray)

def repr_set(self, x, level):
    if not x:
        return 'set()'
    x = _possibly_sorted(x)
    return self._repr_iterable(x, level, '{', '}', self.maxset)

def repr_frozenset(self, x, level):
    if not x:
        return 'frozenset()'
    x = _possibly_sorted(x)
    return self._repr_iterable(x, level, 'frozenset({', '})', self.maxfrozenset)

def repr_dict(self, x, level):
    n = len(x)
    if n == 0:
        return '{}'
    if level <= 0:
        return '{' + self.fillvalue + '}'
    newlevel = level - 1
    repr1 = self.repr1
    pieces = []
    for key in islice(_possibly_sorted(x), self.maxdict):
        keyrepr = repr1(key, newlevel)
        valrepr = repr1(x[key], newlevel)
        pieces.append('%s: %s' % (keyrepr, valrepr))
    if n > self.maxdict:
        pieces.append(self.fillvalue)
    s = self._join(pieces, level)
    return '{%s}' % (s,)

def wrapper(self):
    key = (id(self), get_ident())
    if key in repr_running:
        return fillvalue
    repr_running.add(key)
    try:
        result = user_function(self)
    finally:
        repr_running.discard(key)
    return result

def get_class_members(klass):
    ret = dir(klass)
    if hasattr(klass, '__bases__'):
        for base in klass.__bases__:
            ret = ret + get_class_members(base)
    return ret

def complete(self, text, state):
    """Return the next possible completion for 'text'.

    This is called successively with state == 0, 1, 2, ... until it
    returns None.  The completion should begin with 'text'."""
    if self.use_main_ns:
        self.namespace = __main__.__dict__
    if not text.strip():
        if state == 0:
            if _readline_available:
                readline.insert_text('\t')
                readline.redisplay()
                return ''
            else:
                return '\t'
        else:
            return None
    if state == 0:
        if '.' in text:
            self.matches = self.attr_matches(text)
        else:
            self.matches = self.global_matches(text)
    try:
        return self.matches[state]
    except IndexError:
        return None

def _callable_postfix(self, val, word):
    if callable(val):
        word += '('
        try:
            if not inspect.signature(val).parameters:
                word += ')'
        except ValueError:
            pass
    return word

def global_matches(self, text):
    """Compute matches when text is a simple name.

    Return a list of all keywords, built-in functions and names currently
    defined in self.namespace that match."""
    matches = []
    seen = {'__builtins__'}
    n = len(text)
    for word in keyword.kwlist + keyword.softkwlist:
        if word[:n] == text:
            seen.add(word)
            if word in {'finally', 'try'}:
                word = word + ':'
            elif word not in {'False', 'None', 'True', 'break', 'continue', 'pass', 'else', '_'}:
                word = word + ' '
            matches.append(word)
    for nspace in [self.namespace, builtins.__dict__]:
        for word, val in nspace.items():
            if word[:n] == text and word not in seen:
                seen.add(word)
                matches.append(self._callable_postfix(val, word))
    return matches

def _run_module_as_main(mod_name, alter_argv=True):
    """Runs the designated module in the __main__ namespace

    Note that the executed module will have full access to the
    __main__ namespace. If this is not desirable, the run_module()
    function should be used to run the module code in a fresh namespace.

    At the very least, these variables in __main__ will be overwritten:
        __name__
        __file__
        __cached__
        __loader__
        __package__"""
    try:
        if alter_argv or mod_name != '__main__':
            mod_name, mod_spec, code = _get_module_details(mod_name, _Error)
        else:
            mod_name, mod_spec, code = _get_main_module_details(_Error)
    except _Error as exc:
        msg = '%s: %s' % (sys.executable, exc)
        sys.exit(msg)
    main_globals = sys.modules['__main__'].__dict__
    if alter_argv:
        sys.argv[0] = mod_spec.origin
    return _run_code(code, main_globals, None, '__main__', mod_spec)

def _get_main_module_details(error=ImportError):
    main_name = '__main__'
    saved_main = sys.modules[main_name]
    del sys.modules[main_name]
    try:
        return _get_module_details(main_name)
    except ImportError as exc:
        if main_name in str(exc):
            raise error("can't find %r module in %r" % (main_name, sys.path[0])) from exc
        raise
    finally:
        sys.modules[main_name] = saved_main

def __enter__(self):
    mod_name = self.mod_name
    try:
        self._saved_module.append(sys.modules[mod_name])
    except KeyError:
        pass
    sys.modules[mod_name] = self.module
    return self

def __exit__(self, *args):
    if self._saved_module:
        sys.modules[self.mod_name] = self._saved_module[0]
    else:
        del sys.modules[self.mod_name]
    self._saved_module = []

def __init__(self, value):
    self.value = value
    self._saved_value = self._sentinel = object()

def __enter__(self):
    if self._saved_value is not self._sentinel:
        raise RuntimeError('Already preserving saved value')
    self._saved_value = sys.argv[0]
    sys.argv[0] = self.value

def __exit__(self, *args):
    self.value = self._sentinel
    sys.argv[0] = self._saved_value

def enter(self, delay, priority, action, argument=(), kwargs=_sentinel):
    """A variant that specifies the time as a relative time.

    This is actually the more commonly used interface."""
    time = self.timefunc() + delay
    return self.enterabs(time, priority, action, argument, kwargs)

@property
def queue(self):
    """An ordered list of upcoming events.

    Events are named tuples with fields for:
        time, priority, action, arguments, kwargs"""
    with self._lock:
        events = self._queue[:]
    return list(map(heapq.heappop, [events] * len(events)))

def randbelow(exclusive_upper_bound):
    """Return a random int in the range [0, n)."""
    if exclusive_upper_bound <= 0:
        raise ValueError('Upper bound must be positive.')
    return _sysrand._randbelow(exclusive_upper_bound)

def token_bytes(nbytes=None):
    """Return a random byte string containing *nbytes* bytes.

    If *nbytes* is ``None`` or not supplied, a reasonable
    default is used.

    >>> token_bytes(16)  #doctest:+SKIP
    b'\\xebr\\x17D*t\\xae\\xd4\\xe3S\\xb6\\xe2\\xebP1\\x8b'"""
    if nbytes is None:
        nbytes = DEFAULT_ENTROPY
    return _sysrand.randbytes(nbytes)

def _fileobj_to_fd(fileobj):
    """Return a file descriptor from a file object.

    Parameters:
    fileobj -- file object or file descriptor

    Returns:
    corresponding file descriptor

    Raises:
    ValueError if the object is invalid"""
    if isinstance(fileobj, int):
        fd = fileobj
    else:
        try:
            fd = int(fileobj.fileno())
        except (AttributeError, TypeError, ValueError):
            raise ValueError('Invalid file object: {!r}'.format(fileobj)) from None
    if fd < 0:
        raise ValueError('Invalid file descriptor: {}'.format(fd))
    return fd

def _can_use(method):
    """Check if we can use the selector depending upon the
    operating system."""
    selector = getattr(select, method, None)
    if selector is None:
        return False
    try:
        selector_obj = selector()
        if method == 'poll':
            selector_obj.poll(0)
        else:
            selector_obj.close()
        return True
    except OSError:
        return False

def __getitem__(self, fileobj):
    try:
        fd = self._selector._fileobj_lookup(fileobj)
        return self._selector._fd_to_key[fd]
    except KeyError:
        raise KeyError('{!r} is not registered'.format(fileobj)) from None

def get_key(self, fileobj):
    """Return the key associated to a registered file object.

    Returns:
    SelectorKey for this file object"""
    mapping = self.get_map()
    if mapping is None:
        raise RuntimeError('Selector is closed')
    try:
        return mapping[fileobj]
    except KeyError:
        raise KeyError('{!r} is not registered'.format(fileobj)) from None

@abstractmethod
def get_map(self):
    """Return a mapping of file objects to selector keys."""
    raise NotImplementedError

def __init__(self):
    self._fd_to_key = {}
    self._map = _SelectorMapping(self)

def _fileobj_lookup(self, fileobj):
    """Return a file descriptor from a file object.

    This wraps _fileobj_to_fd() to do an exhaustive search in case
    the object is invalid but we still have it in our map.  This
    is used by unregister() so we can unregister an object that
    was previously registered even if it is closed.  It is also
    used by _SelectorMapping."""
    try:
        return _fileobj_to_fd(fileobj)
    except ValueError:
        for key in self._fd_to_key.values():
            if key.fileobj is fileobj:
                return key.fd
        raise

def register(self, fileobj, events, data=None):
    if not events or events & ~(EVENT_READ | EVENT_WRITE):
        raise ValueError('Invalid events: {!r}'.format(events))
    key = SelectorKey(fileobj, self._fileobj_lookup(fileobj), events, data)
    if key.fd in self._fd_to_key:
        raise KeyError('{!r} (FD {}) is already registered'.format(fileobj, key.fd))
    self._fd_to_key[key.fd] = key
    return key

def unregister(self, fileobj):
    try:
        key = self._fd_to_key.pop(self._fileobj_lookup(fileobj))
    except KeyError:
        raise KeyError('{!r} is not registered'.format(fileobj)) from None
    return key

def modify(self, fileobj, events, data=None):
    try:
        key = self._fd_to_key[self._fileobj_lookup(fileobj)]
    except KeyError:
        raise KeyError('{!r} is not registered'.format(fileobj)) from None
    if events != key.events:
        self.unregister(fileobj)
        key = self.register(fileobj, events, data)
    elif data != key.data:
        key = key._replace(data=data)
        self._fd_to_key[key.fd] = key
    return key

def close(self):
    self._fd_to_key.clear()
    self._map = None

def _key_from_fd(self, fd):
    """Return the key associated to a given file descriptor.

    Parameters:
    fd -- file descriptor

    Returns:
    corresponding key, or None if not found"""
    try:
        return self._fd_to_key[fd]
    except KeyError:
        return None

def register(self, fileobj, events, data=None):
    key = super().register(fileobj, events, data)
    if events & EVENT_READ:
        self._readers.add(key.fd)
    if events & EVENT_WRITE:
        self._writers.add(key.fd)
    return key

def select(self, timeout=None):
    timeout = None if timeout is None else max(timeout, 0)
    ready = []
    try:
        r, w, _ = self._select(self._readers, self._writers, [], timeout)
    except InterruptedError:
        return ready
    r = set(r)
    w = set(w)
    for fd in r | w:
        events = 0
        if fd in r:
            events |= EVENT_READ
        if fd in w:
            events |= EVENT_WRITE
        key = self._key_from_fd(fd)
        if key:
            ready.append((key, events & key.events))
    return ready

def __init__(self):
    super().__init__()
    self._selector = self._selector_cls()

def register(self, fileobj, events, data=None):
    key = super().register(fileobj, events, data)
    poller_events = 0
    if events & EVENT_READ:
        poller_events |= self._EVENT_READ
    if events & EVENT_WRITE:
        poller_events |= self._EVENT_WRITE
    try:
        self._selector.register(key.fd, poller_events)
    except:
        super().unregister(fileobj)
        raise
    return key

def unregister(self, fileobj):
    key = super().unregister(fileobj)
    try:
        self._selector.unregister(key.fd)
    except OSError:
        pass
    return key

def modify(self, fileobj, events, data=None):
    try:
        key = self._fd_to_key[self._fileobj_lookup(fileobj)]
    except KeyError:
        raise KeyError(f'{fileobj!r} is not registered') from None
    changed = False
    if events != key.events:
        selector_events = 0
        if events & EVENT_READ:
            selector_events |= self._EVENT_READ
        if events & EVENT_WRITE:
            selector_events |= self._EVENT_WRITE
        try:
            self._selector.modify(key.fd, selector_events)
        except:
            super().unregister(fileobj)
            raise
        changed = True
    if data != key.data:
        changed = True
    if changed:
        key = key._replace(events=events, data=data)
        self._fd_to_key[key.fd] = key
    return key

def select(self, timeout=None):
    if timeout is None:
        timeout = None
    elif timeout <= 0:
        timeout = 0
    else:
        timeout = math.ceil(timeout * 1000.0)
    ready = []
    try:
        fd_event_list = self._selector.poll(timeout)
    except InterruptedError:
        return ready
    for fd, event in fd_event_list:
        events = 0
        if event & ~self._EVENT_READ:
            events |= EVENT_WRITE
        if event & ~self._EVENT_WRITE:
            events |= EVENT_READ
        key = self._key_from_fd(fd)
        if key:
            ready.append((key, events & key.events))
    return ready

def _select(self, r, w, _, timeout=None):
    r, w, x = select.select(r, w, w, timeout)
    return (r, w + x, [])

def select(self, timeout=None):
    if timeout is None:
        timeout = -1
    elif timeout <= 0:
        timeout = 0
    else:
        timeout = math.ceil(timeout * 1000.0) * 0.001
    max_ev = max(len(self._fd_to_key), 1)
    ready = []
    try:
        fd_event_list = self._selector.poll(timeout, max_ev)
    except InterruptedError:
        return ready
    for fd, event in fd_event_list:
        events = 0
        if event & ~select.EPOLLIN:
            events |= EVENT_WRITE
        if event & ~select.EPOLLOUT:
            events |= EVENT_READ
        key = self._key_from_fd(fd)
        if key:
            ready.append((key, events & key.events))
    return ready

def close(self):
    self._selector.close()
    super().close()

def register(self, fileobj, events, data=None):
    key = super().register(fileobj, events, data)
    try:
        if events & EVENT_READ:
            kev = select.kevent(key.fd, select.KQ_FILTER_READ, select.KQ_EV_ADD)
            self._selector.control([kev], 0, 0)
            self._max_events += 1
        if events & EVENT_WRITE:
            kev = select.kevent(key.fd, select.KQ_FILTER_WRITE, select.KQ_EV_ADD)
            self._selector.control([kev], 0, 0)
            self._max_events += 1
    except:
        super().unregister(fileobj)
        raise
    return key

def unregister(self, fileobj):
    key = super().unregister(fileobj)
    if key.events & EVENT_READ:
        kev = select.kevent(key.fd, select.KQ_FILTER_READ, select.KQ_EV_DELETE)
        self._max_events -= 1
        try:
            self._selector.control([kev], 0, 0)
        except OSError:
            pass
    if key.events & EVENT_WRITE:
        kev = select.kevent(key.fd, select.KQ_FILTER_WRITE, select.KQ_EV_DELETE)
        self._max_events -= 1
        try:
            self._selector.control([kev], 0, 0)
        except OSError:
            pass
    return key

def select(self, timeout=None):
    timeout = None if timeout is None else max(timeout, 0)
    max_ev = self._max_events or 1
    ready = []
    try:
        kev_list = self._selector.control(None, max_ev, timeout)
    except InterruptedError:
        return ready
    for kev in kev_list:
        fd = kev.ident
        flag = kev.filter
        events = 0
        if flag == select.KQ_FILTER_READ:
            events |= EVENT_READ
        if flag == select.KQ_FILTER_WRITE:
            events |= EVENT_WRITE
        key = self._key_from_fd(fd)
        if key:
            ready.append((key, events & key.events))
    return ready

def __iter__(self):
    for k in self.dict.keys():
        yield k.decode(self.keyencoding)

def get(self, key, default=None):
    if key.encode(self.keyencoding) in self.dict:
        return self[key]
    return default

def __getitem__(self, key):
    try:
        value = self.cache[key]
    except KeyError:
        f = BytesIO(self.dict[key.encode(self.keyencoding)])
        value = Unpickler(f).load()
        if self.writeback:
            self.cache[key] = value
    return value

def __delitem__(self, key):
    del self.dict[key.encode(self.keyencoding)]
    try:
        del self.cache[key]
    except KeyError:
        pass

def close(self):
    if self.dict is None:
        return
    try:
        self.sync()
        try:
            self.dict.close()
        except AttributeError:
            pass
    finally:
        try:
            self.dict = _ClosedDict()
        except:
            self.dict = None

def __del__(self):
    if not hasattr(self, 'writeback'):
        return
    self.close()

def sync(self):
    if self.writeback and self.cache:
        self.writeback = False
        for key, entry in self.cache.items():
            self[key] = entry
        self.writeback = True
        self.cache = {}
    if hasattr(self.dict, 'sync'):
        self.dict.sync()

def next(self):
    key, value = next(self.dict)
    f = BytesIO(value)
    return (key.decode(self.keyencoding), Unpickler(f).load())

def previous(self):
    key, value = self.dict.previous()
    f = BytesIO(value)
    return (key.decode(self.keyencoding), Unpickler(f).load())

def first(self):
    key, value = self.dict.first()
    f = BytesIO(value)
    return (key.decode(self.keyencoding), Unpickler(f).load())

def last(self):
    key, value = self.dict.last()
    f = BytesIO(value)
    return (key.decode(self.keyencoding), Unpickler(f).load())

def __init__(self, filename, flag='c', protocol=None, writeback=False):
    import dbm
    Shelf.__init__(self, dbm.open(filename, flag), protocol, writeback)

def split(s, comments=False, posix=True):
    """Split the string *s* using shell-like syntax."""
    if s is None:
        raise ValueError('s argument must not be None')
    lex = shlex(s, posix=posix)
    lex.whitespace_split = True
    if not comments:
        lex.commenters = ''
    return list(lex)

def join(split_command):
    """Return a shell-escaped string from *split_command*."""
    return ' '.join((quote(arg) for arg in split_command))

def quote(s):
    """Return a shell-escaped version of the string *s*."""
    if not s:
        return "''"
    if _find_unsafe(s) is None:
        return s
    return "'" + s.replace("'", '\'"\'"\'') + "'"

def _print_tokens(lexer):
    while (tt := lexer.get_token()):
        print('Token: ' + repr(tt))

@property
def punctuation_chars(self):
    return self._punctuation_chars

def push_token(self, tok):
    """Push a token onto the stack popped by the get_token method"""
    if self.debug >= 1:
        print('shlex: pushing token ' + repr(tok))
    self.pushback.appendleft(tok)

def push_source(self, newstream, newfile=None):
    """Push an input source onto the lexer's input source stack."""
    if isinstance(newstream, str):
        newstream = StringIO(newstream)
    self.filestack.appendleft((self.infile, self.instream, self.lineno))
    self.infile = newfile
    self.instream = newstream
    self.lineno = 1
    if self.debug:
        if newfile is not None:
            print('shlex: pushing to file %s' % (self.infile,))
        else:
            print('shlex: pushing to stream %s' % (self.instream,))

def get_token(self):
    """Get a token from the input stream (or from stack if it's nonempty)"""
    if self.pushback:
        tok = self.pushback.popleft()
        if self.debug >= 1:
            print('shlex: popping token ' + repr(tok))
        return tok
    raw = self.read_token()
    if self.source is not None:
        while raw == self.source:
            spec = self.sourcehook(self.read_token())
            if spec:
                newfile, newstream = spec
                self.push_source(newstream, newfile)
            raw = self.get_token()
    while raw == self.eof:
        if not self.filestack:
            return self.eof
        else:
            self.pop_source()
            raw = self.get_token()
    if self.debug >= 1:
        if raw != self.eof:
            print('shlex: token=' + repr(raw))
        else:
            print('shlex: token=EOF')
    return raw

def sourcehook(self, newfile):
    """Hook called on a filename to be sourced."""
    if newfile[0] == '"':
        newfile = newfile[1:-1]
    if isinstance(self.infile, str) and (not os.path.isabs(newfile)):
        newfile = os.path.join(os.path.dirname(self.infile), newfile)
    return (newfile, open(newfile, 'r'))

def __next__(self):
    token = self.get_token()
    if token == self.eof:
        raise StopIteration
    return token

def _fastcopy_fcopyfile(fsrc, fdst, flags):
    """Copy a regular file content or metadata by using high-performance
    fcopyfile(3) syscall (macOS)."""
    try:
        infd = fsrc.fileno()
        outfd = fdst.fileno()
    except Exception as err:
        raise _GiveupOnFastCopy(err)
    try:
        posix._fcopyfile(infd, outfd, flags)
    except OSError as err:
        err.filename = fsrc.name
        err.filename2 = fdst.name
        if err.errno in {errno.EINVAL, errno.ENOTSUP}:
            raise _GiveupOnFastCopy(err)
        else:
            raise err from None

def _fastcopy_sendfile(fsrc, fdst):
    """Copy data from one regular mmap-like fd to another by using
    high-performance sendfile(2) syscall.
    This should work on Linux >= 2.6.33 only."""
    global _USE_CP_SENDFILE
    try:
        infd = fsrc.fileno()
        outfd = fdst.fileno()
    except Exception as err:
        raise _GiveupOnFastCopy(err)
    try:
        blocksize = max(os.fstat(infd).st_size, 2 ** 23)
    except OSError:
        blocksize = 2 ** 27
    if sys.maxsize < 2 ** 32:
        blocksize = min(blocksize, 2 ** 30)
    offset = 0
    while True:
        try:
            sent = os.sendfile(outfd, infd, offset, blocksize)
        except OSError as err:
            err.filename = fsrc.name
            err.filename2 = fdst.name
            if err.errno == errno.ENOTSOCK:
                _USE_CP_SENDFILE = False
                raise _GiveupOnFastCopy(err)
            if err.errno == errno.ENOSPC:
                raise err from None
            if offset == 0 and os.lseek(outfd, 0, os.SEEK_CUR) == 0:
                raise _GiveupOnFastCopy(err)
            raise err
        else:
            if sent == 0:
                break
            offset += sent

def copyfileobj(fsrc, fdst, length=0):
    """copy data from file-like object fsrc to file-like object fdst"""
    if not length:
        length = COPY_BUFSIZE
    fsrc_read = fsrc.read
    fdst_write = fdst.write
    while (buf := fsrc_read(length)):
        fdst_write(buf)

def _samefile(src, dst):
    if isinstance(src, os.DirEntry) and hasattr(os.path, 'samestat'):
        try:
            return os.path.samestat(src.stat(), os.stat(dst))
        except OSError:
            return False
    if hasattr(os.path, 'samefile'):
        try:
            return os.path.samefile(src, dst)
        except OSError:
            return False
    return os.path.normcase(os.path.abspath(src)) == os.path.normcase(os.path.abspath(dst))

def copymode(src, dst, *, follow_symlinks=True):
    """Copy mode bits from src to dst.

    If follow_symlinks is not set, symlinks aren't followed if and only
    if both `src` and `dst` are symlinks.  If `lchmod` isn't available
    (e.g. Linux) this method does nothing."""
    sys.audit('shutil.copymode', src, dst)
    if not follow_symlinks and _islink(src) and os.path.islink(dst):
        if os.name == 'nt':
            stat_func, chmod_func = (os.lstat, os.chmod)
        elif hasattr(os, 'lchmod'):
            stat_func, chmod_func = (os.lstat, os.lchmod)
        else:
            return
    else:
        if os.name == 'nt' and os.path.islink(dst):
            dst = os.path.realpath(dst, strict=True)
        stat_func, chmod_func = (_stat, os.chmod)
    st = stat_func(src)
    chmod_func(dst, stat.S_IMODE(st.st_mode))

def copy2(src, dst, *, follow_symlinks=True):
    """Copy data and metadata. Return the file's destination.

    Metadata is copied with copystat(). Please see the copystat function
    for more information.

    The destination may be a directory.

    If follow_symlinks is false, symlinks won't be followed. This
    resembles GNU's "cp -P src dst"."""
    if os.path.isdir(dst):
        dst = os.path.join(dst, os.path.basename(src))
    if hasattr(_winapi, 'CopyFile2'):
        src_ = os.fsdecode(src)
        dst_ = os.fsdecode(dst)
        flags = _winapi.COPY_FILE_ALLOW_DECRYPTED_DESTINATION
        if not follow_symlinks:
            flags |= _winapi.COPY_FILE_COPY_SYMLINK
        try:
            _winapi.CopyFile2(src_, dst_, flags)
            return dst
        except OSError as exc:
            if exc.winerror == _winapi.ERROR_PRIVILEGE_NOT_HELD and (not follow_symlinks):
                pass
            elif exc.winerror == _winapi.ERROR_ACCESS_DENIED:
                pass
            else:
                raise
    copyfile(src, dst, follow_symlinks=follow_symlinks)
    copystat(src, dst, follow_symlinks=follow_symlinks)
    return dst

def ignore_patterns(*patterns):
    """Function that can be used as copytree() ignore parameter.

    Patterns is a sequence of glob-style patterns
    that are used to exclude files"""
    def _ignore_patterns(path, names):
        ignored_names = []
        for pattern in patterns:
            ignored_names.extend(fnmatch.filter(names, pattern))
        return set(ignored_names)
    return _ignore_patterns

def _rmtree_unsafe(path, onexc):
    def onerror(err):
        onexc(os.scandir, err.filename, err)
    results = os.walk(path, topdown=False, onerror=onerror, followlinks=os._walk_symlinks_as_files)
    for dirpath, dirnames, filenames in results:
        for name in dirnames:
            fullname = os.path.join(dirpath, name)
            try:
                os.rmdir(fullname)
            except OSError as err:
                onexc(os.rmdir, fullname, err)
        for name in filenames:
            fullname = os.path.join(dirpath, name)
            try:
                os.unlink(fullname)
            except OSError as err:
                onexc(os.unlink, fullname, err)
    try:
        os.rmdir(path)
    except OSError as err:
        onexc(os.rmdir, path, err)

def _destinsrc(src, dst):
    src = os.path.abspath(src)
    dst = os.path.abspath(dst)
    if not src.endswith(os.path.sep):
        src += os.path.sep
    if not dst.endswith(os.path.sep):
        dst += os.path.sep
    return dst.startswith(src)

def _get_gid(name):
    """Returns a gid, given a group name."""
    if name is None:
        return None
    try:
        from grp import getgrnam
    except ImportError:
        return None
    try:
        result = getgrnam(name)
    except KeyError:
        result = None
    if result is not None:
        return result[2]
    return None

def _get_uid(name):
    """Returns an uid, given a user name."""
    if name is None:
        return None
    try:
        from pwd import getpwnam
    except ImportError:
        return None
    try:
        result = getpwnam(name)
    except KeyError:
        result = None
    if result is not None:
        return result[2]
    return None

def register_archive_format(name, function, extra_args=None, description=''):
    """Registers an archive format.

    name is the name of the format. function is the callable that will be
    used to create archives. If provided, extra_args is a sequence of
    (name, value) tuples that will be passed as arguments to the callable.
    description can be provided to describe the format, and will be returned
    by the get_archive_formats() function."""
    if extra_args is None:
        extra_args = []
    if not callable(function):
        raise TypeError('The %s object is not callable' % function)
    if not isinstance(extra_args, (tuple, list)):
        raise TypeError('extra_args needs to be a sequence')
    for element in extra_args:
        if not isinstance(element, (tuple, list)) or len(element) != 2:
            raise TypeError('extra_args elements are : (arg_name, value)')
    _ARCHIVE_FORMATS[name] = (function, extra_args, description)

def _check_unpack_options(extensions, function, extra_args):
    """Checks what gets registered as an unpacker."""
    existing_extensions = {}
    for name, info in _UNPACK_FORMATS.items():
        for ext in info[0]:
            existing_extensions[ext] = name
    for extension in extensions:
        if extension in existing_extensions:
            msg = '%s is already registered for "%s"'
            raise RegistryError(msg % (extension, existing_extensions[extension]))
    if not callable(function):
        raise TypeError('The registered function must be a callable')

def unregister_unpack_format(name):
    """Removes the pack format from the registry."""
    del _UNPACK_FORMATS[name]

def _ensure_directory(path):
    """Ensure that the parent directory of `path` exists"""
    dirname = os.path.dirname(path)
    if not os.path.isdir(dirname):
        os.makedirs(dirname)

def _unpack_zipfile(filename, extract_dir):
    """Unpack zip `filename` to `extract_dir`
    """
    import zipfile
    if not zipfile.is_zipfile(filename):
        raise ReadError('%s is not a zip file' % filename)
    zip = zipfile.ZipFile(filename)
    try:
        for info in zip.infolist():
            name = info.filename
            if name.startswith('/') or '..' in name:
                continue
            targetpath = os.path.join(extract_dir, *name.split('/'))
            if not targetpath:
                continue
            _ensure_directory(targetpath)
            if not name.endswith('/'):
                with zip.open(name, 'r') as source, open(targetpath, 'wb') as target:
                    copyfileobj(source, target)
    finally:
        zip.close()

def _unpack_tarfile(filename, extract_dir, *, filter=None):
    """Unpack tar/tar.gz/tar.bz2/tar.xz `filename` to `extract_dir`
    """
    import tarfile
    try:
        tarobj = tarfile.open(filename)
    except tarfile.TarError:
        raise ReadError('%s is not a compressed or uncompressed tar file' % filename)
    try:
        tarobj.extractall(extract_dir, filter=filter)
    finally:
        tarobj.close()

def _find_unpack_format(filename):
    for name, info in _UNPACK_FORMATS.items():
        for extension in info[0]:
            if filename.endswith(extension):
                return name
    return None

def unpack_archive(filename, extract_dir=None, format=None, *, filter=None):
    """Unpack an archive.

    `filename` is the name of the archive.

    `extract_dir` is the name of the target directory, where the archive
    is unpacked. If not provided, the current working directory is used.

    `format` is the archive format: one of "zip", "tar", "gztar", "bztar",
    or "xztar".  Or any other registered format.  If not provided,
    unpack_archive will use the filename extension and see if an unpacker
    was registered for that extension.

    In case none is found, a ValueError is raised.

    If `filter` is given, it is passed to the underlying
    extraction function."""
    sys.audit('shutil.unpack_archive', filename, extract_dir, format)
    if extract_dir is None:
        extract_dir = os.getcwd()
    extract_dir = os.fspath(extract_dir)
    filename = os.fspath(filename)
    if filter is None:
        filter_kwargs = {}
    else:
        filter_kwargs = {'filter': filter}
    if format is not None:
        try:
            format_info = _UNPACK_FORMATS[format]
        except KeyError:
            raise ValueError("Unknown unpack format '{0}'".format(format)) from None
        func = format_info[1]
        func(filename, extract_dir, **dict(format_info[2]), **filter_kwargs)
    else:
        format = _find_unpack_format(filename)
        if format is None:
            raise ReadError("Unknown archive format '{0}'".format(filename))
        func = _UNPACK_FORMATS[format][1]
        kwargs = dict(_UNPACK_FORMATS[format][2]) | filter_kwargs
        func(filename, extract_dir, **kwargs)

def chown(path, user=None, group=None):
    """Change owner user and group of the given path.

    user and group can be the uid/gid or the user/group names, and in that case,
    they are converted to their respective uid/gid."""
    sys.audit('shutil.chown', path, user, group)
    if user is None and group is None:
        raise ValueError('user and/or group must be set')
    _user = user
    _group = group
    if user is None:
        _user = -1
    elif isinstance(user, str):
        _user = _get_uid(user)
        if _user is None:
            raise LookupError('no such user: {!r}'.format(user))
    if group is None:
        _group = -1
    elif not isinstance(group, int):
        _group = _get_gid(group)
        if _group is None:
            raise LookupError('no such group: {!r}'.format(group))
    os.chown(path, _user, _group)

def _copyxattr(src, dst, *, follow_symlinks=True):
    """Copy extended filesystem attributes from `src` to `dst`.

    Overwrite existing attributes.

    If `follow_symlinks` is false, symlinks won't be followed."""
    try:
        names = os.listxattr(src, follow_symlinks=follow_symlinks)
    except OSError as e:
        if e.errno not in (errno.ENOTSUP, errno.ENODATA, errno.EINVAL):
            raise
        return
    for name in names:
        try:
            value = os.getxattr(src, name, follow_symlinks=follow_symlinks)
            os.setxattr(dst, name, value, follow_symlinks=follow_symlinks)
        except OSError as e:
            if e.errno not in (errno.EPERM, errno.ENOTSUP, errno.ENODATA, errno.EINVAL, errno.EACCES):
                raise

def _ignore_patterns(path, names):
    ignored_names = []
    for pattern in patterns:
        ignored_names.extend(fnmatch.filter(names, pattern))
    return set(ignored_names)

def _rmtree_islink(path):
    try:
        st = os.lstat(path)
        return stat.S_ISLNK(st.st_mode) or (st.st_file_attributes & stat.FILE_ATTRIBUTE_REPARSE_POINT and st.st_reparse_tag == stat.IO_REPARSE_TAG_MOUNT_POINT)
    except OSError:
        return False

def _set_uid_gid(tarinfo):
    if gid is not None:
        tarinfo.gid = gid
        tarinfo.gname = group
    if uid is not None:
        tarinfo.uid = uid
        tarinfo.uname = owner
    return tarinfo

def lookup(name):
    fn = getattr(os, name, _nop)
    if fn in os.supports_follow_symlinks:
        return fn
    return _nop

def _int_to_enum(value, enum_klass):
    """Convert a possible numeric value to an IntEnum member.
    If it's not a known member, return the value itself."""
    if not isinstance(value, int):
        return value
    try:
        return enum_klass(value)
    except ValueError:
        return value

def _enum_to_int(value):
    """Convert an IntEnum member to a numeric value.
    If it's not an IntEnum member return the value itself."""
    try:
        return int(value)
    except (ValueError, TypeError):
        return value

def _wraps(wrapped):
    def decorator(wrapper):
        wrapper.__doc__ = wrapped.__doc__
        return wrapper
    return decorator

@_wraps(_signal.signal)
def signal(signalnum, handler):
    handler = _signal.signal(_enum_to_int(signalnum), _enum_to_int(handler))
    return _int_to_enum(handler, Handlers)

@_wraps(_signal.getsignal)
def getsignal(signalnum):
    handler = _signal.getsignal(signalnum)
    return _int_to_enum(handler, Handlers)

def decorator(wrapper):
    wrapper.__doc__ = wrapped.__doc__
    return wrapper

@_wraps(_signal.pthread_sigmask)
def pthread_sigmask(how, mask):
    sigs_set = _signal.pthread_sigmask(how, mask)
    return set((_int_to_enum(x, Signals) for x in sigs_set))

@_wraps(_signal.sigpending)
def sigpending():
    return {_int_to_enum(x, Signals) for x in _signal.sigpending()}

@_wraps(_signal.sigwait)
def sigwait(sigset):
    retsig = _signal.sigwait(sigset)
    return _int_to_enum(retsig, Signals)

def _trace(message):
    if sys.flags.verbose:
        print(message, file=sys.stderr)

def makepath(*paths):
    dir = os.path.join(*paths)
    try:
        dir = os.path.abspath(dir)
    except OSError:
        pass
    return (dir, os.path.normcase(dir))

def abs_paths():
    """Set all module __file__ and __cached__ attributes to an absolute path"""
    for m in set(sys.modules.values()):
        loader_module = None
        try:
            loader_module = m.__loader__.__module__
        except AttributeError:
            try:
                loader_module = m.__spec__.loader.__module__
            except AttributeError:
                pass
        if loader_module not in {'_frozen_importlib', '_frozen_importlib_external'}:
            continue
        try:
            m.__file__ = os.path.abspath(m.__file__)
        except (AttributeError, OSError, TypeError):
            pass
        try:
            m.__cached__ = os.path.abspath(m.__cached__)
        except (AttributeError, OSError, TypeError):
            pass

def _init_pathinfo():
    """Return a set containing all existing file system items from sys.path."""
    d = set()
    for item in sys.path:
        try:
            if os.path.exists(item):
                _, itemcase = makepath(item)
                d.add(itemcase)
        except TypeError:
            continue
    return d

def addsitedir(sitedir, known_paths=None):
    """Add 'sitedir' argument to sys.path if missing and handle .pth files in
    'sitedir'"""
    _trace(f'Adding directory: {sitedir!r}')
    if known_paths is None:
        known_paths = _init_pathinfo()
        reset = True
    else:
        reset = False
    sitedir, sitedircase = makepath(sitedir)
    if not sitedircase in known_paths:
        sys.path.append(sitedir)
        known_paths.add(sitedircase)
    try:
        names = os.listdir(sitedir)
    except OSError:
        return
    names = [name for name in names if name.endswith('.pth') and (not name.startswith('.'))]
    for name in sorted(names):
        addpackage(sitedir, name, known_paths)
    if reset:
        known_paths = None
    return known_paths

def check_enableusersite():
    """Check if user site directory is safe for inclusion

    The function tests for the command line flag (including environment var),
    process uid/gid equal to effective uid/gid.

    None: Disabled for security reasons
    False: Disabled by user (command line option)
    True: Safe and enabled"""
    if sys.flags.no_user_site:
        return False
    if hasattr(os, 'getuid') and hasattr(os, 'geteuid'):
        if os.geteuid() != os.getuid():
            return None
    if hasattr(os, 'getgid') and hasattr(os, 'getegid'):
        if os.getegid() != os.getgid():
            return None
    return True

def _getuserbase():
    env_base = os.environ.get('PYTHONUSERBASE', None)
    if env_base:
        return env_base
    if sys.platform in {'emscripten', 'vxworks', 'wasi'}:
        return None
    def joinuser(*args):
        return os.path.expanduser(os.path.join(*args))
    if os.name == 'nt':
        base = os.environ.get('APPDATA') or '~'
        return joinuser(base, 'Python')
    if sys.platform == 'darwin' and sys._framework:
        return joinuser('~', 'Library', sys._framework, '%d.%d' % sys.version_info[:2])
    return joinuser('~', '.local')

def _get_path(userbase):
    version = sys.version_info
    if os.name == 'nt':
        ver_nodot = sys.winver.replace('.', '')
        return f'{userbase}\\Python{ver_nodot}\\site-packages'
    if sys.platform == 'darwin' and sys._framework:
        return f'{userbase}/lib/python/site-packages'
    return f'{userbase}/lib/python{version[0]}.{version[1]}/site-packages'

def getusersitepackages():
    """Returns the user-specific site-packages directory path.

    If the global variable ``USER_SITE`` is not initialized yet, this
    function will also set it."""
    global USER_SITE, ENABLE_USER_SITE
    userbase = getuserbase()
    if USER_SITE is None:
        if userbase is None:
            ENABLE_USER_SITE = False
        else:
            USER_SITE = _get_path(userbase)
    return USER_SITE

def getsitepackages(prefixes=None):
    """Returns a list containing all global site-packages directories.

    For each directory present in ``prefixes`` (or the global ``PREFIXES``),
    this function will find its `site-packages` subdirectory depending on the
    system environment, and will return a list of full paths."""
    sitepackages = []
    seen = set()
    if prefixes is None:
        prefixes = PREFIXES
    for prefix in prefixes:
        if not prefix or prefix in seen:
            continue
        seen.add(prefix)
        if os.sep == '/':
            libdirs = [sys.platlibdir]
            if sys.platlibdir != 'lib':
                libdirs.append('lib')
            for libdir in libdirs:
                path = os.path.join(prefix, libdir, 'python%d.%d' % sys.version_info[:2], 'site-packages')
                sitepackages.append(path)
        else:
            sitepackages.append(prefix)
            sitepackages.append(os.path.join(prefix, 'Lib', 'site-packages'))
    return sitepackages

def addsitepackages(known_paths, prefixes=None):
