def quoteaddr(addrstring):
    """Quote a subset of the email addresses defined by RFC 821.

    Should be able to handle anything email.utils.parseaddr can handle."""
    displayname, addr = email.utils.parseaddr(addrstring)
    if (displayname, addr) == ('', ''):
        if addrstring.strip().startswith('<'):
            return addrstring
        return '<%s>' % addrstring
    return '<%s>' % addr

def _addr_only(addrstring):
    displayname, addr = email.utils.parseaddr(addrstring)
    if (displayname, addr) == ('', ''):
        return addrstring
    return addr

def quotedata(data):
    """Quote data for email.

    Double leading '.', and change Unix newline '\\n', or Mac '\\r' into
    internet CRLF end-of-line."""
    return re.sub('(?m)^\\.', '..', re.sub('(?:\\r\\n|\\n|\\r(?!\\n))', CRLF, data))

def __init__(self, recipients):
    self.recipients = recipients
    self.args = (recipients,)

def __exit__(self, *args):
    try:
        code, message = self.docmd('QUIT')
        if code != 221:
            raise SMTPResponseException(code, message)
    except SMTPServerDisconnected:
        pass
    finally:
        self.close()

def _print_debug(self, *args):
    if self.debuglevel > 1:
        print(datetime.datetime.now().time(), *args, file=sys.stderr)
    else:
        print(*args, file=sys.stderr)

def _get_socket(self, host, port, timeout):
    if timeout is not None and (not timeout):
        raise ValueError('Non-blocking socket (timeout=0) is not supported')
    if self.debuglevel > 0:
        self._print_debug('connect: to', (host, port), self.source_address)
    return socket.create_connection((host, port), timeout, self.source_address)

def connect(self, host='localhost', port=0, source_address=None):
    """Connect to a host on a given port.

    If the hostname ends with a colon (`:') followed by a number, and
    there is no port specified, that suffix will be stripped off and the
    number interpreted as the port number to use.

    Note: This method is automatically invoked by __init__, if a host is
    specified during instantiation."""
    if source_address:
        self.source_address = source_address
    if not port and host.find(':') == host.rfind(':'):
        i = host.rfind(':')
        if i >= 0:
            host, port = (host[:i], host[i + 1:])
            try:
                port = int(port)
            except ValueError:
                raise OSError('nonnumeric port')
    if not port:
        port = self.default_port
    sys.audit('smtplib.connect', self, host, port)
    self.sock = self._get_socket(host, port, self.timeout)
    self.file = None
    code, msg = self.getreply()
    if self.debuglevel > 0:
        self._print_debug('connect:', repr(msg))
    return (code, msg)

def send(self, s):
    """Send `s' to the server."""
    if self.debuglevel > 0:
        self._print_debug('send:', repr(s))
    if self.sock:
        if isinstance(s, str):
            s = s.encode(self.command_encoding)
        sys.audit('smtplib.send', self, s)
        try:
            self.sock.sendall(s)
        except OSError:
            self.close()
            raise SMTPServerDisconnected('Server not connected')
    else:
        raise SMTPServerDisconnected('please run connect() first')

def putcmd(self, cmd, args=''):
    """Send a command to the server."""
    if args == '':
        s = cmd
    else:
        s = f'{cmd} {args}'
    if '\r' in s or '\n' in s:
        s = s.replace('\n', '\\n').replace('\r', '\\r')
        raise ValueError(f'command and arguments contain prohibited newline characters: {s}')
    self.send(f'{s}{CRLF}')

def docmd(self, cmd, args=''):
    """Send a command, and return its response code."""
    self.putcmd(cmd, args)
    return self.getreply()

def ehlo(self, name=''):
    """SMTP 'ehlo' command.
    Hostname to send for this command defaults to the FQDN of the local
    host."""
    self.esmtp_features = {}
    self.putcmd(self.ehlo_msg, name or self.local_hostname)
    code, msg = self.getreply()
    if code == -1 and len(msg) == 0:
        self.close()
        raise SMTPServerDisconnected('Server not connected')
    self.ehlo_resp = msg
    if code != 250:
        return (code, msg)
    self.does_esmtp = True
    assert isinstance(self.ehlo_resp, bytes), repr(self.ehlo_resp)
    resp = self.ehlo_resp.decode('latin-1').split('\n')
    del resp[0]
    for each in resp:
        auth_match = OLDSTYLE_AUTH.match(each)
        if auth_match:
            self.esmtp_features['auth'] = self.esmtp_features.get('auth', '') + ' ' + auth_match.groups(0)[0]
            continue
        m = re.match('(?P<feature>[A-Za-z0-9][A-Za-z0-9\\-]*) ?', each)
        if m:
            feature = m.group('feature').lower()
            params = m.string[m.end('feature'):].strip()
            if feature == 'auth':
                self.esmtp_features[feature] = self.esmtp_features.get(feature, '') + ' ' + params
            else:
                self.esmtp_features[feature] = params
    return (code, msg)

def has_extn(self, opt):
    """Does the server support a given SMTP service extension?"""
    return opt.lower() in self.esmtp_features

def rset(self):
    """SMTP 'rset' command -- resets session."""
    self.command_encoding = 'ascii'
    return self.docmd('rset')

def noop(self):
    """SMTP 'noop' command -- doesn't do anything :>"""
    return self.docmd('noop')

def mail(self, sender, options=()):
    """SMTP 'mail' command -- begins mail xfer session.

    This method may raise the following exceptions:

     SMTPNotSupportedError  The options parameter includes 'SMTPUTF8'
                            but the SMTPUTF8 extension is not supported by
                            the server."""
    optionlist = ''
    if options and self.does_esmtp:
        if any((x.lower() == 'smtputf8' for x in options)):
            if self.has_extn('smtputf8'):
                self.command_encoding = 'utf-8'
            else:
                raise SMTPNotSupportedError('SMTPUTF8 not supported by server')
        optionlist = ' ' + ' '.join(options)
    self.putcmd('mail', 'FROM:%s%s' % (quoteaddr(sender), optionlist))
    return self.getreply()

def rcpt(self, recip, options=()):
    """SMTP 'rcpt' command -- indicates 1 recipient for this mail."""
    optionlist = ''
    if options and self.does_esmtp:
        optionlist = ' ' + ' '.join(options)
    self.putcmd('rcpt', 'TO:%s%s' % (quoteaddr(recip), optionlist))
    return self.getreply()

def data(self, msg):
    """SMTP 'DATA' command -- sends message data to server.

    Automatically quotes lines beginning with a period per rfc821.
    Raises SMTPDataError if there is an unexpected reply to the
    DATA command; the return value from this method is the final
    response code received when the all data is sent.  If msg
    is a string, lone '\\r' and '\\n' characters are converted to
    '\\r\\n' characters.  If msg is bytes, it is transmitted as is."""
    self.putcmd('data')
    code, repl = self.getreply()
    if self.debuglevel > 0:
        self._print_debug('data:', (code, repl))
    if code != 354:
        raise SMTPDataError(code, repl)
    else:
        if isinstance(msg, str):
            msg = _fix_eols(msg).encode('ascii')
        q = _quote_periods(msg)
        if q[-2:] != bCRLF:
            q = q + bCRLF
        q = q + b'.' + bCRLF
        self.send(q)
        code, msg = self.getreply()
        if self.debuglevel > 0:
            self._print_debug('data:', (code, msg))
        return (code, msg)

def verify(self, address):
    """SMTP 'verify' command -- checks for address validity."""
    self.putcmd('vrfy', _addr_only(address))
    return self.getreply()

def expn(self, address):
    """SMTP 'expn' command -- expands a mailing list."""
    self.putcmd('expn', _addr_only(address))
    return self.getreply()

def ehlo_or_helo_if_needed(self):
    """Call self.ehlo() and/or self.helo() if needed.

    If there has been no previous EHLO or HELO command this session, this
    method tries ESMTP EHLO first.

    This method may raise the following exceptions:

     SMTPHeloError            The server didn't reply properly to
                              the helo greeting."""
    if self.helo_resp is None and self.ehlo_resp is None:
        if not 200 <= self.ehlo()[0] <= 299:
            code, resp = self.helo()
            if not 200 <= code <= 299:
                raise SMTPHeloError(code, resp)

def auth_cram_md5(self, challenge=None):
    """Authobject to use with CRAM-MD5 authentication. Requires self.user
    and self.password to be set."""
    if challenge is None:
        return None
    return self.user + ' ' + hmac.HMAC(self.password.encode('ascii'), challenge, 'md5').hexdigest()

def auth_plain(self, challenge=None):
    """Authobject to use with PLAIN authentication. Requires self.user and
    self.password to be set."""
    return '\x00%s\x00%s' % (self.user, self.password)

def auth_login(self, challenge=None):
    """Authobject to use with LOGIN authentication. Requires self.user and
    self.password to be set."""
    if challenge is None or self._auth_challenge_count < 2:
        return self.user
    else:
        return self.password

def close(self):
    """Close the connection to the SMTP server."""
    try:
        file = self.file
        self.file = None
        if file:
            file.close()
    finally:
        sock = self.sock
        self.sock = None
        if sock:
            sock.close()

def __init__(self, host='', port=LMTP_PORT, local_hostname=None, source_address=None, timeout=socket._GLOBAL_DEFAULT_TIMEOUT):
    """Initialize a new instance."""
    super().__init__(host, port, local_hostname=local_hostname, source_address=source_address, timeout=timeout)

def connect(self, host='localhost', port=0, source_address=None):
    """Connect to the LMTP daemon, on either a Unix or a TCP socket."""
    if host[0] != '/':
        return super().connect(host, port, source_address=source_address)
    if self.timeout is not None and (not self.timeout):
        raise ValueError('Non-blocking socket (timeout=0) is not supported')
    try:
        self.sock = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        if self.timeout is not socket._GLOBAL_DEFAULT_TIMEOUT:
            self.sock.settimeout(self.timeout)
        self.file = None
        self.sock.connect(host)
    except OSError:
        if self.debuglevel > 0:
            self._print_debug('connect fail:', host)
        if self.sock:
            self.sock.close()
        self.sock = None
        raise
    code, msg = self.getreply()
    if self.debuglevel > 0:
        self._print_debug('connect:', msg)
    return (code, msg)

