def _intenum_converter(value, enum_klass):
    """Convert a numeric family value to an IntEnum member.

    If it's not a known member, return the numeric value itself."""
    try:
        return enum_klass(value)
    except ValueError:
        return value

def fromfd(fd, family, type, proto=0):
    """fromfd(fd, family, type[, proto]) -> socket object

    Create a socket object from a duplicate of the given file
    descriptor.  The remaining arguments are the same as for socket()."""
    nfd = dup(fd)
    return socket(family, type, proto, nfd)

def _fallback_socketpair(family=AF_INET, type=SOCK_STREAM, proto=0):
    if family == AF_INET:
        host = _LOCALHOST
    elif family == AF_INET6:
        host = _LOCALHOST_V6
    else:
        raise ValueError('Only AF_INET and AF_INET6 socket address families are supported')
    if type != SOCK_STREAM:
        raise ValueError('Only SOCK_STREAM socket type is supported')
    if proto != 0:
        raise ValueError('Only protocol zero is supported')
    lsock = socket(family, type, proto)
    try:
        lsock.bind((host, 0))
        lsock.listen()
        addr, port = lsock.getsockname()[:2]
        csock = socket(family, type, proto)
        try:
            csock.setblocking(False)
            try:
                csock.connect((addr, port))
            except (BlockingIOError, InterruptedError):
                pass
            csock.setblocking(True)
            ssock, _ = lsock.accept()
        except:
            csock.close()
            raise
    finally:
        lsock.close()
    try:
        if ssock.getsockname() != csock.getpeername() or csock.getsockname() != ssock.getpeername():
            raise ConnectionError('Unexpected peer connection')
    except:
        ssock.close()
        csock.close()
        raise
    return (ssock, csock)

def getfqdn(name=''):
    """Get fully qualified domain name from name.

    An empty argument is interpreted as meaning the local host.

    First the hostname returned by gethostbyaddr() is checked, then
    possibly existing aliases. In case no FQDN is available and `name`
    was given, it is returned unchanged. If `name` was empty, '0.0.0.0' or '::',
    hostname from gethostname() is returned."""
    name = name.strip()
    if not name or name in ('0.0.0.0', '::'):
        name = gethostname()
    try:
        hostname, aliases, ipaddrs = gethostbyaddr(name)
    except error:
        pass
    else:
        aliases.insert(0, hostname)
        for name in aliases:
            if '.' in name:
                break
        else:
            name = hostname
    return name

def has_dualstack_ipv6():
    """Return True if the platform supports creating a SOCK_STREAM socket
    which can handle both AF_INET and AF_INET6 (IPv4 / IPv6) connections."""
    if not has_ipv6 or not hasattr(_socket, 'IPPROTO_IPV6') or (not hasattr(_socket, 'IPV6_V6ONLY')):
        return False
    try:
        with socket(AF_INET6, SOCK_STREAM) as sock:
            sock.setsockopt(IPPROTO_IPV6, IPV6_V6ONLY, 0)
            return True
    except error:
        return False

def __exit__(self, *args):
    if not self._closed:
        self.close()

def __repr__(self):
    """Wrap __repr__() to reveal the real class name and socket
    address(es)."""
    closed = getattr(self, '_closed', False)
    s = '<%s.%s%s fd=%i, family=%s, type=%s, proto=%i' % (self.__class__.__module__, self.__class__.__qualname__, ' [closed]' if closed else '', self.fileno(), self.family, self.type, self.proto)
    if not closed:
        try:
            laddr = self.getsockname()
            if laddr:
                s += ', laddr=%s' % str(laddr)
        except (error, AttributeError):
            pass
        try:
            raddr = self.getpeername()
            if raddr:
                s += ', raddr=%s' % str(raddr)
        except (error, AttributeError):
            pass
    s += '>'
    return s

def accept(self):
    """accept() -> (socket object, address info)

    Wait for an incoming connection.  Return a new socket
    representing the connection, and the address of the client.
    For IP sockets, the address info is a pair (hostaddr, port)."""
    fd, addr = self._accept()
    sock = socket(self.family, self.type, self.proto, fileno=fd)
    if getdefaulttimeout() is None and self.gettimeout():
        sock.setblocking(True)
    return (sock, addr)

def makefile(self, mode='r', buffering=None, *, encoding=None, errors=None, newline=None):
    """makefile(...) -> an I/O stream connected to the socket

    The arguments are as for io.open() after the filename, except the only
    supported mode values are 'r' (default), 'w', 'b', or a combination of
    those."""
    if not set(mode) <= {'r', 'w', 'b'}:
        raise ValueError('invalid mode %r (only r, w, b allowed)' % (mode,))
    writing = 'w' in mode
    reading = 'r' in mode or not writing
    assert reading or writing
    binary = 'b' in mode
    rawmode = ''
    if reading:
        rawmode += 'r'
    if writing:
        rawmode += 'w'
    raw = SocketIO(self, rawmode)
    self._io_refs += 1
    if buffering is None:
        buffering = -1
    if buffering < 0:
        buffering = io.DEFAULT_BUFFER_SIZE
    if buffering == 0:
        if not binary:
            raise ValueError('unbuffered streams must be binary')
        return raw
    if reading and writing:
        buffer = io.BufferedRWPair(raw, raw, buffering)
    elif reading:
        buffer = io.BufferedReader(raw, buffering)
    else:
        assert writing
        buffer = io.BufferedWriter(raw, buffering)
    if binary:
        return buffer
    encoding = io.text_encoding(encoding)
    text = io.TextIOWrapper(buffer, encoding, errors, newline)
    text.mode = mode
    return text

def _sendfile_use_send(self, file, offset=0, count=None):
    self._check_sendfile_params(file, offset, count)
    if self.gettimeout() == 0:
        raise ValueError('non-blocking sockets are not supported')
    if offset:
        file.seek(offset)
    blocksize = min(count, 8192) if count else 8192
    total_sent = 0
    file_read = file.read
    sock_send = self.send
    try:
        while True:
            if count:
                blocksize = min(count - total_sent, blocksize)
                if blocksize <= 0:
                    break
            data = memoryview(file_read(blocksize))
            if not data:
                break
            while True:
                try:
                    sent = sock_send(data)
                except BlockingIOError:
                    continue
                else:
                    total_sent += sent
                    if sent < len(data):
                        data = data[sent:]
                    else:
                        break
        return total_sent
    finally:
        if total_sent > 0 and hasattr(file, 'seek'):
            file.seek(offset + total_sent)

def _decref_socketios(self):
    if self._io_refs > 0:
        self._io_refs -= 1
    if self._closed:
        self.close()

def close(self):
    self._closed = True
    if self._io_refs <= 0:
        self._real_close()

@property
def family(self):
    """Read-only access to the address family for this socket.
    """
    return _intenum_converter(super().family, AddressFamily)

@property
def type(self):
    """Read-only access to the socket type.
    """
    return _intenum_converter(super().type, SocketKind)

def send_fds(sock, buffers, fds, flags=0, address=None):
    """send_fds(sock, buffers, fds[, flags[, address]]) -> integer

    Send the list of file descriptors fds over an AF_UNIX socket."""
    return sock.sendmsg(buffers, [(_socket.SOL_SOCKET, _socket.SCM_RIGHTS, array.array('i', fds))])

def recv_fds(sock, bufsize, maxfds, flags=0):
    """recv_fds(sock, bufsize, maxfds[, flags]) -> (data, list of file
    descriptors, msg_flags, address)

    Receive up to maxfds file descriptors returning the message
    data and a list containing the descriptors."""
    fds = array.array('i')
    msg, ancdata, flags, addr = sock.recvmsg(bufsize, _socket.CMSG_LEN(maxfds * fds.itemsize))
    for cmsg_level, cmsg_type, cmsg_data in ancdata:
        if cmsg_level == _socket.SOL_SOCKET and cmsg_type == _socket.SCM_RIGHTS:
            fds.frombytes(cmsg_data[:len(cmsg_data) - len(cmsg_data) % fds.itemsize])
    return (msg, list(fds), flags, addr)

def fromshare(info):
    """fromshare(info) -> socket object

    Create a socket object from the bytes object returned by
    socket.share(pid)."""
    return socket(0, 0, 0, info)

def socketpair(family=None, type=SOCK_STREAM, proto=0):
    if family is None:
        try:
            family = AF_UNIX
        except NameError:
            family = AF_INET
    a, b = _socket.socketpair(family, type, proto)
    a = socket(family, type, proto, a.detach())
    b = socket(family, type, proto, b.detach())
    return (a, b)

def readinto(self, b):
    """Read up to len(b) bytes into the writable buffer *b* and return
    the number of bytes read.  If the socket is non-blocking and no bytes
    are available, None is returned.

    If *b* is non-empty, a 0 return value indicates that the connection
    was shutdown at the other end."""
    self._checkClosed()
    self._checkReadable()
    if self._timeout_occurred:
        raise OSError('cannot read from timed out object')
    while True:
        try:
            return self._sock.recv_into(b)
        except timeout:
            self._timeout_occurred = True
            raise
        except error as e:
            if e.errno in _blocking_errnos:
                return None
            raise

def write(self, b):
    """Write the given bytes or bytearray object *b* to the socket
    and return the number of bytes written.  This can be less than
    len(b) if not all data could be written.  If the socket is
    non-blocking and no bytes could be written None is returned."""
    self._checkClosed()
    self._checkWritable()
    try:
        return self._sock.send(b)
    except error as e:
        if e.errno in _blocking_errnos:
            return None
        raise

def writable(self):
    """True if the SocketIO is open for writing.
    """
    if self.closed:
        raise ValueError('I/O operation on closed socket.')
    return self._writing

def seekable(self):
    """True if the SocketIO is open for seeking.
    """
    if self.closed:
        raise ValueError('I/O operation on closed socket.')
    return super().seekable()

@property
def name(self):
    if not self.closed:
        return self.fileno()
    else:
        return -1

@property
def mode(self):
    return self._mode

def handle_request(self):
    """Handle one request, possibly blocking.

    Respects self.timeout."""
    timeout = self.socket.gettimeout()
    if timeout is None:
        timeout = self.timeout
    elif self.timeout is not None:
        timeout = min(timeout, self.timeout)
    if timeout is not None:
        deadline = time() + timeout
    with _ServerSelector() as selector:
        selector.register(self, selectors.EVENT_READ)
        while True:
            if selector.select(timeout):
                return self._handle_request_noblock()
            elif timeout is not None:
                timeout = deadline - time()
                if timeout < 0:
                    return self.handle_timeout()

def _handle_request_noblock(self):
    """Handle one request, without blocking.

    I assume that selector.select() has returned that the socket is
    readable before this function was called, so there should be no risk of
    blocking in get_request()."""
    try:
        request, client_address = self.get_request()
    except OSError:
        return
    if self.verify_request(request, client_address):
        try:
            self.process_request(request, client_address)
        except Exception:
            self.handle_error(request, client_address)
            self.shutdown_request(request)
        except:
            self.shutdown_request(request)
            raise
    else:
        self.shutdown_request(request)

def finish_request(self, request, client_address):
    """Finish one request by instantiating RequestHandlerClass."""
    self.RequestHandlerClass(request, client_address, self)

def shutdown_request(self, request):
    """Called to shutdown and close an individual request."""
    self.close_request(request)

def close_request(self, request):
    """Called to clean up an individual request."""
    pass

def __init__(self, server_address, RequestHandlerClass, bind_and_activate=True):
    """Constructor.  May be extended, do not override."""
    BaseServer.__init__(self, server_address, RequestHandlerClass)
    self.socket = socket.socket(self.address_family, self.socket_type)
    if bind_and_activate:
        try:
            self.server_bind()
            self.server_activate()
        except:
            self.server_close()
            raise

def server_bind(self):
    """Called by constructor to bind the socket.

    May be overridden."""
    if self.allow_reuse_address and hasattr(socket, 'SO_REUSEADDR'):
        self.socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    if self.allow_reuse_port and hasattr(socket, 'SO_REUSEPORT') and (self.address_family in (socket.AF_INET, socket.AF_INET6)):
        self.socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEPORT, 1)
    self.socket.bind(self.server_address)
    self.server_address = self.socket.getsockname()

def fileno(self):
    """Return socket file number.

    Interface required by selector."""
    return self.socket.fileno()

def get_request(self):
    """Get the request and client address from the socket.

    May be overridden."""
    return self.socket.accept()

def shutdown_request(self, request):
    """Called to shutdown and close an individual request."""
    try:
        request.shutdown(socket.SHUT_WR)
    except OSError:
        pass
    self.close_request(request)

def close_request(self, request):
    """Called to clean up an individual request."""
    request.close()

def get_request(self):
    data, client_addr = self.socket.recvfrom(self.max_packet_size)
    return ((data, self.socket), client_addr)

def pop_all(self):
    self[:], result = ([], self[:])
    return result

def join(self):
    for thread in self.pop_all():
        thread.join()

def process_request_thread(self, request, client_address):
    """Same as in BaseServer but as a thread.

    In addition, exception handling is done here."""
    try:
        self.finish_request(request, client_address)
    except Exception:
        self.handle_error(request, client_address)
    finally:
        self.shutdown_request(request)

def server_close(self):
    super().server_close()
    self._threads.join()

def setup(self):
    self.connection = self.request
    if self.timeout is not None:
        self.connection.settimeout(self.timeout)
    if self.disable_nagle_algorithm:
        self.connection.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, True)
    self.rfile = self.connection.makefile('rb', self.rbufsize)
    if self.wbufsize == 0:
        self.wfile = _SocketWriter(self.connection)
    else:
        self.wfile = self.connection.makefile('wb', self.wbufsize)

def finish(self):
    if not self.wfile.closed:
        try:
            self.wfile.flush()
        except socket.error:
            pass
    self.wfile.close()
    self.rfile.close()

def collect_children(self, *, blocking=False):
    """Internal routine to wait for children that have exited."""
    if self.active_children is None:
        return
    while len(self.active_children) >= self.max_children:
        try:
            pid, _ = os.waitpid(-1, 0)
            self.active_children.discard(pid)
        except ChildProcessError:
            self.active_children.clear()
        except OSError:
            break
    for pid in self.active_children.copy():
        try:
            flags = 0 if blocking else os.WNOHANG
            pid, _ = os.waitpid(pid, flags)
            self.active_children.discard(pid)
        except ChildProcessError:
            self.active_children.discard(pid)
        except OSError:
            pass

def process_request(self, request, client_address):
    """Fork a new subprocess to process the request."""
    pid = os.fork()
    if pid:
        if self.active_children is None:
            self.active_children = set()
        self.active_children.add(pid)
        self.close_request(request)
        return
    else:
        status = 1
        try:
            self.finish_request(request, client_address)
            status = 0
        except Exception:
            self.handle_error(request, client_address)
        finally:
            try:
                self.shutdown_request(request)
            finally:
                os._exit(status)

def server_close(self):
    super().server_close()
    self.collect_children(blocking=self.block_on_close)

def __getattr__(name):
    if name in _deprecated_names:
        from warnings import warn
        warn(f'{name} is deprecated and will be removed in Python 3.14', DeprecationWarning, stacklevel=2)
        return globals()[f'_deprecated_{name}']
    raise AttributeError(f'module {__name__!r} has no attribute {name!r}')

def execute(c, sql, suppress_errors=True):
    """Helper that wraps execution of SQL code.

    This is used both by the REPL and by direct execution from the CLI.

    'c' may be a cursor or a connection.
    'sql' is the SQL string to execute."""
    try:
        for row in c.execute(sql):
            print(row)
    except sqlite3.Error as e:
        tp = type(e).__name__
        try:
            print(f'{tp} ({e.sqlite_errorname}): {e}', file=sys.stderr)
        except AttributeError:
            print(f'{tp}: {e}', file=sys.stderr)
        if not suppress_errors:
            sys.exit(1)

def register_adapters_and_converters():
    from warnings import warn
    msg = 'The default {what} is deprecated as of Python 3.12; see the sqlite3 documentation for suggested replacement recipes'
    def adapt_date(val):
        warn(msg.format(what='date adapter'), DeprecationWarning, stacklevel=2)
        return val.isoformat()
    def adapt_datetime(val):
        warn(msg.format(what='datetime adapter'), DeprecationWarning, stacklevel=2)
        return val.isoformat(' ')
    def convert_date(val):
        warn(msg.format(what='date converter'), DeprecationWarning, stacklevel=2)
        return datetime.date(*map(int, val.split(b'-')))
    def convert_timestamp(val):
        warn(msg.format(what='timestamp converter'), DeprecationWarning, stacklevel=2)
        datepart, timepart = val.split(b' ')
        year, month, day = map(int, datepart.split(b'-'))
        timepart_full = timepart.split(b'.')
        hours, minutes, seconds = map(int, timepart_full[0].split(b':'))
        if len(timepart_full) == 2:
            microseconds = int('{:0<6.6}'.format(timepart_full[1].decode()))
        else:
            microseconds = 0
        val = datetime.datetime(year, month, day, hours, minutes, seconds, microseconds)
        return val
    register_adapter(datetime.date, adapt_date)
    register_adapter(datetime.datetime, adapt_datetime)
    register_converter('date', convert_date)
    register_converter('timestamp', convert_timestamp)

