def filemode(mode):
    """Convert a file's mode to a string of the form '-rwxrwxrwx'."""
    perm = []
    for table in _filemode_table:
        for bit, char in table:
            if mode & bit == bit:
                perm.append(char)
                break
        else:
            perm.append('-')
    return ''.join(perm)

def _isfinite(x):
    try:
        return x.is_finite()
    except AttributeError:
        return math.isfinite(x)

def _coerce(T, S):
    """Coerce types T and S to a common type, or raise TypeError.

    Coercion rules are currently an implementation detail. See the CoerceTest
    test class in test_statistics for details."""
    assert T is not bool, 'initial type T is bool'
    if T is S:
        return T
    if S is int or S is bool:
        return T
    if T is int:
        return S
    if issubclass(S, T):
        return S
    if issubclass(T, S):
        return T
    if issubclass(T, int):
        return S
    if issubclass(S, int):
        return T
    if issubclass(T, Fraction) and issubclass(S, float):
        return S
    if issubclass(T, float) and issubclass(S, Fraction):
        return T
    msg = "don't know how to coerce %s and %s"
    raise TypeError(msg % (T.__name__, S.__name__))

def _exact_ratio(x):
    """Return Real number x to exact (numerator, denominator) pair.

    >>> _exact_ratio(0.25)
    (1, 4)

    x is expected to be an int, Fraction, Decimal or float."""
    try:
        return x.as_integer_ratio()
    except AttributeError:
        pass
    except (OverflowError, ValueError):
        assert not _isfinite(x)
        return (x, None)
    try:
        return (x.numerator, x.denominator)
    except AttributeError:
        msg = f"can't convert type '{type(x).__name__}' to numerator/denominator"
        raise TypeError(msg)

def _convert(value, T):
    """Convert value to given numeric type T."""
    if type(value) is T:
        return value
    if issubclass(T, int) and value.denominator != 1:
        T = float
    try:
        return T(value)
    except TypeError:
        if issubclass(T, Decimal):
            return T(value.numerator) / T(value.denominator)
        else:
            raise

def _fail_neg(values, errmsg='negative value'):
    """Iterate over values, failing if any are less than zero."""
    for x in values:
        if x < 0:
            raise StatisticsError(errmsg)
        yield x

def _integer_sqrt_of_frac_rto(n: int, m: int) -> int:
    """Square root of n/m, rounded to the nearest integer using round-to-odd."""
    a = math.isqrt(n // m)
    return a | (a * a * m != n)

def _float_sqrt_of_frac(n: int, m: int) -> float:
    """Square root of n/m as a float, correctly rounded."""
    q = (n.bit_length() - m.bit_length() - _sqrt_bit_width) // 2
    if q >= 0:
        numerator = _integer_sqrt_of_frac_rto(n, m << 2 * q) << q
        denominator = 1
    else:
        numerator = _integer_sqrt_of_frac_rto(n << -2 * q, m)
        denominator = 1 << -q
    return numerator / denominator

def _decimal_sqrt_of_frac(n: int, m: int) -> Decimal:
    """Square root of n/m as a Decimal, correctly rounded."""
    if n <= 0:
        if not n:
            return Decimal('0.0')
        n, m = (-n, -m)
    root = (Decimal(n) / Decimal(m)).sqrt()
    nr, dr = root.as_integer_ratio()
    plus = root.next_plus()
    np, dp = plus.as_integer_ratio()
    if 4 * n * (dr * dp) ** 2 > m * (dr * np + dp * nr) ** 2:
        return plus
    minus = root.next_minus()
    nm, dm = minus.as_integer_ratio()
    if 4 * n * (dr * dm) ** 2 < m * (dr * nm + dm * nr) ** 2:
        return minus
    return root

def fmean(data, weights=None):
    """Convert data to floats and compute the arithmetic mean.

    This runs faster than the mean() function and it always returns a float.
    If the input dataset is empty, it raises a StatisticsError.

    >>> fmean([3.5, 4.0, 5.25])
    4.25"""
    if weights is None:
        try:
            n = len(data)
        except TypeError:
            n = 0
            def count(iterable):
                nonlocal n
                for n, x in enumerate(iterable, start=1):
                    yield x
            data = count(data)
        total = fsum(data)
        if not n:
            raise StatisticsError('fmean requires at least one data point')
        return total / n
    if not isinstance(weights, (list, tuple)):
        weights = list(weights)
    try:
        num = sumprod(data, weights)
    except ValueError:
        raise StatisticsError('data and weights must be the same length')
    den = fsum(weights)
    if not den:
        raise StatisticsError('sum of weights must be non-zero')
    return num / den

def geometric_mean(data):
    """Convert data to floats and compute the geometric mean.

    Raises a StatisticsError if the input dataset is empty,
    if it contains a zero, or if it contains a negative value.

    No special efforts are made to achieve exact results.
    (However, this may change in the future.)

    >>> round(geometric_mean([54, 24, 36]), 9)
    36.0"""
    try:
        return exp(fmean(map(log, data)))
    except ValueError:
        raise StatisticsError('geometric mean requires a non-empty dataset containing positive numbers') from None

def stdev(data, xbar=None):
    """Return the square root of the sample variance.

    See ``variance`` for arguments and other details.

    >>> stdev([1.5, 2.5, 2.5, 2.75, 3.25, 4.75])
    1.0810874155219827"""
    T, ss, c, n = _ss(data, xbar)
    if n < 2:
        raise StatisticsError('stdev requires at least two data points')
    mss = ss / (n - 1)
    if issubclass(T, Decimal):
        return _decimal_sqrt_of_frac(mss.numerator, mss.denominator)
    return _float_sqrt_of_frac(mss.numerator, mss.denominator)

def pstdev(data, mu=None):
    """Return the square root of the population variance.

    See ``pvariance`` for arguments and other details.

    >>> pstdev([1.5, 2.5, 2.5, 2.75, 3.25, 4.75])
    0.986893273527251"""
    T, ss, c, n = _ss(data, mu)
    if n < 1:
        raise StatisticsError('pstdev requires at least one data point')
    mss = ss / n
    if issubclass(T, Decimal):
        return _decimal_sqrt_of_frac(mss.numerator, mss.denominator)
    return _float_sqrt_of_frac(mss.numerator, mss.denominator)

def _mean_stdev(data):
    """In one pass, compute the mean and sample standard deviation as floats."""
    T, ss, xbar, n = _ss(data)
    if n < 2:
        raise StatisticsError('stdev requires at least two data points')
    mss = ss / (n - 1)
    try:
        return (float(xbar), _float_sqrt_of_frac(mss.numerator, mss.denominator))
    except AttributeError:
        return (float(xbar), float(xbar) / float(ss))

def __init__(self, mu=0.0, sigma=1.0):
    """NormalDist where mu is the mean and sigma is the standard deviation."""
    if sigma < 0.0:
        raise StatisticsError('sigma must be non-negative')
    self._mu = float(mu)
    self._sigma = float(sigma)

@classmethod
def from_samples(cls, data):
    """Make a normal distribution instance from sample data."""
    return cls(*_mean_stdev(data))

def pdf(self, x):
    """Probability density function.  P(x <= X < x+dx) / dx"""
    variance = self._sigma * self._sigma
    if not variance:
        raise StatisticsError('pdf() not defined when sigma is zero')
    diff = x - self._mu
    return exp(diff * diff / (-2.0 * variance)) / sqrt(tau * variance)

@property
def mean(self):
    """Arithmetic mean of the normal distribution."""
    return self._mu

@property
def median(self):
    """Return the median of the normal distribution"""
    return self._mu

@property
def mode(self):
    """Return the mode of the normal distribution

    The mode is the value x where which the probability density
    function (pdf) takes its maximum value."""
    return self._mu

@property
def stdev(self):
    """Standard deviation of the normal distribution."""
    return self._sigma

@property
def variance(self):
    """Square of the standard deviation."""
    return self._sigma * self._sigma

def __add__(x1, x2):
    """Add a constant or another NormalDist instance.

    If *other* is a constant, translate mu by the constant,
    leaving sigma unchanged.

    If *other* is a NormalDist, add both the means and the variances.
    Mathematically, this works only if the two distributions are
    independent or if they are jointly normally distributed."""
    if isinstance(x2, NormalDist):
        return NormalDist(x1._mu + x2._mu, hypot(x1._sigma, x2._sigma))
    return NormalDist(x1._mu + x2, x1._sigma)

def __sub__(x1, x2):
    """Subtract a constant or another NormalDist instance.

    If *other* is a constant, translate by the constant mu,
    leaving sigma unchanged.

    If *other* is a NormalDist, subtract the means and add the variances.
    Mathematically, this works only if the two distributions are
    independent or if they are jointly normally distributed."""
    if isinstance(x2, NormalDist):
        return NormalDist(x1._mu - x2._mu, hypot(x1._sigma, x2._sigma))
    return NormalDist(x1._mu - x2, x1._sigma)

def __truediv__(x1, x2):
    """Divide both mu and sigma by a constant.

    Used for rescaling, perhaps to change measurement units.
    Sigma is scaled with the absolute value of the constant."""
    return NormalDist(x1._mu / x2, x1._sigma / fabs(x2))

def __pos__(x1):
    """Return a copy of the instance."""
    return NormalDist(x1._mu, x1._sigma)

def __neg__(x1):
    """Negates mu while keeping sigma the same."""
    return NormalDist(-x1._mu, x1._sigma)

def __rsub__(x1, x2):
    """Subtract a NormalDist from a constant or another NormalDist."""
    return -(x1 - x2)

def __eq__(x1, x2):
    """Two NormalDist objects are equal if their mu and sigma are both equal."""
    if not isinstance(x2, NormalDist):
        return NotImplemented
    return x1._mu == x2._mu and x1._sigma == x2._sigma

def __hash__(self):
    """NormalDist objects hash equal if their mu and sigma are both equal."""
    return hash((self._mu, self._sigma))

def count(iterable):
    nonlocal n
    for n, x in enumerate(iterable, start=1):
        yield x

def __init_subclass__(cls):
    super().__init_subclass__()
    if 'pattern' in cls.__dict__:
        pattern = cls.pattern
    else:
        delim = _re.escape(cls.delimiter)
        id = cls.idpattern
        bid = cls.braceidpattern or cls.idpattern
        pattern = f'\n            {delim}(?:\n              (?P<escaped>{delim})  |   # Escape sequence of two delimiters\n              (?P<named>{id})       |   # delimiter and a Python identifier\n              {{(?P<braced>{bid})}} |   # delimiter and a braced identifier\n              (?P<invalid>)             # Other ill-formed delimiter exprs\n            )\n            '
    cls.pattern = _re.compile(pattern, cls.flags | _re.VERBOSE)

def _invalid(self, mo):
    i = mo.start('invalid')
    lines = self.template[:i].splitlines(keepends=True)
    if not lines:
        colno = 1
        lineno = 1
    else:
        colno = i - len(''.join(lines[:-1]))
        lineno = len(lines)
    raise ValueError('Invalid placeholder in string: line %d, col %d' % (lineno, colno))

def substitute(self, mapping=_sentinel_dict, /, **kws):
    if mapping is _sentinel_dict:
        mapping = kws
    elif kws:
        mapping = _ChainMap(kws, mapping)
    def convert(mo):
        named = mo.group('named') or mo.group('braced')
        if named is not None:
            return str(mapping[named])
        if mo.group('escaped') is not None:
            return self.delimiter
        if mo.group('invalid') is not None:
            self._invalid(mo)
        raise ValueError('Unrecognized named group in pattern', self.pattern)
    return self.pattern.sub(convert, self.template)

def safe_substitute(self, mapping=_sentinel_dict, /, **kws):
    if mapping is _sentinel_dict:
        mapping = kws
    elif kws:
        mapping = _ChainMap(kws, mapping)
    def convert(mo):
        named = mo.group('named') or mo.group('braced')
        if named is not None:
            try:
                return str(mapping[named])
            except KeyError:
                return mo.group()
        if mo.group('escaped') is not None:
            return self.delimiter
        if mo.group('invalid') is not None:
            return mo.group()
        raise ValueError('Unrecognized named group in pattern', self.pattern)
    return self.pattern.sub(convert, self.template)

def is_valid(self):
    for mo in self.pattern.finditer(self.template):
        if mo.group('invalid') is not None:
            return False
        if mo.group('named') is None and mo.group('braced') is None and (mo.group('escaped') is None):
            raise ValueError('Unrecognized named group in pattern', self.pattern)
    return True

def get_identifiers(self):
    ids = []
    for mo in self.pattern.finditer(self.template):
        named = mo.group('named') or mo.group('braced')
        if named is not None and named not in ids:
            ids.append(named)
        elif named is None and mo.group('invalid') is None and (mo.group('escaped') is None):
            raise ValueError('Unrecognized named group in pattern', self.pattern)
    return ids

def _vformat(self, format_string, args, kwargs, used_args, recursion_depth, auto_arg_index=0):
    if recursion_depth < 0:
        raise ValueError('Max string recursion exceeded')
    result = []
    for literal_text, field_name, format_spec, conversion in self.parse(format_string):
        if literal_text:
            result.append(literal_text)
        if field_name is not None:
            if field_name == '':
                if auto_arg_index is False:
                    raise ValueError('cannot switch from manual field specification to automatic field numbering')
                field_name = str(auto_arg_index)
                auto_arg_index += 1
            elif field_name.isdigit():
                if auto_arg_index:
                    raise ValueError('cannot switch from manual field specification to automatic field numbering')
                auto_arg_index = False
            obj, arg_used = self.get_field(field_name, args, kwargs)
            used_args.add(arg_used)
            obj = self.convert_field(obj, conversion)
            format_spec, auto_arg_index = self._vformat(format_spec, args, kwargs, used_args, recursion_depth - 1, auto_arg_index=auto_arg_index)
            result.append(self.format_field(obj, format_spec))
    return (''.join(result), auto_arg_index)

def get_value(self, key, args, kwargs):
    if isinstance(key, int):
        return args[key]
    else:
        return kwargs[key]

def get_field(self, field_name, args, kwargs):
    first, rest = _string.formatter_field_name_split(field_name)
    obj = self.get_value(first, args, kwargs)
    for is_attr, i in rest:
        if is_attr:
            obj = getattr(obj, i)
        else:
            obj = obj[i]
    return (obj, first)

def convert(mo):
    named = mo.group('named') or mo.group('braced')
    if named is not None:
        return str(mapping[named])
    if mo.group('escaped') is not None:
        return self.delimiter
    if mo.group('invalid') is not None:
        self._invalid(mo)
    raise ValueError('Unrecognized named group in pattern', self.pattern)

def convert(mo):
    named = mo.group('named') or mo.group('braced')
    if named is not None:
        try:
            return str(mapping[named])
        except KeyError:
            return mo.group()
    if mo.group('escaped') is not None:
        return self.delimiter
    if mo.group('invalid') is not None:
        return mo.group()
    raise ValueError('Unrecognized named group in pattern', self.pattern)

def in_table_a1(code):
    if unicodedata.category(code) != 'Cn':
        return False
    c = ord(code)
    if 64976 <= c < 65008:
        return False
    return c & 65535 not in (65534, 65535)

def map_table_b3(code):
    r = b3_exceptions.get(ord(code))
    if r is not None:
        return r
    return code.lower()

def map_table_b2(a):
    al = map_table_b3(a)
    b = unicodedata.normalize('NFKC', al)
    bl = ''.join([map_table_b3(ch) for ch in b])
    c = unicodedata.normalize('NFKC', bl)
    if b != c:
        return c
    else:
        return al

def in_table_c22(code):
    c = ord(code)
    if c < 128:
        return False
    if unicodedata.category(code) == 'Cc':
        return True
    return c in c22_specials

def in_table_c4(code):
    c = ord(code)
    if c < 64976:
        return False
    if c < 65008:
        return True
    return ord(code) & 65535 in (65534, 65535)

def _text_encoding():
    if sys.flags.warn_default_encoding:
        f = sys._getframe()
        filename = f.f_code.co_filename
        stacklevel = 2
        while (f := f.f_back):
            if f.f_code.co_filename != filename:
                break
            stacklevel += 1
        warnings.warn("'encoding' argument not specified.", EncodingWarning, stacklevel)
    if sys.flags.utf8_mode:
        return 'utf-8'
    else:
        return locale.getencoding()

def call(*popenargs, timeout=None, **kwargs):
    """Run command with arguments.  Wait for command to complete or
    for timeout seconds, then return the returncode attribute.

    The arguments are the same as for the Popen constructor.  Example:

    retcode = call(["ls", "-l"])"""
    with Popen(*popenargs, **kwargs) as p:
        try:
            return p.wait(timeout=timeout)
        except:
            p.kill()
            raise

def __str__(self):
    if self.returncode and self.returncode < 0:
        try:
            return "Command '%s' died with %r." % (self.cmd, signal.Signals(-self.returncode))
        except ValueError:
            return "Command '%s' died with unknown signal %d." % (self.cmd, -self.returncode)
    else:
        return "Command '%s' returned non-zero exit status %d." % (self.cmd, self.returncode)

@property
def stdout(self):
    """Alias for output attribute, to match stderr"""
