def __exit__(self, exc_type, value, traceback):
    if self.stdout:
        self.stdout.close()
    if self.stderr:
        self.stderr.close()
    try:
        if self.stdin:
            self.stdin.close()
    finally:
        if exc_type == KeyboardInterrupt:
            if self._sigint_wait_secs > 0:
                try:
                    self._wait(timeout=self._sigint_wait_secs)
                except TimeoutExpired:
                    pass
            self._sigint_wait_secs = 0
            return
        self.wait()

def __del__(self, _maxsize=sys.maxsize, _warn=warnings.warn):
    if not self._child_created:
        return
    if self.returncode is None:
        _warn('subprocess %s is still running' % self.pid, ResourceWarning, source=self)
    self._internal_poll(_deadstate=_maxsize)
    if self.returncode is None and _active is not None:
        _active.append(self)

def _get_devnull(self):
    if not hasattr(self, '_devnull'):
        self._devnull = os.open(os.devnull, os.O_RDWR)
    return self._devnull

def _stdin_write(self, input):
    if input:
        try:
            self.stdin.write(input)
        except BrokenPipeError:
            pass
        except OSError as exc:
            if exc.errno == errno.EINVAL:
                pass
            else:
                raise
    try:
        self.stdin.close()
    except BrokenPipeError:
        pass
    except OSError as exc:
        if exc.errno == errno.EINVAL:
            pass
        else:
            raise

def poll(self):
    """Check if child process has terminated. Set and return returncode
    attribute."""
    return self._internal_poll()

def _remaining_time(self, endtime):
    """Convenience for _communicate when computing timeouts."""
    if endtime is None:
        return None
    else:
        return endtime - _time()

def _check_timeout(self, endtime, orig_timeout, stdout_seq, stderr_seq, skip_check_and_raise=False):
    """Convenience for checking if a timeout has expired."""
    if endtime is None:
        return
    if skip_check_and_raise or _time() > endtime:
        raise TimeoutExpired(self.args, orig_timeout, output=b''.join(stdout_seq) if stdout_seq else None, stderr=b''.join(stderr_seq) if stderr_seq else None)

def wait(self, timeout=None):
    """Wait for child process to terminate; returns self.returncode."""
    if timeout is not None:
        endtime = _time() + timeout
    try:
        return self._wait(timeout=timeout)
    except KeyboardInterrupt:
        if timeout is not None:
            sigint_timeout = min(self._sigint_wait_secs, self._remaining_time(endtime))
        else:
            sigint_timeout = self._sigint_wait_secs
        self._sigint_wait_secs = 0
        try:
            self._wait(timeout=sigint_timeout)
        except TimeoutExpired:
            pass
        raise

def _close_pipe_fds(self, p2cread, p2cwrite, c2pread, c2pwrite, errread, errwrite):
    devnull_fd = getattr(self, '_devnull', None)
    with contextlib.ExitStack() as stack:
        if _mswindows:
            if p2cread != -1:
                stack.callback(p2cread.Close)
            if c2pwrite != -1:
                stack.callback(c2pwrite.Close)
            if errwrite != -1:
                stack.callback(errwrite.Close)
        else:
            if p2cread != -1 and p2cwrite != -1 and (p2cread != devnull_fd):
                stack.callback(os.close, p2cread)
            if c2pwrite != -1 and c2pread != -1 and (c2pwrite != devnull_fd):
                stack.callback(os.close, c2pwrite)
            if errwrite != -1 and errread != -1 and (errwrite != devnull_fd):
                stack.callback(os.close, errwrite)
        if devnull_fd is not None:
            stack.callback(os.close, devnull_fd)
    self._closed_child_pipe_fds = True

@contextlib.contextmanager
def _on_error_fd_closer(self):
    """Helper to ensure file descriptors opened in _get_handles are closed"""
    to_close = []
    try:
        yield to_close
    except:
        if hasattr(self, '_devnull'):
            to_close.append(self._devnull)
            del self._devnull
        for fd in to_close:
            try:
                if _mswindows and isinstance(fd, Handle):
                    fd.Close()
                else:
                    os.close(fd)
            except OSError:
                pass
        raise

def copy(self):
    attr_list = self.lpAttributeList.copy()
    if 'handle_list' in attr_list:
        attr_list['handle_list'] = list(attr_list['handle_list'])
    return STARTUPINFO(dwFlags=self.dwFlags, hStdInput=self.hStdInput, hStdOutput=self.hStdOutput, hStdError=self.hStdError, wShowWindow=self.wShowWindow, lpAttributeList=attr_list)

def Close(self, CloseHandle=_winapi.CloseHandle):
    if not self.closed:
        self.closed = True
        CloseHandle(self)

def Detach(self):
    if not self.closed:
        self.closed = True
        return int(self)
    raise ValueError('already closed')

def _make_inheritable(self, handle):
    """Return a duplicate of handle, which is inheritable"""
    h = _winapi.DuplicateHandle(_winapi.GetCurrentProcess(), handle, _winapi.GetCurrentProcess(), 0, 1, _winapi.DUPLICATE_SAME_ACCESS)
    return Handle(h)

def _filter_handle_list(self, handle_list):
    """Filter out console handles that can't be used
    in lpAttributeList["handle_list"] and make sure the list
    isn't empty. This also removes duplicate handles."""
    return list({handle for handle in handle_list if handle & 3 != 3 or _winapi.GetFileType(handle) != _winapi.FILE_TYPE_CHAR})

def _internal_poll(self, _deadstate=None, _WaitForSingleObject=_winapi.WaitForSingleObject, _WAIT_OBJECT_0=_winapi.WAIT_OBJECT_0, _GetExitCodeProcess=_winapi.GetExitCodeProcess):
    """Check if child process has terminated.  Returns returncode
    attribute.

    This method is called by __del__, so it can only refer to objects
    in its local scope."""
    if self.returncode is None:
        if _WaitForSingleObject(self._handle, 0) == _WAIT_OBJECT_0:
            self.returncode = _GetExitCodeProcess(self._handle)
    return self.returncode

def _wait(self, timeout):
    """Internal implementation of wait() on Windows."""
    if timeout is None:
        timeout_millis = _winapi.INFINITE
    elif timeout <= 0:
        timeout_millis = 0
    else:
        timeout_millis = int(timeout * 1000)
    if self.returncode is None:
        result = _winapi.WaitForSingleObject(self._handle, timeout_millis)
        if result == _winapi.WAIT_TIMEOUT:
            raise TimeoutExpired(self.args, timeout)
        self.returncode = _winapi.GetExitCodeProcess(self._handle)
    return self.returncode

def _readerthread(self, fh, buffer):
    buffer.append(fh.read())
    fh.close()

def _communicate(self, input, endtime, orig_timeout):
    if self.stdout and (not hasattr(self, '_stdout_buff')):
        self._stdout_buff = []
        self.stdout_thread = threading.Thread(target=self._readerthread, args=(self.stdout, self._stdout_buff))
        self.stdout_thread.daemon = True
        self.stdout_thread.start()
    if self.stderr and (not hasattr(self, '_stderr_buff')):
        self._stderr_buff = []
        self.stderr_thread = threading.Thread(target=self._readerthread, args=(self.stderr, self._stderr_buff))
        self.stderr_thread.daemon = True
        self.stderr_thread.start()
    if self.stdin:
        self._stdin_write(input)
    if self.stdout is not None:
        self.stdout_thread.join(self._remaining_time(endtime))
        if self.stdout_thread.is_alive():
            raise TimeoutExpired(self.args, orig_timeout)
    if self.stderr is not None:
        self.stderr_thread.join(self._remaining_time(endtime))
        if self.stderr_thread.is_alive():
            raise TimeoutExpired(self.args, orig_timeout)
    stdout = None
    stderr = None
    if self.stdout:
        stdout = self._stdout_buff
        self.stdout.close()
    if self.stderr:
        stderr = self._stderr_buff
        self.stderr.close()
    stdout = stdout[0] if stdout else None
    stderr = stderr[0] if stderr else None
    return (stdout, stderr)

def send_signal(self, sig):
    """Send a signal to the process."""
    if self.returncode is not None:
        return
    if sig == signal.SIGTERM:
        self.terminate()
    elif sig == signal.CTRL_C_EVENT:
        os.kill(self.pid, signal.CTRL_C_EVENT)
    elif sig == signal.CTRL_BREAK_EVENT:
        os.kill(self.pid, signal.CTRL_BREAK_EVENT)
    else:
        raise ValueError('Unsupported signal: {}'.format(sig))

def terminate(self):
    """Terminates the process."""
    if self.returncode is not None:
        return
    try:
        _winapi.TerminateProcess(self._handle, 1)
    except PermissionError:
        rc = _winapi.GetExitCodeProcess(self._handle)
        if rc == _winapi.STILL_ACTIVE:
            raise
        self.returncode = rc

def _posix_spawn(self, args, executable, env, restore_signals, p2cread, p2cwrite, c2pread, c2pwrite, errread, errwrite):
    """Execute program using os.posix_spawn()."""
    if env is None:
        env = os.environ
    kwargs = {}
    if restore_signals:
        sigset = []
        for signame in ('SIGPIPE', 'SIGXFZ', 'SIGXFSZ'):
            signum = getattr(signal, signame, None)
            if signum is not None:
                sigset.append(signum)
        kwargs['setsigdef'] = sigset
    file_actions = []
    for fd in (p2cwrite, c2pread, errread):
        if fd != -1:
            file_actions.append((os.POSIX_SPAWN_CLOSE, fd))
    for fd, fd2 in ((p2cread, 0), (c2pwrite, 1), (errwrite, 2)):
        if fd != -1:
            file_actions.append((os.POSIX_SPAWN_DUP2, fd, fd2))
    if file_actions:
        kwargs['file_actions'] = file_actions
    self.pid = os.posix_spawn(executable, args, env, **kwargs)
    self._child_created = True
    self._close_pipe_fds(p2cread, p2cwrite, c2pread, c2pwrite, errread, errwrite)

def _handle_exitstatus(self, sts, _waitstatus_to_exitcode=_waitstatus_to_exitcode, _WIFSTOPPED=_WIFSTOPPED, _WSTOPSIG=_WSTOPSIG):
    """All callers to this function MUST hold self._waitpid_lock."""
    if _WIFSTOPPED(sts):
        self.returncode = -_WSTOPSIG(sts)
    else:
        self.returncode = _waitstatus_to_exitcode(sts)

def _internal_poll(self, _deadstate=None, _waitpid=_waitpid, _WNOHANG=_WNOHANG, _ECHILD=errno.ECHILD):
    """Check if child process has terminated.  Returns returncode
    attribute.

    This method is called by __del__, so it cannot reference anything
    outside of the local scope (nor can any methods it calls)."""
    if self.returncode is None:
        if not self._waitpid_lock.acquire(False):
            return None
        try:
            if self.returncode is not None:
                return self.returncode
            pid, sts = _waitpid(self.pid, _WNOHANG)
            if pid == self.pid:
                self._handle_exitstatus(sts)
        except OSError as e:
            if _deadstate is not None:
                self.returncode = _deadstate
            elif e.errno == _ECHILD:
                self.returncode = 0
        finally:
            self._waitpid_lock.release()
    return self.returncode

def _try_wait(self, wait_flags):
    """All callers to this function MUST hold self._waitpid_lock."""
    try:
        pid, sts = os.waitpid(self.pid, wait_flags)
    except ChildProcessError:
        pid = self.pid
        sts = 0
    return (pid, sts)

def _wait(self, timeout):
    """Internal implementation of wait() on POSIX."""
    if self.returncode is not None:
        return self.returncode
    if timeout is not None:
        endtime = _time() + timeout
        delay = 0.0005
        while True:
            if self._waitpid_lock.acquire(False):
                try:
                    if self.returncode is not None:
                        break
                    pid, sts = self._try_wait(os.WNOHANG)
                    assert pid == self.pid or pid == 0
                    if pid == self.pid:
                        self._handle_exitstatus(sts)
                        break
                finally:
                    self._waitpid_lock.release()
            remaining = self._remaining_time(endtime)
            if remaining <= 0:
                raise TimeoutExpired(self.args, timeout)
            delay = min(delay * 2, remaining, 0.05)
            time.sleep(delay)
    else:
        while self.returncode is None:
            with self._waitpid_lock:
                if self.returncode is not None:
                    break
                pid, sts = self._try_wait(0)
                if pid == self.pid:
                    self._handle_exitstatus(sts)
    return self.returncode

def _save_input(self, input):
    if self.stdin and self._input is None:
        self._input_offset = 0
        self._input = input
        if input is not None and self.text_mode:
