def send_signal(self, sig):
    """Send a signal to the process."""
    self.poll()
    if self.returncode is not None:
        return
    try:
        os.kill(self.pid, sig)
    except ProcessLookupError:
        pass

def _read_u32(file):
    x = 0
    for i in range(4):
        byte = file.read(1)
        if not byte:
            raise EOFError
        x = x * 256 + ord(byte)
    return x

def open(f, mode=None):
    if mode is None:
        if hasattr(f, 'mode'):
            mode = f.mode
        else:
            mode = 'rb'
    if mode in ('r', 'rb'):
        return Au_read(f)
    elif mode in ('w', 'wb'):
        return Au_write(f)
    else:
        raise Error("mode must be 'r', 'rb', 'w', or 'wb'")

