def _release_save(self):
    if self._count == 0:
        raise RuntimeError('cannot release un-acquired lock')
    count = self._count
    self._count = 0
    owner = self._owner
    self._owner = None
    self._block.release()
    return (count, owner)

def _recursion_count(self):
