    return self._count

def __init__(self, lock=None):
    if lock is None:
        lock = RLock()
    self._lock = lock
    self.acquire = lock.acquire
    self.release = lock.release
    if hasattr(lock, '_release_save'):
        self._release_save = lock._release_save
    if hasattr(lock, '_acquire_restore'):
        self._acquire_restore = lock._acquire_restore
    if hasattr(lock, '_is_owned'):
        self._is_owned = lock._is_owned
    self._waiters = _deque()

def _at_fork_reinit(self):
    self._lock._at_fork_reinit()
    self._waiters.clear()

def _is_owned(self):
    if self._lock.acquire(False):
        self._lock.release()
        return False
    else:
        return True

def wait_for(self, predicate, timeout=None):
    """Wait until a condition evaluates to True.

    predicate should be a callable which result will be interpreted as a
    boolean value.  A timeout may be provided giving the maximum time to
    wait."""
    endtime = None
    waittime = timeout
    result = predicate()
    while not result:
        if waittime is not None:
            if endtime is None:
                endtime = _time() + waittime
            else:
                waittime = endtime - _time()
                if waittime <= 0:
                    break
        self.wait(waittime)
        result = predicate()
    return result

def notify(self, n=1):
    """Wake up one or more threads waiting on this condition, if any.

    If the calling thread has not acquired the lock when this method is
    called, a RuntimeError is raised.

    This method wakes up at most n of the threads waiting for the condition
    variable; it is a no-op if no threads are waiting."""
    if not self._is_owned():
        raise RuntimeError('cannot notify on un-acquired lock')
    waiters = self._waiters
    while waiters and n > 0:
        waiter = waiters[0]
        try:
            waiter.release()
        except RuntimeError:
            pass
        else:
            n -= 1
        try:
            waiters.remove(waiter)
        except ValueError:
            pass

def __init__(self, value=1):
    if value < 0:
        raise ValueError('semaphore initial value must be >= 0')
    self._cond = Condition(Lock())
    self._value = value

def __repr__(self):
    cls = self.__class__
    return f'<{cls.__module__}.{cls.__qualname__} at {id(self):#x}: value={self._value}>'

def __init__(self, value=1):
    super().__init__(value)
    self._initial_value = value

def __repr__(self):
    cls = self.__class__
    return f'<{cls.__module__}.{cls.__qualname__} at {id(self):#x}: value={self._value}/{self._initial_value}>'

def __init__(self):
    self._cond = Condition(Lock())
    self._flag = False

def is_set(self):
    """Return true if and only if the internal flag is true."""
    return self._flag

def isSet(self):
    """Return true if and only if the internal flag is true.

    This method is deprecated, use is_set() instead."""
    import warnings
    warnings.warn('isSet() is deprecated, use is_set() instead', DeprecationWarning, stacklevel=2)
    return self.is_set()

def __repr__(self):
    cls = self.__class__
    if self.broken:
        return f'<{cls.__module__}.{cls.__qualname__} at {id(self):#x}: broken>'
    return f'<{cls.__module__}.{cls.__qualname__} at {id(self):#x}: waiters={self.n_waiting}/{self.parties}>'

def _enter(self):
    while self._state in (-1, 1):
        self._cond.wait()
    if self._state < 0:
        raise BrokenBarrierError
    assert self._state == 0

def _release(self):
    try:
        if self._action:
            self._action()
        self._state = 1
        self._cond.notify_all()
    except:
        self._break()
        raise

def _wait(self, timeout):
    if not self._cond.wait_for(lambda: self._state != 0, timeout):
        self._break()
        raise BrokenBarrierError
    if self._state < 0:
        raise BrokenBarrierError
    assert self._state == 1

def _exit(self):
    if self._count == 0:
        if self._state in (-1, 1):
            self._state = 0
            self._cond.notify_all()

def reset(self):
    """Reset the barrier to the initial state.

    Any threads currently waiting will get the BrokenBarrier exception
    raised."""
    with self._cond:
        if self._count > 0:
            if self._state == 0:
                self._state = -1
            elif self._state == -2:
                self._state = -1
        else:
            self._state = 0
        self._cond.notify_all()

def _break(self):
    self._state = -2
    self._cond.notify_all()

@property
def parties(self):
    """Return the number of threads required to trip the barrier."""
    return self._parties

@property
def n_waiting(self):
    """Return the number of threads currently waiting at the barrier."""
    if self._state == 0:
        return self._count
    return 0

@property
def broken(self):
    """Return True if the barrier is in a broken state."""
    return self._state == -2

def _reset_internal_locks(self, is_alive):
    self._started._at_fork_reinit()
    if is_alive:
        if self._tstate_lock is not None:
            self._tstate_lock._at_fork_reinit()
            self._tstate_lock.acquire()
    else:
        self._is_stopped = True
        self._tstate_lock = None

def __repr__(self):
    assert self._initialized, 'Thread.__init__() was not called'
    status = 'initial'
    if self._started.is_set():
        status = 'started'
    self.is_alive()
    if self._is_stopped:
        status = 'stopped'
    if self._daemonic:
        status += ' daemon'
    if self._ident is not None:
        status += ' %s' % self._ident
    return '<%s(%s, %s)>' % (self.__class__.__name__, self._name, status)

def _bootstrap(self):
    try:
        self._bootstrap_inner()
    except:
        if self._daemonic and _sys is None:
            return
        raise

def _bootstrap_inner(self):
    try:
        self._set_ident()
        self._set_tstate_lock()
        if _HAVE_THREAD_NATIVE_ID:
            self._set_native_id()
        self._started.set()
        with _active_limbo_lock:
            _active[self._ident] = self
            del _limbo[self]
        if _trace_hook:
            _sys.settrace(_trace_hook)
        if _profile_hook:
            _sys.setprofile(_profile_hook)
        try:
            self.run()
        except:
            self._invoke_excepthook(self)
    finally:
        self._delete()

def _stop(self):
    lock = self._tstate_lock
    if lock is not None:
        assert not lock.locked()
    self._is_stopped = True
    self._tstate_lock = None
    if not self.daemon:
        with _shutdown_locks_lock:
            _maintain_shutdown_locks()

def _wait_for_tstate_lock(self, block=True, timeout=-1):
    lock = self._tstate_lock
    if lock is None:
        assert self._is_stopped
        return
    try:
        if lock.acquire(block, timeout):
            lock.release()
            self._stop()
    except:
        if lock.locked():
            lock.release()
            self._stop()
        raise

@name.setter
def name(self, name):
    assert self._initialized, 'Thread.__init__() not called'
    self._name = str(name)

@daemon.setter
def daemon(self, daemonic):
    if not self._initialized:
        raise RuntimeError('Thread.__init__() not called')
    if daemonic and (not _daemon_threads_allowed()):
        raise RuntimeError('daemon threads are disabled in this interpreter')
    if self._started.is_set():
        raise RuntimeError('cannot set daemon status of active thread')
    self._daemonic = daemonic

def invoke_excepthook(thread):
    global excepthook
    try:
        hook = excepthook
        if hook is None:
            hook = old_excepthook
        args = ExceptHookArgs([*sys_exc_info(), thread])
        hook(args)
    except Exception as exc:
        exc.__suppress_context__ = True
        del exc
        if local_sys is not None and local_sys.stderr is not None:
            stderr = local_sys.stderr
        else:
            stderr = thread._stderr
        local_print('Exception in threading.excepthook:', file=stderr, flush=True)
        if local_sys is not None and local_sys.excepthook is not None:
            sys_excepthook = local_sys.excepthook
        else:
            sys_excepthook = old_sys_excepthook
        sys_excepthook(*sys_exc_info())
    finally:
        args = None

def cancel(self):
    """Stop the timer if it hasn't finished yet."""
    self.finished.set()

def run(self):
    self.finished.wait(self.interval)
    if not self.finished.is_set():
        self.function(*self.args, **self.kwargs)
    self.finished.set()

def is_alive(self):
    assert not self._is_stopped and self._started.is_set()
    return True

def excepthook(args, /):
    """Handle uncaught Thread.run() exception."""
    if args.exc_type == SystemExit:
        return
    if _sys is not None and _sys.stderr is not None:
        stderr = _sys.stderr
    elif args.thread is not None:
        stderr = args.thread._stderr
        if stderr is None:
            return
    else:
        return
    if args.thread is not None:
        name = args.thread.name
    else:
        name = get_ident()
    print(f'Exception in thread {name}:', file=stderr, flush=True)
    _print_exception(args.exc_type, args.exc_value, args.exc_traceback, file=stderr)
    stderr.flush()

def reindent(src, indent):
    """Helper to reindent a multi-line statement."""
    return src.replace('\n', '\n' + ' ' * indent)

def timeit(stmt='pass', setup='pass', timer=default_timer, number=default_number, globals=None):
    """Convenience function to create Timer object and call timeit method."""
    return Timer(stmt, setup, timer, globals).timeit(number)

def repeat(stmt='pass', setup='pass', timer=default_timer, repeat=default_repeat, number=default_number, globals=None):
    """Convenience function to create Timer object and call repeat method."""
    return Timer(stmt, setup, timer, globals).repeat(repeat, number)

def autorange(self, callback=None):
    """Return the number of loops and time taken so that total time >= 0.2.

    Calls the timeit method with increasing numbers from the sequence
    1, 2, 5, 10, 20, 50, ... until the time taken is at least 0.2
    second.  Returns (number, time_taken).

    If *callback* is given and is not None, it will be called after
    each trial with two arguments: ``callback(number, time_taken)``."""
    i = 1
    while True:
        for j in (1, 2, 5):
            number = i * j
            time_taken = self.timeit(number)
            if callback:
                callback(number, time_taken)
            if time_taken >= 0.2:
                return (number, time_taken)
        i *= 10

def _join(value):
    """Internal function."""
    return ' '.join(map(_stringify, value))

def _stringify(value):
    """Internal function."""
    if isinstance(value, (list, tuple)):
        if len(value) == 1:
            value = _stringify(value[0])
            if _magic_re.search(value):
                value = '{%s}' % value
        else:
            value = '{%s}' % _join(value)
    else:
        if isinstance(value, bytes):
            value = str(value, 'latin1')
        else:
            value = str(value)
        if not value:
            value = '{}'
        elif _magic_re.search(value):
            value = _magic_re.sub('\\\\\\1', value)
            value = value.replace('\n', '\\n')
            value = _space_re.sub('\\\\\\1', value)
            if value[0] == '"':
                value = '\\' + value
        elif value[0] == '"' or _space_re.search(value):
            value = '{%s}' % value
    return value

def _flatten(seq):
    """Internal function."""
    res = ()
    for item in seq:
        if isinstance(item, (tuple, list)):
            res = res + _flatten(item)
        elif item is not None:
            res = res + (item,)
    return res

def _cnfmerge(cnfs):
    """Internal function."""
    if isinstance(cnfs, dict):
        return cnfs
    elif isinstance(cnfs, (type(None), str)):
        return cnfs
    else:
        cnf = {}
        for c in _flatten(cnfs):
            try:
                cnf.update(c)
            except (AttributeError, TypeError) as msg:
                print('_cnfmerge: fallback due to:', msg)
                for k, v in c.items():
                    cnf[k] = v
        return cnf

def _splitdict(tk, v, cut_minus=True, conv=None):
    """Return a properly formatted dict built from Tcl list pairs.

    If cut_minus is True, the supposed '-' prefix will be removed from
    keys. If conv is specified, it is used to convert values.

    Tcl list is expected to contain an even number of elements."""
    t = tk.splitlist(v)
    if len(t) % 2:
        raise RuntimeError('Tcl list representing a dict is expected to contain an even number of elements')
    it = iter(t)
    dict = {}
    for key, value in zip(it, it):
        key = str(key)
        if cut_minus and key[0] == '-':
            key = key[1:]
        if conv:
            value = conv(value)
        dict[key] = value
    return dict

def _parse_version(version):
    import re
    m = re.fullmatch('(\\d+)\\.(\\d+)([ab.])(\\d+)', version)
    major, minor, releaselevel, serial = m.groups()
    major, minor, serial = (int(major), int(minor), int(serial))
    if releaselevel == '.':
        micro = serial
        serial = 0
        releaselevel = 'final'
    else:
        micro = 0
        releaselevel = {'a': 'alpha', 'b': 'beta'}[releaselevel]
    return _VersionInfoType(major, minor, micro, releaselevel, serial)

def _get_default_root(what=None):
    if not _support_default_root:
        raise RuntimeError('No master specified and tkinter is configured to not support default root')
    if _default_root is None:
        if what:
            raise RuntimeError(f'Too early to {what}: no default root window')
        root = Tk()
        assert _default_root is root
    return _default_root

