def __str__(self):
    if self.releaselevel == 'final':
        return f'{self.major}.{self.minor}.{self.micro}'
    else:
        return f'{self.major}.{self.minor}{self.releaselevel[0]}{self.serial}'

def __repr__(self):
    attrs = {k: v for k, v in self.__dict__.items() if v != '??'}
    if not self.char:
        del attrs['char']
    elif self.char != '??':
        attrs['char'] = repr(self.char)
    if not getattr(self, 'send_event', True):
        del attrs['send_event']
    if self.state == 0:
        del attrs['state']
    elif isinstance(self.state, int):
        state = self.state
        mods = ('Shift', 'Lock', 'Control', 'Mod1', 'Mod2', 'Mod3', 'Mod4', 'Mod5', 'Button1', 'Button2', 'Button3', 'Button4', 'Button5')
        s = []
        for i, n in enumerate(mods):
            if state & 1 << i:
                s.append(n)
        state = state & ~((1 << len(mods)) - 1)
        if state or not s:
            s.append(hex(state))
        attrs['state'] = '|'.join(s)
    if self.delta == 0:
        del attrs['delta']
    keys = ('send_event', 'state', 'keysym', 'keycode', 'char', 'num', 'delta', 'focus', 'x', 'y', 'width', 'height')
    return '<%s event%s>' % (getattr(self.type, 'name', self.type), ''.join((' %s=%s' % (k, attrs[k]) for k in keys if k in attrs)))

def __init__(self, master=None, value=None, name=None):
    """Construct a variable

    MASTER can be given as master widget.
    VALUE is an optional value (defaults to "")
    NAME is an optional Tcl name (defaults to PY_VARnum).

    If NAME matches an existing variable and VALUE is omitted
    then the existing value is retained."""
    if name is not None and (not isinstance(name, str)):
        raise TypeError('name must be a string')
    global _varnum
    if master is None:
        master = _get_default_root('create variable')
    self._root = master._root()
    self._tk = master.tk
    if name:
        self._name = name
    else:
        self._name = 'PY_VAR' + repr(_varnum)
        _varnum += 1
    if value is not None:
        self.initialize(value)
    elif not self._tk.getboolean(self._tk.call('info', 'exists', self._name)):
        self.initialize(self._default)

def __del__(self):
    """Unset the variable in Tcl."""
    if self._tk is None:
        return
    if self._tk.getboolean(self._tk.call('info', 'exists', self._name)):
        self._tk.globalunsetvar(self._name)
    if self._tclCommands is not None:
        for name in self._tclCommands:
            self._tk.deletecommand(name)
        self._tclCommands = None

def __str__(self):
    """Return the name of the variable in Tcl."""
    return self._name

def set(self, value):
    """Set the variable to VALUE."""
    return self._tk.globalsetvar(self._name, value)

def get(self):
    """Return value of variable."""
    return self._tk.globalgetvar(self._name)

def _register(self, callback):
    f = CallWrapper(callback, None, self._root).__call__
    cbname = repr(id(f))
    try:
        callback = callback.__func__
    except AttributeError:
        pass
    try:
        cbname = cbname + callback.__name__
    except AttributeError:
        pass
    self._tk.createcommand(cbname, f)
    if self._tclCommands is None:
        self._tclCommands = []
    self._tclCommands.append(cbname)
    return cbname

def trace_remove(self, mode, cbname):
    """Delete the trace callback for a variable.

    Mode is one of "read", "write", "unset" or a list or tuple of
    such strings.  Must be same as were specified in trace_add().
    cbname is the name of the callback returned from trace_add()."""
    self._tk.call('trace', 'remove', 'variable', self._name, mode, cbname)
    for m, ca in self.trace_info():
        if self._tk.splitlist(ca)[0] == cbname:
            break
    else:
        self._tk.deletecommand(cbname)
        try:
            self._tclCommands.remove(cbname)
        except ValueError:
            pass

def trace_vdelete(self, mode, cbname):
    """Delete the trace callback for a variable.

    MODE is one of "r", "w", "u" for read, write, undefine.
    CBNAME is the name of the callback returned from trace_variable or trace.

    This deprecated method wraps a deprecated Tcl method that will
    likely be removed in the future.  Use trace_remove() instead."""
    self._tk.call('trace', 'vdelete', self._name, mode, cbname)
    cbname = self._tk.splitlist(cbname)[0]
    for m, ca in self.trace_info():
        if self._tk.splitlist(ca)[0] == cbname:
            break
    else:
        self._tk.deletecommand(cbname)
        try:
            self._tclCommands.remove(cbname)
        except ValueError:
            pass

