def _gridconvvalue(self, value):
    if isinstance(value, (str, _tkinter.Tcl_Obj)):
        try:
            svalue = str(value)
            if not svalue:
                return None
            elif '.' in svalue:
                return self.tk.getdouble(svalue)
            else:
                return self.tk.getint(svalue)
        except (ValueError, TclError):
            pass
    return value

