def nametofont(name, root=None):
    """Given the name of a tk named font, returns a Font representation.
    """
    return Font(name=name, exists=True, root=root)

def families(root=None, displayof=None):
    """Get font families (as a tuple)"""
    if root is None:
        root = tkinter._get_default_root('use font.families()')
    args = ()
    if displayof:
        args = ('-displayof', displayof)
    return root.tk.splitlist(root.tk.call('font', 'families', *args))

def names(root=None):
    """Get names of defined fonts (as a tuple)"""
    if root is None:
        root = tkinter._get_default_root('use font.names()')
    return root.tk.splitlist(root.tk.call('font', 'names'))

def _set(self, kw):
    options = []
    for k, v in kw.items():
        options.append('-' + k)
        options.append(str(v))
    return tuple(options)

def _get(self, args):
    options = []
    for k in args:
        options.append('-' + k)
    return tuple(options)

def _mkdict(self, args):
    options = {}
    for i in range(0, len(args), 2):
        options[args[i][1:]] = args[i + 1]
    return options

def __init__(self, root=None, font=None, name=None, exists=False, **options):
    if root is None:
        root = tkinter._get_default_root('use font')
    tk = getattr(root, 'tk', root)
    if font:
        font = tk.splitlist(tk.call('font', 'actual', font))
    else:
        font = self._set(options)
    if not name:
        name = 'font' + str(next(self.counter))
    self.name = name
    if exists:
        self.delete_font = False
        if self.name not in tk.splitlist(tk.call('font', 'names')):
            raise tkinter._tkinter.TclError('named font %s does not already exist' % (self.name,))
        if font:
            tk.call('font', 'configure', self.name, *font)
    else:
        tk.call('font', 'create', self.name, *font)
        self.delete_font = True
    self._tk = tk
    self._split = tk.splitlist
    self._call = tk.call

def __eq__(self, other):
    if not isinstance(other, Font):
        return NotImplemented
    return self.name == other.name and self._tk == other._tk

def __del__(self):
    try:
        if self.delete_font:
            self._call('font', 'delete', self.name)
    except Exception:
        pass

def copy(self):
    """Return a distinct copy of the current font"""
    return Font(self._tk, **self.actual())

def actual(self, option=None, displayof=None):
    """Return actual font attributes"""
    args = ()
    if displayof:
        args = ('-displayof', displayof)
    if option:
        args = args + ('-' + option,)
        return self._call('font', 'actual', self.name, *args)
    else:
        return self._mkdict(self._split(self._call('font', 'actual', self.name, *args)))

def cget(self, option):
    """Get font attribute"""
    return self._call('font', 'config', self.name, '-' + option)

def config(self, **options):
    """Modify font attributes"""
    if options:
        self._call('font', 'config', self.name, *self._set(options))
    else:
        return self._mkdict(self._split(self._call('font', 'config', self.name)))

def measure(self, text, displayof=None):
    """Return text width"""
    args = (text,)
    if displayof:
        args = ('-displayof', displayof, text)
    return self._tk.getint(self._call('font', 'measure', self.name, *args))

def metrics(self, *options, **kw):
    """Return font metrics.

    For best performance, create a dummy widget
    using this font before calling this method."""
    args = ()
    displayof = kw.pop('displayof', None)
    if displayof:
        args = ('-displayof', displayof)
    if options:
        args = args + self._get(options)
        return self._tk.getint(self._call('font', 'metrics', self.name, *args))
    else:
        res = self._split(self._call('font', 'metrics', self.name, *args))
        options = {}
        for i in range(0, len(res), 2):
            options[res[i][1:]] = self._tk.getint(res[i + 1])
        return options

def _show(title=None, message=None, _icon=None, _type=None, **options):
    if _icon and 'icon' not in options:
        options['icon'] = _icon
    if _type and 'type' not in options:
        options['type'] = _type
    if title:
        options['title'] = title
    if message:
        options['message'] = message
    res = Message(**options).show()
    if isinstance(res, bool):
        if res:
            return YES
        return NO
    return str(res)

def showinfo(title=None, message=None, **options):
