def _format_optvalue(value, script=False):
    """Internal function."""
    if script:
        value = _stringify(value)
    elif isinstance(value, (list, tuple)):
        value = _join(value)
    return value

def _format_optdict(optdict, script=False, ignore=None):
    """Formats optdict to a tuple to pass it to tk.call.

    E.g. (script=False):
      {'foreground': 'blue', 'padding': [1, 2, 3, 4]} returns:
      ('-foreground', 'blue', '-padding', '1 2 3 4')"""
    opts = []
    for opt, value in optdict.items():
        if not ignore or opt not in ignore:
            opts.append('-%s' % opt)
            if value is not None:
                opts.append(_format_optvalue(value, script))
    return _flatten(opts)

def _mapdict_values(items):
    opt_val = []
    for *state, val in items:
        if len(state) == 1:
            state = state[0] or ''
        else:
            state = ' '.join(state)
        opt_val.append(state)
        if val is not None:
            opt_val.append(val)
    return opt_val

def _format_mapdict(mapdict, script=False):
    """Formats mapdict to pass it to tk.call.

    E.g. (script=False):
      {'expand': [('active', 'selected', 'grey'), ('focus', [1, 2, 3, 4])]}

      returns:

      ('-expand', '{active selected} grey focus {1, 2, 3, 4}')"""
    opts = []
    for opt, value in mapdict.items():
        opts.extend(('-%s' % opt, _format_optvalue(_mapdict_values(value), script)))
    return _flatten(opts)

def _format_elemcreate(etype, script=False, *args, **kw):
    """Formats args and kw according to the given element factory etype."""
    spec = None
    opts = ()
    if etype in ('image', 'vsapi'):
        if etype == 'image':
            iname = args[0]
            imagespec = _join(_mapdict_values(args[1:]))
            spec = '%s %s' % (iname, imagespec)
        else:
            class_name, part_id = args[:2]
            statemap = _join(_mapdict_values(args[2:]))
            spec = '%s %s %s' % (class_name, part_id, statemap)
        opts = _format_optdict(kw, script)
    elif etype == 'from':
        spec = args[0]
        if len(args) > 1:
            opts = (_format_optvalue(args[1], script),)
    if script:
        spec = '{%s}' % spec
        opts = ' '.join(opts)
    return (spec, opts)

def _script_from_settings(settings):
    """Returns an appropriate script, based on settings, according to
    theme_settings definition to be used by theme_settings and
    theme_create."""
    script = []
    for name, opts in settings.items():
        if opts.get('configure'):
            s = ' '.join(_format_optdict(opts['configure'], True))
            script.append('ttk::style configure %s %s;' % (name, s))
        if opts.get('map'):
            s = ' '.join(_format_mapdict(opts['map'], True))
            script.append('ttk::style map %s %s;' % (name, s))
        if 'layout' in opts:
            if not opts['layout']:
                s = 'null'
            else:
                s, _ = _format_layoutlist(opts['layout'])
            script.append('ttk::style layout %s {\n%s\n}' % (name, s))
        if opts.get('element create'):
            eopts = opts['element create']
            etype = eopts[0]
            argc = 1
            while argc < len(eopts) and (not hasattr(eopts[argc], 'items')):
                argc += 1
            elemargs = eopts[1:argc]
            elemkw = eopts[argc] if argc < len(eopts) and eopts[argc] else {}
            spec, opts = _format_elemcreate(etype, True, *elemargs, **elemkw)
            script.append('ttk::style element create %s %s %s %s' % (name, etype, spec, opts))
    return '\n'.join(script)

def _list_from_statespec(stuple):
    """Construct a list from the given statespec tuple according to the
    accepted statespec accepted by _format_mapdict."""
    if isinstance(stuple, str):
        return stuple
    result = []
    it = iter(stuple)
    for state, val in zip(it, it):
        if hasattr(state, 'typename'):
            state = str(state).split()
        elif isinstance(state, str):
            state = state.split()
        elif not isinstance(state, (tuple, list)):
            state = (state,)
        if hasattr(val, 'typename'):
            val = str(val)
        result.append((*state, val))
    return result

def _convert_stringval(value):
    """Converts a value to, hopefully, a more appropriate Python object."""
    value = str(value)
    try:
        value = int(value)
    except (ValueError, TypeError):
        pass
    return value

def _to_number(x):
    if isinstance(x, str):
        if '.' in x:
            x = float(x)
        else:
            x = int(x)
    return x

def _tclobj_to_py(val):
    """Return value converted from Tcl object to Python object."""
    if val and hasattr(val, '__len__') and (not isinstance(val, str)):
        if getattr(val[0], 'typename', None) == 'StateSpec':
            val = _list_from_statespec(val)
        else:
            val = list(map(_convert_stringval, val))
    elif hasattr(val, 'typename'):
        val = _convert_stringval(val)
    return val

def tclobjs_to_py(adict):
    """Returns adict with its values converted from Tcl objects to Python
    objects."""
    for opt, val in adict.items():
        adict[opt] = _tclobj_to_py(val)
    return adict

def map(self, style, query_opt=None, **kw):
    """Query or sets dynamic values of the specified option(s) in
    style.

    Each key in kw is an option and each value should be a list or a
    tuple (usually) containing statespecs grouped in tuples, or list,
    or something else of your preference. A statespec is compound of
    one or more states and then a value."""
    if query_opt is not None:
        result = self.tk.call(self._name, 'map', style, '-%s' % query_opt)
        return _list_from_statespec(self.tk.splitlist(result))
    result = self.tk.call(self._name, 'map', style, *_format_mapdict(kw))
    return {k: _list_from_statespec(self.tk.splitlist(v)) for k, v in _splitdict(self.tk, result).items()}

def element_names(self):
    """Returns the list of elements defined in the current theme."""
