def identify_region(self, x, y):
    """Returns one of:

    heading: Tree heading area.
    separator: Space between two columns headings;
    tree: The tree area.
    cell: A data cell.

    * Availability: Tk 8.6"""
    return self.identify('region', x, y)

def identify_element(self, x, y):
