    * Availability: Tk 8.6"""
    return self.identify('element', x, y)

def index(self, item):
    """Returns the integer index of item within its parent's list
    of children."""
    return self.tk.getint(self.tk.call(self._w, 'index', item))

def item(self, item, option=None, **kw):
    """Query or modify the options for the specified item.

    If no options are given, a dict with options/values for the item
    is returned. If option is specified then the value for that option
    is returned. Otherwise, sets the options to the corresponding
    values as given by kw."""
    if option is not None:
        kw[option] = None
    return _val_or_dict(self.tk, kw, self._w, 'item', item)

def next(self, item):
    """Returns the identifier of item's next sibling, or '' if item
    is the last child of its parent."""
    return self.tk.call(self._w, 'next', item)

def parent(self, item):
    """Returns the ID of the parent of item, or '' if item is at the
    top level of the hierarchy."""
    return self.tk.call(self._w, 'parent', item)

def prev(self, item):
    """Returns the identifier of item's previous sibling, or '' if
    item is the first child of its parent."""
    return self.tk.call(self._w, 'prev', item)

def selection(self):
    """Returns the tuple of selected items."""
    return self.tk.splitlist(self.tk.call(self._w, 'selection'))

def _selection(self, selop, items):
    if len(items) == 1 and isinstance(items[0], (tuple, list)):
        items = items[0]
    self.tk.call(self._w, 'selection', selop, items)

def selection_set(self, *items):
    """The specified items becomes the new selection."""
    self._selection('set', items)

def selection_add(self, *items):
    """Add all of the specified items to the selection."""
    self._selection('add', items)

def selection_remove(self, *items):
    """Remove all of the specified items from the selection."""
    self._selection('remove', items)

def selection_toggle(self, *items):
    """Toggle the selection state of each specified item."""
    self._selection('toggle', items)

def set(self, item, column=None, value=None):
    """Query or set the value of given item.

    With one argument, return a dictionary of column/value pairs
    for the specified item. With two arguments, return the current
    value of the specified column. With three arguments, set the
    value of given column in given item to the specified value."""
    res = self.tk.call(self._w, 'set', item, column, value)
    if column is None and value is None:
        return _splitdict(self.tk, res, cut_minus=False, conv=_tclobj_to_py)
    else:
        return res

def tag_configure(self, tagname, option=None, **kw):
    """Query or modify the options for the specified tagname.

    If kw is not given, returns a dict of the option settings for tagname.
    If option is specified, returns the value for that option for the
    specified tagname. Otherwise, sets the options to the corresponding
    values for the given tagname."""
    if option is not None:
        kw[option] = None
    return _val_or_dict(self.tk, kw, self._w, 'tag', 'configure', tagname)

def tag_has(self, tagname, item=None):
    """If item is specified, returns 1 or 0 depending on whether the
    specified item has the given tagname. Otherwise, returns a list of
    all items which have the specified tag.

    * Availability: Tk 8.6"""
    if item is None:
        return self.tk.splitlist(self.tk.call(self._w, 'tag', 'has', tagname))
    else:
        return self.tk.getboolean(self.tk.call(self._w, 'tag', 'has', tagname, item))

def destroy(self):
    """Destroy this widget and possibly its associated variable."""
    try:
        self._variable.trace_remove('write', self.__tracecb)
    except AttributeError:
        pass
    else:
        del self._variable
    super().destroy()
    self.label = None
    self.scale = None

@property
def value(self):
    """Return current scale value."""
    return self._variable.get()

@value.setter
def value(self, val):
    """Set new scale value."""
    self._variable.set(val)

def __getitem__(self, item):
    if item == 'menu':
        return self.nametowidget(Menubutton.__getitem__(self, item))
    return Menubutton.__getitem__(self, item)

def destroy(self):
    """Destroy this widget and its associated variable."""
    try:
        del self._variable
    except AttributeError:
        pass
    super().destroy()

def adjust_label():
    self.update_idletasks()
    x, y = self.scale.coords()
    if self._label_top:
        y = self.scale.winfo_y() - self.label.winfo_reqheight()
    else:
        y = self.scale.winfo_reqheight() + self.label.winfo_reqheight()
    self.label.place_configure(x=x, y=y)

def _all_string_prefixes():
    _valid_string_prefixes = ['b', 'r', 'u', 'f', 'br', 'fr']
    result = {''}
    for prefix in _valid_string_prefixes:
        for t in _itertools.permutations(prefix):
            for u in _itertools.product(*[(c, c.upper()) for c in t]):
                result.add(''.join(u))
    return result

@functools.lru_cache
def _compile(expr):
    return re.compile(expr, re.UNICODE)

def generate_tokens(readline):
    """Tokenize a source reading Python code as unicode strings.

    This has the same API as tokenize(), except that it expects the *readline*
    callable to return str objects instead of bytes."""
    return _generate_tokens_from_c_tokenizer(readline, extra_tokens=True)

def _generate_tokens_from_c_tokenizer(source, encoding=None, extra_tokens=False):
    """Tokenize a source reading Python code as unicode strings using the internal C tokenizer"""
    if encoding is None:
        it = _tokenize.TokenizerIter(source, extra_tokens=extra_tokens)
    else:
        it = _tokenize.TokenizerIter(source, encoding=encoding, extra_tokens=extra_tokens)
    try:
        for info in it:
            yield TokenInfo._make(info)
    except SyntaxError as e:
        if type(e) != SyntaxError:
            raise e from None
        msg = _transform_msg(e.msg)
        raise TokenError(msg, (e.lineno, e.offset)) from None

def __repr__(self):
    annotated_type = '%d (%s)' % (self.type, tok_name[self.type])
    return 'TokenInfo(type=%s, string=%r, start=%r, end=%r, line=%r)' % self._replace(type=annotated_type)

@property
def exact_type(self):
    if self.type == OP and self.string in EXACT_TOKEN_TYPES:
        return EXACT_TOKEN_TYPES[self.string]
    else:
        return self.type

def add_whitespace(self, start):
    row, col = start
    if row < self.prev_row or (row == self.prev_row and col < self.prev_col):
        raise ValueError('start ({},{}) precedes previous end ({},{})'.format(row, col, self.prev_row, self.prev_col))
    self.add_backslash_continuation(start)
    col_offset = col - self.prev_col
    if col_offset:
        self.tokens.append(' ' * col_offset)

def escape_brackets(self, token):
    characters = []
    consume_until_next_bracket = False
    for character in token:
        if character == '}':
            if consume_until_next_bracket:
                consume_until_next_bracket = False
            else:
                characters.append(character)
        if character == '{':
            n_backslashes = sum((1 for char in _itertools.takewhile('\\'.__eq__, characters[-2::-1])))
            if n_backslashes % 2 == 0 or characters[-1] != 'N':
                characters.append(character)
            else:
                consume_until_next_bracket = True
        characters.append(character)
    return ''.join(characters)

def find_cookie(line):
    try:
        line_string = line.decode('utf-8')
    except UnicodeDecodeError:
        msg = 'invalid or missing encoding declaration'
        if filename is not None:
            msg = '{} for {!r}'.format(msg, filename)
        raise SyntaxError(msg)
    match = cookie_re.match(line_string)
    if not match:
        return None
    encoding = _get_normal_name(match.group(1))
    try:
        codec = lookup(encoding)
    except LookupError:
        if filename is None:
            msg = 'unknown encoding: ' + encoding
        else:
            msg = 'unknown encoding for {!r}: {}'.format(filename, encoding)
        raise SyntaxError(msg)
    if bom_found:
        if encoding != 'utf-8':
            if filename is None:
                msg = 'encoding problem: utf-8'
            else:
                msg = 'encoding problem for {!r}: utf-8'.format(filename)
            raise SyntaxError(msg)
        encoding += '-sig'
    return encoding

def perror(message):
    sys.stderr.write(message)
    sys.stderr.write('\n')

def error(message, filename=None, location=None):
    if location:
        args = (filename,) + location + (message,)
        perror('%s:%d:%d: error: %s' % args)
    elif filename:
        perror('%s: error: %s' % (filename, message))
    else:
        perror('error: %s' % message)
    sys.exit(1)

def load(fp: BinaryIO, /, *, parse_float: ParseFloat=float) -> dict[str, Any]:
    """Parse TOML from a binary file object."""
    b = fp.read()
    try:
        s = b.decode()
    except AttributeError:
        raise TypeError("File must be opened in binary mode, e.g. use `open('foo.toml', 'rb')`") from None
    return loads(s, parse_float=parse_float)

def skip_chars(src: str, pos: Pos, chars: Iterable[str]) -> Pos:
    try:
        while src[pos] in chars:
            pos += 1
    except IndexError:
        pass
    return pos

def skip_until(src: str, pos: Pos, expect: str, *, error_on: frozenset[str], error_on_eof: bool) -> Pos:
    try:
        new_pos = src.index(expect, pos)
    except ValueError:
        new_pos = len(src)
        if error_on_eof:
            raise suffixed_err(src, new_pos, f'Expected {expect!r}') from None
    if not error_on.isdisjoint(src[pos:new_pos]):
        while src[pos] not in error_on:
            pos += 1
        raise suffixed_err(src, pos, f'Found invalid character {src[pos]!r}')
    return new_pos

def skip_comment(src: str, pos: Pos) -> Pos:
    try:
        char: str | None = src[pos]
    except IndexError:
        char = None
    if char == '#':
        return skip_until(src, pos + 1, '\n', error_on=ILLEGAL_COMMENT_CHARS, error_on_eof=False)
    return pos

def skip_comments_and_array_ws(src: str, pos: Pos) -> Pos:
    while True:
        pos_before_skip = pos
        pos = skip_chars(src, pos, TOML_WS_AND_NEWLINE)
        pos = skip_comment(src, pos)
        if pos == pos_before_skip:
            return pos

def create_dict_rule(src: str, pos: Pos, out: Output) -> tuple[Pos, Key]:
    pos += 1
    pos = skip_chars(src, pos, TOML_WS)
    pos, key = parse_key(src, pos)
    if out.flags.is_(key, Flags.EXPLICIT_NEST) or out.flags.is_(key, Flags.FROZEN):
        raise suffixed_err(src, pos, f'Cannot declare {key} twice')
    out.flags.set(key, Flags.EXPLICIT_NEST, recursive=False)
    try:
        out.data.get_or_create_nest(key)
    except KeyError:
        raise suffixed_err(src, pos, 'Cannot overwrite a value') from None
    if not src.startswith(']', pos):
        raise suffixed_err(src, pos, "Expected ']' at the end of a table declaration")
    return (pos + 1, key)

def create_list_rule(src: str, pos: Pos, out: Output) -> tuple[Pos, Key]:
    pos += 2
    pos = skip_chars(src, pos, TOML_WS)
    pos, key = parse_key(src, pos)
    if out.flags.is_(key, Flags.FROZEN):
        raise suffixed_err(src, pos, f'Cannot mutate immutable namespace {key}')
    out.flags.unset_all(key)
    out.flags.set(key, Flags.EXPLICIT_NEST, recursive=False)
    try:
        out.data.append_nest_to_list(key)
    except KeyError:
        raise suffixed_err(src, pos, 'Cannot overwrite a value') from None
    if not src.startswith(']]', pos):
        raise suffixed_err(src, pos, "Expected ']]' at the end of an array declaration")
    return (pos + 2, key)

def key_value_rule(src: str, pos: Pos, out: Output, header: Key, parse_float: ParseFloat) -> Pos:
    pos, key, value = parse_key_value_pair(src, pos, parse_float)
    key_parent, key_stem = (key[:-1], key[-1])
    abs_key_parent = header + key_parent
    relative_path_cont_keys = (header + key[:i] for i in range(1, len(key)))
    for cont_key in relative_path_cont_keys:
        if out.flags.is_(cont_key, Flags.EXPLICIT_NEST):
            raise suffixed_err(src, pos, f'Cannot redefine namespace {cont_key}')
        out.flags.add_pending(cont_key, Flags.EXPLICIT_NEST)
    if out.flags.is_(abs_key_parent, Flags.FROZEN):
        raise suffixed_err(src, pos, f'Cannot mutate immutable namespace {abs_key_parent}')
    try:
        nest = out.data.get_or_create_nest(abs_key_parent)
    except KeyError:
        raise suffixed_err(src, pos, 'Cannot overwrite a value') from None
    if key_stem in nest:
        raise suffixed_err(src, pos, 'Cannot overwrite a value')
    if isinstance(value, (dict, list)):
        out.flags.set(header + key, Flags.FROZEN, recursive=True)
    nest[key_stem] = value
    return pos

def parse_key_value_pair(src: str, pos: Pos, parse_float: ParseFloat) -> tuple[Pos, Key, Any]:
    pos, key = parse_key(src, pos)
    try:
        char: str | None = src[pos]
    except IndexError:
        char = None
    if char != '=':
        raise suffixed_err(src, pos, "Expected '=' after a key in a key/value pair")
    pos += 1
    pos = skip_chars(src, pos, TOML_WS)
    pos, value = parse_value(src, pos, parse_float)
    return (pos, key, value)

def parse_key(src: str, pos: Pos) -> tuple[Pos, Key]:
    pos, key_part = parse_key_part(src, pos)
    key: Key = (key_part,)
    pos = skip_chars(src, pos, TOML_WS)
    while True:
        try:
            char: str | None = src[pos]
        except IndexError:
            char = None
        if char != '.':
            return (pos, key)
        pos += 1
        pos = skip_chars(src, pos, TOML_WS)
        pos, key_part = parse_key_part(src, pos)
        key += (key_part,)
        pos = skip_chars(src, pos, TOML_WS)

def parse_key_part(src: str, pos: Pos) -> tuple[Pos, str]:
    try:
        char: str | None = src[pos]
    except IndexError:
        char = None
    if char in BARE_KEY_CHARS:
        start_pos = pos
        pos = skip_chars(src, pos, BARE_KEY_CHARS)
        return (pos, src[start_pos:pos])
    if char == "'":
        return parse_literal_str(src, pos)
    if char == '"':
        return parse_one_line_basic_str(src, pos)
    raise suffixed_err(src, pos, 'Invalid initial character for a key part')

def parse_one_line_basic_str(src: str, pos: Pos) -> tuple[Pos, str]:
    pos += 1
    return parse_basic_str(src, pos, multiline=False)

def parse_inline_table(src: str, pos: Pos, parse_float: ParseFloat) -> tuple[Pos, dict]:
    pos += 1
    nested_dict = NestedDict()
    flags = Flags()
    pos = skip_chars(src, pos, TOML_WS)
    if src.startswith('}', pos):
        return (pos + 1, nested_dict.dict)
    while True:
        pos, key, value = parse_key_value_pair(src, pos, parse_float)
        key_parent, key_stem = (key[:-1], key[-1])
        if flags.is_(key, Flags.FROZEN):
            raise suffixed_err(src, pos, f'Cannot mutate immutable namespace {key}')
        try:
            nest = nested_dict.get_or_create_nest(key_parent, access_lists=False)
        except KeyError:
            raise suffixed_err(src, pos, 'Cannot overwrite a value') from None
        if key_stem in nest:
            raise suffixed_err(src, pos, f'Duplicate inline table key {key_stem!r}')
        nest[key_stem] = value
        pos = skip_chars(src, pos, TOML_WS)
        c = src[pos:pos + 1]
        if c == '}':
            return (pos + 1, nested_dict.dict)
        if c != ',':
            raise suffixed_err(src, pos, 'Unclosed inline table')
        if isinstance(value, (dict, list)):
            flags.set(key, Flags.FROZEN, recursive=True)
        pos += 1
        pos = skip_chars(src, pos, TOML_WS)

def parse_basic_str_escape(src: str, pos: Pos, *, multiline: bool=False) -> tuple[Pos, str]:
    escape_id = src[pos:pos + 2]
    pos += 2
    if multiline and escape_id in {'\\ ', '\\\t', '\\\n'}:
        if escape_id != '\\\n':
            pos = skip_chars(src, pos, TOML_WS)
            try:
                char = src[pos]
            except IndexError:
                return (pos, '')
            if char != '\n':
                raise suffixed_err(src, pos, "Unescaped '\\' in a string")
            pos += 1
        pos = skip_chars(src, pos, TOML_WS_AND_NEWLINE)
        return (pos, '')
    if escape_id == '\\u':
        return parse_hex_char(src, pos, 4)
    if escape_id == '\\U':
        return parse_hex_char(src, pos, 8)
    try:
        return (pos, BASIC_STR_ESCAPE_REPLACEMENTS[escape_id])
    except KeyError:
        raise suffixed_err(src, pos, "Unescaped '\\' in a string") from None

def parse_hex_char(src: str, pos: Pos, hex_len: int) -> tuple[Pos, str]:
    hex_str = src[pos:pos + hex_len]
    if len(hex_str) != hex_len or not HEXDIGIT_CHARS.issuperset(hex_str):
        raise suffixed_err(src, pos, 'Invalid hex value')
    pos += hex_len
    hex_int = int(hex_str, 16)
    if not is_unicode_scalar_value(hex_int):
        raise suffixed_err(src, pos, 'Escaped character is not a Unicode scalar value')
    return (pos, chr(hex_int))

def parse_literal_str(src: str, pos: Pos) -> tuple[Pos, str]:
    pos += 1
    start_pos = pos
    pos = skip_until(src, pos, "'", error_on=ILLEGAL_LITERAL_STR_CHARS, error_on_eof=True)
    return (pos + 1, src[start_pos:pos])

def parse_multiline_str(src: str, pos: Pos, *, literal: bool) -> tuple[Pos, str]:
    pos += 3
    if src.startswith('\n', pos):
        pos += 1
    if literal:
        delim = "'"
        end_pos = skip_until(src, pos, "'''", error_on=ILLEGAL_MULTILINE_LITERAL_STR_CHARS, error_on_eof=True)
        result = src[pos:end_pos]
        pos = end_pos + 3
    else:
        delim = '"'
        pos, result = parse_basic_str(src, pos, multiline=True)
    if not src.startswith(delim, pos):
        return (pos, result)
    pos += 1
    if not src.startswith(delim, pos):
        return (pos, result + delim)
    pos += 1
    return (pos, result + delim * 2)

def parse_basic_str(src: str, pos: Pos, *, multiline: bool) -> tuple[Pos, str]:
    if multiline:
        error_on = ILLEGAL_MULTILINE_BASIC_STR_CHARS
        parse_escapes = parse_basic_str_escape_multiline
    else:
        error_on = ILLEGAL_BASIC_STR_CHARS
        parse_escapes = parse_basic_str_escape
    result = ''
    start_pos = pos
    while True:
        try:
            char = src[pos]
        except IndexError:
            raise suffixed_err(src, pos, 'Unterminated string') from None
        if char == '"':
            if not multiline:
                return (pos + 1, result + src[start_pos:pos])
            if src.startswith('"""', pos):
                return (pos + 3, result + src[start_pos:pos])
            pos += 1
            continue
        if char == '\\':
            result += src[start_pos:pos]
            pos, parsed_escape = parse_escapes(src, pos)
            result += parsed_escape
            start_pos = pos
            continue
        if char in error_on:
            raise suffixed_err(src, pos, f'Illegal character {char!r}')
        pos += 1

def suffixed_err(src: str, pos: Pos, msg: str) -> TOMLDecodeError:
    """Return a `TOMLDecodeError` where error message is suffixed with
    coordinates in source."""
    def coord_repr(src: str, pos: Pos) -> str:
        if pos >= len(src):
            return 'end of document'
        line = src.count('\n', 0, pos) + 1
        if line == 1:
            column = pos + 1
        else:
            column = pos - src.rindex('\n', 0, pos)
        return f'line {line}, column {column}'
    return TOMLDecodeError(f'{msg} (at {coord_repr(src, pos)})')

def __init__(self) -> None:
    self._flags: dict[str, dict] = {}
    self._pending_flags: set[tuple[Key, int]] = set()

def finalize_pending(self) -> None:
    for key, flag in self._pending_flags:
        self.set(key, flag, recursive=False)
    self._pending_flags.clear()

def unset_all(self, key: Key) -> None:
    cont = self._flags
    for k in key[:-1]:
        if k not in cont:
            return
        cont = cont[k]['nested']
    cont.pop(key[-1], None)

def set(self, key: Key, flag: int, *, recursive: bool) -> None:
    cont = self._flags
    key_parent, key_stem = (key[:-1], key[-1])
    for k in key_parent:
        if k not in cont:
            cont[k] = {'flags': set(), 'recursive_flags': set(), 'nested': {}}
        cont = cont[k]['nested']
    if key_stem not in cont:
        cont[key_stem] = {'flags': set(), 'recursive_flags': set(), 'nested': {}}
    cont[key_stem]['recursive_flags' if recursive else 'flags'].add(flag)

def is_(self, key: Key, flag: int) -> bool:
    if not key:
        return False
    cont = self._flags
    for k in key[:-1]:
        if k not in cont:
            return False
        inner_cont = cont[k]
        if flag in inner_cont['recursive_flags']:
            return True
        cont = inner_cont['nested']
    key_stem = key[-1]
    if key_stem in cont:
        cont = cont[key_stem]
        return flag in cont['flags'] or flag in cont['recursive_flags']
    return False

def get_or_create_nest(self, key: Key, *, access_lists: bool=True) -> dict:
    cont: Any = self.dict
    for k in key:
        if k not in cont:
            cont[k] = {}
        cont = cont[k]
        if access_lists and isinstance(cont, list):
            cont = cont[-1]
        if not isinstance(cont, dict):
            raise KeyError('There is no nest behind this key')
    return cont

def append_nest_to_list(self, key: Key) -> None:
    cont = self.get_or_create_nest(key[:-1])
    last_key = key[-1]
    if last_key in cont:
        list_ = cont[last_key]
        if not isinstance(list_, list):
            raise KeyError('An object other than list found behind this key')
        list_.append({})
    else:
        cont[last_key] = [{}]

def coord_repr(src: str, pos: Pos) -> str:
    if pos >= len(src):
        return 'end of document'
    line = src.count('\n', 0, pos) + 1
    if line == 1:
        column = pos + 1
    else:
        column = pos - src.rindex('\n', 0, pos)
    return f'line {line}, column {column}'

def safe_parse_float(float_str: str) -> Any:
    float_value = parse_float(float_str)
    if isinstance(float_value, (dict, list)):
        raise ValueError('parse_float must not return dicts or lists')
    return float_value

def match_to_datetime(match: re.Match) -> datetime | date:
    """Convert a `RE_DATETIME` match to `datetime.datetime` or `datetime.date`.

    Raises ValueError if the match does not correspond to a valid date
    or datetime."""
    year_str, month_str, day_str, hour_str, minute_str, sec_str, micros_str, zulu_time, offset_sign_str, offset_hour_str, offset_minute_str = match.groups()
    year, month, day = (int(year_str), int(month_str), int(day_str))
    if hour_str is None:
        return date(year, month, day)
    hour, minute, sec = (int(hour_str), int(minute_str), int(sec_str))
    micros = int(micros_str.ljust(6, '0')) if micros_str else 0
    if offset_sign_str:
        tz: tzinfo | None = cached_tz(offset_hour_str, offset_minute_str, offset_sign_str)
    elif zulu_time:
        tz = timezone.utc
    else:
        tz = None
    return datetime(year, month, day, hour, minute, sec, micros, tzinfo=tz)

@lru_cache(maxsize=None)
def cached_tz(hour_str: str, minute_str: str, sign_str: str) -> timezone:
    sign = 1 if sign_str == '+' else -1
    return timezone(timedelta(hours=sign * int(hour_str), minutes=sign * int(minute_str)))

def match_to_localtime(match: re.Match) -> time:
    hour_str, minute_str, sec_str, micros_str = match.groups()
    micros = int(micros_str.ljust(6, '0')) if micros_str else 0
    return time(int(hour_str), int(minute_str), int(sec_str), micros)

def match_to_number(match: re.Match, parse_float: ParseFloat) -> Any:
    if match.group('floatpart'):
        return parse_float(match.group())
    return int(match.group(), 0)

def _fullmodname(path):
    """Return a plausible module name for the path."""
    comparepath = os.path.normcase(path)
    longest = ''
    for dir in sys.path:
        dir = os.path.normcase(dir)
        if comparepath.startswith(dir) and comparepath[len(dir)] == os.sep:
            if len(dir) > len(longest):
                longest = dir
    if longest:
        base = path[len(longest) + 1:]
    else:
        base = path
    drive, base = os.path.splitdrive(base)
    base = base.replace(os.sep, '.')
    if os.altsep:
        base = base.replace(os.altsep, '.')
    filename, ext = os.path.splitext(base)
    return filename.lstrip('.')

def _find_lines_from_code(code, strs):
    """Return dict where keys are lines in the line number table."""
    linenos = {}
    for _, lineno in dis.findlinestarts(code):
        if lineno not in strs:
            linenos[lineno] = 1
    return linenos

def _find_lines(code, strs):
    """Return lineno dict for all code objects reachable from code."""
    linenos = _find_lines_from_code(code, strs)
    for c in code.co_consts:
        if inspect.iscode(c):
            linenos.update(_find_lines(c, strs))
    return linenos

def _find_strings(filename, encoding=None):
    """Return a dict of possible docstring positions.

    The dict maps line numbers to strings.  There is an entry for
    line that contains only a string or a part of a triple-quoted
    string."""
    d = {}
    prev_ttype = token.INDENT
    with open(filename, encoding=encoding) as f:
        tok = tokenize.generate_tokens(f.readline)
        for ttype, tstr, start, end, line in tok:
            if ttype == token.STRING:
                if prev_ttype == token.INDENT:
                    sline, scol = start
                    eline, ecol = end
                    for i in range(sline, eline + 1):
                        d[i] = 1
            prev_ttype = ttype
    return d

def _find_executable_linenos(filename):
    """Return dict where keys are line numbers in the line number table."""
    try:
        with tokenize.open(filename) as f:
            prog = f.read()
            encoding = f.encoding
    except OSError as err:
        print('Not printing coverage data for %r: %s' % (filename, err), file=sys.stderr)
        return {}
    code = compile(prog, filename, 'exec')
    strs = _find_strings(filename, encoding)
    return _find_lines(code, strs)

def __init__(self, modules=None, dirs=None):
    self._mods = set() if not modules else set(modules)
    self._dirs = [] if not dirs else [os.path.normpath(d) for d in dirs]
    self._ignore = {'<string>': 1}

def names(self, filename, modulename):
    if modulename in self._ignore:
        return self._ignore[modulename]
    if modulename in self._mods:
        self._ignore[modulename] = 1
        return 1
    for mod in self._mods:
        if modulename.startswith(mod + '.'):
            self._ignore[modulename] = 1
            return 1
    if filename is None:
        self._ignore[modulename] = 1
        return 1
    for d in self._dirs:
        if filename.startswith(d + os.sep):
            self._ignore[modulename] = 1
            return 1
    self._ignore[modulename] = 0
    return 0

def __init__(self, counts=None, calledfuncs=None, infile=None, callers=None, outfile=None):
    self.counts = counts
    if self.counts is None:
        self.counts = {}
    self.counter = self.counts.copy()
    self.calledfuncs = calledfuncs
    if self.calledfuncs is None:
        self.calledfuncs = {}
    self.calledfuncs = self.calledfuncs.copy()
    self.callers = callers
    if self.callers is None:
        self.callers = {}
    self.callers = self.callers.copy()
    self.infile = infile
    self.outfile = outfile
    if self.infile:
        try:
            with open(self.infile, 'rb') as f:
                counts, calledfuncs, callers = pickle.load(f)
            self.update(self.__class__(counts, calledfuncs, callers=callers))
        except (OSError, EOFError, ValueError) as err:
            print('Skipping counts file %r: %s' % (self.infile, err), file=sys.stderr)

def is_ignored_filename(self, filename):
    """Return True if the filename does not refer to a file
    we want to have reported."""
    return filename.startswith('<') and filename.endswith('>')

def runctx(self, cmd, globals=None, locals=None):
    if globals is None:
        globals = {}
    if locals is None:
        locals = {}
    if not self.donothing:
        threading.settrace(self.globaltrace)
        sys.settrace(self.globaltrace)
    try:
        exec(cmd, globals, locals)
    finally:
        if not self.donothing:
            sys.settrace(None)
            threading.settrace(None)

def runfunc(self, func, /, *args, **kw):
    result = None
    if not self.donothing:
        sys.settrace(self.globaltrace)
    try:
        result = func(*args, **kw)
    finally:
        if not self.donothing:
            sys.settrace(None)
    return result

def file_module_function_of(self, frame):
    code = frame.f_code
    filename = code.co_filename
    if filename:
        modulename = _modname(filename)
    else:
        modulename = None
    funcname = code.co_name
    clsname = None
    if code in self._caller_cache:
        if self._caller_cache[code] is not None:
            clsname = self._caller_cache[code]
    else:
        self._caller_cache[code] = None
        funcs = [f for f in gc.get_referrers(code) if inspect.isfunction(f)]
        if len(funcs) == 1:
            dicts = [d for d in gc.get_referrers(funcs[0]) if isinstance(d, dict)]
            if len(dicts) == 1:
                classes = [c for c in gc.get_referrers(dicts[0]) if hasattr(c, '__bases__')]
                if len(classes) == 1:
                    clsname = classes[0].__name__
                    self._caller_cache[code] = clsname
    if clsname is not None:
        funcname = '%s.%s' % (clsname, funcname)
    return (filename, modulename, funcname)

def globaltrace_countfuncs(self, frame, why, arg):
    """Handler for call events.

    Adds (filename, modulename, funcname) to the self._calledfuncs dict."""
    if why == 'call':
        this_func = self.file_module_function_of(frame)
        self._calledfuncs[this_func] = 1

def globaltrace_lt(self, frame, why, arg):
    """Handler for call events.

    If the code block being entered is to be ignored, returns `None',
    else returns self.localtrace."""
    if why == 'call':
        code = frame.f_code
        filename = frame.f_globals.get('__file__', None)
        if filename:
            modulename = _modname(filename)
            if modulename is not None:
                ignore_it = self.ignore.names(filename, modulename)
                if not ignore_it:
                    if self.trace:
                        print(' --- modulename: %s, funcname: %s' % (modulename, code.co_name))
                    return self.localtrace
        else:
            return None

def localtrace_trace_and_count(self, frame, why, arg):
    if why == 'line':
        filename = frame.f_code.co_filename
        lineno = frame.f_lineno
        key = (filename, lineno)
        self.counts[key] = self.counts.get(key, 0) + 1
        if self.start_time:
            print('%.2f' % (_time() - self.start_time), end=' ')
        bname = os.path.basename(filename)
        line = linecache.getline(filename, lineno)
        print('%s(%d)' % (bname, lineno), end='')
        if line:
            print(': ', line, end='')
        else:
            print()
    return self.localtrace

def localtrace_trace(self, frame, why, arg):
    if why == 'line':
        filename = frame.f_code.co_filename
        lineno = frame.f_lineno
        if self.start_time:
            print('%.2f' % (_time() - self.start_time), end=' ')
        bname = os.path.basename(filename)
        line = linecache.getline(filename, lineno)
        print('%s(%d)' % (bname, lineno), end='')
        if line:
            print(': ', line, end='')
        else:
            print()
    return self.localtrace

def parse_ignore_dir(s):
    s = os.path.expanduser(os.path.expandvars(s))
    s = s.replace('$prefix', _prefix).replace('$exec_prefix', _exec_prefix)
    return os.path.normpath(s)

def print_list(extracted_list, file=None):
    """Print the list of tuples as returned by extract_tb() or
    extract_stack() as a formatted stack trace to the given file."""
    if file is None:
        file = sys.stderr
    for item in StackSummary.from_list(extracted_list).format():
        print(item, file=file, end='')

def format_list(extracted_list):
    """Format a list of tuples or FrameSummary objects for printing.

    Given a list of tuples or FrameSummary objects as returned by
    extract_tb() or extract_stack(), return a list of strings ready
    for printing.

    Each string in the resulting list corresponds to the item with the
    same index in the argument list.  Each string ends in a newline;
    the strings may contain internal newlines as well, for those items
    whose source text line is not None."""
    return StackSummary.from_list(extracted_list).format()

def format_tb(tb, limit=None):
    """A shorthand for 'format_list(extract_tb(tb, limit))'."""
    return extract_tb(tb, limit=limit).format()

def _parse_value_tb(exc, value, tb):
    if (value is _sentinel) != (tb is _sentinel):
        raise ValueError('Both or neither of value and tb must be given')
    if value is tb is _sentinel:
        if exc is not None:
            if isinstance(exc, BaseException):
                return (exc, exc.__traceback__)
            raise TypeError(f'Exception expected for value, {type(exc).__name__} found')
        else:
            return (None, None)
    return (value, tb)

def _format_final_exc_line(etype, value):
    valuestr = _safe_string(value, 'exception')
    if value is None or not valuestr:
        line = '%s\n' % etype
    else:
        line = '%s: %s\n' % (etype, valuestr)
    return line

def _safe_string(value, what, func=str):
    try:
        return func(value)
    except:
        return f'<{what} {func.__name__}() failed>'

def print_exc(limit=None, file=None, chain=True):
    """Shorthand for 'print_exception(sys.exception(), limit=limit, file=file, chain=chain)'."""
    print_exception(sys.exception(), limit=limit, file=file, chain=chain)

def format_exc(limit=None, chain=True):
    """Like print_exc() but return a string."""
    return ''.join(format_exception(sys.exception(), limit=limit, chain=chain))

def print_last(limit=None, file=None, chain=True):
    """This is a shorthand for 'print_exception(sys.last_exc, limit=limit, file=file, chain=chain)'."""
    if not hasattr(sys, 'last_exc') and (not hasattr(sys, 'last_type')):
        raise ValueError('no last exception')
    if hasattr(sys, 'last_exc'):
        print_exception(sys.last_exc, limit=limit, file=file, chain=chain)
    else:
        print_exception(sys.last_type, sys.last_value, sys.last_traceback, limit=limit, file=file, chain=chain)

def format_stack(f=None, limit=None):
    """Shorthand for 'format_list(extract_stack(f, limit))'."""
    if f is None:
        f = sys._getframe().f_back
    return format_list(extract_stack(f, limit=limit))

def clear_frames(tb):
    """Clear all references to local variables in the frames of a traceback."""
    while tb is not None:
        try:
            tb.tb_frame.clear()
        except RuntimeError:
            pass
        tb = tb.tb_next

def walk_stack(f):
    """Walk a stack yielding the frame and line number for each frame.

    This will follow f.f_back from the given frame. If no frame is given, the
    current stack is used. Usually used with StackSummary.extract."""
    if f is None:
        f = sys._getframe().f_back.f_back.f_back.f_back
    while f is not None:
        yield (f, f.f_lineno)
        f = f.f_back

def _walk_tb_with_full_positions(tb):
    while tb is not None:
        positions = _get_code_position(tb.tb_frame.f_code, tb.tb_lasti)
        if positions[0] is None:
            yield (tb.tb_frame, (tb.tb_lineno,) + positions[1:])
        else:
            yield (tb.tb_frame, positions)
        tb = tb.tb_next

def _byte_offset_to_character_offset(str, offset):
    as_utf8 = str.encode('utf-8')
    return len(as_utf8[:offset].decode('utf-8', errors='replace'))

def _display_width(line, offset):
    """Calculate the extra amount of width space the given source
    code segment might take if it were to be displayed on a fixed
    width output device. Supports wide unicode characters and emojis."""
    if line.isascii():
        return offset
    import unicodedata
    return sum((2 if unicodedata.east_asian_width(char) in _WIDE_CHAR_SPECIFIERS else 1 for char in line[:offset]))

def _substitution_cost(ch_a, ch_b):
    if ch_a == ch_b:
        return 0
    if ch_a.lower() == ch_b.lower():
        return _CASE_COST
    return _MOVE_COST

def _levenshtein_distance(a, b, max_cost):
    if a == b:
        return 0
    pre = 0
    while a[pre:] and b[pre:] and (a[pre] == b[pre]):
        pre += 1
    a = a[pre:]
    b = b[pre:]
    post = 0
    while a[:post or None] and b[:post or None] and (a[post - 1] == b[post - 1]):
        post -= 1
    a = a[:post or None]
    b = b[:post or None]
    if not a or not b:
        return _MOVE_COST * (len(a) + len(b))
    if len(a) > _MAX_STRING_SIZE or len(b) > _MAX_STRING_SIZE:
        return max_cost + 1
    if len(b) < len(a):
        a, b = (b, a)
    if (len(b) - len(a)) * _MOVE_COST > max_cost:
        return max_cost + 1
    row = list(range(_MOVE_COST, _MOVE_COST * (len(a) + 1), _MOVE_COST))
    result = 0
    for bindex in range(len(b)):
        bchar = b[bindex]
        distance = result = bindex * _MOVE_COST
        minimum = sys.maxsize
        for index in range(len(a)):
            substitute = distance + _substitution_cost(bchar, a[index])
            distance = row[index]
            insert_delete = min(result, distance) + _MOVE_COST
            result = min(insert_delete, substitute)
            row[index] = result
            if result < minimum:
                minimum = result
        if minimum > max_cost:
            return max_cost + 1
    return result

def __eq__(self, other):
    if isinstance(other, FrameSummary):
        return self.filename == other.filename and self.lineno == other.lineno and (self.name == other.name) and (self.locals == other.locals)
    if isinstance(other, tuple):
        return (self.filename, self.lineno, self.name, self.line) == other
    return NotImplemented

@property
def _original_line(self):
    self.line
    return self._line

@property
def line(self):
    if self._line is None:
        if self.lineno is None:
            return None
        self._line = linecache.getline(self.filename, self.lineno)
    return self._line.strip()

@classmethod
def extract(klass, frame_gen, *, limit=None, lookup_lines=True, capture_locals=False):
    """Create a StackSummary from a traceback or stack object.

    :param frame_gen: A generator that yields (frame, lineno) tuples
        whose summaries are to be included in the stack.
    :param limit: None to include all frames or the number of frames to
        include.
    :param lookup_lines: If True, lookup lines for each frame immediately,
        otherwise lookup is deferred until the frame is rendered.
    :param capture_locals: If True, the local variables from each frame will
        be captured as object representations into the FrameSummary."""
    def extended_frame_gen():
        for f, lineno in frame_gen:
            yield (f, (lineno, None, None, None))
    return klass._extract_from_extended_frame_gen(extended_frame_gen(), limit=limit, lookup_lines=lookup_lines, capture_locals=capture_locals)

@classmethod
def _extract_from_extended_frame_gen(klass, frame_gen, *, limit=None, lookup_lines=True, capture_locals=False):
    if limit is None:
        limit = getattr(sys, 'tracebacklimit', None)
        if limit is not None and limit < 0:
            limit = 0
    if limit is not None:
        if limit >= 0:
            frame_gen = itertools.islice(frame_gen, limit)
        else:
            frame_gen = collections.deque(frame_gen, maxlen=-limit)
    result = klass()
    fnames = set()
    for f, (lineno, end_lineno, colno, end_colno) in frame_gen:
        co = f.f_code
        filename = co.co_filename
        name = co.co_name
        fnames.add(filename)
        linecache.lazycache(filename, f.f_globals)
        if capture_locals:
            f_locals = f.f_locals
        else:
            f_locals = None
        result.append(FrameSummary(filename, lineno, name, lookup_line=False, locals=f_locals, end_lineno=end_lineno, colno=colno, end_colno=end_colno))
    for filename in fnames:
        linecache.checkcache(filename)
    if lookup_lines:
        for f in result:
            f.line
    return result

@classmethod
def from_list(klass, a_list):
    """Create a StackSummary object from a supplied list of
    FrameSummary objects or old-style list of tuples."""
    result = StackSummary()
    for frame in a_list:
        if isinstance(frame, FrameSummary):
            result.append(frame)
        else:
            filename, lineno, name, line = frame
            result.append(FrameSummary(filename, lineno, name, line=line))
    return result

def emit(self, text_gen, margin_char=None):
    if margin_char is None:
        margin_char = '|'
    indent_str = self.indent()
    if self.exception_group_depth:
        indent_str += margin_char + ' '
    if isinstance(text_gen, str):
        yield textwrap.indent(text_gen, indent_str, lambda line: True)
    else:
        for text in text_gen:
            yield textwrap.indent(text, indent_str, lambda line: True)

@classmethod
def from_exception(cls, exc, *args, **kwargs):
    """Create a TracebackException from an exception."""
    return cls(type(exc), exc, exc.__traceback__, *args, **kwargs)

def __eq__(self, other):
    if isinstance(other, TracebackException):
        return self.__dict__ == other.__dict__
    return NotImplemented

def format_exception_only(self):
    """Format the exception part of the traceback.

    The return value is a generator of strings, each ending in a newline.

    Generator yields the exception message.
    For :exc:`SyntaxError` exceptions, it
    also yields (before the exception message)
    several lines that (when printed)
    display detailed information about where the syntax error occurred.
    Following the message, generator also yields
    all the exception's ``__notes__``."""
    if self.exc_type is None:
        yield _format_final_exc_line(None, self._str)
        return
    stype = self.exc_type.__qualname__
    smod = self.exc_type.__module__
    if smod not in ('__main__', 'builtins'):
        if not isinstance(smod, str):
            smod = '<unknown>'
        stype = smod + '.' + stype
    if not issubclass(self.exc_type, SyntaxError):
        yield _format_final_exc_line(stype, self._str)
    else:
        yield from self._format_syntax_error(stype)
    if isinstance(self.__notes__, collections.abc.Sequence) and (not isinstance(self.__notes__, (str, bytes))):
        for note in self.__notes__:
            note = _safe_string(note, 'note')
            yield from [l + '\n' for l in note.split('\n')]
    elif self.__notes__ is not None:
        yield '{}\n'.format(_safe_string(self.__notes__, '__notes__', func=repr))

def print(self, *, file=None, chain=True):
    """Print the result of self.format(chain=chain) to 'file'."""
    if file is None:
        file = sys.stderr
    for line in self.format(chain=chain):
        print(line, file=file, end='')

def extended_frame_gen():
    for f, lineno in frame_gen:
        yield (f, (lineno, None, None, None))

def _compare_grouped_stats(old_group, new_group):
    statistics = []
    for traceback, stat in new_group.items():
        previous = old_group.pop(traceback, None)
        if previous is not None:
            stat = StatisticDiff(traceback, stat.size, stat.size - previous.size, stat.count, stat.count - previous.count)
        else:
            stat = StatisticDiff(traceback, stat.size, stat.size, stat.count, stat.count)
        statistics.append(stat)
    for traceback, stat in old_group.items():
        stat = StatisticDiff(traceback, 0, -stat.size, 0, -stat.count)
        statistics.append(stat)
    return statistics

def get_object_traceback(obj):
    """Get the traceback where the Python object *obj* was allocated.
    Return a Traceback instance.

    Return None if the tracemalloc module is not tracing memory allocations or
    did not trace the allocation of the object."""
    frames = _get_object_traceback(obj)
    if frames is not None:
        return Traceback(frames)
    else:
        return None

def _normalize_filename(filename):
    filename = os.path.normcase(filename)
    if filename.endswith('.pyc'):
        filename = filename[:-1]
    return filename

def take_snapshot():
    """Take a snapshot of traces of memory blocks allocated by Python."""
    if not is_tracing():
        raise RuntimeError('the tracemalloc module must be tracing memory allocations to take a snapshot')
    traces = _get_traces()
    traceback_limit = get_traceback_limit()
    return Snapshot(traces, traceback_limit)

def __eq__(self, other):
    if not isinstance(other, Statistic):
        return NotImplemented
    return self.traceback == other.traceback and self.size == other.size and (self.count == other.count)

def __str__(self):
    text = '%s: size=%s, count=%i' % (self.traceback, _format_size(self.size, False), self.count)
    if self.count:
        average = self.size / self.count
        text += ', average=%s' % _format_size(average, False)
    return text

def __eq__(self, other):
    if not isinstance(other, StatisticDiff):
        return NotImplemented
    return self.traceback == other.traceback and self.size == other.size and (self.size_diff == other.size_diff) and (self.count == other.count) and (self.count_diff == other.count_diff)

def __str__(self):
    text = '%s: size=%s (%s), count=%i (%+i)' % (self.traceback, _format_size(self.size, False), _format_size(self.size_diff, True), self.count, self.count_diff)
    if self.count:
        average = self.size / self.count
        text += ', average=%s' % _format_size(average, False)
    return text

@property
def filename(self):
    return self._frame[0]

@property
def lineno(self):
