    return self._frame == other._frame

@property
def total_nframe(self):
    return self._total_nframe

def __getitem__(self, index):
    if isinstance(index, slice):
        return tuple((Frame(trace) for trace in self._frames[index]))
    else:
        return Frame(self._frames[index])

def __eq__(self, other):
    if not isinstance(other, Traceback):
        return NotImplemented
    return self._frames == other._frames

def __lt__(self, other):
    if not isinstance(other, Traceback):
        return NotImplemented
    return self._frames < other._frames

def __repr__(self):
    s = f'<Traceback {tuple(self)}'
    if self._total_nframe is None:
        s += '>'
    else:
        s += f' total_nframe={self.total_nframe}>'
    return s

def format(self, limit=None, most_recent_first=False):
    lines = []
    if limit is not None:
        if limit > 0:
            frame_slice = self[-limit:]
        else:
            frame_slice = self[:limit]
    else:
        frame_slice = self
    if most_recent_first:
        frame_slice = reversed(frame_slice)
    for frame in frame_slice:
        lines.append('  File "%s", line %s' % (frame.filename, frame.lineno))
        line = linecache.getline(frame.filename, frame.lineno).strip()
        if line:
            lines.append('    %s' % line)
    return lines

@property
def domain(self):
    return self._trace[0]

@property
def size(self):
    return self._trace[1]

@property
def traceback(self):
    return Traceback(*self._trace[2:])

def __eq__(self, other):
    if not isinstance(other, Trace):
        return NotImplemented
    return self._trace == other._trace

def __init__(self, traces):
    Sequence.__init__(self)
    self._traces = traces

def __getitem__(self, index):
    if isinstance(index, slice):
        return tuple((Trace(trace) for trace in self._traces[index]))
    else:
        return Trace(self._traces[index])

def __eq__(self, other):
    if not isinstance(other, _Traces):
        return NotImplemented
    return self._traces == other._traces

def _match_frame_impl(self, filename, lineno):
    filename = _normalize_filename(filename)
    if not fnmatch.fnmatch(filename, self._filename_pattern):
        return False
    if self.lineno is None:
        return True
    else:
        return lineno == self.lineno

def _match_traceback(self, traceback):
    if self.all_frames:
        if any((self._match_frame_impl(filename, lineno) for filename, lineno in traceback)):
            return self.inclusive
        else:
            return not self.inclusive
    else:
        filename, lineno = traceback[0]
        return self._match_frame(filename, lineno)

def _match(self, trace):
    domain, size, traceback, total_nframe = trace
    res = self._match_traceback(traceback)
    if self.domain is not None:
        if self.inclusive:
            return res and domain == self.domain
        else:
            return res or domain != self.domain
    return res

def __init__(self, inclusive, domain):
    super().__init__(inclusive)
    self._domain = domain

def _match(self, trace):
    domain, size, traceback, total_nframe = trace
    return (domain == self.domain) ^ (not self.inclusive)

def __init__(self, traces, traceback_limit):
    self.traces = _Traces(traces)
    self.traceback_limit = traceback_limit

@staticmethod
def load(filename):
    """Load a snapshot from a file."""
    with open(filename, 'rb') as fp:
        return pickle.load(fp)

def _filter_trace(self, include_filters, exclude_filters, trace):
    if include_filters:
        if not any((trace_filter._match(trace) for trace_filter in include_filters)):
            return False
    if exclude_filters:
        if any((not trace_filter._match(trace) for trace_filter in exclude_filters)):
            return False
    return True

def filter_traces(self, filters):
    """Create a new Snapshot instance with a filtered traces sequence, filters
    is a list of Filter or DomainFilter instances.  If filters is an empty
    list, return a new Snapshot instance with a copy of the traces."""
    if not isinstance(filters, Iterable):
        raise TypeError('filters must be a list of filters, not %s' % type(filters).__name__)
    if filters:
        include_filters = []
        exclude_filters = []
        for trace_filter in filters:
            if trace_filter.inclusive:
                include_filters.append(trace_filter)
            else:
                exclude_filters.append(trace_filter)
        new_traces = [trace for trace in self.traces._traces if self._filter_trace(include_filters, exclude_filters, trace)]
    else:
        new_traces = self.traces._traces.copy()
    return Snapshot(new_traces, self.traceback_limit)

def config_dict(filename):
    """Convert content of config-file into dictionary."""
    with open(filename, 'r') as f:
        cfglines = f.readlines()
    cfgdict = {}
    for line in cfglines:
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        try:
            key, value = line.split('=')
        except ValueError:
            print('Bad line in config-file %s:\n%s' % (filename, line))
            continue
        key = key.strip()
        value = value.strip()
        if value in ['True', 'False', 'None', "''", '""']:
            value = eval(value)
        else:
            try:
                if '.' in value:
                    value = float(value)
                else:
                    value = int(value)
            except ValueError:
                pass
        cfgdict[key] = value
    return cfgdict

def __methodDict(cls, _dict):
    """helper function for Scrolled Canvas"""
    baseList = list(cls.__bases__)
    baseList.reverse()
    for _super in baseList:
        __methodDict(_super, _dict)
    for key, value in cls.__dict__.items():
        if type(value) == types.FunctionType:
            _dict[key] = value

def __methods(cls):
    """helper function for Scrolled Canvas"""
    _dict = {}
    __methodDict(cls, _dict)
    return _dict.keys()

def __forwardmethods(fromClass, toClass, toPart, exclude=()):
    _dict_1 = {}
    __methodDict(toClass, _dict_1)
    _dict = {}
    mfc = __methods(fromClass)
    for ex in _dict_1.keys():
        if ex[:1] == '_' or ex[-1:] == '_' or ex in exclude or (ex in mfc):
            pass
        else:
            _dict[ex] = _dict_1[ex]
    for method, func in _dict.items():
        d = {'method': method, 'func': func}
        if isinstance(toPart, str):
            execString = __stringBody % {'method': method, 'attribute': toPart}
        exec(execString, d)
        setattr(fromClass, method, d[method])

def read_docstrings(lang):
    """Read in docstrings from lang-specific docstring dictionary.

    Transfer docstrings, translated to lang, from a dictionary-file
    to the methods of classes Screen and Turtle and - in revised form -
    to the corresponding functions."""
    modname = 'turtle_docstringdict_%(language)s' % {'language': lang.lower()}
    module = __import__(modname)
    docsdict = module.docsdict
    for key in docsdict:
        try:
            eval(key).__doc__ = docsdict[key]
        except Exception:
            print('Bad docstring-entry: %s' % key)

def _make_global_funcs(functions, cls, obj, init, docrevise):
    for methodname in functions:
        method = getattr(cls, methodname)
        pl1, pl2 = getmethparlist(method)
        if pl1 == '':
            print('>>>>>>', pl1, pl2)
            continue
        defstr = __func_body.format(obj=obj, init=init, name=methodname, paramslist=pl1, argslist=pl2)
        exec(defstr, globals())
        globals()[methodname].__doc__ = docrevise(method.__doc__)

def __mul__(self, other):
    if isinstance(other, Vec2D):
        return self[0] * other[0] + self[1] * other[1]
    return Vec2D(self[0] * other, self[1] * other)

def __rmul__(self, other):
    if isinstance(other, int) or isinstance(other, float):
        return Vec2D(self[0] * other, self[1] * other)
    return NotImplemented

def reset(self, canvwidth=None, canvheight=None, bg=None):
    """Adjust canvas and scrollbars according to given canvas size."""
    if canvwidth:
        self.canvwidth = canvwidth
    if canvheight:
        self.canvheight = canvheight
    if bg:
        self.bg = bg
    self._canvas.config(bg=bg, scrollregion=(-self.canvwidth // 2, -self.canvheight // 2, self.canvwidth // 2, self.canvheight // 2))
    self._canvas.xview_moveto(0.5 * (self.canvwidth - self.width + 30) / self.canvwidth)
    self._canvas.yview_moveto(0.5 * (self.canvheight - self.height + 30) / self.canvheight)
    self.adjustScrolls()

def onResize(self, event):
    """self-explanatory"""
    self.adjustScrolls()

def bbox(self, *args):
    """'forward' method, which canvas itself has inherited...
    """
    return self._canvas.bbox(*args)

def cget(self, *args, **kwargs):
    """'forward' method, which canvas itself has inherited...
    """
    return self._canvas.cget(*args, **kwargs)

def setupcanvas(self, width, height, cwidth, cheight):
    self._canvas = ScrolledCanvas(self, width, height, cwidth, cheight)
    self._canvas.pack(expand=1, fill='both')

def _createpoly(self):
    """Create an invisible polygon item on canvas self.cv)
    """
    return self.cv.create_polygon((0, 0, 0, 0, 0, 0), fill='', outline='')

def _createline(self):
    """Create an invisible line item on canvas self.cv)
    """
    return self.cv.create_line(0, 0, 0, 0, fill='', width=2, capstyle=TK.ROUND)

def _drawline(self, lineitem, coordlist=None, fill=None, width=None, top=False):
    """Configure lineitem according to provided arguments:
    coordlist is sequence of coordinates
    fill is drawing color
    width is width of drawn line.
    top is a boolean value, which specifies if polyitem
    will be put on top of the canvas' displaylist so it
    will not be covered by other items."""
    if coordlist is not None:
        cl = []
        for x, y in coordlist:
            cl.append(x * self.xscale)
            cl.append(-y * self.yscale)
        self.cv.coords(lineitem, *cl)
    if fill is not None:
        self.cv.itemconfigure(lineitem, fill=fill)
    if width is not None:
        self.cv.itemconfigure(lineitem, width=width)
    if top:
        self.cv.tag_raise(lineitem)

def _delay(self, delay):
    """Delay subsequent canvas actions for delay ms."""
    self.cv.after(delay)

def _iscolorstring(self, color):
    """Check if the string color is a legal Tkinter color string.
    """
    try:
        rgb = self.cv.winfo_rgb(color)
        ok = True
    except TK.TclError:
        ok = False
    return ok

def _bgcolor(self, color=None):
    """Set canvas' backgroundcolor if color is not None,
    else return backgroundcolor."""
    if color is not None:
        self.cv.config(bg=color)
        self._update()
    else:
        return self.cv.cget('bg')

def _onclick(self, item, fun, num=1, add=None):
    """Bind fun to mouse-click event on turtle.
    fun must be a function with two arguments, the coordinates
    of the clicked point on the canvas.
    num, the number of the mouse-button defaults to 1"""
    if fun is None:
        self.cv.tag_unbind(item, '<Button-%s>' % num)
    else:
        def eventfun(event):
            x, y = (self.cv.canvasx(event.x) / self.xscale, -self.cv.canvasy(event.y) / self.yscale)
            fun(x, y)
        self.cv.tag_bind(item, '<Button-%s>' % num, eventfun, add)

def _ondrag(self, item, fun, num=1, add=None):
    """Bind fun to mouse-move-event (with pressed mouse button) on turtle.
    fun must be a function with two arguments, the coordinates of the
    actual mouse position on the canvas.
    num, the number of the mouse-button defaults to 1

    Every sequence of mouse-move-events on a turtle is preceded by a
    mouse-click event on that turtle."""
    if fun is None:
        self.cv.tag_unbind(item, '<Button%s-Motion>' % num)
    else:
        def eventfun(event):
            try:
                x, y = (self.cv.canvasx(event.x) / self.xscale, -self.cv.canvasy(event.y) / self.yscale)
                fun(x, y)
            except Exception:
                pass
        self.cv.tag_bind(item, '<Button%s-Motion>' % num, eventfun, add)

def _onkeyrelease(self, fun, key):
    """Bind fun to key-release event of key.
    Canvas must have focus. See method listen"""
    if fun is None:
        self.cv.unbind('<KeyRelease-%s>' % key, None)
    else:
        def eventfun(event):
            fun()
        self.cv.bind('<KeyRelease-%s>' % key, eventfun)

def _onkeypress(self, fun, key=None):
    """If key is given, bind fun to key-press event of key.
    Otherwise bind fun to any key-press.
    Canvas must have focus. See method listen."""
    if fun is None:
        if key is None:
            self.cv.unbind('<KeyPress>', None)
        else:
            self.cv.unbind('<KeyPress-%s>' % key, None)
    else:
        def eventfun(event):
            fun()
        if key is None:
            self.cv.bind('<KeyPress>', eventfun)
        else:
            self.cv.bind('<KeyPress-%s>' % key, eventfun)

def _createimage(self, image):
    """Create and return image item on canvas.
    """
    return self.cv.create_image(0, 0, image=image)

def _resize(self, canvwidth=None, canvheight=None, bg=None):
    """Resize the canvas the turtles are drawing on. Does
    not alter the drawing window."""
    if not isinstance(self.cv, ScrolledCanvas):
        return (self.canvwidth, self.canvheight)
    if canvwidth is canvheight is bg is None:
        return (self.cv.canvwidth, self.cv.canvheight)
    if canvwidth is not None:
        self.canvwidth = canvwidth
    if canvheight is not None:
        self.canvheight = canvheight
    self.cv.reset(canvwidth, canvheight, bg)

def _window_size(self):
    """Return the width and height of the turtle window.
    """
    width = self.cv.winfo_width()
    if width <= 1:
        width = self.cv['width']
    height = self.cv.winfo_height()
    if height <= 1:
        height = self.cv['height']
    return (width, height)

def __init__(self, type_, data=None):
    self._type = type_
    if type_ == 'polygon':
        if isinstance(data, list):
            data = tuple(data)
    elif type_ == 'image':
        if isinstance(data, str):
            if data.lower().endswith('.gif') and isfile(data):
                data = TurtleScreen._image(data)
    elif type_ == 'compound':
        data = []
    else:
        raise TurtleGraphicsError('There is no shape type %s' % type_)
    self._data = data

def reset(self, bufsize=None):
    if bufsize is None:
        for i in range(self.bufsize):
            self.buffer[i] = [None]
    else:
        self.bufsize = bufsize
        self.buffer = [[None]] * bufsize
    self.ptr = -1

def push(self, item):
    if self.bufsize > 0:
        if not self.cumulate:
            self.ptr = (self.ptr + 1) % self.bufsize
            self.buffer[self.ptr] = item
        else:
            self.buffer[self.ptr].append(item)

def _colorstr(self, color):
    """Return color string corresponding to args.

    Argument may be a string or a tuple of three
    numbers corresponding to actual colormode,
    i.e. in the range 0<=n<=colormode.

    If the argument doesn't represent a color,
    an error is raised."""
    if len(color) == 1:
        color = color[0]
    if isinstance(color, str):
        if self._iscolorstring(color) or color == '':
            return color
        else:
            raise TurtleGraphicsError('bad color string: %s' % str(color))
    try:
        r, g, b = color
    except (TypeError, ValueError):
        raise TurtleGraphicsError('bad color arguments: %s' % str(color))
    if self._colormode == 1.0:
        r, g, b = [round(255.0 * x) for x in (r, g, b)]
    if not (0 <= r <= 255 and 0 <= g <= 255 and (0 <= b <= 255)):
        raise TurtleGraphicsError('bad color sequence: %s' % str(color))
    return '#%02x%02x%02x' % (r, g, b)

def _color(self, cstr):
    if not cstr.startswith('#'):
        return cstr
    if len(cstr) == 7:
        cl = [int(cstr[i:i + 2], 16) for i in (1, 3, 5)]
    elif len(cstr) == 4:
        cl = [16 * int(cstr[h], 16) for h in cstr[1:]]
    else:
        raise TurtleGraphicsError('bad colorstring: %s' % cstr)
    return tuple((c * self._colormode / 255 for c in cl))

def _incrementudc(self):
    """Increment update counter."""
    if not TurtleScreen._RUNNING:
        TurtleScreen._RUNNING = True
        raise Terminator
    if self._tracing > 0:
        self._updatecounter += 1
        self._updatecounter %= self._tracing

def _setmode(self, mode=None):
    """Set turtle-mode to 'standard', 'world' or 'logo'.
    """
    if mode is None:
        return self._mode
    if mode not in ['standard', 'logo', 'world']:
        return
    self._mode = mode
    if mode in ['standard', 'world']:
        self._angleOffset = 0
        self._angleOrient = 1
    else:
        self._angleOffset = self._fullcircle / 4.0
        self._angleOrient = -1

def _setDegreesPerAU(self, fullcircle):
    """Helper function for degrees() and radians()"""
    self._fullcircle = fullcircle
    self._degreesPerAU = 360 / fullcircle
    if self._mode == 'standard':
        self._angleOffset = 0
    else:
        self._angleOffset = fullcircle / 4.0

def _goto(self, end):
    """move turtle to position end."""
    self._position = end

def _setshape(self, shapeIndex):
    screen = self.screen
    self.shapeIndex = shapeIndex
    if self._type == 'polygon' == screen._shapes[shapeIndex]._type:
        return
    if self._type == 'image' == screen._shapes[shapeIndex]._type:
        return
    if self._type in ['image', 'polygon']:
        screen._delete(self._item)
    elif self._type == 'compound':
        for item in self._item:
            screen._delete(item)
    self._type = screen._shapes[shapeIndex]._type
    if self._type == 'polygon':
        self._item = screen._createpoly()
    elif self._type == 'image':
        self._item = screen._createimage(screen._shapes['blank']._data)
    elif self._type == 'compound':
        self._item = [screen._createpoly() for item in screen._shapes[shapeIndex]._data]

def undobufferentries(self):
    """Return count of entries in the undobuffer.

    No argument.

    Example (for a Turtle instance named turtle):
    >>> while undobufferentries():
    ...     undo()"""
    if self.undobuffer is None:
        return 0
    return self.undobuffer.nr_of_items()

def _update_data(self):
    self.screen._incrementudc()
    if self.screen._updatecounter != 0:
        return
    if len(self.currentLine) > 1:
        self.screen._drawline(self.currentLineItem, self.currentLine, self._pencolor, self._pensize)

def _update(self):
    """Perform a Turtle-data update.
    """
    screen = self.screen
    if screen._tracing == 0:
        return
    elif screen._tracing == 1:
        self._update_data()
        self._drawturtle()
        screen._update()
        screen._delay(screen._delayvalue)
    else:
        self._update_data()
        if screen._updatecounter == 0:
            for t in screen.turtles():
                t._drawturtle()
            screen._update()

def _cc(self, args):
    """Convert colortriples to hexstrings.
    """
    if isinstance(args, str):
        return args
    try:
        r, g, b = args
    except (TypeError, ValueError):
        raise TurtleGraphicsError('bad color arguments: %s' % str(args))
    if self.screen._colormode == 1.0:
        r, g, b = [round(255.0 * x) for x in (r, g, b)]
    if not (0 <= r <= 255 and 0 <= g <= 255 and (0 <= b <= 255)):
        raise TurtleGraphicsError('bad color sequence: %s' % str(args))
    return '#%02x%02x%02x' % (r, g, b)

def _getshapepoly(self, polygon, compound=False):
    """Calculate transformed shape polygon according to resizemode
    and shapetransform."""
    if self._resizemode == 'user' or compound:
        t11, t12, t21, t22 = self._shapetrafo
    elif self._resizemode == 'auto':
        l = max(1, self._pensize / 5.0)
        t11, t12, t21, t22 = (l, 0, 0, l)
    elif self._resizemode == 'noresize':
        return polygon
    return tuple(((t11 * x + t12 * y, t21 * x + t22 * y) for x, y in polygon))

def _drawturtle(self):
    """Manages the correct rendering of the turtle with respect to
    its shape, resizemode, stretch and tilt etc."""
    screen = self.screen
    shape = screen._shapes[self.turtle.shapeIndex]
    ttype = shape._type
    titem = self.turtle._item
    if self._shown and screen._updatecounter == 0 and (screen._tracing > 0):
        self._hidden_from_screen = False
        tshape = shape._data
        if ttype == 'polygon':
            if self._resizemode == 'noresize':
                w = 1
            elif self._resizemode == 'auto':
                w = self._pensize
            else:
                w = self._outlinewidth
            shape = self._polytrafo(self._getshapepoly(tshape))
            fc, oc = (self._fillcolor, self._pencolor)
            screen._drawpoly(titem, shape, fill=fc, outline=oc, width=w, top=True)
        elif ttype == 'image':
            screen._drawimage(titem, self._position, tshape)
        elif ttype == 'compound':
            for item, (poly, fc, oc) in zip(titem, tshape):
                poly = self._polytrafo(self._getshapepoly(poly, True))
                screen._drawpoly(item, poly, fill=self._cc(fc), outline=self._cc(oc), width=self._outlinewidth, top=True)
    else:
        if self._hidden_from_screen:
            return
        if ttype == 'polygon':
            screen._drawpoly(titem, ((0, 0), (0, 0), (0, 0)), '', '')
        elif ttype == 'image':
            screen._drawimage(titem, self._position, screen._shapes['blank']._data)
        elif ttype == 'compound':
            for item in titem:
                screen._drawpoly(item, ((0, 0), (0, 0), (0, 0)), '', '')
        self._hidden_from_screen = True

def _clearstamp(self, stampid):
    """does the work for clearstamp() and clearstamps()
    """
    if stampid in self.stampItems:
        if isinstance(stampid, tuple):
            for subitem in stampid:
                self.screen._delete(subitem)
        else:
            self.screen._delete(stampid)
        self.stampItems.remove(stampid)
    item = ('stamp', stampid)
    buf = self.undobuffer
    if item not in buf.buffer:
        return
    index = buf.buffer.index(item)
    buf.buffer.remove(item)
    if index <= buf.ptr:
        buf.ptr = (buf.ptr - 1) % buf.bufsize
    buf.buffer.insert((buf.ptr + 1) % buf.bufsize, [None])

def _goto(self, end):
    """Move the pen to the point end, thereby drawing a line
    if pen is down. All other methods for turtle movement depend
    on this one."""
    go_modes = (self._drawing, self._pencolor, self._pensize, isinstance(self._fillpath, list))
    screen = self.screen
    undo_entry = ('go', self._position, end, go_modes, (self.currentLineItem, self.currentLine[:], screen._pointlist(self.currentLineItem), self.items[:]))
    if self.undobuffer:
        self.undobuffer.push(undo_entry)
    start = self._position
    if self._speed and screen._tracing == 1:
        diff = end - start
        diffsq = (diff[0] * screen.xscale) ** 2 + (diff[1] * screen.yscale) ** 2
        nhops = 1 + int(diffsq ** 0.5 / (3 * 1.1 ** self._speed * self._speed))
        delta = diff * (1.0 / nhops)
        for n in range(1, nhops):
            if n == 1:
                top = True
            else:
                top = False
            self._position = start + delta * n
            if self._drawing:
                screen._drawline(self.drawingLineItem, (start, self._position), self._pencolor, self._pensize, top)
            self._update()
        if self._drawing:
            screen._drawline(self.drawingLineItem, ((0, 0), (0, 0)), fill='', width=self._pensize)
    if self._drawing:
        self.currentLine.append(end)
    if isinstance(self._fillpath, list):
        self._fillpath.append(end)
    self._position = end
    if self._creatingPoly:
        self._poly.append(end)
    if len(self.currentLine) > 42:
        self._newLine()
    self._update()

def _newLine(self, usePos=True):
    """Closes current line item and starts a new one.
    Remark: if current line became too long, animation
    performance (via _drawline) slowed down considerably."""
    if len(self.currentLine) > 1:
        self.screen._drawline(self.currentLineItem, self.currentLine, self._pencolor, self._pensize)
        self.currentLineItem = self.screen._createline()
        self.items.append(self.currentLineItem)
    else:
        self.screen._drawline(self.currentLineItem, top=True)
    self.currentLine = []
    if usePos:
        self.currentLine = [self._position]

def get_poly(self):
    """Return the lastly recorded polygon.

    No argument.

    Example (for a Turtle instance named turtle):
    >>> p = turtle.get_poly()
    >>> turtle.register_shape("myFavouriteShape", p)"""
    if self._poly is not None:
