def _callTestMethod(self, method):
    if self._callMaybeAsync(method) is not None:
        warnings.warn(f'It is deprecated to return a value that is not None from a test case ({method})', DeprecationWarning, stacklevel=4)

def _callTearDown(self):
    self._callAsync(self.asyncTearDown)
    self._asyncioTestContext.run(self.tearDown)

def _callAsync(self, func, /, *args, **kwargs):
    assert self._asyncioRunner is not None, 'asyncio runner is not initialized'
    assert inspect.iscoroutinefunction(func), f'{func!r} is not an async function'
    return self._asyncioRunner.run(func(*args, **kwargs), context=self._asyncioTestContext)

def _callMaybeAsync(self, func, /, *args, **kwargs):
    assert self._asyncioRunner is not None, 'asyncio runner is not initialized'
    if inspect.iscoroutinefunction(func):
        return self._asyncioRunner.run(func(*args, **kwargs), context=self._asyncioTestContext)
    else:
        return self._asyncioTestContext.run(func, *args, **kwargs)

def _tearDownAsyncioRunner(self):
    runner = self._asyncioRunner
    runner.close()

def run(self, result=None):
    self._setupAsyncioRunner()
    try:
        return super().run(result)
    finally:
        self._tearDownAsyncioRunner()

def __del__(self):
    if self._asyncioRunner is not None:
        self._tearDownAsyncioRunner()

def _addSkip(result, test_case, reason):
    addSkip = getattr(result, 'addSkip', None)
    if addSkip is not None:
        addSkip(test_case, reason)
    else:
        warnings.warn('TestResult has no addSkip method, skips not reported', RuntimeWarning, 2)
        result.addSuccess(test_case)

def _addError(result, test, exc_info):
    if result is not None and exc_info is not None:
        if issubclass(exc_info[0], test.failureException):
            result.addFailure(test, exc_info)
        else:
            result.addError(test, exc_info)

def _enter_context(cm, addcleanup):
    cls = type(cm)
    try:
        enter = cls.__enter__
        exit = cls.__exit__
    except AttributeError:
        raise TypeError(f"'{cls.__module__}.{cls.__qualname__}' object does not support the context manager protocol") from None
    result = enter(cm)
    addcleanup(exit, cm, None, None, None)
    return result

def enterModuleContext(cm):
    """Same as enterContext, but module-wide."""
    return _enter_context(cm, addModuleCleanup)

def doModuleCleanups():
    """Execute all module cleanup functions. Normally called for you after
    tearDownModule."""
    exceptions = []
    while _module_cleanups:
        function, args, kwargs = _module_cleanups.pop()
        try:
            function(*args, **kwargs)
        except Exception as exc:
            exceptions.append(exc)
    if exceptions:
        raise exceptions[0]

def skip(reason):
    """Unconditionally skip a test."""
    def decorator(test_item):
        if not isinstance(test_item, type):
            @functools.wraps(test_item)
            def skip_wrapper(*args, **kwargs):
                raise SkipTest(reason)
            test_item = skip_wrapper
        test_item.__unittest_skip__ = True
        test_item.__unittest_skip_why__ = reason
        return test_item
    if isinstance(reason, types.FunctionType):
        test_item = reason
        reason = ''
        return decorator(test_item)
    return decorator

def skipIf(condition, reason):
    """Skip a test if the condition is true."""
    if condition:
        return skip(reason)
    return _id

def skipUnless(condition, reason):
    """Skip a test unless the condition is true."""
    if not condition:
        return skip(reason)
    return _id

def expectedFailure(test_item):
    test_item.__unittest_expecting_failure__ = True
    return test_item

def _is_subtype(expected, basetype):
    if isinstance(expected, tuple):
        return all((_is_subtype(e, basetype) for e in expected))
    return isinstance(expected, type) and issubclass(expected, basetype)

@contextlib.contextmanager
def testPartExecutor(self, test_case, subTest=False):
    old_success = self.success
    self.success = True
    try:
        yield
    except KeyboardInterrupt:
        raise
    except SkipTest as e:
        self.success = False
        _addSkip(self.result, test_case, str(e))
    except _ShouldStop:
        pass
    except:
        exc_info = sys.exc_info()
        if self.expecting_failure:
            self.expectedFailure = exc_info
        else:
            self.success = False
            if subTest:
                self.result.addSubTest(test_case.test_case, test_case, exc_info)
            else:
                _addError(self.result, test_case, exc_info)
        exc_info = None
    else:
        if subTest and self.success:
            self.result.addSubTest(test_case.test_case, test_case, None)
    finally:
        self.success = self.success and old_success

def decorator(test_item):
    if not isinstance(test_item, type):
        @functools.wraps(test_item)
        def skip_wrapper(*args, **kwargs):
            raise SkipTest(reason)
        test_item = skip_wrapper
    test_item.__unittest_skip__ = True
    test_item.__unittest_skip_why__ = reason
    return test_item

def _raiseFailure(self, standardMsg):
    msg = self.test_case._formatMessage(self.msg, standardMsg)
    raise self.test_case.failureException(msg)

def handle(self, name, args, kwargs):
    """If args is empty, assertRaises/Warns is being used as a
    context manager, so check for a 'msg' kwarg and return self.
    If args is not empty, call a callable passing positional and keyword
    arguments."""
    try:
        if not _is_subtype(self.expected, self._base_type):
            raise TypeError('%s() arg 1 must be %s' % (name, self._base_type_str))
        if not args:
            self.msg = kwargs.pop('msg', None)
            if kwargs:
                raise TypeError('%r is an invalid keyword argument for this function' % (next(iter(kwargs)),))
            return self
        callable_obj, *args = args
        try:
            self.obj_name = callable_obj.__name__
        except AttributeError:
            self.obj_name = str(callable_obj)
        with self:
            callable_obj(*args, **kwargs)
    finally:
        self = None

def __exit__(self, exc_type, exc_value, tb):
    if exc_type is None:
        try:
            exc_name = self.expected.__name__
        except AttributeError:
            exc_name = str(self.expected)
        if self.obj_name:
            self._raiseFailure('{} not raised by {}'.format(exc_name, self.obj_name))
        else:
            self._raiseFailure('{} not raised'.format(exc_name))
    else:
        traceback.clear_frames(tb)
    if not issubclass(exc_type, self.expected):
        return False
    self.exception = exc_value.with_traceback(None)
    if self.expected_regex is None:
        return True
    expected_regex = self.expected_regex
    if not expected_regex.search(str(exc_value)):
        self._raiseFailure('"{}" does not match "{}"'.format(expected_regex.pattern, str(exc_value)))
    return True

def __exit__(self, exc_type, exc_value, tb):
    self.warnings_manager.__exit__(exc_type, exc_value, tb)
    if exc_type is not None:
        return
    try:
        exc_name = self.expected.__name__
    except AttributeError:
        exc_name = str(self.expected)
    first_matching = None
    for m in self.warnings:
        w = m.message
        if not isinstance(w, self.expected):
            continue
        if first_matching is None:
            first_matching = w
        if self.expected_regex is not None and (not self.expected_regex.search(str(w))):
            continue
        self.warning = w
        self.filename = m.filename
        self.lineno = m.lineno
        return
    if first_matching is not None:
        self._raiseFailure('"{}" does not match "{}"'.format(self.expected_regex.pattern, str(first_matching)))
    if self.obj_name:
        self._raiseFailure('{} not triggered by {}'.format(exc_name, self.obj_name))
    else:
        self._raiseFailure('{} not triggered'.format(exc_name))

def __iter__(self):
    seen = set()
    for mapping in self.maps:
        for k in mapping:
            if k not in seen:
                seen.add(k)
                yield k

def enterContext(self, cm):
    """Enters the supplied context manager.

    If successful, also adds its __exit__ method as a cleanup
    function and returns the result of the __enter__ method."""
    return _enter_context(cm, self.addCleanup)

@classmethod
def addClassCleanup(cls, function, /, *args, **kwargs):
    """Same as addCleanup, except the cleanup items are called even if
    setUpClass fails (unlike tearDownClass)."""
    cls._class_cleanups.append((function, args, kwargs))

@classmethod
def enterClassContext(cls, cm):
    """Same as enterContext, but class-wide."""
    return _enter_context(cm, cls.addClassCleanup)

def setUp(self):
    """Hook method for setting up the test fixture before exercising it."""
    pass

def tearDown(self):
    """Hook method for deconstructing the test fixture after testing it."""
    pass

@classmethod
def setUpClass(cls):
    """Hook method for setting up class fixture before running tests in the class."""

@classmethod
def tearDownClass(cls):
    """Hook method for deconstructing the class fixture after running all tests in the class."""

@contextlib.contextmanager
def subTest(self, msg=_subtest_msg_sentinel, **params):
    """Return a context manager that will return the enclosed block
    of code in a subtest identified by the optional message and
    keyword parameters.  A failure in the subtest marks the test
    case as failed but resumes execution at the end of the enclosed
    block, allowing further test code to be executed."""
    if self._outcome is None or not self._outcome.result_supports_subtests:
        yield
        return
    parent = self._subtest
    if parent is None:
        params_map = _OrderedChainMap(params)
    else:
        params_map = parent.params.new_child(params)
    self._subtest = _SubTest(self, msg, params_map)
    try:
        with self._outcome.testPartExecutor(self._subtest, subTest=True):
            yield
        if not self._outcome.success:
            result = self._outcome.result
            if result is not None and result.failfast:
                raise _ShouldStop
        elif self._outcome.expectedFailure:
            raise _ShouldStop
    finally:
        self._subtest = parent

def _addExpectedFailure(self, result, exc_info):
    try:
        addExpectedFailure = result.addExpectedFailure
    except AttributeError:
        warnings.warn('TestResult has no addExpectedFailure method, reporting as passes', RuntimeWarning)
        result.addSuccess(self)
    else:
        addExpectedFailure(self, exc_info)

def _addUnexpectedSuccess(self, result):
    try:
        addUnexpectedSuccess = result.addUnexpectedSuccess
    except AttributeError:
        warnings.warn('TestResult has no addUnexpectedSuccess method, reporting as failure', RuntimeWarning)
        try:
            raise _UnexpectedSuccess from None
        except _UnexpectedSuccess:
            result.addFailure(self, sys.exc_info())
    else:
        addUnexpectedSuccess(self)

def _addDuration(self, result, elapsed):
    try:
        addDuration = result.addDuration
    except AttributeError:
        warnings.warn('TestResult has no addDuration method', RuntimeWarning)
    else:
        addDuration(self, elapsed)

def _callTestMethod(self, method):
    if method() is not None:
        warnings.warn(f'It is deprecated to return a value that is not None from a test case ({method})', DeprecationWarning, stacklevel=3)

def doCleanups(self):
    """Execute all cleanup functions. Normally called for you after
    tearDown."""
    outcome = self._outcome or _Outcome()
    while self._cleanups:
        function, args, kwargs = self._cleanups.pop()
        with outcome.testPartExecutor(self):
            self._callCleanup(function, *args, **kwargs)
    return outcome.success

@classmethod
def doClassCleanups(cls):
    """Execute all class cleanup functions. Normally called for you after
    tearDownClass."""
    cls.tearDown_exceptions = []
    while cls._class_cleanups:
        function, args, kwargs = cls._class_cleanups.pop()
        try:
            function(*args, **kwargs)
        except Exception:
            cls.tearDown_exceptions.append(sys.exc_info())

def debug(self):
    """Run the test without collecting errors in a TestResult"""
    testMethod = getattr(self, self._testMethodName)
    if getattr(self.__class__, '__unittest_skip__', False) or getattr(testMethod, '__unittest_skip__', False):
        skip_why = getattr(self.__class__, '__unittest_skip_why__', '') or getattr(testMethod, '__unittest_skip_why__', '')
        raise SkipTest(skip_why)
    self._callSetUp()
    self._callTestMethod(testMethod)
    self._callTearDown()
    while self._cleanups:
        function, args, kwargs = self._cleanups.pop()
        self._callCleanup(function, *args, **kwargs)

def skipTest(self, reason):
    """Skip this test."""
    raise SkipTest(reason)

def fail(self, msg=None):
    """Fail immediately, with the given message."""
    raise self.failureException(msg)

def assertFalse(self, expr, msg=None):
    """Check that the expression is false."""
    if expr:
        msg = self._formatMessage(msg, '%s is not false' % safe_repr(expr))
        raise self.failureException(msg)

def assertTrue(self, expr, msg=None):
    """Check that the expression is true."""
    if not expr:
        msg = self._formatMessage(msg, '%s is not true' % safe_repr(expr))
        raise self.failureException(msg)

def _formatMessage(self, msg, standardMsg):
    """Honour the longMessage attribute when generating failure messages.
    If longMessage is False this means:
    * Use only an explicit message if it is provided
    * Otherwise use the standard message for the assert

    If longMessage is True:
    * Use the standard message
    * If an explicit message is provided, plus ' : ' and the explicit message"""
    if not self.longMessage:
        return msg or standardMsg
    if msg is None:
        return standardMsg
    try:
        return '%s : %s' % (standardMsg, msg)
    except UnicodeDecodeError:
        return '%s : %s' % (safe_repr(standardMsg), safe_repr(msg))

def assertNoLogs(self, logger=None, level=None):
    """Fail unless no log messages of level *level* or higher are emitted
    on *logger_name* or its children.

    This method must be used as a context manager."""
    from ._log import _AssertLogsContext
    return _AssertLogsContext(self, logger, level, no_logs=True)

def _getAssertEqualityFunc(self, first, second):
    """Get a detailed comparison function for the types of the two args.

    Returns: A callable accepting (first, second, msg=None) that will
    raise a failure exception if first != second with a useful human
    readable error message for those types."""
    if type(first) is type(second):
        asserter = self._type_equality_funcs.get(type(first))
        if asserter is not None:
            if isinstance(asserter, str):
                asserter = getattr(self, asserter)
            return asserter
    return self._baseAssertEqual

def _baseAssertEqual(self, first, second, msg=None):
    """The default assertEqual implementation, not type specific."""
    if not first == second:
        standardMsg = '%s != %s' % _common_shorten_repr(first, second)
        msg = self._formatMessage(msg, standardMsg)
        raise self.failureException(msg)

def assertNotEqual(self, first, second, msg=None):
    """Fail if the two objects are equal as determined by the '!='
    operator."""
    if not first != second:
        msg = self._formatMessage(msg, '%s == %s' % (safe_repr(first), safe_repr(second)))
        raise self.failureException(msg)

def assertNotAlmostEqual(self, first, second, places=None, msg=None, delta=None):
    """Fail if the two objects are equal as determined by their
    difference rounded to the given number of decimal places
    (default 7) and comparing to zero, or by comparing that the
    difference between the two objects is less than the given delta.

    Note that decimal places (from zero) are usually not the same
    as significant digits (measured from the most significant digit).

    Objects that are equal automatically fail."""
    if delta is not None and places is not None:
        raise TypeError('specify delta or places not both')
    diff = abs(first - second)
    if delta is not None:
        if not first == second and diff > delta:
            return
        standardMsg = '%s == %s within %s delta (%s difference)' % (safe_repr(first), safe_repr(second), safe_repr(delta), safe_repr(diff))
    else:
        if places is None:
            places = 7
        if not first == second and round(diff, places) != 0:
            return
        standardMsg = '%s == %s within %r places' % (safe_repr(first), safe_repr(second), places)
    msg = self._formatMessage(msg, standardMsg)
    raise self.failureException(msg)

def _truncateMessage(self, message, diff):
    max_diff = self.maxDiff
    if max_diff is None or len(diff) <= max_diff:
        return message + diff
    return message + DIFF_OMITTED % len(diff)

def assertSetEqual(self, set1, set2, msg=None):
    """A set-specific equality assertion.

    Args:
        set1: The first set to compare.
        set2: The second set to compare.
        msg: Optional message to use on failure instead of a list of
                differences.

    assertSetEqual uses ducktyping to support different types of sets, and
    is optimized for sets specifically (parameters must support a
    difference method)."""
    try:
        difference1 = set1.difference(set2)
    except TypeError as e:
        self.fail('invalid type when attempting set difference: %s' % e)
    except AttributeError as e:
        self.fail('first argument does not support set difference: %s' % e)
    try:
        difference2 = set2.difference(set1)
    except TypeError as e:
        self.fail('invalid type when attempting set difference: %s' % e)
    except AttributeError as e:
        self.fail('second argument does not support set difference: %s' % e)
    if not (difference1 or difference2):
        return
    lines = []
    if difference1:
        lines.append('Items in the first set but not the second:')
        for item in difference1:
            lines.append(repr(item))
    if difference2:
        lines.append('Items in the second set but not the first:')
        for item in difference2:
            lines.append(repr(item))
    standardMsg = '\n'.join(lines)
    self.fail(self._formatMessage(msg, standardMsg))

def assertIn(self, member, container, msg=None):
    """Just like self.assertTrue(a in b), but with a nicer default message."""
    if member not in container:
        standardMsg = '%s not found in %s' % (safe_repr(member), safe_repr(container))
        self.fail(self._formatMessage(msg, standardMsg))

def assertNotIn(self, member, container, msg=None):
    """Just like self.assertTrue(a not in b), but with a nicer default message."""
    if member in container:
        standardMsg = '%s unexpectedly found in %s' % (safe_repr(member), safe_repr(container))
        self.fail(self._formatMessage(msg, standardMsg))

def assertIs(self, expr1, expr2, msg=None):
    """Just like self.assertTrue(a is b), but with a nicer default message."""
    if expr1 is not expr2:
        standardMsg = '%s is not %s' % (safe_repr(expr1), safe_repr(expr2))
        self.fail(self._formatMessage(msg, standardMsg))

def assertIsNot(self, expr1, expr2, msg=None):
    """Just like self.assertTrue(a is not b), but with a nicer default message."""
    if expr1 is expr2:
        standardMsg = 'unexpectedly identical: %s' % (safe_repr(expr1),)
        self.fail(self._formatMessage(msg, standardMsg))

def assertMultiLineEqual(self, first, second, msg=None):
    """Assert that two multi-line strings are equal."""
    self.assertIsInstance(first, str, 'First argument is not a string')
    self.assertIsInstance(second, str, 'Second argument is not a string')
    if first != second:
        if len(first) > self._diffThreshold or len(second) > self._diffThreshold:
            self._baseAssertEqual(first, second, msg)
        first_presplit = first
        second_presplit = second
        if first and second:
            if first[-1] != '\n' or second[-1] != '\n':
                first_presplit += '\n'
                second_presplit += '\n'
        elif second and second[-1] != '\n':
            second_presplit += '\n'
        elif first and first[-1] != '\n':
            first_presplit += '\n'
        firstlines = first_presplit.splitlines(keepends=True)
        secondlines = second_presplit.splitlines(keepends=True)
        standardMsg = '%s != %s' % _common_shorten_repr(first, second)
        diff = '\n' + ''.join(difflib.ndiff(firstlines, secondlines))
        standardMsg = self._truncateMessage(standardMsg, diff)
        self.fail(self._formatMessage(msg, standardMsg))

def assertLess(self, a, b, msg=None):
    """Just like self.assertTrue(a < b), but with a nicer default message."""
    if not a < b:
        standardMsg = '%s not less than %s' % (safe_repr(a), safe_repr(b))
        self.fail(self._formatMessage(msg, standardMsg))

def assertLessEqual(self, a, b, msg=None):
    """Just like self.assertTrue(a <= b), but with a nicer default message."""
    if not a <= b:
        standardMsg = '%s not less than or equal to %s' % (safe_repr(a), safe_repr(b))
        self.fail(self._formatMessage(msg, standardMsg))

def assertGreater(self, a, b, msg=None):
    """Just like self.assertTrue(a > b), but with a nicer default message."""
    if not a > b:
        standardMsg = '%s not greater than %s' % (safe_repr(a), safe_repr(b))
        self.fail(self._formatMessage(msg, standardMsg))

def assertGreaterEqual(self, a, b, msg=None):
    """Just like self.assertTrue(a >= b), but with a nicer default message."""
    if not a >= b:
        standardMsg = '%s not greater than or equal to %s' % (safe_repr(a), safe_repr(b))
        self.fail(self._formatMessage(msg, standardMsg))

def assertIsNone(self, obj, msg=None):
    """Same as self.assertTrue(obj is None), with a nicer default message."""
    if obj is not None:
        standardMsg = '%s is not None' % (safe_repr(obj),)
        self.fail(self._formatMessage(msg, standardMsg))

def assertIsNotNone(self, obj, msg=None):
    """Included for symmetry with assertIsNone."""
    if obj is None:
        standardMsg = 'unexpectedly None'
        self.fail(self._formatMessage(msg, standardMsg))

def assertIsInstance(self, obj, cls, msg=None):
    """Same as self.assertTrue(isinstance(obj, cls)), with a nicer
    default message."""
    if not isinstance(obj, cls):
        standardMsg = '%s is not an instance of %r' % (safe_repr(obj), cls)
        self.fail(self._formatMessage(msg, standardMsg))

def assertNotIsInstance(self, obj, cls, msg=None):
    """Included for symmetry with assertIsInstance."""
    if isinstance(obj, cls):
        standardMsg = '%s is an instance of %r' % (safe_repr(obj), cls)
        self.fail(self._formatMessage(msg, standardMsg))

def assertRegex(self, text, expected_regex, msg=None):
    """Fail the test unless the text matches the regular expression."""
    if isinstance(expected_regex, (str, bytes)):
        assert expected_regex, 'expected_regex must not be empty.'
        expected_regex = re.compile(expected_regex)
    if not expected_regex.search(text):
        standardMsg = "Regex didn't match: %r not found in %r" % (expected_regex.pattern, text)
        msg = self._formatMessage(msg, standardMsg)
        raise self.failureException(msg)

def assertNotRegex(self, text, unexpected_regex, msg=None):
    """Fail the test if the text matches the regular expression."""
    if isinstance(unexpected_regex, (str, bytes)):
        unexpected_regex = re.compile(unexpected_regex)
    match = unexpected_regex.search(text)
    if match:
        standardMsg = 'Regex matched: %r matches %r in %r' % (text[match.start():match.end()], unexpected_regex.pattern, text)
        msg = self._formatMessage(msg, standardMsg)
        raise self.failureException(msg)

def setUp(self):
    if self._setUpFunc is not None:
        self._setUpFunc()

def tearDown(self):
    if self._tearDownFunc is not None:
        self._tearDownFunc()

def __eq__(self, other):
    if not isinstance(other, self.__class__):
        return NotImplemented
    return self._setUpFunc == other._setUpFunc and self._tearDownFunc == other._tearDownFunc and (self._testFunc == other._testFunc) and (self._description == other._description)

def shortDescription(self):
    if self._description is not None:
        return self._description
    doc = self._testFunc.__doc__
    return doc and doc.split('\n')[0].strip() or None

def _subDescription(self):
    parts = []
    if self._message is not _subtest_msg_sentinel:
        parts.append('[{}]'.format(self._message))
    if self.params:
        params_desc = ', '.join(('{}={!r}'.format(k, v) for k, v in self.params.items()))
        parts.append('({})'.format(params_desc))
    return ' '.join(parts) or '(<subtest>)'

def shortDescription(self):
    """Returns a one-line description of the subtest, or None if no
    description has been provided."""
    return self.test_case.shortDescription()

@functools.wraps(test_item)
def skip_wrapper(*args, **kwargs):
    raise SkipTest(reason)

def _make_failed_import_test(name, suiteClass):
    message = 'Failed to import test module: %s\n%s' % (name, traceback.format_exc())
    return _make_failed_test(name, ImportError(message), suiteClass, message)

def _make_failed_load_tests(name, exception, suiteClass):
    message = 'Failed to call load_tests:\n%s' % (traceback.format_exc(),)
    return _make_failed_test(name, exception, suiteClass, message)

def _make_failed_test(methodname, exception, suiteClass, message):
    test = _FailedTest(methodname, exception)
    return (suiteClass((test,)), message)

def _make_skipped_test(methodname, exception, suiteClass):
    @case.skip(str(exception))
    def testSkipped(self):
        pass
    attrs = {methodname: testSkipped}
    TestClass = type('ModuleSkipped', (case.TestCase,), attrs)
    return suiteClass((TestClass(methodname),))

def getTestCaseNames(testCaseClass, prefix, sortUsing=util.three_way_cmp, testNamePatterns=None):
    import warnings
    warnings.warn('unittest.getTestCaseNames() is deprecated and will be removed in Python 3.13. Please use unittest.TestLoader.getTestCaseNames() instead.', DeprecationWarning, stacklevel=2)
    return _makeLoader(prefix, sortUsing, testNamePatterns=testNamePatterns).getTestCaseNames(testCaseClass)

def makeSuite(testCaseClass, prefix='test', sortUsing=util.three_way_cmp, suiteClass=suite.TestSuite):
    import warnings
    warnings.warn('unittest.makeSuite() is deprecated and will be removed in Python 3.13. Please use unittest.TestLoader.loadTestsFromTestCase() instead.', DeprecationWarning, stacklevel=2)
    return _makeLoader(prefix, sortUsing, suiteClass).loadTestsFromTestCase(testCaseClass)

def findTestCases(module, prefix='test', sortUsing=util.three_way_cmp, suiteClass=suite.TestSuite):
    import warnings
    warnings.warn('unittest.findTestCases() is deprecated and will be removed in Python 3.13. Please use unittest.TestLoader.loadTestsFromModule() instead.', DeprecationWarning, stacklevel=2)
    return _makeLoader(prefix, sortUsing, suiteClass).loadTestsFromModule(module)

def __init__(self, method_name, exception):
    self._exception = exception
    super(_FailedTest, self).__init__(method_name)

def __getattr__(self, name):
    if name != self._testMethodName:
        return super(_FailedTest, self).__getattr__(name)
    def testFailure():
        raise self._exception
    return testFailure

@case.skip(str(exception))
def testSkipped(self):
    pass

def loadTestsFromTestCase(self, testCaseClass):
    """Return a suite of all test cases contained in testCaseClass"""
    if issubclass(testCaseClass, suite.TestSuite):
        raise TypeError('Test cases should not be derived from TestSuite. Maybe you meant to derive from TestCase?')
    if testCaseClass in (case.TestCase, case.FunctionTestCase):
        testCaseNames = []
    else:
        testCaseNames = self.getTestCaseNames(testCaseClass)
        if not testCaseNames and hasattr(testCaseClass, 'runTest'):
            testCaseNames = ['runTest']
    loaded_suite = self.suiteClass(map(testCaseClass, testCaseNames))
    return loaded_suite

def loadTestsFromModule(self, module, *, pattern=None):
    """Return a suite of all test cases contained in the given module"""
    tests = []
    for name in dir(module):
        obj = getattr(module, name)
        if isinstance(obj, type) and issubclass(obj, case.TestCase) and (obj not in (case.TestCase, case.FunctionTestCase)):
            tests.append(self.loadTestsFromTestCase(obj))
    load_tests = getattr(module, 'load_tests', None)
    tests = self.suiteClass(tests)
    if load_tests is not None:
        try:
            return load_tests(self, tests, pattern)
        except Exception as e:
            error_case, error_message = _make_failed_load_tests(module.__name__, e, self.suiteClass)
            self.errors.append(error_message)
            return error_case
    return tests

def loadTestsFromNames(self, names, module=None):
    """Return a suite of all test cases found using the given sequence
    of string specifiers. See 'loadTestsFromName()'."""
    suites = [self.loadTestsFromName(name, module) for name in names]
    return self.suiteClass(suites)

def getTestCaseNames(self, testCaseClass):
    """Return a sorted sequence of method names found within testCaseClass
    """
    def shouldIncludeMethod(attrname):
        if not attrname.startswith(self.testMethodPrefix):
            return False
        testFunc = getattr(testCaseClass, attrname)
        if not callable(testFunc):
            return False
        fullName = f'%s.%s.%s' % (testCaseClass.__module__, testCaseClass.__qualname__, attrname)
        return self.testNamePatterns is None or any((fnmatchcase(fullName, pattern) for pattern in self.testNamePatterns))
    testFnNames = list(filter(shouldIncludeMethod, dir(testCaseClass)))
    if self.sortTestMethodsUsing:
        testFnNames.sort(key=functools.cmp_to_key(self.sortTestMethodsUsing))
    return testFnNames

def _get_directory_containing_module(self, module_name):
    module = sys.modules[module_name]
    full_path = os.path.abspath(module.__file__)
    if os.path.basename(full_path).lower().startswith('__init__.py'):
        return os.path.dirname(os.path.dirname(full_path))
    else:
        return os.path.dirname(full_path)

def _find_tests(self, start_dir, pattern):
    """Used by discovery. Yields test suites it loads."""
    name = self._get_name_from_path(start_dir)
    if name != '.' and name not in self._loading_packages:
        tests, should_recurse = self._find_test_path(start_dir, pattern)
        if tests is not None:
            yield tests
        if not should_recurse:
            return
    paths = sorted(os.listdir(start_dir))
    for path in paths:
        full_path = os.path.join(start_dir, path)
        tests, should_recurse = self._find_test_path(full_path, pattern)
        if tests is not None:
            yield tests
        if should_recurse:
            name = self._get_name_from_path(full_path)
            self._loading_packages.add(name)
            try:
                yield from self._find_tests(full_path, pattern)
            finally:
                self._loading_packages.discard(name)

def shouldIncludeMethod(attrname):
    if not attrname.startswith(self.testMethodPrefix):
        return False
    testFunc = getattr(testCaseClass, attrname)
    if not callable(testFunc):
        return False
    fullName = f'%s.%s.%s' % (testCaseClass.__module__, testCaseClass.__qualname__, attrname)
    return self.testNamePatterns is None or any((fnmatchcase(fullName, pattern) for pattern in self.testNamePatterns))

def _convert_name(name):
    if os.path.isfile(name) and name.lower().endswith('.py'):
        if os.path.isabs(name):
            rel_path = os.path.relpath(name, os.getcwd())
            if os.path.isabs(rel_path) or rel_path.startswith(os.pardir):
                return name
            name = rel_path
        return os.path.normpath(name)[:-3].replace('\\', '.').replace('/', '.')
    return name

def _convert_select_pattern(pattern):
    if not '*' in pattern:
        pattern = '*%s*' % pattern
    return pattern

def usageExit(self, msg=None):
    warnings.warn('TestProgram.usageExit() is deprecated and will be removed in Python 3.13', DeprecationWarning)
    if msg:
        print(msg)
    if self._discovery_parser is None:
        self._initArgParsers()
    self._print_help()
    sys.exit(2)

def _print_help(self, *args, **kwargs):
    if self.module is None:
        print(self._main_parser.format_help())
        print(MAIN_EXAMPLES % {'prog': self.progName})
        self._discovery_parser.print_help()
    else:
        print(self._main_parser.format_help())
        print(MODULE_EXAMPLES % {'prog': self.progName})

def parseArgs(self, argv):
    self._initArgParsers()
    if self.module is None:
        if len(argv) > 1 and argv[1].lower() == 'discover':
            self._do_discovery(argv[2:])
            return
        self._main_parser.parse_args(argv[1:], self)
        if not self.tests:
            self._do_discovery([])
            return
    else:
        self._main_parser.parse_args(argv[1:], self)
    if self.tests:
        self.testNames = _convert_names(self.tests)
        if __name__ == '__main__':
            self.module = None
    elif self.defaultTest is None:
        self.testNames = None
    elif isinstance(self.defaultTest, str):
        self.testNames = (self.defaultTest,)
    else:
        self.testNames = list(self.defaultTest)
    self.createTests()

def createTests(self, from_discovery=False, Loader=None):
    if self.testNamePatterns:
        self.testLoader.testNamePatterns = self.testNamePatterns
    if from_discovery:
        loader = self.testLoader if Loader is None else Loader()
        self.test = loader.discover(self.start, self.pattern, self.top)
    elif self.testNames is None:
        self.test = self.testLoader.loadTestsFromModule(self.module)
    else:
        self.test = self.testLoader.loadTestsFromNames(self.testNames, self.module)

def _do_discovery(self, argv, Loader=None):
    self.start = '.'
    self.pattern = 'test*.py'
    self.top = None
    if argv is not None:
        if self._discovery_parser is None:
            self._initArgParsers()
        self._discovery_parser.parse_args(argv, self)
    self.createTests(from_discovery=True, Loader=Loader)

def runTests(self):
    if self.catchbreak:
        installHandler()
    if self.testRunner is None:
        self.testRunner = runner.TextTestRunner
    if isinstance(self.testRunner, type):
        try:
            try:
                testRunner = self.testRunner(verbosity=self.verbosity, failfast=self.failfast, buffer=self.buffer, warnings=self.warnings, tb_locals=self.tb_locals, durations=self.durations)
            except TypeError:
                testRunner = self.testRunner(verbosity=self.verbosity, failfast=self.failfast, buffer=self.buffer, warnings=self.warnings)
        except TypeError:
            testRunner = self.testRunner()
    else:
        testRunner = self.testRunner
    self.result = testRunner.run(self.test)
    if self.exit:
        if self.result.testsRun == 0 and len(self.result.skipped) == 0:
            sys.exit(_NO_TESTS_EXITCODE)
        elif self.result.wasSuccessful():
            sys.exit(0)
        else:
            sys.exit(1)

def _is_async_obj(obj):
    if _is_instance_mock(obj) and (not isinstance(obj, AsyncMock)):
        return False
    if hasattr(obj, '__func__'):
        obj = getattr(obj, '__func__')
    return iscoroutinefunction(obj) or inspect.isawaitable(obj)

def _is_async_func(func):
    if getattr(func, '__code__', None):
        return iscoroutinefunction(func)
    else:
        return False

def _extract_mock(obj):
    if isinstance(obj, FunctionTypes) and hasattr(obj, 'mock'):
        return obj.mock
    else:
        return obj

def _get_signature_object(func, as_instance, eat_self):
    """Given an arbitrary, possibly callable object, try to create a suitable
    signature object.
    Return a (reduced func, signature) tuple, or None."""
    if isinstance(func, type) and (not as_instance):
        func = func.__init__
        eat_self = True
    elif isinstance(func, (classmethod, staticmethod)):
        if isinstance(func, classmethod):
            eat_self = True
        func = func.__func__
    elif not isinstance(func, FunctionTypes):
        try:
            func = func.__call__
        except AttributeError:
            return None
    if eat_self:
        sig_func = partial(func, None)
    else:
        sig_func = func
    try:
        return (func, inspect.signature(sig_func))
    except ValueError:
        return None

def _check_signature(func, mock, skipfirst, instance=False):
    sig = _get_signature_object(func, instance, skipfirst)
    if sig is None:
        return
    func, sig = sig
    def checksig(self, /, *args, **kwargs):
        sig.bind(*args, **kwargs)
    _copy_func_details(func, checksig)
    type(mock)._mock_check_sig = checksig
    type(mock).__signature__ = sig

def _copy_func_details(func, funcopy):
    for attribute in ('__name__', '__doc__', '__text_signature__', '__module__', '__defaults__', '__kwdefaults__'):
        try:
            setattr(funcopy, attribute, getattr(func, attribute))
        except AttributeError:
            pass

def _callable(obj):
    if isinstance(obj, type):
        return True
    if isinstance(obj, (staticmethod, classmethod, MethodType)):
        return _callable(obj.__func__)
    if getattr(obj, '__call__', None) is not None:
        return True
    return False

def _instance_callable(obj):
    """Given an object, return True if the object is callable.
    For classes, return True if instances would be callable."""
    if not isinstance(obj, type):
        return getattr(obj, '__call__', None) is not None
    for base in (obj,) + obj.__mro__:
        if base.__dict__.get('__call__') is not None:
            return True
    return False

def _setup_async_mock(mock):
    mock._is_coroutine = asyncio.coroutines._is_coroutine
    mock.await_count = 0
    mock.await_args = None
    mock.await_args_list = _CallList()
    def wrapper(attr, /, *args, **kwargs):
        return getattr(mock.mock, attr)(*args, **kwargs)
    for attribute in ('assert_awaited', 'assert_awaited_once', 'assert_awaited_with', 'assert_awaited_once_with', 'assert_any_await', 'assert_has_awaits', 'assert_not_awaited'):
        setattr(mock, attribute, partial(wrapper, attribute))

def _delegating_property(name):
    _allowed_names.add(name)
    _the_name = '_mock_' + name
    def _get(self, name=name, _the_name=_the_name):
        sig = self._mock_delegate
        if sig is None:
            return getattr(self, _the_name)
        return getattr(sig, name)
    def _set(self, value, name=name, _the_name=_the_name):
        sig = self._mock_delegate
        if sig is None:
            self.__dict__[_the_name] = value
        else:
            setattr(sig, name, value)
    return property(_get, _set)

def _check_and_set_parent(parent, value, name, new_name):
    value = _extract_mock(value)
    if not _is_instance_mock(value):
        return False
    if (value._mock_name or value._mock_new_name) or value._mock_parent is not None or value._mock_new_parent is not None:
        return False
    _parent = parent
    while _parent is not None:
        if _parent is value:
            return False
        _parent = _parent._mock_new_parent
    if new_name:
        value._mock_new_parent = parent
        value._mock_new_name = new_name
    if name:
        value._mock_parent = parent
        value._mock_name = name
    return True

def _try_iter(obj):
    if obj is None:
        return obj
    if _is_exception(obj):
        return obj
    if _callable(obj):
        return obj
    try:
        return iter(obj)
    except TypeError:
        return obj

def _get_target(target):
    try:
        target, attribute = target.rsplit('.', 1)
    except (TypeError, ValueError, AttributeError):
        raise TypeError(f'Need a valid target to patch. You supplied: {target!r}')
    return (partial(pkgutil.resolve_name, target), attribute)

def _clear_dict(in_dict):
    try:
        in_dict.clear()
    except AttributeError:
        keys = list(in_dict)
        for key in keys:
            del in_dict[key]

def _patch_stopall():
    """Stop all active patches. LIFO to unroll nested patches."""
    for patch in reversed(_patch._active_patches):
        patch.stop()

def _get_method(name, func):
    """Turns a callable object (like a mock) into a real function"""
    def method(self, /, *args, **kw):
        return func(self, *args, **kw)
    method.__name__ = name
    return method

def _get_eq(self):
    def __eq__(other):
        ret_val = self.__eq__._mock_return_value
        if ret_val is not DEFAULT:
            return ret_val
        if self is other:
            return True
        return NotImplemented
    return __eq__

def _get_ne(self):
    def __ne__(other):
        if self.__ne__._mock_return_value is not DEFAULT:
            return DEFAULT
        if self is other:
            return False
        return NotImplemented
    return __ne__

def _get_iter(self):
    def __iter__():
        ret_val = self.__iter__._mock_return_value
        if ret_val is DEFAULT:
            return iter([])
        return iter(ret_val)
    return __iter__

def _get_async_iter(self):
    def __aiter__():
        ret_val = self.__aiter__._mock_return_value
        if ret_val is DEFAULT:
            return _AsyncIterator(iter([]))
        return _AsyncIterator(iter(ret_val))
    return __aiter__

def _set_return_value(mock, method, name):
    fixed = _return_values.get(name, DEFAULT)
    if fixed is not DEFAULT:
        method.return_value = fixed
        return
    return_calculator = _calculate_return_value.get(name)
    if return_calculator is not None:
        return_value = return_calculator(mock)
        method.return_value = return_value
        return
    side_effector = _side_effect_methods.get(name)
    if side_effector is not None:
        method.side_effect = side_effector(mock)

def _format_call_signature(name, args, kwargs):
    message = '%s(%%s)' % name
    formatted_args = ''
    args_string = ', '.join([repr(arg) for arg in args])
    kwargs_string = ', '.join(['%s=%r' % (key, value) for key, value in kwargs.items()])
    if args_string:
        formatted_args = args_string
    if kwargs_string:
        if formatted_args:
            formatted_args += ', '
        formatted_args += kwargs_string
    return message % formatted_args

def _must_skip(spec, entry, is_type):
    """Return whether we should skip the first argument on spec's `entry`
    attribute."""
    if not isinstance(spec, type):
        if entry in getattr(spec, '__dict__', {}):
            return False
        spec = spec.__class__
    for klass in spec.__mro__:
        result = klass.__dict__.get(entry, DEFAULT)
        if result is DEFAULT:
            continue
        if isinstance(result, (staticmethod, classmethod)):
            return False
        elif isinstance(result, FunctionTypes):
            return is_type
        else:
            return False
    return is_type

def _to_stream(read_data):
    if isinstance(read_data, bytes):
        return io.BytesIO(read_data)
    else:
        return io.StringIO(read_data)

def seal(mock):
    """Disable the automatic generation of child mocks.

    Given an input Mock, seals it to ensure no further mocks will be generated
    when accessing an attribute that was not already defined.

    The operation recursively seals the mock passed in, meaning that
    the mock itself, any mocks generated by accessing one of its attributes,
    and all assigned mocks without a name or spec will be sealed."""
    mock._mock_sealed = True
    for attr in dir(mock):
        try:
            m = getattr(mock, attr)
        except AttributeError:
            continue
        if not isinstance(m, NonCallableMock):
            continue
        if isinstance(m._mock_children.get(attr), _SpecState):
            continue
        if m._mock_new_parent is mock:
            seal(m)

def __getattr__(self, name):
    if name == '__bases__':
        raise AttributeError
    return self._sentinels.setdefault(name, _SentinelObject(name))

def _get(self, name=name, _the_name=_the_name):
    sig = self._mock_delegate
    if sig is None:
        return getattr(self, _the_name)
    return getattr(sig, name)

def __contains__(self, value):
    if not isinstance(value, list):
        return list.__contains__(self, value)
    len_value = len(value)
    len_self = len(self)
    if len_value > len_self:
        return False
    for i in range(0, len_self - len_value + 1):
        sub_list = self[i:i + len_value]
        if sub_list == value:
            return True
    return False

def __new__(cls, spec=None, wraps=None, name=None, spec_set=None, parent=None, _spec_state=None, _new_name='', _new_parent=None, _spec_as_instance=False, _eat_self=None, unsafe=False, **kwargs):
    bases = (cls,)
    if not issubclass(cls, AsyncMockMixin):
        spec_arg = spec_set or spec
        if spec_arg is not None and _is_async_obj(spec_arg):
            bases = (AsyncMockMixin, cls)
    new = type(cls.__name__, bases, {'__doc__': cls.__doc__})
    instance = _safe_super(NonCallableMock, cls).__new__(new)
    return instance

def __get_return_value(self):
    ret = self._mock_return_value
    if self._mock_delegate is not None:
        ret = self._mock_delegate.return_value
    if ret is DEFAULT and self._mock_wraps is None:
        ret = self._get_child_mock(_new_parent=self, _new_name='()')
        self.return_value = ret
    return ret

def __set_return_value(self, value):
    if self._mock_delegate is not None:
        self._mock_delegate.return_value = value
    else:
        self._mock_return_value = value
        _check_and_set_parent(self, value, None, '()')

@property
def __class__(self):
    if self._spec_class is None:
        return type(self)
    return self._spec_class

def __get_side_effect(self):
    delegated = self._mock_delegate
    if delegated is None:
        return self._mock_side_effect
    sf = delegated.side_effect
    if sf is not None and (not callable(sf)) and (not isinstance(sf, _MockIter)) and (not _is_exception(sf)):
        sf = _MockIter(sf)
        delegated.side_effect = sf
    return sf

def __set_side_effect(self, value):
    value = _try_iter(value)
    delegated = self._mock_delegate
    if delegated is None:
        self._mock_side_effect = value
    else:
        delegated.side_effect = value

def reset_mock(self, visited=None, *, return_value: bool=False, side_effect: bool=False):
    """Restore the mock object to its initial state."""
    if visited is None:
        visited = []
    if id(self) in visited:
        return
    visited.append(id(self))
    self.called = False
    self.call_args = None
    self.call_count = 0
    self.mock_calls = _CallList()
    self.call_args_list = _CallList()
    self.method_calls = _CallList()
    if return_value:
        self._mock_return_value = DEFAULT
    if side_effect:
        self._mock_side_effect = None
    for child in self._mock_children.values():
        if isinstance(child, _SpecState) or child is _deleted:
            continue
        child.reset_mock(visited, return_value=return_value, side_effect=side_effect)
    ret = self._mock_return_value
    if _is_instance_mock(ret) and ret is not self:
        ret.reset_mock(visited)

def __getattr__(self, name):
    if name in {'_mock_methods', '_mock_unsafe'}:
        raise AttributeError(name)
    elif self._mock_methods is not None:
        if name not in self._mock_methods or name in _all_magics:
            raise AttributeError('Mock object has no attribute %r' % name)
    elif _is_magic(name):
        raise AttributeError(name)
    if not self._mock_unsafe and (not self._mock_methods or name not in self._mock_methods):
        if name.startswith(('assert', 'assret', 'asert', 'aseert', 'assrt')) or name in _ATTRIB_DENY_LIST:
            raise AttributeError(f'{name!r} is not a valid assertion. Use a spec for the mock if {name!r} is meant to be an attribute.')
    with NonCallableMock._lock:
        result = self._mock_children.get(name)
        if result is _deleted:
            raise AttributeError(name)
        elif result is None:
            wraps = None
            if self._mock_wraps is not None:
                wraps = getattr(self._mock_wraps, name)
            result = self._get_child_mock(parent=self, name=name, wraps=wraps, _new_name=name, _new_parent=self)
            self._mock_children[name] = result
        elif isinstance(result, _SpecState):
            try:
                result = create_autospec(result.spec, result.spec_set, result.instance, result.parent, result.name)
            except InvalidSpecError:
                target_name = self.__dict__['_mock_name'] or self
                raise InvalidSpecError(f'Cannot autospec attr {name!r} from target {target_name!r} as it has already been mocked out. [target={self!r}, attr={result.spec!r}]')
            self._mock_children[name] = result
    return result

def _extract_mock_name(self):
    _name_list = [self._mock_new_name]
    _parent = self._mock_new_parent
    last = self
    dot = '.'
    if _name_list == ['()']:
        dot = ''
    while _parent is not None:
        last = _parent
        _name_list.append(_parent._mock_new_name + dot)
        dot = '.'
        if _parent._mock_new_name == '()':
            dot = ''
        _parent = _parent._mock_new_parent
    _name_list = list(reversed(_name_list))
    _first = last._mock_name or 'mock'
    if len(_name_list) > 1:
        if _name_list[1] not in ('()', '().'):
            _first += '.'
    _name_list[0] = _first
    return ''.join(_name_list)

def __repr__(self):
    name = self._extract_mock_name()
    name_string = ''
    if name not in ('mock', 'mock.'):
        name_string = ' name=%r' % name
    spec_string = ''
    if self._spec_class is not None:
        spec_string = ' spec=%r'
        if self._spec_set:
            spec_string = ' spec_set=%r'
        spec_string = spec_string % self._spec_class.__name__
    return "<%s%s%s id='%s'>" % (type(self).__name__, name_string, spec_string, id(self))

def __dir__(self):
    """Filter the output of `dir(mock)` to only useful members."""
    if not FILTER_DIR:
        return object.__dir__(self)
    extras = self._mock_methods or []
    from_type = dir(type(self))
    from_dict = list(self.__dict__)
    from_child_mocks = [m_name for m_name, m_value in self._mock_children.items() if m_value is not _deleted]
    from_type = [e for e in from_type if not e.startswith('_')]
    from_dict = [e for e in from_dict if not e.startswith('_') or _is_magic(e)]
    return sorted(set(extras + from_type + from_dict + from_child_mocks))

def __setattr__(self, name, value):
    if name in _allowed_names:
        return object.__setattr__(self, name, value)
    elif self._spec_set and self._mock_methods is not None and (name not in self._mock_methods) and (name not in self.__dict__):
        raise AttributeError("Mock object has no attribute '%s'" % name)
    elif name in _unsupported_magics:
        msg = 'Attempting to set unsupported magic method %r.' % name
        raise AttributeError(msg)
    elif name in _all_magics:
        if self._mock_methods is not None and name not in self._mock_methods:
            raise AttributeError("Mock object has no attribute '%s'" % name)
        if not _is_instance_mock(value):
            setattr(type(self), name, _get_method(name, value))
            original = value
            value = lambda *args, **kw: original(self, *args, **kw)
        else:
            _check_and_set_parent(self, value, None, name)
            setattr(type(self), name, value)
            self._mock_children[name] = value
    elif name == '__class__':
        self._spec_class = value
        return
    elif _check_and_set_parent(self, value, name, name):
        self._mock_children[name] = value
    if self._mock_sealed and (not hasattr(self, name)):
        mock_name = f'{self._extract_mock_name()}.{name}'
        raise AttributeError(f'Cannot set {mock_name}')
    if isinstance(value, PropertyMock):
        self.__dict__[name] = value
        return
    return object.__setattr__(self, name, value)

def __delattr__(self, name):
    if name in _all_magics and name in type(self).__dict__:
        delattr(type(self), name)
        if name not in self.__dict__:
            return
    obj = self._mock_children.get(name, _missing)
    if name in self.__dict__:
        _safe_super(NonCallableMock, self).__delattr__(name)
    elif obj is _deleted:
        raise AttributeError(name)
    if obj is not _missing:
        del self._mock_children[name]
    self._mock_children[name] = _deleted

def _format_mock_call_signature(self, args, kwargs):
    name = self._mock_name or 'mock'
    return _format_call_signature(name, args, kwargs)

def _format_mock_failure_message(self, args, kwargs, action='call'):
    message = 'expected %s not found.\nExpected: %s\n  Actual: %s'
    expected_string = self._format_mock_call_signature(args, kwargs)
    call_args = self.call_args
    actual_string = self._format_mock_call_signature(*call_args)
    return message % (action, expected_string, actual_string)

def _call_matcher(self, _call):
    """Given a call (or simply an (args, kwargs) tuple), return a
    comparison key suitable for matching with other calls.
    This is a best effort method which relies on the spec's signature,
    if available, or falls back on the arguments themselves."""
    if isinstance(_call, tuple) and len(_call) > 2:
        sig = self._get_call_signature_from_name(_call[0])
    else:
        sig = self._spec_signature
    if sig is not None:
        if len(_call) == 2:
            name = ''
            args, kwargs = _call
        else:
            name, args, kwargs = _call
        try:
            bound_call = sig.bind(*args, **kwargs)
            return call(name, bound_call.args, bound_call.kwargs)
        except TypeError as e:
            return e.with_traceback(None)
    else:
        return _call

def assert_not_called(self):
    """assert that the mock was never called.
    """
    if self.call_count != 0:
        msg = "Expected '%s' to not have been called. Called %s times.%s" % (self._mock_name or 'mock', self.call_count, self._calls_repr())
        raise AssertionError(msg)

def assert_called(self):
    """assert that the mock was called at least once
    """
    if self.call_count == 0:
        msg = "Expected '%s' to have been called." % (self._mock_name or 'mock')
        raise AssertionError(msg)

def assert_called_once(self):
    """assert that the mock was called only once.
    """
    if not self.call_count == 1:
        msg = "Expected '%s' to have been called once. Called %s times.%s" % (self._mock_name or 'mock', self.call_count, self._calls_repr())
        raise AssertionError(msg)

def assert_called_once_with(self, /, *args, **kwargs):
    """assert that the mock was called exactly once and that that call was
    with the specified arguments."""
    if not self.call_count == 1:
        msg = "Expected '%s' to be called once. Called %s times.%s" % (self._mock_name or 'mock', self.call_count, self._calls_repr())
        raise AssertionError(msg)
    return self.assert_called_with(*args, **kwargs)

def assert_has_calls(self, calls, any_order=False):
    """assert the mock has been called with the specified calls.
    The `mock_calls` list is checked for the calls.

    If `any_order` is False (the default) then the calls must be
    sequential. There can be extra calls before or after the
    specified calls.

    If `any_order` is True then the calls can be in any order, but
    they must all appear in `mock_calls`."""
    expected = [self._call_matcher(c) for c in calls]
    cause = next((e for e in expected if isinstance(e, Exception)), None)
    all_calls = _CallList((self._call_matcher(c) for c in self.mock_calls))
    if not any_order:
        if expected not in all_calls:
            if cause is None:
                problem = 'Calls not found.'
            else:
                problem = 'Error processing expected calls.\nErrors: {}'.format([e if isinstance(e, Exception) else None for e in expected])
            raise AssertionError(f"{problem}\nExpected: {_CallList(calls)}{self._calls_repr(prefix='  Actual').rstrip('.')}") from cause
        return
    all_calls = list(all_calls)
    not_found = []
    for kall in expected:
        try:
            all_calls.remove(kall)
        except ValueError:
            not_found.append(kall)
    if not_found:
        raise AssertionError('%r does not contain all of %r in its call list, found %r instead' % (self._mock_name or 'mock', tuple(not_found), all_calls)) from cause

def _get_child_mock(self, /, **kw):
    """Create the child mocks for attributes and return value.
    By default child mocks will be the same type as the parent.
    Subclasses of Mock may want to override this to customize the way
    child mocks are made.

    For non-callable mocks the callable variant will be used (rather than
    any custom subclass)."""
    if self._mock_sealed:
        attribute = f".{kw['name']}" if 'name' in kw else '()'
        mock_name = self._extract_mock_name() + attribute
        raise AttributeError(mock_name)
    _new_name = kw.get('_new_name')
    if _new_name in self.__dict__['_spec_asyncs']:
        return AsyncMock(**kw)
    _type = type(self)
    if issubclass(_type, MagicMock) and _new_name in _async_method_magics:
        klass = AsyncMock
    elif issubclass(_type, AsyncMockMixin):
        if _new_name in _all_sync_magics or (self._mock_methods and _new_name in self._mock_methods):
            klass = MagicMock
        else:
            klass = AsyncMock
    elif not issubclass(_type, CallableMixin):
        if issubclass(_type, NonCallableMagicMock):
            klass = MagicMock
        elif issubclass(_type, NonCallableMock):
            klass = Mock
    else:
        klass = _type.__mro__[1]
    return klass(**kw)

def __contains__(self, item):
    for _call in self:
        assert len(item) == len(_call)
        if all([expected == actual for expected, actual in zip(item, _call)]):
            return True
    return False

def _execute_mock_call(self, /, *args, **kwargs):
    effect = self.side_effect
    if effect is not None:
        if _is_exception(effect):
            raise effect
        elif not _callable(effect):
            result = next(effect)
            if _is_exception(result):
                raise result
        else:
            result = effect(*args, **kwargs)
        if result is not DEFAULT:
            return result
    if self._mock_return_value is not DEFAULT:
        return self.return_value
    if self._mock_delegate and self._mock_delegate.return_value is not DEFAULT:
        return self.return_value
    if self._mock_wraps is not None:
        return self._mock_wraps(*args, **kwargs)
    return self.return_value

def __call__(self, func):
    if isinstance(func, type):
        return self.decorate_class(func)
    if inspect.iscoroutinefunction(func):
        return self.decorate_async_callable(func)
    return self.decorate_callable(func)

def decorate_class(self, klass):
    for attr in dir(klass):
        if not attr.startswith(patch.TEST_PREFIX):
            continue
        attr_value = getattr(klass, attr)
        if not hasattr(attr_value, '__call__'):
            continue
        patcher = self.copy()
        setattr(klass, attr, patcher(attr_value))
    return klass

@contextlib.contextmanager
def decoration_helper(self, patched, args, keywargs):
    extra_args = []
    with contextlib.ExitStack() as exit_stack:
        for patching in patched.patchings:
            arg = exit_stack.enter_context(patching)
            if patching.attribute_name is not None:
                keywargs.update(arg)
            elif patching.new is DEFAULT:
                extra_args.append(arg)
        args += tuple(extra_args)
        yield (args, keywargs)

def decorate_callable(self, func):
    if hasattr(func, 'patchings'):
        func.patchings.append(self)
        return func
    @wraps(func)
    def patched(*args, **keywargs):
        with self.decoration_helper(patched, args, keywargs) as (newargs, newkeywargs):
            return func(*newargs, **newkeywargs)
    patched.patchings = [self]
    return patched

def decorate_async_callable(self, func):
    if hasattr(func, 'patchings'):
        func.patchings.append(self)
        return func
    @wraps(func)
    async def patched(*args, **keywargs):
        with self.decoration_helper(patched, args, keywargs) as (newargs, newkeywargs):
            return await func(*newargs, **newkeywargs)
    patched.patchings = [self]
    return patched

def __exit__(self, *exc_info):
    """Undo the patch."""
    if not self.is_started:
        return
    if self.is_local and self.temp_original is not DEFAULT:
        setattr(self.target, self.attribute, self.temp_original)
    else:
        delattr(self.target, self.attribute)
        if not self.create and (not hasattr(self.target, self.attribute) or self.attribute in ('__doc__', '__module__', '__defaults__', '__annotations__', '__kwdefaults__')):
            setattr(self.target, self.attribute, self.temp_original)
    del self.temp_original
    del self.is_local
    del self.target
    exit_stack = self._exit_stack
    del self._exit_stack
    self.is_started = False
    return exit_stack.__exit__(*exc_info)

def stop(self):
    """Stop an active patch."""
    try:
        self._active_patches.remove(self)
    except ValueError:
        return None
    return self.__exit__(None, None, None)

def __call__(self, f):
    if isinstance(f, type):
        return self.decorate_class(f)
    if inspect.iscoroutinefunction(f):
        return self.decorate_async_callable(f)
    return self.decorate_callable(f)

def decorate_callable(self, f):
    @wraps(f)
    def _inner(*args, **kw):
        self._patch_dict()
        try:
            return f(*args, **kw)
        finally:
            self._unpatch_dict()
    return _inner

def decorate_async_callable(self, f):
    @wraps(f)
    async def _inner(*args, **kw):
        self._patch_dict()
        try:
            return await f(*args, **kw)
        finally:
            self._unpatch_dict()
    return _inner

def decorate_class(self, klass):
    for attr in dir(klass):
        attr_value = getattr(klass, attr)
        if attr.startswith(patch.TEST_PREFIX) and hasattr(attr_value, '__call__'):
            decorator = _patch_dict(self.in_dict, self.values, self.clear)
            decorated = decorator(attr_value)
            setattr(klass, attr, decorated)
    return klass

def _patch_dict(self):
    values = self.values
    if isinstance(self.in_dict, str):
        self.in_dict = pkgutil.resolve_name(self.in_dict)
    in_dict = self.in_dict
    clear = self.clear
    try:
        original = in_dict.copy()
    except AttributeError:
        original = {}
        for key in in_dict:
            original[key] = in_dict[key]
    self._original = original
    if clear:
        _clear_dict(in_dict)
    try:
        in_dict.update(values)
    except AttributeError:
        for key in values:
            in_dict[key] = values[key]

def _unpatch_dict(self):
    in_dict = self.in_dict
    original = self._original
    _clear_dict(in_dict)
    try:
        in_dict.update(original)
    except AttributeError:
        for key in original:
            in_dict[key] = original[key]

def __exit__(self, *args):
    """Unpatch the dict."""
    if self._original is not None:
        self._unpatch_dict()
    return False

def stop(self):
    """Stop an active patch."""
    try:
        _patch._active_patches.remove(self)
    except ValueError:
        return None
    return self.__exit__(None, None, None)

def __eq__(other):
    ret_val = self.__eq__._mock_return_value
    if ret_val is not DEFAULT:
        return ret_val
    if self is other:
        return True
    return NotImplemented

def __ne__(other):
    if self.__ne__._mock_return_value is not DEFAULT:
        return DEFAULT
    if self is other:
        return False
    return NotImplemented

def __iter__():
    ret_val = self.__iter__._mock_return_value
    if ret_val is DEFAULT:
        return iter([])
    return iter(ret_val)

def __aiter__():
    ret_val = self.__aiter__._mock_return_value
    if ret_val is DEFAULT:
        return _AsyncIterator(iter([]))
    return _AsyncIterator(iter(ret_val))

def _mock_set_magics(self):
    orig_magics = _magics | _async_method_magics
    these_magics = orig_magics
    if getattr(self, '_mock_methods', None) is not None:
        these_magics = orig_magics.intersection(self._mock_methods)
        remove_magics = set()
        remove_magics = orig_magics - these_magics
        for entry in remove_magics:
            if entry in type(self).__dict__:
                delattr(self, entry)
    these_magics = these_magics - set(type(self).__dict__)
    _type = type(self)
    for entry in these_magics:
        setattr(_type, entry, MagicProxy(entry, self))

def reset_mock(self, /, *args, return_value: bool=False, **kwargs):
    if return_value and self._mock_name and _is_magic(self._mock_name):
        return_value = False
    super().reset_mock(*args, return_value=return_value, **kwargs)

def __init__(self, name, parent):
