def _setupStdout(self):
    if self.buffer:
        if self._stderr_buffer is None:
            self._stderr_buffer = io.StringIO()
            self._stdout_buffer = io.StringIO()
        sys.stdout = self._stdout_buffer
        sys.stderr = self._stderr_buffer

def startTestRun(self):
    """Called once before any tests are executed.

    See startTest for a method called before each test."""

def _restoreStdout(self):
    if self.buffer:
        if self._mirrorOutput:
            output = sys.stdout.getvalue()
            error = sys.stderr.getvalue()
            if output:
                if not output.endswith('\n'):
                    output += '\n'
                self._original_stdout.write(STDOUT_LINE % output)
            if error:
                if not error.endswith('\n'):
                    error += '\n'
                self._original_stderr.write(STDERR_LINE % error)
        sys.stdout = self._original_stdout
        sys.stderr = self._original_stderr
        self._stdout_buffer.seek(0)
        self._stdout_buffer.truncate()
        self._stderr_buffer.seek(0)
        self._stderr_buffer.truncate()

def stopTestRun(self):
    """Called once after all tests are executed.

    See stopTest for a method called after each test."""

@failfast
def addFailure(self, test, err):
    """Called when an error has occurred. 'err' is a tuple of values as
    returned by sys.exc_info()."""
    self.failures.append((test, self._exc_info_to_string(err, test)))
    self._mirrorOutput = True

def addSubTest(self, test, subtest, err):
    """Called at the end of a subtest.
    'err' is None if the subtest ended successfully, otherwise it's a
    tuple of values as returned by sys.exc_info()."""
    if err is not None:
        if getattr(self, 'failfast', False):
            self.stop()
        if issubclass(err[0], test.failureException):
            errors = self.failures
        else:
            errors = self.errors
        errors.append((subtest, self._exc_info_to_string(err, test)))
        self._mirrorOutput = True

def addSuccess(self, test):
    """Called when a test has completed successfully"""
    pass

def addSkip(self, test, reason):
    """Called when a test is skipped."""
    self.skipped.append((test, reason))

def addExpectedFailure(self, test, err):
    """Called when an expected failure/error occurred."""
    self.expectedFailures.append((test, self._exc_info_to_string(err, test)))

@failfast
def addUnexpectedSuccess(self, test):
    """Called when a test was expected to fail, but succeed."""
    self.unexpectedSuccesses.append(test)

def wasSuccessful(self):
    """Tells whether or not this result was a success."""
    return len(self.failures) == len(self.errors) == 0 and (not hasattr(self, 'unexpectedSuccesses') or len(self.unexpectedSuccesses) == 0)

def stop(self):
    """Indicates that the tests should be aborted."""
    self.shouldStop = True

def _exc_info_to_string(self, err, test):
    """Converts a sys.exc_info()-style tuple of values into a string."""
    exctype, value, tb = err
    tb = self._clean_tracebacks(exctype, value, tb, test)
    tb_e = traceback.TracebackException(exctype, value, tb, capture_locals=self.tb_locals, compact=True)
    msgLines = list(tb_e.format())
    if self.buffer:
        output = sys.stdout.getvalue()
        error = sys.stderr.getvalue()
        if output:
            if not output.endswith('\n'):
                output += '\n'
            msgLines.append(STDOUT_LINE % output)
        if error:
            if not error.endswith('\n'):
                error += '\n'
            msgLines.append(STDERR_LINE % error)
    return ''.join(msgLines)

def _clean_tracebacks(self, exctype, value, tb, test):
    ret = None
    first = True
    excs = [(exctype, value, tb)]
    seen = {id(value)}
    while excs:
        exctype, value, tb = excs.pop()
        while tb and self._is_relevant_tb_level(tb):
            tb = tb.tb_next
        if exctype is test.failureException:
            self._remove_unittest_tb_frames(tb)
        if first:
            ret = tb
            first = False
        else:
            value.__traceback__ = tb
        if value is not None:
            for c in (value.__cause__, value.__context__):
                if c is not None and id(c) not in seen:
                    excs.append((type(c), c, c.__traceback__))
                    seen.add(id(c))
    return ret

def __getattr__(self, attr):
    if attr in ('stream', '__getstate__'):
        raise AttributeError(attr)
    return getattr(self.stream, attr)

def writeln(self, arg=None):
    if arg:
        self.write(arg)
    self.write('\n')

def getDescription(self, test):
    doc_first_line = test.shortDescription()
    if self.descriptions and doc_first_line:
        return '\n'.join((str(test), doc_first_line))
    else:
        return str(test)

def _write_status(self, test, status):
    is_subtest = isinstance(test, _SubTest)
    if is_subtest or self._newline:
        if not self._newline:
            self.stream.writeln()
        if is_subtest:
            self.stream.write('  ')
        self.stream.write(self.getDescription(test))
        self.stream.write(' ... ')
    self.stream.writeln(status)
    self.stream.flush()
    self._newline = True

def addSubTest(self, test, subtest, err):
    if err is not None:
        if self.showAll:
            if issubclass(err[0], subtest.failureException):
                self._write_status(subtest, 'FAIL')
            else:
                self._write_status(subtest, 'ERROR')
        elif self.dots:
            if issubclass(err[0], subtest.failureException):
                self.stream.write('F')
            else:
                self.stream.write('E')
            self.stream.flush()
    super(TextTestResult, self).addSubTest(test, subtest, err)

def addSuccess(self, test):
    super(TextTestResult, self).addSuccess(test)
    if self.showAll:
        self._write_status(test, 'ok')
    elif self.dots:
        self.stream.write('.')
        self.stream.flush()

def addError(self, test, err):
    super(TextTestResult, self).addError(test, err)
    if self.showAll:
        self._write_status(test, 'ERROR')
    elif self.dots:
        self.stream.write('E')
        self.stream.flush()

def addFailure(self, test, err):
    super(TextTestResult, self).addFailure(test, err)
    if self.showAll:
        self._write_status(test, 'FAIL')
    elif self.dots:
        self.stream.write('F')
        self.stream.flush()

def addSkip(self, test, reason):
    super(TextTestResult, self).addSkip(test, reason)
    if self.showAll:
        self._write_status(test, 'skipped {0!r}'.format(reason))
    elif self.dots:
        self.stream.write('s')
        self.stream.flush()

def addExpectedFailure(self, test, err):
    super(TextTestResult, self).addExpectedFailure(test, err)
    if self.showAll:
        self.stream.writeln('expected failure')
        self.stream.flush()
    elif self.dots:
        self.stream.write('x')
        self.stream.flush()

def addUnexpectedSuccess(self, test):
    super(TextTestResult, self).addUnexpectedSuccess(test)
    if self.showAll:
        self.stream.writeln('unexpected success')
        self.stream.flush()
    elif self.dots:
        self.stream.write('u')
        self.stream.flush()

def printErrors(self):
    if self.dots or self.showAll:
        self.stream.writeln()
        self.stream.flush()
    self.printErrorList('ERROR', self.errors)
    self.printErrorList('FAIL', self.failures)
    unexpectedSuccesses = getattr(self, 'unexpectedSuccesses', ())
    if unexpectedSuccesses:
        self.stream.writeln(self.separator1)
        for test in unexpectedSuccesses:
            self.stream.writeln(f'UNEXPECTED SUCCESS: {self.getDescription(test)}')
        self.stream.flush()

def _makeResult(self):
    try:
        return self.resultclass(self.stream, self.descriptions, self.verbosity, durations=self.durations)
    except TypeError:
        return self.resultclass(self.stream, self.descriptions, self.verbosity)

def _printDurations(self, result):
    if not result.collectedDurations:
        return
    ls = sorted(result.collectedDurations, key=lambda x: x[1], reverse=True)
    if self.durations > 0:
        ls = ls[:self.durations]
    self.stream.writeln('Slowest test durations')
    if hasattr(result, 'separator2'):
        self.stream.writeln(result.separator2)
    hidden = False
    for test, elapsed in ls:
        if self.verbosity < 2 and elapsed < 0.001:
            hidden = True
            continue
        self.stream.writeln('%-10s %s' % ('%.3fs' % elapsed, test))
    if hidden:
        self.stream.writeln('\n(durations < 0.001s were hidden; use -v to show these durations)')
    else:
        self.stream.writeln('')

def installHandler():
    global _interrupt_handler
    if _interrupt_handler is None:
        default_handler = signal.getsignal(signal.SIGINT)
        _interrupt_handler = _InterruptHandler(default_handler)
        signal.signal(signal.SIGINT, _interrupt_handler)

def removeHandler(method=None):
    if method is not None:
        @wraps(method)
        def inner(*args, **kwargs):
            initial = signal.getsignal(signal.SIGINT)
            removeHandler()
            try:
                return method(*args, **kwargs)
            finally:
                signal.signal(signal.SIGINT, initial)
        return inner
    global _interrupt_handler
    if _interrupt_handler is not None:
        signal.signal(signal.SIGINT, _interrupt_handler.original_handler)

def __init__(self, default_handler):
    self.called = False
    self.original_handler = default_handler
    if isinstance(default_handler, int):
        if default_handler == signal.SIG_DFL:
            default_handler = signal.default_int_handler
        elif default_handler == signal.SIG_IGN:
            def default_handler(unused_signum, unused_frame):
                pass
        else:
            raise TypeError('expected SIGINT signal handler to be signal.SIG_IGN, signal.SIG_DFL, or a callable object')
    self.default_handler = default_handler

def __call__(self, signum, frame):
    installed_handler = signal.getsignal(signal.SIGINT)
    if installed_handler is not self:
        self.default_handler(signum, frame)
    if self.called:
        self.default_handler(signum, frame)
    self.called = True
    for result in _results.keys():
        result.stop()

@wraps(method)
def inner(*args, **kwargs):
    initial = signal.getsignal(signal.SIGINT)
    removeHandler()
    try:
        return method(*args, **kwargs)
    finally:
        signal.signal(signal.SIGINT, initial)

def _call_if_exists(parent, attr):
    func = getattr(parent, attr, lambda: None)
    func()

def _isnotsuite(test):
    """A crude way to tell apart testcases and suites with duck-typing"""
    try:
        iter(test)
    except TypeError:
        return True
    return False

def __eq__(self, other):
    if not isinstance(other, self.__class__):
        return NotImplemented
    return list(self) == list(other)

def countTestCases(self):
    cases = self._removed_tests
    for test in self:
        if test:
            cases += test.countTestCases()
    return cases

def addTest(self, test):
    if not callable(test):
        raise TypeError('{} is not callable'.format(repr(test)))
    if isinstance(test, type) and issubclass(test, (case.TestCase, TestSuite)):
        raise TypeError('TestCases and TestSuites must be instantiated before passing them to addTest()')
    self._tests.append(test)

def addTests(self, tests):
    if isinstance(tests, str):
        raise TypeError('tests must be an iterable of tests, not a string')
    for test in tests:
        self.addTest(test)

def run(self, result):
    for index, test in enumerate(self):
        if result.shouldStop:
            break
        test(result)
        if self._cleanup:
            self._removeTestAtIndex(index)
    return result

def _removeTestAtIndex(self, index):
    """Stop holding a reference to the TestCase at index."""
    try:
        test = self._tests[index]
    except TypeError:
        pass
    else:
        if hasattr(test, 'countTestCases'):
            self._removed_tests += test.countTestCases()
        self._tests[index] = None

def debug(self):
    """Run the tests without collecting errors in a TestResult"""
    for test in self:
        test.debug()

def run(self, result, debug=False):
    topLevel = False
    if getattr(result, '_testRunEntered', False) is False:
        result._testRunEntered = topLevel = True
    for index, test in enumerate(self):
        if result.shouldStop:
            break
        if _isnotsuite(test):
            self._tearDownPreviousClass(test, result)
            self._handleModuleFixture(test, result)
            self._handleClassSetUp(test, result)
            result._previousTestClass = test.__class__
            if getattr(test.__class__, '_classSetupFailed', False) or getattr(result, '_moduleSetUpFailed', False):
                continue
        if not debug:
            test(result)
        else:
            test.debug()
        if self._cleanup:
            self._removeTestAtIndex(index)
    if topLevel:
        self._tearDownPreviousClass(None, result)
        self._handleModuleTearDown(result)
        result._testRunEntered = False
    return result

def _handleClassSetUp(self, test, result):
    previousClass = getattr(result, '_previousTestClass', None)
    currentClass = test.__class__
    if currentClass == previousClass:
        return
    if result._moduleSetUpFailed:
        return
    if getattr(currentClass, '__unittest_skip__', False):
        return
    failed = False
    try:
        currentClass._classSetupFailed = False
    except TypeError:
        pass
    setUpClass = getattr(currentClass, 'setUpClass', None)
    doClassCleanups = getattr(currentClass, 'doClassCleanups', None)
    if setUpClass is not None:
        _call_if_exists(result, '_setupStdout')
        try:
            try:
                setUpClass()
            except Exception as e:
                if isinstance(result, _DebugResult):
                    raise
                failed = True
                try:
                    currentClass._classSetupFailed = True
                except TypeError:
                    pass
                className = util.strclass(currentClass)
                self._createClassOrModuleLevelException(result, e, 'setUpClass', className)
            if failed and doClassCleanups is not None:
                doClassCleanups()
                for exc_info in currentClass.tearDown_exceptions:
                    self._createClassOrModuleLevelException(result, exc_info[1], 'setUpClass', className, info=exc_info)
        finally:
            _call_if_exists(result, '_restoreStdout')

def _get_previous_module(self, result):
    previousModule = None
    previousClass = getattr(result, '_previousTestClass', None)
    if previousClass is not None:
        previousModule = previousClass.__module__
    return previousModule

def _handleModuleFixture(self, test, result):
    previousModule = self._get_previous_module(result)
    currentModule = test.__class__.__module__
    if currentModule == previousModule:
        return
    self._handleModuleTearDown(result)
    result._moduleSetUpFailed = False
    try:
        module = sys.modules[currentModule]
    except KeyError:
        return
    setUpModule = getattr(module, 'setUpModule', None)
    if setUpModule is not None:
        _call_if_exists(result, '_setupStdout')
        try:
            try:
                setUpModule()
            except Exception as e:
                if isinstance(result, _DebugResult):
                    raise
                result._moduleSetUpFailed = True
                self._createClassOrModuleLevelException(result, e, 'setUpModule', currentModule)
            if result._moduleSetUpFailed:
                try:
                    case.doModuleCleanups()
                except Exception as e:
                    self._createClassOrModuleLevelException(result, e, 'setUpModule', currentModule)
        finally:
            _call_if_exists(result, '_restoreStdout')

def _createClassOrModuleLevelException(self, result, exc, method_name, parent, info=None):
    errorName = f'{method_name} ({parent})'
    self._addClassOrModuleLevelException(result, exc, errorName, info)

def _addClassOrModuleLevelException(self, result, exception, errorName, info=None):
    error = _ErrorHolder(errorName)
    addSkip = getattr(result, 'addSkip', None)
    if addSkip is not None and isinstance(exception, case.SkipTest):
        addSkip(error, str(exception))
    elif not info:
        result.addError(error, sys.exc_info())
    else:
        result.addError(error, info)

def _handleModuleTearDown(self, result):
    previousModule = self._get_previous_module(result)
    if previousModule is None:
        return
    if result._moduleSetUpFailed:
        return
    try:
        module = sys.modules[previousModule]
    except KeyError:
        return
    _call_if_exists(result, '_setupStdout')
    try:
        tearDownModule = getattr(module, 'tearDownModule', None)
        if tearDownModule is not None:
            try:
                tearDownModule()
            except Exception as e:
                if isinstance(result, _DebugResult):
                    raise
                self._createClassOrModuleLevelException(result, e, 'tearDownModule', previousModule)
        try:
            case.doModuleCleanups()
        except Exception as e:
            if isinstance(result, _DebugResult):
                raise
            self._createClassOrModuleLevelException(result, e, 'tearDownModule', previousModule)
    finally:
        _call_if_exists(result, '_restoreStdout')

def _tearDownPreviousClass(self, test, result):
    previousClass = getattr(result, '_previousTestClass', None)
    currentClass = test.__class__
    if currentClass == previousClass or previousClass is None:
        return
    if getattr(previousClass, '_classSetupFailed', False):
        return
    if getattr(result, '_moduleSetUpFailed', False):
        return
    if getattr(previousClass, '__unittest_skip__', False):
        return
    tearDownClass = getattr(previousClass, 'tearDownClass', None)
    doClassCleanups = getattr(previousClass, 'doClassCleanups', None)
    if tearDownClass is None and doClassCleanups is None:
        return
    _call_if_exists(result, '_setupStdout')
    try:
        if tearDownClass is not None:
            try:
                tearDownClass()
            except Exception as e:
                if isinstance(result, _DebugResult):
                    raise
                className = util.strclass(previousClass)
                self._createClassOrModuleLevelException(result, e, 'tearDownClass', className)
        if doClassCleanups is not None:
            doClassCleanups()
            for exc_info in previousClass.tearDown_exceptions:
                if isinstance(result, _DebugResult):
                    raise exc_info[1]
                className = util.strclass(previousClass)
                self._createClassOrModuleLevelException(result, exc_info[1], 'tearDownClass', className, info=exc_info)
    finally:
        _call_if_exists(result, '_restoreStdout')

def _shorten(s, prefixlen, suffixlen):
    skip = len(s) - prefixlen - suffixlen
    if skip > _PLACEHOLDER_LEN:
        s = '%s[%d chars]%s' % (s[:prefixlen], skip, s[len(s) - suffixlen:])
    return s

def _common_shorten_repr(*args):
    args = tuple(map(safe_repr, args))
    maxlen = max(map(len, args))
    if maxlen <= _MAX_LENGTH:
        return args
    prefix = commonprefix(args)
    prefixlen = len(prefix)
    common_len = _MAX_LENGTH - (maxlen - prefixlen + _MIN_BEGIN_LEN + _PLACEHOLDER_LEN)
    if common_len > _MIN_COMMON_LEN:
        assert _MIN_BEGIN_LEN + _PLACEHOLDER_LEN + _MIN_COMMON_LEN + (maxlen - prefixlen) < _MAX_LENGTH
        prefix = _shorten(prefix, _MIN_BEGIN_LEN, common_len)
        return tuple((prefix + s[prefixlen:] for s in args))
    prefix = _shorten(prefix, _MIN_BEGIN_LEN, _MIN_COMMON_LEN)
    return tuple((prefix + _shorten(s[prefixlen:], _MIN_DIFF_LEN, _MIN_END_LEN) for s in args))

def safe_repr(obj, short=False):
    try:
        result = repr(obj)
    except Exception:
        result = object.__repr__(obj)
    if not short or len(result) < _MAX_LENGTH:
        return result
    return result[:_MAX_LENGTH] + ' [truncated]...'

def sorted_list_difference(expected, actual):
    """Finds elements in only one or the other of two, sorted input lists.

    Returns a two-element tuple of lists.    The first list contains those
    elements in the "expected" list but not in the "actual" list, and the
    second contains those elements in the "actual" list but not in the
    "expected" list.    Duplicate elements in either input list are ignored."""
    i = j = 0
    missing = []
    unexpected = []
    while True:
        try:
            e = expected[i]
            a = actual[j]
            if e < a:
                missing.append(e)
                i += 1
                while expected[i] == e:
                    i += 1
            elif e > a:
                unexpected.append(a)
                j += 1
                while actual[j] == a:
                    j += 1
            else:
                i += 1
                try:
                    while expected[i] == e:
                        i += 1
                finally:
                    j += 1
                    while actual[j] == a:
                        j += 1
        except IndexError:
            missing.extend(expected[i:])
            unexpected.extend(actual[j:])
            break
    return (missing, unexpected)

def unorderable_list_difference(expected, actual):
    """Same behavior as sorted_list_difference but
    for lists of unorderable items (like dicts).

    As it does a linear search per item (remove) it
    has O(n*n) performance."""
    missing = []
    while expected:
        item = expected.pop()
        try:
            actual.remove(item)
        except ValueError:
            missing.append(item)
    return (missing, actual)

def three_way_cmp(x, y):
    """Return -1 if x < y, 0 if x == y and 1 if x > y"""
    return (x > y) - (x < y)

def _count_diff_all_purpose(actual, expected):
    """Returns list of (cnt_act, cnt_exp, elem) triples where the counts differ"""
    s, t = (list(actual), list(expected))
    m, n = (len(s), len(t))
    NULL = object()
    result = []
    for i, elem in enumerate(s):
        if elem is NULL:
            continue
        cnt_s = cnt_t = 0
        for j in range(i, m):
            if s[j] == elem:
                cnt_s += 1
                s[j] = NULL
        for j, other_elem in enumerate(t):
            if other_elem == elem:
                cnt_t += 1
                t[j] = NULL
        if cnt_s != cnt_t:
            diff = _Mismatch(cnt_s, cnt_t, elem)
            result.append(diff)
    for i, elem in enumerate(t):
        if elem is NULL:
            continue
        cnt_t = 0
        for j in range(i, n):
            if t[j] == elem:
                cnt_t += 1
                t[j] = NULL
        diff = _Mismatch(0, cnt_t, elem)
        result.append(diff)
    return result

def _count_diff_hashable(actual, expected):
    """Returns list of (cnt_act, cnt_exp, elem) triples where the counts differ"""
    s, t = (Counter(actual), Counter(expected))
    result = []
    for elem, cnt_s in s.items():
        cnt_t = t.get(elem, 0)
        if cnt_s != cnt_t:
            diff = _Mismatch(cnt_s, cnt_t, elem)
            result.append(diff)
    for elem, cnt_t in t.items():
        if elem not in s:
            diff = _Mismatch(0, cnt_t, elem)
            result.append(diff)
    return result

def __init__(self, reason, filename=None):
    self.args = (reason,)
    self.reason = reason
    if filename is not None:
        self.filename = filename

@property
def reason(self):
    return self.msg

@property
def headers(self):
    return self.hdrs

@headers.setter
def headers(self, headers):
    self.hdrs = headers

def __init__(self, message, content):
    URLError.__init__(self, message)
    self.content = content

def _coerce_args(*args):
    str_input = isinstance(args[0], str)
    for arg in args[1:]:
        if arg and isinstance(arg, str) != str_input:
            raise TypeError('Cannot mix str and non-str arguments')
    if str_input:
        return args + (_noop,)
    return _decode_args(args) + (_encode_result,)

def _fix_result_transcoding():
    _result_pairs = ((DefragResult, DefragResultBytes), (SplitResult, SplitResultBytes), (ParseResult, ParseResultBytes))
    for _decoded, _encoded in _result_pairs:
        _decoded._encoded_counterpart = _encoded
        _encoded._decoded_counterpart = _decoded

def _splitparams(url):
    if '/' in url:
        i = url.find(';', url.rfind('/'))
        if i < 0:
            return (url, '')
    else:
        i = url.find(';')
    return (url[:i], url[i + 1:])

def _splitnetloc(url, start=0):
    delim = len(url)
    for c in '/?#':
        wdelim = url.find(c, start)
        if wdelim >= 0:
            delim = min(delim, wdelim)
    return (url[start:delim], url[delim:])

def _checknetloc(netloc):
    if not netloc or netloc.isascii():
        return
    import unicodedata
    n = netloc.replace('@', '')
    n = n.replace(':', '')
    n = n.replace('#', '')
    n = n.replace('?', '')
    netloc2 = unicodedata.normalize('NFKC', n)
    if n == netloc2:
        return
    for c in '/?#@:':
        if c in netloc2:
            raise ValueError("netloc '" + netloc + "' contains invalid " + 'characters under NFKC normalization')

def _check_bracketed_netloc(netloc):
    hostname_and_port = netloc.rpartition('@')[2]
    before_bracket, have_open_br, bracketed = hostname_and_port.partition('[')
    if have_open_br:
        if before_bracket:
            raise ValueError('Invalid IPv6 URL')
        hostname, _, port = bracketed.partition(']')
        if port and (not port.startswith(':')):
            raise ValueError('Invalid IPv6 URL')
    else:
        hostname, _, port = hostname_and_port.partition(':')
    _check_bracketed_host(hostname)

def _check_bracketed_host(hostname):
    if hostname.startswith('v'):
        if not re.match('\\Av[a-fA-F0-9]+\\..+\\Z', hostname):
            raise ValueError(f'IPvFuture address is invalid')
    else:
        ip = ipaddress.ip_address(hostname)
        if isinstance(ip, ipaddress.IPv4Address):
            raise ValueError(f'An IPv4 address cannot be in brackets')

def urlunparse(components):
    """Put a parsed URL back together again.  This may result in a
    slightly different, but equivalent URL, if the URL that was parsed
    originally had redundant delimiters, e.g. a ? with an empty query
    (the draft states that these are equivalent)."""
    scheme, netloc, url, params, query, fragment, _coerce_result = _coerce_args(*components)
    if params:
        url = '%s;%s' % (url, params)
    return _coerce_result(urlunsplit((scheme, netloc, url, query, fragment)))

def urlunsplit(components):
    """Combine the elements of a tuple as returned by urlsplit() into a
    complete URL as a string. The data argument can be any five-item iterable.
    This may result in a slightly different, but equivalent URL, if the URL that
    was parsed originally had unnecessary delimiters (for example, a ? with an
    empty query; the RFC states that these are equivalent)."""
    scheme, netloc, url, query, fragment, _coerce_result = _coerce_args(*components)
    if netloc:
        if url and url[:1] != '/':
            url = '/' + url
        url = '//' + netloc + url
    elif url[:2] == '//':
        url = '//' + url
    elif scheme and scheme in uses_netloc and (not url or url[:1] == '/'):
        url = '//' + url
    if scheme:
        url = scheme + ':' + url
    if query:
        url = url + '?' + query
    if fragment:
        url = url + '#' + fragment
    return _coerce_result(url)

def urldefrag(url):
    """Removes any existing fragment from URL.

    Returns a tuple of the defragmented URL and the fragment.  If
    the URL contained no fragments, the second element is the
    empty string."""
    url, _coerce_result = _coerce_args(url)
    if '#' in url:
        s, n, p, a, q, frag = urlparse(url)
        defrag = urlunparse((s, n, p, a, q, ''))
    else:
        frag = ''
        defrag = url
    return _coerce_result(DefragResult(defrag, frag))

def unquote_to_bytes(string):
    """unquote_to_bytes('abc%20def') -> b'abc def'."""
    return bytes(_unquote_impl(string))

def _unquote_impl(string: bytes | bytearray | str) -> bytes | bytearray:
