def __init__(self, debuglevel=None, context=None, check_hostname=None):
    debuglevel = debuglevel if debuglevel is not None else http.client.HTTPSConnection.debuglevel
    AbstractHTTPHandler.__init__(self, debuglevel)
    if context is None:
        http_version = http.client.HTTPSConnection._http_vsn
        context = http.client._create_https_context(http_version)
    if check_hostname is not None:
        context.check_hostname = check_hostname
    self._context = context

def _https_connection(self, host):
    if self.key_file or self.cert_file:
        http_version = http.client.HTTPSConnection._http_vsn
        context = http.client._create_https_context(http_version)
        context.load_cert_chain(self.cert_file, self.key_file)
        if context.post_handshake_auth is not None:
            context.post_handshake_auth = True
    else:
        context = None
    return http.client.HTTPSConnection(host, context=context)

def open_https(self, url, data=None):
    """Use HTTPS protocol."""
    return self._open_generic_http(self._https_connection, url, data)

def getproxies_registry():
    """Return a dictionary of scheme -> proxy server URL mappings.

    Win32 uses the registry to store proxies."""
    proxies = {}
    try:
        import winreg
    except ImportError:
        return proxies
    try:
        internetSettings = winreg.OpenKey(winreg.HKEY_CURRENT_USER, 'Software\\Microsoft\\Windows\\CurrentVersion\\Internet Settings')
        proxyEnable = winreg.QueryValueEx(internetSettings, 'ProxyEnable')[0]
        if proxyEnable:
            proxyServer = str(winreg.QueryValueEx(internetSettings, 'ProxyServer')[0])
            if '=' not in proxyServer and ';' not in proxyServer:
                proxyServer = 'http={0};https={0};ftp={0}'.format(proxyServer)
            for p in proxyServer.split(';'):
                protocol, address = p.split('=', 1)
                if not re.match('(?:[^/:]+)://', address):
                    if protocol in ('http', 'https', 'ftp'):
                        address = 'http://' + address
                    elif protocol == 'socks':
                        address = 'socks://' + address
                proxies[protocol] = address
            if proxies.get('socks'):
                address = re.sub('^socks://', 'socks4://', proxies['socks'])
                proxies['http'] = proxies.get('http') or address
                proxies['https'] = proxies.get('https') or address
        internetSettings.Close()
    except (OSError, ValueError, TypeError):
        pass
    return proxies

def getproxies():
    """Return a dictionary of scheme -> proxy server URL mappings.

    Returns settings gathered from the environment, if specified,
    or the registry."""
    return getproxies_environment() or getproxies_registry()

def proxy_bypass_registry(host):
    try:
        import winreg
    except ImportError:
        return False
    try:
        internetSettings = winreg.OpenKey(winreg.HKEY_CURRENT_USER, 'Software\\Microsoft\\Windows\\CurrentVersion\\Internet Settings')
        proxyEnable = winreg.QueryValueEx(internetSettings, 'ProxyEnable')[0]
        proxyOverride = str(winreg.QueryValueEx(internetSettings, 'ProxyOverride')[0])
    except OSError:
        return False
    if not proxyEnable or not proxyOverride:
        return False
    return _proxy_bypass_winreg_override(host, proxyOverride)

def proxy_bypass(host):
    """Return True, if host should be bypassed.

    Checks proxy settings gathered from the environment, if specified,
    or the registry."""
    proxies = getproxies_environment()
    if proxies:
        return proxy_bypass_environment(host, proxies)
    else:
        return proxy_bypass_registry(host)

def __init__(self, fp):
    super(addbase, self).__init__(fp, '<urllib response>', delete=False)
    self.fp = fp

def __enter__(self):
    if self.fp.closed:
        raise ValueError('I/O operation on closed file')
    return self

def close(self):
    try:
        closehook = self.closehook
        hookargs = self.hookargs
        if closehook:
            self.closehook = None
            self.hookargs = None
            closehook(*hookargs)
    finally:
        super(addclosehook, self).close()

def __init__(self, fp, headers):
    super(addinfo, self).__init__(fp)
    self.headers = headers

@property
def status(self):
    return self.code

def read(self):
    """Reads the robots.txt URL and feeds it to the parser."""
    try:
        f = urllib.request.urlopen(self.url)
    except urllib.error.HTTPError as err:
        if err.code in (401, 403):
            self.disallow_all = True
        elif err.code >= 400 and err.code < 500:
            self.allow_all = True
        err.close()
    else:
        raw = f.read()
        self.parse(raw.decode('utf-8').splitlines())

def _add_entry(self, entry):
    if '*' in entry.useragents:
        if self.default_entry is None:
            self.default_entry = entry
    else:
        self.entries.append(entry)

def can_fetch(self, useragent, url):
    """using the parsed robots.txt decide if useragent can fetch url"""
    if self.disallow_all:
        return False
    if self.allow_all:
        return True
    if not self.last_checked:
        return False
    parsed_url = urllib.parse.urlparse(urllib.parse.unquote(url))
    url = urllib.parse.urlunparse(('', '', parsed_url.path, parsed_url.params, parsed_url.query, parsed_url.fragment))
    url = urllib.parse.quote(url)
    if not url:
        url = '/'
    for entry in self.entries:
        if entry.applies_to(useragent):
            return entry.allowance(url)
    if self.default_entry:
        return self.default_entry.allowance(url)
    return True

def crawl_delay(self, useragent):
    if not self.mtime():
        return None
    for entry in self.entries:
        if entry.applies_to(useragent):
            return entry.delay
    if self.default_entry:
        return self.default_entry.delay
    return None

def request_rate(self, useragent):
    if not self.mtime():
        return None
    for entry in self.entries:
        if entry.applies_to(useragent):
            return entry.req_rate
    if self.default_entry:
        return self.default_entry.req_rate
    return None

def site_maps(self):
    if not self.sitemaps:
        return None
    return self.sitemaps

def __str__(self):
    entries = self.entries
    if self.default_entry is not None:
        entries = entries + [self.default_entry]
    return '\n\n'.join(map(str, entries))

def __init__(self, path, allowance):
    if path == '' and (not allowance):
        allowance = True
    path = urllib.parse.urlunparse(urllib.parse.urlparse(path))
    self.path = urllib.parse.quote(path)
    self.allowance = allowance

def __str__(self):
    ret = []
    for agent in self.useragents:
        ret.append(f'User-agent: {agent}')
    if self.delay is not None:
        ret.append(f'Crawl-delay: {self.delay}')
    if self.req_rate is not None:
        rate = self.req_rate
        ret.append(f'Request-rate: {rate.requests}/{rate.seconds}')
    ret.extend(map(str, self.rulelines))
    return '\n'.join(ret)

def allowance(self, filename):
    """Preconditions:
    - our agent applies to this entry
    - filename is URL decoded"""
    for line in self.rulelines:
        if line.applies_to(filename):
            return line.allowance
    return True

def encode(in_file, out_file, name=None, mode=None, *, backtick=False):
    """Uuencode file"""
    opened_files = []
    try:
        if in_file == '-':
            in_file = sys.stdin.buffer
        elif isinstance(in_file, str):
            if name is None:
                name = os.path.basename(in_file)
            if mode is None:
                try:
                    mode = os.stat(in_file).st_mode
                except AttributeError:
                    pass
            in_file = open(in_file, 'rb')
            opened_files.append(in_file)
        if out_file == '-':
            out_file = sys.stdout.buffer
        elif isinstance(out_file, str):
            out_file = open(out_file, 'wb')
            opened_files.append(out_file)
        if name is None:
            name = '-'
        if mode is None:
            mode = 438
        name = name.replace('\n', '\\n')
        name = name.replace('\r', '\\r')
        out_file.write(('begin %o %s\n' % (mode & 511, name)).encode('ascii'))
        data = in_file.read(45)
        while len(data) > 0:
            out_file.write(binascii.b2a_uu(data, backtick=backtick))
            data = in_file.read(45)
        if backtick:
            out_file.write(b'`\nend\n')
        else:
            out_file.write(b' \nend\n')
    finally:
        for f in opened_files:
            f.close()

def test():
    """uuencode/uudecode main program"""
    import optparse
