def _get_command_stdout(command, *args):
    import io, os, shutil, subprocess
    try:
        path_dirs = os.environ.get('PATH', os.defpath).split(os.pathsep)
        path_dirs.extend(['/sbin', '/usr/sbin'])
        executable = shutil.which(command, path=os.pathsep.join(path_dirs))
        if executable is None:
            return None
        env = dict(os.environ)
        env['LC_ALL'] = 'C'
        if args != ('',):
            command = (executable, *args)
        else:
            command = (executable,)
        proc = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, env=env)
        if not proc:
            return None
        stdout, stderr = proc.communicate()
        return io.BytesIO(stdout)
    except (OSError, subprocess.SubprocessError):
        return None

def _find_mac_near_keyword(command, args, keywords, get_word_index):
    """Searches a command's output for a MAC address near a keyword.

    Each line of words in the output is case-insensitively searched for
    any of the given keywords.  Upon a match, get_word_index is invoked
    to pick a word from the line, given the index of the match.  For
    example, lambda i: 0 would get the first word on the line, while
    lambda i: i - 1 would get the word preceding the keyword."""
    stdout = _get_command_stdout(command, args)
    if stdout is None:
        return None
    first_local_mac = None
    for line in stdout:
        words = line.lower().rstrip().split()
        for i in range(len(words)):
            if words[i] in keywords:
                try:
                    word = words[get_word_index(i)]
                    mac = int(word.replace(_MAC_DELIM, b''), 16)
                except (ValueError, IndexError):
                    pass
                else:
                    if _is_universal(mac):
                        return mac
                    first_local_mac = first_local_mac or mac
    return first_local_mac or None

def _parse_mac(word):
    parts = word.split(_MAC_DELIM)
    if len(parts) != 6:
        return
    if _MAC_OMITS_LEADING_ZEROES:
        if not all((1 <= len(part) <= 2 for part in parts)):
            return
        hexstr = b''.join((part.rjust(2, b'0') for part in parts))
    else:
        if not all((len(part) == 2 for part in parts)):
            return
        hexstr = b''.join(parts)
    try:
        return int(hexstr, 16)
    except ValueError:
        return

def _find_mac_under_heading(command, args, heading):
    """Looks for a MAC address under a heading in a command's output.

    The first line of words in the output is searched for the given
    heading. Words at the same word index as the heading in subsequent
    lines are then examined to see if they look like MAC addresses."""
    stdout = _get_command_stdout(command, args)
    if stdout is None:
        return None
    keywords = stdout.readline().rstrip().split()
    try:
        column_index = keywords.index(heading)
    except ValueError:
        return None
    first_local_mac = None
    for line in stdout:
        words = line.rstrip().split()
        try:
            word = words[column_index]
        except IndexError:
            continue
        mac = _parse_mac(word)
        if mac is None:
            continue
        if _is_universal(mac):
            return mac
        if first_local_mac is None:
            first_local_mac = mac
    return first_local_mac

def _ifconfig_getnode():
    """Get the hardware address on Unix by running ifconfig."""
    keywords = (b'hwaddr', b'ether', b'address:', b'lladdr')
    for args in ('', '-a', '-av'):
        mac = _find_mac_near_keyword('ifconfig', args, keywords, lambda i: i + 1)
        if mac:
            return mac
    return None

def _ip_getnode():
    """Get the hardware address on Unix by running ip."""
    mac = _find_mac_near_keyword('ip', 'link', [b'link/ether'], lambda i: i + 1)
    if mac:
        return mac
    return None

def _arp_getnode():
    """Get the hardware address on Unix by running arp."""
    import os, socket
    if not hasattr(socket, 'gethostbyname'):
        return None
    try:
        ip_addr = socket.gethostbyname(socket.gethostname())
    except OSError:
        return None
    mac = _find_mac_near_keyword('arp', '-an', [os.fsencode(ip_addr)], lambda i: -1)
    if mac:
        return mac
    mac = _find_mac_near_keyword('arp', '-an', [os.fsencode(ip_addr)], lambda i: i + 1)
    if mac:
        return mac
    mac = _find_mac_near_keyword('arp', '-an', [os.fsencode('(%s)' % ip_addr)], lambda i: i + 2)
    if mac:
        return mac
    return None

def _lanscan_getnode():
    """Get the hardware address on Unix by running lanscan."""
    return _find_mac_near_keyword('lanscan', '-ai', [b'lan0'], lambda i: 0)

def _netstat_getnode():
    """Get the hardware address on Unix by running netstat."""
    return _find_mac_under_heading('netstat', '-ian', b'Address')

def _netbios_getnode():
    """[DEPRECATED] Get the hardware address on Windows."""
    return _windll_getnode()

def _unix_getnode():
    """Get the hardware address on Unix using the _uuid extension module."""
    if _generate_time_safe:
        uuid_time, _ = _generate_time_safe()
        return UUID(bytes=uuid_time).node

def _windll_getnode():
    """Get the hardware address on Windows using the _uuid extension module."""
    if _UuidCreate:
        uuid_bytes = _UuidCreate()
        return UUID(bytes_le=uuid_bytes).node

def getnode():
    """Get the hardware address as a 48-bit positive integer.

    The first time this runs, it may launch a separate program, which could
    be quite slow.  If all attempts to obtain the hardware address fail, we
    choose a random 48-bit number with its eighth bit set to 1 as recommended
    in RFC 4122."""
    global _node
    if _node is not None:
        return _node
    for getter in _GETTERS + [_random_getnode]:
        try:
            _node = getter()
        except:
            continue
        if _node is not None and 0 <= _node < 1 << 48:
            return _node
    assert False, '_random_getnode() returned invalid value: {}'.format(_node)

def uuid1(node=None, clock_seq=None):
    """Generate a UUID from a host ID, sequence number, and the current time.
    If 'node' is not given, getnode() is used to obtain the hardware
    address.  If 'clock_seq' is given, it is used as the sequence number;
    otherwise a random 14-bit sequence number is chosen."""
    if _generate_time_safe is not None and node is clock_seq is None:
        uuid_time, safely_generated = _generate_time_safe()
        try:
            is_safe = SafeUUID(safely_generated)
        except ValueError:
            is_safe = SafeUUID.unknown
        return UUID(bytes=uuid_time, is_safe=is_safe)
    global _last_timestamp
    import time
    nanoseconds = time.time_ns()
    timestamp = nanoseconds // 100 + 122192928000000000
    if _last_timestamp is not None and timestamp <= _last_timestamp:
        timestamp = _last_timestamp + 1
    _last_timestamp = timestamp
    if clock_seq is None:
        import random
        clock_seq = random.getrandbits(14)
    time_low = timestamp & 4294967295
    time_mid = timestamp >> 32 & 65535
    time_hi_version = timestamp >> 48 & 4095
    clock_seq_low = clock_seq & 255
    clock_seq_hi_variant = clock_seq >> 8 & 63
    if node is None:
        node = getnode()
    return UUID(fields=(time_low, time_mid, time_hi_version, clock_seq_hi_variant, clock_seq_low, node), version=1)

def uuid3(namespace, name):
    """Generate a UUID from the MD5 hash of a namespace UUID and a name."""
    if isinstance(name, str):
        name = bytes(name, 'utf-8')
    from hashlib import md5
    digest = md5(namespace.bytes + name, usedforsecurity=False).digest()
    return UUID(bytes=digest[:16], version=3)

def uuid4():
    """Generate a random UUID."""
    return UUID(bytes=os.urandom(16), version=4)

def uuid5(namespace, name):
    """Generate a UUID from the SHA-1 hash of a namespace UUID and a name."""
    if isinstance(name, str):
        name = bytes(name, 'utf-8')
    from hashlib import sha1
    hash = sha1(namespace.bytes + name).digest()
    return UUID(bytes=hash[:16], version=5)

def main():
    """Run the uuid command line interface."""
    uuid_funcs = {'uuid1': uuid1, 'uuid3': uuid3, 'uuid4': uuid4, 'uuid5': uuid5}
    uuid_namespace_funcs = ('uuid3', 'uuid5')
    namespaces = {'@dns': NAMESPACE_DNS, '@url': NAMESPACE_URL, '@oid': NAMESPACE_OID, '@x500': NAMESPACE_X500}
    import argparse
    parser = argparse.ArgumentParser(description='Generates a uuid using the selected uuid function.')
    parser.add_argument('-u', '--uuid', choices=uuid_funcs.keys(), default='uuid4', help='The function to use to generate the uuid. By default uuid4 function is used.')
    parser.add_argument('-n', '--namespace', help="The namespace is a UUID, or '@ns' where 'ns' is a well-known predefined UUID addressed by namespace name. Such as @dns, @url, @oid, and @x500. Only required for uuid3/uuid5 functions.")
    parser.add_argument('-N', '--name', help='The name used as part of generating the uuid. Only required for uuid3/uuid5 functions.')
    args = parser.parse_args()
    uuid_func = uuid_funcs[args.uuid]
    namespace = args.namespace
    name = args.name
    if args.uuid in uuid_namespace_funcs:
        if not namespace or not name:
            parser.error(f"Incorrect number of arguments. {args.uuid} requires a namespace and a name. Run 'python -m uuid -h' for more information.")
        namespace = namespaces[namespace] if namespace in namespaces else UUID(namespace)
        print(uuid_func(namespace, name))
    else:
        print(uuid_func())

def __getstate__(self):
    d = {'int': self.int}
    if self.is_safe != SafeUUID.unknown:
        d['is_safe'] = self.is_safe.value
    return d

def __setstate__(self, state):
    object.__setattr__(self, 'int', state['int'])
    object.__setattr__(self, 'is_safe', SafeUUID(state['is_safe']) if 'is_safe' in state else SafeUUID.unknown)

def __eq__(self, other):
    if isinstance(other, UUID):
        return self.int == other.int
    return NotImplemented

def __lt__(self, other):
    if isinstance(other, UUID):
        return self.int < other.int
    return NotImplemented

def __gt__(self, other):
    if isinstance(other, UUID):
        return self.int > other.int
    return NotImplemented

def __le__(self, other):
    if isinstance(other, UUID):
        return self.int <= other.int
    return NotImplemented

def __ge__(self, other):
    if isinstance(other, UUID):
        return self.int >= other.int
    return NotImplemented

def __str__(self):
    hex = '%032x' % self.int
    return '%s-%s-%s-%s-%s' % (hex[:8], hex[8:12], hex[12:16], hex[16:20], hex[20:])

@property
def bytes(self):
    return self.int.to_bytes(16)

@property
def bytes_le(self):
    bytes = self.bytes
    return bytes[4 - 1::-1] + bytes[6 - 1:4 - 1:-1] + bytes[8 - 1:6 - 1:-1] + bytes[8:]

@property
def fields(self):
    return (self.time_low, self.time_mid, self.time_hi_version, self.clock_seq_hi_variant, self.clock_seq_low, self.node)

@property
def time_low(self):
    return self.int >> 96

@property
def time_mid(self):
    return self.int >> 80 & 65535

@property
def clock_seq_hi_variant(self):
    return self.int >> 56 & 255

@property
def clock_seq_low(self):
    return self.int >> 48 & 255

@property
def time(self):
    return (self.time_hi_version & 4095) << 48 | self.time_mid << 32 | self.time_low

@property
def clock_seq(self):
    return (self.clock_seq_hi_variant & 63) << 8 | self.clock_seq_low

@property
def node(self):
    return self.int & 281474976710655

@property
def hex(self):
    return '%032x' % self.int

@property
def urn(self):
    return 'urn:uuid:' + str(self)

@property
def variant(self):
    if not self.int & 32768 << 48:
        return RESERVED_NCS
    elif not self.int & 16384 << 48:
        return RFC_4122
    elif not self.int & 8192 << 48:
        return RESERVED_MICROSOFT
    else:
        return RESERVED_FUTURE

@property
def version(self):
    if self.variant == RFC_4122:
        return int(self.int >> 76 & 15)

def clear_directory(self, path):
    for fn in os.listdir(path):
        fn = os.path.join(path, fn)
        if os.path.islink(fn) or os.path.isfile(fn):
            os.remove(fn)
        elif os.path.isdir(fn):
            shutil.rmtree(fn)

def _venv_path(self, env_dir, name):
    vars = {'base': env_dir, 'platbase': env_dir, 'installed_base': env_dir, 'installed_platbase': env_dir}
    return sysconfig.get_path(name, scheme='venv', vars=vars)

@classmethod
def _same_path(cls, path1, path2):
    """Check whether two paths appear the same.

    Whether they refer to the same file is irrelevant; we're testing for
    whether a human reader would look at the path string and easily tell
    that they're the same file."""
    if sys.platform == 'win32':
        if os.path.normcase(path1) == os.path.normcase(path2):
            return True
        import _winapi
        try:
            path1 = _winapi.GetLongPathName(os.fsdecode(path1))
        except OSError:
            pass
        try:
            path2 = _winapi.GetLongPathName(os.fsdecode(path2))
        except OSError:
            pass
        if os.path.normcase(path1) == os.path.normcase(path2):
            return True
        return False
    else:
        return path1 == path2

def create_configuration(self, context):
    """Create a configuration file indicating where the environment's Python
    was copied from, and whether the system site-packages should be made
    available in the environment.

    :param context: The information for the environment creation request
                    being processed."""
    context.cfg_path = path = os.path.join(context.env_dir, 'pyvenv.cfg')
    with open(path, 'w', encoding='utf-8') as f:
        f.write('home = %s\n' % context.python_dir)
        if self.system_site_packages:
            incl = 'true'
        else:
            incl = 'false'
        f.write('include-system-site-packages = %s\n' % incl)
        f.write('version = %d.%d.%d\n' % sys.version_info[:3])
        if self.prompt is not None:
            f.write(f'prompt = {self.prompt!r}\n')
        f.write('executable = %s\n' % os.path.realpath(sys.executable))
        args = []
        nt = os.name == 'nt'
        if nt and self.symlinks:
            args.append('--symlinks')
        if not nt and (not self.symlinks):
            args.append('--copies')
        if not self.with_pip:
            args.append('--without-pip')
        if self.system_site_packages:
            args.append('--system-site-packages')
        if self.clear:
            args.append('--clear')
        if self.upgrade:
            args.append('--upgrade')
        if self.upgrade_deps:
            args.append('--upgrade-deps')
        if self.orig_prompt is not None:
            args.append(f'--prompt="{self.orig_prompt}"')
        args.append(context.env_dir)
        args = ' '.join(args)
        f.write(f'command = {sys.executable} -m venv {args}\n')

def _setup_pip(self, context):
    """Installs or upgrades pip in a virtual environment"""
    self._call_new_python(context, '-m', 'ensurepip', '--upgrade', '--default-pip', stderr=subprocess.STDOUT)

def replace_variables(self, text, context):
    """Replace variable placeholders in script text with context-specific
    variables.

    Return the text passed in , but with variables replaced.

    :param text: The text in which to replace placeholder variables.
    :param context: The information for the environment creation request
                    being processed."""
    replacements = {'__VENV_DIR__': context.env_dir, '__VENV_NAME__': context.env_name, '__VENV_PROMPT__': context.prompt, '__VENV_BIN_NAME__': context.bin_name, '__VENV_PYTHON__': context.env_exe}
    def quote_ps1(s):
        """This should satisfy PowerShell quoting rules [1], unless the quoted
        string is passed directly to Windows native commands [2].
        [1]: https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.core/about/about_quoting_rules
        [2]: https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.core/about/about_parsing#passing-arguments-that-contain-quote-characters"""
        s = s.replace("'", "''")
        return f"'{s}'"
    def quote_bat(s):
        return s
    quote = shlex.quote
    script_path = context.script_path
    if script_path.endswith('.ps1'):
        quote = quote_ps1
    elif script_path.endswith('.bat'):
        quote = quote_bat
    else:
        quote = shlex.quote
    replacements = {key: quote(s) for key, s in replacements.items()}
    for key, quoted in replacements.items():
        text = text.replace(key, quoted)
    return text

def upgrade_dependencies(self, context):
    logger.debug(f'Upgrading {CORE_VENV_DEPS} packages in {context.bin_path}')
    self._call_new_python(context, '-m', 'pip', 'install', '--upgrade', *CORE_VENV_DEPS)

def create_if_needed(d):
    if not os.path.exists(d):
        os.makedirs(d)
    elif os.path.islink(d) or os.path.isfile(d):
        raise ValueError('Unable to create directory %r' % d)

def symlink_or_copy(self, src, dst, relative_symlinks_ok=False):
    """Try symlinking a file, and if that fails, fall back to copying."""
    force_copy = not self.symlinks
    if not force_copy:
        try:
            if not os.path.islink(dst):
                if relative_symlinks_ok:
                    assert os.path.dirname(src) == os.path.dirname(dst)
                    os.symlink(os.path.basename(src), dst)
                else:
                    os.symlink(src, dst)
        except Exception:
            logger.warning('Unable to symlink %r to %r', src, dst)
            force_copy = True
    if force_copy:
        shutil.copyfile(src, dst)

def symlink_or_copy(self, src, dst, relative_symlinks_ok=False):
    """Try symlinking a file, and if that fails, fall back to copying."""
    bad_src = os.path.lexists(src) and (not os.path.exists(src))
    if self.symlinks and (not bad_src) and (not os.path.islink(dst)):
        try:
            if relative_symlinks_ok:
                assert os.path.dirname(src) == os.path.dirname(dst)
                os.symlink(os.path.basename(src), dst)
            else:
                os.symlink(src, dst)
            return
        except Exception:
            logger.warning('Unable to symlink %r to %r', src, dst)
    basename, ext = os.path.splitext(os.path.basename(src))
    srcfn = os.path.join(os.path.dirname(__file__), 'scripts', 'nt', basename + ext)
    if sysconfig.is_python_build() or not os.path.isfile(srcfn):
        if basename.endswith('_d'):
            ext = '_d' + ext
            basename = basename[:-2]
        if basename == 'python':
            basename = 'venvlauncher'
        elif basename == 'pythonw':
            basename = 'venvwlauncher'
        src = os.path.join(os.path.dirname(src), basename + ext)
    else:
        src = srcfn
    if not os.path.exists(src):
        if not bad_src:
            logger.warning('Unable to copy %r', src)
        return
    shutil.copyfile(src, dst)

def formatwarning(message, category, filename, lineno, line=None):
    """Function to format a warning the standard way."""
    msg = WarningMessage(message, category, filename, lineno, None, line)
    return _formatwarnmsg_impl(msg)

def _showwarnmsg_impl(msg):
    file = msg.file
    if file is None:
        file = sys.stderr
        if file is None:
            return
    text = _formatwarnmsg(msg)
    try:
        file.write(text)
    except OSError:
        pass

def _showwarnmsg(msg):
    """Hook to write a warning to a file; replace if you like."""
    try:
        sw = showwarning
    except NameError:
        pass
    else:
        if sw is not _showwarning_orig:
            if not callable(sw):
                raise TypeError('warnings.showwarning() must be set to a function or method')
            sw(msg.message, msg.category, msg.filename, msg.lineno, msg.file, msg.line)
            return
    _showwarnmsg_impl(msg)

def _formatwarnmsg(msg):
    """Function to format a warning the standard way."""
    try:
        fw = formatwarning
    except NameError:
        pass
    else:
        if fw is not _formatwarning_orig:
            return fw(msg.message, msg.category, msg.filename, msg.lineno, msg.line)
    return _formatwarnmsg_impl(msg)

def _add_filter(*item, append):
    if not append:
        try:
            filters.remove(item)
        except ValueError:
            pass
        filters.insert(0, item)
    elif item not in filters:
        filters.append(item)
    _filters_mutated()

def _processoptions(args):
    for arg in args:
        try:
            _setoption(arg)
        except _OptionError as msg:
            print('Invalid -W option ignored:', msg, file=sys.stderr)

def _setoption(arg):
    parts = arg.split(':')
    if len(parts) > 5:
        raise _OptionError('too many fields (max 5): %r' % (arg,))
    while len(parts) < 5:
        parts.append('')
    action, message, category, module, lineno = [s.strip() for s in parts]
    action = _getaction(action)
    category = _getcategory(category)
    if message or module:
        import re
    if message:
        message = re.escape(message)
    if module:
        module = re.escape(module) + '\\Z'
    if lineno:
        try:
            lineno = int(lineno)
            if lineno < 0:
                raise ValueError
        except (ValueError, OverflowError):
            raise _OptionError('invalid lineno %r' % (lineno,)) from None
    else:
        lineno = 0
    filterwarnings(action, message, category, module, lineno)

def _getaction(action):
    if not action:
        return 'default'
    if action == 'all':
        return 'always'
    for a in ('default', 'always', 'ignore', 'module', 'once', 'error'):
        if a.startswith(action):
            return a
    raise _OptionError('invalid action: %r' % (action,))

def _getcategory(category):
    if not category:
        return Warning
    if '.' not in category:
        import builtins as m
        klass = category
    else:
        module, _, klass = category.rpartition('.')
        try:
            m = __import__(module, None, None, [klass])
        except ImportError:
            raise _OptionError('invalid module name: %r' % (module,)) from None
    try:
        cat = getattr(m, klass)
    except AttributeError:
        raise _OptionError('unknown warning category: %r' % (category,)) from None
    if not issubclass(cat, Warning):
        raise _OptionError('invalid warning category: %r' % (category,))
    return cat

def _is_internal_frame(frame):
    """Signal whether the frame is an internal CPython implementation detail."""
    return _is_internal_filename(frame.f_code.co_filename)

def _next_external_frame(frame, skip_file_prefixes):
    """Find the next frame that doesn't involve Python or user internals."""
    frame = frame.f_back
    while frame is not None and (_is_internal_filename((filename := frame.f_code.co_filename)) or _is_filename_to_skip(filename, skip_file_prefixes)):
        frame = frame.f_back
    return frame

def warn(message, category=None, stacklevel=1, source=None, *, skip_file_prefixes=()):
    """Issue a warning, or maybe ignore it or raise an exception."""
    if isinstance(message, Warning):
        category = message.__class__
    if category is None:
        category = UserWarning
    if not (isinstance(category, type) and issubclass(category, Warning)):
        raise TypeError("category must be a Warning subclass, not '{:s}'".format(type(category).__name__))
    if not isinstance(skip_file_prefixes, tuple):
        raise TypeError('skip_file_prefixes must be a tuple of strs.')
    if skip_file_prefixes:
        stacklevel = max(2, stacklevel)
    try:
        if stacklevel <= 1 or _is_internal_frame(sys._getframe(1)):
            frame = sys._getframe(stacklevel)
        else:
            frame = sys._getframe(1)
            for x in range(stacklevel - 1):
                frame = _next_external_frame(frame, skip_file_prefixes)
                if frame is None:
                    raise ValueError
    except ValueError:
        globals = sys.__dict__
        filename = 'sys'
        lineno = 1
    else:
        globals = frame.f_globals
        filename = frame.f_code.co_filename
        lineno = frame.f_lineno
    if '__name__' in globals:
        module = globals['__name__']
    else:
        module = '<string>'
    registry = globals.setdefault('__warningregistry__', {})
    warn_explicit(message, category, filename, lineno, module, registry, globals, source)

def _warn_unawaited_coroutine(coro):
    msg_lines = [f"coroutine '{coro.__qualname__}' was never awaited\n"]
    if coro.cr_origin is not None:
        import linecache, traceback
        def extract():
            for filename, lineno, funcname in reversed(coro.cr_origin):
                line = linecache.getline(filename, lineno)
                yield (filename, lineno, funcname, line)
        msg_lines.append('Coroutine created at (most recent call last)\n')
        msg_lines += traceback.format_list(list(extract()))
    msg = ''.join(msg_lines).rstrip('\n')
    warn(msg, category=RuntimeWarning, stacklevel=2, source=coro)

def __repr__(self):
    args = []
    if self._record:
        args.append('record=True')
    if self._module is not sys.modules['warnings']:
        args.append('module=%r' % self._module)
    name = type(self).__name__
    return '%s(%s)' % (name, ', '.join(args))

def extract():
    for filename, lineno, funcname in reversed(coro.cr_origin):
        line = linecache.getline(filename, lineno)
        yield (filename, lineno, funcname, line)

def _filters_mutated():
    global _filters_version
    _filters_version += 1

def _byteswap(data, width):
    swapped_data = bytearray(len(data))
    for i in range(0, len(data), width):
        for j in range(width):
            swapped_data[i + width - 1 - j] = data[i + j]
    return bytes(swapped_data)

def open(f, mode=None):
    if mode is None:
        if hasattr(f, 'mode'):
            mode = f.mode
        else:
            mode = 'rb'
    if mode in ('r', 'rb'):
        return Wave_read(f)
    elif mode in ('w', 'wb'):
        return Wave_write(f)
    else:
        raise Error("mode must be 'r', 'rb', 'w', or 'wb'")

def __init__(self, file, align=True, bigendian=True, inclheader=False):
    self.closed = False
    self.align = align
    if bigendian:
        strflag = '>'
    else:
        strflag = '<'
    self.file = file
    self.chunkname = file.read(4)
    if len(self.chunkname) < 4:
        raise EOFError
    try:
        self.chunksize = struct.unpack_from(strflag + 'L', file.read(4))[0]
    except struct.error:
        raise EOFError from None
    if inclheader:
        self.chunksize = self.chunksize - 8
    self.size_read = 0
    try:
        self.offset = self.file.tell()
    except (AttributeError, OSError):
        self.seekable = False
    else:
        self.seekable = True

def initfp(self, file):
    self._convert = None
    self._soundpos = 0
    self._file = _Chunk(file, bigendian=0)
    if self._file.getname() != b'RIFF':
        raise Error('file does not start with RIFF id')
    if self._file.read(4) != b'WAVE':
        raise Error('not a WAVE file')
    self._fmt_chunk_read = 0
    self._data_chunk = None
    while 1:
        self._data_seek_needed = 1
        try:
            chunk = _Chunk(self._file, bigendian=0)
        except EOFError:
            break
        chunkname = chunk.getname()
        if chunkname == b'fmt ':
            self._read_fmt_chunk(chunk)
            self._fmt_chunk_read = 1
        elif chunkname == b'data':
            if not self._fmt_chunk_read:
                raise Error('data chunk before fmt chunk')
            self._data_chunk = chunk
            self._nframes = chunk.chunksize // self._framesize
            self._data_seek_needed = 0
            break
        chunk.skip()
    if not self._fmt_chunk_read or not self._data_chunk:
        raise Error('fmt chunk and/or data chunk missing')

def __init__(self, f):
    self._i_opened_the_file = None
    if isinstance(f, str):
        f = builtins.open(f, 'rb')
        self._i_opened_the_file = f
    try:
        self.initfp(f)
    except:
        if self._i_opened_the_file:
            f.close()
        raise

def rewind(self):
    self._data_seek_needed = 1
    self._soundpos = 0

def close(self):
    self._file = None
    file = self._i_opened_the_file
    if file:
        self._i_opened_the_file = None
        file.close()

def setpos(self, pos):
    if pos < 0 or pos > self._nframes:
        raise Error('position not in range')
    self._soundpos = pos
    self._data_seek_needed = 1

def readframes(self, nframes):
    if self._data_seek_needed:
        self._data_chunk.seek(0, 0)
        pos = self._soundpos * self._framesize
        if pos:
            self._data_chunk.seek(pos, 0)
        self._data_seek_needed = 0
    if nframes == 0:
        return b''
    data = self._data_chunk.read(nframes * self._framesize)
    if self._sampwidth != 1 and sys.byteorder == 'big':
        data = _byteswap(data, self._sampwidth)
    if self._convert and data:
        data = self._convert(data)
    self._soundpos = self._soundpos + len(data) // (self._nchannels * self._sampwidth)
    return data

def _read_fmt_chunk(self, chunk):
    try:
        wFormatTag, self._nchannels, self._framerate, dwAvgBytesPerSec, wBlockAlign = struct.unpack_from('<HHLLH', chunk.read(14))
    except struct.error:
        raise EOFError from None
    if wFormatTag != WAVE_FORMAT_PCM and wFormatTag != WAVE_FORMAT_EXTENSIBLE:
        raise Error('unknown format: %r' % (wFormatTag,))
    try:
        sampwidth = struct.unpack_from('<H', chunk.read(2))[0]
    except struct.error:
        raise EOFError from None
    if wFormatTag == WAVE_FORMAT_EXTENSIBLE:
        try:
            cbSize, wValidBitsPerSample, dwChannelMask = struct.unpack_from('<HHL', chunk.read(8))
            SubFormat = chunk.read(16)
            if len(SubFormat) < 16:
                raise EOFError
        except struct.error:
            raise EOFError from None
        if SubFormat != KSDATAFORMAT_SUBTYPE_PCM:
            try:
                import uuid
                subformat_msg = f'unknown extended format: {uuid.UUID(bytes_le=SubFormat)}'
            except Exception:
                subformat_msg = 'unknown extended format'
            raise Error(subformat_msg)
    self._sampwidth = (sampwidth + 7) // 8
    if not self._sampwidth:
        raise Error('bad sample width')
    if not self._nchannels:
        raise Error('bad # of channels')
    self._framesize = self._nchannels * self._sampwidth
    self._comptype = 'NONE'
    self._compname = 'not compressed'

def __init__(self, f):
    self._i_opened_the_file = None
    if isinstance(f, str):
        f = builtins.open(f, 'wb')
        self._i_opened_the_file = f
    try:
        self.initfp(f)
    except:
        if self._i_opened_the_file:
            f.close()
        raise

def setnchannels(self, nchannels):
    if self._datawritten:
        raise Error('cannot change parameters after starting to write')
    if nchannels < 1:
        raise Error('bad # of channels')
    self._nchannels = nchannels

def setsampwidth(self, sampwidth):
    if self._datawritten:
        raise Error('cannot change parameters after starting to write')
    if sampwidth < 1 or sampwidth > 4:
        raise Error('bad sample width')
    self._sampwidth = sampwidth

def setframerate(self, framerate):
    if self._datawritten:
        raise Error('cannot change parameters after starting to write')
    if framerate <= 0:
        raise Error('bad frame rate')
    self._framerate = int(round(framerate))

def setnframes(self, nframes):
    if self._datawritten:
        raise Error('cannot change parameters after starting to write')
    self._nframes = nframes

def setcomptype(self, comptype, compname):
    if self._datawritten:
        raise Error('cannot change parameters after starting to write')
    if comptype not in ('NONE',):
        raise Error('unsupported compression type')
    self._comptype = comptype
    self._compname = compname

def getparams(self):
    if not self._nchannels or not self._sampwidth or (not self._framerate):
        raise Error('not all parameters set')
    return _wave_params(self._nchannels, self._sampwidth, self._framerate, self._nframes, self._comptype, self._compname)

def writeframesraw(self, data):
    if not isinstance(data, (bytes, bytearray)):
        data = memoryview(data).cast('B')
    self._ensure_header_written(len(data))
    nframes = len(data) // (self._sampwidth * self._nchannels)
    if self._convert:
        data = self._convert(data)
    if self._sampwidth != 1 and sys.byteorder == 'big':
        data = _byteswap(data, self._sampwidth)
    self._file.write(data)
    self._datawritten += len(data)
    self._nframeswritten = self._nframeswritten + nframes

def writeframes(self, data):
    self.writeframesraw(data)
    if self._datalength != self._datawritten:
        self._patchheader()

def close(self):
    try:
        if self._file:
            self._ensure_header_written(0)
            if self._datalength != self._datawritten:
                self._patchheader()
            self._file.flush()
    finally:
        self._file = None
        file = self._i_opened_the_file
        if file:
            self._i_opened_the_file = None
            file.close()

def _ensure_header_written(self, datasize):
    if not self._headerwritten:
        if not self._nchannels:
            raise Error('# channels not specified')
        if not self._sampwidth:
            raise Error('sample width not specified')
        if not self._framerate:
            raise Error('sampling rate not specified')
        self._write_header(datasize)

def _write_header(self, initlength):
    assert not self._headerwritten
    self._file.write(b'RIFF')
    if not self._nframes:
        self._nframes = initlength // (self._nchannels * self._sampwidth)
    self._datalength = self._nframes * self._nchannels * self._sampwidth
    try:
        self._form_length_pos = self._file.tell()
    except (AttributeError, OSError):
        self._form_length_pos = None
    self._file.write(struct.pack('<L4s4sLHHLLHH4s', 36 + self._datalength, b'WAVE', b'fmt ', 16, WAVE_FORMAT_PCM, self._nchannels, self._framerate, self._nchannels * self._framerate * self._sampwidth, self._nchannels * self._sampwidth, self._sampwidth * 8, b'data'))
    if self._form_length_pos is not None:
        self._data_length_pos = self._file.tell()
    self._file.write(struct.pack('<L', self._datalength))
    self._headerwritten = True

def __new__(cls, meth, callback=None):
    try:
        obj = meth.__self__
        func = meth.__func__
    except AttributeError:
        raise TypeError('argument should be a bound method, not {}'.format(type(meth))) from None
    def _cb(arg):
        self = self_wr()
        if self._alive:
            self._alive = False
            if callback is not None:
                callback(self)
    self = ref.__new__(cls, obj, _cb)
    self._func_ref = ref(func, _cb)
    self._meth_type = type(meth)
    self._alive = True
    self_wr = ref(self)
    return self

def __call__(self):
    obj = super().__call__()
    func = self._func_ref()
    if obj is None or func is None:
        return None
    return self._meth_type(func, obj)

def __eq__(self, other):
    if isinstance(other, WeakMethod):
        if not self._alive or not other._alive:
            return self is other
        return ref.__eq__(self, other) and self._func_ref == other._func_ref
    return NotImplemented

def __ne__(self, other):
    if isinstance(other, WeakMethod):
        if not self._alive or not other._alive:
            return self is not other
        return ref.__ne__(self, other) or self._func_ref != other._func_ref
    return NotImplemented

def __init__(self, other=(), /, **kw):
    def remove(wr, selfref=ref(self), _atomic_removal=_remove_dead_weakref):
        self = selfref()
        if self is not None:
            if self._iterating:
                self._pending_removals.append(wr.key)
            else:
