def format_date_time(timestamp):
    year, month, day, hh, mm, ss, wd, y, z = time.gmtime(timestamp)
    return '%s, %02d %3s %4d %02d:%02d:%02d GMT' % (_weekdayname[wd], day, _monthname[month], year, hh, mm, ss)

def read_environ():
    """Read environment, fixing HTTP variables"""
    enc = sys.getfilesystemencoding()
    esc = 'surrogateescape'
    try:
        ''.encode('utf-8', esc)
    except LookupError:
        esc = 'replace'
    environ = {}
    for k, v in os.environ.items():
        if _needs_transcode(k):
            if sys.platform == 'win32':
                software = os.environ.get('SERVER_SOFTWARE', '').lower()
                if software.startswith('microsoft-iis/'):
                    v = v.encode('utf-8').decode('iso-8859-1')
                elif software.startswith('apache/'):
                    pass
                elif software.startswith('simplehttp/') and 'python/3' in software:
                    v = v.encode('utf-8').decode('iso-8859-1')
                else:
                    v = v.encode(enc, 'replace').decode('iso-8859-1')
            else:
                v = v.encode(enc, esc).decode('iso-8859-1')
        environ[k] = v
    return environ

def run(self, application):
    """Invoke the application"""
    try:
        self.setup_environ()
        self.result = application(self.environ, self.start_response)
        self.finish_response()
    except (ConnectionAbortedError, BrokenPipeError, ConnectionResetError):
        return
    except:
        try:
            self.handle_error()
        except:
            self.close()
            raise

def finish_response(self):
    """Send any iterable data, then close self and the iterable

    Subclasses intended for use in asynchronous servers will
    want to redefine this method, such that it sets up callbacks
    in the event loop to iterate over the data, and to call
    'self.close()' once the response is finished."""
    try:
        if not self.result_is_file() or not self.sendfile():
            for data in self.result:
                self.write(data)
            self.finish_content()
    except:
        if hasattr(self.result, 'close'):
            self.result.close()
        raise
    else:
        self.close()

def get_scheme(self):
    """Return the URL scheme being used"""
    return guess_scheme(self.environ)

def set_content_length(self):
    """Compute Content-Length or switch to chunked encoding if possible"""
    try:
        blocks = len(self.result)
    except (TypeError, AttributeError, NotImplementedError):
        pass
    else:
        if blocks == 1:
            self.headers['Content-Length'] = str(self.bytes_sent)
            return

def cleanup_headers(self):
    """Make any necessary header changes or defaults

    Subclasses can extend this to add other defaults."""
    if 'Content-Length' not in self.headers:
        self.set_content_length()

def start_response(self, status, headers, exc_info=None):
    """'start_response()' callable as specified by PEP 3333"""
    if exc_info:
        try:
            if self.headers_sent:
                raise
        finally:
            exc_info = None
    elif self.headers is not None:
        raise AssertionError('Headers already set!')
    self.status = status
    self.headers = self.headers_class(headers)
    status = self._convert_string_type(status, 'Status')
    self._validate_status(status)
    if __debug__:
        for name, val in headers:
            name = self._convert_string_type(name, 'Header name')
            val = self._convert_string_type(val, 'Header value')
            assert not is_hop_by_hop(name), f"Hop-by-hop header, '{name}: {val}', not allowed"
    return self.write

def _validate_status(self, status):
    if len(status) < 4:
        raise AssertionError('Status must be at least 4 characters')
    if not status[:3].isdigit():
        raise AssertionError('Status message must begin w/3-digit code')
    if status[3] != ' ':
        raise AssertionError('Status message must have a space after code')

def _convert_string_type(self, value, title):
    """Convert/check value type."""
    if type(value) is str:
        return value
    raise AssertionError('{0} must be of type str (got {1})'.format(title, repr(value)))

def send_preamble(self):
    """Transmit version/status/date/server, via self._write()"""
    if self.origin_server:
        if self.client_is_modern():
            self._write(('HTTP/%s %s\r\n' % (self.http_version, self.status)).encode('iso-8859-1'))
            if 'Date' not in self.headers:
                self._write(('Date: %s\r\n' % format_date_time(time.time())).encode('iso-8859-1'))
            if self.server_software and 'Server' not in self.headers:
                self._write(('Server: %s\r\n' % self.server_software).encode('iso-8859-1'))
    else:
        self._write(('Status: %s\r\n' % self.status).encode('iso-8859-1'))

def write(self, data):
    """'write()' callable as specified by PEP 3333"""
    assert type(data) is bytes, 'write() argument must be a bytes instance'
    if not self.status:
        raise AssertionError('write() before start_response()')
    elif not self.headers_sent:
        self.bytes_sent = len(data)
        self.send_headers()
    else:
        self.bytes_sent += len(data)
    self._write(data)
    self._flush()

def finish_content(self):
    """Ensure headers and content have both been sent"""
    if not self.headers_sent:
        self.headers.setdefault('Content-Length', '0')
        self.send_headers()
    else:
        pass

def close(self):
    """Close the iterable (if needed) and reset all instance vars

    Subclasses may want to also drop the client connection."""
    try:
        if hasattr(self.result, 'close'):
            self.result.close()
    finally:
        self.result = self.headers = self.status = self.environ = None
        self.bytes_sent = 0
        self.headers_sent = False

def result_is_file(self):
    """True if 'self.result' is an instance of 'self.wsgi_file_wrapper'"""
    wrapper = self.wsgi_file_wrapper
    return wrapper is not None and isinstance(self.result, wrapper)

def client_is_modern(self):
    """True if client can accept status and headers"""
    return self.environ['SERVER_PROTOCOL'].upper() != 'HTTP/0.9'

def handle_error(self):
    """Log current error, and send error output to client if possible"""
    self.log_exception(sys.exc_info())
    if not self.headers_sent:
        self.result = self.error_output(self.environ, self.start_response)
        self.finish_response()

def get_stdin(self):
    """Override in subclass to return suitable 'wsgi.input'"""
    raise NotImplementedError

def get_stderr(self):
    """Override in subclass to return suitable 'wsgi.errors'"""
    raise NotImplementedError

def add_cgi_vars(self):
    """Override in subclass to insert CGI variables in 'self.environ'"""
    raise NotImplementedError

def _write(self, data):
    result = self.stdout.write(data)
    if result is None or result == len(data):
        return
    from warnings import warn
    warn('SimpleHandler.stdout.write() should not do partial writes', DeprecationWarning)
    while (data := data[result:]):
        result = self.stdout.write(data)

def _flush(self):
    self.stdout.flush()
    self._flush = self.stdout.flush

def _formatparam(param, value=None, quote=1):
    """Convenience function to format and return a key=value pair.

    This will quote the value if needed or if quote is true."""
    if value is not None and len(value) > 0:
        if quote or tspecials.search(value):
            value = value.replace('\\', '\\\\').replace('"', '\\"')
            return '%s="%s"' % (param, value)
        else:
            return '%s=%s' % (param, value)
    else:
        return param

def __init__(self, headers=None):
    headers = headers if headers is not None else []
    if type(headers) is not list:
        raise TypeError('Headers must be a list of name/value tuples')
    self._headers = headers
    if __debug__:
        for k, v in headers:
            self._convert_string_type(k, name=True)
            self._convert_string_type(v, name=False)

def _convert_string_type(self, value, *, name):
    """Convert/check value type."""
    if type(value) is str:
        regex = _name_disallowed_re if name else _value_disallowed_re
        if regex.search(value):
            raise ValueError('Control characters not allowed in headers')
        return value
    raise AssertionError('Header names/values must be of type str (got {0})'.format(repr(value)))

def __contains__(self, name):
    """Return true if the message contains the header."""
    return self.get(name) is not None

def get(self, name, default=None):
    """Get the first header value for 'name', or return 'default'"""
    name = self._convert_string_type(name.lower(), name=True)
    for k, v in self._headers:
        if k.lower() == name:
            return v
    return default

def __str__(self):
    """str() returns the formatted headers, complete with end line,
    suitable for direct HTTP transmission."""
    return '\r\n'.join(['%s: %s' % kv for kv in self._headers] + ['', ''])

def setdefault(self, name, value):
    """Return first matching header value for 'name', or 'value'

    If there is no header named 'name', add a new header with name 'name'
    and value 'value'."""
    result = self.get(name)
    if result is None:
        self._headers.append((self._convert_string_type(name, name=True), self._convert_string_type(value, name=False)))
        return value
    else:
        return result

def close(self):
    try:
        self.request_handler.log_request(self.status.split(' ', 1)[0], self.bytes_sent)
    finally:
        SimpleHandler.close(self)

def get_environ(self):
    env = self.server.base_environ.copy()
    env['SERVER_PROTOCOL'] = self.request_version
    env['SERVER_SOFTWARE'] = self.server_version
    env['REQUEST_METHOD'] = self.command
    if '?' in self.path:
        path, query = self.path.split('?', 1)
    else:
        path, query = (self.path, '')
    env['PATH_INFO'] = urllib.parse.unquote(path, 'iso-8859-1')
    env['QUERY_STRING'] = query
    host = self.address_string()
    if host != self.client_address[0]:
        env['REMOTE_HOST'] = host
    env['REMOTE_ADDR'] = self.client_address[0]
    if self.headers.get('content-type') is None:
        env['CONTENT_TYPE'] = self.headers.get_content_type()
    else:
        env['CONTENT_TYPE'] = self.headers['content-type']
    length = self.headers.get('content-length')
    if length:
        env['CONTENT_LENGTH'] = length
    for k, v in self.headers.items():
        k = k.replace('-', '_').upper()
        v = v.strip()
        if k in env:
            continue
        if 'HTTP_' + k in env:
            env['HTTP_' + k] += ',' + v
        else:
            env['HTTP_' + k] = v
    return env

def guess_scheme(environ):
    """Return a guess for whether 'wsgi.url_scheme' should be 'http' or 'https'
    """
    if environ.get('HTTPS') in ('yes', 'on', '1'):
        return 'https'
    else:
        return 'http'

def application_uri(environ):
    """Return the application's base URI (no PATH_INFO or QUERY_STRING)"""
    url = environ['wsgi.url_scheme'] + '://'
    from urllib.parse import quote
    if environ.get('HTTP_HOST'):
        url += environ['HTTP_HOST']
    else:
        url += environ['SERVER_NAME']
        if environ['wsgi.url_scheme'] == 'https':
            if environ['SERVER_PORT'] != '443':
                url += ':' + environ['SERVER_PORT']
        elif environ['SERVER_PORT'] != '80':
            url += ':' + environ['SERVER_PORT']
    url += quote(environ.get('SCRIPT_NAME') or '/', encoding='latin1')
    return url

def request_uri(environ, include_query=True):
    """Return the full request URI, optionally including the query string"""
    url = application_uri(environ)
    from urllib.parse import quote
    path_info = quote(environ.get('PATH_INFO', ''), safe='/;=,', encoding='latin1')
    if not environ.get('SCRIPT_NAME'):
        url += path_info[1:]
    else:
        url += path_info
    if include_query and environ.get('QUERY_STRING'):
        url += '?' + environ['QUERY_STRING']
    return url

def is_hop_by_hop(header_name):
    """Return true if 'header_name' is an HTTP/1.1 "Hop-by-Hop" header"""
    return _hoppish(header_name.lower())

def __init__(self, filelike, blksize=8192):
    self.filelike = filelike
    self.blksize = blksize
    if hasattr(filelike, 'close'):
        self.close = filelike.close

def __next__(self):
    data = self.filelike.read(self.blksize)
    if data:
        return data
    raise StopIteration

def assert_(cond, *args):
    if not cond:
        raise AssertionError(*args)

def check_string_type(value, title):
    if type(value) is str:
        return value
    raise AssertionError('{0} must be of type str (got {1})'.format(title, repr(value)))

def check_input(wsgi_input):
    for attr in ['read', 'readline', 'readlines', '__iter__']:
        assert_(hasattr(wsgi_input, attr), "wsgi.input (%r) doesn't have the attribute %s" % (wsgi_input, attr))

def check_errors(wsgi_errors):
    for attr in ['flush', 'write', 'writelines']:
        assert_(hasattr(wsgi_errors, attr), "wsgi.errors (%r) doesn't have the attribute %s" % (wsgi_errors, attr))

def check_content_type(status, headers):
    status = check_string_type(status, 'Status')
    code = int(status.split(None, 1)[0])
    NO_MESSAGE_BODY = (204, 304)
    for name, value in headers:
        name = check_string_type(name, 'Header name')
        if name.lower() == 'content-type':
            if code not in NO_MESSAGE_BODY:
                return
            assert_(0, 'Content-Type header found in a %s response, which must not return content.' % code)
    if code not in NO_MESSAGE_BODY:
        assert_(0, 'No Content-Type header found in headers (%s)' % headers)

def __iter__(self):
    while (line := self.readline()):
        yield line

def write(self, s):
    assert_(type(s) is str)
    self.errors.write(s)

def writelines(self, seq):
    for line in seq:
        self.write(line)

def __call__(self, s):
    assert_(type(s) is bytes)
    self.writer(s)

def __next__(self):
    assert_(not self.closed, 'Iterator read after closed')
    v = next(self.iterator)
    if type(v) is not bytes:
        assert_(False, 'Iterator yielded non-bytestring (%r)' % (v,))
    if self.check_start_response is not None:
        assert_(self.check_start_response, 'The application returns and we started iterating over its body, but start_response has not yet been called')
        self.check_start_response = None
    return v

def close(self):
    self.closed = True
    if hasattr(self.original_iterator, 'close'):
        self.original_iterator.close()

def __del__(self):
    if not self.closed:
        sys.stderr.write('Iterator garbage collected without being closed')
    assert_(self.closed, 'Iterator garbage collected without being closed')

def raise_conversion_error(function):
    """Wrap any raised struct.errors in a ConversionError."""
    @wraps(function)
    def result(self, value):
        try:
            return function(self, value)
        except struct.error as e:
            raise ConversionError(e.args[0]) from None
    return result

@wraps(function)
def result(self, value):
    try:
        return function(self, value)
    except struct.error as e:
        raise ConversionError(e.args[0]) from None

@raise_conversion_error
def pack_uint(self, x):
    self.__buf.write(struct.pack('>L', x))

@raise_conversion_error
def pack_int(self, x):
    self.__buf.write(struct.pack('>l', x))

def pack_bool(self, x):
    if x:
        self.__buf.write(b'\x00\x00\x00\x01')
    else:
        self.__buf.write(b'\x00\x00\x00\x00')

def pack_uhyper(self, x):
    try:
        self.pack_uint(x >> 32 & 4294967295)
    except (TypeError, struct.error) as e:
        raise ConversionError(e.args[0]) from None
    try:
        self.pack_uint(x & 4294967295)
    except (TypeError, struct.error) as e:
        raise ConversionError(e.args[0]) from None

@raise_conversion_error
def pack_float(self, x):
    self.__buf.write(struct.pack('>f', x))

@raise_conversion_error
def pack_double(self, x):
    self.__buf.write(struct.pack('>d', x))

def pack_list(self, list, pack_item):
    for item in list:
        self.pack_uint(1)
        pack_item(item)
    self.pack_uint(0)

def pack_farray(self, n, list, pack_item):
    if len(list) != n:
        raise ValueError('wrong array size')
    for item in list:
        pack_item(item)

def reset(self, data):
    self.__buf = data
    self.__pos = 0

def done(self):
    if self.__pos < len(self.__buf):
        raise Error('unextracted data remains')

def unpack_fstring(self, n):
    if n < 0:
        raise ValueError('fstring size must be nonnegative')
    i = self.__pos
    j = i + (n + 3) // 4 * 4
    if j > len(self.__buf):
        raise EOFError
    self.__pos = j
    return self.__buf[i:i + n]

def unpack_string(self):
    n = self.unpack_uint()
    return self.unpack_fstring(n)

def unpack_list(self, unpack_item):
    list = []
    while (x := self.unpack_uint()) != 0:
        if x != 1:
            raise ConversionError('0 or 1 expected, got %r' % (x,))
        item = unpack_item()
        list.append(item)
    return list

def unpack_farray(self, n, unpack_item):
    list = []
    for i in range(n):
        list.append(unpack_item())
    return list

def unpack_array(self, unpack_item):
    n = self.unpack_uint()
    return self.unpack_farray(n, unpack_item)

def __init__(self, *args, **kw):
    if self.__class__ is DOMException:
        raise RuntimeError('DOMException should not be instantiated directly')
    Exception.__init__(self, *args, **kw)

def _good_enough(dom, features):
    """_good_enough(dom, features) -> Return 1 if the dom offers the features"""
    for f, v in features:
        if not dom.hasFeature(f, v):
            return 0
    return 1

def getDOMImplementation(name=None, features=()):
    """getDOMImplementation(name = None, features = ()) -> DOM implementation.

    Return a suitable DOM implementation. The name is either
    well-known, the module name of a DOM implementation, or None. If
    it is not None, imports the corresponding module and returns
    DOMImplementation object if the import succeeds.

    If name is not given, consider the available implementations to
    find one with the required feature set. If no implementation can
    be found, raise an ImportError. The features list must be a sequence
    of (feature, version) pairs which are passed to hasFeature."""
    import os
    creator = None
    mod = well_known_implementations.get(name)
    if mod:
        mod = __import__(mod, {}, {}, ['getDOMImplementation'])
        return mod.getDOMImplementation()
    elif name:
        return registered[name]()
    elif not sys.flags.ignore_environment and 'PYTHON_DOM' in os.environ:
        return getDOMImplementation(name=os.environ['PYTHON_DOM'])
    if isinstance(features, str):
        features = _parse_feature_string(features)
    for creator in registered.values():
        dom = creator()
        if _good_enough(dom, features):
            return dom
    for creator in well_known_implementations.keys():
        try:
            dom = getDOMImplementation(name=creator)
        except Exception:
            continue
        if _good_enough(dom, features):
            return dom
    raise ImportError('no suitable DOM implementation found')

def _parse_feature_string(s):
    features = []
    parts = s.split()
    i = 0
    length = len(parts)
    while i < length:
        feature = parts[i]
        if feature[0] in '0123456789':
            raise ValueError('bad feature name: %r' % (feature,))
        i = i + 1
        version = None
        if i < length:
            v = parts[i]
            if v[0] in '0123456789':
                i = i + 1
                version = v
        features.append((feature, version))
    return tuple(features)

def parse(file, namespaces=True):
    """Parse a document, returning the resulting Document node.

    'file' may be either a file name or an open file object."""
    if namespaces:
        builder = ExpatBuilderNS()
    else:
        builder = ExpatBuilder()
    if isinstance(file, str):
        with open(file, 'rb') as fp:
            result = builder.parseFile(fp)
    else:
        result = builder.parseFile(file)
    return result

def parseString(string, namespaces=True):
    """Parse a document from a string, returning the resulting
    Document node."""
    if namespaces:
        builder = ExpatBuilderNS()
    else:
        builder = ExpatBuilder()
    return builder.parseString(string)

def parseFragment(file, context, namespaces=True):
    """Parse a fragment of a document, given the context from which it
    was originally extracted.  context should be the parent of the
    node(s) which are in the fragment.

    'file' may be either a file name or an open file object."""
    if namespaces:
        builder = FragmentBuilderNS(context)
    else:
        builder = FragmentBuilder(context)
    if isinstance(file, str):
        with open(file, 'rb') as fp:
            result = builder.parseFile(fp)
    else:
        result = builder.parseFile(file)
    return result

def parseFragmentString(string, context, namespaces=True):
    """Parse a fragment of a document from a string, given the context
    from which it was originally extracted.  context should be the
    parent of the node(s) which are in the fragment."""
    if namespaces:
        builder = FragmentBuilderNS(context)
    else:
        builder = FragmentBuilder(context)
    return builder.parseString(string)

def makeBuilder(options):
    """Create a builder based on an Options object."""
    if options.namespaces:
        return ExpatBuilderNS(options)
    else:
        return ExpatBuilder(options)

def getAttributeType(self, aname):
    for info in self._attr_info:
        if info[1] == aname:
            t = info[-2]
            if t[0] == '(':
                return _typeinfo_map['ENUM']
            else:
                return _typeinfo_map[info[-2]]
    return minidom._no_type

def isElementContent(self):
    if self._model:
        type = self._model[0]
        return type not in (expat.model.XML_CTYPE_ANY, expat.model.XML_CTYPE_MIXED)
    else:
        return False

def isEmpty(self):
    if self._model:
        return self._model[0] == expat.model.XML_CTYPE_EMPTY
    else:
        return False

def isId(self, aname):
    for info in self._attr_info:
        if info[1] == aname:
            return info[-2] == 'ID'
    return False

def __init__(self, options=None):
    if options is None:
        options = xmlbuilder.Options()
    self._options = options
    if self._options.filter is not None:
        self._filter = FilterVisibilityController(self._options.filter)
    else:
        self._filter = None
        self._finish_start_element = id
    self._parser = None
    self.reset()

def createParser(self):
    """Create a new parser object."""
    return expat.ParserCreate()

def end_doctype_decl_handler(self):
    if self._options.comments:
        self._parser.CommentHandler = self.comment_handler
    self._parser.ProcessingInstructionHandler = self.pi_handler
    if not (self._elem_info or self._filter):
        self._finish_end_element = id

def pi_handler(self, target, data):
    node = self.document.createProcessingInstruction(target, data)
    _append_child(self.curNode, node)
    if self._filter and self._filter.acceptNode(node) == FILTER_REJECT:
        self.curNode.removeChild(node)

def entity_decl_handler(self, entityName, is_parameter_entity, value, base, systemId, publicId, notationName):
    if is_parameter_entity:
        return
    if not self._options.entities:
        return
    node = self.document._create_entity(entityName, publicId, systemId, notationName)
    if value is not None:
        child = self.document.createTextNode(value)
        node.childNodes.append(child)
    self.document.doctype.entities._seq.append(node)
    if self._filter and self._filter.acceptNode(node) == FILTER_REJECT:
        del self.document.doctype.entities._seq[-1]

def notation_decl_handler(self, notationName, base, systemId, publicId):
    node = self.document._create_notation(notationName, publicId, systemId)
    self.document.doctype.notations._seq.append(node)
    if self._filter and self._filter.acceptNode(node) == FILTER_ACCEPT:
        del self.document.doctype.notations._seq[-1]

def comment_handler(self, data):
    node = self.document.createComment(data)
    _append_child(self.curNode, node)
    if self._filter and self._filter.acceptNode(node) == FILTER_REJECT:
        self.curNode.removeChild(node)

def start_cdata_section_handler(self):
    self._cdata = True
    self._cdata_continue = False

def end_cdata_section_handler(self):
    self._cdata = False
    self._cdata_continue = False

def first_element_handler(self, name, attributes):
    if self._filter is None and (not self._elem_info):
        self._finish_end_element = id
    self.getParser().StartElementHandler = self.start_element_handler
    self.start_element_handler(name, attributes)

def start_element_handler(self, name, attributes):
    node = self.document.createElement(name)
    _append_child(self.curNode, node)
    self.curNode = node
    if attributes:
        for i in range(0, len(attributes), 2):
            a = minidom.Attr(attributes[i], EMPTY_NAMESPACE, None, EMPTY_PREFIX)
            value = attributes[i + 1]
            a.value = value
            a.ownerDocument = self.document
            _set_attribute_node(node, a)
    if node is not self.document.documentElement:
        self._finish_start_element(node)

def _finish_start_element(self, node):
    if self._filter:
        if node is self.document.documentElement:
            return
        filt = self._filter.startContainer(node)
        if filt == FILTER_REJECT:
            Rejecter(self)
        elif filt == FILTER_SKIP:
            Skipper(self)
        else:
            return
        self.curNode = node.parentNode
        node.parentNode.removeChild(node)
        node.unlink()

def _finish_end_element(self, curNode):
    info = self._elem_info.get(curNode.tagName)
    if info:
        self._handle_white_text_nodes(curNode, info)
    if self._filter:
        if curNode is self.document.documentElement:
            return
        if self._filter.acceptNode(curNode) == FILTER_REJECT:
            self.curNode.removeChild(curNode)
            curNode.unlink()

def _handle_white_text_nodes(self, node, info):
    if self._options.whitespace_in_element_content or not info.isElementContent():
        return
    L = []
    for child in node.childNodes:
        if child.nodeType == TEXT_NODE and (not child.data.strip()):
            L.append(child)
    for child in L:
        node.removeChild(child)

def element_decl_handler(self, name, model):
    info = self._elem_info.get(name)
    if info is None:
        self._elem_info[name] = ElementInfo(name, model)
    else:
        assert info._model is None
        info._model = model

def attlist_decl_handler(self, elem, name, type, default, required):
    info = self._elem_info.get(elem)
    if info is None:
        info = ElementInfo(elem)
        self._elem_info[elem] = info
    info._attr_info.append([None, name, None, None, default, 0, type, required])

def xml_decl_handler(self, version, encoding, standalone):
    self.document.version = version
    self.document.encoding = encoding
    if standalone >= 0:
        if standalone:
            self.document.standalone = True
        else:
            self.document.standalone = False

def startContainer(self, node):
    mask = self._nodetype_mask[node.nodeType]
    if self.filter.whatToShow & mask:
        val = self.filter.startContainer(node)
        if val == FILTER_INTERRUPT:
            raise ParseEscape
        if val not in _ALLOWED_FILTER_RETURNS:
            raise ValueError('startContainer() returned illegal value: ' + repr(val))
        return val
    else:
        return FILTER_ACCEPT

def acceptNode(self, node):
    mask = self._nodetype_mask[node.nodeType]
    if self.filter.whatToShow & mask:
        val = self.filter.acceptNode(node)
        if val == FILTER_INTERRUPT:
            raise ParseEscape
        if val == FILTER_SKIP:
            parent = node.parentNode
            for child in node.childNodes[:]:
                parent.appendChild(child)
            return FILTER_REJECT
        if val not in _ALLOWED_FILTER_RETURNS:
            raise ValueError('acceptNode() returned illegal value: ' + repr(val))
        return val
    else:
        return FILTER_ACCEPT

def __init__(self, builder):
    FilterCrutch.__init__(self, builder)
    parser = builder._parser
    for name in ('ProcessingInstructionHandler', 'CommentHandler', 'CharacterDataHandler', 'StartCdataSectionHandler', 'EndCdataSectionHandler', 'ExternalEntityRefHandler'):
        setattr(parser, name, None)

def end_element_handler(self, *args):
    if self._level == 0:
        parser = self._builder._parser
        self._builder.install(parser)
        parser.StartElementHandler = self._old_start
        parser.EndElementHandler = self._old_end
    else:
        self._level = self._level - 1

def start_element_handler(self, *args):
    node = self._builder.curNode
    self._old_start(*args)
    if self._builder.curNode is not node:
        self._level = self._level + 1

def reset(self):
    ExpatBuilder.reset(self)
    self.fragment = None

def parseFile(self, file):
    """Parse a document fragment from a file object, returning the
    fragment node."""
    return self.parseString(file.read())

def _getDeclarations(self):
    """Re-create the internal subset from the DocumentType node.

    This is only needed if we don't already have the
    internalSubset as a string."""
    doctype = self.context.ownerDocument.doctype
    s = ''
    if doctype:
        for i in range(doctype.notations.length):
            notation = doctype.notations.item(i)
            if s:
                s = s + '\n  '
            s = '%s<!NOTATION %s' % (s, notation.nodeName)
            if notation.publicId:
                s = '%s PUBLIC "%s"\n             "%s">' % (s, notation.publicId, notation.systemId)
            else:
                s = '%s SYSTEM "%s">' % (s, notation.systemId)
        for i in range(doctype.entities.length):
            entity = doctype.entities.item(i)
            if s:
                s = s + '\n  '
            s = '%s<!ENTITY %s' % (s, entity.nodeName)
            if entity.publicId:
                s = '%s PUBLIC "%s"\n             "%s"' % (s, entity.publicId, entity.systemId)
            elif entity.systemId:
                s = '%s SYSTEM "%s"' % (s, entity.systemId)
            else:
                s = '%s "%s"' % (s, entity.firstChild.data)
            if entity.notationName:
                s = '%s NOTATION %s' % (s, entity.notationName)
            s = s + '>'
    return s

def install(self, parser):
    """Insert the namespace-handlers onto the parser."""
    ExpatBuilder.install(self, parser)
    if self._options.namespace_declarations:
        parser.StartNamespaceDeclHandler = self.start_namespace_decl_handler

def start_namespace_decl_handler(self, prefix, uri):
    """Push this namespace declaration on our storage."""
    self._ns_ordered_prefixes.append((prefix, uri))

def reset(self):
    ExpatBuilder.reset(self)
    self._initNamespaces()

def reset(self):
    FragmentBuilder.reset(self)
    self._initNamespaces()

def _getNSattrs(self):
    """Return string of namespace attributes from this element and
    ancestors."""
    attrs = ''
    context = self.context
    L = []
    while context:
        if hasattr(context, '_ns_prefix_uri'):
            for prefix, uri in context._ns_prefix_uri.items():
                if prefix in L:
                    continue
                L.append(prefix)
                if prefix:
                    declname = 'xmlns:' + prefix
                else:
                    declname = 'xmlns'
                if attrs:
                    attrs = "%s\n    %s='%s'" % (attrs, declname, uri)
                else:
                    attrs = " %s='%s'" % (declname, uri)
        context = context.parentNode
    return attrs

def getSubset(self):
    """Return the internal subset as a string."""
    return self.subset

def parseFile(self, file):
