def end_element_handler(self, name):
    curNode = self.curNode
    if ' ' in name:
        uri, localname, prefix, qname = _parse_ns_name(self, name)
        assert curNode.namespaceURI == uri and curNode.localName == localname and (curNode.prefix == prefix), 'element stack messed up! (namespace)'
    else:
        assert curNode.nodeName == name, 'element stack messed up - bad nodeName'
        assert curNode.namespaceURI == EMPTY_NAMESPACE, 'element stack messed up - bad namespaceURI'
    self.curNode = curNode.parentNode
    self._finish_end_element(curNode)

def __setstate__(self, state):
    if state is None:
        state = []
    self[:] = state

def _write_data(writer, data):
    """Writes datachars to writer."""
    if data:
        data = data.replace('&', '&amp;').replace('<', '&lt;').replace('"', '&quot;').replace('>', '&gt;')
        writer.write(data)

def _get_elements_by_tagName_helper(parent, name, rc):
    for node in parent.childNodes:
        if node.nodeType == Node.ELEMENT_NODE and (name == '*' or node.tagName == name):
            rc.append(node)
        _get_elements_by_tagName_helper(node, name, rc)
    return rc

def _get_containing_element(node):
    c = node.parentNode
    while c is not None:
        if c.nodeType == Node.ELEMENT_NODE:
            return c
        c = c.parentNode
    return None

def _get_containing_entref(node):
    c = node.parentNode
    while c is not None:
        if c.nodeType == Node.ENTITY_REFERENCE_NODE:
            return c
        c = c.parentNode
    return None

def _clear_id_cache(node):
    if node.nodeType == Node.DOCUMENT_NODE:
        node._id_cache.clear()
        node._id_search_stack = None
    elif node.ownerDocument:
        node.ownerDocument._id_cache.clear()
        node.ownerDocument._id_search_stack = None

def _nssplit(qualifiedName):
    fields = qualifiedName.split(':', 1)
    if len(fields) == 2:
        return fields
    else:
        return (None, fields[0])

def parseString(string, parser=None):
    """Parse a file into a DOM from a string."""
    if parser is None:
        from xml.dom import expatbuilder
        return expatbuilder.parseString(string)
    else:
        from xml.dom import pulldom
        return _do_pulldom_parse(pulldom.parseString, (string,), {'parser': parser})

def getDOMImplementation(features=None):
    if features:
        if isinstance(features, str):
            features = domreg._parse_feature_string(features)
        for f, v in features:
            if not Document.implementation.hasFeature(f, v):
                return None
    return Document.implementation

def toprettyxml(self, indent='\t', newl='\n', encoding=None, standalone=None):
    if encoding is None:
        writer = io.StringIO()
    else:
        writer = io.TextIOWrapper(io.BytesIO(), encoding=encoding, errors='xmlcharrefreplace', newline='\n')
    if self.nodeType == Node.DOCUMENT_NODE:
        self.writexml(writer, '', indent, newl, encoding, standalone)
    else:
        self.writexml(writer, '', indent, newl)
    if encoding is None:
        return writer.getvalue()
    else:
        return writer.detach().getvalue()

def _get_firstChild(self):
    if self.childNodes:
        return self.childNodes[0]

def _get_lastChild(self):
    if self.childNodes:
        return self.childNodes[-1]

def insertBefore(self, newChild, refChild):
    if newChild.nodeType == self.DOCUMENT_FRAGMENT_NODE:
        for c in tuple(newChild.childNodes):
            self.insertBefore(c, refChild)
        return newChild
    if newChild.nodeType not in self._child_node_types:
        raise xml.dom.HierarchyRequestErr('%s cannot be child of %s' % (repr(newChild), repr(self)))
    if newChild.parentNode is not None:
        newChild.parentNode.removeChild(newChild)
    if refChild is None:
        self.appendChild(newChild)
    else:
        try:
            index = self.childNodes.index(refChild)
        except ValueError:
            raise xml.dom.NotFoundErr()
        if newChild.nodeType in _nodeTypes_with_children:
            _clear_id_cache(self)
        self.childNodes.insert(index, newChild)
        newChild.nextSibling = refChild
        refChild.previousSibling = newChild
        if index:
            node = self.childNodes[index - 1]
            node.nextSibling = newChild
            newChild.previousSibling = node
        else:
            newChild.previousSibling = None
        newChild.parentNode = self
    return newChild

def appendChild(self, node):
    if node.nodeType == self.DOCUMENT_FRAGMENT_NODE:
        for c in tuple(node.childNodes):
            self.appendChild(c)
        return node
    if node.nodeType not in self._child_node_types:
        raise xml.dom.HierarchyRequestErr('%s cannot be child of %s' % (repr(node), repr(self)))
    elif node.nodeType in _nodeTypes_with_children:
        _clear_id_cache(self)
    if node.parentNode is not None:
        node.parentNode.removeChild(node)
    _append_child(self, node)
    node.nextSibling = None
    return node

def replaceChild(self, newChild, oldChild):
    if newChild.nodeType == self.DOCUMENT_FRAGMENT_NODE:
        refChild = oldChild.nextSibling
        self.removeChild(oldChild)
        return self.insertBefore(newChild, refChild)
    if newChild.nodeType not in self._child_node_types:
        raise xml.dom.HierarchyRequestErr('%s cannot be child of %s' % (repr(newChild), repr(self)))
    if newChild is oldChild:
        return
    if newChild.parentNode is not None:
        newChild.parentNode.removeChild(newChild)
    try:
        index = self.childNodes.index(oldChild)
    except ValueError:
        raise xml.dom.NotFoundErr()
    self.childNodes[index] = newChild
    newChild.parentNode = self
    oldChild.parentNode = None
    if newChild.nodeType in _nodeTypes_with_children or oldChild.nodeType in _nodeTypes_with_children:
        _clear_id_cache(self)
    newChild.nextSibling = oldChild.nextSibling
    newChild.previousSibling = oldChild.previousSibling
    oldChild.nextSibling = None
    oldChild.previousSibling = None
    if newChild.previousSibling:
        newChild.previousSibling.nextSibling = newChild
    if newChild.nextSibling:
        newChild.nextSibling.previousSibling = newChild
    return oldChild

def removeChild(self, oldChild):
    try:
        self.childNodes.remove(oldChild)
    except ValueError:
        raise xml.dom.NotFoundErr()
    if oldChild.nextSibling is not None:
        oldChild.nextSibling.previousSibling = oldChild.previousSibling
    if oldChild.previousSibling is not None:
        oldChild.previousSibling.nextSibling = oldChild.nextSibling
    oldChild.nextSibling = oldChild.previousSibling = None
    if oldChild.nodeType in _nodeTypes_with_children:
        _clear_id_cache(self)
    oldChild.parentNode = None
    return oldChild

def normalize(self):
    L = []
    for child in self.childNodes:
        if child.nodeType == Node.TEXT_NODE:
            if not child.data:
                if L:
                    L[-1].nextSibling = child.nextSibling
                if child.nextSibling:
                    child.nextSibling.previousSibling = child.previousSibling
                child.unlink()
            elif L and L[-1].nodeType == child.nodeType:
                node = L[-1]
                node.data = node.data + child.data
                node.nextSibling = child.nextSibling
                if child.nextSibling:
                    child.nextSibling.previousSibling = node
                child.unlink()
            else:
                L.append(child)
        else:
            L.append(child)
            if child.nodeType == Node.ELEMENT_NODE:
                child.normalize()
    self.childNodes[:] = L

def getInterface(self, feature):
    if self.isSupported(feature, None):
        return self
    else:
        return None

def getUserData(self, key):
    try:
        return self._user_data[key][0]
    except (AttributeError, KeyError):
        return None

def setUserData(self, key, data, handler):
    old = None
    try:
        d = self._user_data
    except AttributeError:
        d = {}
        self._user_data = d
    if key in d:
        old = d[key][0]
    if data is None:
        handler = None
        if old is not None:
            del d[key]
    else:
        d[key] = (data, handler)
    return old

def _call_user_data_handler(self, operation, src, dst):
    if hasattr(self, '_user_data'):
        for key, (data, handler) in list(self._user_data.items()):
            if handler is not None:
                handler.handle(operation, key, data, src, dst)

def unlink(self):
    self.parentNode = self.ownerDocument = None
    if self.childNodes:
        for child in self.childNodes:
            child.unlink()
        self.childNodes = NodeList()
    self.previousSibling = None
    self.nextSibling = None

def _get_localName(self):
    try:
        return self._localName
    except AttributeError:
        return self.nodeName.split(':', 1)[-1]

def _set_name(self, value):
    self._name = value
    if self.ownerElement is not None:
        _clear_id_cache(self.ownerElement)

def _set_value(self, value):
    self._value = value
    self.childNodes[0].data = value
    if self.ownerElement is not None:
        _clear_id_cache(self.ownerElement)
    self.childNodes[0].data = value

def _set_prefix(self, prefix):
    nsuri = self.namespaceURI
    if prefix == 'xmlns':
        if nsuri and nsuri != XMLNS_NAMESPACE:
            raise xml.dom.NamespaceErr("illegal use of 'xmlns' prefix for the wrong namespace")
    self._prefix = prefix
    if prefix is None:
        newName = self.localName
    else:
        newName = '%s:%s' % (prefix, self.localName)
    if self.ownerElement:
        _clear_id_cache(self.ownerElement)
    self.name = newName

def _get_isId(self):
    if self._is_id:
        return True
    doc = self.ownerDocument
    elem = self.ownerElement
    if doc is None or elem is None:
        return False
    info = doc._get_elem_info(elem)
    if info is None:
        return False
    if self.namespaceURI:
        return info.isIdNS(self.namespaceURI, self.localName)
    else:
        return info.isId(self.nodeName)

def _get_schemaType(self):
    doc = self.ownerDocument
    elem = self.ownerElement
    if doc is None or elem is None:
        return _no_type
    info = doc._get_elem_info(elem)
    if info is None:
        return _no_type
    if self.namespaceURI:
        return info.getAttributeTypeNS(self.namespaceURI, self.localName)
    else:
        return info.getAttributeType(self.nodeName)

def item(self, index):
    try:
        return self[list(self._attrs.keys())[index]]
    except IndexError:
        return None

def items(self):
    L = []
    for node in self._attrs.values():
        L.append((node.nodeName, node.value))
    return L

def itemsNS(self):
    L = []
    for node in self._attrs.values():
        L.append(((node.namespaceURI, node.localName), node.value))
    return L

def __contains__(self, key):
    if isinstance(key, str):
        return key in self._attrs
    else:
        return key in self._attrsNS

def _cmp(self, other):
    if self._attrs is getattr(other, '_attrs', None):
        return 0
    else:
        return (id(self) > id(other)) - (id(self) < id(other))

def __getitem__(self, attname_or_tuple):
    if isinstance(attname_or_tuple, tuple):
        return self._attrsNS[attname_or_tuple]
    else:
        return self._attrs[attname_or_tuple]

def __setitem__(self, attname, value):
    if isinstance(value, str):
        try:
            node = self._attrs[attname]
        except KeyError:
            node = Attr(attname)
            node.ownerDocument = self._ownerElement.ownerDocument
            self.setNamedItem(node)
        node.value = value
    else:
        if not isinstance(value, Attr):
            raise TypeError('value must be a string or Attr object')
        node = value
        self.setNamedItem(node)

def getNamedItem(self, name):
    try:
        return self._attrs[name]
    except KeyError:
        return None

def getNamedItemNS(self, namespaceURI, localName):
    try:
        return self._attrsNS[namespaceURI, localName]
    except KeyError:
        return None

def removeNamedItem(self, name):
    n = self.getNamedItem(name)
    if n is not None:
        _clear_id_cache(self._ownerElement)
        del self._attrs[n.nodeName]
        del self._attrsNS[n.namespaceURI, n.localName]
        if hasattr(n, 'ownerElement'):
            n.ownerElement = None
        return n
    else:
        raise xml.dom.NotFoundErr()

def removeNamedItemNS(self, namespaceURI, localName):
    n = self.getNamedItemNS(namespaceURI, localName)
    if n is not None:
        _clear_id_cache(self._ownerElement)
        del self._attrsNS[n.namespaceURI, n.localName]
        del self._attrs[n.nodeName]
        if hasattr(n, 'ownerElement'):
            n.ownerElement = None
        return n
    else:
        raise xml.dom.NotFoundErr()

def __init__(self, namespace, name):
    self.namespace = namespace
    self.name = name

def __repr__(self):
    if self.namespace:
        return '<%s %r (from %r)>' % (self.__class__.__name__, self.name, self.namespace)
    else:
        return '<%s %r>' % (self.__class__.__name__, self.name)

def _ensure_attributes(self):
    if self._attrs is None:
        self._attrs = {}
