    try:
        if '&' in text:
            text = text.replace('&', '&amp;')
        if '>' in text:
            text = text.replace('>', '&gt;')
        if '"' in text:
            text = text.replace('"', '&quot;')
        return text
    except (TypeError, AttributeError):
        _raise_serialization_error(text)

def indent(tree, space='  ', level=0):
    """Indent an XML document by inserting newlines and indentation space
    after elements.

    *tree* is the ElementTree or Element to modify.  The (root) element
    itself will not be changed, but the tail text of all elements in its
    subtree will be adapted.

    *space* is the whitespace to insert for each indentation level, two
    space characters by default.

    *level* is the initial indentation level. Setting this to a higher
    value than 0 can be used for indenting subtrees that are more deeply
    nested inside of a document."""
    if isinstance(tree, ElementTree):
        tree = tree.getroot()
    if level < 0:
        raise ValueError(f'Initial indentation level must be >= 0, got {level}')
    if not len(tree):
        return
    indentations = ['\n' + level * space]
    def _indent_children(elem, level):
        child_level = level + 1
        try:
            child_indentation = indentations[child_level]
        except IndexError:
            child_indentation = indentations[level] + space
            indentations.append(child_indentation)
        if not elem.text or not elem.text.strip():
            elem.text = child_indentation
        for child in elem:
            if len(child):
                _indent_children(child, child_level)
            if not child.tail or not child.tail.strip():
                child.tail = child_indentation
        if not child.tail.strip():
            child.tail = indentations[level]
    _indent_children(tree, 0)

def XML(text, parser=None):
    """Parse XML document from string constant.

    This function can be used to embed "XML Literals" in Python code.

    *text* is a string containing XML data, *parser* is an
    optional parser instance, defaulting to the standard XMLParser.

    Returns an Element instance."""
    if not parser:
        parser = XMLParser(target=TreeBuilder())
    parser.feed(text)
    return parser.close()

def XMLID(text, parser=None):
    """Parse XML document from string constant for its IDs.

    *text* is a string containing XML data, *parser* is an
    optional parser instance, defaulting to the standard XMLParser.

    Returns an (Element, dict) tuple, in which the
    dict maps element id:s to elements."""
    if not parser:
        parser = XMLParser(target=TreeBuilder())
    parser.feed(text)
    tree = parser.close()
    ids = {}
    for elem in tree.iter():
        id = elem.get('id')
        if id:
            ids[id] = elem
    return (tree, ids)

def fromstringlist(sequence, parser=None):
    """Parse XML document from sequence of string fragments.

    *sequence* is a list of other sequence, *parser* is an optional parser
    instance, defaulting to the standard XMLParser.

    Returns an Element instance."""
    if not parser:
        parser = XMLParser(target=TreeBuilder())
    for text in sequence:
        parser.feed(text)
    return parser.close()

def _escape_cdata_c14n(text):
    try:
        if '&' in text:
            text = text.replace('&', '&amp;')
        if '<' in text:
            text = text.replace('<', '&lt;')
        if '>' in text:
            text = text.replace('>', '&gt;')
        if '\r' in text:
            text = text.replace('\r', '&#xD;')
        return text
    except (TypeError, AttributeError):
        _raise_serialization_error(text)

def _escape_attrib_c14n(text):
    try:
        if '&' in text:
            text = text.replace('&', '&amp;')
        if '<' in text:
            text = text.replace('<', '&lt;')
        if '"' in text:
            text = text.replace('"', '&quot;')
        if '\t' in text:
            text = text.replace('\t', '&#x9;')
        if '\n' in text:
            text = text.replace('\n', '&#xA;')
        if '\r' in text:
            text = text.replace('\r', '&#xD;')
        return text
    except (TypeError, AttributeError):
        _raise_serialization_error(text)

def __init__(self, tag, attrib={}, **extra):
    if not isinstance(attrib, dict):
        raise TypeError('attrib must be dict, not %s' % (attrib.__class__.__name__,))
    self.tag = tag
    self.attrib = {**attrib, **extra}
    self._children = []

def makeelement(self, tag, attrib):
    """Create a new element with the same type.

    *tag* is a string containing the element name.
    *attrib* is a dictionary containing the element attributes.

    Do not call this method, use the SubElement factory function instead."""
    return self.__class__(tag, attrib)

def __bool__(self):
    warnings.warn("Testing an element's truth value will always return True in future versions.  Use specific 'len(elem)' or 'elem is not None' test instead.", DeprecationWarning, stacklevel=2)
    return len(self._children) != 0

def __setitem__(self, index, element):
    if isinstance(index, slice):
        for elt in element:
            self._assert_is_element(elt)
    else:
        self._assert_is_element(element)
    self._children[index] = element

def extend(self, elements):
    """Append subelements from a sequence.

    *elements* is a sequence with zero or more elements."""
    for element in elements:
        self._assert_is_element(element)
        self._children.append(element)

def _assert_is_element(self, e):
    if not isinstance(e, _Element_Py):
        raise TypeError('expected an Element, not %s' % type(e).__name__)

def find(self, path, namespaces=None):
    """Find first matching element by tag name or path.

    *path* is a string having either an element tag or an XPath,
    *namespaces* is an optional mapping from namespace prefix to full name.

    Return the first matching element, or None if no element was found."""
    return ElementPath.find(self, path, namespaces)

def iterfind(self, path, namespaces=None):
    """Find all matching subelements by tag name or path.

    *path* is a string having either an element tag or an XPath,
    *namespaces* is an optional mapping from namespace prefix to full name.

    Return an iterable yielding all matching elements in document order."""
    return ElementPath.iterfind(self, path, namespaces)

def keys(self):
    """Get list of attribute names.

    Names are returned in an arbitrary order, just like an ordinary
    Python dict.  Equivalent to attrib.keys()"""
    return self.attrib.keys()

def items(self):
    """Get element attributes as a sequence.

    The attributes are returned in arbitrary order.  Equivalent to
    attrib.items().

    Return a list of (name, value) tuples."""
    return self.attrib.items()

def itertext(self):
    """Create text iterator.

    The iterator loops over the element and all subelements in document
    order, returning all inner text."""
    tag = self.tag
    if not isinstance(tag, str) and tag is not None:
        return
    t = self.text
    if t:
        yield t
    for e in self:
        yield from e.itertext()
        t = e.tail
        if t:
            yield t

def __init__(self, text_or_uri, tag=None):
    if tag:
        text_or_uri = '{%s}%s' % (text_or_uri, tag)
    self.text = text_or_uri

def __le__(self, other):
    if isinstance(other, QName):
        return self.text <= other.text
    return self.text <= other

def __lt__(self, other):
    if isinstance(other, QName):
        return self.text < other.text
    return self.text < other

def __ge__(self, other):
    if isinstance(other, QName):
        return self.text >= other.text
    return self.text >= other

def __gt__(self, other):
    if isinstance(other, QName):
        return self.text > other.text
    return self.text > other

def __eq__(self, other):
    if isinstance(other, QName):
        return self.text == other.text
    return self.text == other

def __init__(self, element=None, file=None):
    self._root = element
    if file:
        self.parse(file)

def getroot(self):
    """Return root element of this tree."""
    return self._root

def parse(self, source, parser=None):
    """Load external XML document into element tree.

    *source* is a file name or file object, *parser* is an optional parser
    instance that defaults to XMLParser.

    ParseError is raised if the parser fails to parse the document.

    Returns the root element of the given source document."""
    close_source = False
    if not hasattr(source, 'read'):
        source = open(source, 'rb')
        close_source = True
    try:
        if parser is None:
            parser = XMLParser()
            if hasattr(parser, '_parse_whole'):
                self._root = parser._parse_whole(source)
                return self._root
        while (data := source.read(65536)):
            parser.feed(data)
        self._root = parser.close()
        return self._root
    finally:
        if close_source:
            source.close()

def iter(self, tag=None):
    """Create and return tree iterator for the root element.

    The iterator loops over all elements in this tree, in document order.

    *tag* is a string with the tag name to iterate over
    (default is to return all elements)."""
    return self._root.iter(tag)

def find(self, path, namespaces=None):
    """Find first matching element by tag name or path.

    Same as getroot().find(path), which is Element.find()

    *path* is a string having either an element tag or an XPath,
    *namespaces* is an optional mapping from namespace prefix to full name.

    Return the first matching element, or None if no element was found."""
    if path[:1] == '/':
        path = '.' + path
        warnings.warn('This search is broken in 1.3 and earlier, and will be fixed in a future version.  If you rely on the current behaviour, change it to %r' % path, FutureWarning, stacklevel=2)
    return self._root.find(path, namespaces)

def findtext(self, path, default=None, namespaces=None):
    """Find first matching element by tag name or path.

    Same as getroot().findtext(path),  which is Element.findtext()

    *path* is a string having either an element tag or an XPath,
    *namespaces* is an optional mapping from namespace prefix to full name.

    Return the first matching element, or None if no element was found."""
    if path[:1] == '/':
        path = '.' + path
        warnings.warn('This search is broken in 1.3 and earlier, and will be fixed in a future version.  If you rely on the current behaviour, change it to %r' % path, FutureWarning, stacklevel=2)
    return self._root.findtext(path, default, namespaces)

def findall(self, path, namespaces=None):
    """Find all matching subelements by tag name or path.

    Same as getroot().findall(path), which is Element.findall().

    *path* is a string having either an element tag or an XPath,
    *namespaces* is an optional mapping from namespace prefix to full name.

    Return list containing all matching elements in document order."""
    if path[:1] == '/':
        path = '.' + path
        warnings.warn('This search is broken in 1.3 and earlier, and will be fixed in a future version.  If you rely on the current behaviour, change it to %r' % path, FutureWarning, stacklevel=2)
    return self._root.findall(path, namespaces)

def iterfind(self, path, namespaces=None):
    """Find all matching subelements by tag name or path.

    Same as getroot().iterfind(path), which is element.iterfind()

    *path* is a string having either an element tag or an XPath,
    *namespaces* is an optional mapping from namespace prefix to full name.

    Return an iterable yielding all matching elements in document order."""
    if path[:1] == '/':
        path = '.' + path
        warnings.warn('This search is broken in 1.3 and earlier, and will be fixed in a future version.  If you rely on the current behaviour, change it to %r' % path, FutureWarning, stacklevel=2)
    return self._root.iterfind(path, namespaces)

def add_qname(qname):
    try:
        if qname[:1] == '{':
            uri, tag = qname[1:].rsplit('}', 1)
            prefix = namespaces.get(uri)
            if prefix is None:
                prefix = _namespace_map.get(uri)
                if prefix is None:
                    prefix = 'ns%d' % len(namespaces)
                if prefix != 'xml':
                    namespaces[uri] = prefix
            if prefix:
                qnames[qname] = '%s:%s' % (prefix, tag)
            else:
                qnames[qname] = tag
        else:
            if default_namespace:
                raise ValueError('cannot use non-qualified names with default_namespace option')
            qnames[qname] = qname
    except TypeError:
        _raise_serialization_error(qname)

def _indent_children(elem, level):
    child_level = level + 1
    try:
        child_indentation = indentations[child_level]
    except IndexError:
        child_indentation = indentations[level] + space
        indentations.append(child_indentation)
    if not elem.text or not elem.text.strip():
        elem.text = child_indentation
    for child in elem:
        if len(child):
            _indent_children(child, child_level)
        if not child.tail or not child.tail.strip():
            child.tail = child_indentation
    if not child.tail.strip():
        child.tail = indentations[level]

def iterator(source):
    try:
        while True:
            yield from pullparser.read_events()
            data = source.read(16 * 1024)
            if not data:
                break
            pullparser.feed(data)
        root = pullparser._close_and_return_root()
        yield from pullparser.read_events()
        it = wr()
        if it is not None:
            it.root = root
    finally:
        if close_source:
            source.close()

def __init__(self, events=None, *, _parser=None):
    self._events_queue = collections.deque()
    self._parser = _parser or XMLParser(target=TreeBuilder())
    if events is None:
        events = ('end',)
    self._parser._setevents(self._events_queue, events)

def feed(self, data):
    """Feed encoded data to parser."""
    if self._parser is None:
        raise ValueError('feed() called after end of stream')
    if data:
        try:
            self._parser.feed(data)
        except SyntaxError as exc:
            self._events_queue.append(exc)

def read_events(self):
    """Return an iterator over currently available (event, elem) pairs.

    Events are consumed from the internal event queue as they are
    retrieved from the iterator."""
    events = self._events_queue
    while events:
        event = events.popleft()
        if isinstance(event, Exception):
            raise event
        else:
            yield event

def flush(self):
    if self._parser is None:
        raise ValueError('flush() called after end of stream')
    self._parser.flush()

def _flush(self):
    if self._data:
        if self._last is not None:
            text = ''.join(self._data)
            if self._tail:
                assert self._last.tail is None, 'internal error (tail)'
                self._last.tail = text
            else:
                assert self._last.text is None, 'internal error (text)'
                self._last.text = text
        self._data = []

def data(self, data):
    """Add text to current element."""
    self._data.append(data)

def comment(self, text):
    """Create a comment using the comment_factory.

    *text* is the text of the comment."""
    return self._handle_single(self._comment_factory, self.insert_comments, text)

def pi(self, target, text=None):
    """Create a processing instruction using the pi_factory.

    *target* is the target name of the processing instruction.
    *text* is the data of the processing instruction, or ''."""
    return self._handle_single(self._pi_factory, self.insert_pis, target, text)

def _handle_single(self, factory, insert, *args):
    elem = factory(*args)
    if insert:
        self._flush()
        self._last = elem
        if self._elem:
            self._elem[-1].append(elem)
        self._tail = 1
    return elem

def __init__(self, *, target=None, encoding=None):
    try:
        from xml.parsers import expat
    except ImportError:
        try:
            import pyexpat as expat
        except ImportError:
            raise ImportError('No module named expat; use SimpleXMLTreeBuilder instead')
    parser = expat.ParserCreate(encoding, '}')
    if target is None:
        target = TreeBuilder()
    self.parser = self._parser = parser
    self.target = self._target = target
    self._error = expat.error
    self._names = {}
    parser.DefaultHandlerExpand = self._default
    if hasattr(target, 'start'):
        parser.StartElementHandler = self._start
    if hasattr(target, 'end'):
        parser.EndElementHandler = self._end
    if hasattr(target, 'start_ns'):
        parser.StartNamespaceDeclHandler = self._start_ns
    if hasattr(target, 'end_ns'):
        parser.EndNamespaceDeclHandler = self._end_ns
    if hasattr(target, 'data'):
        parser.CharacterDataHandler = target.data
    if hasattr(target, 'comment'):
        parser.CommentHandler = target.comment
    if hasattr(target, 'pi'):
        parser.ProcessingInstructionHandler = target.pi
    parser.buffer_text = 1
    parser.ordered_attributes = 1
    self._doctype = None
    self.entity = {}
    try:
        self.version = 'Expat %d.%d.%d' % expat.version_info
    except AttributeError:
        pass

def _setevents(self, events_queue, events_to_report):
    parser = self._parser
    append = events_queue.append
    for event_name in events_to_report:
        if event_name == 'start':
            parser.ordered_attributes = 1
            def handler(tag, attrib_in, event=event_name, append=append, start=self._start):
                append((event, start(tag, attrib_in)))
            parser.StartElementHandler = handler
        elif event_name == 'end':
            def handler(tag, event=event_name, append=append, end=self._end):
                append((event, end(tag)))
            parser.EndElementHandler = handler
        elif event_name == 'start-ns':
            if hasattr(self.target, 'start_ns'):
                def handler(prefix, uri, event=event_name, append=append, start_ns=self._start_ns):
                    append((event, start_ns(prefix, uri)))
            else:
                def handler(prefix, uri, event=event_name, append=append):
                    append((event, (prefix or '', uri or '')))
            parser.StartNamespaceDeclHandler = handler
        elif event_name == 'end-ns':
            if hasattr(self.target, 'end_ns'):
                def handler(prefix, event=event_name, append=append, end_ns=self._end_ns):
                    append((event, end_ns(prefix)))
            else:
                def handler(prefix, event=event_name, append=append):
                    append((event, None))
            parser.EndNamespaceDeclHandler = handler
        elif event_name == 'comment':
            def handler(text, event=event_name, append=append, self=self):
                append((event, self.target.comment(text)))
            parser.CommentHandler = handler
        elif event_name == 'pi':
            def handler(pi_target, data, event=event_name, append=append, self=self):
                append((event, self.target.pi(pi_target, data)))
            parser.ProcessingInstructionHandler = handler
        else:
            raise ValueError('unknown event %r' % event_name)

def _fixname(self, key):
    try:
        name = self._names[key]
    except KeyError:
        name = key
        if '}' in name:
            name = '{' + name
        self._names[key] = name
    return name

def _start(self, tag, attr_list):
    fixname = self._fixname
    tag = fixname(tag)
    attrib = {}
    if attr_list:
        for i in range(0, len(attr_list), 2):
            attrib[fixname(attr_list[i])] = attr_list[i + 1]
    return self.target.start(tag, attrib)

def feed(self, data):
    """Feed encoded data to parser."""
    try:
        self.parser.Parse(data, False)
    except self._error as v:
        self._raiseerror(v)

def close(self):
    """Finish feeding data to parser and return element structure."""
    try:
        self.parser.Parse(b'', True)
    except self._error as v:
        self._raiseerror(v)
    try:
        close_handler = self.target.close
    except AttributeError:
        pass
    else:
        return close_handler()
    finally:
        del self.parser, self._parser
        del self.target, self._target

def flush(self):
    was_enabled = self.parser.GetReparseDeferralEnabled()
    try:
        self.parser.SetReparseDeferralEnabled(False)
        self.parser.Parse(b'', False)
    except self._error as v:
        self._raiseerror(v)
    finally:
        self.parser.SetReparseDeferralEnabled(was_enabled)

def _iter_namespaces(self, ns_stack, _reversed=reversed):
    for namespaces in _reversed(ns_stack):
        if namespaces:
            yield from namespaces

def _resolve_prefix_name(self, prefixed_name):
    prefix, name = prefixed_name.split(':', 1)
    for uri, p in self._iter_namespaces(self._ns_stack):
        if p == prefix:
            return f'{{{uri}}}{name}'
    raise ValueError(f'Prefix {prefix} of QName "{prefixed_name}" is not declared in scope')

def _qname(self, qname, uri=None):
    if uri is None:
        uri, tag = qname[1:].rsplit('}', 1) if qname[:1] == '{' else ('', qname)
    else:
        tag = qname
    prefixes_seen = set()
    for u, prefix in self._iter_namespaces(self._declared_ns_stack):
        if u == uri and prefix not in prefixes_seen:
            return (f'{prefix}:{tag}' if prefix else tag, tag, uri)
        prefixes_seen.add(prefix)
    if self._rewrite_prefixes:
        if uri in self._prefix_map:
            prefix = self._prefix_map[uri]
        else:
            prefix = self._prefix_map[uri] = f'n{len(self._prefix_map)}'
        self._declared_ns_stack[-1].append((uri, prefix))
        return (f'{prefix}:{tag}', tag, uri)
    if not uri and '' not in prefixes_seen:
        return (tag, tag, uri)
    for u, prefix in self._iter_namespaces(self._ns_stack):
        if u == uri:
            self._declared_ns_stack[-1].append((uri, prefix))
            return (f'{prefix}:{tag}' if prefix else tag, tag, uri)
    if not uri:
        return (tag, tag, uri)
    raise ValueError(f'Namespace "{uri}" is not declared in scope')

def data(self, data):
    if not self._ignored_depth:
        self._data.append(data)

def _flush(self, _join_text=''.join):
    data = _join_text(self._data)
    del self._data[:]
    if self._strip_text and (not self._preserve_space[-1]):
        data = data.strip()
    if self._pending_start is not None:
        args, self._pending_start = (self._pending_start, None)
        qname_text = data if data and _looks_like_prefix_name(data) else None
        self._start(*args, qname_text)
        if qname_text is not None:
            return
    if data and self._root_seen:
        self._write(_escape_cdata_c14n(data))

def start_ns(self, prefix, uri):
    if self._ignored_depth:
        return
    if self._data:
        self._flush()
    self._ns_stack[-1].append((uri, prefix))

def start(self, tag, attrs):
    if self._exclude_tags is not None and (self._ignored_depth or tag in self._exclude_tags):
        self._ignored_depth += 1
        return
    if self._data:
        self._flush()
    new_namespaces = []
    self._declared_ns_stack.append(new_namespaces)
    if self._qname_aware_tags is not None and tag in self._qname_aware_tags:
        self._pending_start = (tag, attrs, new_namespaces)
        return
    self._start(tag, attrs, new_namespaces)

def comment(self, text):
    if not self._with_comments:
        return
    if self._ignored_depth:
        return
    if self._root_done:
        self._write('\n')
    elif self._root_seen and self._data:
        self._flush()
    self._write(f'<!--{_escape_cdata_c14n(text)}-->')
    if not self._root_seen:
        self._write('\n')

def pi(self, target, data):
    if self._ignored_depth:
        return
    if self._root_done:
        self._write('\n')
    elif self._root_seen and self._data:
        self._flush()
    self._write(f'<?{target} {_escape_cdata_c14n(data)}?>' if data else f'<?{target}?>')
    if not self._root_seen:
        self._write('\n')

def __del__(self):
    if close_source:
        source.close()

def parseString(string, handler, errorHandler=ErrorHandler()):
    import io
    if errorHandler is None:
        errorHandler = ErrorHandler()
    parser = make_parser()
    parser.setContentHandler(handler)
    parser.setErrorHandler(errorHandler)
    inpsrc = InputSource()
    if isinstance(string, str):
        inpsrc.setCharacterStream(io.StringIO(string))
    else:
        inpsrc.setByteStream(io.BytesIO(string))
    parser.parse(inpsrc)

def make_parser(parser_list=()):
    """Creates and returns a SAX parser.

    Creates the first parser it is able to instantiate of the ones
    given in the iterable created by chaining parser_list and
    default_parser_list.  The iterables must contain the names of Python
    modules containing both a SAX parser and a create_parser function."""
    for parser_name in list(parser_list) + default_parser_list:
        try:
            return _create_parser(parser_name)
        except ImportError:
            import sys
            if parser_name in sys.modules:
                raise
        except SAXReaderNotAvailable:
            pass
    raise SAXReaderNotAvailable('No parsers found', None)

def _create_parser(parser_name):
    drv_module = __import__(parser_name, {}, {}, ['create_parser'])
    return drv_module.create_parser()

def getMessage(self):
    """Return a message for this exception."""
    return self._msg

def getException(self):
    """Return the embedded exception, or None if there was none."""
    return self._exception

def getLineNumber(self):
    """The line number of the end of the text where the exception occurred."""
    return self._linenum

def getPublicId(self):
    """Get the public identifier of the entity where the exception occurred."""
    return self._locator.getPublicId()

def getSystemId(self):
    """Get the system identifier of the entity where the exception occurred."""
    return self._systemId

def __str__(self):
    """Create a string representation of the exception."""
    sysid = self.getSystemId()
    if sysid is None:
