def request(self, host, handler, request_body, verbose=False):
    for i in (0, 1):
        try:
            return self.single_request(host, handler, request_body, verbose)
        except http.client.RemoteDisconnected:
            if i:
                raise
        except OSError as e:
            if i or e.errno not in (errno.ECONNRESET, errno.ECONNABORTED, errno.EPIPE):
                raise

def single_request(self, host, handler, request_body, verbose=False):
    try:
        http_conn = self.send_request(host, handler, request_body, verbose)
        resp = http_conn.getresponse()
        if resp.status == 200:
            self.verbose = verbose
            return self.parse_response(resp)
    except Fault:
        raise
    except Exception:
        self.close()
        raise
    if resp.getheader('content-length', ''):
        resp.read()
    raise ProtocolError(host + handler, resp.status, resp.reason, dict(resp.getheaders()))

def get_host_info(self, host):
    x509 = {}
    if isinstance(host, tuple):
        host, x509 = host
    auth, host = urllib.parse._splituser(host)
    if auth:
        auth = urllib.parse.unquote_to_bytes(auth)
        auth = base64.encodebytes(auth).decode('utf-8')
        auth = ''.join(auth.split())
        extra_headers = [('Authorization', 'Basic ' + auth)]
    else:
        extra_headers = []
    return (host, extra_headers, x509)

def make_connection(self, host):
    if self._connection and host == self._connection[0]:
        return self._connection[1]
    chost, self._extra_headers, x509 = self.get_host_info(host)
    self._connection = (host, http.client.HTTPConnection(chost))
    return self._connection[1]

def close(self):
    host, connection = self._connection
    if connection:
        self._connection = (None, None)
        connection.close()

def send_headers(self, connection, headers):
    for key, val in headers:
        connection.putheader(key, val)

def send_content(self, connection, request_body):
    if self.encode_threshold is not None and self.encode_threshold < len(request_body) and gzip:
        connection.putheader('Content-Encoding', 'gzip')
        request_body = gzip_encode(request_body)
    connection.putheader('Content-Length', str(len(request_body)))
    connection.endheaders(request_body)

def parse_response(self, response):
    if hasattr(response, 'getheader'):
        if response.getheader('Content-Encoding', '') == 'gzip':
            stream = GzipDecodedResponse(response)
        else:
            stream = response
    else:
        stream = response
    p, u = self.getparser()
    while (data := stream.read(1024)):
        if self.verbose:
            print('body:', repr(data))
        p.feed(data)
    if stream is not response:
        stream.close()
    p.close()
    return u.close()

def __init__(self, use_datetime=False, use_builtin_types=False, *, headers=(), context=None):
    super().__init__(use_datetime=use_datetime, use_builtin_types=use_builtin_types, headers=headers)
    self.context = context

def make_connection(self, host):
    if self._connection and host == self._connection[0]:
        return self._connection[1]
    if not hasattr(http.client, 'HTTPSConnection'):
        raise NotImplementedError("your version of http.client doesn't support HTTPS")
    chost, self._extra_headers, x509 = self.get_host_info(host)
    self._connection = (host, http.client.HTTPSConnection(chost, None, context=self.context, **x509 or {}))
    return self._connection[1]

def __init__(self, uri, transport=None, encoding=None, verbose=False, allow_none=False, use_datetime=False, use_builtin_types=False, *, headers=(), context=None):
    p = urllib.parse.urlsplit(uri)
    if p.scheme not in ('http', 'https'):
        raise OSError('unsupported XML-RPC protocol')
    self.__host = p.netloc
    self.__handler = urllib.parse.urlunsplit(['', '', *p[2:]])
    if not self.__handler:
        self.__handler = '/RPC2'
    if transport is None:
        if p.scheme == 'https':
            handler = SafeTransport
            extra_kwargs = {'context': context}
        else:
            handler = Transport
            extra_kwargs = {}
        transport = handler(use_datetime=use_datetime, use_builtin_types=use_builtin_types, headers=headers, **extra_kwargs)
    self.__transport = transport
    self.__encoding = encoding or 'utf-8'
    self.__verbose = verbose
    self.__allow_none = allow_none

def __request(self, methodname, params):
    request = dumps(params, methodname, encoding=self.__encoding, allow_none=self.__allow_none).encode(self.__encoding, 'xmlcharrefreplace')
    response = self.__transport.request(self.__host, self.__handler, request, verbose=self.__verbose)
    if len(response) == 1:
        response = response[0]
    return response

def __call__(self, attr):
    """A workaround to get special attributes on the ServerProxy
    without interfering with the magic __getattr__"""
    if attr == 'close':
        return self.__close
    elif attr == 'transport':
        return self.__transport
    raise AttributeError('Attribute %r not found' % (attr,))

def resolve_dotted_attribute(obj, attr, allow_dotted_names=True):
    """resolve_dotted_attribute(a, 'b.c.d') => a.b.c.d

    Resolves a dotted attribute name to an object.  Raises
    an AttributeError if any attribute in the chain starts with a '_'.

    If the optional allow_dotted_names argument is false, dots are not
    supported and this function operates similar to getattr(obj, attr)."""
    if allow_dotted_names:
        attrs = attr.split('.')
    else:
        attrs = [attr]
    for i in attrs:
        if i.startswith('_'):
            raise AttributeError('attempt to access private attribute "%s"' % i)
        else:
            obj = getattr(obj, i)
    return obj

def __init__(self, allow_none=False, encoding=None, use_builtin_types=False):
    self.funcs = {}
    self.instance = None
    self.allow_none = allow_none
    self.encoding = encoding or 'utf-8'
    self.use_builtin_types = use_builtin_types

def register_function(self, function=None, name=None):
    """Registers a function to respond to XML-RPC requests.

    The optional name argument can be used to set a Unicode name
    for the function."""
    if function is None:
        return partial(self.register_function, name=name)
    if name is None:
        name = function.__name__
    self.funcs[name] = function
    return function

def _marshaled_dispatch(self, data, dispatch_method=None, path=None):
    """Dispatches an XML-RPC method from marshalled (XML) data.

    XML-RPC methods are dispatched from the marshalled (XML) data
    using the _dispatch method and the result is returned as
    marshalled data. For backwards compatibility, a dispatch
    function can be provided as an argument (see comment in
    SimpleXMLRPCRequestHandler.do_POST) but overriding the
    existing method through subclassing is the preferred means
    of changing method dispatch behavior."""
    try:
        params, method = loads(data, use_builtin_types=self.use_builtin_types)
        if dispatch_method is not None:
            response = dispatch_method(method, params)
        else:
            response = self._dispatch(method, params)
        response = (response,)
        response = dumps(response, methodresponse=1, allow_none=self.allow_none, encoding=self.encoding)
    except Fault as fault:
        response = dumps(fault, allow_none=self.allow_none, encoding=self.encoding)
    except BaseException as exc:
        response = dumps(Fault(1, '%s:%s' % (type(exc), exc)), encoding=self.encoding, allow_none=self.allow_none)
    return response.encode(self.encoding, 'xmlcharrefreplace')

def system_listMethods(self):
    """system.listMethods() => ['add', 'subtract', 'multiple']

    Returns a list of the methods supported by the server."""
    methods = set(self.funcs.keys())
    if self.instance is not None:
        if hasattr(self.instance, '_listMethods'):
            methods |= set(self.instance._listMethods())
        elif not hasattr(self.instance, '_dispatch'):
            methods |= set(list_public_methods(self.instance))
    return sorted(methods)

def system_methodHelp(self, method_name):
    """system.methodHelp('add') => "Adds two integers together"

    Returns a string containing documentation for the specified method."""
    method = None
    if method_name in self.funcs:
        method = self.funcs[method_name]
    elif self.instance is not None:
        if hasattr(self.instance, '_methodHelp'):
            return self.instance._methodHelp(method_name)
        elif not hasattr(self.instance, '_dispatch'):
            try:
                method = resolve_dotted_attribute(self.instance, method_name, self.allow_dotted_names)
            except AttributeError:
                pass
    if method is None:
        return ''
    else:
        return pydoc.getdoc(method)

def system_multicall(self, call_list):
    """system.multicall([{'methodName': 'add', 'params': [2, 2]}, ...]) => [[4], ...]

    Allows the caller to package multiple XML-RPC calls into a single
    request.

    See http://www.xmlrpc.com/discuss/msgReader$1208"""
    results = []
    for call in call_list:
        method_name = call['methodName']
        params = call['params']
        try:
            results.append([self._dispatch(method_name, params)])
        except Fault as fault:
            results.append({'faultCode': fault.faultCode, 'faultString': fault.faultString})
        except BaseException as exc:
            results.append({'faultCode': 1, 'faultString': '%s:%s' % (type(exc), exc)})
    return results

def _dispatch(self, method, params):
    """Dispatches the XML-RPC method.

    XML-RPC calls are forwarded to a registered function that
    matches the called XML-RPC method name. If no such function
    exists then the call is forwarded to the registered instance,
    if available.

    If the registered instance has a _dispatch method then that
    method will be called with the name of the XML-RPC method and
    its parameters as a tuple
    e.g. instance._dispatch('add',(2,3))

    If the registered instance does not have a _dispatch method
    then the instance will be searched to find a matching method
    and, if found, will be called.

    Methods beginning with an '_' are considered private and will
    not be called."""
    try:
        func = self.funcs[method]
    except KeyError:
        pass
    else:
        if func is not None:
            return func(*params)
        raise Exception('method "%s" is not supported' % method)
    if self.instance is not None:
        if hasattr(self.instance, '_dispatch'):
            return self.instance._dispatch(method, params)
        try:
            func = resolve_dotted_attribute(self.instance, method, self.allow_dotted_names)
        except AttributeError:
            pass
        else:
            if func is not None:
                return func(*params)
    raise Exception('method "%s" is not supported' % method)

def accept_encodings(self):
    r = {}
    ae = self.headers.get('Accept-Encoding', '')
    for e in ae.split(','):
        match = self.aepattern.match(e)
        if match:
            v = match.group(3)
            v = float(v) if v else 1.0
            r[match.group(1)] = v
    return r

def is_rpc_path_valid(self):
    if self.rpc_paths:
        return self.path in self.rpc_paths
    else:
        return True

def decode_request_content(self, data):
    encoding = self.headers.get('content-encoding', 'identity').lower()
    if encoding == 'identity':
        return data
    if encoding == 'gzip':
        try:
            return gzip_decode(data)
        except NotImplementedError:
            self.send_response(501, 'encoding %r not supported' % encoding)
        except ValueError:
            self.send_response(400, 'error decoding gzip content')
    else:
        self.send_response(501, 'encoding %r not supported' % encoding)
    self.send_header('Content-length', '0')
    self.end_headers()

def log_request(self, code='-', size='-'):
    """Selectively log an accepted request."""
    if self.server.logRequests:
        BaseHTTPRequestHandler.log_request(self, code, size)

def __init__(self, addr, requestHandler=SimpleXMLRPCRequestHandler, logRequests=True, allow_none=False, encoding=None, bind_and_activate=True, use_builtin_types=False):
    SimpleXMLRPCServer.__init__(self, addr, requestHandler, logRequests, allow_none, encoding, bind_and_activate, use_builtin_types)
    self.dispatchers = {}
    self.allow_none = allow_none
    self.encoding = encoding or 'utf-8'

def add_dispatcher(self, path, dispatcher):
    self.dispatchers[path] = dispatcher
    return dispatcher

def _marshaled_dispatch(self, data, dispatch_method=None, path=None):
    try:
        response = self.dispatchers[path]._marshaled_dispatch(data, dispatch_method, path)
    except BaseException as exc:
        response = dumps(Fault(1, '%s:%s' % (type(exc), exc)), encoding=self.encoding, allow_none=self.allow_none)
        response = response.encode(self.encoding, 'xmlcharrefreplace')
    return response

def handle_request(self, request_text=None):
    """Handle a single XML-RPC request passed through a CGI post method.

    If no XML data is given then it is read from stdin. The resulting
    XML-RPC response is printed to stdout along with the correct HTTP
    headers."""
    if request_text is None and os.environ.get('REQUEST_METHOD', None) == 'GET':
        self.handle_get()
    else:
        try:
            length = int(os.environ.get('CONTENT_LENGTH', None))
        except (ValueError, TypeError):
            length = -1
        if request_text is None:
            request_text = sys.stdin.read(length)
        self.handle_xmlrpc(request_text)

def docroutine(self, object, name, mod=None, funcs={}, classes={}, methods={}, cl=None):
    """Produce HTML documentation for a function or method object."""
    anchor = (cl and cl.__name__ or '') + '-' + name
    note = ''
    title = '<a name="%s"><strong>%s</strong></a>' % (self.escape(anchor), self.escape(name))
    if callable(object):
        argspec = str(signature(object))
    else:
        argspec = '(...)'
    if isinstance(object, tuple):
        argspec = object[0] or argspec
        docstring = object[1] or ''
    else:
        docstring = pydoc.getdoc(object)
    decl = title + argspec + (note and self.grey('<font face="helvetica, arial">%s</font>' % note))
    doc = self.markup(docstring, self.preformat, funcs, classes, methods)
    doc = doc and '<dd><tt>%s</tt></dd>' % doc
    return '<dl><dt>%s</dt>%s</dl>\n' % (decl, doc)

def set_server_title(self, server_title):
    """Set the HTML title of the generated server documentation"""
    self.server_title = server_title

def set_server_name(self, server_name):
    """Set the name of the generated HTML server documentation"""
    self.server_name = server_name

def set_server_documentation(self, server_documentation):
    """Set the documentation string for the entire server."""
    self.server_documentation = server_documentation

def generate_html_documentation(self):
    """generate_html_documentation() => html documentation for the server

    Generates HTML documentation for the server using introspection for
    installed functions and instances that do not implement the
    _dispatch method. Alternatively, instances can choose to implement
    the _get_method_argstring(method_name) method to provide the
    argument string used in the documentation and the
    _methodHelp(method_name) method to provide the help text used
    in the documentation."""
    methods = {}
    for method_name in self.system_listMethods():
        if method_name in self.funcs:
            method = self.funcs[method_name]
        elif self.instance is not None:
            method_info = [None, None]
            if hasattr(self.instance, '_get_method_argstring'):
                method_info[0] = self.instance._get_method_argstring(method_name)
            if hasattr(self.instance, '_methodHelp'):
                method_info[1] = self.instance._methodHelp(method_name)
            method_info = tuple(method_info)
            if method_info != (None, None):
                method = method_info
            elif not hasattr(self.instance, '_dispatch'):
                try:
                    method = resolve_dotted_attribute(self.instance, method_name)
                except AttributeError:
                    method = method_info
            else:
                method = method_info
        else:
            assert 0, 'Could not find method in self.functions and no instance installed'
        methods[method_name] = method
    documenter = ServerHTMLDoc()
    documentation = documenter.docserver(self.server_name, self.server_documentation, methods)
    return documenter.page(html.escape(self.server_title), documentation)

def _get_css(self, url):
