@staticmethod
def getCurrentTime():
    return datetime.datetime.now()

@contextlib.contextmanager
def _maybe_open(archive, mode):
    if isinstance(archive, (str, os.PathLike)):
        with open(archive, mode) as f:
            yield f
    else:
        yield archive

def _write_file_prefix(f, interpreter):
    """Write a shebang line."""
    if interpreter:
        shebang = b'#!' + interpreter.encode(shebang_encoding) + b'\n'
        f.write(shebang)

def get_interpreter(archive):
    with _maybe_open(archive, 'rb') as f:
        if f.read(2) == b'#!':
            return f.readline().strip().decode(shebang_encoding)

def _strip_extra(extra, xids):
    unpack = _EXTRA_FIELD_STRUCT.unpack
    modified = False
    buffer = []
    start = i = 0
    while i + 4 <= len(extra):
        xid, xlen = unpack(extra[i:i + 4])
        j = i + 4 + xlen
        if xid in xids:
            if i != start:
                buffer.append(extra[start:i])
            start = j
            modified = True
        i = j
    if not modified:
        return extra
    if start != len(extra):
        buffer.append(extra[start:])
    return b''.join(buffer)

def _check_zipfile(fp):
    try:
        if _EndRecData(fp):
            return True
    except OSError:
        pass
    return False

def is_zipfile(filename):
    """Quickly see if a file is a ZIP file by checking the magic number.

    The filename argument may be a file or file-like object too."""
    result = False
    try:
        if hasattr(filename, 'read'):
            result = _check_zipfile(fp=filename)
        else:
            with open(filename, 'rb') as fp:
                result = _check_zipfile(fp)
    except (OSError, BadZipFile):
        pass
    return result

def _gen_crc(crc):
    for j in range(8):
        if crc & 1:
            crc = crc >> 1 ^ 3988292384
        else:
            crc >>= 1
    return crc

def _check_compression(compression):
    if compression == ZIP_STORED:
        pass
    elif compression == ZIP_DEFLATED:
        if not zlib:
            raise RuntimeError('Compression requires the (missing) zlib module')
    elif compression == ZIP_BZIP2:
        if not bz2:
            raise RuntimeError('Compression requires the (missing) bz2 module')
    elif compression == ZIP_LZMA:
        if not lzma:
            raise RuntimeError('Compression requires the (missing) lzma module')
    else:
        raise NotImplementedError('That compression method is not supported')

def _get_compressor(compress_type, compresslevel=None):
    if compress_type == ZIP_DEFLATED:
        if compresslevel is not None:
            return zlib.compressobj(compresslevel, zlib.DEFLATED, -15)
        return zlib.compressobj(zlib.Z_DEFAULT_COMPRESSION, zlib.DEFLATED, -15)
    elif compress_type == ZIP_BZIP2:
        if compresslevel is not None:
            return bz2.BZ2Compressor(compresslevel)
        return bz2.BZ2Compressor()
    elif compress_type == ZIP_LZMA:
        return LZMACompressor()
    else:
        return None

def _get_decompressor(compress_type):
    _check_compression(compress_type)
    if compress_type == ZIP_STORED:
        return None
    elif compress_type == ZIP_DEFLATED:
        return zlib.decompressobj(-15)
    elif compress_type == ZIP_BZIP2:
        return bz2.BZ2Decompressor()
    elif compress_type == ZIP_LZMA:
        return LZMADecompressor()
    else:
        descr = compressor_names.get(compress_type)
        if descr:
            raise NotImplementedError('compression type %d (%s)' % (compress_type, descr))
        else:
            raise NotImplementedError('compression type %d' % (compress_type,))

def __repr__(self):
    result = ['<%s filename=%r' % (self.__class__.__name__, self.filename)]
    if self.compress_type != ZIP_STORED:
        result.append(' compress_type=%s' % compressor_names.get(self.compress_type, self.compress_type))
    hi = self.external_attr >> 16
    lo = self.external_attr & 65535
    if hi:
        result.append(' filemode=%r' % stat.filemode(hi))
    if lo:
        result.append(' external_attr=%#x' % lo)
    isdir = self.is_dir()
    if not isdir or self.file_size:
        result.append(' file_size=%r' % self.file_size)
    if (not isdir or self.compress_size) and (self.compress_type != ZIP_STORED or self.file_size != self.compress_size):
        result.append(' compress_size=%r' % self.compress_size)
    result.append('>')
    return ''.join(result)

def _encodeFilenameFlags(self):
    try:
        return (self.filename.encode('ascii'), self.flag_bits)
    except UnicodeEncodeError:
        return (self.filename.encode('utf-8'), self.flag_bits | _MASK_UTF_FILENAME)

def _decodeExtra(self, filename_crc):
    extra = self.extra
    unpack = struct.unpack
    while len(extra) >= 4:
        tp, ln = unpack('<HH', extra[:4])
        if ln + 4 > len(extra):
            raise BadZipFile('Corrupt extra field %04x (size=%d)' % (tp, ln))
        if tp == 1:
            data = extra[4:ln + 4]
            try:
                if self.file_size in (18446744073709551615, 4294967295):
                    field = 'File size'
                    self.file_size, = unpack('<Q', data[:8])
                    data = data[8:]
                if self.compress_size == 4294967295:
                    field = 'Compress size'
                    self.compress_size, = unpack('<Q', data[:8])
                    data = data[8:]
                if self.header_offset == 4294967295:
                    field = 'Header offset'
                    self.header_offset, = unpack('<Q', data[:8])
            except struct.error:
                raise BadZipFile(f'Corrupt zip64 extra field. {field} not found.') from None
        elif tp == 28789:
            data = extra[4:ln + 4]
            try:
                up_version, up_name_crc = unpack('<BL', data[:5])
                if up_version == 1 and up_name_crc == filename_crc:
                    up_unicode_name = data[5:].decode('utf-8')
                    if up_unicode_name:
                        self.filename = _sanitize_filename(up_unicode_name)
                    else:
                        import warnings
                        warnings.warn('Empty unicode path extra field (0x7075)', stacklevel=2)
            except struct.error as e:
                raise BadZipFile('Corrupt unicode path extra field (0x7075)') from e
            except UnicodeDecodeError as e:
                raise BadZipFile('Corrupt unicode path extra field (0x7075): invalid utf-8 bytes') from e
        extra = extra[ln + 4:]

@classmethod
def from_file(cls, filename, arcname=None, *, strict_timestamps=True):
    """Construct an appropriate ZipInfo for a file on the filesystem.

    filename should be the path to a file or directory on the filesystem.

    arcname is the name which it will have within the archive (by default,
    this will be the same as filename, but without a drive letter and with
    leading path separators removed)."""
    if isinstance(filename, os.PathLike):
        filename = os.fspath(filename)
    st = os.stat(filename)
    isdir = stat.S_ISDIR(st.st_mode)
    mtime = time.localtime(st.st_mtime)
    date_time = mtime[0:6]
    if not strict_timestamps and date_time[0] < 1980:
        date_time = (1980, 1, 1, 0, 0, 0)
    elif not strict_timestamps and date_time[0] > 2107:
        date_time = (2107, 12, 31, 23, 59, 59)
    if arcname is None:
        arcname = filename
    arcname = os.path.normpath(os.path.splitdrive(arcname)[1])
    while arcname[0] in (os.sep, os.altsep):
        arcname = arcname[1:]
    if isdir:
        arcname += '/'
    zinfo = cls(arcname, date_time)
    zinfo.external_attr = (st.st_mode & 65535) << 16
    if isdir:
        zinfo.file_size = 0
        zinfo.external_attr |= 16
    else:
        zinfo.file_size = st.st_size
    return zinfo

def is_dir(self):
    """Return True if this archive member is a directory."""
    if self.filename.endswith('/'):
        return True
    if os.path.altsep:
        return self.filename.endswith((os.path.sep, os.path.altsep))
    return False

def crc32(ch, crc):
    """Compute the CRC32 primitive on one byte."""
    return crc >> 8 ^ crctable[(crc ^ ch) & 255]

def decrypter(data):
    """Decrypt a bytes object."""
    result = bytearray()
    append = result.append
    for c in data:
        k = key2 | 2
        c ^= k * (k ^ 1) >> 8 & 255
        update_keys(c)
        append(c)
    return bytes(result)

def compress(self, data):
    if self._comp is None:
        return self._init() + self._comp.compress(data)
    return self._comp.compress(data)

def flush(self):
    if self._comp is None:
        return self._init() + self._comp.flush()
    return self._comp.flush()

def seek(self, offset, whence=0):
    with self._lock:
        if self._writing():
            raise ValueError("Can't reposition in the ZIP file while there is an open writing handle on it. Close the writing handle before trying to read.")
        if whence == os.SEEK_CUR:
            self._file.seek(self._pos + offset)
        else:
            self._file.seek(offset, whence)
        self._pos = self._file.tell()
        return self._pos

def close(self):
    if self._file is not None:
        fileobj = self._file
        self._file = None
        self._close(fileobj)

def __init__(self, fp):
    self.fp = fp
    self.offset = 0

def __repr__(self):
    result = ['<%s.%s' % (self.__class__.__module__, self.__class__.__qualname__)]
    if not self.closed:
        result.append(' name=%r mode=%r' % (self.name, self.mode))
        if self._compress_type != ZIP_STORED:
            result.append(' compress_type=%s' % compressor_names.get(self._compress_type, self._compress_type))
    else:
        result.append(' [closed]')
    result.append('>')
    return ''.join(result)

def readline(self, limit=-1):
    """Read and return a line from the stream.

    If limit is specified, at most limit bytes will be read."""
    if limit < 0:
        i = self._readbuffer.find(b'\n', self._offset) + 1
        if i > 0:
            line = self._readbuffer[self._offset:i]
            self._offset = i
            return line
    return io.BufferedIOBase.readline(self, limit)

def peek(self, n=1):
    """Returns buffered bytes without advancing the position."""
    if n > len(self._readbuffer) - self._offset:
        chunk = self.read(n)
        if len(chunk) > self._offset:
            self._readbuffer = chunk + self._readbuffer[self._offset:]
            self._offset = 0
        else:
            self._offset -= len(chunk)
    return self._readbuffer[self._offset:self._offset + 512]

def _update_crc(self, newdata):
    if self._expected_crc is None:
        return
    self._running_crc = crc32(newdata, self._running_crc)
    if self._eof and self._running_crc != self._expected_crc:
        raise BadZipFile('Bad CRC-32 for file %r' % self.name)

def _read1(self, n):
    if self._eof or n <= 0:
        return b''
    if self._compress_type == ZIP_DEFLATED:
        data = self._decompressor.unconsumed_tail
        if n > len(data):
            data += self._read2(n - len(data))
    else:
        data = self._read2(n)
    if self._compress_type == ZIP_STORED:
        self._eof = self._compress_left <= 0
    elif self._compress_type == ZIP_DEFLATED:
        n = max(n, self.MIN_READ_SIZE)
        data = self._decompressor.decompress(data, n)
        self._eof = self._decompressor.eof or (self._compress_left <= 0 and (not self._decompressor.unconsumed_tail))
        if self._eof:
            data += self._decompressor.flush()
    else:
        data = self._decompressor.decompress(data)
        self._eof = self._decompressor.eof or self._compress_left <= 0
    data = data[:self._left]
    self._left -= len(data)
    if self._left <= 0:
        self._eof = True
    self._update_crc(data)
    return data

def _read2(self, n):
    if self._compress_left <= 0:
        return b''
    n = max(n, self.MIN_READ_SIZE)
    n = min(n, self._compress_left)
    data = self._fileobj.read(n)
    self._compress_left -= len(data)
    if not data:
        raise EOFError
    if self._decrypter is not None:
        data = self._decrypter(data)
    return data

def close(self):
    try:
        if self._close_fileobj:
            self._fileobj.close()
    finally:
        super().close()

def tell(self):
    if self.closed:
        raise ValueError('tell on closed file.')
    if not self._seekable:
        raise io.UnsupportedOperation('underlying stream is not seekable')
    filepos = self._orig_file_size - self._left - len(self._readbuffer) + self._offset
    return filepos

@property
def _fileobj(self):
    return self._zipfile.fp

def write(self, data):
    if self.closed:
        raise ValueError('I/O operation on closed file.')
    if isinstance(data, (bytes, bytearray)):
        nbytes = len(data)
    else:
        data = memoryview(data)
        nbytes = data.nbytes
    self._file_size += nbytes
    self._crc = crc32(data, self._crc)
    if self._compressor:
        data = self._compressor.compress(data)
        self._compress_size += len(data)
    self._fileobj.write(data)
    return nbytes

def close(self):
    if self.closed:
        return
    try:
        super().close()
        if self._compressor:
            buf = self._compressor.flush()
            self._compress_size += len(buf)
            self._fileobj.write(buf)
            self._zinfo.compress_size = self._compress_size
        else:
            self._zinfo.compress_size = self._file_size
        self._zinfo.CRC = self._crc
        self._zinfo.file_size = self._file_size
        if not self._zip64:
            if self._file_size > ZIP64_LIMIT:
                raise RuntimeError('File size too large, try using force_zip64')
            if self._compress_size > ZIP64_LIMIT:
                raise RuntimeError('Compressed size too large, try using force_zip64')
        if self._zinfo.flag_bits & _MASK_USE_DATA_DESCRIPTOR:
            fmt = '<LLQQ' if self._zip64 else '<LLLL'
            self._fileobj.write(struct.pack(fmt, _DD_SIGNATURE, self._zinfo.CRC, self._zinfo.compress_size, self._zinfo.file_size))
            self._zipfile.start_dir = self._fileobj.tell()
        else:
            self._zipfile.start_dir = self._fileobj.tell()
            self._fileobj.seek(self._zinfo.header_offset)
            self._fileobj.write(self._zinfo.FileHeader(self._zip64))
            self._fileobj.seek(self._zipfile.start_dir)
        self._zipfile.filelist.append(self._zinfo)
        self._zipfile.NameToInfo[self._zinfo.filename] = self._zinfo
    finally:
        self._zipfile._writing = False

def __repr__(self):
    result = ['<%s.%s' % (self.__class__.__module__, self.__class__.__qualname__)]
    if self.fp is not None:
        if self._filePassed:
            result.append(' file=%r' % self.fp)
        elif self.filename is not None:
            result.append(' filename=%r' % self.filename)
        result.append(' mode=%r' % self.mode)
    else:
        result.append(' [closed]')
    result.append('>')
    return ''.join(result)

def namelist(self):
    """Return a list of file names in the archive."""
    return [data.filename for data in self.filelist]

def printdir(self, file=None):
    """Print a table of contents for the zip file."""
    print('%-46s %19s %12s' % ('File Name', 'Modified    ', 'Size'), file=file)
    for zinfo in self.filelist:
        date = '%d-%02d-%02d %02d:%02d:%02d' % zinfo.date_time[:6]
        print('%-46s %s %12d' % (zinfo.filename, date, zinfo.file_size), file=file)

def testzip(self):
    """Read all the files and check the CRC.

    Return None if all files could be read successfully, or the name
    of the offending file otherwise."""
    chunk_size = 2 ** 20
    for zinfo in self.filelist:
        try:
            with self.open(zinfo.filename, 'r') as f:
                while f.read(chunk_size):
                    pass
        except BadZipFile:
            return zinfo.filename

def getinfo(self, name):
    """Return the instance of ZipInfo given 'name'."""
    info = self.NameToInfo.get(name)
    if info is None:
        raise KeyError('There is no item named %r in the archive' % name)
    return info

def setpassword(self, pwd):
    """Set default password for encrypted files."""
    if pwd and (not isinstance(pwd, bytes)):
        raise TypeError('pwd: expected bytes, got %s' % type(pwd).__name__)
    if pwd:
        self.pwd = pwd
    else:
        self.pwd = None

@property
def comment(self):
    """The comment text associated with the ZIP file."""
    return self._comment

@comment.setter
def comment(self, comment):
    if not isinstance(comment, bytes):
        raise TypeError('comment: expected bytes, got %s' % type(comment).__name__)
    if len(comment) > ZIP_MAX_COMMENT:
        import warnings
        warnings.warn('Archive comment is too long; truncating to %d bytes' % ZIP_MAX_COMMENT, stacklevel=2)
        comment = comment[:ZIP_MAX_COMMENT]
    self._comment = comment
    self._didModify = True

def read(self, name, pwd=None):
    """Return file bytes for name. 'pwd' is the password to decrypt
    encrypted files."""
    with self.open(name, 'r', pwd) as fp:
        return fp.read()

def _open_to_write(self, zinfo, force_zip64=False):
    if force_zip64 and (not self._allowZip64):
        raise ValueError('force_zip64 is True, but allowZip64 was False when opening the ZIP file.')
    if self._writing:
        raise ValueError("Can't write to the ZIP file while there is another write handle open on it. Close the first handle before opening another.")
    zinfo.compress_size = 0
    zinfo.CRC = 0
    zinfo.flag_bits = 0
    if zinfo.compress_type == ZIP_LZMA:
        zinfo.flag_bits |= _MASK_COMPRESS_OPTION_1
    if not self._seekable:
        zinfo.flag_bits |= _MASK_USE_DATA_DESCRIPTOR
    if not zinfo.external_attr:
        zinfo.external_attr = 384 << 16
    zip64 = force_zip64 or zinfo.file_size * 1.05 > ZIP64_LIMIT
    if not self._allowZip64 and zip64:
        raise LargeZipFile('Filesize would require ZIP64 extensions')
    if self._seekable:
        self.fp.seek(self.start_dir)
    zinfo.header_offset = self.fp.tell()
    self._writecheck(zinfo)
    self._didModify = True
    self.fp.write(zinfo.FileHeader(zip64))
    self._writing = True
    return _ZipWriteFile(self, zinfo, zip64)

def extract(self, member, path=None, pwd=None):
    """Extract a member from the archive to the current working directory,
    using its full name. Its file information is extracted as accurately
    as possible. `member' may be a filename or a ZipInfo object. You can
    specify a different directory using `path'. You can specify the
    password to decrypt the file using 'pwd'."""
    if path is None:
        path = os.getcwd()
    else:
        path = os.fspath(path)
    return self._extract_member(member, path, pwd)

def extractall(self, path=None, members=None, pwd=None):
    """Extract all members from the archive to the current working
    directory. `path' specifies a different directory to extract to.
    `members' is optional and must be a subset of the list returned
    by namelist(). You can specify the password to decrypt all files
    using 'pwd'."""
    if members is None:
        members = self.namelist()
    if path is None:
        path = os.getcwd()
    else:
        path = os.fspath(path)
    for zipinfo in members:
        self._extract_member(zipinfo, path, pwd)

def _writecheck(self, zinfo):
    """Check for errors before writing a file to the archive."""
    if zinfo.filename in self.NameToInfo:
        import warnings
        warnings.warn('Duplicate name: %r' % zinfo.filename, stacklevel=3)
    if self.mode not in ('w', 'x', 'a'):
        raise ValueError("write() requires mode 'w', 'x', or 'a'")
    if not self.fp:
        raise ValueError('Attempt to write ZIP archive that was already closed')
    _check_compression(zinfo.compress_type)
    if not self._allowZip64:
        requires_zip64 = None
        if len(self.filelist) >= ZIP_FILECOUNT_LIMIT:
            requires_zip64 = 'Files count'
        elif zinfo.file_size > ZIP64_LIMIT:
            requires_zip64 = 'Filesize'
        elif zinfo.header_offset > ZIP64_LIMIT:
            requires_zip64 = 'Zipfile size'
        if requires_zip64:
            raise LargeZipFile(requires_zip64 + ' would require ZIP64 extensions')

def write(self, filename, arcname=None, compress_type=None, compresslevel=None):
    """Put the bytes from filename into the archive under the name
    arcname."""
    if not self.fp:
        raise ValueError('Attempt to write to ZIP archive that was already closed')
    if self._writing:
        raise ValueError("Can't write to ZIP archive while an open writing handle exists")
    zinfo = ZipInfo.from_file(filename, arcname, strict_timestamps=self._strict_timestamps)
    if zinfo.is_dir():
        zinfo.compress_size = 0
        zinfo.CRC = 0
        self.mkdir(zinfo)
    else:
        if compress_type is not None:
            zinfo.compress_type = compress_type
        else:
            zinfo.compress_type = self.compression
        if compresslevel is not None:
            zinfo._compresslevel = compresslevel
        else:
            zinfo._compresslevel = self.compresslevel
        with open(filename, 'rb') as src, self.open(zinfo, 'w') as dest:
            shutil.copyfileobj(src, dest, 1024 * 8)

def writestr(self, zinfo_or_arcname, data, compress_type=None, compresslevel=None):
    """Write a file into the archive.  The contents is 'data', which
    may be either a 'str' or a 'bytes' instance; if it is a 'str',
    it is encoded as UTF-8 first.
    'zinfo_or_arcname' is either a ZipInfo instance or
    the name of the file in the archive."""
    if isinstance(data, str):
        data = data.encode('utf-8')
    if not isinstance(zinfo_or_arcname, ZipInfo):
        zinfo = ZipInfo(filename=zinfo_or_arcname, date_time=time.localtime(time.time())[:6])
        zinfo.compress_type = self.compression
        zinfo._compresslevel = self.compresslevel
        if zinfo.filename.endswith('/'):
            zinfo.external_attr = 16893 << 16
            zinfo.external_attr |= 16
        else:
            zinfo.external_attr = 384 << 16
    else:
        zinfo = zinfo_or_arcname
    if not self.fp:
        raise ValueError('Attempt to write to ZIP archive that was already closed')
    if self._writing:
        raise ValueError("Can't write to ZIP archive while an open writing handle exists.")
    if compress_type is not None:
        zinfo.compress_type = compress_type
    if compresslevel is not None:
        zinfo._compresslevel = compresslevel
    zinfo.file_size = len(data)
    with self._lock:
        with self.open(zinfo, mode='w') as dest:
            dest.write(data)

def __del__(self):
    """Call the "close()" method in case the user forgot."""
    self.close()

def close(self):
    """Close the file, and for mode 'w', 'x' and 'a' write the ending
    records."""
    if self.fp is None:
        return
    if self._writing:
        raise ValueError("Can't close the ZIP file while there is an open writing handle on it. Close the writing handle before closing the zip.")
    try:
        if self.mode in ('w', 'x', 'a') and self._didModify:
            with self._lock:
                if self._seekable:
                    self.fp.seek(self.start_dir)
                self._write_end_record()
    finally:
        fp = self.fp
        self.fp = None
        self._fpclose(fp)

def _fpclose(self, fp):
    assert self._fileRefCnt > 0
    self._fileRefCnt -= 1
    if not self._fileRefCnt and (not self._filePassed):
        fp.close()

def __init__(self, file, mode='r', compression=ZIP_STORED, allowZip64=True, optimize=-1):
    ZipFile.__init__(self, file, mode=mode, compression=compression, allowZip64=allowZip64)
    self._optimize = optimize

def _compile(file, optimize=-1):
    import py_compile
    if self.debug:
        print('Compiling', file)
    try:
        py_compile.compile(file, doraise=True, optimize=optimize)
    except py_compile.PyCompileError as err:
        print(err.msg)
        return False
    return True

def addToZip(zf, path, zippath):
    if os.path.isfile(path):
        zf.write(path, zippath, ZIP_DEFLATED)
    elif os.path.isdir(path):
        if zippath:
            zf.write(path, zippath)
        for nm in sorted(os.listdir(path)):
            addToZip(zf, os.path.join(path, nm), os.path.join(zippath, nm))

def _difference(minuend, subtrahend):
    """Return items in minuend not in subtrahend, retaining order
    with O(1) lookup."""
    return itertools.filterfalse(set(subtrahend).__contains__, minuend)

def __setstate__(self, state):
    args, kwargs = state
    super().__init__(*args, **kwargs)

@staticmethod
def _implied_dirs(names):
    parents = itertools.chain.from_iterable(map(_parents, names))
    as_dirs = (p + posixpath.sep for p in parents)
    return _dedupe(_difference(as_dirs, names))

def getinfo(self, name):
    """Supplement getinfo for implied dirs."""
    try:
        return super().getinfo(name)
    except KeyError:
        if not name.endswith('/') or name not in self._name_set():
            raise
        return zipfile.ZipInfo(filename=name)

@classmethod
def make(cls, source):
    """Given a source (filename or zipfile), return an
    appropriate CompleteDirs subclass."""
    if isinstance(source, CompleteDirs):
        return source
    if not isinstance(source, zipfile.ZipFile):
        return cls(source)
    if 'r' not in source.mode:
        cls = CompleteDirs
    source.__class__ = cls
    return source

def __eq__(self, other):
    """>>> Path(zipfile.ZipFile(io.BytesIO(), 'w')) == 'foo'
    False"""
    if self.__class__ is not other.__class__:
        return NotImplemented
    return (self.root, self.at) == (other.root, other.at)

def open(self, mode='r', *args, pwd=None, **kwargs):
    """Open this entry as text or binary following the semantics
    of ``pathlib.Path.open()`` by passing arguments through
    to io.TextIOWrapper()."""
    if self.is_dir():
        raise IsADirectoryError(self)
    zip_mode = mode[0]
    if zip_mode == 'r' and (not self.exists()):
        raise FileNotFoundError(self)
    stream = self.root.open(self.at, zip_mode, pwd=pwd)
    if 'b' in mode:
        if args or kwargs:
            raise ValueError('encoding args invalid for binary operation')
        return stream
    encoding, args, kwargs = _extract_text_encoding(*args, **kwargs)
    return io.TextIOWrapper(stream, encoding, *args, **kwargs)

@property
def name(self):
    return self._base().name

@property
def suffix(self):
    return self._base().suffix

@property
def suffixes(self):
    return self._base().suffixes

@property
def stem(self):
    return self._base().stem

@property
def filename(self):
    return pathlib.Path(self.root.filename).joinpath(self.at)

def read_text(self, *args, **kwargs):
    encoding, args, kwargs = _extract_text_encoding(*args, **kwargs)
    with self.open('r', encoding, *args, **kwargs) as strm:
        return strm.read()

def read_bytes(self):
    with self.open('rb') as strm:
        return strm.read()

def iterdir(self):
    if not self.is_dir():
        raise ValueError("Can't listdir a file")
    subs = map(self._next, self.root.namelist())
    return filter(self._is_child, subs)

def is_symlink(self):
    """Return whether this path is a symlink. Always false (python/cpython#82102)."""
    return False

def glob(self, pattern):
    if not pattern:
        raise ValueError(f'Unacceptable pattern: {pattern!r}')
    prefix = re.escape(self.at)
    matches = re.compile(prefix + translate(pattern)).fullmatch
    return map(self._next, filter(matches, self.root.namelist()))

def joinpath(self, *other):
    next = posixpath.join(self.at, *other)
    return self._next(self.root.resolve_dir(next))

@property
def parent(self):
    if not self.at:
        return self.filename.parent
    parent_at = posixpath.dirname(self.at.rstrip('/'))
    if parent_at:
        parent_at += '/'
    return self._next(parent_at)

def replace(match):
    """Perform the replacements for a match from :func:`separate`."""
    return match.group('set') or re.escape(match.group(0)).replace('\\*\\*', '.*').replace('\\*', '[^/]*').replace('\\?', '.')

def _is_dir(self, path):
    dirpath = path + path_sep
    return dirpath in self._files

def _get_module_info(self, fullname):
    path = _get_module_path(self, fullname)
    for suffix, isbytecode, ispackage in _zip_searchorder:
        fullpath = path + suffix
        if fullpath in self._files:
            return ispackage
    return None

def _get_data(archive, toc_entry):
    datapath, compress, data_size, file_size, file_offset, time, date, crc = toc_entry
    if data_size < 0:
        raise ZipImportError('negative data size')
    with _io.open_code(archive) as fp:
        try:
            fp.seek(file_offset)
        except OSError:
            raise ZipImportError(f"can't read Zip file: {archive!r}", path=archive)
        buffer = fp.read(30)
        if len(buffer) != 30:
            raise EOFError('EOF read where not expected')
        if buffer[:4] != b'PK\x03\x04':
            raise ZipImportError(f'bad local file header: {archive!r}', path=archive)
        name_size = _unpack_uint16(buffer[26:28])
        extra_size = _unpack_uint16(buffer[28:30])
        header_size = 30 + name_size + extra_size
        file_offset += header_size
        try:
            fp.seek(file_offset)
        except OSError:
            raise ZipImportError(f"can't read Zip file: {archive!r}", path=archive)
        raw_data = fp.read(data_size)
        if len(raw_data) != data_size:
            raise OSError("zipimport: can't read data")
    if compress == 0:
        return raw_data
    try:
        decompress = _get_decompress_func()
    except Exception:
        raise ZipImportError("can't decompress data; zlib not available")
    return decompress(raw_data, -15)

def _unmarshal_code(self, pathname, fullpath, fullname, data):
    exc_details = {'name': fullname, 'path': fullpath}
    flags = _bootstrap_external._classify_pyc(data, fullname, exc_details)
    hash_based = flags & 1 != 0
    if hash_based:
        check_source = flags & 2 != 0
        if _imp.check_hash_based_pycs != 'never' and (check_source or _imp.check_hash_based_pycs == 'always'):
            source_bytes = _get_pyc_source(self, fullpath)
            if source_bytes is not None:
                source_hash = _imp.source_hash(_bootstrap_external._RAW_MAGIC_NUMBER, source_bytes)
                _bootstrap_external._validate_hash_pyc(data, source_hash, fullname, exc_details)
    else:
        source_mtime, source_size = _get_mtime_and_size_of_source(self, fullpath)
        if source_mtime:
            if not _eq_mtime(_unpack_uint32(data[8:12]), source_mtime) or _unpack_uint32(data[12:16]) != source_size:
                _bootstrap._verbose_message(f'bytecode is stale for {fullname!r}')
                return None
    code = marshal.loads(data[16:])
    if not isinstance(code, _code_type):
        raise TypeError(f'compiled module {pathname!r} is not a code object')
    return code

def _compile_source(pathname, source):
    source = _normalize_line_endings(source)
    return compile(source, pathname, 'exec', dont_inherit=True)

def _get_mtime_and_size_of_source(self, path):
    try:
        assert path[-1:] in ('c', 'o')
        path = path[:-1]
        toc_entry = self._files[path]
        time = toc_entry[5]
        date = toc_entry[6]
        uncompressed_size = toc_entry[3]
        return (_parse_dostime(date, time), uncompressed_size)
    except (KeyError, IndexError, TypeError):
        return (0, 0)

def _get_pyc_source(self, path):
    assert path[-1:] in ('c', 'o')
    path = path[:-1]
    try:
        toc_entry = self._files[path]
    except KeyError:
        return None
    else:
        return _get_data(self.archive, toc_entry)

def _get_module_code(self, fullname):
    path = _get_module_path(self, fullname)
    import_error = None
    for suffix, isbytecode, ispackage in _zip_searchorder:
        fullpath = path + suffix
        _bootstrap._verbose_message('trying {}{}{}', self.archive, path_sep, fullpath, verbosity=2)
        try:
            toc_entry = self._files[fullpath]
        except KeyError:
            pass
        else:
            modpath = toc_entry[0]
            data = _get_data(self.archive, toc_entry)
            code = None
            if isbytecode:
                try:
                    code = _unmarshal_code(self, modpath, fullpath, fullname, data)
                except ImportError as exc:
                    import_error = exc
            else:
                code = _compile_source(modpath, data)
            if code is None:
                continue
            modpath = toc_entry[0]
            return (code, ispackage, modpath)
    else:
        if import_error:
            msg = f'module load failed: {import_error}'
            raise ZipImportError(msg, name=fullname) from import_error
        else:
            raise ZipImportError(f"can't find module {fullname!r}", name=fullname)

def __init__(self, path):
    if not isinstance(path, str):
        raise TypeError(f'expected str, not {type(path)!r}')
    if not path:
        raise ZipImportError('archive path is empty', path=path)
    if alt_path_sep:
        path = path.replace(alt_path_sep, path_sep)
    prefix = []
    while True:
        try:
            st = _bootstrap_external._path_stat(path)
        except (OSError, ValueError):
            dirname, basename = _bootstrap_external._path_split(path)
            if dirname == path:
                raise ZipImportError('not a Zip file', path=path)
            path = dirname
            prefix.append(basename)
        else:
            if st.st_mode & 61440 != 32768:
                raise ZipImportError('not a Zip file', path=path)
            break
    try:
        files = _zip_directory_cache[path]
    except KeyError:
        files = _read_directory(path)
        _zip_directory_cache[path] = files
    self._files = files
    self.archive = path
    self.prefix = _bootstrap_external._path_join(*prefix[::-1])
    if self.prefix:
        self.prefix += path_sep

def find_spec(self, fullname, target=None):
    """Create a ModuleSpec for the specified module.

    Returns None if the module cannot be found."""
    module_info = _get_module_info(self, fullname)
    if module_info is not None:
        return _bootstrap.spec_from_loader(fullname, self, is_package=module_info)
    else:
        modpath = _get_module_path(self, fullname)
        if _is_dir(self, modpath):
            path = f'{self.archive}{path_sep}{modpath}'
            spec = _bootstrap.ModuleSpec(name=fullname, loader=None, is_package=True)
            spec.submodule_search_locations.append(path)
            return spec
        else:
            return None

def get_data(self, pathname):
    """get_data(pathname) -> string with file data.

    Return the data associated with 'pathname'. Raise OSError if
    the file wasn't found."""
    if alt_path_sep:
        pathname = pathname.replace(alt_path_sep, path_sep)
    key = pathname
    if pathname.startswith(self.archive + path_sep):
        key = pathname[len(self.archive + path_sep):]
    try:
        toc_entry = self._files[key]
    except KeyError:
        raise OSError(0, '', key)
    return _get_data(self.archive, toc_entry)

def get_source(self, fullname):
    """get_source(fullname) -> source string.

    Return the source code for the specified module. Raise ZipImportError
    if the module couldn't be found, return None if the archive does
    contain the module, but has no source for it."""
    mi = _get_module_info(self, fullname)
    if mi is None:
        raise ZipImportError(f"can't find module {fullname!r}", name=fullname)
    path = _get_module_path(self, fullname)
    if mi:
        fullpath = _bootstrap_external._path_join(path, '__init__.py')
    else:
        fullpath = f'{path}.py'
    try:
        toc_entry = self._files[fullpath]
    except KeyError:
        return None
    return _get_data(self.archive, toc_entry).decode()

def get_resource_reader(self, fullname):
    """Return the ResourceReader for a module in a zip file."""
    from importlib.readers import ZipReader
    return ZipReader(self, fullname)

def invalidate_caches(self):
    """Reload the file data of the archive path."""
    try:
        self._files = _read_directory(self.archive)
        _zip_directory_cache[self.archive] = self._files
    except ZipImportError:
        _zip_directory_cache.pop(self.archive, None)
        self._files = {}

def __getattr__(name):
    if name == 'TZPATH':
        return _tzpath.TZPATH
    else:
        raise AttributeError(f'module {__name__!r} has no attribute {name!r}')

def load_tzdata(key):
    from importlib import resources
    components = key.split('/')
    package_name = '.'.join(['tzdata.zoneinfo'] + components[:-1])
    resource_name = components[-1]
    try:
        return resources.files(package_name).joinpath(resource_name).open('rb')
    except (ImportError, FileNotFoundError, UnicodeEncodeError):
        raise ZoneInfoNotFoundError(f'No time zone found with key {key}')

def get_abbr(idx):
    if idx not in abbr_vals:
        span_end = abbr_chars.find(b'\x00', idx)
        abbr_vals[idx] = abbr_chars[idx:span_end].decode()
    return abbr_vals[idx]

def __init__(self, *args):
    for attr, val in zip(self.__slots__, args, strict=True):
        setattr(self, attr, val)

@classmethod
def from_file(cls, stream):
    if stream.read(4) != b'TZif':
        raise ValueError('Invalid TZif file: magic not found')
    _version = stream.read(1)
    if _version == b'\x00':
        version = 1
    else:
        version = int(_version)
    stream.read(15)
    args = (version,)
    args = args + struct.unpack('>6l', stream.read(24))
    return cls(*args)

def _reset_tzpath(to=None, stacklevel=4):
    global TZPATH
    tzpaths = to
    if tzpaths is not None:
        if isinstance(tzpaths, (str, bytes)):
            raise TypeError(f'tzpaths must be a list or tuple, ' + f'not {type(tzpaths)}: {tzpaths!r}')
        if not all(map(os.path.isabs, tzpaths)):
            raise ValueError(_get_invalid_paths_message(tzpaths))
        base_tzpath = tzpaths
    else:
        env_var = os.environ.get('PYTHONTZPATH', None)
        if env_var is None:
            env_var = sysconfig.get_config_var('TZPATH')
        base_tzpath = _parse_python_tzpath(env_var, stacklevel)
    TZPATH = tuple(base_tzpath)

def reset_tzpath(to=None):
    """Reset global TZPATH."""
    _reset_tzpath(to)

def _parse_python_tzpath(env_var, stacklevel):
    if not env_var:
        return ()
    raw_tzpath = env_var.split(os.pathsep)
    new_tzpath = tuple(filter(os.path.isabs, raw_tzpath))
    if len(new_tzpath) != len(raw_tzpath):
        import warnings
        msg = _get_invalid_paths_message(raw_tzpath)
        warnings.warn('Invalid paths specified in PYTHONTZPATH environment variable. ' + msg, InvalidTZPathWarning, stacklevel=stacklevel)
    return new_tzpath

def find_tzfile(key):
    """Retrieve the path to a TZif file from a key."""
    _validate_tzfile_path(key)
    for search_path in TZPATH:
        filepath = os.path.join(search_path, key)
        if os.path.isfile(filepath):
            return filepath
    return None

def valid_key(fpath):
    try:
        with open(fpath, 'rb') as f:
            return f.read(4) == b'TZif'
    except Exception:
        return False

@functools.lru_cache(maxsize=512)
def _load_timedelta(seconds):
    return timedelta(seconds=seconds)

def _parse_tz_str(tz_str):
    offset_str, *start_end_str = tz_str.split(',', 1)
    parser_re = re.compile('\n        (?P<std>[^<0-9:.+-]+|<[a-zA-Z0-9+-]+>)\n        (?:\n            (?P<stdoff>[+-]?\\d{1,3}(?::\\d{2}(?::\\d{2})?)?)\n            (?:\n                (?P<dst>[^0-9:.+-]+|<[a-zA-Z0-9+-]+>)\n                (?P<dstoff>[+-]?\\d{1,3}(?::\\d{2}(?::\\d{2})?)?)?\n            )? # dst\n        )? # stdoff\n        ', re.ASCII | re.VERBOSE)
    m = parser_re.fullmatch(offset_str)
    if m is None:
        raise ValueError(f'{tz_str} is not a valid TZ string')
    std_abbr = m.group('std')
    dst_abbr = m.group('dst')
    dst_offset = None
    std_abbr = std_abbr.strip('<>')
    if dst_abbr:
        dst_abbr = dst_abbr.strip('<>')
    if (std_offset := m.group('stdoff')):
        try:
            std_offset = _parse_tz_delta(std_offset)
        except ValueError as e:
            raise ValueError(f'Invalid STD offset in {tz_str}') from e
    else:
        std_offset = 0
    if dst_abbr is not None:
        if (dst_offset := m.group('dstoff')):
            try:
                dst_offset = _parse_tz_delta(dst_offset)
            except ValueError as e:
                raise ValueError(f'Invalid DST offset in {tz_str}') from e
        else:
            dst_offset = std_offset + 3600
        if not start_end_str:
            raise ValueError(f'Missing transition rules: {tz_str}')
        start_end_strs = start_end_str[0].split(',', 1)
        try:
            start, end = (_parse_dst_start_end(x) for x in start_end_strs)
        except ValueError as e:
            raise ValueError(f'Invalid TZ string: {tz_str}') from e
        return _TZStr(std_abbr, std_offset, dst_abbr, dst_offset, start, end)
    elif start_end_str:
        raise ValueError(f'Transition rule present without DST: {tz_str}')
    else:
        return _ttinfo(_load_timedelta(std_offset), _load_timedelta(0), std_abbr)

def _parse_dst_start_end(dststr):
    date, *time = dststr.split('/', 1)
    type = date[:1]
    if type == 'M':
        n_is_julian = False
        m = re.fullmatch('M(\\d{1,2})\\.(\\d).(\\d)', date, re.ASCII)
        if m is None:
            raise ValueError(f'Invalid dst start/end date: {dststr}')
        date_offset = tuple(map(int, m.groups()))
        offset = _CalendarOffset(*date_offset)
    else:
        if type == 'J':
            n_is_julian = True
            date = date[1:]
        else:
            n_is_julian = False
        doy = int(date)
        offset = _DayOffset(doy, n_is_julian)
    if time:
        offset.hour, offset.minute, offset.second = _parse_transition_time(time[0])
    return offset

def _parse_transition_time(time_str):
    match = re.fullmatch('(?P<sign>[+-])?(?P<h>\\d{1,3})(:(?P<m>\\d{2})(:(?P<s>\\d{2}))?)?', time_str, re.ASCII)
    if match is None:
        raise ValueError(f'Invalid time: {time_str}')
    h, m, s = (int(v or 0) for v in match.group('h', 'm', 's'))
    if h > 167:
        raise ValueError(f'Hour must be in [0, 167]: {time_str}')
    if match.group('sign') == '-':
        h, m, s = (-h, -m, -s)
    return (h, m, s)

def _parse_tz_delta(tz_delta):
    match = re.fullmatch('(?P<sign>[+-])?(?P<h>\\d{1,3})(:(?P<m>\\d{2})(:(?P<s>\\d{2}))?)?', tz_delta, re.ASCII)
    assert match is not None, tz_delta
    h, m, s = (int(v or 0) for v in match.group('h', 'm', 's'))
    total = h * 3600 + m * 60 + s
    if h > 24:
        raise ValueError(f'Offset hours must be in [0, 24]: {tz_delta}')
    if match.group('sign') != '-':
        total = -total
    return total

def __init_subclass__(cls):
    cls._strong_cache = collections.OrderedDict()
    cls._weak_cache = weakref.WeakValueDictionary()

@classmethod
def _new_instance(cls, key):
    obj = super().__new__(cls)
    obj._key = key
    obj._file_path = obj._find_tzfile(key)
    if obj._file_path is not None:
        file_obj = open(obj._file_path, 'rb')
    else:
        file_obj = _common.load_tzdata(key)
    with file_obj as f:
        obj._load_file(f)
    return obj

def fromutc(self, dt):
    """Convert from datetime in UTC to datetime in local time"""
    if not isinstance(dt, datetime):
        raise TypeError('fromutc() requires a datetime argument')
    if dt.tzinfo is not self:
        raise ValueError('dt.tzinfo is not self')
    timestamp = self._get_local_timestamp(dt)
    num_trans = len(self._trans_utc)
    if num_trans >= 1 and timestamp < self._trans_utc[0]:
        tti = self._tti_before
        fold = 0
    elif (num_trans == 0 or timestamp > self._trans_utc[-1]) and (not isinstance(self._tz_after, _ttinfo)):
        tti, fold = self._tz_after.get_trans_info_fromutc(timestamp, dt.year)
    elif num_trans == 0:
        tti = self._tz_after
        fold = 0
    else:
        idx = bisect.bisect_right(self._trans_utc, timestamp)
        if num_trans > 1 and timestamp >= self._trans_utc[1]:
            tti_prev, tti = self._ttinfos[idx - 2:idx]
        elif timestamp > self._trans_utc[-1]:
            tti_prev = self._ttinfos[-1]
            tti = self._tz_after
        else:
            tti_prev = self._tti_before
            tti = self._ttinfos[0]
        shift = tti_prev.utcoff - tti.utcoff
        fold = shift.total_seconds() > timestamp - self._trans_utc[idx - 1]
    dt += tti.utcoff
    if fold:
        return dt.replace(fold=1)
    else:
        return dt

def _find_trans(self, dt):
    if dt is None:
        if self._fixed_offset:
            return self._tz_after
        else:
            return _NO_TTINFO
    ts = self._get_local_timestamp(dt)
    lt = self._trans_local[dt.fold]
    num_trans = len(lt)
    if num_trans and ts < lt[0]:
        return self._tti_before
    elif not num_trans or ts > lt[-1]:
        if isinstance(self._tz_after, _TZStr):
            return self._tz_after.get_trans_info(ts, dt.year, dt.fold)
        else:
            return self._tz_after
    else:
        idx = bisect.bisect_right(lt, ts) - 1
        assert idx >= 0
        return self._ttinfos[idx]

def __str__(self):
    if self._key is not None:
        return f'{self._key}'
    else:
        return repr(self)

def __repr__(self):
    if self._key is not None:
        return f'{self.__class__.__name__}(key={self._key!r})'
    else:
        return f'{self.__class__.__name__}.from_file({self._file_repr})'

def _file_reduce(self):
    import pickle
    raise pickle.PicklingError('Cannot pickle a ZoneInfo file created from a file stream.')

@classmethod
def _unpickle(cls, key, from_cache, /):
    if from_cache:
        return cls(key)
    else:
        return cls.no_cache(key)

def _load_file(self, fobj):
    trans_idx, trans_utc, utcoff, isdst, abbr, tz_str = _common.load_data(fobj)
    dstoff = self._utcoff_to_dstoff(trans_idx, utcoff, isdst)
    trans_local = self._ts_to_local(trans_idx, trans_utc, utcoff)
    _ttinfo_list = [_ttinfo(_load_timedelta(utcoffset), _load_timedelta(dstoffset), tzname) for utcoffset, dstoffset, tzname in zip(utcoff, dstoff, abbr)]
    self._trans_utc = trans_utc
    self._trans_local = trans_local
    self._ttinfos = [_ttinfo_list[idx] for idx in trans_idx]
    for i in range(len(isdst)):
        if not isdst[i]:
            self._tti_before = _ttinfo_list[i]
            break
    else:
        if self._ttinfos:
            self._tti_before = self._ttinfos[0]
        else:
            self._tti_before = None
    if tz_str is not None and tz_str != b'':
        self._tz_after = _parse_tz_str(tz_str.decode())
    else:
        if not self._ttinfos and (not _ttinfo_list):
            raise ValueError('No time zone information found.')
        if self._ttinfos:
            self._tz_after = self._ttinfos[-1]
        else:
            self._tz_after = _ttinfo_list[-1]
    if len(_ttinfo_list) > 1 or not isinstance(self._tz_after, _ttinfo):
        self._fixed_offset = False
    elif not _ttinfo_list:
        self._fixed_offset = True
    else:
        self._fixed_offset = _ttinfo_list[0] == self._tz_after

@staticmethod
def _utcoff_to_dstoff(trans_idx, utcoffsets, isdsts):
    typecnt = len(isdsts)
    dstoffs = [0] * typecnt
    dst_cnt = sum(isdsts)
    dst_found = 0
    for i in range(1, len(trans_idx)):
        if dst_cnt == dst_found:
            break
        idx = trans_idx[i]
        dst = isdsts[idx]
        if not dst:
            continue
        if dstoffs[idx] != 0:
            continue
        dstoff = 0
        utcoff = utcoffsets[idx]
        comp_idx = trans_idx[i - 1]
        if not isdsts[comp_idx]:
            dstoff = utcoff - utcoffsets[comp_idx]
        if not dstoff and idx < typecnt - 1:
            comp_idx = trans_idx[i + 1]
            if isdsts[comp_idx]:
                continue
            dstoff = utcoff - utcoffsets[comp_idx]
        if dstoff:
            dst_found += 1
            dstoffs[idx] = dstoff
    else:
        for idx in range(typecnt):
            if not dstoffs[idx] and isdsts[idx]:
                dstoffs[idx] = 3600
    return dstoffs

@staticmethod
def _ts_to_local(trans_idx, trans_list_utc, utcoffsets):
    """Generate number of seconds since 1970 *in the local time*.

    This is necessary to easily find the transition times in local time"""
    if not trans_list_utc:
        return [[], []]
    trans_list_wall = [list(trans_list_utc), list(trans_list_utc)]
    if len(utcoffsets) > 1:
        offset_0 = utcoffsets[0]
        offset_1 = utcoffsets[trans_idx[0]]
        if offset_1 > offset_0:
            offset_1, offset_0 = (offset_0, offset_1)
    else:
        offset_0 = offset_1 = utcoffsets[0]
    trans_list_wall[0][0] += offset_0
    trans_list_wall[1][0] += offset_1
    for i in range(1, len(trans_idx)):
        offset_0 = utcoffsets[trans_idx[i - 1]]
        offset_1 = utcoffsets[trans_idx[i]]
        if offset_1 > offset_0:
            offset_1, offset_0 = (offset_0, offset_1)
        trans_list_wall[0][i] += offset_0
        trans_list_wall[1][i] += offset_1
    return trans_list_wall

def transitions(self, year):
    start = self.start.year_to_epoch(year)
    end = self.end.year_to_epoch(year)
    return (start, end)

def _get_trans_info(self, ts, year, fold):
    """Get the information about the current transition - tti"""
    start, end = self.transitions(year)
    if fold == (self.dst_diff >= 0):
        end -= self.dst_diff
    else:
        start += self.dst_diff
    if start < end:
        isdst = start <= ts < end
    else:
        isdst = not end <= ts < start
    return self.dst if isdst else self.std

def _get_trans_info_fromutc(self, ts, year):
    start, end = self.transitions(year)
    start -= self.std.utcoff.total_seconds()
    end -= self.dst.utcoff.total_seconds()
    if start < end:
        isdst = start <= ts < end
    else:
        isdst = not end <= ts < start
    if self.dst_diff > 0:
        ambig_start = end
        ambig_end = end + self.dst_diff
    else:
        ambig_start = start
        ambig_end = start - self.dst_diff
    fold = ambig_start <= ts < ambig_end
    return (self.dst if isdst else self.std, fold)

def __init__(self, m, w, d, hour=2, minute=0, second=0):
    if not 1 <= m <= 12:
        raise ValueError('m must be in [1, 12]')
    if not 1 <= w <= 5:
        raise ValueError('w must be in [1, 5]')
    if not 0 <= d <= 6:
        raise ValueError('d must be in [0, 6]')
    self.m = m
    self.w = w
    self.d = d
    self.hour = hour
    self.minute = minute
    self.second = second
